# --- SECTION 2: CORE UTILITIES AND LOGGING ---

# --- [新增] 检查 Corium 系统是否已初始化的内部函数 ---
# --- [V102 健壮性修复] 检查 Corium 系统是否已初始化的内部函数 ---
_is_system_initialized() {
    # 我们选择检查 genesis.json 文件，因为它是网络身份和历史的根源。
    # We check for the genesis.json file as it's the root of the network's identity and history.
    if [ -f "$GENESIS_CONFIG_FILE" ]; then
        return 0 # 0 表示成功（已初始化）
    else
        return 1 # 1 表示失败（未初始化）
    fi
}

# --- [兼容性修复 V2 - 动态查找] 查找并锁定 Python 解释器 ---
# --- [Compatibility Fix V2 - Dynamic Discovery] Find and lock the Python interpreter ---
_find_best_python() {
    # 优先使用 PATH 中明确的 python3.11, 3.10 等版本
    for version in 3.13 3.12 3.11; do
        if command -v "python${version}" >/dev/null 2>&1; then
            command -v "python${version}"
            return 0
        fi
    done
    # 如果都找不到，则回退到通用的 python3
    if command -v "python3" >/dev/null 2>&1; then
        command -v "python3"
        return 0
    fi
    # 如果连 python3 都没有，则返回失败
    return 1
}

# 在脚本启动时执行一次查找，并将结果存入只读变量
# Execute the discovery once at script startup and store in a readonly variable
if ! PYTHON_CMD=$(_find_best_python); then
    echo "致命错误：在您的 PATH 中找不到兼容的 Python 3 解释器。" >&2
    echo "FATAL: Could not find a compatible Python 3 interpreter in your PATH." >&2
    exit 1
fi
readonly PYTHON_CMD
# --- [修复结束] ---

# =======================================================
# --- [UX] New Logging System (Theme Engine Integrated) ---
# --- [用户体验] 新日志系统 (已集成主题引擎)          ---
# =======================================================

# Log levels: 0=Silent, 1=Errors/Warns, 2=Normal, 3=Detailed, 4=Debug
# 日志级别: 0=静默, 1=错误/警告, 2=普通, 3=详细, 4=调试

# Internal logging engine. All output goes to stderr to keep stdout clean for scripting.
# [批次二收尾] 此函数现在将所有输出委托给 _apply_theme 引擎。
#
# 内部日志引擎。所有输出都到 stderr，以保持 stdout 干净，便于脚本编程。
# [BATCH TWO FINALE] This function now delegates all output to the _apply_theme engine.
_log() {
    local level_num="$1"; local style_name="$2"; local message="$3"
    
    # 仅当全局日志级别足够高时才处理并打印消息。
    # Only process and print the message if the global log level is high enough.
    if [ "${CORIUM_LOG_LEVEL:-2}" -ge "$level_num" ]; then
        # 将消息传递给美化引擎进行最终渲染
        # Pass the message to the theming engine for final rendering
        _apply_theme "$style_name" "$message" >&2
    fi
}

# Normal, successful status messages. (Level 2)
# 普通的、成功的状态消息。(级别 2)
msg()    { _log 2 "success" "[  OK  ] $*"; }

# General informational messages. (Level 2)
# 一般的信息性消息。(级别 2)
info()   { _log 2 "info"    "[ INFO ] $*"; }

# Detailed, less important messages. (Level 3)
# 详细的、次要的消息。(级别 3)
detail() { _log 3 "debug"   "[DETAIL] $*"; } # 使用 debug 颜色, 因为它通常更低调

# Warning messages for non-fatal issues. (Level 1)
# 针对非致命问题的警告消息。(级别 1)
warn()   { _log 1 "warn"    "[ WARN ] $*"; }

# Error messages that terminate the script. (Level 1)
# 终止脚本的错误消息。(级别 1)
error()  { 
    _log 1 "error" "[ ERROR] $*"
    _log 1 "error" "[ EXIT ] Operation aborted due to a fatal error. / 因致命错误，操作已中止。"
    exit 1
}

# Debugging messages for developers. (Level 4)
# 供开发者使用的调试消息。(级别 4)
debug()  { 
    local timestamp
    timestamp=$(date +'%T.%3N')
    _log 4 "debug" "[DEBUG ${timestamp}] $*"
}


# --- [UX 优化] 为长时间操作提供旋转动画 ---
# --- [UX POLISH] Spinner for long-running operations ---
_spinner() {
    local pid=$1
    local delay=0.1
    local spinstr='|/-\'
    while kill -0 "$pid" 2>/dev/null; do
        local temp=${spinstr#?}
        printf " [%c]  " "$spinstr" >&2
        local spinstr=$temp${spinstr%"$temp"}
        sleep $delay
        printf "\r" >&2
    done
    printf "    \r" >&2
}

# =======================================================
# --- [新增] 事务性操作辅助函数 (V2 - 集中管理版)   ---
# =======================================================

# 全局变量，用于跟踪当前事务的状态
# Global variables to track the current transaction's state
declare CURRENT_TRANSACTION_BACKUP_PATH=""
declare TRANSACTION_SUCCESSFUL=0
declare CORIUM_FS_TX_DEPTH=0

# 当事务性函数返回时，此函数会被 trap 调用
# This function is called by the trap when a transactional function returns
_end_transaction() {
    # 检查全局成功标志
    if [ "$TRANSACTION_SUCCESSFUL" -eq 1 ]; then
        # 如果成功，则删除备份
        detail "事务成功提交，正在清理备份... / Transaction committed successfully, cleaning up backup..."
        if [ -n "$CURRENT_TRANSACTION_BACKUP_PATH" ] && [ -e "$CURRENT_TRANSACTION_BACKUP_PATH" ]; then
            rm -rf "$CURRENT_TRANSACTION_BACKUP_PATH"
        fi
    else
        # 如果不成功（提前退出或失败），则保留备份以供恢复
        warn "事务未成功提交。备份已保留以备恢复: ${CURRENT_TRANSACTION_BACKUP_PATH}"
        warn "Transaction was not committed successfully. Backup preserved for recovery: ${CURRENT_TRANSACTION_BACKUP_PATH}"
    fi

    # 清理全局状态并移除陷阱
    CURRENT_TRANSACTION_BACKUP_PATH=""
    TRANSACTION_SUCCESSFUL=0
    trap - RETURN
}

# Persist transaction ownership and backups before modifying installation state.
_internal_fs_transaction_context() {
    [ -n "$CORIUM_FS_TX_DIR" ] || return 1
    local tx_db tx_args=()
    for tx_db in "$BLOCKCHAIN_DB" "$FORUM_DB" "$DHT_DB"; do
        [ -z "${CORIUM_DB_TX_BACKUPS[$tx_db]:-}" ] || tx_args+=("$tx_db" "${CORIUM_DB_TX_BACKUPS[$tx_db]}")
    done
    "${PYTHON_CMD}" - "$CORIUM_FS_TX_DIR" "$1" "$BASHPID" "$CORIUM_ROOT" "$INSTALLED_DB" "$CURRENT_TRANSACTION_BACKUP_PATH" "$WORLD_FILE" "${tx_args[@]}" <<'PY_FS_CONTEXT'
import json,os,pathlib,sys
folder,phase,pid,root,installed,backup,world=sys.argv[1:8]
folder=pathlib.Path(folder)
if phase=='committed':
    previous=json.loads((folder/'context.json').read_text())
    if previous['pid']!=int(pid): raise ValueError('Filesystem transaction owner mismatch')
context={'phase':phase,'pid':int(pid),'start':pathlib.Path('/proc/'+pid+'/stat').read_text().rsplit(')',1)[1].split()[19],
         'boot':pathlib.Path('/proc/sys/kernel/random/boot_id').read_text().strip(),
         'root':str(pathlib.Path(root).resolve()),'installed':installed,'installed_backup':backup,'world':world,
         'databases':list(zip(sys.argv[8::2],sys.argv[9::2]))}
# Original backups must reach storage before callers overwrite their counterparts.
paths=[folder,pathlib.Path(backup)] if phase=='prepared' else [pathlib.Path(installed)]
files=[pathlib.Path(world)]+[pathlib.Path(p) for pair in context['databases'] for p in pair]
if phase=='committed' and (folder/'journal.json').exists():
    files += [pathlib.Path(context['root'])/name for name in json.loads((folder/'journal.json').read_text())]
for tree in paths:
    if tree.exists():
        for parent,dirs,names in os.walk(tree):
            files += [pathlib.Path(parent)/name for name in names]
            files.append(pathlib.Path(parent))
for path in files:
    if path.exists() and not path.is_symlink():
        fd=os.open(path,os.O_RDONLY)
        try: os.fsync(fd)
        finally: os.close(fd)
        fd=os.open(path.parent,os.O_RDONLY)
        try: os.fsync(fd)
        finally: os.close(fd)
next_file=folder/'context.next'
with next_file.open('w') as stream:
    json.dump(context,stream); stream.flush(); os.fsync(stream.fileno())
os.replace(next_file,folder/'context.json')
fd=os.open(folder,os.O_RDONLY)
try: os.fsync(fd)
finally: os.close(fd)
PY_FS_CONTEXT
}

# On a cold restart, restore only abandoned journals; live transactions retain ownership.
_internal_recover_abandoned_transactions() {
    [ -d "$LOCK_DIR" ] || return 0
    local journals=()
    while IFS= read -r -d '' journal; do journals+=("$journal"); done < <(find "$LOCK_DIR" -maxdepth 2 -name context.json -path '*/filesystem-tx.*/*' -print0)
    [ ${#journals[@]} -gt 0 ] || return 0
    "${PYTHON_CMD}" - "$CORIUM_ROOT" "$LOCK_DIR" "${journals[@]}" <<'PY_FS_RECOVER'
import fcntl,json,os,pathlib,shutil,sqlite3,sys
root=pathlib.Path(sys.argv[1]).resolve(); lockdir=pathlib.Path(sys.argv[2])
boot=pathlib.Path('/proc/sys/kernel/random/boot_id').read_text().strip()
def inside(value):
    path=pathlib.Path(value)
    if not path.is_absolute() or not path.resolve().is_relative_to(root): raise ValueError('Invalid transaction recovery path')
    return path
with (lockdir/'recovery.lock').open('a') as lock:
    fcntl.flock(lock,fcntl.LOCK_EX)
    for filename in sys.argv[3:]:
        journal=pathlib.Path(filename)
        if not journal.exists(): continue
        data=json.loads(journal.read_text()); folder=inside(str(journal.parent))
        if data['root']!=str(root): raise ValueError('Transaction recovery root mismatch')
        stat=pathlib.Path('/proc/'+str(data['pid'])+'/stat')
        try:
            if data['boot']==boot and stat.read_text().rsplit(')',1)[1].split()[19]==data['start']: continue
        except FileNotFoundError: pass
        installed=inside(data['installed']); backup=inside(data['installed_backup']); world=inside(data['world'])
        databases=[(inside(path),inside(saved)) for path,saved in data['databases']]
        if data['phase']!='committed':
            entries=json.loads((folder/'journal.json').read_text()) if (folder/'journal.json').exists() else {}
            for name,item in sorted(entries.items(),key=lambda x:-len(pathlib.PurePosixPath(x[0]).parts)):
                relative=pathlib.PurePosixPath(name)
                if relative.is_absolute() or '..' in relative.parts: raise ValueError('Invalid recovery manifest')
                target=root/relative
                for parent in target.parents:
                    if parent==root: break
                    if parent.is_symlink(): raise ValueError('Symlink in recovery parent')
                if item.get('directory'): continue
                if os.path.lexists(target):
                    if target.is_dir() and not target.is_symlink(): target.rmdir()
                    else: target.unlink()
                if item['exists']:
                    target.parent.mkdir(parents=True,exist_ok=True)
                    if 'link' in item: target.symlink_to(item['link'])
                    else: shutil.copy2(inside(str(folder/item['backup'])),target)
            shutil.copy2(folder/'world',world)
            if installed.exists(): shutil.rmtree(installed)
            # Keep the original backup until all databases have been restored.
            shutil.copytree(backup,installed)
            for path,saved in databases:
                if saved.stat().st_size:
                    source=sqlite3.connect(saved.resolve().as_uri()+'?mode=ro',uri=True)
                    destination=sqlite3.connect(path)
                    try: source.backup(destination)
                    finally: source.close(); destination.close()
                else:
                    for suffix in ('','-wal','-shm'): pathlib.Path(str(path)+suffix).unlink(missing_ok=True)
            print('Recovered abandoned Corium transaction: '+str(folder),file=sys.stderr)
        for path,saved in databases: saved.unlink(missing_ok=True)
        if backup.exists(): shutil.rmtree(backup)
        shutil.rmtree(folder)
PY_FS_RECOVER
}

# 开始一个事务
# Begins a transaction
_begin_transaction() {
    local source_dir="$1"
    
    # 防止嵌套事务
    if [ -n "$CURRENT_TRANSACTION_BACKUP_PATH" ]; then
        [ "$source_dir" = "$INSTALLED_DB" ] || return 1
        ((CORIUM_FS_TX_DEPTH+=1))
        return 0
    fi

    info "正在为此操作创建事务性备份... / Creating transactional backup for this operation..."
    mkdir -p "$source_dir"
    local backup_dir
    backup_dir=$(mktemp -d "${source_dir}.bak.XXXXXX") || return 1
    
    cp -a "$source_dir/." "$backup_dir/" || { rm -rf -- "$backup_dir"; return 1; }
    CURRENT_TRANSACTION_BACKUP_PATH="$backup_dir"
    CORIUM_FS_TX_DIR=$(mktemp -d "${LOCK_DIR}/filesystem-tx.XXXXXX") || return 1
    export WORLD_FILE
    cp -a "$WORLD_FILE" "$CORIUM_FS_TX_DIR/world" || return 1
    for tx_db in "$BLOCKCHAIN_DB" "$FORUM_DB" "$DHT_DB"; do
        [ ! -f "$tx_db" ] || db_begin_transaction "$tx_db" || return 1
    done
    
    # 设置全局状态
    CURRENT_TRANSACTION_BACKUP_PATH="$backup_dir"
    CORIUM_FS_TX_DEPTH=1
    TRANSACTION_SUCCESSFUL=0
    _internal_fs_transaction_context prepared || return 1

    # Do not install a RETURN trap here: RETURN fires when _begin_transaction
    # itself returns, which would end the transaction immediately. Failed callers
    # deliberately leave the backup in place for recovery; successful callers
    # finalize explicitly via _commit_transaction.
}

# Mark and finalize a successful filesystem transaction.
_commit_transaction() {
    if [ "$CORIUM_FS_TX_DEPTH" -gt 1 ]; then ((CORIUM_FS_TX_DEPTH-=1)); return 0; fi
    _internal_fs_transaction_context committed || return 1
    db_commit_transaction "$BLOCKCHAIN_DB" "$FORUM_DB" "$DHT_DB"
    [ -z "$CORIUM_FS_TX_DIR" ] || rm -rf -- "$CORIUM_FS_TX_DIR"
    CORIUM_FS_TX_DIR=""
    CORIUM_FS_TX_DEPTH=0
    TRANSACTION_SUCCESSFUL=1
    _end_transaction
}

# --- [V86 事务强化] 开始一个或多个数据库的事务 (支持嵌套) ---
# --- [V86 TX Hardening] Begins a transaction on one or more databases (supports nesting) ---
# Journal originals before file mutation; never follow an existing parent symlink.
# 修改文件前记录原件，不允许沿父目录符号链接写出安装根目录。
_transaction_stage_files() {
    [ -n "$CORIUM_FS_TX_DIR" ] || return 1
    "${PYTHON_CMD}" - "$CORIUM_ROOT" "$CORIUM_FS_TX_DIR" "$1" <<'PY_FS_STAGE'
import os, sys, json, pathlib, shutil, stat
root = pathlib.Path(sys.argv[1]).resolve()
tx = pathlib.Path(sys.argv[2]); journal = tx / 'journal.json'
entries = json.loads(journal.read_text()) if journal.exists() else {}
for name in pathlib.Path(sys.argv[3]).read_text().splitlines():
    path = pathlib.PurePosixPath(name)
    if not name or path.is_absolute() or '..' in path.parts or '\x00' in name:
        raise ValueError('Invalid file manifest path')
    target = root / path
    for parent in target.parents:
        if parent == root: break
        if parent.is_symlink(): raise ValueError('Symlink parent in installation path')
    for item in [target] + list(target.parents)[:len(path.parts)-1]:
        relative = str(item.relative_to(root))
        if relative in entries: continue
        exists = os.path.lexists(item)
        record = {'exists': exists}
        if exists:
            mode = item.lstat().st_mode
            if stat.S_ISLNK(mode): record['link'] = os.readlink(item)
            elif stat.S_ISREG(mode):
                backup = str(len(entries)) + '.original'
                shutil.copy2(item, tx / backup); record['backup'] = backup
            elif stat.S_ISDIR(mode): record['directory'] = True
            else: raise ValueError('Unsupported existing filesystem object')
        entries[relative] = record
    tmp = tx / 'journal.next'
    with tmp.open('w') as f:
        json.dump(entries, f, ensure_ascii=False); f.flush(); os.fsync(f.fileno())
    os.replace(tmp, journal)
    for original in tx.glob('*.original'):
        with original.open('rb') as stream: os.fsync(stream.fileno())
    fd=os.open(tx,os.O_RDONLY)
    try: os.fsync(fd)
    finally: os.close(fd)
PY_FS_STAGE
}

_rollback_filesystem_transaction() {
    [ -n "${CURRENT_TRANSACTION_BACKUP_PATH:-}" ] || return 0
    if [ -n "$CORIUM_FS_TX_DIR" ]; then
        "${PYTHON_CMD}" - "$CORIUM_ROOT" "$CORIUM_FS_TX_DIR" <<'PY_FS_ROLLBACK'
import os, sys, json, pathlib, shutil
root = pathlib.Path(sys.argv[1]).resolve(); tx = pathlib.Path(sys.argv[2])
journal = tx / 'journal.json'
entries = json.loads(journal.read_text()) if journal.exists() else {}
for name, record in sorted(entries.items(), key=lambda x: (-len(pathlib.PurePosixPath(x[0]).parts), x[0])):
    target = root / name
    if record.get('directory'): continue
    if os.path.lexists(target):
        if target.is_dir() and not target.is_symlink(): target.rmdir()
        else: target.unlink()
    if record['exists']:
        target.parent.mkdir(parents=True, exist_ok=True)
        if 'link' in record: target.symlink_to(record['link'])
        else: shutil.copy2(tx / record['backup'], target)
shutil.copy2(tx / 'world', os.environ['WORLD_FILE'])
PY_FS_ROLLBACK
        local rollback_rc=$?
        [ "$rollback_rc" -eq 0 ] || { warn "文件回滚失败，保留日志。/ File rollback failed; journal retained: $CORIUM_FS_TX_DIR"; return "$rollback_rc"; }
    fi
    rm -rf -- "$INSTALLED_DB"
    mv -- "$CURRENT_TRANSACTION_BACKUP_PATH" "$INSTALLED_DB" || return 1
    CURRENT_TRANSACTION_BACKUP_PATH=""
    [ -z "$CORIUM_FS_TX_DIR" ] || rm -rf -- "$CORIUM_FS_TX_DIR"
    CORIUM_FS_TX_DIR=""
    CORIUM_FS_TX_DEPTH=0
}

# Validate archive paths and links before extraction, including backup archives.
# 解压前校验归档路径及链接，适用于软件包和备份。
_validate_archive() {
    "${PYTHON_CMD}" - "$1" <<'PY_ARCHIVE'
import sys, tarfile, pathlib, subprocess
path = sys.argv[1]
process = subprocess.Popen(['zstd', '-dc', '--', path], stdout=subprocess.PIPE) if path.endswith('.zst') else None
try:
    with tarfile.open(fileobj=process.stdout, mode='r|') if process else tarfile.open(path, 'r:*') as archive:
        names = {}; links = set()
        for member in archive:
            name = pathlib.PurePosixPath(member.name)
            if name.is_absolute() or '..' in name.parts or '\n' in member.name or '\r' in member.name:
                raise ValueError('Unsafe archive member path')
            key = str(name)
            if key in ('.', ''): continue
            if key in names: raise ValueError('Duplicate archive member')
            if not (member.isfile() or member.isdir() or member.issym() or member.islnk()):
                raise ValueError('Special archive member is forbidden')
            if member.islnk():
                target = pathlib.PurePosixPath(member.linkname)
                if target.is_absolute() or '..' in target.parts: raise ValueError('Unsafe hardlink')
            if member.issym(): links.add(key)
            names[key] = member
        for name, member in names.items():
            if any(str(p) in links for p in pathlib.PurePosixPath(name).parents):
                raise ValueError('Archive writes through symlink')
            if member.islnk() and member.linkname in links: raise ValueError('Hardlink to symlink')
finally:
    if process:
        process.stdout.close()
        if process.wait() != 0: raise ValueError('Archive decompression failed')
PY_ARCHIVE
}

