# @param $1 - 路径 (Path to check)
# @param $2 - 预估需要的空间 (MB) (Estimated space needed in MB)
_check_disk_space() {
    local path_to_check="$1"
    local space_needed_mb="$2"
    
    # 获取可用空间 (MB)
    local available_space_mb
    available_space_mb=$(df -BM --output=avail "$path_to_check" | tail -n 1 | tr -d 'M')
    
    if [ "$available_space_mb" -lt "$space_needed_mb" ]; then
        error "磁盘空间不足。路径 '${path_to_check}' 需要 ${space_needed_mb}MB，但仅有 ${available_space_mb}MB 可用。"
        error "Insufficient disk space. Path '${path_to_check}' requires ${space_needed_mb}MB, but only ${available_space_mb}MB is available."
        exit 1
    fi
}


# ==============================================================================
# --- Helper function to wait for multiple PIDs with a timeout (V2 - Robust) ---
# --- 带超时的、等待多个PID的辅助函数 (V2 - 健壮版)                        ---
# ==============================================================================
# This function waits for multiple background processes (given their PIDs) to
# complete. It implements a per-process timeout. If any process runs longer
# than the specified timeout, it will be terminated.
#
# 此函数等待多个后台进程 (通过其PID指定) 完成。它为每个进程实现了独立的超时
# 机制。如果任何进程的运行时间超过了指定的超时，它将被终止。
#
# @param $1 - timeout (The timeout duration in seconds / 超时时长，单位为秒)
# @param $@ - PIDs (The list of process IDs to wait for / 要等待的进程ID列表)
# @return Returns 0 if all processes completed successfully within the timeout.
#         Returns 1 if any process failed, was killed due to timeout, or
#         if an error occurred.
# @返回 如果所有进程都在超时内成功完成，则返回 0。
#       如果任何进程失败、因超时被杀死、或发生错误，则返回 1。
wait_all() {
    local timeout="$1"
    shift
    local pids=("$@")
    local failed=0 pid monitor_status wait_status

    # A subshell cannot `wait` for a process that is a child of its parent shell.
    # Monitor each PID externally, but perform the actual wait in this shell.
    for pid in "${pids[@]}"; do
        if ! kill -0 "$pid" 2>/dev/null; then
            if ! wait "$pid" 2>/dev/null; then failed=1; fi
            continue
        fi

        if timeout "${timeout}s" tail --pid="$pid" -f /dev/null >/dev/null 2>&1; then
            monitor_status=0
        else
            monitor_status=$?
        fi
        if [ "$monitor_status" -eq 124 ]; then
            kill "$pid" 2>/dev/null || true
            sleep 0.1
            kill -KILL "$pid" 2>/dev/null || true
            failed=1
        elif [ "$monitor_status" -ne 0 ]; then
            # Fallback for platforms whose tail lacks --pid: poll in the parent.
            local started now
            started=$(date +%s)
            while kill -0 "$pid" 2>/dev/null; do
                now=$(date +%s)
                if [ $((now - started)) -ge "$timeout" ]; then
                    kill "$pid" 2>/dev/null || true
                    failed=1
                    break
                fi
                sleep 0.1
            done
        fi

        if wait "$pid" 2>/dev/null; then
            wait_status=0
        else
            wait_status=$?
        fi
        [ "$wait_status" -eq 0 ] || failed=1
    done
    return "$failed"
}
# NEW HELPER FUNCTION: Securely encode a string into a hex literal for SQL queries.
# This prevents SQL injection by representing the data in a format with no special SQL characters.
# 新增辅助函数: 安全地将字符串编码为用于SQL查询的十六进制字面量。
# 通过将数据表示为没有特殊SQL字符的格式来防止SQL注入。

# MAYBE BUGGY, NO USE
# 可能有Bug，请勿使用
_sql_safe_string_to_hex() {
    echo -n "$1" | xxd -p | tr -d '\n'
}

_sql_safe_string_to_literal() {
    # This function safely escapes a string for use in an SQL literal
    # by doubling any single quotes within it, and then wrapping the
    # whole string in single quotes.
    # e.g., "it's a string" -> "'it''s a string'"
    echo "'${1//\'/\'\'}'"
}

progress() {
    local percent=$1
    local width=50
    local completed=$((width * percent / 100))
    local remaining=$((width - completed))
    printf "\r[%-${width}s] %d%%" "$(printf '#%.0s' $(seq 1 $completed))" "$percent"
}

check_dep() {
    command -v "$1" >/dev/null 2>&1 || error "Missing dependency: '$1' is required but not installed."
}

# --- [NEW] Function to check for Python library dependencies ---
# --- [新增] 用于检查 Python 库依赖的函数 ---
# It works by attempting to import the library using the python3 interpreter.
# If the import succeeds, the command exits with 0. If it fails (ImportError),
# it exits with a non-zero status, which is caught by the '||' operator.
#
# 它的工作原理是尝试使用 python3 解释器导入指定的库。如果导入成功，
# 命令以状态码 0 退出。如果失败 (ImportError)，则以非零状态码退出，
# 这会被 '||' 操作符捕获。
# --- [V102 最终修复] 用于检查 Python 库依赖的函数 (支持包名与模块名不一致的情况) ---
check_py_dep() {
    local pkg_name="$1" # 我们接收的参数是“包名”
    
    # 如果没有传递参数，则直接返回，避免 unbound variable 错误
    if [ -z "$pkg_name" ]; then
        return
    fi
    
    local module_name_to_import="$pkg_name" # 默认情况下，要导入的模块名和包名一样

    # 在这里处理那些“名字不一样”的特例
    case "$pkg_name" in
        pystun3)
            module_name_to_import="stun"
            ;;
    esac

    # 使用我们之前确定的 PYTHON_CMD 变量来执行检查
    # 如果导入失败，则报错并退出
    ${PYTHON_CMD} -c "import ${module_name_to_import}" >/dev/null 2>&1 || error "Missing Python library: '${pkg_name}' is required. Please run: 'python3 -m pip install ${pkg_name}'"
}


# [修改] 集中式权限检查函数，替代 check-root
# [MODIFICATION] Centralized permission check function, replacing check-root
check_permissions() {
    local command="$1"
    local -a dirs_to_check=()
    local write_needed=1

    # 根据命令名，决定需要检查哪些目录的写权限
    case "$command" in
        # --- 需要写权限的核心命令 ---
        init)
            # init需要创建整个目录结构，因此检查根目录
            # 注意：这里假设/etc, /var, /usr的父目录是可访问的
            dirs_to_check+=("${CORIUM_ROOT%/}/etc" "${CORIUM_ROOT%/}/var" "${CORIUM_ROOT%/}/usr" "${CORIUM_ROOT%/}/tmp")
            ;;
        install|remove|upgrade|build|rebuild|autoremove|clean|adopt|rollback|key|strata|manage)
            # 这些命令需要修改数据库、缓存、锁文件或安装文件
            dirs_to_check+=("$VAR_LIB_CORIUM_DIR" "$VAR_CACHE_CORIUM_DIR" "$LOCK_DIR" "$ETC_CORIUM_DIR")
            ;;
        sync)
            # sync主要修改仓库和元数据缓存
            dirs_to_check+=("$REPOS_DIR" "$METADATA_CACHE_DIR" "$LOCK_DIR" "$VAR_CACHE_CORIUM_DIR")
            ;;
        forum)
            # 论坛的写操作
            dirs_to_check+=("$FORUM_DIR" "$LOCK_DIR")
            ;;

        # --- 只读命令，完全不需要写权限 ---
        search|info|owns|gen-build|help)
            write_needed=0
            ;;

        # 默认情况，作为安全保障
        *)
            warn "未知命令 '$command' 的权限需求，将执行默认检查。 (Unknown permission requirements for command '$command', performing default checks.)"
            dirs_to_check+=("$VAR_LIB_CORIUM_DIR" "$VAR_CACHE_CORIUM_DIR" "$LOCK_DIR")
            ;;
    esac

    # 如果命令不需要写权限，则直接成功返回
    [ "$write_needed" -eq 0 ] && return 0
    
    # --- 执行实际的写权限检查 ---
    local missing_perms=0
    # 确保基础目录存在，否则检查会失败
    for dir in "${dirs_to_check[@]}"; do
        mkdir -p "$dir" 2>/dev/null
    done

    for dir in "${dirs_to_check[@]}"; do
        if [ ! -w "$dir" ]; then
             warn "没有对 '${dir}' 的写权限。 (No write permission for '${dir}'.)"
             missing_perms=1
        fi
    done

    if [ "$missing_perms" -eq 1 ]; then
        error "命令 '$command' 权限不足。请使用 'sudo'，或通过设置 CORIUM_ROOT 在您有权限的目录下运行。"
        error "Insufficient permissions for command '$command'. Please use 'sudo' or run in a directory you own by setting CORIUM_ROOT."
    fi
}

# [新增] 为必须使用root权限的底层命令（如 chroot）保留此函数
# [NEW] This function is kept for low-level commands that require root (e.g., chroot).
_internal_check_root_privileges() {
    [ "$(id -u)" -eq 0 ] || error "此特定操作需要真正的 root 权限。 (This specific operation requires true root privileges.)"
}

# --- [架构变更] 用于跟踪动态锁文件描述符的全局关联数组 ---
# --- [ARCHITECTURAL CHANGE] Global associative array to track dynamic lock file descriptors ---
declare -A LOCK_DEPTH=() LOCK_OWNERS=()
declare -A LOCK_FDS

# Acquires a specific type of lock for the current process.
# 为当前进程获取一个特定类型的锁。
#
# @param $1 - type (The type of lock to acquire: "system" or "network" / 要获取的锁类型: "system" 或 "network")
# @param $2 - mode (Optional: "block" for blocking, empty for non-blocking / 可选: "block" 为阻塞模式，空为非阻塞)
acquire_lock() {
    local type="$1"
    local mode="${2:-non-block}" # 默认为非阻塞行为 / Default to non-blocking behavior
    
    # --- [修复] 锁重入检查 ---
    # 如果我们已经持有这个锁，就什么都不做，直接成功返回
    if [ -n "${LOCK_FDS[$type]+_}" ]; then
        return 0
    fi
    # --- [修复结束] ---

    local lock_file_path=""
    case "$type" in
        system)  lock_file_path="$SYSTEM_LOCK_FILE" ;;
        network) lock_file_path="$NETWORK_LOCK_FILE" ;;
        *)       error "无效的锁类型 / Invalid lock type: '$type'" ;;
    esac

    # 如果当前脚本实例尚未持有此类型的锁，则动态分配并存储文件描述符
    # Dynamically allocate and store file descriptor if not already held by this script instance
    if [ -z "${LOCK_FDS[$type]+_}" ]; then
        local fd
        # 此语法将一个可用的文件描述符动态分配给变量 fd
        # This syntax dynamically assigns an available file descriptor to the variable 'fd'
        if ! exec {fd}>"$lock_file_path"; then
            error "无法打开锁文件 / Could not open lock file: $lock_file_path"
        fi
        LOCK_FDS["$type"]=$fd
        LOCK_DEPTH["$type"]=$((${#FUNCNAME[@]} - 1))
        LOCK_OWNERS["$type"]=$BASHPID
    fi

    local fd=${LOCK_FDS[$type]}
    if [ "$mode" = "block" ]; then
        # 阻塞模式：等待直到可以获取锁
        # Blocking mode: waits until the lock can be acquired
        if ! flock -x "$fd"; then
             # 这通常不应发生，除非有权限问题
             # This should not typically happen unless there are permission issues
             error "无法获取阻塞的 '${type}' 锁。 / Could not acquire blocking '${type}' lock."
        fi
    else
        # 非阻塞模式：如果无法立即获取，则失败
        # Non-blocking mode: fails immediately if it cannot be acquired
        if ! flock -n "$fd"; then
            error "另一个 Corium 实例正在使用 '${type}' 锁。请稍候。/ Another Corium instance is using the '${type}' lock. Please wait."
        fi
    fi
}

# Releases a specific type of lock held by the current process.
# 释放当前进程持有的一个特定类型的锁。
#
# @param $1 - type (The type of lock to release: "system" or "network" / 要释放的锁类型: "system" 或 "network")
release_lock() {
    local type="${1:-}" force="${2:-}" fd
    if [ -z "$type" ]; then
        for type in "${!LOCK_FDS[@]}"; do release_lock "$type"; done
        return 0
    fi
    [ -n "${LOCK_FDS[$type]+_}" ] || return 0
    [ "${LOCK_OWNERS[$type]:-$BASHPID}" = "$BASHPID" ] || return 0
    # Nested functions and command substitutions borrow the caller's lock.
    # 嵌套调用只能借用外层锁，不能提前释放它。
    if [ "$force" != force ] && [ "$((${#FUNCNAME[@]} - 1))" -gt "${LOCK_DEPTH[$type]:-0}" ]; then return 0; fi
    fd=${LOCK_FDS[$type]}
    flock -u "$fd" || return 1
    exec {fd}>&-
    unset 'LOCK_FDS[$type]' 'LOCK_DEPTH[$type]' 'LOCK_OWNERS[$type]'
}

# =======================================================
# --- [修复后 V2] cleanup (整合 PID 文件逻辑)         ---
# --- [FIXED V2] cleanup (Integrates PID file logic)---
# =======================================================
# Global cleanup function, triggered on script exit.
# 全局清理函数，在脚本退出时触发。
cleanup() {
    # --- [重构] 释放所有当前进程持有的锁 ---
    # --- [REFACTOR] Release all locks held by the current process ---
    for type in "${!LOCK_FDS[@]}"; do
        release_lock "$type"
    done

    # --- [修复] 优先从 PID 文件中读取并杀死主守护进程 ---
    # --- [FIX] Prioritize reading from the PID file to kill the main daemon ---
    local pid_file="$DAEMON_PID_FILE"
    if [ -f "$pid_file" ]; then
        local daemon_pid
        daemon_pid=$(cat "$pid_file" 2>/dev/null)
        if [ -n "$daemon_pid" ] && kill -0 "$daemon_pid" 2>/dev/null; then
            debug "正在清理守护进程 (来自 PID 文件): ${daemon_pid} / Cleaning up daemon (from PID file): ${daemon_pid}"
            kill "$daemon_pid" 2>/dev/null || true
            rm -f "$pid_file"
        fi
    fi

    # --- 备用机制 1: 优雅地终止所有已记录的非守护进程后台任务 ---
    # --- Fallback 1: Gracefully terminate all tracked non-daemon background tasks ---
    if [ ${#CORIUM_BACKGROUND_PIDS[@]} -gt 0 ]; then
        debug "正在清理其他后台进程: ${CORIUM_BACKGROUND_PIDS[*]} / Cleaning up other background processes: ${CORIUM_BACKGROUND_PIDS[*]}"
        kill "${CORIUM_BACKGROUND_PIDS[@]}" 2>/dev/null || true
    fi

    # --- 备用机制 2: 原始的基于job的清理，作为最终的“安全网” ---
    # --- Fallback 2: The original job-based cleaning as a final "safety net" ---
    # 这可以捕获任何可能遗漏的后台作业
    # This can catch any background jobs that might have been missed
    if jobs -p | read -r; then
        debug "正在使用 'jobs -p' 进行最终的后台进程清理... / Performing final background process cleanup using 'jobs -p'..."
        jobs -p | xargs -r kill 2>/dev/null || true
    fi
    
    # --- 优雅地移除所有已记录的临时项目 (逻辑不变) ---
    # --- Gracefully remove all tracked temporary items (logic unchanged) ---
    if [ ${#CORIUM_TEMP_ITEMS[@]} -gt 0 ]; then
        debug "正在清理临时项目 / Cleaning up temporary items: ${CORIUM_TEMP_ITEMS[*]}"
        rm -rf "${CORIUM_TEMP_ITEMS[@]}"
    fi
}

# =======================================================================================
# --- [V105.7 SECURITY] 新增内部速率限制器                                            ---
# --- [V105.7 SECURITY] NEW Internal Rate Limiter                                     ---
# =======================================================================================
# Implements a simple token bucket rate limiter using file timestamps.
# This prevents abuse of resource-intensive semi-internal commands.
# 使用文件时间戳实现了一个简单的令牌桶速率限制器。
# 这可以防止资源密集型的半内部命令被滥用。
#
# @param $1 - limiter_name (A unique name for the rate limit bucket, e.g., "dht_crawl")
#             (速率限制桶的唯一名称)
# @param $2 - max_tokens (The maximum number of tokens the bucket can hold (burst capacity))
#             (桶能容纳的最大令牌数 (突发容量))
# @param $3 - refill_rate_seconds (How many seconds it takes to generate one new token)
#             (生成一个新令牌需要多少秒)
# @return 0 if the request is allowed, 1 if it is denied (rate limited).
#         如果请求被允许，返回0；如果被限流，返回1。
_internal_rate_limiter_check() {
    local name="$1"
    local max_tokens="$2"
    local refill_rate="$3"

    local state_file="${LOCK_DIR}/rate_limit_${name}.state"
    touch "$state_file"

    # 从状态文件中读取上一次的状态：令牌数和最后更新时间
    local last_tokens last_update_ts
    read -r last_tokens last_update_ts < "$state_file"
    last_tokens=${last_tokens:-$max_tokens}
    last_update_ts=${last_update_ts:-$(date +%s)}
    
    local now; now=$(date +%s)
    local time_passed=$((now - last_update_ts))

    # 根据经过的时间，计算新生成的令牌数
    local new_tokens=$((time_passed / refill_rate))

    # 将新令牌加入桶中，但不能超过最大容量
    local current_tokens=$((last_tokens + new_tokens))
    if [ "$current_tokens" -gt "$max_tokens" ]; then
        current_tokens="$max_tokens"
    fi

    # 检查是否有足够的令牌来处理当前请求
    if [ "$current_tokens" -ge 1 ]; then
        # 消耗一个令牌
        current_tokens=$((current_tokens - 1))
        # 将新状态写回文件
        echo "$current_tokens $now" > "$state_file"
        return 0 # 允许
    else
        # 令牌不足
        # 将当前时间（而不是上一次的更新时间）写回，以防止“饿死”
        echo "0 $now" > "$state_file"
        return 1 # 拒绝
    fi
}

# Generate random bytes for cryptographic operations
# We don't use it now, except a semi-internal function
random_bytes() {
    local count=$1
    openssl rand -hex "$count"
}

# Base64 encode/decode
# We don't use them now, except a semi-internal function
base64_encode() { base64 -w0; }
