    if [ -f "$DAEMON_PID_FILE" ] && kill -0 "$(cat "$DAEMON_PID_FILE" 2>/dev/null)" 2>/dev/null; then
        info "主 P2P 守护进程已在运行。跳过启动。 / Main P2P daemon is already running. Skipping launch."
