            export CORIUM_IPC_SOCKET_PATH="${CORIUM_ROOT%/}/run/corix.${CORIUM_NETWORK_ID}.sock"
            mkdir -p "$(dirname "$CORIUM_IPC_SOCKET_PATH")"
            export VAR_LIB_CORIUM_DIR="$VAR_LIB_CORIUM_DIR"
