def bilingual_print(message_en, message_zh, level="INFO"):
    print(f"PY_DAEMON_LOG|{level}| {message_en} / {message_zh}", file=sys.stderr)

def db_query_ro(db_path, query, params=(), fetch_one=False, fetch_all=False):
    if not db_path or not os.path.exists(db_path): return None
    conn = None
    try:
        with db_lock:
            conn = sqlite3.connect(pathlib.Path(db_path).resolve().as_uri() + "?mode=ro", uri=True, timeout=10)
            cursor = conn.cursor()
            cursor.execute(query, params)
            if fetch_one: return cursor.fetchone()
            if fetch_all: return cursor.fetchall()
    except sqlite3.Error as e:
        bilingual_print(f"Read-only DB query failed: {e}", f"只读数据库查询失败: {e}", "ERROR")
    finally:
        if conn: conn.close()
    return None

def verify_identity_signature(domain, network_id, claimed_id, payload_bytes, signature_hex, pubkey_pem):
    try:
        if not isinstance(claimed_id, str) or len(claimed_id) != 64:
            return False
        if hashlib.sha256(pubkey_pem.rstrip('\n').encode('utf-8')).hexdigest() != claimed_id:
            return False
        if not isinstance(signature_hex, str) or not signature_hex or len(signature_hex) % 2:
            return False
        if any(c not in '0123456789abcdefABCDEF' for c in signature_hex):
            return False
        public_key = load_pem_public_key(pubkey_pem.encode('utf-8'))
        if not isinstance(public_key, ec.EllipticCurvePublicKey) or not isinstance(public_key.curve, ec.SECP256K1):
            return False
        public_key.verify(bytes.fromhex(signature_hex), payload_bytes, ec.ECDSA(hashes.SHA256()))
        return True
    except (ValueError, TypeError, InvalidSignature, AttributeError):
        return False

def parse_protocol_json(data):
    def unique(pairs):
        result = {}
        for key,value in pairs:
            if key in result: raise ValueError("Duplicate protocol field")
            result[key] = value
        return result
    return json.loads(data, object_pairs_hook=unique)

def calculate_hash(data):
    if isinstance(data, str): data = data.encode('utf-8')
    return hashlib.sha256(data).hexdigest()

OUR_NODE_ID_CACHE = None

def get_our_node_id():
    global OUR_NODE_ID_CACHE
    if OUR_NODE_ID_CACHE: return OUR_NODE_ID_CACHE
    if USER_PUBLIC_KEY_FILE and os.path.exists(USER_PUBLIC_KEY_FILE):
        with open(USER_PUBLIC_KEY_FILE, 'r') as f: public_key = f.read()
        OUR_NODE_ID_CACHE = calculate_hash(public_key.rstrip('\n'))
        return OUR_NODE_ID_CACHE
    return "0" * 64

# --- NAT 穿透函数 / NAT Traversal Functions ---
def discover_public_address():
    # RFC 8489 Binding discovers a mapped endpoint without legacy NAT probing.
    # Bound retries and validate the transaction ID before accepting a response.
    import struct
    global PUBLIC_IP, PUBLIC_PORT, NAT_TYPE
    servers = os.environ.get("CORIUM_STUN_SERVERS", "")
    cookie = 0x2112A442
    for server in servers.split(','):
        if not server.strip(): continue
        try:
            host, port = server.strip().rsplit(':', 1)
            address = socket.getaddrinfo(host.strip('[]'), int(port), type=socket.SOCK_DGRAM)[0]
            family, socktype, protocol, _, endpoint = address
            with socket.socket(family, socktype, protocol) as client:
                client.connect(endpoint)
                transaction = os.urandom(12)
                request = struct.pack('!HHI', 1, 0, cookie) + transaction
                for retry in range(3):
                    client.settimeout(0.5 * (2 ** retry))
                    client.send(request)
                    deadline = time.monotonic() + 0.5 * (2 ** retry)
                    while time.monotonic() < deadline:
                        client.settimeout(max(0.001, deadline-time.monotonic()))
                        try: response = client.recv(65535)
                        except socket.timeout: break
                        if len(response) < 20: continue
                        kind, size, received_cookie = struct.unpack('!HHI', response[:8])
                        if kind != 0x0101 or received_cookie != cookie or response[8:20] != transaction: continue
                        if size % 4 or len(response) != 20 + size: continue
                        offset = 20
                        while offset + 4 <= len(response):
                            attribute, length = struct.unpack('!HH', response[offset:offset+4])
                            value = response[offset+4:offset+4+length]
                            offset += 4 + ((length + 3) // 4) * 4
                            if len(value) != length or offset > len(response): break
                            if attribute not in (0x0020, 0x0001) or length < 4: continue
                            ip_family = value[1]
                            width = 4 if ip_family == 1 else 16 if ip_family == 2 else 0
                            if not width or length != 4 + width: continue
                            mapped_port = int.from_bytes(value[2:4], 'big')
                            raw_ip = value[4:]
                            if attribute == 0x0020:
                                mapped_port ^= cookie >> 16
                                mask = struct.pack('!I', cookie) + transaction
                                raw_ip = bytes(a ^ b for a, b in zip(raw_ip, mask))
                            if not mapped_port: continue
                            PUBLIC_IP = socket.inet_ntop(socket.AF_INET if width == 4 else socket.AF_INET6, raw_ip)
                            PUBLIC_PORT, NAT_TYPE = mapped_port, 'Unknown'
                            bilingual_print(f"STUN success! Public address: {PUBLIC_IP}:{PUBLIC_PORT}", f"STUN成功！公网地址: {PUBLIC_IP}:{PUBLIC_PORT}", "OK")
                            return
        except (OSError, ValueError, struct.error) as error:
            bilingual_print(f"STUN query to {server} failed: {error}", f"对 {server} 的STUN查询失败: {error}", "DEBUG")
    bilingual_print("Failed to discover public IP via any STUN server.", "通过所有STUN服务器发现公网IP均失败。", "WARN")

def setup_automatic_port_forwarding():
    if not MINIUPNPC_AVAILABLE or os.environ.get("CORIUM_ENABLE_UPNP", "false").lower() != 'true':
        return

    bilingual_print("Attempting automatic port forwarding via UPnP/NAT-PMP...", "正在尝试通过UPnP/NAT-PMP进行自动端口转发...", "INFO")
    try:
        upnp = miniupnpc.UPnP()
        upnp.discoverdelay = 200
        upnp.discover()
        upnp.selectigd()
        
        local_ip = upnp.lanaddr
        http_offset = int(os.environ.get("CORIUM_P2P_HTTP_PORT_OFFSET"))
        file_offset = int(os.environ.get("CORIUM_P2P_FILE_PORT_OFFSET"))
        p2p_port = int(os.environ.get("CORIUM_P2P_PORT"))
        ports_to_map = {
            p2p_port: "Corium P2P DHT",
            p2p_port + http_offset: "Corium P2P HTTPS API",
            p2p_port + file_offset: "Corium P2P File Server"
        }

        for port, desc in ports_to_map.items():
            try: upnp.deleteportmapping(port, 'TCP')
            except Exception: pass
            upnp.addportmapping(port, 'TCP', local_ip, port, desc, '')
            bilingual_print(f"Successfully mapped external TCP port {port} to local {local_ip}:{port}.", f"成功将外部TCP端口 {port} 映射到本地 {local_ip}:{port}。", "OK")
    except Exception as e:
        bilingual_print(f"UPnP/NAT-PMP setup failed: {e}", f"UPnP/NAT-PMP设置失败: {e}", "WARN")

# ==============================================================================
# --- [V72 FINAL] 统一的 P2P 上传安全审查与执行函数                  ---
# --- [V72 FINAL] Unified P2P Upload Security Check & Execution Function ---
# ==============================================================================
# This is the single source of truth for handling P2P upload requests from
# both DApps and local Mods. It contains the critical user confirmation logic.
# 这是处理来自 DApp 和本地 Mod 的 P2P 上传请求的唯一真相来源。
# 它包含了关键的用户确认逻辑。
def _internal_confirm_and_execute_upload(requester_id, content_string):
    """
    Checks ACL, gets user confirmation if needed, and executes a P2P upload.
    检查 ACL，在需要时获取用户确认，并执行 P2P 上传。
    """
    # --- 1. Permission Check with Interactive Confirmation ---
    # --- 1. 带有交互式确认的权限检查 ---
    auto_approve_policy = get_local_acl_permission(requester_id, 'api.p2p_upload', 'confirm')
    user_approved = False
    
    if auto_approve_policy.lower() == 'true':
        user_approved = True
        bilingual_print(f"P2P upload from '{requester_id}' auto-approved by local ACL.",
                        f"来自 '{requester_id}' 的 P2P 上传已被本地 ACL 自动批准。", "DEBUG")
    elif auto_approve_policy.lower() == 'deny':
        bilingual_print(f"SECURITY ALERT: P2P upload attempt from '{requester_id}' DENIED by local ACL.",
                        f"安全警报: 来自 '{requester_id}' 的 P2P 上传尝试已被本地 ACL 拒绝。", "WARN")
        return None # Explicitly return None on failure
    else: # 'confirm' (default)
        # Interactive confirmation logic
        content_preview = content_string[:200] + ('...' if len(content_string) > 200 else '')
        print("\n" + "="*70, file=sys.stderr)
        bilingual_print(f"SECURITY ALERT: Application '{requester_id}' is requesting to publish content to the P2P network.",
                        f"安全警报: 应用 '{requester_id}' 正在请求向 P2P 网络发布内容。", "WARN")
        print(f"  Size / 大小    : {len(content_string)} bytes\n  Preview / 预览   :\n{content_preview}\n" + "="*70, file=sys.stderr)
        try:
            choice = input(f"  Authorize this action? [y/N] (or add api.p2p_upload = true to the [{requester_id}] section in local_acl.conf to bypass) / 是否授权此操作？[y/N] (或在 local_acl.conf 的 [{requester_id}] 段中添加 api.p2p_upload = true 来跳过此提示) ").lower().strip()
            if choice == 'y':
                user_approved = True
        except EOFError:
            pass # Non-interactive session, treat as 'no'
    
    if not user_approved:
        bilingual_print(f"P2P upload from '{requester_id}' was not authorized by the user.",
                        f"来自 '{requester_id}' 的 P2P 上传未被用户授权。", "INFO")
        return None

    # --- 2. IPC Call to Bash Core ---
    # --- 2. 对 Bash 核心进行 IPC 调用 ---
    try:
        content_bytes = content_string.encode('utf-8')
        result = subprocess.run(
            [SCRIPT_PATH, '--quiet', '_internal_p2p_put_from_stdin'],
            input=content_bytes,
            capture_output=True,
            check=True,
            timeout=300 # Uploading can be slow
        )
        return result.stdout.decode('utf-8').strip()
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired) as e:
        stderr = e.stderr.decode('utf-8').strip() if hasattr(e, 'stderr') and e.stderr else str(e)
        bilingual_print(f"P2P upload IPC call failed: {stderr}", f"P2P 上传 IPC 调用失败: {stderr}", "ERROR")
        return None

# --- [V95 新增] IPC 写数据库辅助函数 ---
# --- [V95 NEW] IPC DB Write Helper Function ---
def ipc_write_to_db(db_path, query, params=()):
    """
    一个专门用于执行写操作的 IPC 调用。
    A dedicated IPC call for write operations.
    """
    try:
        # 调用一个新的内部命令来保证原子性
        # Call a new internal command for atomicity
        subprocess.run(
            [SCRIPT_PATH, '--quiet', '_internal_db_write', db_path, query, json.dumps(params)],
            check=True, timeout=10
        )
        return True
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired) as e:
        stderr = e.stderr.decode('utf-8').strip() if hasattr(e, 'stderr') and e.stderr else str(e)
        bilingual_print(f"IPC DB write failed for query '{query}': {stderr}", f"IPC 数据库写入失败: '{query}': {stderr}", "ERROR")
        return False
        

