class APIDispatcher:
    """
    API调度器，包含所有可供 Mod 调用的方法。
    The API dispatcher, contains all methods callable by Mods.
    """
    def __init__(self, mod_name, supervisor=None):
        self.mod_name = mod_name
        self.supervisor = supervisor

    def _ipc_call(self, args):
        """
        一个内部辅助函数，用于调用 Corium 的 Bash 核心功能。
        An internal helper to call into Corium's Bash core functions.
        """
        try:
            # 使用 --quiet 最小化不必要的输出
            # Use --quiet to minimize unnecessary output
            result = subprocess.run(
                [SCRIPT_PATH, '--quiet'] + args,
                capture_output=True, text=True, check=True, timeout=30
            )
            return {"status": "success", "data": result.stdout.strip()}
        except subprocess.CalledProcessError as e:
            return {"status": "error", "message": f"IPC call failed: {e.stderr.strip()}"}
        except subprocess.TimeoutExpired:
            return {"status": "error", "message": "IPC call timed out."}

    # --- API 方法示例 (API Method Examples) ---
    
    def create_transaction(self, params):
        if len(params) != 2:
            return {"status": "error", "message": "Invalid parameters for create_transaction. Expected [type, data_json]."}
        
        tx_type, tx_data_json = params
        bilingual_print(f"IPC: Mod '{self.mod_name}' requests transaction.", f"IPC: Mod '{self.mod_name}' 请求创建交易。")
        
        # [设计说明] 交互式确认
        # 在一个后台守护进程中处理交互式用户确认是一个复杂的问题。
        # 理想的解决方案是使用一个专用的通知系统 (如 D-Bus) 或一个图形化的授权代理。
        # 为了在当前架构下实现功能，我们采取一个折衷方案：直接在守护进程的终端打印提示。
        # 这要求启动 Corium 的终端是可交互的。这是一个已知的局限。
        #
        # [Design Note] Interactive Confirmation
        # Handling interactive user confirmation from a background daemon is a complex problem.
        # The ideal solution would use a dedicated notification system (like D-Bus) or a graphical
        # authorization agent. To achieve functionality within the current architecture, we adopt a
        # compromise: printing the prompt directly to the daemon's terminal. This requires the
        # terminal that launched Corium to be interactive. This is a known limitation.
        
        # 调用 Bash 核心来创建交易
        # Call the Bash core to create the transaction
        return self._ipc_call(['_internal_create_transaction', tx_type, tx_data_json])

    def subscribe_event(self, params, client_connection):
        if len(params) != 1:
            return {"status": "error", "message": "Invalid parameters for subscribe_event. Expected [event_name]."}
        event_name = params[0]
        
        with event_lock:
            if event_name not in EVENT_SUBSCRIPTIONS:
                EVENT_SUBSCRIPTIONS[event_name] = []
            if client_connection not in EVENT_SUBSCRIPTIONS[event_name]:
                EVENT_SUBSCRIPTIONS[event_name].append(client_connection)
        
        bilingual_print(f"IPC: Mod '{self.mod_name}' subscribed to event '{event_name}'.", f"IPC: Mod '{self.mod_name}' 已订阅事件 '{event_name}'。")
        return {"status": "success", "data": f"Successfully subscribed to {event_name}."}
    
    # --- [NEW] Get the status of all Agent services ---
    def get_service_status(self, params):
        """
        返回 AGENT_STATE 字典的一个可序列化副本。
        Returns a serializable copy of the AGENT_STATE dictionary.
        """
        with AGENT_STATE_LOCK:
            # 创建一个安全的、可被 JSON 序列化的状态副本
            # Create a safe, JSON-serializable copy of the state
            status_snapshot = {}
            for pkg_id, state in AGENT_STATE.items():
                status_snapshot[pkg_id] = {
                    'status': state.get('status', 'unknown'),
                    'pid': state.get('pid'),
                    'restarts': state.get('restarts', 0),
                    'is_unboxed': state.get('is_unboxed', False),
                    'log_file': state.get('log_file', 'N/A'),
                    'port_file': state.get('port_file')
                }
        bilingual_print(f"IPC: API call 'get_service_status' handled.",
                        f"IPC: 已处理 API 调用 'get_service_status'。", "DEBUG")
        return {"status": "success", "data": status_snapshot}

    # --- [新增] 控制单个 Agent 服务的启停 ---
    # --- [NEW] Control the start/stop of a single Agent service ---
    def control_service(self, params):
        """
        直接调用 Supervisor 的方法来控制一个 Agent，并返回操作结果。
        Directly calls the Supervisor's methods to control an Agent and returns the result.
        """
        if not self.supervisor:
            return {"status": "error", "message": "Supervisor is not available in this context."}
        if len(params) != 2:
            return {"status": "error", "message": "Invalid params. Expected [action, pkg_id]."}
        
        action, pkg_id = params
        bilingual_print(f"IPC: API call 'control_service' received: {action} {pkg_id}",
                        f"IPC: 收到 API 调用 'control_service': {action} {pkg_id}", "DEBUG")

        result = False
        message = ""
        
        if action == "start":
            result, message = self.supervisor.start_agent(pkg_id)
        elif action == "stop":
            result, message = self.supervisor.stop_agent(pkg_id, reason="manual")
        elif action == "restart":
            stop_res, stop_msg = self.supervisor.stop_agent(pkg_id, reason="restart")
            if stop_res:
                result, message = self.supervisor.start_agent(pkg_id)
            else:
                result, message = False, f"Failed to stop agent for restart: {stop_msg}"
        else:
            return {"status": "error", "message": f"Unknown action: {action}"}

        if result:
            return {"status": "success", "data": message}
        else:
            return {"status": "error", "message": message}
            
    # =========================================================================
    # --- [NEW V72 APIDispatcher METHODS] for Mod IPC access              ---
    # --- [V72 新增 APIDispatcher 方法] 用于 Mod 的 IPC 访问                ---
    # =========================================================================
    def p2p_upload(self, params):
        if len(params) != 1:
            return {"status": "error", "message": "Invalid params for p2p_upload. Expected [content_string]."}
        
        content_string = params[0]
        bilingual_print(f"IPC: Mod '{self.mod_name}' requests P2P upload.", f"IPC: Mod '{self.mod_name}' 请求 P2P 上传。")
        
        # Delegate to the unified security and execution function.
        # 委托给统一的安全与执行函数。
        uploaded_hash = _internal_confirm_and_execute_upload(self.mod_name, content_string)
        
        if uploaded_hash is not None:
            return {"status": "success", "data": uploaded_hash}
        else:
            return {"status": "error", "message": "P2P upload failed or was denied by user."}
        
    def p2p_download(self, params):
        if len(params) != 1:
            return {"status": "error", "message": "Invalid params for p2p_download. Expected [object_hash]."}
        
        object_hash = params[0]
        bilingual_print(f"IPC: Mod '{self.mod_name}' requests P2P download for {object_hash[:12]}.", f"IPC: Mod '{self.mod_name}' 请求 P2P 下载 {object_hash[:12]}。")
        
        # The _ipc_call is in the CoriumGatewayHandler instance, so we need to access it.
        # _ipc_call 位于 CoriumGatewayHandler 实例中，所以我们需要访问它。
        # This is a bit of a workaround; a better design might have a shared IPC client.
        # 这算是一个变通方法；更好的设计可能会有一个共享的IPC客户端。
        try:
            result = subprocess.run([SCRIPT_PATH, '--quiet', '_internal_p2p_get_bytes', object_hash], capture_output=True, check=True, timeout=30)
            content_bytes = result.stdout
        except (subprocess.CalledProcessError, subprocess.TimeoutExpired):
            content_bytes = None
        if content_bytes is not None:
            content_b64 = base64.b64encode(content_bytes).decode('ascii')
            return {"status": "success", "data": content_b64}
        else:
            return {"status": "error", "message": "P2P download failed or object not found."} 
        
       
            
            
def get_local_acl_permission(mod_name, permission_key, default_value='deny'):
    """
    从 local_acl.conf 文件中安全地解析权限。
    Safely parses a permission from the local_acl.conf file.
    """
    if not LOCAL_ACL_FILE or not os.path.exists(LOCAL_ACL_FILE):
        return default_value
    
    config = configparser.ConfigParser()
    try:
        config.read(LOCAL_ACL_FILE)
        section_name = f"mod:{mod_name}"
        if config.has_section(section_name):
            return config.get(section_name, permission_key, fallback=default_value)
    except configparser.Error:
        pass # Ignore parsing errors in the config file
    
    return default_value

# ==============================================================================
# --- [新增] Corium Agent Supervisor (V1.0)                                    ---
# --- [NEW] Corium Agent Supervisor (V1.0)                                     ---
# ==============================================================================
# 这个类负责启动、监控和管理所有被声明为持久化服务的 Corium Agents。
# This class is responsible for starting, monitoring, and managing all Corium Agents
# that are declared as persistent services.

class CoriumAgentSupervisor(threading.Thread):
    def __init__(self):
        super().__init__(daemon=True, name="Agent-Supervisor-Thread")
        # 从环境变量获取必要的路径
        # Get necessary paths from environment variables
        self.etc_corium_dir = os.environ.get('ETC_CORIUM_DIR')
        self.script_path = os.environ.get('SCRIPT_PATH')
        self.agent_logs_dir = os.path.join(os.environ.get('VAR_LIB_CORIUM_DIR'), 'logs', 'agents')
        self.enabled_mods_file = os.path.join(self.etc_corium_dir, 'mods_enabled.conf') if self.etc_corium_dir else None
        # [V98 新增] 增加对 psutil 可用性的检查
        # [V98 NEW] Add check for psutil availability
        if not PSUTIL_AVAILABLE:
            bilingual_print("psutil library not found, Agent resource monitoring will be disabled.",
                            "未找到 psutil 库，Agent 资源监控功能将被禁用。", "WARN")

        
        # 确保日志目录存在
        # Ensure the log directory exists
        if not os.path.exists(self.agent_logs_dir):
            os.makedirs(self.agent_logs_dir, exist_ok=True)

    def run(self):
        """
        Supervisor 的主循环。它会定期扫描配置，并与当前状态比对，以管理 Agents 的生命周期。
        The main loop for the Supervisor. It periodically scans the configuration and compares it
        against the current state to manage the lifecycle of Agents.
        """
        bilingual_print("Agent Supervisor started. Initial scan in 5 seconds...", "Agent Supervisor 已启动。将在5秒后进行初次扫描...", "INFO")
        time.sleep(5) # 给予守护进程其他部分启动的时间 / Give other parts of the daemon time to start
        
        # [V98 新增] 启动资源监控线程 (如果 psutil 可用)
        # [V98 NEW] Start the resource monitor thread (if psutil is available)
        if PSUTIL_AVAILABLE:
            monitor_thread = threading.Thread(target=self.resource_monitor_loop, daemon=True, name="Agent-Resource-Monitor")
            monitor_thread.start()
            bilingual_print("Agent resource monitor thread started.", "Agent 资源监控线程已启动。", "INFO")

        while True:
            try:
                self.scan_and_manage_agents()
            except Exception as e:
                bilingual_print(f"Error in Agent Supervisor loop: {e}", f"Agent Supervisor 循环出错: {e}", "ERROR")
            time.sleep(15) # 扫描周期为 15 秒 / Scan interval is 15 seconds
            
    # [V98 新增] 完整的资源监控循环函数
    # [V98 NEW] Complete resource monitor loop function
    def resource_monitor_loop(self):
        """
        一个在后台运行的独立循环，用于监控所有 Agent 的资源使用情况。
        A separate loop running in the background to monitor resource usage of all Agents.
        """
        time.sleep(20) # 首次启动后稍作等待
        while True:
            with AGENT_STATE_LOCK:
                # 使用 list() 复制字典键，以允许在循环中安全地修改字典
                # Use list() to copy dict keys to allow safe modification during iteration
                for pkg_id in list(AGENT_STATE.keys()):
                    state = AGENT_STATE.get(pkg_id)
                    if not state or state.get('status') != 'running' or not state.get('pid'):
                        continue
                    
                    try:
                        proc = psutil.Process(state.get('pid'))
                        mem_percent = proc.memory_percent()
                        cpu_percent = proc.cpu_percent(interval=1) # 1秒间隔的CPU使用率
                        
                        # 从状态中获取资源限制
                        # Get resource limits from the state
                        mem_limit_mb = state.get('memory_limit_mb', 64) # 默认 64MB
                        cpu_limit_percent = state.get('cpu_limit_percent', 25) # 默认 25%

                        # 检查内存使用是否超限
                        # Check memory usage
                        if mem_limit_mb > 0:
                            mem_usage_mb = proc.memory_info().rss / (1024 * 1024)
                            if mem_usage_mb > mem_limit_mb:
                                bilingual_print(f"Agent '{pkg_id}' exceeded memory limit ({mem_usage_mb:.1f}MB > {mem_limit_mb}MB). Triggering circuit breaker.",
                                                f"Agent '{pkg_id}' 超出内存限制 ({mem_usage_mb:.1f}MB > {mem_limit_mb}MB)。正在触发熔断机制。", "WARN")
                                self.stop_agent(pkg_id, reason="faulted_memory_limit")

                        # 检查CPU使用是否持续超限 (一个简单的滑动窗口)
                        # Check for sustained high CPU usage (a simple sliding window)
                        if cpu_limit_percent > 0:
                            cpu_history = state.get('cpu_history', [])
                            cpu_history.append(cpu_percent)
                            if len(cpu_history) > 5: # 检查过去5个周期的平均值
                                cpu_history.pop(0)
                                avg_cpu = sum(cpu_history) / len(cpu_history)
                                if avg_cpu > cpu_limit_percent:
                                    bilingual_print(f"Agent '{pkg_id}' exceeded average CPU limit ({avg_cpu:.1f}% > {cpu_limit_percent}%). Triggering circuit breaker.",
                                                    f"Agent '{pkg_id}' 超出平均 CPU 限制 ({avg_cpu:.1f}% > {cpu_limit_percent}%). 正在触发熔断机制。", "WARN")
                                    self.stop_agent(pkg_id, reason="faulted_cpu_limit")
                            state['cpu_history'] = cpu_history

                    except psutil.NoSuchProcess:
                        # 进程已不存在，主循环会处理它
                        # Process is already gone, main loop will handle it
                        continue
                    except Exception as e:
                        bilingual_print(f"Error in resource monitor for '{pkg_id}': {e}",
                                        f"在为 '{pkg_id}' 进行资源监控时出错: {e}", "ERROR")

            time.sleep(10) # 监控周期为10秒

    def _ipc_call(self, args):
        """
        一个简化的、用于调用 Bash 内部函数的 IPC 客户端。
        A simplified IPC client for calling internal Bash functions.
        """
        if not self.script_path: return None
        try:
            result = subprocess.run(
                [self.script_path, '--quiet'] + args,
                capture_output=True, text=True, check=True, timeout=10
            )
            return result.stdout.strip()
        except (subprocess.CalledProcessError, subprocess.TimeoutExpired) as e:
            stderr = e.stderr.strip() if hasattr(e, 'stderr') and e.stderr else str(e)
            bilingual_print(f"Supervisor IPC call failed: {' '.join(args)} -> {stderr}",
                            f"Supervisor IPC调用失败: {' '.join(args)} -> {stderr}", "ERROR")
            return None

    def scan_and_manage_agents(self):
        """
        核心管理逻辑。
        The core management logic.
        """
        if not self.enabled_mods_file or not os.path.exists(self.enabled_mods_file):
            return

        # 1. 获取当前期望运行的服务列表
        # 1. Get the current list of desired services
        current_desired_agents = {}
        with open(self.enabled_mods_file, 'r') as f:
            for line in f:
                pkg_id = line.strip()
                if not pkg_id or pkg_id.startswith('#'):
                    continue
                
                is_persistent = self._ipc_call(['_internal_get_mod_meta', pkg_id, 'persistent_service'])
                if is_persistent == 'true':
                    current_desired_agents[pkg_id] = True
        
        with AGENT_STATE_LOCK:
            # 2. 启动新启用的服务
            # 2. Start newly enabled services
            for pkg_id in current_desired_agents:
                if pkg_id not in AGENT_STATE:
                    self.start_agent(pkg_id)

            # 3. 停止已禁用的服务 (使用 list() 复制键)
            # 3. Stop disabled services (use list() to copy keys)
            for pkg_id in list(AGENT_STATE.keys()):
                if pkg_id not in current_desired_agents:
                    self.stop_agent(pkg_id, "disabled")

            # 4. 检查正在运行的服务的状态
            # 4. Check the status of running services
            for pkg_id, state in list(AGENT_STATE.items()):
                if state.get('status') == 'running':
                    proc = state.get('process')
                    if proc and proc.poll() is not None: # 进程已退出
                        bilingual_print(f"Agent '{pkg_id}' terminated unexpectedly with code {proc.returncode}.",
                                        f"Agent '{pkg_id}' 意外终止，退出码 {proc.returncode}。", "WARN")
                        
                        state['status'] = 'stopped'
                        state['pid'] = None
                        state['restarts'] = state.get('restarts', 0) + 1
                        
                        # 5. 应用重启策略
                        # 5. Apply restart policy
                        if state.get('restart_policy') == 'always' or \
                           (state.get('restart_policy') == 'on-failure' and proc.returncode != 0):
                            bilingual_print(f"Restarting Agent '{pkg_id}' based on policy.",
                                            f"根据策略，正在重启 Agent '{pkg_id}'。", "INFO")
                            self.start_agent(pkg_id)

    def start_agent(self, pkg_id):
        """
        启动一个指定的 Agent。此方法是线程安全的。
        Starts a specific Agent. This method is thread-safe.

        Returns:
            (bool, str): A tuple containing the success status and a descriptive message.
                         一个包含成功状态和描述性消息的元组。
        """
        with AGENT_STATE_LOCK:
            # 步骤 1: 检查 Agent 是否已在运行
            # Step 1: Check if the Agent is already running
            state = AGENT_STATE.get(pkg_id)
            if state and state.get('status') == 'running':
                pid = state.get('pid', 'N/A')
                message = f"Agent '{pkg_id}' is already running with PID {pid}."
                bilingual_print(message, f"Agent '{pkg_id}' 已在运行，PID 为 {pid}。", "DEBUG")
                return True, message

            bilingual_print(f"Attempting to start Agent: {pkg_id}", f"正在尝试启动 Agent: {pkg_id}", "INFO")
            
            # 步骤 2: 通过 IPC 调用 Bash 来获取 Agent 的元数据
            # Step 2: Call Bash via IPC to get the Agent's metadata
            meta_json = self._ipc_call(['_internal_get_mod_meta_all', pkg_id])
            if not meta_json:
                err_msg = f"Failed to get metadata for Agent '{pkg_id}'. Cannot start."
                bilingual_print(err_msg, f"无法获取 Agent '{pkg_id}' 的元数据。无法启动。", "ERROR")
                AGENT_STATE[pkg_id] = {'status': 'error', 'reason': 'Metadata fetch failed'}
                return False, err_msg

            # 步骤 3: 解析元数据
            # Step 3: Parse the metadata
            try:
                meta = json.loads(meta_json)
            except (json.JSONDecodeError, TypeError):
                err_msg = f"Failed to parse metadata for Agent '{pkg_id}'."
                bilingual_print(err_msg, f"无法解析 Agent '{pkg_id}' 的元数据。", "ERROR")
                AGENT_STATE[pkg_id] = {'status': 'error', 'reason': 'Metadata parse failed'}
                return False, err_msg

            # 步骤 4: 准备启动命令和日志文件
            # Step 4: Prepare the launch command and log file
            cmd = [self.script_path, '_internal_launch_agent', pkg_id]

            log_file_base = os.path.join(self.agent_logs_dir, pkg_id.replace('/', '_'))
            self.rotate_log(log_file_base) # 轮转旧日志 / Rotate old logs
            log_file_path = f"{log_file_base}.log"
            
            # [V84.1 新增] 为持久化服务创建端口文件路径
            # [V84.1 NEW] Create a port file path for persistent services
            port_file_path = os.path.join(self.agent_logs_dir, f"{pkg_id.replace('/', '_')}.port")

            # [V84.1 新增] 准备传递给子进程的环境变量
            # [V84.1 NEW] Prepare environment variables to pass to the child process
            child_env = os.environ.copy()
            child_env['CORIUM_PORT_FILE'] = port_file_path
            
            # 步骤 5: 启动子进程并重定向输出
            # Step 5: Launch the subprocess and redirect its output
            try:
                # 使用 close_fds=True 是一个好的安全实践，可以防止文件描述符泄露到子进程
                # Using close_fds=True is a good security practice to prevent file descriptor leakage
                log_handle = open(log_file_path, 'a')
                proc = subprocess.Popen(cmd, stdout=log_handle, stderr=log_handle, text=True, close_fds=True, env=child_env)
            except Exception as e:
                err_msg = f"Failed to launch Agent process for '{pkg_id}': {e}"
                bilingual_print(err_msg, f"为 '{pkg_id}' 启动 Agent 进程失败: {e}", "ERROR")
                # 确保关闭可能已打开的文件句柄
                if 'log_handle' in locals() and not log_handle.closed:
                    log_handle.close()
                return False, err_msg

            # 步骤 6: 更新全局状态字典
            # Step 6: Update the global state dictionary
            AGENT_STATE[pkg_id] = {
                'process': proc,
                'status': 'running',
                'port_file': port_file_path,
                'pid': proc.pid,
                # 如果是重启，则在原有重启次数上加1，否则从0开始
                # If restarting, increment the restart count, otherwise start from 0
                'restarts': state.get('restarts', -1) + 1 if state else 0,
                'restart_policy': meta.get('restart_policy', 'on-failure'),
                'is_unboxed': meta.get('unboxed_execution') == 'true',
                'log_file': log_file_path,
                'log_handle': log_handle # 保存文件句柄以便后续可以关闭它
            }
            
            message = f"Agent '{pkg_id}' started successfully with PID {proc.pid}."
            bilingual_print(message, f"Agent '{pkg_id}' 成功启动，PID 为 {proc.pid}。", "OK")
            
            # 步骤 7: 返回成功状态和消息
            # Step 7: Return success status and message
            return True, message

    def stop_agent(self, pkg_id, reason="manual"):
        """
        停止一个指定的 Agent。此方法是线程安全的。
        Stops a specific Agent. This method is thread-safe.
        Returns: (bool, str) - (success_status, message)
        """
        with AGENT_STATE_LOCK:
            state = AGENT_STATE.get(pkg_id)
            if not state or state.get('status') != 'running':
                message = f"Agent '{pkg_id}' is not running or not managed. Nothing to stop."
                bilingual_print(message, f"Agent '{pkg_id}' 未在运行或不受管理。无需停止。", "DEBUG")
                # 如果是因为 restart 或 disable 而调用，认为“已经停止”是成功
                return True, message

            bilingual_print(f"Stopping Agent '{pkg_id}' (Reason: {reason})",
                            f"正在停止 Agent '{pkg_id}' (原因: {reason})", "INFO")
            
            proc = state.get('process')
            if proc:
                proc.terminate()
                try:
                    proc.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    bilingual_print(f"Agent '{pkg_id}' did not terminate gracefully. Killing.",
                                    f"Agent '{pkg_id}' 未能优雅地终止。正在强制结束。", "WARN")
                    proc.kill()
            
            state['status'] = 'stopped'
            state['pid'] = None
            
            if reason.startswith("faulted"):
                state['status'] = 'faulted' # 标记为熔断状态
                state['pid'] = None
                # 在这种状态下，服务不会被自动重启
                # The service will not be automatically restarted in this state
            else:
                state['status'] = 'stopped'
                state['pid'] = None
                
            if reason == "disabled":
                del AGENT_STATE[pkg_id]
            
            message = f"Agent '{pkg_id}' stopped successfully."
            bilingual_print(message, f"Agent '{pkg_id}' 已成功停止。", "OK")
            return True, message
            
    def rotate_log(self, base_path, keep=3):
        """
        简单的日志轮转。
        Simple log rotation.
        """
        if os.path.exists(f"{base_path}.log"):
            # 删除最旧的日志
            oldest_log = f"{base_path}.{keep}.log"
            if os.path.exists(oldest_log):
                os.remove(oldest_log)
            # 轮转现有的日志
            for i in range(keep - 1, 0, -1):
                src = f"{base_path}.{i}.log"
                dst = f"{base_path}.{i+1}.log"
                if os.path.exists(src):
                    os.rename(src, dst)
            # 备份当前的日志
            os.rename(f"{base_path}.log", f"{base_path}.1.log")
    
    # --- [V74 Stop-Fix NEW METHOD] ---
    def shutdown_all_agents(self):
        """
        按顺序、优雅地停止所有被管理的 Agent。
        Gracefully stop all managed agents in sequence.
        """
        bilingual_print("Supervisor is shutting down all managed agents...",
                        "Supervisor 正在关停所有被管理的 Agent...", "INFO")
        with AGENT_STATE_LOCK:
            # 使用 list() 复制键，因为我们会在循环中修改字典
            # Use list() to copy keys as we will be modifying the dict in the loop
            for pkg_id in list(AGENT_STATE.keys()):
                # reason="daemon_shutdown" 可以让 stop_agent 知道这是正常关停
                # reason="daemon_shutdown" lets stop_agent know this is a normal shutdown
                self.stop_agent(pkg_id, reason="daemon_shutdown")
        bilingual_print("All agents have been instructed to stop.",
                        "已向所有 Agent 发出停止指令。", "OK")
            
class IPC_Gateway_Thread(threading.Thread):
    """
    监听 Unix 套接字，处理来自 Mods 的 JSON-RPC 请求。
    Listens on a Unix socket and processes JSON-RPC requests from Mods.
    """
    def __init__(self, supervisor): # <--- 接收 supervisor 参数
        super().__init__(daemon=True, name="IPC-Gateway-Thread")
        self.supervisor = supervisor # <--- 使用接收到的参数

    def run(self):
        if os.path.exists(IPC_SOCKET_PATH):
            os.remove(IPC_SOCKET_PATH)
            
        server = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        server.bind(IPC_SOCKET_PATH)
        server.listen(5)
        bilingual_print(f"IPC Gateway is listening on {IPC_SOCKET_PATH}", f"IPC 网关正在 {IPC_SOCKET_PATH} 上监听")
        
        while True:
            conn, _ = server.accept()
            handler_thread = threading.Thread(target=self.handle_client, args=(conn,), daemon=True)
            handler_thread.start()

    def handle_client(self, conn):
        try:
            with conn:
                while True:
                    data = conn.recv(4096)
                    if not data: break
                    
                    try:
                        req = json.loads(data.decode('utf-8'))
                        bilingual_print(f"IPC Request Received: {req}", f"收到 IPC 请求: {req}", "DEBUG")
                        
                        # [核心] 从请求中获取 Mod 名称，这是权限检查的基础
                        # [CORE] Get the mod name from the request, this is the basis for permission checks
                        mod_name = req.get('mod_name')
                        if not mod_name:
                            response = self.create_error_response(-32600, "Invalid Request: 'mod_name' is missing.", req.get('id'))
                            conn.sendall(response.encode('utf-8'))
                            continue

                        # [核心] 权限检查
                        # [CORE] Permission Check
                        permission_key = f"api.{req['method']}"
                        permission_value = get_local_acl_permission(mod_name, permission_key, 'confirm') # 默认为 confirm
                        
                        if permission_value not in ('true','allow','yes','1'):
                            approved = False
                            if permission_value == 'confirm' and sys.stdin.isatty():
                                try: approved = input(f"Authorize {mod_name}: {req['method']}? [y/N] / 授权此操作？[y/N] ").strip().lower() == 'y'
                                except EOFError: approved = False
                            if approved:
                                permission_value = 'allow'
                        if permission_value not in ('true','allow','yes','1'):
                            response = self.create_error_response(-32000, "Permission Denied", req.get('id'))
                            conn.sendall(response.encode('utf-8'))
                            continue
                        
                        # [核心] API 方法调度
                        # [CORE] API Method Dispatch
                        api = APIDispatcher(mod_name, supervisor=self.supervisor)
                        method = getattr(api, req['method'], None)
                        
                        if callable(method):
                            if req['method'] == 'subscribe_event':
                                result = method(req.get('params', []), conn)
                            else:
                                result = method(req.get('params', []))
                            
                            if result.get('status') == 'success':
                                response = self.create_success_response(result.get('data'), req.get('id'))
                            else:
                                response = self.create_error_response(-32001, result.get('message'), req.get('id'))
                        else:
                            response = self.create_error_response(-32601, "Method not found", req.get('id'))
                        
                        conn.sendall(response.encode('utf-8'))

                    except (json.JSONDecodeError, KeyError):
                        response = self.create_error_response(-32700, "Parse error", None)
                        conn.sendall(response.encode('utf-8'))

        except Exception as e:
            bilingual_print(f"IPC client handler error: {e}", f"IPC 客户端处理器错误: {e}", "ERROR")

    def create_success_response(self, result, req_id):
        return json.dumps({"jsonrpc": "2.0", "result": result, "id": req_id}) + "\n"
    
    def create_error_response(self, code, message, req_id):
        return json.dumps({"jsonrpc": "2.0", "error": {"code": code, "message": message}, "id": req_id}) + "\n"


# --- CoriumGatewayHandler (完整且修正版) ---
# BEGIN ZIOKT STATIC SITE HELPERS
"""Read-only NNS static assets: content integrity, clean URLs, executable JS isolation."""
import base64 as _cs_b64
import hashlib as _cs_hash
import json as _cs_json
import re as _cs_re
import mimetypes as _cs_mime
from html.parser import HTMLParser as _CSParser
from urllib.parse import unquote as _cs_unquote


def cs_path(path):
    if not isinstance(path,str) or len(path)>2048 or _cs_re.search('%(?:2f|5c|00)',path,_cs_re.I):raise ValueError('invalid static path')
    path=_cs_unquote(path,errors='strict').lstrip('/')
    if any(c in path for c in ('\\','\0','?','#')) or any(x in {'.','..'} for x in path.split('/')):raise ValueError('invalid static path')
    if any(ord(c)<32 for c in path):raise ValueError('invalid static path')
    return path


def cs_resolve(manifest,path):
    if not isinstance(manifest,dict) or not isinstance(manifest.get('files'),dict) or len(manifest['files'])>100000:raise ValueError('invalid static manifest')
    path=cs_path(path);files=manifest['files']
    if not path:path=manifest.get('index','index.html')
    candidates=[path]
    if path.endswith('/'):candidates.append(path+'index.html')
    elif not path.rsplit('/',1)[-1].count('.'):candidates.extend([path+'/index.html',path+'.html'])
    for candidate in candidates:
        if candidate in files:return candidate,files[candidate],200
    # SPA fallback is opt-in; never turn missing .js assets into HTML.
    if manifest.get('static_routing')=='spa' and not path.rsplit('/',1)[-1].count('.') and 'index.html' in files:return 'index.html',files['index.html'],200
    if '404.html' in files:return '404.html',files['404.html'],404
    raise FileNotFoundError('static file unavailable')


def cs_content(digest,fetch,maximum=64*1024*1024):
    def get(key):
        if not isinstance(key,str) or not _cs_re.fullmatch('[a-f0-9]{64}',key):raise ValueError('invalid static object reference')
        data=fetch(key)
        if not isinstance(data,bytes) or len(data)>maximum or _cs_hash.sha256(data).hexdigest()!=key:raise ValueError('static object missing or corrupt')
        return data
    raw=get(digest)
    try:value=_cs_json.loads(raw)
    except (UnicodeError,ValueError):return raw
    if not isinstance(value,dict) or 'chunks' not in value or 'size' not in value:return raw
    if (type(value['size']) is not int or not 0<=value['size']<=maximum or not isinstance(value['chunks'],list) or len(value['chunks'])>4096):raise ValueError('static chunk manifest rejected')
    output=bytearray()
    for chunk in value['chunks']:
        part=get(chunk)
        if len(output)+len(part)>value['size']:raise ValueError('static content exceeds declared size')
        output.extend(part)
    if len(output)!=value['size']:raise ValueError('static content truncated')
    return bytes(output)


class _CSInline(_CSParser):
    def __init__(self):super().__init__(convert_charrefs=False);self.script=False;self.parts=[];self.hashes=set();self.handlers=set()
    def handle_starttag(self,tag,attrs):
        if tag=='script':self.script=True;self.parts=[]
        for key,value in attrs:
            if key.lower().startswith('on') and value:self.handlers.add(self.digest(value))
    def handle_endtag(self,tag):
        if tag=='script' and self.script:
            if self.parts:self.hashes.add(self.digest(''.join(self.parts)))
            self.script=False
    def handle_data(self,data):
        if self.script:self.parts.append(data)
    def digest(self,value):return "'sha256-"+_cs_b64.b64encode(_cs_hash.sha256(value.replace('\r\n','\n').replace('\r','\n').encode()).digest()).decode()+"'"


def cs_headers(path,content,*,isolated=False,wasm=False):
    kind,encoding=_cs_mime.guess_type(path)
    kind={'.mjs':'text/javascript','.wasm':'application/wasm','.webmanifest':'application/manifest+json'}.get('.'+path.rsplit('.',1)[-1],kind) or 'application/octet-stream'
    script=["'self'"];parser=_CSInline()
    if kind in {'text/html','application/xhtml+xml'}:
        parser.feed(content.decode('utf-8'));script.extend(sorted(parser.hashes))
        if parser.handlers:script.extend(["'unsafe-hashes'",*sorted(parser.handlers)])
    if wasm:script.append("'wasm-unsafe-eval'")
    # Opaque origin on a shared portal; origin-preserving sandbox only on an
    # independently routed static-only origin, never selected by public input.
    sandbox='sandbox allow-scripts'+(' allow-same-origin' if isolated else '')
    policy=sandbox+"; default-src 'none'; script-src "+' '.join(script)+"; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self'; media-src 'self' blob:; connect-src 'self'; worker-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"
    headers={'Content-Type':kind+('; charset=utf-8' if kind.startswith('text/') or kind in {'application/javascript','application/json'} else ''),
        'Content-Security-Policy':policy,'X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer',
        'Permissions-Policy':'camera=(), microphone=(), geolocation=(), browsing-topics=()',
        'Access-Control-Allow-Origin':'*','Cross-Origin-Resource-Policy':'cross-origin','X-DNS-Prefetch-Control':'off',
        'ETag':'"'+_cs_hash.sha256(content).hexdigest()+'"','Cache-Control':'public, max-age=60, must-revalidate'}
    if encoding=='gzip':headers['Content-Encoding']='gzip'
    return headers

# END ZIOKT STATIC SITE HELPERS

class CoriumGatewayHandler(http.server.BaseHTTPRequestHandler):
    punch_slots = threading.BoundedSemaphore(4)
    punch_lock = threading.Lock()
    punch_recent = {}
    _nns_cache = {}
    _manifest_cache = {}
    _cache_lock = threading.Lock()
    CACHE_TTL = 60.0

    def _punch_admit(self, sender):
        now = time.monotonic()
        with self.punch_lock:
            type(self).punch_recent = {k:v for k,v in self.punch_recent.items() if v > now}
            if sender in self.punch_recent or len(self.punch_recent) >= 256: return False
            self.punch_recent[sender] = now + 30
            return True

    def _punch_addresses(self, requester, advertised):
        if not re.fullmatch(r"[a-f0-9]{64}", requester) or len(advertised) > 2048: return []
        claims = advertised.split("|")
        if not 1 <= len(claims) <= 4 or len(set(claims)) != len(claims): return []
        rows = db_query_ro(DHT_DB_PATH, "SELECT address_type,address,port FROM nodes WHERE id=? LIMIT 4", (requester,), fetch_all=True)
        if not rows: return []
        approved = []
        for kind, address, port in rows:
            if kind not in ("ipv4", "ipv6") or type(port) is not int or not 1 <= port <= 65535: continue
            try:
                import ipaddress
                parsed = ipaddress.ip_address(address)
                if parsed.is_unspecified or parsed.is_multicast: continue
            except ValueError: continue
            short = f"{kind}:{address}"
            full = f"{requester}:{kind}:{address}:{port}"
            if short in claims or full in claims: approved.append(full)
        return approved

    def __init__(self, *args, **kwargs):
        # We detect if we are in public gateway mode by checking an environment variable.
        # 我们通过检查一个环境变量来判断是否处于公共网关模式。
        self.is_public_gateway = os.environ.get('CORIUM_PUBLIC_GATEWAY', 'false').lower() == 'true'
        super().__init__(*args, **kwargs)
    
    def _ipc_call(self, args, is_binary=False):
        try:
            result = subprocess.run([SCRIPT_PATH, '--quiet'] + args, capture_output=True, check=True, timeout=30)
            return result.stdout if is_binary else result.stdout.decode('utf-8').strip()
        except (subprocess.CalledProcessError, subprocess.TimeoutExpired) as e:
            stderr_output = e.stderr.decode('utf-8').strip() if hasattr(e, 'stderr') and e.stderr else str(e)
            bilingual_print(f"IPC call failed: {' '.join(args)} -> {stderr_output}", f"IPC调用失败: {' '.join(args)} -> {stderr_output}", "ERROR")
            return None

    def _direct_nns_resolve(self, domain_name):
        if FORUM_DB_PATH and os.path.isfile(FORUM_DB_PATH):
            try:
                row = db_query_ro(FORUM_DB_PATH, "SELECT target_hash FROM nns_records WHERE domain_name = ?", (domain_name,), fetch_one=True)
                if row and row[0]:
                    return row[0].strip()
            except Exception:
                pass
        return None

    def _resolve_nns(self, domain_name):
        now = time.time()
        with self._cache_lock:
            cached = self._nns_cache.get(domain_name)
            if cached and cached[1] > now:
                return cached[0]

        target_hash = self._direct_nns_resolve(domain_name)
        if not target_hash:
            target_hash = self._ipc_call(['_internal_nns_resolve', domain_name])

        if target_hash:
            with self._cache_lock:
                self._nns_cache[domain_name] = (target_hash, now + self.CACHE_TTL)
        return target_hash

    def _direct_get_bytes(self, object_hash):
        if not isinstance(object_hash, str) or not re.fullmatch(r'[a-f0-9]{64}', object_hash):
            return None
        if DHT_DB_PATH and os.path.isfile(DHT_DB_PATH):
            try:
                row = db_query_ro(DHT_DB_PATH, "SELECT file_path, offset, size FROM local_chunks WHERE hash=?", (object_hash,), fetch_one=True)
                if row:
                    filepath, offset, size = row
                    if os.path.isfile(filepath):
                        with open(filepath, 'rb') as f:
                            f.seek(offset)
                            data = f.read(size)
                            if len(data) == size:
                                return data
            except Exception:
                pass
        if DHT_DB_PATH:
            p2p_root = os.path.dirname(DHT_DB_PATH)
            for sub in ('objects', 'objects/transactions'):
                cand = os.path.join(p2p_root, sub, object_hash)
                if os.path.isfile(cand):
                    try:
                        with open(cand, 'rb') as f:
                            return f.read()
                    except Exception:
                        pass
        return None

    def _fetch_object_bytes(self, object_hash):
        data = self._direct_get_bytes(object_hash)
        if data is None:
            data = self._ipc_call(['_internal_p2p_get_bytes', object_hash], is_binary=True)
        return data

    def _get_manifest(self, root_hash):
        now = time.time()
        with self._cache_lock:
            cached = self._manifest_cache.get(root_hash)
            if cached and cached[1] > now:
                return cached[0]

        manifest_bytes = self._fetch_object_bytes(root_hash)
        if not manifest_bytes:
            return None

        try:
            manifest = json.loads(manifest_bytes.decode('utf-8'))
            if isinstance(manifest, dict) and "chunks" in manifest and "files" not in manifest and "gateway_app" not in manifest:
                chunks = manifest.get("chunks", [])
                full_bytes = b"".join(self._fetch_object_bytes(ch) or b"" for ch in chunks)
                manifest = json.loads(full_bytes.decode('utf-8'))
            with self._cache_lock:
                self._manifest_cache[root_hash] = (manifest, now + self.CACHE_TTL)
            return manifest
        except Exception:
            return None

    def _p2p_get_py(self, object_hash):
        temp_file_path = self._ipc_call(['_internal_p2p_get_to_temp', object_hash]) # This needs an implementation in Bash
        if temp_file_path and os.path.exists(temp_file_path):
            with open(temp_file_path, 'rb') as f: content = f.read()
            os.remove(temp_file_path)
            return content
        return None

    def get_peer_pubkey(self, peer_id):
        if not CRYPTOGRAPHY_AVAILABLE: return None
        pubkey_tuple = db_query_ro(BLOCKCHAIN_DB_PATH, "SELECT public_key FROM validators WHERE public_key_hash = ?", (peer_id,), fetch_one=True)
        if pubkey_tuple and pubkey_tuple[0]: return pubkey_tuple[0]
        miner_tuple = db_query_ro(BLOCKCHAIN_DB_PATH, "SELECT json_extract(w.proof, '$.miner_public_key') FROM blocks b JOIN block_work w ON b.hash = w.hash WHERE b.validator = ? LIMIT 1", (peer_id,), fetch_one=True)
        if miner_tuple and miner_tuple[0]: return miner_tuple[0]
        id_tuple = db_query_ro(BLOCKCHAIN_DB_PATH, "SELECT public_key FROM onchain_identities WHERE agent_id = ?", (peer_id,), fetch_one=True)
        if id_tuple and id_tuple[0]: return id_tuple[0]
        pubkey_bytes = self._p2p_get_py(peer_id)
        return pubkey_bytes.decode('utf-8') if pubkey_bytes else None

    def handle_dht_message(self, data):
        import subprocess
        if not isinstance(data, dict):
            return {"status": "error", "message": "Malformed request"}
        msg_type = data.get('type')
        payload = data.get('payload', '')
        sender_id = data.get('sender_id')
        signature_hex = data.get('signature')

        try:
            if isinstance(payload, str): payload.encode('utf-8', 'strict')
        except UnicodeError:
            return {"status": "error", "message": "Invalid UTF-8 payload"}

        # sender_id 在任何操作前都必须被检查
        # sender_id must be checked before any other operation
        if (not isinstance(sender_id, str) or len(sender_id) != 64
                or any(c not in '0123456789abcdef' for c in sender_id)
                or not isinstance(msg_type, str) or not isinstance(payload, str)
                or len(payload.encode('utf-8')) > 1048576):
            return {"status": "error", "message": "Malformed request: sender_id is missing"}

        if not all([msg_type, sender_id, signature_hex]):
            return {"status": "error", "message": "Malformed request"}
        if sender_id in os.environ.get('CORIUM_EXCLUDED_NODES','').split(','):
            return {"status":"error","message":"Node excluded by local policy"}

        sender_pubkey_str = data.get("public_key")
        if sender_pubkey_str is None: sender_pubkey_str = self.get_peer_pubkey(sender_id)
        if not isinstance(sender_pubkey_str, str): return {"status": "error", "message": "Invalid sender public key"}
        if not sender_pubkey_str: return {"status": "error", "message": f"Could not retrieve public key for sender {sender_id}"}
        
        if not verify_identity_signature("DHT", os.environ.get("CORIUM_NETWORK_ID", "mainnet"),
                                         sender_id, f"{msg_type}|{payload}".encode('utf-8'),
                                         signature_hex, sender_pubkey_str):
            return {"status": "error", "message": "Invalid signature"}

        # --- [全新] P2P 不信任与申诉权杖检查 (入站) v2.0 ---
        # --- [NEW] P2P Distrust & Grievance Token Check (Inbound) v2.0 ---
        my_id = get_our_node_id()
        distrust_info = db_query_ro(DHT_DB_PATH, "SELECT distrust_until, grievance_token_used FROM distrusted_peers WHERE blocker_id = ? AND blocked_id = ?", (my_id, sender_id), fetch_one=True)
        
        is_distrusted = False
        if distrust_info:
            distrust_until, token_used = distrust_info
            current_time = int(time.time())
            if distrust_until == 0 or current_time < distrust_until:
                is_distrusted = True
    
        # 检查消息是否为特殊的“申诉消息”
        # Check if the message is a special "grievance message"
        is_grievance_message = (msg_type == "GRIEVANCE_MESSAGE")
    
        if is_distrusted:
            if is_grievance_message and token_used == 0:
                # 场景 A: 对方被拉黑，但正在使用一个有效的申诉权杖
                # Scenario A: Peer is distrusted, but is using a valid Grievance Token
                bilingual_print(f"Accepting a high-priority Grievance Message from distrusted peer {sender_id[:12]}.",
                                f"正在接受来自不信任节点 {sender_id[:12]} 的一条高优先级申诉消息。", "WARN")
                
                # 在状态机中处理这条特殊消息
                # Process this special message in the state machine
                # (这需要一个新的内部 Bash 函数来写入消息到数据库)
                stored = self._ipc_call(['_internal_process_grievance_message', sender_id, payload])
                if stored is None: return {"status": "error", "message": "Grievance transaction failed"}
    
                # [关键] 标记权杖为已使用
                # [CRITICAL] Mark the token as used
                # 这是一个写操作，所以需要一个专用的IPC调用
                # Token consumption is part of the atomic grievance write.
    
                return {"status": "success", "message": "Grievance message acknowledged."}
            else:
                # 场景 B: 对方被拉黑，且没有有效的申诉权杖
                # Scenario B: Peer is distrusted and has no valid token to use
                bilingual_print(f"Ignoring message from distrusted peer {sender_id[:12]}.",
                                f"正在忽略来自不信任节点 {sender_id[:12]} 的消息。", "WARN")
                # [关键] 在错误响应中告知对方他被拉黑了
                # [CRITICAL] Inform the peer they have been blocked in the error response
                return {"status": "error", "message": "RECIPIENT_BLOCKED_SENDER"}
                
            # --- [新增逻辑结束] ---

        bilingual_print(f"Received valid DHT message: type={msg_type} from {sender_id[:12]}", f"收到来自 {sender_id[:12]} 的有效 DHT 消息: 类型={msg_type}", "DEBUG")
        
        if msg_type == "PING":
            return {"status": "success", "data": f"PONG:{get_our_node_id()}"}

        elif msg_type == "NOTIFY_NEW_MESSAGE":
            # 这是一个可选的优化。收到通知后，节点可以被触发去主动获取
            # 某个特定的交易，而无需等待下一次完整的同步。
            # This is an optional optimization. Upon receiving this, the node could be
            # triggered to fetch a specific transaction proactively, without waiting for the next full sync.
            bilingual_print(f"Received new message notification for tx {payload[:12]} from {sender_id[:12]}",
                            f"收到来自 {sender_id[:12]} 的关于交易 {payload[:12]} 的新消息通知", "DEBUG")
            return {"status": "success", "message": "Notification received"}
            
        elif msg_type == "ANNOUNCE_BLOCK":
            fields=payload.split('|')
            if len(fields)!=6: return {"status":"error","message":"Malformed block announcement"}
            digest,height,host,port,announcer,signature=fields
            if not re.fullmatch(r'[a-f0-9]{64}',digest) or not re.fullmatch(r'(0|[1-9][0-9]{0,9})',height) or announcer!=sender_id:
                return {"status":"error","message":"Invalid block announcement binding"}
            if not re.fullmatch(r'[1-9][0-9]{0,4}',port) or int(port)>65535:
                return {"status":"error","message":"Invalid announced port"}
            # The envelope key was already bound to sender_id and its signature
            # verified above. Announcers need no validator stake; the actual
            # native branch verifier below decides block/transaction admission.
            public_key=sender_pubkey_str
            if not public_key or not verify_identity_signature('ANNOUNCE_BLOCK',os.environ.get('CORIUM_NETWORK_ID','default'),sender_id,(digest+'|'+height).encode(),signature,public_key):
                return {"status":"error","message":"Invalid announcement signature"}
            known=db_query_ro(BLOCKCHAIN_DB_PATH,'SELECT height FROM blocks WHERE hash=?',(digest,),fetch_one=True)
            if known:
                return {"status":"success","data":"BLOCK_KNOWN"} if known[0]==int(height) else {"status":"error","message":"Announced height mismatch"}
            # Use the authenticated routing entry, never an unsolicited advertised address.
            peer=db_query_ro(DHT_DB_PATH,'SELECT address,port FROM nodes WHERE id=?',(sender_id,),fetch_one=True)
            if not peer or not peer[1]: return {"status":"error","message":"Announcer address unavailable"}
            proc=subprocess.Popen(['bash','-c','source "$1"; _blockchain_reorganize_to "$2" "$3" "$4"','corium-announcement',SCRIPT_PATH,digest,peer[0],str(peer[1])],stdout=subprocess.PIPE,stderr=subprocess.PIPE,start_new_session=True)
            try: output,errors=proc.communicate(timeout=90)
            except subprocess.TimeoutExpired:
                os.killpg(proc.pid,signal.SIGTERM)
                try: proc.communicate(timeout=10)
                except subprocess.TimeoutExpired: os.killpg(proc.pid,signal.SIGKILL);proc.communicate()
                return {"status":"error","message":"Announced chain validation timed out"}
            applied=db_query_ro(BLOCKCHAIN_DB_PATH,'SELECT height FROM blocks WHERE hash=?',(digest,),fetch_one=True)
            if proc.returncode or not applied or applied[0]!=int(height):
                return {"status":"error","message":"Announced chain rejected"}
            return {"status":"success","data":"BLOCK_ACCEPTED"}

        elif msg_type == "STORE":
            # Announcements are discovery hints, bound to the authenticated provider.
            # 公告仅为发现线索，提供者必须是已验证签名的发送者。
            fields = payload.split(' ')
            if len(fields)!=2 or not re.fullmatch(r'[a-f0-9]{64}',fields[0]) or fields[1]!=sender_id:
                return {"status":"error","message":"Invalid provider announcement"}
            query = """INSERT INTO chunks(hash,nodes,last_updated) VALUES (?,json_array(?),?)
                ON CONFLICT(hash) DO UPDATE SET nodes=(SELECT json_group_array(value) FROM
                    (SELECT value FROM json_each(chunks.nodes) UNION SELECT ? ORDER BY value)),
                    last_updated=excluded.last_updated"""
            with db_lock:
                if not ipc_write_to_db(DHT_DB_PATH,query,(fields[0],sender_id,int(time.time()),sender_id)):
                    return {"status":"error","message":"Provider persistence failed"}
            return {"status":"success","data":"STORED"}

        elif msg_type in ("FIND_NODE", "FIND_VALUE"):
            if not re.fullmatch(r'[a-f0-9]{64}', payload):
                return {"status": "error", "message": "Invalid lookup target"}
            nodes_raw = db_query_ro(DHT_DB_PATH, "SELECT id, address_type, address, port FROM nodes ORDER BY last_seen DESC,id LIMIT 1024;", fetch_all=True)
            if nodes_raw is None: return {"status": "error", "message": "Routing database unavailable"}
            nodes_raw = sorted((r for r in nodes_raw if re.fullmatch(r'[a-f0-9]{64}',r[0])),key=lambda r:(int(r[0],16)^int(payload,16),r[0],r[1],r[2]))[:10]
            nodes_list = [f"{r[0]}:{r[1]}:{r[2]}" + (f":{r[3]}" if r[3] else "") for r in nodes_raw]
            nodes_str = " ".join(nodes_list)
            
            if msg_type == "FIND_VALUE":
                local_info = db_query_ro(DHT_DB_PATH, "SELECT 1 FROM local_chunks WHERE hash = ?", (payload,), fetch_one=True)
                if local_info: return {"status": "success", "data": "FOUND_CHUNK"}
                announced = db_query_ro(DHT_DB_PATH,"SELECT N.id,N.address_type,N.address,N.port FROM chunks C JOIN json_each(C.nodes) P JOIN nodes N ON N.id=P.value WHERE C.hash=? ORDER BY N.id LIMIT 10",(payload,),fetch_all=True)
                if announced is None: return {"status":"error","message":"Provider database unavailable"}
                hints = [f"{r[0]}:{r[1]}:{r[2]}"+(f":{r[3]}" if r[3] else "") for r in announced if re.fullmatch(r'[a-f0-9]{64}',r[0])]
                nodes_str = " ".join(list(dict.fromkeys(hints+nodes_list))[:10])
            
            return {"status": "success", "data": f"NODES:{nodes_str}"}

        # Bounded punch workers only dial authenticated stored destinations.
        elif msg_type in ("PUNCH_HOLE_SIGNAL", "PUNCH_HOLE_EXECUTE"):
            try:
                if os.environ.get('CORIUM_ENABLE_HOLE_PUNCHING', 'false').lower() != 'true':
                    return {"status":"error","message":"Hole punching disabled"}
                if msg_type == "PUNCH_HOLE_SIGNAL":
                    target, requester, advertised = payload.split('|', 2)
                    if requester != sender_id or not re.fullmatch(r'[a-f0-9]{64}', target) or target == requester:
                        return {"status":"error","message":"Invalid punch identity"}
                    if not db_query_ro(DHT_DB_PATH, 'SELECT 1 FROM nodes WHERE id=?', (target,), fetch_one=True):
                        return {"status":"error","message":"Unknown punch target"}
                else:
                    requester, advertised = payload.split('|', 1)
                    if not db_query_ro(DHT_DB_PATH, 'SELECT 1 FROM nodes WHERE id=?', (sender_id,), fetch_one=True):
                        return {"status":"error","message":"Unknown punch relay"}
                addresses = self._punch_addresses(requester, advertised)
                if not addresses or not self._punch_admit(sender_id) or not self.punch_slots.acquire(False):
                    return {"status":"error","message":"Punch admission denied"}
                if msg_type == "PUNCH_HOLE_SIGNAL":
                    try:
                        result = self._ipc_call(['_internal_dht_send', target, 'PUNCH_HOLE_EXECUTE', requester+'|'+'|'.join(addresses)])
                        return {"status":"success","data":"SIGNAL_RELAYED"} if result is not None else {"status":"error","message":"Punch relay unavailable"}
                    finally: self.punch_slots.release()
                def execute():
                    try:
                        for address in addresses:
                            self._ipc_call(['_internal_dht_send_to_addr', address, 'PING', 'PUNCH_BACK'])
                    finally: self.punch_slots.release()
                try: threading.Thread(target=execute, daemon=True).start()
                except BaseException:
                    self.punch_slots.release(); raise
                return {"status":"success","data":"PUNCH_ATTEMPTED"}
            except (ValueError, TypeError):
                return {"status":"error","message":"Invalid punch payload"}

        # --- [已添加] 处理中继消息请求 ---
        elif msg_type == "RELAY_MESSAGE":
            try:
                relay_data = parse_protocol_json(payload)
                final_target = relay_data['final_target']
                inner_type = relay_data['inner_type']
                inner_payload = relay_data['inner_payload']
                bilingual_print(f"Relaying message of type '{inner_type}' to {final_target[:12]}", f"正在中继类型为 '{inner_type}' 的消息到 {final_target[:12]}", "INFO")
                
                # IPC调用返回的是最终目标的响应
                relayed_response = self._ipc_call(['_internal_dht_send', final_target, inner_type, inner_payload])
                
                return {"status": "success", "data": relayed_response} if relayed_response is not None else {"status": "error", "message": "Relay target unreachable"}
            except Exception as e:
                return {"status": "error", "message": "Invalid relay payload"}
                
        elif msg_type == "/pouw/validate-request":
            # payload 格式: JSON 字符串化的 uptime_proof
            # payload format: JSON-stringified uptime_proof
            try:
                proof = parse_protocol_json(payload)
                if (proof.get('node_id') != sender_id or type(proof.get('start_timestamp')) is not int
                        or type(proof.get('end_timestamp')) is not int
                        or not 0 <= proof['start_timestamp'] < proof['end_timestamp'] <= int(time.time())+300):
                    return {"status":"error","message":"Invalid uptime proof binding or interval"}
                proof_content=f"{sender_id}|{proof['start_timestamp']}|{proof['end_timestamp']}"
                if not verify_identity_signature("PoUW",os.environ.get("CORIUM_NETWORK_ID","default"),sender_id,proof_content.encode(),proof.get('signature'),sender_pubkey_str):
                    return {"status":"error","message":"Invalid uptime proof signature"}
                # ----------------------------------------------------------------------
                # --- 1. 生产级速率限制 (Production-Grade Rate Limiting) ---
                # ----------------------------------------------------------------------
                with db_lock:
                    # [MODIFICATION START] 从区块链数据库读取速率限制参数
                    # [MODIFICATION START] Read the rate limit parameter from the blockchain database
                    rate_limit_tuple = db_query_ro(BLOCKCHAIN_DB_PATH, "SELECT param_value FROM system_params WHERE param_key = 'pouw_validation_request_rate_limit_per_minute'", fetch_one=True)
                    
                    # 如果在数据库中找不到该参数，则使用一个安全的默认值
                    # Use a safe default value if the parameter is not found in the database
                    rate_limit = int(rate_limit_tuple[0]) if rate_limit_tuple else 5
                    bilingual_print(f"Applying PoUW rate limit of {rate_limit} req/min.", f"正在应用 PoUW 速率限制: {rate_limit} 次请求/分钟。", "DEBUG")
                    # [MODIFICATION END]

                    conn = sqlite3.connect(f"file:{DHT_DB_PATH}?mode=rw", uri=True)
                    cursor = conn.cursor()
                    
                    one_minute_ago = int(time.time()) - 60
                    cursor.execute("DELETE FROM pouw_rate_limit_log WHERE requester_id = ? AND timestamp < ?", (sender_id, one_minute_ago))
                    
                    cursor.execute("SELECT COUNT(*) FROM pouw_rate_limit_log WHERE requester_id = ?", (sender_id,))
                    request_count = cursor.fetchone()[0]
                    
                    # [MODIFICATION] 使用从数据库读取的变量进行比较
                    # [MODIFICATION] Use the variable read from the database for comparison
                    if request_count >= rate_limit:
                        conn.close()
                        bilingual_print(f"Rate limit exceeded for {sender_id[:12]}...", f"节点 {sender_id[:12]}... 的请求已超过速率限制。", "WARN")
                        return {"status": "error", "message": "Rate limit exceeded."}
                    
                    cursor.execute("INSERT INTO pouw_rate_limit_log (requester_id, timestamp) VALUES (?, ?)", (sender_id, int(time.time())))
                    conn.commit()
                    conn.close()

                # ----------------------------------------------------------------------
                # --- 2. 验证证明格式与签名 (Validate Proof Format & Signature) ---
                # ----------------------------------------------------------------------
                proof = parse_protocol_json(payload)
                data_to_verify = f"{proof['node_id']}|{proof['start_timestamp']}|{proof['end_timestamp']}"
                
                requester_pubkey_str = self.get_peer_pubkey(proof['node_id'])
                if not requester_pubkey_str:
                    return {"status": "error", "message": "Could not verify requester signature, public key unknown."}

                public_key = load_pem_public_key(requester_pubkey_str.encode('utf-8'))
                signature = bytes.fromhex(proof['signature'])
                public_key.verify(signature, data_to_verify.encode('utf-8'), ec.ECDSA(hashes.SHA256()))

                # ----------------------------------------------------------------------
                # --- 3. 检查自身状态 (Check Own State - Non-placeholder) ---
                # ----------------------------------------------------------------------
                # 检查我们是否认为该节点在过去24小时内处于活跃状态
                # Check if we consider this peer to be active in the last 24 hours
                last_active = db_query_ro(DHT_DB_PATH, "SELECT last_seen_active FROM peer_activity WHERE node_id = ?", (proof['node_id'],), fetch_one=True)
                
                is_peer_online = False
                if last_active and last_active[0]:
                    twenty_four_hours_ago = int(time.time()) - 86400
                    if last_active[0] > twenty_four_hours_ago:
                        is_peer_online = True

                if not is_peer_online:
                     bilingual_print(f"Validation rejected for {proof['node_id'][:12]}: Peer not considered recently active.",
                                     f"已拒绝为 {proof['node_id'][:12]} 的验证请求：该节点近期不活跃。", "WARN")
                     return {"status": "error", "message": "Node is not considered recently active by this validator."}

                # ----------------------------------------------------------------------
                # --- 4. 签署证明哈希 (Sign the Proof Hash) ---
                # ----------------------------------------------------------------------
                proof_hash = calculate_hash(payload)
                my_id = get_our_node_id()

                # 调用 Bash 核心进行签名
                # Call the Bash core to perform the signature
                # 我们使用一个新的、专用的内部命令 _internal_sign_data_raw
                # We use a new, dedicated internal command _internal_sign_data_raw
                validation_signature = self._ipc_call(['_internal_sign_data_raw', proof_hash])

                if validation_signature:
                    return {"status": "success", "data": json.dumps({
                        "validator_id": my_id,
                        "signature": validation_signature
                    })}
                else:
                    return {"status": "error", "message": "Internal signing error occurred on validator node."}

            except Exception as e:
                import traceback
                bilingual_print(f"PoUW validation failed with exception: {e}\n{traceback.format_exc()}",
                                f"PoUW 验证因异常失败: {e}\n{traceback.format_exc()}", "ERROR")
                return {"status": "error", "message": f"Validation failed due to an internal error: {str(e)}"}
        
        # --- [V95 Phoenix Protocol] 紧急协议消息处理 ---
        # --- [V95 Phoenix Protocol] Emergency Protocol Message Handling ---
        elif msg_type == "CBB_POST":
            try:
                data = parse_protocol_json(payload)
                author_id, raw_ts, message, sig = data['author_id'], data['timestamp'], data['message'], data['signature']
                if (isinstance(raw_ts, bool) or not isinstance(raw_ts, (int, str))
                        or not str(raw_ts).isascii() or not str(raw_ts).isdigit()
                        or not isinstance(message, str) or not message
                        or '\x00' in message or len(message.encode('utf-8')) > 65536):
                    return {"status": "error", "message": "Malformed CBB fields"}
                ts = int(raw_ts)
                
                author_pubkey_str = self.get_peer_pubkey(author_id)
                if not author_pubkey_str: return {"status": "error", "message": "Unknown author public key"}
                
                network_id = os.environ.get("CORIUM_NETWORK_ID", "mainnet")
                canonical_str = f"CORIUM-CBB-V1\n{network_id}\n{author_id}\n{ts}\n{message}"
                if not verify_identity_signature("CBB", network_id, author_id, canonical_str.encode('utf-8'), sig, author_pubkey_str):
                    return {"status": "error", "message": "Invalid CBB signature"}
                
                if ts > time.time() + 300 or ts <= int(time.time()) - 86400: return {"status": "error", "message": "Message timestamp out of allowed window"}

                expires_at = ts + 86400
                msg_hash = calculate_hash(canonical_str)
                
                if ipc_write_to_db(FORUM_DB_PATH, 
                    "INSERT OR IGNORE INTO cbb_messages (msg_hash, author_id, timestamp, message, signature, expires_at) VALUES (?, ?, ?, ?, ?, ?)",
                    [msg_hash, author_id, ts, message, sig, expires_at]):
                    return {"status": "success", "data": "CBB_MSG_ACK"}
                else:
                    return {"status": "error", "message": "Failed to write CBB message to DB"}
            except Exception as e:
                return {"status": "error", "message": f"Invalid CBB_POST payload: {e}"}

        elif msg_type == "CBB_SYNC_REQUEST":
            try:
                now = int(time.time())
                messages = db_query_ro(FORUM_DB_PATH, "SELECT msg_hash,author_id,timestamp,message,signature,expires_at FROM cbb_messages WHERE expires_at>? ORDER BY timestamp,msg_hash", (now,), fetch_all=True)
                if messages is None: raise ValueError("CBB database unavailable")
                messages_list = []
                network_id = os.environ.get("CORIUM_NETWORK_ID", "default")
                for msg_hash,author,ts,text,sig,expires in messages:
                    if type(ts) is not int or not now-86400<ts<=now+300 or expires!=ts+86400 or not isinstance(text,str) or not text or '\x00' in text or len(text.encode('utf-8'))>65536:
                        raise ValueError("Corrupted cached CBB fields")
                    canonical = f"CORIUM-CBB-V1\n{network_id}\n{author}\n{ts}\n{text}"
                    public_key = sender_pubkey_str if author==sender_id else self.get_peer_pubkey(author)
                    if calculate_hash(canonical)!=msg_hash or not public_key or not verify_identity_signature("CBB",network_id,author,canonical.encode(),sig,public_key):
                        raise ValueError("Corrupted cached CBB signature")
                    messages_list.append({"author_id":author,"timestamp":ts,"message":text,"signature":sig})
                return {"status":"success","data":json.dumps(messages_list,ensure_ascii=False)}
            except Exception as e:
                return {"status": "error", "message": f"CBB sync failed: {e}"}

        elif msg_type == "ANNOUNCE_SSPO":
            try:
                sspo = parse_protocol_json(payload)
                author_id, raw_height, raw_ts, sig = sspo['author_id'], sspo['target_block_height'], sspo['timestamp'], sspo['signature']
                if (type(raw_height) is not int or raw_height < 0 or raw_height > 9223372036854775807
                        or type(raw_ts) is not int or raw_ts > time.time() + 300
                        or raw_ts <= time.time() - 604800):
                    return {"status": "error", "message": "Invalid SSPO height or timestamp"}
                height, ts = raw_height, raw_ts
                target_hash = sspo['target_block_hash']
                if (not isinstance(target_hash, str) or len(target_hash) != 64
                        or any(c not in '0123456789abcdef' for c in target_hash)):
                    return {"status": "error", "message": "Invalid SSPO block hash"}
                local_target = db_query_ro(BLOCKCHAIN_DB_PATH, "SELECT hash FROM blocks WHERE height = ?", (height,), fetch_one=True)
                if local_target and local_target[0] != target_hash:
                    return {"status": "error", "message": "SSPO contradicts local canonical history"}
                author_pubkey_str = self.get_peer_pubkey(author_id)
                if not author_pubkey_str: return {"status": "error", "message": "Unknown author public key"}
                network_id = os.environ.get("CORIUM_NETWORK_ID", "mainnet")
                canonical_str = f"CORIUM-EXODUS-SSPO-V1\n{network_id}\n{author_id}\n{height}\n{target_hash}\n{ts}"
                if not verify_identity_signature("SSPO", network_id, author_id, canonical_str.encode('utf-8'), sig, author_pubkey_str):
                    return {"status": "error", "message": "Invalid SSPO signature"}
                
                proposal_hash = calculate_hash(canonical_str)
                expires_at = ts + 604800 # 7 days
                if ipc_write_to_db(FORUM_DB_PATH,
                    "INSERT OR IGNORE INTO exodus_proposals (proposal_hash, author_id, target_block_height, target_block_hash, timestamp, full_proposal_object, expires_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
                    [proposal_hash, author_id, height, target_hash, ts, payload, expires_at]):
                    return {"status": "success", "data": "SSPO_ACK"}
                else:
                    return {"status": "error", "message": "Failed to write SSPO to DB"}
            except Exception as e:
                return {"status": "error", "message": f"Invalid ANNOUNCE_SSPO payload: {e}"}

        elif msg_type == "ANNOUNCE_SNSO":
            try:
                snso = parse_protocol_json(payload)
                proposal_hash, notary_id, sig = snso['proposal_hash'], snso['notary_id'], snso['signature']
                
                notary_pubkey_str = self.get_peer_pubkey(notary_id)
                if not notary_pubkey_str: return {"status": "error", "message": "Unknown notary public key"}
                network_id = os.environ.get("CORIUM_NETWORK_ID", "mainnet")
                canonical_str = f"CORIUM-EXODUS-SNSO-V1\n{network_id}\n{proposal_hash}\n{notary_id}"
                if not verify_identity_signature("SNSO", network_id, notary_id, canonical_str.encode('utf-8'), sig, notary_pubkey_str):
                    return {"status": "error", "message": "Invalid SNSO signature"}
                
                proposal = db_query_ro(FORUM_DB_PATH, "SELECT 1 FROM exodus_proposals WHERE proposal_hash = ? AND expires_at > ?", (proposal_hash, int(time.time())), fetch_one=True)
                if not proposal: return {"status": "error", "message": "Proposal not found or expired"}

                if ipc_write_to_db(FORUM_DB_PATH,
                    "INSERT OR IGNORE INTO exodus_notarizations (proposal_hash, notary_id, signature, full_notarization_object) VALUES (?, ?, ?, ?)",
                    [proposal_hash, notary_id, sig, payload]):
                    return {"status": "success", "data": "SNSO_ACK"}
                else:
                    return {"status": "error", "message": "Failed to write SNSO to DB"}
            except Exception as e:
                return {"status": "error", "message": f"Invalid ANNOUNCE_SNSO payload: {e}"}

        elif msg_type == "GET_NOTARIZATIONS":
            try:
                proposal_hash = payload
                if not isinstance(proposal_hash,str) or not re.fullmatch(r'[a-f0-9]{64}',proposal_hash): raise ValueError('Invalid proposal hash')
                notarizations = db_query_ro(FORUM_DB_PATH, "SELECT notary_id,signature,full_notarization_object FROM exodus_notarizations WHERE proposal_hash = ? ORDER BY notary_id", (proposal_hash,), fetch_all=True)
                if notarizations is None: raise ValueError('Notarization database unavailable')
                notarization_objects = []
                network_id = os.environ.get("CORIUM_NETWORK_ID", "default")
                for notary,sig,stored in notarizations:
                    obj=parse_protocol_json(stored)
                    if obj.get('proposal_hash')!=proposal_hash or obj.get('notary_id')!=notary or obj.get('signature')!=sig: raise ValueError('Corrupted cached notarization')
                    key=self.get_peer_pubkey(notary)
                    canonical=f"CORIUM-EXODUS-SNSO-V1\n{network_id}\n{proposal_hash}\n{notary}"
                    if not key or not verify_identity_signature("SNSO",network_id,notary,canonical.encode('utf-8'),sig,key): raise ValueError('Invalid cached notarization signature')
                    notarization_objects.append(obj)
                return {"status": "success", "data": json.dumps(notarization_objects)}
            except Exception as e:
                return {"status": "error", "message": f"GET_NOTARIZATIONS failed: {e}"}

        elif msg_type == "AGENT_EMERGENCY_TASK":
            try:
                task = parse_protocol_json(payload)
                target_agent, task_payload, proposer, sig = task['target_agent_id'], task['task_payload'], task['proposer_id'], task['signature']
                if proposer != sender_id or not re.fullmatch(r'[a-f0-9]{64}', target_agent):
                    return {"status": "error", "message": "Invalid emergency task identity"}
                signed_task = {k: task[k] for k in ('type','target_agent_id','task_payload','proposer_id')}
                if signed_task['type'] != 'AGENT_EMERGENCY_TASK' or not isinstance(task_payload, dict):
                    return {"status": "error", "message": "Malformed emergency task"}
                canonical = json.dumps(signed_task, sort_keys=True, ensure_ascii=False, separators=(',', ':'))
                public_key = self.get_peer_pubkey(proposer)
                if not public_key or not verify_identity_signature("AGENT_EMERGENCY_TASK", os.environ.get("CORIUM_NETWORK_ID", "default"), proposer, canonical.encode("utf-8"), sig, public_key):
                    return {"status": "error", "message": "Invalid emergency task signature"}
                known_agent = db_query_ro(BLOCKCHAIN_DB_PATH, "SELECT 1 FROM onchain_identities WHERE agent_id=?", (target_agent,), fetch_one=True)
                if not known_agent:
                    return {"status": "error", "message": "Unknown emergency agent"}
                task_hash = calculate_hash(canonical)
                expires_at = int(time.time()) + 86400 # 任务有效期 24 小时
                
                if ipc_write_to_db(FORUM_DB_PATH,
                    "INSERT OR IGNORE INTO agent_emergency_queue (task_hash, target_agent_id, task_payload, proposer_id, proposer_signature, submitted_at, expires_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
                    [task_hash, target_agent, json.dumps(task_payload), proposer, sig, int(time.time()), expires_at]):
                    return {"status": "success", "data": "AGENT_TASK_QUEUED"}
                else:
                    return {"status": "error", "message": "Failed to queue agent task"}
            except Exception as e:
                return {"status": "error", "message": f"Invalid AGENT_EMERGENCY_TASK payload: {e}"}

        elif msg_type == "AGENT_REGULAR_CALL":
            try:
                call_data = parse_protocol_json(payload)
                target_agent_id = call_data['target_agent_id']
                
                # Check supervisor for agent status
                import subprocess
                try:
                    result = subprocess.run(
                        [SCRIPT_PATH, '--quiet', '_internal_ipc_call_supervisor', 'get_service_status', '[]'],
                        capture_output=True, text=True, check=True, timeout=15
                    )
                    status_json_str = result.stdout.strip()
                    services_status = json.loads(status_json_str)
                    agent_status = services_status.get(target_agent_id)
                except Exception as e:
                    return {"status": "error", "message": f"Supervisor IPC failed: {e}"}

                if not agent_status or agent_status.get('status') != 'running':
                    return {"status": "error", "message": f"Agent {target_agent_id} is not running"}

                port_file = agent_status.get('port_file')
                if not port_file or not os.path.exists(port_file):
                    return {"status": "error", "message": f"Agent {target_agent_id} port file missing"}

                with open(port_file, 'r') as f:
                    agent_port = int(f.read().strip())

                import http.client
                conn = http.client.HTTPConnection('127.0.0.1', agent_port, timeout=30)
                conn.request("POST", f"/api/agent/{target_agent_id}/call", body=payload, headers={"Content-Type": "application/json"})
                resp = conn.getresponse()
                resp_data = resp.read().decode('utf-8')
                conn.close()

                return {"status": "success", "data": resp_data}

            except Exception as e:
                return {"status": "error", "message": f"AGENT_REGULAR_CALL failed: {e}"}
                
        elif msg_type == "GET_CHAIN_STATE":
            # [V105.4 SYNC LOGIC] Handle requests for the current chain state.
            # This is used by peers to find the heaviest chain tip.
            # [V105.4 同步逻辑] 处理对当前链状态的请求。
            # 对等节点使用此消息来找到最重链的链顶。
            try:
                chain_tip_info = db_query_ro(
                    BLOCKCHAIN_DB_PATH, 
                    "SELECT hash, height, total_weight FROM blocks ORDER BY total_weight DESC, height DESC LIMIT 1;", 
                    fetch_one=True
                )
                if chain_tip_info:
                    response_data = f"{chain_tip_info[0]}|{chain_tip_info[1]}|{chain_tip_info[2]}"
                    return {"status": "success", "data": response_data}
                else:
                    return {"status": "error", "message": "No blocks found in chain."}
            except Exception as e:
                return {"status": "error", "message": f"Database error while fetching chain state: {e}"}

        elif msg_type == "GET_BLOCK_HASH_AT_HEIGHT":
            # [V105.5 SECURITY] Handle requests for a block hash at a specific height.
            # This is essential for the Weak Subjectivity Checkpoint verification.
            # [V105.5 安全] 处理对特定高度区块哈希的请求。
            # 这对于弱主观性检查点的验证至关重要。
            try:
                height = int(payload)
                block_hash_tuple = db_query_ro(
                    BLOCKCHAIN_DB_PATH,
                    "SELECT hash FROM blocks WHERE height = ?;",
                    (height,),
                    fetch_one=True
                )
                if block_hash_tuple:
                    return {"status": "success", "data": block_hash_tuple[0]}
                else:
                    return {"status": "error", "message": "Block not found at that height."}
            except (ValueError, TypeError):
                return {"status": "error", "message": "Invalid height provided."}
                
        elif msg_type == "GET_BLOCK_HEADER":
            if not re.fullmatch(r'[a-f0-9]{64}', payload):
                return {"status": "error", "message": "Invalid block hash"}
            header = db_query_ro(BLOCKCHAIN_DB_PATH, "SELECT height,previous_hash,timestamp FROM blocks WHERE hash=?", (payload,), fetch_one=True)
            if header is None: return {"status": "error", "message": "Block header unavailable"}
            return {"status": "success", "data": f"HEADER:{header[0]}|{header[1]}|{header[2]}"}

        elif msg_type == "GET_FULL_BLOCK":
            try:
                block_hash = payload
                block_data = db_query_ro(BLOCKCHAIN_DB_PATH, "SELECT height, previous_hash, timestamp, validator, signature, transactions FROM blocks WHERE hash = ?;", (block_hash,), fetch_one=True)
                if block_data:
                    native_block={
                        "height": block_data[0], "previous_hash": block_data[1],
                        "timestamp": block_data[2], "validator": block_data[3],
                        "signature": block_data[4], "transactions": json.loads(block_data[5])}
                    has_work=db_query_ro(BLOCKCHAIN_DB_PATH,"SELECT 1 FROM sqlite_master WHERE type='table' AND name='block_work'",(),fetch_one=True)
                    proof=db_query_ro(BLOCKCHAIN_DB_PATH,"SELECT proof FROM block_work WHERE hash=?",(block_hash,),fetch_one=True) if has_work else None
                    if proof: native_block['work']=json.loads(proof[0])
                    return {"status": "success", "data": "BLOCK:" + json.dumps(native_block,ensure_ascii=False,separators=(',',':'))}
                else:
                    return {"status": "error", "message": "Block not found."}
            except Exception as e:
                return {"status": "error", "message": f"Database error while fetching block: {e}"}

        elif msg_type == "GET_TRANSACTION":
            try:
                tx_hash = payload
                tx_row = db_query_ro(BLOCKCHAIN_DB_PATH, "SELECT type, data, public_key, signature, timestamp FROM transactions WHERE hash = ?;", (tx_hash,), fetch_one=True)
                if tx_row:
                    tx_obj = {
                        "type": tx_row[0],
                        "data": json.loads(tx_row[1]),
                        "public_key": tx_row[2],
                        "signature": tx_row[3],
                        "timestamp": tx_row[4]
                    }
                    return {"status": "success", "data": json.dumps(tx_obj)}
                else:
                    return {"status": "error", "message": "Transaction not found."}
            except Exception as e:
                return {"status": "error", "message": f"Database error while fetching transaction: {e}"}

        else:
            return {"status": "error", "message": "Unknown message type after verification"}

    def do_POST(self):    
        # For a public-facing, read-only gateway, we disable ALL POST requests.
        # 对于面向公众的只读网关，我们禁用所有的 POST 请求。
        if self.is_public_gateway:
            self.send_error(405, "Method Not Allowed", "This is a read-only public gateway.")
            bilingual_print(f"SECURITY ALERT: Blocked POST request to public gateway from {self.client_address[0]}.",
                            f"安全警报: 已阻止来自 {self.client_address[0]} 对公共网关的 POST 请求。", "WARN")
            return
            
        if self.path == "/dht":
            try:
                lengths = self.headers.get_all('Content-Length', [])
                if len(lengths) != 1 or not lengths[0].isascii() or not lengths[0].isdigit():
                    self.send_error(400, "Invalid Content-Length"); return
                content_length = int(lengths[0])
                if not 0 < content_length <= 2097152 or self.headers.get('Transfer-Encoding'):
                    self.send_error(413, "Invalid request framing or size"); return
                self.connection.settimeout(10)
                post_data = self.rfile.read(content_length).decode('utf-8')
                data = parse_protocol_json(post_data)
                response_data = self.handle_dht_message(data)
                self.send_response(200)
                response_bytes = json.dumps(response_data).encode('utf-8')
                self.send_header('Content-type', 'application/json')
                self.send_header('Content-Length', str(len(response_bytes)))
                self.end_headers()
                self.wfile.write(response_bytes)
            except (ValueError, UnicodeError, TimeoutError): self.send_error(400, "Malformed request")
            except Exception: self.send_error(500, "Internal Server Error")
        else: self.send_error(404, "Not Found")

    def do_GET(self):    
        parsed_path = urlparse(self.path)
        if parsed_path.path.startswith('/chunk/'):
            digest=parsed_path.path.removeprefix('/chunk/')
            if not re.fullmatch(r'[a-f0-9]{64}',digest): self.send_error(400,'Invalid object hash'); return
            row=db_query_ro(DHT_DB_PATH,'SELECT file_path,offset,size FROM local_chunks WHERE hash=?',(digest,),fetch_one=True)
            if not row: self.send_error(404,'Object not available'); return
            try:
                filename,offset,size=row
                if type(offset) is not int or type(size) is not int or offset<0 or size<0: raise ValueError('Invalid object range')
                with open(filename,'rb') as source:
                    if offset+size>os.fstat(source.fileno()).st_size: raise ValueError('Truncated local object')
                    source.seek(offset);remaining=size;hasher=hashlib.sha256()
                    while remaining:
                        data=source.read(min(65536,remaining))
                        if not data: raise ValueError('Truncated local object')
                        hasher.update(data);remaining-=len(data)
                    if hasher.hexdigest()!=digest:
                        if size>2097152 or offset!=0 or size!=os.fstat(source.fileno()).st_size or not verify_object_file(filename,digest,BLOCKCHAIN_DB_PATH):
                            raise ValueError('Corrupted local object')
                    start,end=0,size-1;range_header=self.headers.get('Range')
                    if range_header:
                        match=re.fullmatch(r'bytes=([0-9]{0,20})-([0-9]{0,20})',range_header)
                        if not match or not any(match.groups()): self.send_response(416);self.send_header('Content-Range',f'bytes */{size}');self.send_header('Content-Length','0');self.end_headers();return
                        left,right=match.groups()
                        if left:
                            start=int(left);end=min(int(right),size-1) if right else size-1
                        else:
                            count=int(right);start=max(0,size-count)
                            if count==0: self.send_response(416);self.send_header('Content-Range',f'bytes */{size}');self.send_header('Content-Length','0');self.end_headers();return
                        if start>=size or start>end: self.send_response(416);self.send_header('Content-Range',f'bytes */{size}');self.send_header('Content-Length','0');self.end_headers();return
                    self.send_response(206 if range_header else 200)
                    self.send_header('Content-Type','application/octet-stream')
                    self.send_header('Accept-Ranges','bytes')
                    self.send_header('Content-Length',str(max(0,end-start+1)))
                    if range_header: self.send_header('Content-Range',f'bytes {start}-{end}/{size}')
                    self.end_headers();source.seek(offset+start);remaining=max(0,end-start+1)
                    while remaining:
                        data=source.read(min(65536,remaining))
                        if not data: raise ValueError('Truncated object')
                        self.wfile.write(data);remaining-=len(data)
            except (BrokenPipeError,ConnectionResetError): return
            except Exception as exc:
                bilingual_print(f'Object retrieval failed: {exc}',f'对象读取失败: {exc}','ERROR')
                self.send_error(500,'Object retrieval failed')
            return
        if self.is_public_gateway and parsed_path.path.startswith('/app/'):
            self.send_error(403, "Forbidden", "DApp execution is disabled on public gateways for security reasons.")
            bilingual_print(f"SECURITY ALERT: Blocked DApp execution request to public gateway from {self.client_address[0]}.",
                            f"安全警报: 已阻止来自 {self.client_address[0]} 对公共网关的 DApp 执行请求。", "WARN")
            return
            
        parsed_path = urlparse(self.path)
        if parsed_path.path in ('', '/'):
            self.send_response(302)
            self.send_header('Location', '/app/explorer')
            self.end_headers()
            return

        path_parts = parsed_path.path.strip('/').split('/')
        if not path_parts or len(path_parts) < 2:
            self.send_error(404, "Not Found: Invalid path")
            return

        request_type, domain_name = path_parts[0], path_parts[1]
        if request_type == "nns":
            self.handle_static_site(domain_name, path_parts[2:])
        elif request_type == "app":
            self.handle_gateway_app(domain_name, path_parts[2:], parse_qs(parsed_path.query))
        else:
            self.send_error(404, f"Unknown request type: {request_type}")

    def handle_static_site(self, domain_name, file_path_parts):
        root_hash = self._resolve_nns(domain_name)
        if not root_hash:
            self.send_error(404, "Domain Not Found")
            return

        try:
            manifest = _cs_json.loads(cs_content(root_hash, self._fetch_object_bytes))
            file_path, file_hash, status = cs_resolve(manifest, '/'.join(file_path_parts))
            file_content = cs_content(file_hash, self._fetch_object_bytes)
            headers = cs_headers(file_path, file_content, wasm=manifest.get('static_wasm') is True)
        except FileNotFoundError:
            self.send_error(404, "Static File Not Found")
            return
        except (ValueError, TypeError, UnicodeError, KeyError):
            self.send_error(502, "Static Content Integrity Or Policy Rejected")
            return
        self.send_response(status)
        for name, value in headers.items(): self.send_header(name, value)
        self.send_header('Content-Length', str(len(file_content)))
        self.end_headers()
        self.wfile.write(file_content)

    # --- [完整重写] handle_gateway_app (现在是路由分发器) ---
    # --- [COMPLETE REWRITE] handle_gateway_app (Now a Routing Dispatcher) ---
    def handle_gateway_app(self, domain_name, path_parts, query_params):
        """
        Handles requests for DApps. It now acts as a dispatcher, routing requests
        to either the built-in RestrictedPython engine or a custom dapp_engine mod.
        处理对 DApp 的请求。它现在作为一个分发器，将请求路由到
        内置的 RestrictedPython 引擎或一个自定义的 dapp_engine 模组。
        """
        if any(key in query_params for key in ('topic', 'reply_to', 'content')) and (domain_name == 'forum' or 'forum' in path_parts):
            self.send_error(405, "Forum writes require POST /api/gateway/forum and explicit authentication")
            return
        # --- 步骤 1: 获取 DApp 清单 / Step 1: Fetch the DApp Manifest ---
        root_hash = self._resolve_nns(domain_name)
        if not root_hash:
            self.send_error(404, "Domain Not Found")
            return
        
        manifest = self._get_manifest(root_hash)
        if not manifest or not isinstance(manifest, dict):
            self.send_error(500, "Manifest Error", "Could not fetch DApp manifest from P2P network.")
            return

        try:
            gateway_app_config = manifest.get('gateway_app', {})
            # [关键] 检查 'engine' 字段
            # [CRITICAL] Check for the 'engine' field
            engine_pkg_id = gateway_app_config.get('engine', 'built-in')
        except (json.JSONDecodeError, KeyError, Exception):
            self.send_error(500, "Manifest Error", "DApp manifest is malformed.")
            return

        # --- 步骤 2: 路由决策 / Step 2: Routing Decision ---
        if engine_pkg_id == 'built-in':
            # --- 分支 A: 使用内置的 RestrictedPython 引擎 (向后兼容) ---
            # --- Branch A: Use the built-in RestrictedPython engine (backward compatibility) ---
            bilingual_print(f"Routing DApp '{domain_name}' to built-in RestrictedPython engine.",
                            f"正在将 DApp '{domain_name}' 路由至内置的 RestrictedPython 引擎。", "DEBUG")
            self._execute_with_builtin_engine(gateway_app_config, path_parts, query_params, domain_name)
        else:
            # --- 分支 B: 代理到自定义的 dapp_engine 模组 ---
            # --- Branch B: Proxy to a custom dapp_engine mod ---
            bilingual_print(f"Routing DApp '{domain_name}' to custom engine: {engine_pkg_id}",
                            f"正在将 DApp '{domain_name}' 路由至自定义引擎: {engine_pkg_id}", "INFO")
            self._proxy_to_custom_engine(engine_pkg_id)
            
    def _execute_with_builtin_engine(self, gateway_app_config, path_parts, query_params, domain_name=""):
        """
        The new logic for running DApps using both Language and OS Sandboxing.
        使用语言级 (RestrictedPython) + 操作系统级 (bwrap) 运行 DApp 的新逻辑。
        """
        try:
            app_hash = gateway_app_config['entrypoint']
        except KeyError:
            self.send_error(500, "Manifest Error", "Manifest for built-in DApp is missing 'entrypoint'.")
            return

        try:
            # We call our new bash internal command that runs bwrap
            import subprocess
            import http.cookies
            cookie=http.cookies.SimpleCookie()
            try: cookie.load(self.headers.get('Cookie',''))
            except http.cookies.CookieError: pass
            preference=query_params.get('lang',[None])[0] or (cookie['ziokt_lang'].value if 'ziokt_lang' in cookie else None) or self.headers.get('Accept-Language','en-US').split(',')[0].split(';')[0]
            locale='zh-CN' if preference.lower().startswith('zh') else 'en-US'
            req_data = {'path': path_parts, 'query': query_params, 'app_id': domain_name, 'locale':locale}
            result = subprocess.run(
                [SCRIPT_PATH, '--quiet', '_internal_run_dapp_sandboxed', app_hash, json.dumps(req_data), domain_name],
                capture_output=True, text=True, timeout=10
            )
            if result.returncode != 0:
                self.send_error(500, "Application Execution Error", f"Sandbox returned {result.returncode}: {result.stderr}")
                return
            response_html = result.stdout
        except Exception as e:
            self.send_error(500, "Application Execution Error", str(e)); return

        self.send_response(200)
        self.send_header('Content-type', 'text/html; charset=utf-8')
        self.end_headers()
        self.wfile.write(response_html.encode('utf-8'))
    
    # --- [V84.1 新增] Python 侧的 IPC 桥梁辅助函数 ---
    # --- [V84.1 NEW] Python-side IPC bridge helper function ---
    def _ipc_call_supervisor(self, method, params_json="[]"):
        """
        Calls the Supervisor's API via the main Bash script's internal command.
        通过主 Bash 脚本的内部命令，调用 Supervisor 的 API。
        
        :param method: The API method to call (e.g., "get_service_status").
                       要调用的 API 方法 (例如 "get_service_status")。
        :param params_json: A JSON string representing the parameters array.
                            代表参数数组的 JSON 字符串。
        :return: The 'data' field from the Supervisor's response as a string, or None on failure.
                 以字符串形式返回 Supervisor 响应中的 'data' 字段，如果失败则返回 None。
        """
        try:
            # We call our new internal command _internal_ipc_call_supervisor
            # 我们调用我们新的内部命令 _internal_ipc_call_supervisor
            result = subprocess.run(
                [SCRIPT_PATH, '--quiet', '_internal_ipc_call_supervisor', method, params_json],
                capture_output=True, text=True, check=True, timeout=15
            )
            # The bash function already extracts the 'data' field, so we return the raw stdout
            # bash 函数已经提取了 'data' 字段，所以我们直接返回原始的标准输出
            return result.stdout.strip()
        except (subprocess.CalledProcessError, subprocess.TimeoutExpired) as e:
            stderr_output = e.stderr.strip() if hasattr(e, 'stderr') and e.stderr else str(e)
            bilingual_print(f"IPC call to Supervisor failed: {method} -> {stderr_output}",
                            f"对 Supervisor 的 IPC 调用失败: {method} -> {stderr_output}", "ERROR")
            return None

    # --- [V84.1 完整重写] _proxy_to_custom_engine (使用新的 IPC 桥梁) ---
    # --- [V84.1 COMPLETE REWRITE] _proxy_to_custom_engine (using the new IPC bridge) ---
    def _proxy_to_custom_engine(self, engine_pkg_id):
        """
        Finds the running dapp_engine mod, gets its port, and reverse-proxies the request to it.
        查找正在运行的 dapp_engine 模组，获取其端口，并将请求反向代理过去。
        """
        # --- Step 2.1: Get engine info from the Supervisor via our new IPC bridge ---
        # --- 步骤 2.1: 通过我们新的 IPC 桥梁，从 Supervisor 获取引擎信息 ---
        bilingual_print(f"Querying Supervisor for engine '{engine_pkg_id}'...",
                        f"正在向 Supervisor 查询引擎 '{engine_pkg_id}' 的信息...", "DEBUG")
        
        status_json_str = self._ipc_call_supervisor('get_service_status', '[]')
        if not status_json_str:
            self.send_error(503, "Service Unavailable", f"Could not communicate with Supervisor to find engine '{engine_pkg_id}'.")
            return

        try:
            all_statuses = json.loads(status_json_str)
            engine_status = all_statuses.get(engine_pkg_id)

            if not engine_status or engine_status.get('status') != 'running':
                # [关键] 如果服务未运行，尝试启动它！
                # [CRITICAL] If the service is not running, try to start it!
                bilingual_print(f"Engine '{engine_pkg_id}' is not running. Requesting Supervisor to start it...",
                                f"引擎 '{engine_pkg_id}' 未在运行。正在请求 Supervisor 启动它...", "INFO")
                
                start_params_json = f'["start", "{engine_pkg_id}"]'
                start_result_str = self._ipc_call_supervisor('control_service', start_params_json)

                if not start_result_str or "error" in start_result_str:
                    self.send_error(503, "Service Unavailable", f"Engine '{engine_pkg_id}' is not running and failed to start.")
                    return
                
                # Re-fetch status after a short delay to allow the engine to start
                # 短暂延迟后重新获取状态，以允许引擎启动
                time.sleep(2) 
                status_json_str = self._ipc_call_supervisor('get_service_status', '[]')
                engine_status = json.loads(status_json_str).get(engine_pkg_id)

            engine_port_file = engine_status.get('port_file') # <-- [重要] 我们从 Supervisor 获取的是 port_file 的路径
            if not engine_port_file or not os.path.exists(engine_port_file):
                self.send_error(503, "Service Unavailable", f"Engine '{engine_pkg_id}' is running but did not report a listening port file.")
                return

            with open(engine_port_file, 'r') as f:
                engine_port = int(f.read().strip())

        except (json.JSONDecodeError, KeyError, ValueError, IOError) as e:
            self.send_error(500, "Internal Server Error", f"Failed to get engine port for '{engine_pkg_id}': {e}")
            return
            
        # --- 步骤 2.2: 执行反向代理 ---
        # --- Step 2.2: Perform the Reverse Proxy ---
        try:
            target_host = '127.0.0.1'
            target_port = int(engine_port)

            conn = http.client.HTTPConnection(target_host, target_port, timeout=30)
            
            # 复制请求体 (如果有)
            # Copy request body (if any)
            content_length = int(self.headers.get('Content-Length', 0))
            body = self.rfile.read(content_length) if content_length > 0 else None

            # 复制请求头
            # Copy request headers
            proxy_headers = dict(self.headers)
            proxy_headers['X-Forwarded-For'] = self.client_address[0]
            proxy_headers['X-Forwarded-Proto'] = 'http' # We are the HTTPS endpoint

            conn.request(self.command, self.path, body=body, headers=proxy_headers)
            
            response = conn.getresponse()
            
            # 将后端服务的响应头和状态码复制回来
            # Copy the response headers and status code from the backend service
            self.send_response(response.status, response.reason)
            for key, value in response.getheaders():
                # 不要复制这些头，因为它们由 send_response 和 end_headers 管理
                # Do not copy these headers as they are managed by send_response and end_headers
                if key.lower() not in ('connection', 'transfer-encoding', 'date', 'server'):
                    self.send_header(key, value)
            self.end_headers()
            
            # 将后端服务的响应体流式传输回来
            # Stream the response body from the backend service
            while True:
                chunk = response.read(8192)
                if not chunk:
                    break
                self.wfile.write(chunk)
            
            conn.close()
            bilingual_print(f"Successfully proxied request to {engine_pkg_id} on port {engine_port}",
                            f"已成功将请求代理至运行在 {engine_port} 端口的 {engine_pkg_id}", "DEBUG")

        except (http.client.HTTPException, socket.error) as e:
            self.send_error(502, "Bad Gateway", f"Could not connect to the DApp engine backend: {e}")
        except Exception as e:
            self.send_error(500, "Proxy Error", f"An unexpected error occurred while proxying: {e}")



class SandboxAPI:
    def __init__(self, request_handler):
        if isinstance(request_handler, str):
            self.handler = None
            self.app_id = request_handler
        elif hasattr(request_handler, 'path'):
            self.handler = request_handler
            self.app_id = urlparse(self.handler.path).path.strip('/').split('/')[1]
        else:
            self.handler = request_handler
            self.app_id = getattr(request_handler, 'app_id', 'dapp')
    
    def log(self, msg_en, msg_zh=""):
        bilingual_print(f"[APP:{self.app_id}] {msg_en}", f"[应用:{self.app_id}] {msg_zh}", "APP_LOG")

    def create_transaction(self, tx_type, tx_data_json_string):
        try:
            tx_data_obj = json.loads(tx_data_json_string)
            pretty_data = json.dumps(tx_data_obj, indent=2)
        except json.JSONDecodeError: return None

        auto_approve_policy = get_local_acl_permission(self.app_id, 'api.transaction.auto_approve', 'confirm')
        user_approved = False
        if auto_approve_policy.lower() == 'true':
            user_approved = True
        else:
            print("\n" + "="*70, file=sys.stderr)
            bilingual_print(f"SECURITY ALERT: Web App '{self.app_id}' is requesting a blockchain transaction.",
                            f"安全警报: 网页应用 '{self.app_id}' 正在请求创建一笔区块链交易。", "WARN")
            print(f"  Type / 类型    : {tx_type}\n  Data / 数据      :\n{pretty_data}\n" + "="*70, file=sys.stderr)
            try:
                choice = input("  Authorize this action? [y/N] (or add api.transaction.auto_approve = true to its ACL section to bypass) / 是否授权此操作？[y/N] (或在其 ACL 配置段中添加 api.transaction.auto_approve = true 来跳过此提示) ").lower().strip()
                if choice == 'y': user_approved = True
            except EOFError: pass
        
        if not user_approved: return None
        return self.handler._ipc_call(['_internal_create_transaction', tx_type, tx_data_json_string])

    def nns_resolve(self, domain_name):
        return self.handler._ipc_call(['_internal_nns_resolve', domain_name])

    def p2p_get(self, object_hash):
        return self.handler._ipc_call(['_internal_p2p_get', object_hash])
        
    def p2p_get_bytes(self, object_hash):
        return self.handler._ipc_call(['_internal_p2p_get_bytes', object_hash], is_binary=True)

    def p2p_upload(self, content_string):
        """
        Requests the Corium core to publish content to the P2P network.
        This is the DApp-facing method.
        请求 Corium 核心将内容发布到 P2P 网络。这是面向 DApp 的方法。
        """
        # Delegate to the unified security and execution function.
        # 委托给统一的安全与执行函数。
        return _internal_confirm_and_execute_upload(self.app_id, content_string)
    
    def _get_vault_physical_path(self, relative_path=""):
        """
        内部辅助函数，安全地构造并验证数据保险库的物理路径。
        Internal helper to safely construct and validate the physical path for the data vault.
        """
        # 1. 构造 DApp 专属的保险库根目录
        # 1. Construct the DApp-specific vault root directory
        dapp_data_dir = os.environ.get('DAPP_DATA_DIR')
        pkg_id_for_path = self.app_id.replace(':', '-').replace('/', '_') # Replicate Bash logic
        base_vault_path = os.path.join(dapp_data_dir, pkg_id_for_path)

        # 2. 路径安全检查：禁止任何形式的路径遍历
        # 2. Path Security Check: Prohibit any form of path traversal
        if os.path.isabs(relative_path) or ".." in relative_path.split(os.path.sep):
            bilingual_print(f"SECURITY ALERT: Vault path traversal attempt from '{self.app_id}' was blocked.",
                            f"安全警报：来自 '{self.app_id}' 的保险库路径遍历尝试已被阻止。", "WARN")
            return None

        # 3. 组合并规范化最终路径
        # 3. Combine and normalize the final path
        return os.path.normpath(os.path.join(base_vault_path, relative_path))

    def write_to_vault(self, filepath, content):
        """
        将内容写入 DApp 的数据保险库。需要 'fs.data_vault.write' 权限。
        Writes content to the DApp's data vault. Requires 'fs.data_vault.write' permission.
        """
        # 权限检查 / Permission Check
        if get_local_acl_permission(self.app_id, 'fs.data_vault.write', 'deny') != 'allow':
            bilingual_print(f"ACL DENY: DApp '{self.app_id}' attempted to write to vault without permission.",
                            f"ACL 拒绝：DApp '{self.app_id}' 尝试在未经许可的情况下写入保险库。", "WARN")
            return {"status": "error", "message": "Permission denied by local ACL."}

        physical_path = self._get_vault_physical_path(filepath)
        if not physical_path:
            return {"status": "error", "message": "Invalid vault path."}

        try:
            # 确保父目录存在 / Ensure parent directory exists
            os.makedirs(os.path.dirname(physical_path), exist_ok=True)
            # 写入文件 / Write the file
            with open(physical_path, 'w', encoding='utf-8') as f:
                f.write(content)
            bilingual_print(f"Vault Write OK: DApp '{self.app_id}' wrote to '{filepath}'.",
                            f"保险库写入成功：DApp '{self.app_id}' 已写入 '{filepath}'。", "DEBUG")
            return {"status": "success"}
        except Exception as e:
            bilingual_print(f"Vault Write FAIL: DApp '{self.app_id}' failed to write to '{filepath}': {e}",
                            f"保险库写入失败：DApp '{self.app_id}' 写入 '{filepath}' 时出错: {e}", "ERROR")
            return {"status": "error", "message": str(e)}

    def read_from_vault(self, filepath):
        """
        从 DApp 的数据保险库读取内容。需要 'fs.data_vault.read' 或 'write' 权限。
        Reads content from the DApp's data vault. Requires 'fs.data_vault.read' or 'write' permission.
        """
        # 权限检查 / Permission Check
        read_perm = get_local_acl_permission(self.app_id, 'fs.data_vault.read', 'deny')
        write_perm = get_local_acl_permission(self.app_id, 'fs.data_vault.write', 'deny')
        if read_perm != 'allow' and write_perm != 'allow':
            bilingual_print(f"ACL DENY: DApp '{self.app_id}' attempted to read from vault without permission.",
                            f"ACL 拒绝：DApp '{self.app_id}' 尝试在未经许可的情况下读取保险库。", "WARN")
            return {"status": "error", "message": "Permission denied by local ACL."}

        physical_path = self._get_vault_physical_path(filepath)
        if not physical_path:
            return {"status": "error", "message": "Invalid vault path."}

        try:
            if not os.path.exists(physical_path):
                 return {"status": "error", "message": "File not found in vault."}
            with open(physical_path, 'r', encoding='utf-8') as f:
                content = f.read()
            return {"status": "success", "data": content}
        except Exception as e:
            bilingual_print(f"Vault Read FAIL: DApp '{self.app_id}' failed to read from '{filepath}': {e}",
                            f"保险库读取失败：DApp '{self.app_id}' 读取 '{filepath}' 时出错: {e}", "ERROR")
            return {"status": "error", "message": str(e)}

    def list_vault(self, directory=""):
        """
        列出 DApp 数据保险库中一个目录的内容。
        Lists the contents of a directory within the DApp's data vault.
        """
        # 权限检查 (与 read 相同) / Permission Check (same as read)
        read_perm = get_local_acl_permission(self.app_id, 'fs.data_vault.read', 'deny')
        write_perm = get_local_acl_permission(self.app_id, 'fs.data_vault.write', 'deny')
        if read_perm != 'allow' and write_perm != 'allow':
            return {"status": "error", "message": "Permission denied by local ACL."}

        physical_path = self._get_vault_physical_path(directory)
        if not physical_path:
            return {"status": "error", "message": "Invalid vault path."}

        try:
            if not os.path.isdir(physical_path):
                return {"status": "error", "message": "Not a directory."}
            
            # 返回一个包含文件名和类型的列表
            # Return a list of items with name and type
            items = []
            for item in os.listdir(physical_path):
                item_path = os.path.join(physical_path, item)
                item_type = 'dir' if os.path.isdir(item_path) else 'file'
                items.append({'name': item, 'type': item_type})

            return {"status": "success", "data": items}
        except Exception as e:
            return {"status": "error", "message": str(e)}
            
    def delete_from_vault(self, filepath):
        """
        从 DApp 的数据保险库中删除一个文件或目录。需要 'fs.data_vault.write' 权限。
        Deletes a file or directory from the DApp's data vault. Requires 'fs.data_vault.write' permission.
        """
        # 权限检查 / Permission Check
        if get_local_acl_permission(self.app_id, 'fs.data_vault.write', 'deny') != 'allow':
            return {"status": "error", "message": "Permission denied by local ACL."}

        physical_path = self._get_vault_physical_path(filepath)
        if not physical_path:
            return {"status": "error", "message": "Invalid vault path."}

        try:
            if os.path.isdir(physical_path):
                import shutil
                shutil.rmtree(physical_path)
            elif os.path.isfile(physical_path):
                os.remove(physical_path)
            else:
                return {"status": "error", "message": "File or directory not found."}
            return {"status": "success"}
        except Exception as e:
            return {"status": "error", "message": str(e)}
    
    # =========================================================================
    # --- [V75 Sign-Svc] request_signature API (智能预览与双重确认版)   ---
    # --- [V75 Sign-Svc] request_signature API (Smart Preview & Dual Confirm) ---
    # =========================================================================
    def _parse_and_preview_transaction(self, data_to_sign):
        """
        一个内部辅助函数，尝试解析交易数据并生成人类可读的预览。
        An internal helper to parse transaction data and generate a human-readable preview.
        """
        try:
            tx_obj = json.loads(data_to_sign)
            tx_type = tx_obj.get('type')
            tx_data = tx_obj.get('data')
    
            bilingual_print("This appears to be a Corium Transaction. Details:",
                            "这似乎是一笔 Corium 交易。详情如下:", "INFO")
    
            print(f"  - 类型 / Type:    {tx_type}", file=sys.stderr)
            
            # 为不同交易类型提供定制的、安全的预览
            # Provide custom, safe previews for different transaction types
            if tx_type == "group_transfer_ownership":
                group_id = tx_data.get('group_id', '???')
                new_owner_id = tx_data.get('new_owner_id', '???')
                print(f"  - 操作 / Action:   转移群组所有权 / Transfer Group Ownership", file=sys.stderr)
                print(f"  - 目标群组 / Target Group: {group_id[:16]}...", file=sys.stderr)
                print(f"  - 新群主 / New Owner:   {new_owner_id[:16]}...", file=sys.stderr)
            elif tx_type == "set_nickname":
                nickname = tx_data.get('nickname', '???')
                print(f"  - 操作 / Action:   设置昵称 / Set Nickname", file=sys.stderr)
                print(f"  - 新昵称 / New Nickname: {nickname}", file=sys.stderr)
            # ... 在这里可以为更多交易类型添加预览逻辑 ...
            else:
                # 通用预览
                # Generic preview
                print(f"  - 数据 / Data:     {json.dumps(tx_data)}", file=sys.stderr)
    
            return True # 表示解析成功
        except:
            # 如果不是有效的 JSON 或交易格式，就回退到普通预览
            # If not valid JSON or transaction format, fall back to normal preview
            print(f"  Data Preview (first 100 chars) / 数据预览 (前100字符):", file=sys.stderr)
            print(f"  > {data_to_sign[:100]}", file=sys.stderr)
            return False
    
    def request_signature(self, data_to_sign_b64):
        """
        请求 Corium 核心使用用户的私钥对一段数据进行签名。
        Requests the Corium core to sign a piece of data with the user's private key.
        """
        # 权限检查 / Permission Check
        perm = get_local_acl_permission(self.app_id, 'api.request_signature', 'confirm')
        if perm not in ('confirm', 'allow_auto'):
            return {"status": "error", "message": "Permission denied by local ACL."}
    
        # 自动签名模式检查 / Auto-sign mode check
        if perm == 'allow_auto':
            confirmation_log = os.path.join(os.environ.get('VAR_LIB_CORIUM_DIR'), '.auto_signer_confirmations')
            # 再次检查确认日志，确保权限已被激活
            # Double-check the confirmation log to ensure the permission is activated
            if os.path.exists(confirmation_log):
                 with open(confirmation_log, 'r') as f:
                    if self.app_id in f.read().splitlines():
                        bilingual_print(f"AUTO-SIGN: Signing request from '{self.app_id}' automatically.",
                                        f"自动签名：正在为 '{self.app_id}' 的请求自动签名。", "DEBUG")
                        return self.handler._ipc_call(['_internal_sign_data', data_to_sign_b64])
            
            # 如果未被确认，则降级为 confirm 模式
            # If not confirmed, fall back to confirm mode
            bilingual_print(f"AUTO-SIGN DENIED: Permission for '{self.app_id}' is not confirmed. Falling back to manual confirmation.",
                            f"自动签名被拒绝：'{self.app_id}' 的权限尚未被确认。降级为手动确认。", "WARN")
    
        # 手动确认模式 (confirm mode)
        try:
            data_to_sign = base64.b64decode(data_to_sign_b64).decode('utf-8')
        except:
            return {"status": "error", "message": "Invalid base64 data."}
    
        # --- 第一重确认：预览与意图确认 ---
        # --- First Confirmation: Preview and Intent ---
        print("\n" + "="*70, file=sys.stderr)
        bilingual_print(f"SIGNATURE REQUEST (1/2): Please review the action requested by '{self.app_id}'.",
                        f"签名请求 (1/2): 请审查来自 '{self.app_id}' 的操作请求。", "WARN")
        
        # 智能预览 / Smart Preview
        self._parse_and_preview_transaction(data_to_sign)
        data_hash = calculate_hash(data_to_sign)
        print(f"  - 数据哈希 / Data Hash: {data_hash}", file=sys.stderr)
        print("="*70, file=sys.stderr)
        
        try:
            choice = input("  Do you approve this action? Type 'yes' to proceed to the final confirmation: / 您是否批准此操作？请输入 'yes' 进入最终确认：").strip()
            if choice.lower() != 'yes':
                bilingual_print("Action denied by user.", "操作已被用户拒绝。", "INFO")
                return {"status": "error", "message": "User denied the action."}
        except EOFError:
            return {"status": "error", "message": "User denied the action."}
    
        # --- 第二重确认：最终执行确认 ---
        # --- Second Confirmation: Final Execution ---
        print("\n" + "="*70, file=sys.stderr)
        bilingual_print(f"FINAL CONFIRMATION (2/2): You are about to cryptographically sign the data with hash starting with {data_hash[:8]}.",
                        f"最终确认 (2/2): 您即将使用您的私钥对哈希以 {data_hash[:8]} 开头的数据进行加密签名。", "ERROR")
        bilingual_print("This action is irreversible. / 此操作不可逆转。", "ERROR")
        
        try:
            # 要求用户输入一个随机词或进行一个简单的计算，以防止肌肉记忆
            # Ask the user to type a random word or do a simple calculation to prevent muscle memory
            confirm_word = "sign"
            choice = input(f"  To confirm, please type the word '{confirm_word}' and press Enter: / 请输入 '{confirm_word}' 并按回车以确认：").strip()
            if choice != confirm_word:
                bilingual_print("Final confirmation failed. Signature request cancelled.",
                                "最终确认失败。签名请求已取消。", "INFO")
                return {"status": "error", "message": "Final confirmation failed."}
        except EOFError:
            return {"status": "error", "message": "Final confirmation failed."}
            
        bilingual_print("Confirmation received. Executing signature...", "已收到确认。正在执行签名...", "OK")
        return self.handler._ipc_call(['_internal_sign_data', data_to_sign_b64])
        
