            sys.exit(1)

        def create_server(port, handler):
            """
            一个健壮的、网络协议无关的服务器创建函数。
            A robust, network-protocol-agnostic server creation function.
            """
            # AF_UNSPEC: 允许返回IPv4或IPv6的地址
            # AI_PASSIVE: 表明我们想用这个套接字来接受连接 (bind)
            # socket.getaddrinfo will return a list of suitable configurations.
            # On modern dual-stack systems, it typically returns the IPv6 config first.
            addr_info = socket.getaddrinfo(None, port, socket.AF_UNSPEC, socket.SOCK_STREAM, 0, socket.AI_PASSIVE)

            server = None
            last_error = None
            # 遍历所有操作系统推荐的配置，尝试第一个能成功的
            # Iterate through all OS-recommended configurations and try the first one that works.
            for family, socktype, proto, canonname, sockaddr in addr_info:
                try:
                    # 我们需要动态地设置 address_family
                    # We need to set the address_family dynamically
                    class ThreadedTCPServer(socketserver.ThreadingMixIn, http.server.HTTPServer):
                        pass
                    
                    ThreadedTCPServer.address_family = family
                    server = ThreadedTCPServer(sockaddr, handler)
                    break # 如果成功，就跳出循环 / If successful, break the loop
                except OSError as e:
                    last_error = e
                    continue # 如果失败，就尝试下一个 / If it fails, try the next one
            
            if server is None:
                # 如果遍历完所有配置都失败了，就抛出最后的错误
                # If all configurations failed, raise the last error
                raise last_error

            # 如果最终创建的是一个IPv6服务器，确保它也能接受IPv4连接（双栈模式）
            # If an IPv6 server was created, ensure it also accepts IPv4 connections (dual-stack mode)
            if server.address_family == socket.AF_INET6:
                try:
                    server.socket.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_V6ONLY, 0)
                except (OSError, AttributeError):
                    # 在某些系统上这可能会失败，但不是致命错误
                    # This might fail on some systems, but it's not a fatal error
                    pass
            
            return server

        # 3. 在 main 逻辑中，使用新的 create_server 函数
        dht_api_port = P2P_PORT + P2P_HTTP_PORT_OFFSET
        file_server_port = P2P_PORT + P2P_FILE_PORT_OFFSET
        gateway_port = GATEWAY_PORT

        context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        
        context.load_cert_chain(certfile=cert_file, keyfile=key_file)
        
