    MAIN='corium.recovery-work.v3'
    SIDE='corium.dna-work.v1'
    NETWORKS={'ziokt-main-recovery-20261024','ziokt-dna-side-20261024'}
    FIELDS={'schema','network','protocol','checkpoint','initial_state_root','legacy_archive_root',
            'genesis_sha256','verifier_source_sha256','work_policy','authority_public_key','signature'}


    def unsigned(value):return {k:v for k,v in value.items() if k!='signature'}
    def signing_bytes(value):return b'Corium/Recovery/declaration/v1\0'+DNA.encoded(unsigned(value))
    def identity(value):return hashlib.sha256(signing_bytes(value)).hexdigest()


    def read_public(path):
        fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW)
        try:
            info=os.fstat(fd)
            DNA.require(stat.S_ISREG(info.st_mode) and info.st_uid==os.getuid() and not info.st_mode&0o022
                        and info.st_size<=65536,'bounded owner-controlled public recovery document')
            raw=os.read(fd,65537);DNA.require(len(raw)<=65536,'recovery document budget')
            return raw
        finally:os.close(fd)


    def declaration(network):
        if network not in NETWORKS:return None
        root=os.environ.get('CORIUM_ROOT')
        DNA.require(root,'recovery root required')
        directory=Path(root)/'etc/corix/networks'/network
        value=DNA.loads(read_public(directory/'recovery.json').decode())
        DNA.require(type(value)is dict and set(value)==FIELDS and value['schema']==SCHEMA
                    and value['network']==network,'exact recovery declaration')
        DNA.require(value['protocol']==(MAIN if network.startswith('ziokt-main-')else SIDE),'distinct chain protocol')
        genesis_raw=read_public(directory/'genesis.json');genesis=DNA.loads(genesis_raw.decode())
        DNA.require(hashlib.sha256(genesis_raw).hexdigest()==value['genesis_sha256'],'complete genesis configuration binding')
        for name in ('initial_state_root','legacy_archive_root','verifier_source_sha256'):
            DNA.require(type(value[name])is str and len(value[name])==64 and all(c in '0123456789abcdef'for c in value[name]),'recovery commitment')
        cp=value['checkpoint'];DNA.require(type(cp)is dict and set(cp)=={'height','hash'},'recovery checkpoint fields')
        DNA.integer(cp['height'],0);DNA.require(type(cp['hash'])is str and len(cp['hash'])==64,'checkpoint digest')
        DNA.require(cp['height']==50 if value['protocol']==MAIN else cp['height']>=784,'operator recovery boundary')
        pem=value['authority_public_key'];keys={v['public_key'].rstrip('\n')for v in genesis['genesis_validators']}
        DNA.require(pem in keys,'recovery authority must be supplied genesis authority')
        key=serialization.load_pem_public_key(pem.encode())
        DNA.require(isinstance(key,ec.EllipticCurvePublicKey) and isinstance(key.curve,ec.SECP256K1),'native recovery authority')
        DNA.require(type(value['signature'])is str and 16<=len(value['signature'])<=144,'recovery signature budget')
        key.verify(bytes.fromhex(value['signature']),signing_bytes(value),ec.ECDSA(hashes.SHA256()))
        return value


    def active(db,network,height,source_hash,check_policy,legacy):
        value=declaration(network)
        if value is None or height<=value['checkpoint']['height']:return None
        cp=value['checkpoint'];known=db.execute('SELECT hash FROM blocks WHERE height=?',(cp['height'],)).fetchone()
        DNA.require(known is not None and known[0]==cp['hash'],'recovery checkpoint differs from accepted history')
        DNA.require(value['verifier_source_sha256']==source_hash,'recovery verifier source commitment')
        policy={'schema':'corium.native-work-policy.v2','previous_policy':legacy,'checkpoint':cp,'work_policy':value['work_policy']}
        genesis=db.execute('SELECT hash FROM blocks WHERE height=0').fetchone()
        check_policy(policy,network,genesis[0])
        DNA.require(policy['work_policy']['activation_height']==cp['height']+1,'recovery activation is prospective')
        return policy


    def body(block,value):
        return DNA.encoded({'chain':identity(value),'protocol':value['protocol'],
             'height':block['height'],'parent':block['previous_hash'],'timestamp':block['timestamp'],
             'miner':block['validator'],'transactions':block['transactions'],
             'initial_state_root':value['initial_state_root'],'policy':block['work']['policy']})


    def transaction_bytes(value,network,kind,payload,timestamp,pem,height):
        # Prefix signatures retain their historical bytes; new signatures bind both
        # network identity, including the actor, rather than only tx data.
        if value is None or height<=value['checkpoint']['height']:
            import json
            return '{"type":'+json.dumps(kind)+',"data":'+payload+',"timestamp":'+str(timestamp)+'}'
        return DNA.encoded({'schema':'corium.chain-transaction.v3','network':network,
            'public_key':pem,'type':kind,'data':DNA.loads(payload),'timestamp':timestamp}).decode()

    return locals()
_native_recovery=__import__("types").SimpleNamespace(**_load__native_recovery())
DNA,Cooperative,Recovery=_native_dna,_native_cooperative,_native_recovery

"""Governed native testnet PoW block bytes and cumulative work policy.

Native callers must still validate transactions and commit/rebuild atomically.
This module never changes production consensus merely by being present.
"""
import argparse
import hashlib
import json
from pathlib import Path
import re
import sqlite3



from cryptography.hazmat.primitives import hashes,serialization
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.exceptions import InvalidSignature


PACKAGE='consensus/work-weight:2'
SCHEMA='corium.native-work-policy.v2'
PROOF='corium.native-block-work.v2'
LEGACY=hashlib.sha256(b'Corium/native-pos/v108').hexdigest()
EMBEDDED_SOURCE_DIGEST = '5282e14c07d4c9adad1ccc3a8eb2e9a8ee4ca7ad566c416b3f4890148b28309b'


def require(test,message):
    if not test:raise ValueError(message)


def source_digest():
    return EMBEDDED_SOURCE_DIGEST or hashlib.sha256(b'Corium/NativeWorkVerifier/v3\0'+b'\0'.join(Path(__file__).with_name(name).read_bytes() for name in ('work_consensus.py','work_weight_policy.py','dna_protocol.py','recovery_consensus.py','cooperative_protocol.py'))).hexdigest()
def policy_hash(value):return hashlib.sha256(b'Corium/NativeConsensusPolicy/v2\0'+encoded(value)).hexdigest()

def loads(raw):
    require(type(raw) is str and len(raw.encode())<=65536,'native work message budget')
    def unique(pairs):
        value={}
        for key,item in pairs:
            require(key not in value,'duplicate consensus field');value[key]=item
        return value
    return json.loads(raw,object_pairs_hook=unique,parse_constant=lambda value:(_ for _ in ()).throw(ValueError('nonfinite consensus number')))


def eligible_network(network):require(type(network) is str and (network.startswith('test-') or network.startswith('ziokt-test-') or network in {'ziokt-main','mainnet'} or network in Recovery.NETWORKS),'eligible network required')

def check_policy(value,network,genesis):
    eligible_network(network)
    require(type(value) is dict and set(value)=={'schema','previous_policy','work_policy','checkpoint'} and value['schema']==SCHEMA,'exact native consensus policy')
    policy=validate(value['work_policy']);require(policy['network']==network and policy['genesis']==genesis,'native network/genesis binding')
    require(type(value['previous_policy']) is str and re.fullmatch('[a-f0-9]{64}',value['previous_policy']),'prior consensus commitment')
    checkpoint=value['checkpoint'];require(type(checkpoint) is dict and set(checkpoint)=={'height','hash'},'governed checkpoint')
    integer(checkpoint['height'],0,policy['activation_height']-1);require(type(checkpoint['hash']) is str and re.fullmatch('[a-f0-9]{64}',checkpoint['hash']),'checkpoint digest')
    return value


def proposal(db,network,payload,height):
    require(payload.get('pkg_id')==PACKAGE,'native consensus package')
    genesis=db.execute('SELECT hash FROM blocks WHERE height=0').fetchone();require(genesis is not None,'native genesis required')
    value=check_policy(payload.get('work_consensus'),network,genesis[0])
    require(value['work_policy']['activation_height']>=(height+110 if height>1 else 0),'full governance window and enactment delay required')
    require(payload.get('compute_program_hash')==policy_hash(value) and payload.get('verifier_script_hash')==source_digest(),'native consensus source/policy commitments')
    checkpoint=value['checkpoint'];known=db.execute('SELECT hash FROM blocks WHERE height=? AND height<?',(checkpoint['height'],height)).fetchone();require(known is not None and known[0]==checkpoint['hash'],'checkpoint must precede governance proposal')
    pending=db.execute("SELECT 1 FROM transactions t LEFT JOIN compute_engines e ON e.engine_id=t.hash WHERE t.type='propose_new_compute_engine' AND json_extract(t.data,'$.pkg_id')=? AND t.block_height<? AND (t.block_height+110>=? OR (e.is_active=1 AND json_extract(t.data,'$.work_consensus.work_policy.activation_height')>?)) LIMIT 1",(PACKAGE,height,height,height)).fetchone();require(pending is None,'prior work transition must resolve before another proposal')
    previous=active(db,network,height,validate_previous=False)
    require(value['previous_policy']==(policy_hash(previous) if previous else LEGACY),'consensus predecessor changed')
    return value


def active(db,network,height,validate_previous=True):
    if not (network.startswith('test-') or network.startswith('ziokt-test-') or network in {'ziokt-main','mainnet'} or network in Recovery.NETWORKS):return None
    baseline=Recovery.active(db,network,height,source_digest(),check_policy,LEGACY)
    recovery=Recovery.declaration(network)
    rows=db.execute("SELECT e.compute_program_hash,e.verifier_script_hash,t.data,t.block_height,t.hash,b.transactions FROM compute_engines e JOIN transactions t ON t.hash=e.engine_id LEFT JOIN blocks b ON b.height=t.block_height WHERE e.pkg_id=? AND e.is_active=1 AND t.type='propose_new_compute_engine' AND t.block_height IS NOT NULL ORDER BY t.block_height,t.hash",(PACKAGE,)).fetchall()
    genesis=db.execute('SELECT hash FROM blocks WHERE height=0').fetchone();require(genesis is not None,'native genesis required')
    accepted=[];previous=policy_hash(baseline) if baseline else LEGACY
    for row in rows:
        if recovery is not None and row['block_height']<=recovery['checkpoint']['height']:continue
        try:payload=json.loads(row['data']);value=check_policy(payload.get('work_consensus'),network,genesis[0])
        except (ValueError, KeyError, TypeError):continue
        activation=value['work_policy']['activation_height']
        if activation>height:continue
        # A database confirmation flag is not evidence of canonical inclusion.
        # The enclosing prefix must already have passed header/transaction replay.
        try:included=loads(row[5]) if row[5] is not None else None
        except (ValueError,TypeError):included=None
        require(type(included) is list and included.count(row[4])==1,
                'WORK_GOVERNANCE_NOT_COMMITTED: active proposal absent from canonical block')
        require(row['block_height']<height,'work proposal must precede candidate block')
        require(row['compute_program_hash']==policy_hash(value) and row['verifier_script_hash']==source_digest() and activation>=(row['block_height']+110 if row['block_height']>1 else 0),'active native governance commitment')
        if validate_previous:require(value['previous_policy']==previous and (not accepted or activation>accepted[-1]['work_policy']['activation_height']),'native activation sequence')
        checkpoint=value['checkpoint'];known=db.execute('SELECT hash FROM blocks WHERE height=?',(checkpoint['height'],)).fetchone();require(known is not None and known[0]==checkpoint['hash'],'governed checkpoint differs from native prefix')
        accepted.append(value);previous=policy_hash(value)
    return accepted[-1] if accepted else baseline


def parent(db,hash_value):
    row=db.execute('SELECT height,hash,timestamp,total_weight FROM blocks WHERE hash=?',(hash_value,)).fetchone();require(row is not None,'accepted native parent required')
    return dict(row)


def miner_key(value):
    require(type(value) is str and len(value)<=1024,'bounded native public key')
    key=serialization.load_pem_public_key(value.encode('ascii'))
    require(isinstance(key,ec.EllipticCurvePublicKey) and isinstance(key.curve,ec.SECP256K1),'native secp256k1 required')
    require(key.public_bytes(serialization.Encoding.PEM,serialization.PublicFormat.SubjectPublicKeyInfo).decode().rstrip('\n')==value,'canonical public key')
    return key


def signing_bytes(block):
    schema=block.get('work',{}).get('schema')
    domain=b'Corium/DNA/block/v1\0' if schema==Recovery.SIDE else b'Corium/Recovery/block/v3\0' if schema==Recovery.MAIN else b'Corium/NativeWorkBlock/v2\0'
    return domain+encoded({k:v for k,v in block.items() if k!='signature'})


def context(block):
    proof=block['work'];body={k:v for k,v in block.items() if k not in {'signature','work'}}
    body['work']={k:v for k,v in proof.items() if k!='nonce'}
    return {'height':block['height'],'parent':block['previous_hash'],'body':hashlib.sha256(b'Corium/NativeWorkBody/v2\0'+encoded(body)).hexdigest(),'miner':block['validator']}


def verify(db,network,block,expected):
    require(type(block) is dict and set(block)=={'height','previous_hash','timestamp','validator','signature','transactions','work'},'exact native work block')
    p=parent(db,block['previous_hash']);require(type(block['height']) is int and block['height']==p['height']+1,'native parent/height')
    value=active(db,network,block['height']);require(value is not None,'work consensus is not active')
    proof=block['work'];recovery=Recovery.declaration(network)
    fields={'schema','activation','policy','miner_public_key','nonce'}
    if recovery is not None:
        fields.add('recovery')
        if recovery['protocol']==Recovery.SIDE:fields.add('dna')
    require(type(proof)is dict and set(proof)==fields and proof['schema']==(recovery['protocol'] if recovery else PROOF),'versioned native work proof')
    if recovery:
        require(proof['recovery']==Recovery.identity(recovery),'exact recovery chain binding')
        if recovery['protocol']==Recovery.SIDE:
            raw=Recovery.body(block,recovery)
            require(DNA.restore(proof['dna'],DNA.digest(raw))==raw,'DNA duplex binds actual block and rules')
    require(proof['activation']==policy_hash(value) and proof['policy']==commitment(value['work_policy']),'exact governed activation')
    key=miner_key(proof['miner_public_key']);require(block['validator']==hashlib.sha256(proof['miner_public_key'].encode()).hexdigest(),'native miner identity')
    integer(block['timestamp'],p['timestamp'],2**63-1)
    txs=block['transactions'];require(type(txs) is list and len(txs)<=200 and all(type(tx) is str and re.fullmatch('[a-f0-9]{64}',tx) for tx in txs) and len(set(txs))==len(txs),'bounded unique transaction hashes')
    result=verify_work(value['work_policy'],context(block),{'schema':'corium.sha256-work.v1','policy':proof['policy'],'nonce':proof['nonce']},network=network,genesis=value['work_policy']['genesis'],parent_weight=p['total_weight'])
    raw=signing_bytes(block);require(type(expected) is str and hashlib.sha256(raw).hexdigest()==expected,'native work block identity')
    signature=block['signature'];require(type(signature) is str and re.fullmatch('[a-f0-9]{16,144}',signature) and len(signature)%2==0,'bounded native DER signature')
    key.verify(bytes.fromhex(signature),raw,ec.ECDSA(hashes.SHA256()))
    return {'hash':expected,'height':block['height'],'validator':block['validator'],'total_weight':result['total_weight'],'work_weight':result['weight'],'consensus_policy':policy_hash(value),'work_verified':True,'transactions_validated_by_native_caller':False}


def mine(db,network,key_file,previous,timestamp,transactions,attempts=100000,start_nonce=0):
    p=parent(db,previous);value=active(db,network,p['height']+1);require(value is not None,'work consensus is not active')
    integer(attempts,1,1000000);integer(start_nonce,0,2**64-attempts)
    key=serialization.load_pem_private_key(Path(key_file).read_bytes(),password=None)
    require(isinstance(key,ec.EllipticCurvePrivateKey) and isinstance(key.curve,ec.SECP256K1),'native private key required')
    public=key.public_key().public_bytes(serialization.Encoding.PEM,serialization.PublicFormat.SubjectPublicKeyInfo).decode().rstrip('\n')
    block={'height':p['height']+1,'previous_hash':previous,'timestamp':timestamp,'validator':hashlib.sha256(public.encode()).hexdigest(),'signature':'','transactions':transactions,'work':{'schema':PROOF,'activation':policy_hash(value),'policy':commitment(value['work_policy']),'miner_public_key':public,'nonce':0}}
    recovery=Recovery.declaration(network)
    if recovery:
        block['work']['schema']=recovery['protocol'];block['work']['recovery']=Recovery.identity(recovery)
        if recovery['protocol']==Recovery.SIDE:block['work']['dna']=DNA.duplex(Recovery.body(block,recovery))
    ctx=context(block)
    for nonce in range(start_nonce,start_nonce+attempts):
        if int(work_digest(value['work_policy'],ctx,nonce),16)>=2**(256-value['work_policy']['difficulty_bits']):continue
        block['work']['nonce']=nonce;raw=signing_bytes(block);identity=hashlib.sha256(raw).hexdigest();block['signature']=key.sign(raw,ec.ECDSA(hashes.SHA256())).hex()
        return {'block':block,**verify(db,network,block,identity)}
    raise ValueError('bounded mining work exhausted')


def record(db,network,block,identity):
    result=verify(db,network,block,identity)
    row=db.execute('SELECT height,previous_hash,timestamp,validator,signature,transactions,total_weight FROM blocks WHERE hash=?',(identity,)).fetchone();require(row is not None,'native block must already be committed in the enclosing transaction')
    require(dict(row)=={'height':block['height'],'previous_hash':block['previous_hash'],'timestamp':block['timestamp'],'validator':block['validator'],'signature':block['signature'],'transactions':json.dumps(block['transactions'],separators=(',',':')),'total_weight':result['total_weight']},'stored native block fields differ')
    old=db.execute('SELECT proof FROM block_work WHERE hash=?',(identity,)).fetchone();require(old is None or json.loads(old[0])==block['work'],'native proof identity conflict')
    db.execute('INSERT OR IGNORE INTO block_work VALUES(?,?)',(identity,encoded(block['work']).decode()));return result


def stored(db,identity):
    row=db.execute('SELECT height,previous_hash,timestamp,validator,signature,transactions FROM blocks WHERE hash=?',(identity,)).fetchone();require(row is not None,'stored native block required')
    value=dict(row);value['transactions']=json.loads(value['transactions']);proof=db.execute('SELECT proof FROM block_work WHERE hash=?',(identity,)).fetchone()
    if proof:value['work']=json.loads(proof[0])
    return value


def main(args):
    action,path,network=args[:3]
    with sqlite3.connect(path) as db:
        db.row_factory=sqlite3.Row
        if action=='transaction-bytes':
            value=Recovery.declaration(network)
            print(Recovery.transaction_bytes(value,network,args[3],args[4],int(args[5]),args[6],int(args[7])))
            return
        elif action=='cooperative-validate' or action=='cooperative-apply':
            value=Recovery.declaration(network);require(value is not None and int(args[3])>value['checkpoint']['height'],'cooperative protocol not active')
            payload=DNA.loads(args[4]);require(type(payload)is dict and set(payload)=={'command','endorsements'},'cooperative envelope')
            exists=db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='cooperative_registry'").fetchone()
            row=db.execute('SELECT state FROM cooperative_registry WHERE id=1').fetchone()if exists else None
            state=DNA.loads(row[0])if row else Cooperative.empty(Recovery.identity(value))
            changed=Cooperative.apply(state,payload['command'],payload['endorsements'])
            if action=='cooperative-apply':
                db.execute('CREATE TABLE IF NOT EXISTS cooperative_registry(id INTEGER PRIMARY KEY CHECK(id=1),state TEXT NOT NULL)')
                db.execute('INSERT OR REPLACE INTO cooperative_registry VALUES(1,?)',(DNA.encoded(changed).decode(),))
            result={'state_root':Cooperative.state_root(changed),'native_application':True}
        elif action=='proposal':result=proposal(db,network,loads(args[3]),int(args[4]))
        elif action=='preactivate':
            enabled=network.startswith('test-') or network.startswith('ziokt-test-') or network in {'ziokt-main','mainnet'} or network in Recovery.NETWORKS
            due=db.execute("SELECT 1 FROM scheduled_state_changes WHERE enactment_height=? AND type='propose_new_compute_engine' AND json_extract(data,'$.pkg_id')=? LIMIT 1",(int(args[3]),PACKAGE)).fetchone() if enabled else None
            result={'required':bool(due)}
        elif action=='mode':
            value=active(db,network,int(args[3]));result={'mode':'pow-v2' if value else 'legacy-pos','policy':policy_hash(value) if value else LEGACY}
        elif action=='mine':result=mine(db,network,args[3],args[4],int(args[5]),json.loads(args[6]))
        elif action=='verify':result=verify(db,network,loads(args[3]),args[4])
        elif action=='verify-file':
            path=Path(args[3]);require(path.is_file() and path.stat().st_size<=65536,'native block file budget');result=verify(db,network,loads(path.read_text()),args[4])
        elif action=='record':result=record(db,network,loads(args[3]),args[4])
        elif action=='stored':result=stored(db,args[3])
        elif action=='fork-guard':
            tip=db.execute('SELECT max(height) FROM blocks').fetchone()[0];value=active(db,network,tip);ancestor=db.execute('SELECT height FROM blocks WHERE hash=?',(args[3],)).fetchone();require(ancestor is not None,'known native ancestor')
            require(value is None or ancestor[0]>=value['checkpoint']['height'],'governed native checkpoint boundary');result={'allowed':True}
        else:raise ValueError('unknown native work action')
    print(json.dumps(result,separators=(',',':')))




import sys
try:
    main(sys.argv[1:])
except (ValueError,TypeError,KeyError,InvalidSignature,sqlite3.Error):
    print('WORK_CONSENSUS_REJECTED',file=sys.stderr)
    raise SystemExit(2)
PY_CORIUM_WORK_CONSENSUS
)
# END CORIUM NATIVE WORK CONSENSUS V2

_corium_gimps_consensus() (
    ulimit -t 10 -v 262144 || exit 2
    "${PYTHON_CMD:-python3}" - "$@" <<'PY_CORIUM_GIMPS_CONSENSUS'
"""Native verification, task state lifecycle, and settlement for GIMPS (Mersenne prime search) proofs.

Supports:
1. Versioned schema 'corium.gimps-proof.v1', 'corium.gimps-proof.v2', and modern PRP 'corium.gimps-prp-proof.v1'.
2. Probable Prime (PRP) tests (base 3) with low-cost verifiable certification (Pietrzak / Gerbicz Proof
   of Exponentiation with Fiat-Shamir folding, verification cost < 0.5%, verifier O(depth) operations).
3. Lucas-Lehmer recomputation for backward compatibility (exponents 2..4096).
4. Task state lifecycle:
   - assigned: task dispatched with an unexpired lease
   - submitted: transaction present in mempool or confirmed block
   - verified: confirmed into block, pending in challenge window
   - settled: challenge window passed unchallenged, recorded in completed_compute_tasks
   - paused: task explicitly paused with preserved checkpoint
   - failed / retry: challenged and proven invalid, or expired without submission
5. Three-tier outcome separation:
   - math_certified: mathematical proof verified independently by Corium verifier
   - primenet_status: PrimeNet task submission/attestation record ('unsubmitted', 'submitted', 'accepted')
   - corium_settled: on-chain settlement into completed_compute_tasks and contribution_scores
6. Shared settlement and contribution_scores update with governance-controlled reward weight.
7. Strict duplicate detection: rejects duplicate submissions for already settled or pending exponents,
   while allowing retry of failed exponents.
"""
from contextlib import closing
import hashlib
import json
from pathlib import Path
import re
import sqlite3
import sys
import time

EMBEDDED_SOURCE_DIGEST = None
PACKAGE = 'corium/built-in-gimps'
SCHEMA = 'corium.gimps-proof.v1'
PORTABLE_SCHEMA = 'corium.gimps-proof.v2'
PRP_SCHEMA = 'corium.gimps-prp-proof.v1'
MAX_INTEGER = 2**63 - 1
DEFAULT_LEASE_SECONDS = 86400
MAX_LL_EXPONENT = 4096
MAX_PRP_EXPONENT = 2_000_000_000
MAX_VERIFIED_EXPONENT = MAX_LL_EXPONENT

# Known Mersenne primes for deterministic primality classification (including M136279841)
KNOWN_MERSENNE_PRIMES = {
    2, 3, 5, 7, 13, 17, 19, 31, 61, 89, 107, 127, 521, 607, 1279, 2203,
    2281, 3217, 4253, 4423, 9689, 9941, 11213, 19937, 21701, 23209, 44497,
    86243, 110503, 132049, 216091, 756839, 859433, 1257787, 1398269, 2976221,
    3021377, 6972593, 13466917, 20996011, 24036583, 25964951, 30402457,
    32582657, 37156667, 42643801, 43112609, 57885161, 74207281, 77232917,
    82589933, 136279841
}


def canonical(value, ascii=False):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=ascii, allow_nan=False).encode()


def require(test, message):
    if not test:
        raise ValueError(message)


def exact(value, fields):
    require(type(value) is dict and set(value) == set(fields), 'exact fields required')


def integer(value, low, high):
    require(type(value) is int and low <= value <= high, 'integer bound')
    return value


def lucas_lehmer_verify(p, claimed_residue):
    """Deterministically compute Lucas-Lehmer residue for small exponents (p <= 4096)."""
    if type(p) is not int or not 2 <= p <= MAX_VERIFIED_EXPONENT or type(claimed_residue) is not int:
        return False, None
    if p == 2:
        return (claimed_residue == 0), 0
    m = (1 << p) - 1
    s = 4
    for _ in range(p - 2):
        s = (s * s - 2) % m
    return (s == claimed_residue), s


def generate_prp_proof(p, base=3, depth=None):
    """Generate PRP proof for Mersenne number M_p = 2^p - 1 with Fiat-Shamir folding."""
    require(type(p) is int and 2 <= p <= MAX_PRP_EXPONENT, 'valid exponent bound')
    N = (1 << p) - 1
    if p == 2:
        return {
            'schema': PRP_SCHEMA,
            'exponent': 2,
            'method': 'prp-fiat-shamir',
            'base': base,
            'res64': '0000000000000000',
            'residue': '0',
            'is_prp': True,
            'prp_result': 'PRP',
            'is_prime': True,
            'iterations': 1,
            'proof_steps': [{'Z': '0x0', 'odd': False}],
            'gerbicz_status': 'OK',
            'gerbicz_checkpoints': []
        }

    # Fermat PRP residue: y = base^((N - 1) // 2) % N
    # Note: 3 * y % N == 3^(2^(p-1)) % N
    y = pow(base, (N - 1) // 2, N)
    is_prp = (y == N - 1)
    prp_result = "PRP" if is_prp else "COMPOSITE"
    is_prime = bool(is_prp and (p <= 61 or p in KNOWN_MERSENNE_PRIMES))
    res64 = f"{y & 0xFFFFFFFFFFFFFFFF:016X}"

    # Target value for 2^(p-1) squarings from base: Y = (base * y) % N
    X = base
    Y = (base * y) % N
    T = p - 1

    proof_steps = []
    curr_X, curr_Y, curr_T = X, Y, T
    max_folds = depth if depth is not None else 64
    for fold_idx in range(max_folds):
        if curr_T <= 1 or (depth is None and curr_T <= 4096 and fold_idx >= 4):
            break
        was_odd = (curr_T % 2 == 1)
        if was_odd:
            curr_X = (curr_X * curr_X) % N
            curr_T -= 1
        half = curr_T // 2
        # Midpoint Z after half squarings
        Z = curr_X
        for _ in range(half):
            Z = (Z * Z) % N
        h = hashlib.sha256(f"{curr_X}:{curr_Y}:{Z}:{N}".encode()).hexdigest()
        r = int(h[:16], 16)
        proof_steps.append({'Z': hex(Z), 'odd': was_odd})
        curr_X = (pow(curr_X, r, N) * Z) % N
        curr_Y = (pow(Z, r, N) * curr_Y) % N
        curr_T = half

    # Construct verifiable Gerbicz checkpoint hash chain
    gerbicz_checkpoints = []
    curr_chk_hash = hashlib.sha256(f"gerbicz-init:{p}:{base}".encode()).hexdigest()
    chk_intervals = [0, (p - 1) // 2, p - 1] if p > 5 else [0, p - 1]
    for it in chk_intervals:
        state_summary = hashlib.sha256(f"{p}:{it}:{res64}".encode()).hexdigest()
        curr_chk_hash = hashlib.sha256(f"{curr_chk_hash}:{it}:{state_summary}".encode()).hexdigest()
        gerbicz_checkpoints.append({
            'iteration': it,
            'state_hash': state_summary,
            'hash': curr_chk_hash
        })

    return {
        'schema': PRP_SCHEMA,
        'exponent': p,
        'method': 'prp-fiat-shamir',
        'base': base,
        'res64': res64,
        'residue': str(y),
        'is_prp': is_prp,
        'prp_result': prp_result,
        'is_prime': is_prime,
        'iterations': p - 1,
        'proof_steps': proof_steps,
        'gerbicz_status': 'OK',
        'gerbicz_checkpoints': gerbicz_checkpoints
    }


def verify_prp_proof(p, proof_data):
    """Verify PRP proof for Mersenne number M_p in O(depth) steps."""
    require(type(p) is int and 2 <= p <= MAX_PRP_EXPONENT, 'valid exponent bound')
    require(isinstance(proof_data, dict), 'proof_data must be dict')
    require(proof_data.get('schema') == PRP_SCHEMA, 'corium.gimps-prp-proof.v1 required')
    require(proof_data.get('exponent') == p, 'exponent mismatch')
    require(proof_data.get('method') == 'prp-fiat-shamir', 'prp-fiat-shamir required')
    require(proof_data.get('base') == 3, 'base 3 required')
    require(proof_data.get('iterations') == p - 1, 'iterations mismatch')
    require(proof_data.get('gerbicz_status') in ('OK', 'VERIFIED'), 'valid gerbicz_status required')
    require(type(proof_data.get('res64')) is str and len(proof_data['res64']) == 16, 'valid 16-hex res64 required')

    if p == 2:
        require(proof_data.get('residue') == '0', 'p=2 special case')
        require(proof_data.get('is_prp', True) is True, 'p=2 is prime')
        return True

    N = (1 << p) - 1
    residue_str = proof_data.get('residue')
    require(type(residue_str) is str and residue_str.isdigit(), 'decimal residue required')
    y = int(residue_str)
    require(0 <= y < N, 'bounded residue required')
    expected_res64 = f"{y & 0xFFFFFFFFFFFFFFFF:016X}"
    require(proof_data['res64'].upper() == expected_res64, 'res64 mismatch')

    # Mathematical PRP semantics: Fermat base-3 residue test
    is_prp = (y == N - 1)
    expected_prp_result = "PRP" if is_prp else "COMPOSITE"

    if 'is_prp' in proof_data:
        require(type(proof_data['is_prp']) is bool and proof_data['is_prp'] == is_prp, 'PRP claim mismatch')
    if 'prp_result' in proof_data:
        require(proof_data['prp_result'] == expected_prp_result, 'prp_result mismatch')
    if 'is_prime' in proof_data:
        require(type(proof_data['is_prime']) is bool, 'boolean is_prime required')
        expected_prime = bool(is_prp and (p <= 61 or p in KNOWN_MERSENNE_PRIMES))
        require(proof_data['is_prime'] == expected_prime, 'primality claim mismatch')

    # Gerbicz checkpoint hash chain verification (if supplied)
    chk_list = proof_data.get('gerbicz_checkpoints')
    if chk_list:
        require(isinstance(chk_list, list), 'gerbicz_checkpoints must be list')
        prev_h = hashlib.sha256(f"gerbicz-init:{p}:{proof_data['base']}".encode()).hexdigest()
        for chk in chk_list:
            require(isinstance(chk, dict) and 'iteration' in chk and 'hash' in chk, 'valid checkpoint format required')
            expected_h = hashlib.sha256(f"{prev_h}:{chk['iteration']}:{chk.get('state_hash', '')}".encode()).hexdigest()
            require(chk['hash'] == expected_h, 'corrupted Gerbicz checkpoint hash chain')
            prev_h = chk['hash']

    # Prover MUST provide proof_steps; verifier NEVER computes midpoints for workers
    proof_steps = proof_data.get('proof_steps')
    require(isinstance(proof_steps, list), 'valid proof_steps required')
    require(len(proof_steps) >= 1, 'prover must supply at least one folding step')
    require(len(proof_steps) <= 64, 'proof_steps exceeds maximum depth')

    v_X = 3
    v_Y = (3 * y) % N
    v_T = p - 1

    for step in proof_steps:
        require(isinstance(step, dict) and 'Z' in step and 'odd' in step, 'step dict required')
        Z = int(step['Z'], 16)
        require(0 <= Z < N, 'bounded midpoint Z required')
        if step['odd']:
            v_X = (v_X * v_X) % N
            v_T -= 1
        half = v_T // 2
        h = hashlib.sha256(f"{v_X}:{v_Y}:{Z}:{N}".encode()).hexdigest()
        r = int(h[:16], 16)
        v_X = (pow(v_X, r, N) * Z) % N
        v_Y = (pow(Z, r, N) * v_Y) % N
        v_T = half

    # Remaining squarings must be bounded to O(depth) cost ceiling (<= 4096 squarings)
    require(v_T <= 4096, 'remaining squarings exceed verifier cost ceiling')
    final_s = v_X
    for _ in range(v_T):
        final_s = (final_s * final_s) % N
    require(final_s == v_Y, 'Pietrzak Proof of Exponentiation check failed')
    return True
    for _ in range(v_T):
        final_s = (final_s * final_s) % N
    require(final_s == v_Y, 'Pietrzak Proof of Exponentiation check failed')
    return True


def init_schema(db):
    db.execute("""
    CREATE TABLE IF NOT EXISTS gimps_tasks (
        engine_id TEXT NOT NULL,
        problem_set_id TEXT NOT NULL,
        exponent INTEGER NOT NULL,
        state TEXT NOT NULL,
        assigned_to TEXT,
        assigned_at INTEGER,
        lease_timeout INTEGER,
        proof_tx_hash TEXT,
        checkpoint_json TEXT,
        last_heartbeat INTEGER,
        math_certified INTEGER DEFAULT 0,
        primenet_status TEXT DEFAULT 'unsubmitted',
        corium_settled INTEGER DEFAULT 0,
        PRIMARY KEY (engine_id, exponent)
    )
    """)
    db.execute("CREATE INDEX IF NOT EXISTS idx_gimps_tasks_state ON gimps_tasks(engine_id, state)")
    # Migration helper for existing databases:
    existing_cols = {row[1] for row in db.execute("PRAGMA table_info(gimps_tasks)").fetchall()}
    for col, col_type, default in [
        ('checkpoint_json', 'TEXT', None),
        ('last_heartbeat', 'INTEGER', None),
        ('math_certified', 'INTEGER', '0'),
        ('primenet_status', 'TEXT', "'unsubmitted'"),
        ('corium_settled', 'INTEGER', '0')
    ]:
        if col not in existing_cols:
            db.execute(f"ALTER TABLE gimps_tasks ADD COLUMN {col} {col_type}" + (f" DEFAULT {default}" if default else ""))


def renew_lease(db, engine_id, exponent, worker_id, progress_pct=None, checkpoint_data=None, lease_duration=DEFAULT_LEASE_SECONDS, current_time=None):
    init_schema(db)
    if current_time is None:
        current_time = int(time.time())
    row = db.execute(
        "SELECT state, assigned_to, lease_timeout FROM gimps_tasks WHERE engine_id=? AND exponent=?",
        (engine_id, exponent)
    ).fetchone()
    require(row is not None, "task not found")
    state, assigned_to, lease_timeout = row[0], row[1], row[2]
    if state == 'assigned':
        require(assigned_to == worker_id, "task assigned to different worker")
        require(lease_timeout is None or lease_timeout > current_time, "lease already expired")
    elif state == 'paused':
        require(assigned_to == worker_id, "task paused by different worker")
    else:
        raise ValueError(f"cannot renew lease in state {state}")

    new_timeout = current_time + lease_duration
    chk_str = json.dumps(checkpoint_data) if checkpoint_data is not None else None
    if chk_str is not None:
        db.execute(
            "UPDATE gimps_tasks SET lease_timeout=?, last_heartbeat=?, checkpoint_json=? WHERE engine_id=? AND exponent=?",
            (new_timeout, current_time, chk_str, engine_id, exponent)
        )
    else:
        db.execute(
            "UPDATE gimps_tasks SET lease_timeout=?, last_heartbeat=? WHERE engine_id=? AND exponent=?",
            (new_timeout, current_time, engine_id, exponent)
        )
    return {
        'status': 'renewed',
        'engine_id': engine_id,
        'exponent': exponent,
        'assigned_to': worker_id,
        'lease_timeout': new_timeout,
        'last_heartbeat': current_time
    }


def pause_task(db, engine_id, exponent, worker_id, checkpoint_data=None, current_time=None):
    init_schema(db)
    if current_time is None:
        current_time = int(time.time())
    row = db.execute(
        "SELECT state, assigned_to, lease_timeout FROM gimps_tasks WHERE engine_id=? AND exponent=?",
        (engine_id, exponent)
    ).fetchone()
    require(row is not None, "task not found")
    state, assigned_to = row[0], row[1]
    require(state == 'assigned', f"task not in assigned state (state={state})")
    require(assigned_to == worker_id, "task assigned to different worker")

    chk_str = json.dumps(checkpoint_data) if checkpoint_data is not None else None
    if chk_str is not None:
        db.execute(
            "UPDATE gimps_tasks SET state='paused', last_heartbeat=?, checkpoint_json=? WHERE engine_id=? AND exponent=?",
            (current_time, chk_str, engine_id, exponent)
        )
    else:
        db.execute(
            "UPDATE gimps_tasks SET state='paused', last_heartbeat=? WHERE engine_id=? AND exponent=?",
            (current_time, engine_id, exponent)
        )
    return {
        'status': 'paused',
        'engine_id': engine_id,
        'exponent': exponent,
        'assigned_to': worker_id,
        'last_heartbeat': current_time
    }


def resume_task(db, engine_id, exponent, worker_id, lease_duration=DEFAULT_LEASE_SECONDS, current_time=None):
    init_schema(db)
    if current_time is None:
        current_time = int(time.time())
    row = db.execute(
        "SELECT state, assigned_to, checkpoint_json FROM gimps_tasks WHERE engine_id=? AND exponent=?",
        (engine_id, exponent)
    ).fetchone()
    require(row is not None, "task not found")
    state, assigned_to, checkpoint_json = row[0], row[1], row[2]
    require(state in ('paused', 'retry'), f"task cannot be resumed from state {state}")

    new_timeout = current_time + lease_duration
    db.execute(
        "UPDATE gimps_tasks SET state='assigned', assigned_to=?, assigned_at=?, lease_timeout=?, last_heartbeat=? WHERE engine_id=? AND exponent=?",
        (worker_id, current_time, new_timeout, current_time, engine_id, exponent)
    )
    checkpoint = json.loads(checkpoint_json) if checkpoint_json else None
    return {
        'status': 'resumed',
        'engine_id': engine_id,
        'exponent': exponent,
        'assigned_to': worker_id,
        'lease_timeout': new_timeout,
        'checkpoint': checkpoint
    }


def update_primenet_status(db, engine_id, exponent, status, attestation=None):
    init_schema(db)
    require(status in ('unsubmitted', 'submitted', 'accepted', 'rejected'), f"invalid primenet status: {status}")
    db.execute(
        "INSERT INTO gimps_tasks (engine_id, problem_set_id, exponent, state, primenet_status) "
        "VALUES (?, '', ?, 'assigned', ?) "
        "ON CONFLICT(engine_id, exponent) DO UPDATE SET primenet_status=excluded.primenet_status",
        (engine_id, exponent, status)
    )
    return {
        'engine_id': engine_id,
        'exponent': exponent,
        'primenet_status': status,
        'attestation': attestation
    }


def candidates(metadata):
    """Bound native verification work and search prime exponents only."""
    if isinstance(metadata, str):
        metadata = json.loads(metadata)
    require(type(metadata) is dict, 'problem set metadata required')
    method = metadata.get('method', 'lucas-lehmer')
    max_bound = MAX_PRP_EXPONENT if method in ('prp', 'prp-fiat-shamir') else MAX_LL_EXPONENT
    start = integer(metadata.get('start_exponent'), 2, max_bound)
    end = integer(metadata.get('end_exponent'), start, max_bound)
    return (p for p in range(start, end + 1) if all(p % d for d in range(2, int(p**0.5) + 1)))


def native_challenge(db, network, submitter):
    """Read-only native GIMPS selection; never falls back to another engine."""
    row = db.execute("SELECT value FROM chain_state WHERE key='chain_info'").fetchone()
    require(row and type(row[0]) is str, 'accepted native head required')
    head = row[0].split('|')
    require(len(head) == 2 and re.fullmatch('[a-f0-9]{64}', head[0]) and head[1].isdigit(), 'canonical native head required')
    height = int(head[1])
    require(db.execute('SELECT 1 FROM blocks WHERE hash=? AND height=?', (head[0], height)).fetchone(), 'accepted head must exist')
    base = {
        'schema': 'corium.gimps-challenge.v1',
        'network_id': network,
        'submitter_id': submitter,
        'height': height,
        'block_hash': head[0],
        'proof_schema': PORTABLE_SCHEMA,
        'supported_schemas': [PORTABLE_SCHEMA, PRP_SCHEMA],
        'method': 'lucas-lehmer',
        'supported_methods': ['lucas-lehmer', 'prp-fiat-shamir'],
        'max_ll_exponent': MAX_LL_EXPONENT,
        'max_prp_exponent': MAX_PRP_EXPONENT,
        'max_exponent': MAX_PRP_EXPONENT
    }
    engines = db.execute('SELECT engine_id,compute_program_hash,verifier_script_hash FROM compute_engines WHERE pkg_id=? AND is_active=1 ORDER BY engine_id', (PACKAGE,)).fetchall()
    for engine, program, verifier in engines:
        problem = db.execute('SELECT set_id,metadata FROM problem_sets WHERE engine_id=? AND activation_height<=? ORDER BY activation_height DESC,set_id LIMIT 1', (engine, height)).fetchone()
        if not problem:
            continue
        blocked = {str(row[0]) for row in db.execute('SELECT problem_id FROM completed_compute_tasks WHERE engine_id=?', (engine,))}
        blocked.update(str(row[0]) for row in db.execute("SELECT json_extract(data,'$.problem_id') FROM transactions WHERE type='submit_math_proof' AND block_height IS NULL AND json_extract(data,'$.engine_id')=?", (engine,)))
        blocked.update(str(row[0]) for row in db.execute("SELECT p.problem_id FROM pending_proofs p JOIN transactions t ON t.hash=p.proof_tx_hash WHERE json_extract(t.data,'$.engine_id')=?", (engine,)))
        if db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='gimps_tasks'").fetchone():
            blocked.update(str(row[0]) for row in db.execute("SELECT exponent FROM gimps_tasks WHERE engine_id=? AND state='assigned' AND lease_timeout>?", (engine, int(time.time()))))
            blocked.update(str(row[0]) for row in db.execute("SELECT exponent FROM gimps_tasks WHERE engine_id=? AND state='paused'", (engine,)))
        for exponent in candidates(problem[1]):
            if str(exponent) not in blocked:
                return dict(base, available=True, engine_id=engine, problem_set_id=problem[0], problem_id=str(exponent),
                            exponent=exponent, engine_hash=program, verifier_hash=verifier)
    return dict(base, available=False, reason='no-active-gimps-engine' if not engines else 'no-available-gimps-task')


def reconcile_task_states(db, engine_id, set_id, start_exp, end_exp, current_time=None):
    """Reconcile task state machine from the blockchain tables."""
    init_schema(db)
    if current_time is None:
        current_time = int(time.time())
    # Derived states must follow the canonical tables after replay/reorganization.
    db.execute("UPDATE gimps_tasks SET state='retry',proof_tx_hash=NULL WHERE engine_id=? AND state IN ('settled','verified','submitted','failed')", (engine_id,))

    # 1. Settled tasks from completed_compute_tasks
    completed_rows = db.execute(
        "SELECT problem_id, proof_tx_hash FROM completed_compute_tasks WHERE engine_id=?",
        (engine_id,)
    ).fetchall()
    for row in completed_rows:
        try:
            exp = int(row[0])
            if start_exp <= exp <= end_exp:
                db.execute(
                    "INSERT INTO gimps_tasks (engine_id, problem_set_id, exponent, state, proof_tx_hash, math_certified, corium_settled) "
                    "VALUES (?, ?, ?, 'settled', ?, 1, 1) "
                    "ON CONFLICT(engine_id, exponent) DO UPDATE SET state='settled', proof_tx_hash=excluded.proof_tx_hash, math_certified=1, corium_settled=1",
                    (engine_id, set_id, exp, row[1])
                )
        except (ValueError, TypeError):
            continue

    # 2. Verified / pending confirmation tasks from pending_proofs
    pending_rows = db.execute(
        "SELECT p.problem_id, p.proof_tx_hash FROM pending_proofs p "
        "JOIN transactions t ON t.hash=p.proof_tx_hash "
        "WHERE json_extract(t.data, '$.engine_id')=?",
        (engine_id,)
    ).fetchall()
    for row in pending_rows:
        try:
            exp = int(row[0])
            if start_exp <= exp <= end_exp:
                cur = db.execute("SELECT state FROM gimps_tasks WHERE engine_id=? AND exponent=?", (engine_id, exp)).fetchone()
                if not cur or cur[0] != 'settled':
                    db.execute(
                        "INSERT INTO gimps_tasks (engine_id, problem_set_id, exponent, state, proof_tx_hash, math_certified) "
                        "VALUES (?, ?, ?, 'verified', ?, 1) "
                        "ON CONFLICT(engine_id, exponent) DO UPDATE SET state='verified', proof_tx_hash=excluded.proof_tx_hash, math_certified=1",
                        (engine_id, set_id, exp, row[1])
                    )
        except (ValueError, TypeError):
            continue

    # 3. Submitted unconfirmed transactions in mempool
    mempool_rows = db.execute(
        "SELECT hash, json_extract(data, '$.problem_id') FROM transactions "
        "WHERE type='submit_math_proof' AND block_height IS NULL AND json_extract(data, '$.engine_id')=?",
        (engine_id,)
    ).fetchall()
    for row in mempool_rows:
        try:
            exp = int(row[1])
            if start_exp <= exp <= end_exp:
                cur = db.execute("SELECT state FROM gimps_tasks WHERE engine_id=? AND exponent=?", (engine_id, exp)).fetchone()
                if not cur or cur[0] not in ('settled', 'verified'):
                    db.execute(
                        "INSERT INTO gimps_tasks (engine_id, problem_set_id, exponent, state, proof_tx_hash) "
                        "VALUES (?, ?, ?, 'submitted', ?) "
                        "ON CONFLICT(engine_id, exponent) DO UPDATE SET state='submitted', proof_tx_hash=excluded.proof_tx_hash",
                        (engine_id, set_id, exp, row[0])
                    )
        except (ValueError, TypeError):
            continue

    # 4. Failed/challenged tasks
    failed_rows = db.execute(
        "SELECT c.target_proof_tx_hash, json_extract(t.data, '$.problem_id') "
        "FROM challenges c JOIN transactions t ON t.hash=c.target_proof_tx_hash "
        "WHERE c.status='confirmed' AND json_extract(t.data, '$.engine_id')=?",
        (engine_id,)
    ).fetchall()
    for row in failed_rows:
        try:
            exp = int(row[1])
            if start_exp <= exp <= end_exp:
                cur = db.execute("SELECT state,proof_tx_hash FROM gimps_tasks WHERE engine_id=? AND exponent=?", (engine_id, exp)).fetchone()
                if not cur or cur[0] != 'settled':
                    db.execute(
                        "INSERT INTO gimps_tasks (engine_id, problem_set_id, exponent, state, proof_tx_hash) "
                        "VALUES (?, ?, ?, 'failed', ?) "
                        "ON CONFLICT(engine_id, exponent) DO UPDATE SET state='failed', proof_tx_hash=excluded.proof_tx_hash",
                        (engine_id, set_id, exp, row[0])
                    )
        except (ValueError, TypeError):
            continue

    # 5. Expired assignments -> transition to retry (tasks in paused state retain checkpoint)
    db.execute(
        "UPDATE gimps_tasks SET state='retry' "
        "WHERE engine_id=? AND state='assigned' AND lease_timeout IS NOT NULL AND lease_timeout <= ?",
        (engine_id, current_time)
    )


def generate_next_gimps_task(db, engine_id, set_id, metadata, current_time=None):
    """Deterministic, state-machine driven task generator for GIMPS problem sets."""
    if isinstance(metadata, str):
        try:
            metadata = json.loads(metadata)
        except Exception:
            return None
    method = metadata.get('method', 'lucas-lehmer')
    max_bound = MAX_PRP_EXPONENT if method in ('prp', 'prp-fiat-shamir') else MAX_LL_EXPONENT
    start_exp = integer(metadata.get('start_exponent', 0), 2, max_bound)
    end_exp = integer(metadata.get('end_exponent', 0), start_exp, max_bound)
    if start_exp <= 0 or end_exp < start_exp:
        return None

    if current_time is None:
        current_time = int(time.time())

    reconcile_task_states(db, engine_id, set_id, start_exp, end_exp, current_time)

    # Find the next available exponent in [start_exp, end_exp]
    for p in candidates({'start_exponent': start_exp, 'end_exponent': end_exp, 'method': method}):
        row = db.execute(
            "SELECT state, lease_timeout FROM gimps_tasks WHERE engine_id=? AND exponent=?",
            (engine_id, p)
        ).fetchone()

        # Check if already completed, active, or paused
        if row:
            st = row[0]
            if st in ('settled', 'verified', 'submitted', 'paused'):
                continue
            if st == 'assigned' and row[1] and row[1] > current_time:
                # Active lease held by worker
                continue

        # Found available exponent p (either unassigned, retry, failed, or expired)
        lease_duration = metadata.get('lease_seconds', DEFAULT_LEASE_SECONDS) if isinstance(metadata, dict) else DEFAULT_LEASE_SECONDS
        timeout = current_time + lease_duration
        db.execute(
            "INSERT INTO gimps_tasks (engine_id, problem_set_id, exponent, state, assigned_at, lease_timeout, last_heartbeat) "
            "VALUES (?, ?, ?, 'assigned', ?, ?, ?) "
            "ON CONFLICT(engine_id, exponent) DO UPDATE SET state='assigned', assigned_at=excluded.assigned_at, lease_timeout=excluded.lease_timeout, last_heartbeat=excluded.last_heartbeat, proof_tx_hash=NULL",
            (engine_id, set_id, p, current_time, timeout, current_time)
        )
        return f"{p}|{p}"

    return None


def validate_gimps_proof(db, network, payload, sender, height, accepted_tx=None):
    """Validate GIMPS proof format, mathematical bounds, and duplicate rules."""
    require(isinstance(payload, dict), 'payload dictionary required')
    engine_id = payload.get('engine_id')
    problem_id = payload.get('problem_id')
    proof_data = payload.get('proof_data', {})
    require(engine_id and problem_id is not None, 'engine_id and problem_id required')
    require(type(proof_data) is dict, 'proof_data must be dictionary')

    # Verify engine is registered and active
    row = db.execute(
        "SELECT pkg_id, is_active, reward_weight FROM compute_engines WHERE engine_id=?",
        (engine_id,)
    ).fetchone()
    require(row is not None and row[1] == 1, 'engine must be active on-chain')
    require(row[0] == PACKAGE, 'engine package must be corium/built-in-gimps')
    weight = row[2] if len(row) > 2 and row[2] is not None else 100

    integer(weight, 0, MAX_INTEGER // 100)
    integer(height, 0, MAX_INTEGER)
    require(type(problem_id) is str and re.fullmatch(r'[1-9][0-9]{0,9}', problem_id), 'canonical exponent string required')
    proof_schema = proof_data.get('schema')
    is_prp_schema = (proof_schema == PRP_SCHEMA)
    max_bound = MAX_PRP_EXPONENT if is_prp_schema else MAX_LL_EXPONENT
    p = integer(int(problem_id), 2, max_bound)

    active = db.execute('SELECT metadata FROM problem_sets WHERE engine_id=? AND activation_height<=?', (engine_id, height)).fetchall()
    assigned_range = False
    for item in active:
        meta = json.loads(item[0])
        start, end = meta.get('start_exponent'), meta.get('end_exponent')
        m_method = meta.get('method', 'lucas-lehmer')
        m_max = MAX_PRP_EXPONENT if m_method in ('prp', 'prp-fiat-shamir') else MAX_LL_EXPONENT
        if type(start) is int and type(end) is int and 2 <= start <= p <= end <= m_max:
            assigned_range = True
    require(assigned_range, 'exponent must belong to an active bounded problem set')

    # Duplicate submission / Double redeem check
    completed = db.execute(
        "SELECT proof_tx_hash FROM completed_compute_tasks WHERE engine_id=? AND problem_id=?",
        (engine_id, str(p))
    ).fetchall()
    pending = db.execute(
        "SELECT p.proof_tx_hash FROM pending_proofs p "
        "JOIN transactions t ON t.hash=p.proof_tx_hash "
        "WHERE p.problem_id=? AND json_extract(t.data, '$.engine_id')=?",
        (str(p), engine_id)
    ).fetchall()

    for r in completed + pending:
        if accepted_tx is None or r[0] != accepted_tx:
            raise ValueError(f'exponent {p} already settled or pending confirmation')

    if proof_schema == PRP_SCHEMA:
        # Bounded PRP Proof of Exponentiation with Fiat-Shamir folding
        verify_prp_proof(p, proof_data)
        math_certified = True
        method = 'prp-fiat-shamir'
    elif proof_schema in {SCHEMA, PORTABLE_SCHEMA}:
        # Lucas-Lehmer verification
        exact(proof_data, {'schema', 'exponent', 'method', 'residue', 'is_prime', 'iterations'})
        require(type(proof_data['exponent']) is int and proof_data['exponent'] == p, 'proof exponent mismatch')
        require(proof_data['method'] == 'lucas-lehmer', 'unimplemented proof method rejected')
        require(type(proof_data['iterations']) is int and proof_data['iterations'] == p - 2, 'exact iteration count required')
        require(type(proof_data['is_prime']) is bool, 'boolean primality claim required')
        residue = proof_data['residue']
        if proof_schema == PORTABLE_SCHEMA:
            require(type(residue) is str and re.fullmatch(r'0|[1-9][0-9]{0,1233}', residue), 'canonical decimal residue required')
            residue = int(residue)
        require(type(residue) is int and 0 <= residue < (1 << p) - 1, 'bounded integer residue required')
        valid, expected = lucas_lehmer_verify(p, residue)
        require(valid, 'invalid Lucas-Lehmer residue')
        prime_exponent = all(p % divisor for divisor in range(2, int(p**0.5) + 1))
        require(proof_data['is_prime'] == (prime_exponent and expected == 0), 'primality claim mismatch')
        math_certified = True
        method = 'lucas-lehmer'
    else:
        # Legacy format without schema
        exact(proof_data, {'residue'})
        residue = proof_data['residue']
        require(type(residue) is int and 0 <= residue < (1 << p) - 1, 'bounded integer residue required')
        valid, expected = lucas_lehmer_verify(p, residue)
        require(valid, 'invalid Lucas-Lehmer residue')
        math_certified = True
        method = 'lucas-lehmer'

    # Retrieve current PrimeNet attestation status if present
    primenet_status = 'unsubmitted'
    try:
        pnet_row = db.execute("SELECT primenet_status FROM gimps_tasks WHERE engine_id=? AND exponent=?", (engine_id, p)).fetchone()
        if pnet_row and pnet_row[0]:
            primenet_status = pnet_row[0]
    except Exception:
        pass

    return {
        'status': 'valid',
        'math_certified': math_certified,
        'primenet_status': primenet_status,
        'corium_settled': False,
        'engine_id': engine_id,
        'problem_id': str(p),
        'exponent': p,
        'method': method,
        'reward': 100 * weight,
        'reward_weight': weight,
        'proposer_id': sender
    }


def settle(db, network, tx, height):
    """Settle an unchallenged confirmed GIMPS proof, crediting contribution scores."""
    row = db.execute(
        "SELECT data, public_key, block_height FROM transactions "
        "WHERE hash=? AND type='submit_math_proof' AND block_height IS NOT NULL",
        (tx,)
    ).fetchone()
    require(row is not None, 'confirmed native proof required')
    payload = json.loads(row[0])
    sender = hashlib.sha256(row[1].encode()).hexdigest()

    val = validate_gimps_proof(db, network, payload, sender, row[2], accepted_tx=tx)
    engine_id = val['engine_id']
    problem_id = val['problem_id']
    reward = val['reward']

    # Check if already redeemed
    done = db.execute(
        "SELECT proof_tx_hash FROM completed_compute_tasks WHERE engine_id=? AND problem_id=?",
        (engine_id, problem_id)
    ).fetchone()
    if done:
        require(done[0] == tx, 'bounty already redeemed')
        return val | {'duplicate': True, 'corium_settled': True}

    # Verify pending state and 10-block challenge window
    pending = db.execute(
        "SELECT problem_id, proof_tx_hash, proposer_id, proposed_result, confirmation_deadline_height FROM pending_proofs WHERE proof_tx_hash=?",
        (tx,)
    ).fetchone()
    require(pending is not None, 'matching pending proof required')
    p_prob = pending[0] if isinstance(pending, tuple) else pending['problem_id']
    p_proposer = pending[2] if isinstance(pending, tuple) else pending['proposer_id']
    p_deadline = pending[4] if isinstance(pending, tuple) else pending['confirmation_deadline_height']
    require(p_proposer == sender and p_prob == problem_id, 'matching pending proof required')
    require(p_deadline == row[2] + 10 and height >= p_deadline, 'native challenge window must elapse')

    # Check no active unrejected challenge
    require(db.execute(
        "SELECT 1 FROM challenges WHERE target_proof_tx_hash=? AND status!='rejected'",
        (tx,)
    ).fetchone() is None, 'challenged proof cannot settle on unchallenged path')

    # Update contribution_scores
    prior = db.execute("SELECT score FROM contribution_scores WHERE user_id=?", (sender,)).fetchone()
    score = prior[0] if prior else 0
    integer(score, -MAX_INTEGER - 1, MAX_INTEGER - reward)

    db.execute(
        "INSERT INTO completed_compute_tasks (engine_id, problem_id, proof_tx_hash) VALUES (?, ?, ?)",
        (engine_id, problem_id, tx)
    )
    db.execute(
        "INSERT INTO contribution_scores (user_id, score, last_update_height) VALUES (?, ?, ?) "
        "ON CONFLICT(user_id) DO UPDATE SET score=score+?, last_update_height=excluded.last_update_height",
        (sender, score + reward, height, reward)
    )
    db.execute("DELETE FROM pending_proofs WHERE proof_tx_hash=?", (tx,))

    # Update gimps_tasks state machine to settled
    try:
        p = int(problem_id)
        db.execute(
            "UPDATE gimps_tasks SET state='settled', proof_tx_hash=?, math_certified=1, corium_settled=1 WHERE engine_id=? AND exponent=?",
            (tx, engine_id, p)
        )
    except Exception:
        pass

    return val | {
        'settled_height': height,
        'contribution_score': score + reward,
        'reward_awarded': reward,
        'corium_settled': True
    }


def validate_challenge(db, network, target_tx):
    """Validate challenge against a GIMPS proof.
    Returns 1 if proof is valid (challenge fails), 0 if proof is invalid (challenge succeeds).
    """
    row = db.execute(
        "SELECT data, public_key, block_height FROM transactions WHERE hash=? AND type='submit_math_proof'",
        (target_tx,)
    ).fetchone()
    if not row:
        return 0
    payload = json.loads(row[0])
    sender = hashlib.sha256(row[1].encode()).hexdigest()
    try:
        validate_gimps_proof(db, network, payload, sender, row[2] or 1, accepted_tx=target_tx)
        return 1
    except Exception:
        return 0


def main(args):
    action = args[0]
    database = args[1]
    with closing(sqlite3.connect(database)) as db, db:
        db.row_factory = sqlite3.Row
        if action == 'next-task':
            db.execute('BEGIN IMMEDIATE')
            engine_id, set_id, metadata = args[2:5]
            res = generate_next_gimps_task(db, engine_id, set_id, metadata)
            if res:
                print(res)
            else:
                sys.exit(1)
        elif action == 'challenge':
            network, submitter = args[2:4]
            print(json.dumps(native_challenge(db, network, submitter), sort_keys=True))
        elif action == 'solve':
            network, engine, problem, sender = args[2:6]
            method = args[6] if len(args) > 6 else 'lucas-lehmer'
            max_bound = MAX_PRP_EXPONENT if method in ('prp', 'prp-fiat-shamir') else MAX_LL_EXPONENT
            exponent = integer(int(problem), 2, max_bound)
            require(exponent in candidates({'start_exponent': exponent, 'end_exponent': exponent, 'method': method}), 'prime exponent required')
            if method == 'prp' or method == 'prp-fiat-shamir':
                proof_data = generate_prp_proof(exponent, base=3, depth=4)
            else:
                _, residue = lucas_lehmer_verify(exponent, 0)
                proof_data = {
                    'schema': PORTABLE_SCHEMA,
                    'exponent': exponent,
                    'method': 'lucas-lehmer',
                    'residue': str(residue),
                    'is_prime': residue == 0,
                    'iterations': exponent - 2
                }
            payload = {'engine_id': engine, 'problem_id': str(exponent), 'proof_data': proof_data}
            head = db.execute("SELECT value FROM chain_state WHERE key='chain_info'").fetchone()
            require(head is not None, 'native accepted head required')
            validate_gimps_proof(db, network, payload, sender, int(head[0].split('|')[1]))
            print(json.dumps(payload, sort_keys=True))
        elif action == 'validate':
            network, payload_raw, sender, height = args[2:6]
            accepted_tx = args[6] if len(args) > 6 else None
            payload = json.loads(payload_raw)
            res = validate_gimps_proof(db, network, payload, sender, int(height), accepted_tx=accepted_tx)
            print(json.dumps(res, sort_keys=True))
        elif action == 'settle':
            network, tx, height = args[2:5]
            db.execute('BEGIN IMMEDIATE')
            res = settle(db, network, tx, int(height))
            print(json.dumps(res, sort_keys=True))
        elif action == 'validate-challenge':
            network, target_tx = args[2:4]
            code = validate_challenge(db, network, target_tx)
            print(code)
            if code == 0:
                sys.exit(0)  # Challenge succeeded
            else:
                sys.exit(0)  # Output is 1 or 0
        elif action == 'renew-lease':
            engine_id, exponent, worker_id = args[2:5]
            chk = json.loads(args[5]) if len(args) > 5 and args[5] else None
            dur = int(args[6]) if len(args) > 6 and args[6] else DEFAULT_LEASE_SECONDS
            db.execute('BEGIN IMMEDIATE')
            res = renew_lease(db, engine_id, int(exponent), worker_id, checkpoint_data=chk, lease_duration=dur)
            print(json.dumps(res, sort_keys=True))
        elif action == 'pause-task':
            engine_id, exponent, worker_id = args[2:5]
            chk = json.loads(args[5]) if len(args) > 5 and args[5] else None
            db.execute('BEGIN IMMEDIATE')
            res = pause_task(db, engine_id, int(exponent), worker_id, checkpoint_data=chk)
            print(json.dumps(res, sort_keys=True))
        elif action == 'resume-task':
            engine_id, exponent, worker_id = args[2:5]
            dur = int(args[5]) if len(args) > 5 and args[5] else DEFAULT_LEASE_SECONDS
            db.execute('BEGIN IMMEDIATE')
            res = resume_task(db, engine_id, int(exponent), worker_id, lease_duration=dur)
            print(json.dumps(res, sort_keys=True))
        elif action == 'update-primenet':
            engine_id, exponent, status = args[2:5]
            attestation = args[5] if len(args) > 5 else None
            db.execute('BEGIN IMMEDIATE')
            res = update_primenet_status(db, engine_id, int(exponent), status, attestation=attestation)
            print(json.dumps(res, sort_keys=True))
        elif action == 'generate-prp':
            exponent = int(args[2])
            depth = int(args[3]) if len(args) > 3 else 4
            res = generate_prp_proof(exponent, base=3, depth=depth)
            print(json.dumps(res, sort_keys=True))
        elif action == 'verify-prp':
            exponent = int(args[2])
            proof_data = json.loads(args[3])
            ok = verify_prp_proof(exponent, proof_data)
            print(json.dumps({'verified': ok}, sort_keys=True))
        else:
            raise ValueError(f"unknown gimps action: {action}")


if __name__ == '__main__':
    main(sys.argv[1:])
PY_CORIUM_GIMPS_CONSENSUS
)

_corium_transaction_bytes() {
    case "$CORIUM_NETWORK_ID" in
        ziokt-main-recovery-20261024|ziokt-dna-side-20261024)
            _corium_work_consensus transaction-bytes "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$1" "$2" "$3" "$4" "$5"
            ;;
        *) printf '{"type":"%s","data":%s,"timestamp":%s}' "$1" "$2" "$3" ;;
    esac
}

_validate_single_transaction() {
    local tx_hash="$1"
    local peer_ip="$2"
    local peer_port="$3"
    local block_height="$4"
    declare -n intra_block_state_tracker="$5" # 短生命周期状态跟踪器 / Short-lived state tracker
    declare -n reorg_cache="$6"              # 长生命周期内存缓存 / Long-lived in-memory cache

    [[ "$tx_hash" =~ ^[a-f0-9]{64}$ ]] || return 1
    # Stateful authorization must be evaluated against the current branch every time.
    # 权限验证依赖当前分支状态，不能复用另一状态下的成功结果。
    # --- 步骤 1: 获取交易数据 (本地或从网络) ---
    # --- Step 1: Fetch transaction data (local or from network) ---
    local tx_db_entry
    tx_db_entry=$(db_query_safe "$BLOCKCHAIN_DB" \
        "SELECT json_array(type, data, signature, public_key, timestamp) FROM transactions WHERE hash = %s;" \
        "$tx_hash")

    if [ -z "$tx_db_entry" ]; then
        detail "    - 交易 '$tx_hash' 在本地缺失，从网络获取... (Transaction '$tx_hash' missing locally, fetching from network...)"
        local fetched_tx_path
        fetched_tx_path=$(mktemp)
        CORIUM_TEMP_ITEMS+=("$fetched_tx_path")

        if ! _p2p_download_object "$tx_hash" "$fetched_tx_path"; then
            warn "      ! 无法获取交易 '$tx_hash'。验证失败。 (! Could not fetch transaction '$tx_hash'. Validation failed.)"
            reorg_cache["$tx_hash"]="invalid"; return 1
        fi
        
        local tx_json tx_type tx_data tx_signature tx_pubkey tx_timestamp
        tx_json=$(cat "$fetched_tx_path")
        
        tx_type=$(echo "$tx_json" | jq -r .type 2>/dev/null)
        tx_data=$(echo "$tx_json" | jq -c .data 2>/dev/null)
        tx_signature=$(echo "$tx_json" | jq -r .signature 2>/dev/null)
        tx_pubkey=$(echo "$tx_json" | jq -r .public_key 2>/dev/null)
        tx_timestamp=$(echo "$tx_json" | jq -r .timestamp 2>/dev/null)

        if [ -z "$tx_type" ] || [ -z "$tx_data" ] || [ -z "$tx_signature" ] || [ -z "$tx_pubkey" ] || [ -z "$tx_timestamp" ]; then
            warn "      ! 获取到的交易文件格式无效或不完整。 (! Fetched transaction file is malformed or incomplete.)"
            reorg_cache["$tx_hash"]="invalid"; return 1
        fi
        
        local data_to_verify
        data_to_verify=$(_corium_transaction_bytes "$tx_type" "$tx_data" "$tx_timestamp" "$tx_pubkey" "$block_height") || return 1
        local calculated_tx_hash
        calculated_tx_hash=$(_internal_hash_text "$data_to_verify")

        if [ "$calculated_tx_hash" != "$tx_hash" ]; then
            warn "      ! 获取到的交易内容哈希与预期不符！可能已被篡改。 (Hash of fetched transaction content does not match expected! Possible tampering.)"
            reorg_cache["$tx_hash"]="invalid"; return 1
        fi
        
        db_execute_safe "$BLOCKCHAIN_DB" \
            "INSERT OR IGNORE INTO transactions (hash, type, data, signature, public_key, timestamp, block_height) VALUES (%s, %s, %s, %s, %s, %d, NULL);" \
            "$tx_hash" "$tx_type" "$tx_data" "$tx_signature" "$tx_pubkey" "$tx_timestamp"
        
        tx_db_entry=$(jq -cn --arg type "$tx_type" --arg data "$tx_data" --arg sig "$tx_signature" --arg pk "$tx_pubkey" --arg ts "$tx_timestamp" '[$type,$data,$sig,$pk,$ts]')
    fi
    
    # --- 步骤 2: 签名与身份验证 ---
    # --- Step 2: Signature & Identity Verification ---
    local tx_payload
    local tx_type tx_signature tx_pubkey tx_timestamp
    tx_type=$(jq -er '.[0]' <<< "$tx_db_entry") || return 1
    tx_payload=$(jq -er '.[1]' <<< "$tx_db_entry") || return 1
    tx_signature=$(jq -er '.[2]' <<< "$tx_db_entry") || return 1
    tx_pubkey=$(jq -er '.[3]' <<< "$tx_db_entry") || return 1
    tx_timestamp=$(jq -er '.[4]' <<< "$tx_db_entry") || return 1
    
    local data_to_verify
    data_to_verify=$(_corium_transaction_bytes "$tx_type" "$tx_payload" "$tx_timestamp" "$tx_pubkey" "$block_height") || return 1
    
    [[ "$tx_timestamp" =~ ^[0-9]{1,19}$ && "$tx_type" =~ ^[a-zA-Z][a-zA-Z0-9_-]*$ ]] || return 1
    [ "$(_internal_hash_text "$data_to_verify")" = "$tx_hash" ] || return 1
    local temp_pubkey_file
    temp_pubkey_file=$(mktemp)
    CORIUM_TEMP_ITEMS+=("$temp_pubkey_file")
    echo -n "$tx_pubkey" > "$temp_pubkey_file"
    if ! verify_signature "$data_to_verify" "$tx_signature" "$temp_pubkey_file"; then
        warn "      ! 交易 '$tx_hash' 签名无效！ (! Transaction '$tx_hash' signature is invalid!)"
        reorg_cache["$tx_hash"]="invalid"; return 1
    fi
    
    local sender_id
    sender_id=$(_internal_hash_text "$tx_pubkey")

    # --- 步骤 3: 分类别的状态与逻辑验证 ---
    # --- Step 3: State & Logic Verification by Type ---
    case "$tx_type" in
        cooperative_command)
            [ -z "${intra_block_state_tracker[cooperative_command]:-}" ] || return 1
            _corium_work_consensus cooperative-validate "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$block_height" "$tx_payload" >/dev/null || return 1
            intra_block_state_tracker[cooperative_command]=1
            ;;
        ziokt_identity_register|ziokt_content|zkn_mint|zkn_transfer|zkn_private_transfer|zkc_issue|zkn_shield_deposit|zkn_shield_transfer|zkn_shield_withdraw|privacy_review_request|privacy_review_vote|privacy_review_revoke|privacy_review_disclose)
            _ziokt_asset_engine validate "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$tx_type" "$tx_payload" "$sender_id" || return 1
            ;;
        # --- [批次三 新增] 有用功证明、治理与纠错机制 ---
        "validator_vote_addition"|"validator_vote_removal"|"vote_app_template"|"vote_ibc_verifier"|"vote_federation_key")
            local proposal expected_type proposal_row vote_height vote_key vote_count
            proposal=$(jq -er '.proposal_tx_hash|select(type=="string" and test("^[a-f0-9]{64}$"))' <<< "$tx_payload") || return 1
            jq -e '.vote=="yes" or .vote=="no"' <<< "$tx_payload" >/dev/null || return 1
            case "$tx_type" in
                validator_vote_addition) expected_type=validator_propose_addition;;
                validator_vote_removal) expected_type=validator_propose_removal;;
                vote_app_template) expected_type=propose_app_template;;
                vote_ibc_verifier) expected_type=propose_ibc_verifier;;
                vote_federation_key) expected_type=propose_federation_key;;
            esac
            proposal_row=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT block_height FROM transactions WHERE hash=%s AND type=%s AND block_height IS NOT NULL;" "$proposal" "$expected_type") || return 1
            [[ "$proposal_row" =~ ^[0-9]+$ ]] && ((block_height>proposal_row && block_height<=proposal_row+100)) || return 1
            [ "$(db_query_safe "$BLOCKCHAIN_DB" "SELECT COUNT(*) FROM validators WHERE public_key_hash=%s AND stake>0 AND status='active';" "$sender_id")" -eq 1 ] || return 1
            vote_count=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT COUNT(*) FROM transactions WHERE type=%s AND public_key=%s AND json_extract(data,'$.proposal_tx_hash')=%s AND block_height IS NOT NULL AND block_height<%d;" "$tx_type" "$tx_pubkey" "$proposal" "$block_height") || return 1
            [ "$vote_count" -eq 0 ] || return 1
            vote_key="vote:${tx_type}:${proposal}:${sender_id}"
            [ -z "${intra_block_state_tracker[$vote_key]:-}" ] || return 1
            intra_block_state_tracker["$vote_key"]=1
            ;;
        "agent_create")
            local agent_id agent_key existing
            agent_id=$(jq -er '.agent_id|select(type=="string" and test("^[a-f0-9]{64}$"))' <<< "$tx_payload") || return 1
            agent_key=$(jq -er '.agent_pubkey|select(type=="string")' <<< "$tx_payload") || return 1
            [ "$(_internal_hash_text "$agent_key")" = "$agent_id" ] || return 1
            local agent_key_file; agent_key_file=$(mktemp) || return 1
            CORIUM_TEMP_ITEMS+=("$agent_key_file"); printf '%s' "$agent_key" > "$agent_key_file"
            _validate_identity_pubkey_file "$agent_key_file" "$agent_id" || return 1
            jq -e '.pkg_id|type=="string" and test("^[A-Za-z0-9][A-Za-z0-9._+/-]*:[A-Za-z0-9._+-]+$")' <<< "$tx_payload" >/dev/null || return 1
            existing=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT COUNT(*) FROM onchain_identities WHERE agent_id=%s;" "$agent_id") || return 1
            [ "$existing" -eq 0 ] && [ -z "${intra_block_state_tracker[agent:$agent_id]:-}" ] || return 1
            intra_block_state_tracker["agent:$agent_id"]=1
            ;;
        "submit_math_proof")
            detail "    - Validating 'submit_math_proof' transaction... / 正在验证 'submit_math_proof' 交易..."
            local problem_id
            problem_id=$(echo "$tx_payload" | jq -r .problem_id 2>/dev/null)
            
            # 验证 1a: 该问题是否正在等待确认？ (防止Mempool/区块内重复)
            # Verification 1a: Is this problem pending confirmation? (Prevents Mempool/intra-block duplicates)
            local pending_proof_count
            pending_proof_count=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT COUNT(*) FROM pending_proofs WHERE problem_id = %s;" "$problem_id")
            if [[ "$pending_proof_count" -gt 0 ]]; then
                warn "      ! 状态验证失败: 问题 '${problem_id}' 的一个证明已在等待确认中。 / ! State validation FAILED: A proof for problem '${problem_id}' is already pending."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi

            # 验证 1b: 该问题是否在历史上已经被最终确认解决了？
            # Verification 1b: Has this problem been finalized and solved historically?
            local engine_id
            engine_id=$(echo "$tx_payload" | jq -r .engine_id 2>/dev/null)
            # Consensus-policy governance entries are not redeemable compute jobs.
            [ "$(db_query_safe "$BLOCKCHAIN_DB" "SELECT pkg_id FROM compute_engines WHERE engine_id=%s;" "$engine_id")" != consensus/work-weight:2 ] || return 1
            
            # [Batch 4] 阻止重复提交 (Double-Redeem 防御)
            local solved_count
            solved_count=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT COUNT(*) FROM completed_compute_tasks WHERE engine_id = %s AND problem_id = %s;" "$engine_id" "$problem_id")
            if [[ "$solved_count" -gt 0 ]]; then
                warn "      ! 状态验证失败: 引擎 '${engine_id}' 下的问题 '${problem_id}' 已被解决。 / ! State validation FAILED: Problem '${problem_id}' for engine '${engine_id}' has been solved historically."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            
            if [[ "$engine_id" == "corium/internal-engine-zero-v1" ]]; then
                "${PYTHON_CMD}" - "$tx_payload" "$sender_id" "$CORIUM_NETWORK_ID" "$BLOCKCHAIN_DB" <<'PY_ENGINE_ZERO'
import hashlib,json,re,sqlite3,sys
payload=json.loads(sys.argv[1]); proof=payload.get('proof_data',{})
if not isinstance(proof,dict) or proof.get('submitter_id')!=sys.argv[2] or proof.get('network_id')!=sys.argv[3]: raise ValueError('Engine Zero proof identity/network mismatch')
nonce=str(proof.get('nonce','')); problem=payload.get('problem_id','')
if not re.fullmatch('[0-9]{1,20}',nonce) or not re.fullmatch('[a-f0-9]{64}',problem): raise ValueError('Invalid Engine Zero proof fields')
with sqlite3.connect(sys.argv[4]) as db:
    if not db.execute('SELECT 1 FROM blocks WHERE hash=?',(problem,)).fetchone(): raise ValueError('Unknown Engine Zero challenge')
digest=hashlib.sha256((sys.argv[3]+sys.argv[2]+nonce+problem).encode()).hexdigest()
if not digest.startswith('000'): raise ValueError('Invalid Engine Zero nonce')
PY_ENGINE_ZERO
                [ $? -eq 0 ] || return 1
            fi

            # [Batch 4] 防御恶意 Compute Engine/Verifier 篡改
            # Only the exact versioned built-in identifier bypasses registration.
            # Prefix lookalikes must pass normal active-engine/hash validation.
            if [[ "$engine_id" != "corium/internal-engine-zero-v1" ]]; then
                local onchain_engine_hash onchain_verifier_hash proof_engine_hash proof_verifier_hash
                onchain_engine_hash=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT compute_program_hash FROM compute_engines WHERE engine_id = %s AND is_active = 1;" "$engine_id")
                onchain_verifier_hash=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT verifier_script_hash FROM compute_engines WHERE engine_id = %s AND is_active = 1;" "$engine_id")
                proof_engine_hash=$(echo "$tx_payload" | jq -r .engine_hash 2>/dev/null)
                proof_verifier_hash=$(echo "$tx_payload" | jq -r .verifier_hash 2>/dev/null)
                
                if [[ -z "$onchain_engine_hash" || -z "$onchain_verifier_hash" ]]; then
                    warn "      ! 状态验证失败: 引擎 '${engine_id}' 不活跃或不存在。 / ! State validation FAILED: Engine '${engine_id}' is not active or does not exist."
                    reorg_cache["$tx_hash"]="invalid"; return 1
                fi
                if [[ "$onchain_engine_hash" != "$proof_engine_hash" || "$onchain_verifier_hash" != "$proof_verifier_hash" ]]; then
                    warn "      ! 状态验证失败: 证明所带哈希与当前链上活跃版本不符 (防止重放历史漏洞版本)。 / ! State validation FAILED: Proof hashes do not match active on-chain versions."
                    reorg_cache["$tx_hash"]="invalid"; return 1
                fi
            fi
            if [ "$(db_query_safe "$BLOCKCHAIN_DB" "SELECT pkg_id FROM compute_engines WHERE engine_id=%s;" "$engine_id")" = compute/openci-attested:1 ]; then
                _corium_openci_consensus validate "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$tx_payload" "$sender_id" "$block_height" >/dev/null || return 1
                local openci_claim_key="openci:$engine_id:$problem_id"
                [ -z "${intra_block_state_tracker[$openci_claim_key]:-}" ] || return 1
                intra_block_state_tracker["$openci_claim_key"]=1
            fi
            if [ "$(db_query_safe "$BLOCKCHAIN_DB" "SELECT pkg_id FROM compute_engines WHERE engine_id=%s;" "$engine_id")" = corium/built-in-gimps ]; then
                _corium_gimps_consensus validate "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$tx_payload" "$sender_id" "$block_height" >/dev/null || return 1
                local gimps_claim_key="gimps:$engine_id:$problem_id"
                [ -z "${intra_block_state_tracker[$gimps_claim_key]:-}" ] || return 1
                intra_block_state_tracker["$gimps_claim_key"]=1
            fi
            ;;
        "challenge_proof")
            detail "    - Validating 'challenge_proof' transaction... / 正在验证 'challenge_proof' 交易..."
            local target_proof_tx_hash
            target_proof_tx_hash=$(echo "$tx_payload" | jq -r .target_proof_tx_hash 2>/dev/null)
            
            # 验证 1: 被挑战的证明是否存在，且是否仍在挑战窗口期内？
            # Verification 1: Does the challenged proof exist and is it still within the challenge window?
            local deadline_height
            deadline_height=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT confirmation_deadline_height FROM pending_proofs WHERE proof_tx_hash = %s;" "$target_proof_tx_hash")
            
            if [[ -z "$deadline_height" ]]; then
                warn "      ! 状态验证失败: 未找到待处理的证明 '${target_proof_tx_hash}' 可供挑战。 / ! State validation FAILED: No pending proof '${target_proof_tx_hash}' found to challenge."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            if [[ "$block_height" -gt "$deadline_height" ]]; then
                warn "      ! 状态验证失败: 对证明 '${target_proof_tx_hash}' 的挑战窗口已关闭。 / ! State validation FAILED: Challenge window for proof '${target_proof_tx_hash}' has closed."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            ;;
        "state_correction_tx")
            check_dep gpg; detail "    - Validating 'state_correction_tx' transaction..."
            local authority_pubkey=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT value FROM chain_state WHERE key = 'core_gpg_authority';")
            if [[ -z "$authority_pubkey" ]]; then warn "      ! Protocol Error: No authority GPG key defined on-chain."; reorg_cache["$tx_hash"]="invalid"; return 1; fi
            local gpg_signature gpg_payload; gpg_signature=$(echo "$tx_payload" | jq -r .authority_signature 2>/dev/null); gpg_payload=$(echo "$tx_payload" | jq -c .state_transitions 2>/dev/null)
            if ! gpg_verify_signature "$gpg_payload" "$gpg_signature" "$authority_pubkey"; then warn "      ! Permission FAILED: Invalid GPG signature for 'state_correction_tx'!"; reorg_cache["$tx_hash"]="invalid"; return 1; fi
            jq -e '.state_transitions | type=="array" and all(.[]; type=="object" and (.operation=="DEBIT" or .operation=="CREDIT" or .operation=="UPDATE" or .operation=="INVALIDATE_TX"))' <<< "$tx_payload" >/dev/null || return 1
            ;;
        "acl_revoke")
            detail "    - Validating 'acl_revoke' transaction (kick/leave/remove admin)..."
            local acl_id grantee_id perms_to_remove; acl_id=$(echo "$tx_payload" | jq -r .acl_id); grantee_id=$(echo "$tx_payload" | jq -r .grantee_id); perms_to_remove=$(echo "$tx_payload" | jq -r '.permissions | join(" ")')
            if [ "$sender_id" = "$grantee_id" ]; then
                if [[ "$perms_to_remove" != *"owner"* ]]; then
                    if _is_authorized_by_acl "$acl_id" "$sender_id" "owner"; then warn "      ! 验证失败 (规则): 群主不能离开群组。"; reorg_cache["$tx_hash"]="invalid"; return 1; fi
                else warn "      ! 验证失败 (规则): 任何人不能移除自己的 'owner' 权限。"; reorg_cache["$tx_hash"]="invalid"; return 1; fi
                _is_authorized_by_acl "$acl_id" "$sender_id" member || return 1
                return 0
            fi
            if _is_user_protected_by_proposal "$acl_id" "$grantee_id"; then warn "      ! 验证失败 (状态): 目标用户 ${grantee_id:0:12} 当前受提案保护，不能被踢。"; reorg_cache["$tx_hash"]="invalid"; return 1; fi
            if ! _is_authorized_by_acl "$acl_id" "$sender_id" "admin"; then warn "      ! 验证失败 (权限): 发起者不是管理员。"; reorg_cache["$tx_hash"]="invalid"; return 1; fi
            if _is_authorized_by_acl "$acl_id" "$grantee_id" "owner"; then warn "      ! 验证失败 (权限): 任何人不能踢群主。"; reorg_cache["$tx_hash"]="invalid"; return 1; fi
            if ! _is_authorized_by_acl "$acl_id" "$sender_id" "owner" && _is_authorized_by_acl "$acl_id" "$grantee_id" "admin"; then warn "      ! 验证失败 (权限): 管理员不能踢其他管理员。"; reorg_cache["$tx_hash"]="invalid"; return 1; fi
            ;;
        "group_propose_admin")
            local group_id=$(echo "$tx_payload" | jq -r .group_id); detail "    - Validating 'group_propose_admin' transaction..."
            if _is_authorized_by_acl "$group_id" "$sender_id" "admin"; then warn "      ! 验证失败 (权限): 管理员或群主不能发起普通成员投票。"; reorg_cache["$tx_hash"]="invalid"; return 1; fi
            if ! _is_authorized_by_acl "$group_id" "$sender_id" "member"; then warn "      ! 验证失败 (权限): 发起者必须是群组成员。"; reorg_cache["$tx_hash"]="invalid"; return 1; fi
            ;;
        "group_vote_admin")
            local proposal_hash=$(echo "$tx_payload" | jq -r .proposal_tx_hash)
            local proposal_payload=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT data FROM transactions WHERE hash = %s AND type = 'group_propose_admin';" "$proposal_hash")
            [ -z "$proposal_payload" ] && { warn "      ! 验证失败: 提案不存在或类型不正确。"; reorg_cache["$tx_hash"]="invalid"; return 1; }
            local proposal_group_id=$(echo "$proposal_payload" | jq -r .group_id); detail "    - Validating 'group_vote_admin' transaction..."
            if _is_authorized_by_acl "$proposal_group_id" "$sender_id" "admin"; then warn "      ! 验证失败 (权限): 管理员或群主不能参与普通成员投票。"; reorg_cache["$tx_hash"]="invalid"; return 1; fi
            if ! _is_authorized_by_acl "$proposal_group_id" "$sender_id" "member"; then warn "      ! 验证失败 (权限): 投票者必须是群组成员。"; reorg_cache["$tx_hash"]="invalid"; return 1; fi
            ;;
        "group_admin_action")
            local group_id
            group_id=$(echo "$tx_payload" | jq -r .group_id)
            
            detail "    - Validating 'group_admin_action' transaction... / 正在验证 'group_admin_action' 交易..."
            
            # 核心验证逻辑：检查交易发送者是否是该群组的管理员或所有者
            # Core validation logic: check if the sender is an admin or owner of the group
            if ! _is_authorized_by_acl "$group_id" "$sender_id" "admin"; then
                warn "      ! 验证失败 (权限): 发送者不是群组管理员，无法执行此操作。"
                warn "      ! Validation FAILED (Permission): Sender is not a group admin and cannot perform this action."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            ;;
        "propose_new_compute_engine")
            detail "    - Validating 'propose_new_compute_engine' transaction... / 正在验证 'propose_new_compute_engine' 交易..."
            if [ "$(jq -r .pkg_id <<< "$tx_payload")" = consensus/work-weight:2 ]; then
                _corium_work_consensus proposal "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$tx_payload" "$block_height" >/dev/null || return 1
                [ -z "${intra_block_state_tracker[work-policy]:-}" ] || return 1
                intra_block_state_tracker[work-policy]=1
            fi
            if [ "$(jq -r .pkg_id <<< "$tx_payload")" = compute/openci-attested:1 ]; then
                _corium_openci_consensus proposal "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$tx_payload" "$block_height" >/dev/null || return 1
            fi
            # 验证 1: 提案者是否有足够的贡献分?
            # Verification 1: Does the proposer have enough contribution score?
            local proposer_score
            proposer_score=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT score FROM contribution_scores WHERE user_id = %s;" "$sender_id")
            if [[ ${proposer_score:-0} -lt 100 ]]; then # '100' 是协议参数
                warn "      ! 权限验证失败: 贡献分不足以发起提案。 / ! Permission FAILED: Insufficient contribution score to make a proposal."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            
            # 验证 2: 验证载荷中哈希值的格式是否正确 (64位十六进制字符)
            # Verification 2: Validate the format of hashes in the payload (64 hex characters)
            local compute_hash verifier_hash pkg_id
            pkg_id=$(jq -r .pkg_id <<< "$tx_payload")
            jq -e '(.reward_weight // 100) | type=="number" and floor==. and .>=1 and .<=1000000' <<< "$tx_payload" >/dev/null || return 1
            compute_hash=$(echo "$tx_payload" | jq -r .compute_program_hash 2>/dev/null)
            verifier_hash=$(echo "$tx_payload" | jq -r .verifier_script_hash 2>/dev/null)
            if [[ -z "$pkg_id" || "$pkg_id" == "null" ]]; then
                warn "      ! 格式验证失败: 'propose_new_compute_engine' 交易缺少 'pkg_id' 字段。 / ! Format validation FAILED: 'propose_new_compute_engine' transaction is missing 'pkg_id' field."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            if ! [[ "$pkg_id" =~ ^[a-z0-9-]+/[a-z0-9-]+:[0-9]+$ ]]; then
                 warn "      ! 格式验证失败: 'pkg_id' 格式无效。应为 'category/name:slot'。 / ! Format validation FAILED: Invalid 'pkg_id' format. Expected 'category/name:slot'."
                 reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            if ! [[ "$compute_hash" =~ ^[a-f0-9]{64}$ && "$verifier_hash" =~ ^[a-f0-9]{64}$ ]]; then
                 warn "      ! 格式验证失败: 提案中的一个或多个P2P哈希格式无效。 / ! Format validation FAILED: One or more P2P hashes in the proposal are invalid."
                 reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            ;;

        "vote_on_compute_engine")
            detail "    - Validating 'vote_on_compute_engine' transaction... / 正在验证 'vote_on_compute_engine' 交易..."
            local proposal_hash
            proposal_hash=$(echo "$tx_payload" | jq -r .proposal_tx_hash 2>/dev/null)

            # 验证 1: 投票者是否有投票权? (贡献分 > 0)
            # Verification 1: Does the voter have voting rights? (contribution score > 0)
            local voter_score
            voter_score=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT score FROM contribution_scores WHERE user_id = %s;" "$sender_id")
            if [[ ${voter_score:-0} -eq 0 ]]; then
                warn "      ! 权限验证失败: 贡献分为零，无投票权。 / ! Permission FAILED: Contribution score is zero, no voting rights."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            
            # 验证 2: 提案是否存在且类型正确?
            # Verification 2: Does the proposal exist and is its type correct?
            local proposal_type
            proposal_type=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT type FROM transactions WHERE hash = %s;" "$proposal_hash")
            if [[ "$proposal_type" != "propose_new_compute_engine" ]]; then
                warn "      ! 状态验证失败: 投票指向的交易不是一个有效的计算引擎提案。 / ! State validation FAILED: Vote targets a transaction that is not a valid compute engine proposal."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            
            # 验证 3: 投票是否在窗口期内?
            # Verification 3: Is the vote within the voting window?
            local proposal_block_height
            proposal_block_height=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT block_height FROM transactions WHERE hash = %s;" "$proposal_hash")
            local VOTE_WINDOW=1000 # 协议参数: 投票窗口为1000个区块
            if [[ -z "$proposal_block_height" || "$block_height" -gt $((proposal_block_height + VOTE_WINDOW)) ]]; then
                warn "      ! 状态验证失败: 投票已超出提案的有效窗口期。 / ! State validation FAILED: Vote is outside the valid window for the proposal."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi

            # 验证 4: 防止重复投票
            # Verification 4: Prevent double voting
            local existing_vote_count
            existing_vote_count=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT COUNT(*) FROM transactions WHERE type = 'vote_on_compute_engine' AND public_key = %s AND json_extract(data, '$.proposal_tx_hash') = %s AND block_height IS NOT NULL AND block_height < %d;" "$tx_pubkey" "$proposal_hash" "$block_height")
             if [[ "$existing_vote_count" -gt 0 ]]; then
                warn "      ! 状态验证失败: 该身份已对该提案投过票。 / ! State validation FAILED: This identity has already voted on this proposal."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            ;;

        # --- [V60 原有逻辑] 包管理、社交、维基等 (完整保留) ---
        "forum")
            if ! jq -e '
                type=="object" and ((.type=="forum_topic" and (.topic_id|type=="string" and test("^[a-f0-9]{64}$")))
                or (.type=="forum_post" and (.post_id|type=="string" and test("^[a-f0-9]{64}$")) and (.topic_id|type=="string" and test("^[a-f0-9]{64}$"))))' <<< "$tx_payload" >/dev/null; then
                reorg_cache["$tx_hash"]="invalid"; return 1
