            local existing_registration_count
            existing_registration_count=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT COUNT(*) FROM transactions WHERE type = 'package_register' AND json_extract(data, '$.name') = %s AND json_extract(data, '$.version') = %s AND block_height IS NOT NULL AND block_height < %d;" "$pkg_name" "$pkg_version" "$block_height")

            if [ "$existing_registration_count" -gt 0 ]; then
                warn "      ! 状态验证失败: 软件包 '${pkg_name}' v'${pkg_version}' 已在历史区块中注册。 / ! State validation FAILED: Package '${pkg_name}' v'${pkg_version}' was already registered in a prior block."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            
            intra_block_state_tracker[$registration_key]=1
