            lock_holder=$(db_query_safe "$FORUM_DB" "SELECT locked_by_user_id FROM wiki_pages WHERE page_tx_hash = %s;" "$page_tx_hash")
            if [ "$lock_holder" != "$sender_id" ]; then
                warn "      ! 验证失败 (状态): 发送者不持有该页面的编辑锁。/ ! Validation FAILED (State): Sender does not hold the edit lock for this page."
