            fi
            prev_ver_in_tx=$(echo "$tx_payload" | jq -r .previous_version_hash)
            latest_ver_in_db=$(db_query_safe "$FORUM_DB" "SELECT latest_version_hash FROM wiki_pages WHERE page_tx_hash = %s;" "$page_tx_hash")
            if [ "$prev_ver_in_tx" != "$latest_ver_in_db" ]; then
                warn "      ! 验证失败 (状态): 编辑冲突，该页面已被更新。/ ! Validation FAILED (State): Edit conflict, the page has been updated since the lock was acquired."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            ;;
        "wiki_page_unlock")
             local page_tx_hash lock_holder
             page_tx_hash=$(echo "$tx_payload" | jq -r .page_create_tx_hash 2>/dev/null)
             lock_holder=$(db_query_safe "$FORUM_DB" "SELECT locked_by_user_id FROM wiki_pages WHERE page_tx_hash = %s;" "$page_tx_hash")
             if [ "$lock_holder" != "$sender_id" ]; then
                warn "      ! 验证失败 (权限): 只有锁的持有者才能解锁。/ ! Validation FAILED (Permission): Only the lock holder can unlock."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            ;;
        "ibc_dispatch")
            if [ "$(jq -r '.message_type // ""' <<< "$tx_payload")" = "ZIOKT_NAME_BINDING_V1" ]; then
                jq -e --arg source "$CORIUM_NETWORK_ID" 'keys==["message_payload","message_type","target_chain_id"] and (.target_chain_id|type=="string" and test("^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$")) and (.message_payload | keys==["epoch","expires_at","namespace","record","root","source_chain_id"] and .source_chain_id==$source and (.namespace|type=="string" and test("^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$")) and (.root|type=="string" and test("^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$")) and (.epoch|type=="number" and .==floor and .>=1 and .<=9007199254740991) and (.expires_at|type=="number" and .==floor) and (.record|type=="object") and .record.network_id==.namespace)' <<< "$tx_payload" >/dev/null || return 1
                local binding_root binding_owner binding_expiry
                binding_root=$(jq -r .message_payload.root <<< "$tx_payload")
                binding_owner=$(db_query_safe "$FORUM_DB" "SELECT owner_id FROM nns_records WHERE domain_name=%s;" "$binding_root") || return 1
                [ "$binding_owner" = "$sender_id" ] || return 1
                binding_expiry=$(jq -r .message_payload.expires_at <<< "$tx_payload")
                [[ "$binding_expiry" =~ ^[0-9]{1,12}$ ]] && [ "$binding_expiry" -gt "$tx_timestamp" ] && [ "$binding_expiry" -le "$((tx_timestamp+600))" ] || return 1
                local binding_namespace binding_epoch binding_previous binding_destination binding_slot
                binding_namespace=$(jq -r .message_payload.namespace <<< "$tx_payload")
                binding_epoch=$(jq -r .message_payload.epoch <<< "$tx_payload")
                binding_destination=$(jq -r .target_chain_id <<< "$tx_payload")
                binding_previous=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT COALESCE(MAX(json_extract(data,'$.message_payload.epoch')),0) FROM transactions WHERE type='ibc_dispatch' AND block_height<%d AND json_extract(data,'$.message_type')='ZIOKT_NAME_BINDING_V1' AND json_extract(data,'$.target_chain_id')=%s AND json_extract(data,'$.message_payload.namespace')=%s AND json_extract(data,'$.message_payload.root')=%s;" "$block_height" "$binding_destination" "$binding_namespace" "$binding_root") || return 1
                [ "$binding_epoch" -gt "$binding_previous" ] || return 1
                binding_slot="ziokt-name:$binding_namespace:$binding_root:$binding_destination"
                [ -z "${intra_block_state_tracker[$binding_slot]:-}" ] || return 1
                intra_block_state_tracker["$binding_slot"]=1
                # A namespace binding is an owner-authorized, short-lived lease.
                # It does not advance destination trust checkpoints or grant access.
            fi
            ;;
        "nns_register")
            local domain_name current_height
            domain_name=$(echo "$tx_payload" | jq -r .domain_name 2>/dev/null)
            if ! [[ "$domain_name" =~ ^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$ ]]; then
                warn "      ! NNS 错误: '${domain_name}' 的域名格式无效。/ ! NNS Error: Invalid domain name format for '${domain_name}'."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            # Registration cannot overwrite another NNS owner's existing root,
            # including genesis reservations. Expired roots use native auction
            # governance rather than an unauthenticated registration overwrite.
            local registered_owner registration_slot
            registered_owner=$(db_query_safe "$FORUM_DB" "SELECT owner_id FROM nns_records WHERE domain_name=%s;" "$domain_name") || return 1
            [ -z "$registered_owner" ] || [ "$registered_owner" = "$sender_id" ] || return 1
            registration_slot="nns-register:$domain_name"
            [ -z "${intra_block_state_tracker[$registration_slot]:-}" ] || return 1
            intra_block_state_tracker["$registration_slot"]=1
            current_height="$block_height"
            if [ "$current_height" -le 5000 ]; then
                if ! echo "$tx_payload" | jq -e '.proof_of_genesis_contribution' >/dev/null; then
                     warn "      ! 验证失败 (创世期): 缺少创世贡献度证明。/ ! Validation FAILED (Genesis): Missing proof of genesis contribution."
                     reorg_cache["$tx_hash"]="invalid"; return 1
                fi
            else
                if ! echo "$tx_payload" | jq -e '.proof_of_contribution' >/dev/null; then
                     warn "      ! 验证失败 (成熟期): 缺少贡献度证明。/ ! Validation FAILED (Maturity): Missing proof of contribution."
                     reorg_cache["$tx_hash"]="invalid"; return 1
                fi
            fi
            ;;
        "nns_update")
            jq -e 'keys==["records"] and (.records|type=="array" and length>0 and length<=32 and all(.[]; keys==["domain_name","target_hash"] and (.domain_name|type=="string" and test("^[a-z0-9-]{1,63}$")) and (.target_hash|type=="string" and test("^[a-f0-9]{64}$"))))' <<< "$tx_payload" >/dev/null || return 1
            local nns_record nns_owner
            while IFS= read -r nns_record; do
                nns_owner=$(db_query_safe "$FORUM_DB" "SELECT owner_id FROM nns_records WHERE domain_name = %s;" "$(jq -r .domain_name <<< "$nns_record")")
                [ "$nns_owner" = "$sender_id" ] || return 1
            done < <(jq -c '.records[]' <<< "$tx_payload")
            ;;
        "nns_transfer")
            local domain_name current_owner current_height
            domain_name=$(echo "$tx_payload" | jq -r .domain_name 2>/dev/null)
            current_owner=$(db_query_safe "$FORUM_DB" "SELECT owner_id FROM nns_records WHERE domain_name = %s;" "$domain_name")
            if [ "$current_owner" != "$sender_id" ]; then
                warn "      ! 验证失败 (权限): 发送者不是域名 '${domain_name}' 的所有者。/ ! Validation FAILED (Permission): Sender is not the owner of domain '${domain_name}'."
                reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            current_height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT COALESCE(MAX(height), 0) FROM blocks;")
            if [ "$current_height" -le 5000 ]; then
                 if ! echo "$tx_payload" | jq -e '.contribution_tax' >/dev/null; then
                     warn "      ! 验证失败 (创世期): 域名转让交易缺少贡献度税收证明。/ ! Validation FAILED (Genesis): Domain transfer is missing contribution tax proof."
                     reorg_cache["$tx_hash"]="invalid"; return 1
                fi
            fi
            ;;
        "acl_grant")
            local acl_id
            acl_id=$(echo "$tx_payload" | jq -r .acl_id 2>/dev/null)
            jq -e '.grantee_id|type=="string" and test("^[a-f0-9]{64}$")' <<< "$tx_payload" >/dev/null || return 1
            jq -e '.permissions|type=="array" and length>0 and all(.[];type=="string")' <<< "$tx_payload" >/dev/null || return 1
            if jq -e '.permissions|any(.=="owner" or .=="admin")' <<< "$tx_payload" >/dev/null; then
                _is_authorized_by_acl "$acl_id" "$sender_id" owner || return 1
            fi
            if ! _is_authorized_by_acl "$acl_id" "$sender_id" "admin"; then
                 warn "      ! 验证失败 (权限): 发送者无权修改ACL '${acl_id:0:16}'。/ ! Validation FAILED (Permission): Sender is not authorized to modify ACL '${acl_id:0:16}'."
                 reorg_cache["$tx_hash"]="invalid"; return 1
            fi
            ;;
        *)
            # 默认情况下，如果交易类型未知，我们将其视为有效，以保证向前兼容性。
            # By default, we treat unknown transaction types as valid for forward compatibility.
            ;;
    esac
    
    detail "    - 交易 '$tx_hash' 验证通过。 / Transaction '$tx_hash' validated."
    reorg_cache["$tx_hash"]="valid"
    return 0
}


# REVISED: Gets the hash of the tip of the "heaviest" chain.
# This is now the single source of truth for the canonical chain head.
#
# 已修订: 获取“最重”链的链顶哈希。
# 这里现在是规范链头的唯一真实来源。
blockchain_get_latest_hash() {
    local chain_info
    chain_info=$(db_query_static "$BLOCKCHAIN_DB" "SELECT value FROM chain_state WHERE key = 'chain_info';")
    if [ -n "$chain_info" ]; then
        echo "$chain_info" | cut -d'|' -f1
    else
        # Fallback for an uninitialized chain state
        # 对未初始化的链状态进行回退处理
        db_query_static "$BLOCKCHAIN_DB" "SELECT hash FROM blocks ORDER BY total_weight DESC, height DESC LIMIT 1;"
    fi
}

# Mining/validation process (PoS) with P2P broadcast
# 挖矿/验证过程 (PoS)，包含P2P广播功能
blockchain_mine_block() (
    _internal_consensus_safety_check || return 1
    set -e
    acquire_lock "system" || return 1
    local mining_committed=false mining_original_fs="$CURRENT_TRANSACTION_BACKUP_PATH"
    db_begin_transaction "$BLOCKCHAIN_DB" "$FORUM_DB" "$DHT_DB" || return 1
    trap 'status=$?; if ! $mining_committed; then if [ -z "$mining_original_fs" ]; then _rollback_filesystem_transaction || status=1; fi; db_rollback_transaction "$BLOCKCHAIN_DB" "$FORUM_DB" "$DHT_DB"; fi; release_lock "system"; exit "$status"' EXIT
    info "尝试创建并广播新区块... (Attempting to create and broadcast a new block...)"
    
    # 1. 检查是否有待处理的交易 (Check if there are any pending transactions)
    local activation_height work_mode work_result="" native_work_block=""
    activation_height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT COALESCE(MAX(height),-1)+1 FROM blocks;") || return 1
    local early_work_activation=false
    if [ "$(_corium_work_consensus preactivate "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$activation_height" | jq -er .required)" = true ]; then
        _protocol_execute_scheduled_changes "$activation_height" || return 1
        _slashing_check_for_jailed_validators "$activation_height" || return 1
        early_work_activation=true
    fi
    work_mode=$(_corium_work_consensus mode "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$activation_height" | jq -er .mode) || return 1
    local pending_txs
    pending_txs=$(db_query_static "$BLOCKCHAIN_DB" "SELECT hash FROM transactions WHERE block_height IS NULL ORDER BY timestamp, hash;") || return 1
    local allow_empty=false
    if [ "${CORIUM_ALLOW_EMPTY_BLOCKS:-0}" = "1" ] || [ -f "$CORIUM_ROOT/allow_empty_blocks" ] || [ "$work_mode" = pow-v2 ]; then
        allow_empty=true
    fi
    if [ -z "$pending_txs" ] && [ "$allow_empty" != "true" ]; then
        info "交易池无待处理交易，跳过空区块创建。 (No pending transactions to mine; skipping empty block creation.)"
        return 0
    fi
    
    # 2. 检查我们是否是验证者 (Check if we are a validator)
    [ ! -f "$USER_PUBLIC_KEY_FILE" ] && { info "非验证者节点，跳过区块创建。 (Not a validator node, skipping block creation.)"; return 0; }
    local our_pubkey=$(cat "$USER_PUBLIC_KEY_FILE")

    local stake

    # 3. 确定下一个合法的区块验证者，并检查是否轮到我们 (Identify the next legitimate block validator and check if it's our turn)
    local next_validator_pubkey
    if [ "$work_mode" != pow-v2 ]; then
    next_validator_pubkey=$(blockchain_get_next_validator) || return 1
    if [ "$our_pubkey" != "$next_validator_pubkey" ]; then
        info "根据共识，现在不是我们创建区块的时候。跳过。 (According to consensus, it is not our turn to create a block. Skipping.)"
        return 0
    fi
    
    fi
    if ! $early_work_activation; then
        _protocol_execute_scheduled_changes "$activation_height" || return 1
        _slashing_check_for_jailed_validators "$activation_height" || return 1
    fi
    if [ "$work_mode" != pow-v2 ]; then
        stake=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT stake FROM validators WHERE public_key=%s AND status='active';" "$our_pubkey") || return 1
    fi
    msg "轮到我们创建区块了！正在打包、签名并广播... (It's our turn to create a block! Packaging, signing, and broadcasting...)"
    
    # 4. 获取最新的区块哈希和高度 (Get the latest block hash and height)
    local latest_hash=$(blockchain_get_latest_hash)
    local height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT COALESCE(MAX(height), -1) + 1 FROM blocks;")

    # 5. 创建交易列表 JSON (Create transaction list JSON)
    local tx_json="["
    local first=true
    local tx_hashes_in_block=()
    local -A block_tracker=() validation_cache=()
    while IFS= read -r hash; do
        [ -n "$hash" ] || continue
        _validate_single_transaction "$hash" "" "" "$height" block_tracker validation_cache || return 1
        tx_hashes_in_block+=("$hash")
        [ "$first" = true ] && first=false || tx_json+=","
        tx_json+="\"$hash\""
    done <<< "$pending_txs"
    tx_json+="]"
    
    # 6. 创建并签名新区块 (本地操作) (Create and sign a new block (local operation))
    local validator_id=$(_internal_hash_text "$our_pubkey")
    local timestamp=$(date +%s)
    local block_data_to_sign="{\"height\":$height,\"previous_hash\":\"$latest_hash\",\"timestamp\":$timestamp,\"transactions\":$tx_json}"
    local block_hash=$(_internal_hash_text "$block_data_to_sign")
    local signature=$(sign_data "$block_data_to_sign" "$USER_IDENTITY_FILE")
    if [ "$work_mode" = pow-v2 ]; then
        work_result=$(_corium_work_consensus mine "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$USER_IDENTITY_FILE" "$latest_hash" "$timestamp" "$tx_json") || return 1
        native_work_block=$(jq -ec .block <<< "$work_result") || return 1
        block_hash=$(jq -er .hash <<< "$work_result") || return 1
        signature=$(jq -er .signature <<< "$native_work_block") || return 1
    fi
    
    # 7. 将新区块存入本地数据库 (Store the new block in the local database)
    local parent_weight total_weight
    parent_weight=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT total_weight FROM blocks WHERE hash=%s;" "$latest_hash") || return 1
    if [ "$work_mode" = pow-v2 ]; then
        total_weight=$(jq -er .total_weight <<< "$work_result") || return 1
    else
        [[ "$stake" =~ ^[1-9][0-9]{0,18}$ ]] && [ "$stake" -le "$((9223372036854775807-parent_weight))" ] || return 1
        total_weight=$((parent_weight+stake))
    fi
    db_execute_safe "$BLOCKCHAIN_DB" \
        "INSERT INTO blocks (height, hash, previous_hash, timestamp, validator, signature, transactions,total_weight) VALUES (%d, %s, %s, %d, %s, %s, %s,%d);" \
        "$height" "$block_hash" "$latest_hash" "$timestamp" "$validator_id" "$signature" "$tx_json" "$total_weight" || return 1
    
    # 8. 将区块的完整内容作为一个P2P对象进行共享 (Share the complete content of the block as a P2P object)
    info "正在将新区块 $block_hash 作为P2P对象共享... (Sharing new block $block_hash as a P2P object...)"
    local temp_block_file
    temp_block_file=$(mktemp)
    CORIUM_TEMP_ITEMS+=("$temp_block_file")
    # 创建完整的区块JSON对象，用于网络共享 (Create a complete block JSON object for network sharing)
    local full_block_json="{\"height\":$height,\"previous_hash\":\"$latest_hash\",\"timestamp\":$timestamp,\"validator\":\"$validator_id\",\"signature\":\"$signature\",\"transactions\":$tx_json}"
    if [ "$work_mode" = pow-v2 ]; then
        full_block_json="$native_work_block"
        _corium_work_consensus record "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$full_block_json" "$block_hash" >/dev/null || return 1
    fi
    echo "$full_block_json" > "$temp_block_file"
    
    # p2p_split_file 使用文件内容计算哈希，这必须与我们的 block_hash 匹配
    # The p2p_split_file uses the file content to calculate the hash, which must match our block_hash
    # 为了确保一致，我们应该让 p2p_split_file 直接使用我们计算好的哈希
    # To ensure consistency, we should have p2p_split_file directly use the hash we have calculated
    local temp_final_block_path="${P2P_DIR}/objects/${block_hash}"
    # Ensure the directory exists
    mkdir -p "$(dirname "$temp_final_block_path")"
    # Copy from the temporary file (source) to the final path (destination)
    cp "$temp_block_file" "$temp_final_block_path" 
    db_execute_safe "$DHT_DB" "INSERT OR REPLACE INTO local_chunks VALUES (%s,%s,0,%d);" "$block_hash" "$temp_final_block_path" "$(stat -c%s "$temp_final_block_path")" || return 1
    
    # 9. 向网络广播新区块的哈希 (Broadcast the hash of the new block to the network)
    # Broadcast only after the complete durable state transition commits.
    
    # --- [MODIFICATION START] Process state transitions after successfully adding and broadcasting a new block ---
    # --- [修改开始] 在成功添加并广播一个新区块后，处理状态转换 ---
    # Now that block height is officially part of our chain, we check if it concludes any voting periods.
    # 既然区块 height 已正式成为我们链的一部分，我们检查它是否结束了任何投票期。
    # Settlements run once in _update_chain_state_cache after transaction binding.
    # --- [MODIFICATION END] ---
    
    # 10. 更新本地状态 (Update local state)
    info "正在更新本地数据库状态... (Updating local database state...)"
    for tx_hash in "${tx_hashes_in_block[@]}"; do
        db_execute_safe "$BLOCKCHAIN_DB" \
            "UPDATE transactions SET block_height = %d WHERE hash = %s;" \
            "$height" "$tx_hash"
    done
    
    # SECURE UPDATE: Use the hex literal for the public key in the WHERE clause here as well.
    # 安全更新：同样地，在 WHERE 子句中使用十六进制字面量来指定公钥。
    db_execute_safe "$BLOCKCHAIN_DB" \
        "UPDATE validators SET last_block = %d, missed_blocks_counter=0 WHERE public_key = %s;" \
        "$height" "$our_pubkey"

    _update_chain_state_cache || return 1
    db_execute_safe "$BLOCKCHAIN_DB" "INSERT OR REPLACE INTO chain_state VALUES ('chain_info',%s);" "$block_hash|$height" || return 1
    _ziokt_zkn_after_pack "$block_hash" || return 1
    if [ -z "$mining_original_fs" ] && [ -n "$CURRENT_TRANSACTION_BACKUP_PATH" ]; then _commit_transaction || return 1; fi
    db_commit_transaction "$BLOCKCHAIN_DB" "$FORUM_DB" "$DHT_DB" || return 1
    mining_committed=true
    dht_announce_chunk "$block_hash" >/dev/null || true
    _blockchain_broadcast_new_block "$block_hash" || true
    msg "新区块 $height (哈希: $block_hash) 已本地提交；传播结果见上方日志。 (New block $height (hash: $block_hash) committed locally; see propagation results above.)"
    echo "$block_hash"
    
)

# Register package on blockchain
blockchain_register_package() {
    local package_name="$1" package_version="$2" package_hash="$3" build_file_hash="$4"
    [[ "$package_hash" =~ ^[a-f0-9]{64}$ && "$build_file_hash" =~ ^[a-f0-9]{64}$ ]] || return 1
    [ -n "$package_version" ] || return 1
    (get_pkg_id_parts "${package_name}:0") || return 1
    acquire_lock "system" || return 1
    trap 'release_lock "system"' RETURN
    local existing package_data tx_hash
    existing=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT json_array(hash,data,signature,public_key,timestamp) FROM transactions WHERE type='package_register' AND json_extract(data,'$.name')=%s AND json_extract(data,'$.version')=%s ORDER BY block_height IS NULL, timestamp, hash LIMIT 1;" "$package_name" "$package_version") || return 1
    if [ -n "$existing" ]; then
        [ "$(jq -r '.[1]|fromjson|.hash' <<< "$existing")" = "$package_hash" ] && [ "$(jq -r '.[1]|fromjson|.build_hash' <<< "$existing")" = "$build_file_hash" ] || { warn "软件包版本已注册不同内容。 / Package version already registered with different content."; return 1; }
        local key_file body
        key_file=$(mktemp) || return 1; CORIUM_TEMP_ITEMS+=("$key_file")
        jq -r '.[3]' <<< "$existing" > "$key_file" || return 1
        _validate_identity_pubkey_file "$key_file" "$(_internal_hash_text "$(cat "$key_file")")" || return 1
        body=$(jq -c '{type:"package_register",data:(.[1]|fromjson),timestamp:.[4]}' <<< "$existing") || return 1
        verify_signature "$body" "$(jq -r '.[2]' <<< "$existing")" "$key_file" || return 1
        jq -er '.[0]' <<< "$existing"
        return 0
    fi
    package_data=$(jq -cn --arg name "$package_name" --arg version "$package_version" --arg hash "$package_hash" --arg build "$build_file_hash" '{name:$name,version:$version,hash:$hash,build_hash:$build}') || return 1
    tx_hash=$(blockchain_create_transaction "package_register" "$package_data") || return 1
    info "软件包注册交易已创建。 / Package registration transaction created: $tx_hash"
    printf '%s\n' "$tx_hash"
}


# Verify package on blockchain
# REVISED FOR ROBUSTNESS: Uses sqlite's json_extract for precise and safe queries,
# preventing failures due to whitespace changes in the JSON data and protecting
# against potential SQL injection vectors.
#
# 为健壮性而修订: 使用 sqlite 的 json_extract 函数进行精确、安全的查询，
# 防止因 JSON 数据中的空白变化而导致的失败，并防御潜在的 SQL 注入。
blockchain_verify_package() {
    local package_name="$1"
    local package_version="$2"
    local package_hash="$3"
    
    # 在区块链中查询包的注册信息。
    # Query blockchain for package registration.
    local registered
    registered=$(db_query_safe "$BLOCKCHAIN_DB" \
        "SELECT COUNT(*) FROM transactions WHERE type = 'package_register' AND json_extract(data, '$.name') = %s AND json_extract(data, '$.version') = %s AND json_extract(data, '$.hash') = %s AND block_height IS NOT NULL;" \
        "$package_name" "$package_version" "$package_hash")
    
    [ "$registered" -gt 0 ]
}


# =================================================================
# --- NEWLY IMPLEMENTED BLOCKCHAIN CORE FUNCTIONS (CRITICAL)    ---
# --- 新实现的核心区块链函数 (至关重要)                         ---
# =================================================================
# The following five functions were missing from the initial v0.6.0 script.
# Their implementation is critical for the blockchain to function.
#
# 以下五个函数在 v0.6.0 初始脚本中缺失。
# 它们的实现对于区块链的正常运作至关重要。

# --- Function 1: Create a new transaction ---
# --- 函数 1: 创建一个新交易 ---
# Creates, signs, and stores a new transaction, then shares its hash on the P2P network.
# 创建、签名并存储一个新交易，然后将其哈希共享到 P2P 网络。
blockchain_create_transaction() {
    local tx_type="$1"
    local tx_data="$2"

    [ ! -f "$USER_IDENTITY_FILE" ] && error "用户身份密钥文件未找到，无法创建交易。 (User identity key file not found, cannot create transaction.)"
    
    [[ "$tx_type" =~ ^[a-zA-Z][a-zA-Z0-9_-]*$ ]] || return 1
    tx_data=$(jq -ce 'select(type == "object")' <<< "$tx_data") || return 1
    case "$tx_type" in
        zkn_shield_*|privacy_review_*|zkn_transfer|zkn_private_transfer|zkc_issue) tx_data=$(jq -cS . <<< "$tx_data") || return 1 ;;
    esac
    local timestamp public_key
    timestamp=$(date +%s)
    public_key=$(cat "$USER_PUBLIC_KEY_FILE")

    # The data that gets signed and hashed does not include the signature itself.
    # 被签名和哈希的数据本身不包含签名。
    local data_to_verify signing_height
    signing_height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT COALESCE(MAX(height),-1)+1 FROM blocks;") || return 1
    data_to_verify=$(_corium_transaction_bytes "$tx_type" "$tx_data" "$timestamp" "$public_key" "$signing_height") || return 1
    
    local tx_hash signature
    tx_hash=$(_internal_hash_text "$data_to_verify")
    signature=$(sign_data "$data_to_verify" "$USER_IDENTITY_FILE")
    
    # Native signed assets use the same atomic admission as MCP/native plans.
    case "$tx_type" in
        zkn_shield_*|privacy_review_*|zkn_transfer|zkn_private_transfer|zkc_issue)
            local privacy_tx
            privacy_tx=$(jq -cn --arg type "$tx_type" --argjson data "$tx_data" --argjson ts "$timestamp" --arg pk "$public_key" --arg sig "$signature" '{type:$type,data:$data,timestamp:$ts,public_key:$pk,signature:$sig}') || return 1
            _ziokt_asset_engine submit-asset "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$CORIUM_ROOT" "$privacy_tx" || return 1
            return 0
            ;;
    esac

    # Store the complete transaction details in the local database.
    # It is initially "pending" (block_height is NULL).
    # 将完整的交易详情存入本地数据库。
    # 它最初是“待处理”状态 (block_height 为 NULL)。
    db_execute_safe "$BLOCKCHAIN_DB" \
        "INSERT OR IGNORE INTO transactions (hash, type, data, signature, public_key, timestamp, block_height) VALUES (%s, %s, %s, %s, %s, %d, NULL);" \
        "$tx_hash" "$tx_type" "$tx_data" "$signature" "$public_key" "$timestamp"

    # To make this transaction available to other nodes for mining, we treat it as a P2P object.
    # The object's content is the signed data, and its hash is the transaction hash.
    # 为了让其他节点能够获取此交易以进行打包，我们将其视为一个 P2P 对象。
    # 对象的内容是被签名的数据，其哈希就是交易哈希。
    local tx_object_dir="${P2P_DIR}/objects/transactions"
    local tx_object_path="${tx_object_dir}/${tx_hash}"
    mkdir -p "$tx_object_dir"
    chmod 700 "$tx_object_dir" || return 1
    jq -cn --arg type "$tx_type" --argjson data "$tx_data" --argjson ts "$timestamp" --arg pk "$public_key" --arg sig "$signature" '{type:$type,data:$data,timestamp:$ts,public_key:$pk,signature:$sig}' > "$tx_object_path"
    
    case "$tx_type" in zkn_shield_*|privacy_review_*) chmod 600 "$tx_object_path" || return 1 ;; esac

    # Announce this transaction "object" to the network.
    # Note: We are announcing a single chunk object.
    # 将此交易“对象”宣告到网络。
    # 注意：我们宣告的是一个单块对象。
    if ! dht_store_chunk "$tx_hash" "$tx_object_path" 0 "$(stat -c%s "$tx_object_path")"; then
        # [V105 BUG FIX] Gracefully handle network failure during transaction announcement.
        # The transaction is already saved locally and will be broadcast later.
        # [V105 BUG修复] 优雅地处理交易宣告期间的网络失败。
        # 交易已经保存在本地，会在下一次同步时被广播。
        warn "无法将交易宣告到P2P网络。它已被保存在本地，将在下次同步时广播。"
        warn "Could not announce transaction to the P2P network. It has been saved locally and will be broadcast during the next sync."
    fi

    info "Transaction created and stored locally. Hash: $tx_hash / 交易已在本地创建并存储。哈希: $tx_hash"
    echo "$tx_hash"
    return 0
    
}

_notify_recipient_of_new_message() {
    local recipient_id="$1"
    local tx_hash="$2"

    # 1. 发送一个低优先级的 P2P 直接通知消息
    # 1. Send a low-priority, direct P2P notification message
    local response
    response=$(dht_send_message "$recipient_id" "NOTIFY_NEW_MESSAGE" "$tx_hash")

    # 2. 检查响应，触发申诉逻辑
    # 2. Check the response to trigger the grievance logic
    if [[ "$response" == *"RECIPIENT_BLOCKED_SENDER"* ]]; then
        # 我们被对方拉黑了！触发申诉流程
        # We've been blocked! Trigger the grievance process.
        warn "消息交易已提交，但 P2P 通知失败：接收方已将您屏蔽。"
        warn "Message transaction submitted, but P2P notification failed: The recipient has blocked you."
        
        read -rp "您有一次机会向对方发送一条最多280字符的高优先级纯文本消息。是否使用？[y/N] You have one chance to send a high priority plain text message of up to 280 characters to the recipient. Do you want to use it? [y/N]" choice
        [[ ! "$choice" =~ ^[yY] ]] && return 1

        echo "请输入您的申诉消息 (最多280字符，按 Ctrl+D 结束):"
        echo "Please enter your appeal message (up to 280 characters, press Ctrl+D to end):"
        local grievance_text
        # head -c 会读取精确的字节数，这对于多字节字符可能不理想，但对于简单实现是可接受的
        # head -c reads exact bytes, which can be suboptimal for multi-byte chars, but is acceptable for a simple implementation.
        grievance_text=$(head -c 280)
        
        info "正在发送高优先级申诉消息... / Sending high-priority grievance message..."
        local grievance_response
        grievance_response=$(dht_send_message "$recipient_id" "GRIEVANCE_MESSAGE" "$grievance_text")
        
        if [[ "$grievance_response" == *"acknowledged"* ]]; then
            msg "申诉消息已送达。/ Grievance message delivered."
        else
            error "申诉消息发送失败，可能是对方已离线或您的申诉权杖已被使用。/ Grievance message failed. The peer may be offline or your token has been used."
        fi
    fi
}

# --- Function 2: Get all pending (unmined) transactions ---
# --- 函数 2: 获取所有待处理 (未被打包) 的交易 ---
blockchain_get_pending_transactions() {
    # A pending transaction is one that has not been assigned a block height yet.
    # We select a limited number to avoid creating blocks that are too large.
    # 待处理交易是指尚未被分配区块高度的交易。
    # 我们选择有限数量的交易以避免创建过大的区块。
    db_query_static "$BLOCKCHAIN_DB" "
    SELECT hash, type, data, signature, public_key, timestamp 
    FROM transactions 
    WHERE block_height IS NULL 
    ORDER BY timestamp ASC 
    LIMIT 200;
    "
}

# --- Function 3: Get the next validator based on a deterministic round-robin ---
# --- 函数 3: 基于确定性的轮询算法获取下一个验证者 ---

# REWRITTEN FOR SECURE PROOF-OF-STAKE: Get the next validator.
# This function implements a deterministic, stake-weighted lottery to select
# the next block creator. The previous block's hash is used as a source of
# unpredictable randomness, making the selection secure against targeted
# attacks while ensuring all nodes agree on the winner. It is no longer
# a simple round-robin algorithm.
#
# 为实现安全的权益证明而重写: 获取下一个验证者。
# 此函数实现了一个确定性的、基于权益权重的抽签机制来选择下一个区块的创建者。
# 前一个区块的哈希被用作不可预测的随机性来源，这使得选择过程能抵御定点攻击，
# 同时确保所有节点都能就胜利者达成一致。它不再是一个简单的轮询算法。
_slashing_check_for_jailed_validators() {
    [ $# -eq 1 ] && [[ "$1" =~ ^[0-9]{1,10}$ ]] || return 1
    db_execute_safe "$BLOCKCHAIN_DB" "UPDATE validators SET status='active', jailed_until_height=0, missed_blocks_counter=0 WHERE status='jailed' AND jailed_until_height<=%d AND stake>0;" "$1"
}

blockchain_get_next_validator() {
    # Selection is a read-only preview. State transitions commit with their block.
    # 验证者选择仅预览状态；所有实际变更随区块事务提交。
    local latest_height next_height latest_hash
    latest_height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT COALESCE(MAX(height),-1) FROM blocks;") || return 1
    next_height=$((latest_height+1))
    latest_hash=$(blockchain_get_latest_hash) || return 1
    "${PYTHON_CMD}" - "$BLOCKCHAIN_DB" "$latest_hash" "$next_height" <<'PY_VALIDATOR_LOTTERY'
import sqlite3,sys,hashlib,pathlib,json
height=int(sys.argv[3])
with sqlite3.connect(pathlib.Path(sys.argv[1]).resolve().as_uri()+'?mode=ro',uri=True) as db:
    columns=[row[1] for row in db.execute('PRAGMA table_info(validators)')]
    validators={row[columns.index('public_key_hash')]:dict(zip(columns,row)) for row in db.execute('SELECT * FROM validators')}
    for proposal,kind,raw in db.execute('SELECT proposal_hash,type,data FROM scheduled_state_changes WHERE enactment_height=? ORDER BY proposal_hash',(height,)):
        data=json.loads(raw)
        if kind=='validator_propose_addition':
            pem=data['target_pubkey'];identity=hashlib.sha256(pem.encode()).hexdigest();stake=data['initial_stake']
            if type(stake) is not int or not 0<stake<=9223372036854775807: raise ValueError('Invalid scheduled stake')
            if identity not in validators: validators[identity]={'public_key':pem,'stake':stake,'status':'active','jailed_until_height':0}
        elif kind=='validator_propose_removal' and data['target_pubkey_hash'] in validators:
            validators[data['target_pubkey_hash']]['stake']=0
active=[]
for row in validators.values():
    if row['stake']<=0: continue
    if row['status']=='active' or (row['status']=='jailed' and row['jailed_until_height']<=height): active.append((row['public_key'],row['stake']))
active.sort()
if not active: raise ValueError('No active validators')
total=sum(v[1] for v in active)
ticket=int(hashlib.sha256(sys.argv[2].encode()).hexdigest(),16)%total
cumulative=0
for key,stake in active:
    cumulative+=stake
    if cumulative>ticket:
        print(key.rstrip('\n')); break
else: raise ValueError('Invalid validator lottery state')
PY_VALIDATOR_LOTTERY
}

# --- Function 4: Broadcast a new block announcement to the network ---
# --- 函数 4: 向网络广播一个新区块的宣告 ---
# REVISED: Broadcast a new block announcement with a digital signature.
# 已修订: 广播带有数字签名的新区块宣告。
_blockchain_broadcast_new_block() {
    local block_hash="$1"
    
    local height
    height=$(db_query_safe "$BLOCKCHAIN_DB" \
        "SELECT height FROM blocks WHERE hash = %s;" \
        "$block_hash") || return 1
    
    # Announce to a set of diverse peers in the network.
    # 向网络中一组多样化的对等节点进行宣告。
    local peers
    peers=$(dht_find_closest_nodes "$(get_our_node_id)" 8 2>/dev/null) || peers=""

    # 1. 检查是否存在远端节点 (Check if remote peers exist)
    if [ -z "$peers" ]; then
        info "[PROPAGATION:NO_REMOTE_PEERS] 没有远端节点，区块已本地安全提交。 (No remote peers available; block committed locally.)"
        return 0
    fi

    # --- NEW: Prepare data for signing ---
    # --- 新增: 准备用于签名的数据 ---
    # The core information (hash and height) is signed to prove authenticity.
    # 对核心信息 (哈希和高度) 进行签名以证明其真实性。
    local data_to_sign="${block_hash}|${height}"
    local signature
    signature=$(sign_data "$data_to_sign" "$USER_IDENTITY_FILE")
    local our_node_id
    our_node_id=$(get_our_node_id)
    
    info "正在向对等节点广播已签名的新区块宣告... (Broadcasting signed new block announcement to peers...)"
    local address node_id total=0 success=0 timeouts=0 rejections=0 failures=0
    while IFS= read -r address; do
        [ -n "$address" ] || continue
        _parse_full_address "$address" || continue
        node_id="$ADDR_NODE_ID"
        [ -n "$node_id" ] || continue
        total=$((total + 1))
        local send_rc=0
        dht_send_message "$node_id" "ANNOUNCE_BLOCK" \
            "${block_hash}|${height}|$(get_our_ip)|${P2P_PORT}|${our_node_id}|${signature}" || send_rc=$?
        case "$send_rc" in
            0) success=$((success + 1)) ;;
            2) timeouts=$((timeouts + 1)) ;;
            3) rejections=$((rejections + 1)) ;;
            *) failures=$((failures + 1)) ;;
        esac
    done <<< "$peers"

    if [ "$total" -eq 0 ]; then
        info "[PROPAGATION:NO_REMOTE_PEERS] 没有远端节点，区块已本地安全提交。 (No remote peers available; block committed locally.)"
        return 0
    elif [ "$success" -eq "$total" ]; then
        info "[PROPAGATION:BROADCAST_SUCCESS] 有目标且发送成功 ($success/$total)。 (Block broadcast succeeded to all targets ($success/$total).)"
        return 0
    elif [ "$success" -gt 0 ]; then
        warn "[PROPAGATION:BROADCAST_PARTIAL] 只有部分目标成功 (成功: $success/$total, 超时: $timeouts, 拒绝: $rejections, 失败: $failures)。 (Block broadcast partially succeeded ($success/$total).)"
        return 1
    else
        # 所有目标均失败 (All targets failed)
        if [ "$rejections" -gt 0 ]; then
            warn "[PROPAGATION:PEER_REJECTED] 对端明确拒绝区块 (拒绝数: $rejections/$total)。 (Peer explicitly rejected block ($rejections/$total).)"
            return 1
        elif [ "$timeouts" -gt 0 ]; then
            warn "[PROPAGATION:ACK_TIMEOUT] 已发送但无法确认接收 (超时数: $timeouts/$total)。 (Block announcement ACK timed out ($timeouts/$total).)"
            return 1
        else
            warn "[PROPAGATION:BROADCAST_FAILED] 有目标但全部失败 (不可达节点数: $failures/$total)。 (Block broadcast failed to all targets ($failures/$total).)"
            return 1
        fi
    fi
}

# =======================================================================================
# --- [GOVERNANCE] Core functions for protocol state transitions (NEW)                ---
# --- [治理] 用于协议状态转换的核心函数 (新增)                                        ---
# =======================================================================================

# This function is called after a new block is successfully added to the local chain.
# It scans for proposals that have just finished their voting window and tallies the votes.
# If a proposal passes, it schedules the state change for a future block height.
#
# 此函数在一个新区块被成功添加到本地链后调用。
# 它会扫描那些正好在此区块结束投票期的提议，并对其进行计票。
# 如果一个提议通过，它会计划在未来的某个区块高度执行状态变更。
#
# @param $1 - The height of the newly added block. / 新增区块的高度。
_protocol_tally_votes_and_schedule_changes() {
    local new_block_height="$1"
    
    # --- 治理常量 / Governance Constants ---
    local VOTE_WINDOW=100      # 投票期持续100个区块 / Voting period lasts for 100 blocks.
    local ENACTMENT_DELAY=10   # 状态变更在投票结束后10个区块发生 / State change happens 10 blocks after voting ends.
    local CONSENSUS_THRESHOLD_NUMERATOR=2
    local CONSENSUS_THRESHOLD_DENOMINATOR=3

    local proposals_to_tally
    proposals_to_tally=$(db_query_safe "$BLOCKCHAIN_DB" \
        "SELECT json_array(hash, type, data, block_height, public_key) FROM transactions WHERE type IN ('validator_propose_addition', 'validator_propose_removal', 'propose_app_template', 'propose_ibc_verifier', 'propose_new_compute_engine', 'propose_federation_key') AND (block_height + %d) = %d;" \
        "$VOTE_WINDOW" "$new_block_height")

    [ -z "$proposals_to_tally" ] && return 0

    info "[GOVERNANCE] Tallying votes for completed proposals... / [治理] 正在为已结束的提议计票..."
    
    local total_stake_at_vote_end
    total_stake_at_vote_end=$("${PYTHON_CMD}" - "$BLOCKCHAIN_DB" <<'PY_STAKE'
import sqlite3,sys
with sqlite3.connect(sys.argv[1]) as db:
    print(sum(row[0] for row in db.execute("SELECT stake FROM validators") if row[0]>0))
PY_STAKE
    ) || return 1
    [ -z "$total_stake_at_vote_end" ] || [ "$total_stake_at_vote_end" -eq 0 ] && { warn "[GOVERNANCE] Total network stake is 0, cannot tally votes."; return; }

    local row proposal_hash proposal_type proposal_data proposal_block_height proposal_pubkey
    while IFS= read -r row; do
        proposal_hash=$(jq -er '.[0]' <<< "$row") || return 1
        proposal_type=$(jq -er '.[1]' <<< "$row") || return 1
        proposal_data=$(jq -er '.[2]' <<< "$row") || return 1
        proposal_block_height=$(jq -er '.[3]' <<< "$row") || return 1
        proposal_pubkey=$(jq -er '.[4]' <<< "$row") || return 1
        detail "  -> Tallying for proposal ${proposal_hash:0:16} (type: ${proposal_type})... /   -> 正在为提议 ${proposal_hash:0:16} (类型: ${proposal_type}) 计票..."
        
        # --- [V78 Gen3 MODIFY] 增加对新投票类型的处理 ---
        # --- [V78 Gen3 MODIFY] Add handling for new vote type ---
        local vote_tx_type=""
        case "$proposal_type" in
            "validator_propose_addition") vote_tx_type="validator_vote_addition" ;;
            "validator_propose_removal") vote_tx_type="validator_vote_removal" ;;
            "propose_app_template") vote_tx_type="vote_app_template" ;;
            "propose_ibc_verifier") vote_tx_type="vote_ibc_verifier" ;;
            "propose_new_compute_engine") vote_tx_type="vote_on_compute_engine" ;;
            "propose_federation_key") vote_tx_type="vote_federation_key" ;;
            *) continue ;;  # 跳过未知类型 / Skip unknown types
        esac

        local votes
        votes=$(db_query_safe "$BLOCKCHAIN_DB" \
            "SELECT json_array(T.public_key) FROM transactions AS T WHERE T.type = %s AND json_extract(T.data, '$.proposal_tx_hash') = %s AND json_extract(T.data, '$.vote') = 'yes' AND T.block_height > %d AND T.block_height <= %d;" \
            "$vote_tx_type" "$proposal_hash" "$proposal_block_height" "$new_block_height")

        local yes_stake=0
        declare -A has_voted=()
        
        while IFS= read -r row; do
            [ -z "$row" ] && continue
            local voter_pubkey
            voter_pubkey=$(jq -er '.[0]' <<< "$row") || return 1
            local voter_hash
            voter_hash=$(_internal_hash_text "$voter_pubkey")
            [ -n "${has_voted[$voter_hash]:-}" ] && continue
            has_voted["$voter_hash"]=1

            local voter_stake
            voter_stake=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT stake FROM validators WHERE public_key_hash = %s;" "$voter_hash")
            yes_stake=$("${PYTHON_CMD}" -c 'import sys; print(int(sys.argv[1])+max(0,int(sys.argv[2])))' "$yes_stake" "${voter_stake:-0}") || return 1
        done <<< "$votes"


        
        detail "  -> Vote result: ${yes_stake} (yes stake) / ${total_stake_at_vote_end} (total stake) /   -> 投票结果: ${yes_stake} (赞成) / ${total_stake_at_vote_end} (总计)"

        if "${PYTHON_CMD}" -c 'import sys; sys.exit(0 if int(sys.argv[1])*3 >= int(sys.argv[2])*2 else 1)' "$yes_stake" "$total_stake_at_vote_end"; then
            local enactment_height=$((new_block_height + ENACTMENT_DELAY))
            msg "[GOVERNANCE] Proposal ${proposal_hash:0:16} PASSED. State change scheduled for block height ${enactment_height}."
            msg "[治理] 提议 ${proposal_hash:0:16} 已通过。状态变更计划于区块高度 ${enactment_height} 执行。"
            
            # --- [V78 Gen3 MODIFY] 增加对新提案类型数据的处理 ---
            # --- [V78 Gen3 MODIFY] Add data handling for the new proposal type ---
            # 对于应用模板提案，我们需要把提案者的 ID 也存起来
            # For app template proposals, we need to store the proposer's ID as well
            
            if [ "$proposal_type" = "propose_app_template" ]; then
                local developer_id=$(_internal_hash_text "$proposal_pubkey")
                # 将开发者 ID 附加到 JSON 数据中
                # Append the developer ID to the JSON data
                proposal_data=$(echo "$proposal_data" | jq --arg devid "$developer_id" '. + {developer_id: $devid}')
            fi
            
            db_execute_safe "$BLOCKCHAIN_DB" \
                "INSERT OR IGNORE INTO scheduled_state_changes (proposal_hash, enactment_height, type, data) VALUES (%s, %d, %s, %s);" \
                "$proposal_hash" "$enactment_height" "$proposal_type" "$proposal_data"

        else
            info "[GOVERNANCE] Proposal ${proposal_hash:0:16} FAILED to reach consensus. / [治理] 提议 ${proposal_hash:0:16} 未能达成共识。"
        fi
    done <<< "$proposals_to_tally"
}

# This function executes scheduled state changes for a given block height.
# It MUST be called BEFORE calculating the next validator for that block height.
#
# 此函数执行特定区块高度的已计划状态变更。
# 它必须在为该区块高度计算下一个验证者之前被调用。
#
# @param $1 - The block height for which to check for and execute changes. / 要检查并执行变更的区块高度。
# =======================================================================================
# --- [V100 FINAL] 协议状态变更执行器 (带所有权证明验证)                             ---
# --- [V100 FINAL] Protocol State Change Executor (with Ownership Proof Verification) ---
# =======================================================================================
# This function executes scheduled state changes for a given block height.
# It MUST be called BEFORE calculating the next validator for that block height.
#
# 此函数执行特定区块高度的已计划状态变更。
# 它必须在为该区块高度计算下一个验证者之前被调用。
#
# @param $1 - The block height for which to check for and execute changes. / 要检查并执行变更的区块高度。
_protocol_execute_scheduled_changes() {
    local current_block_height="$1"
    local TMP_DIR
    TMP_DIR=$(mktemp -d -p "$BUILD_TMP_DIR_BASE" "scheduled-state.XXXXXX") || return 1
    CORIUM_TEMP_ITEMS+=("$TMP_DIR")
    
    local changes_to_execute
    changes_to_execute=$(db_query_safe "$BLOCKCHAIN_DB" \
        "SELECT json_array(proposal_hash, type, data) FROM scheduled_state_changes WHERE enactment_height = %d ORDER BY proposal_hash;" \
        "$current_block_height")

    [ -z "$changes_to_execute" ] && return 0

    info "[GOVERNANCE] Executing scheduled state changes for block ${current_block_height}... / [治理] 正在为区块 ${current_block_height} 执行已计划的状态变更..."

    local row proposal_hash change_type change_data
    while IFS= read -r row; do
        proposal_hash=$(jq -er '.[0]' <<< "$row") || return 1
        change_type=$(jq -er '.[1]' <<< "$row") || return 1
        change_data=$(jq -er '.[2]' <<< "$row") || return 1
        case "$change_type" in
            "validator_propose_addition")
                local pubkey stake pubkey_hash
                pubkey=$(echo "$change_data" | jq -r .target_pubkey)
                stake=$(echo "$change_data" | jq -r .initial_stake)
                pubkey_hash=$(_internal_hash_text "$pubkey")
                
                msg "[GOVERNANCE] ADDING new validator ${pubkey_hash:0:16} with stake ${stake}. / [治理] 正在添加新验证者 ${pubkey_hash:0:16}，权益为 ${stake}。"
                db_execute_safe "$BLOCKCHAIN_DB" \
                    "INSERT OR IGNORE INTO validators (public_key, public_key_hash, stake, last_block) VALUES (%s, %s, %d, %d);" \
                    "$pubkey" "$pubkey_hash" "$stake" "$current_block_height"
                ;;

            "validator_propose_removal")
                local pubkey_hash
                pubkey_hash=$(echo "$change_data" | jq -r .target_pubkey_hash)

                msg "[GOVERNANCE] REMOVING validator ${pubkey_hash:0:16} from active set. / [治理] 正在从活跃集合中移除验证者 ${pubkey_hash:0:16}。"
                db_execute_safe "$BLOCKCHAIN_DB" "UPDATE validators SET stake = 0 WHERE public_key_hash = %s;" "$pubkey_hash"
                ;;
            
            "propose_app_template")
                local name pkg_id package_hash manifest_hash dev_sig developer_id handles_tx_types
                name=$(echo "$change_data" | jq -r .template_name)
                pkg_id=$(echo "$change_data" | jq -r .pkg_id)
                package_hash=$(echo "$change_data" | jq -r .package_hash)
                manifest_hash=$(echo "$change_data" | jq -r .manifest_hash)
                dev_sig=$(echo "$change_data" | jq -r .developer_signature)
                developer_id=$(echo "$change_data" | jq -r .developer_id)
                handles_tx_types=$(echo "$change_data" | jq -c .handles_tx_types)
                
                msg "[治理] 正在激活并安装新的应用模板: '${name}' / [GOVERNANCE] Activating and installing new Application Template: '${name}'"
                
                # [Batch 3] 完整生命周期闭环: 下载 -> 哈希校验 -> 签名校验 -> 解包 -> schema install
                # 1. 尝试从 P2P 下载包 (阻塞直到成功，因为在确定性状态机中必须有数据才能继续)
                # 实际生产中这里会有复杂的异步和超时，但目前作为原型闭环，我们通过 _p2p_download_object 阻塞获取
                local target_pkg_file="${TMP_DIR}/app_template_${package_hash}.tar.gz"
                
                # 如果我们自己在本地已经有了包缓存（例如提议者自己），则直接复制
                local cached_pkg=$(ls "${BINARY_CACHE}/"*"${package_hash}"* 2>/dev/null | head -n 1)
                if [ -n "$cached_pkg" ] && [ -f "$cached_pkg" ]; then
                    cp "$cached_pkg" "$target_pkg_file"
                else
                    info "  -> 正在从 P2P 网络下载模板包... / Downloading template package from P2P..."
                    _download_file_p2p "$manifest_hash" "$target_pkg_file" || return 1
                fi
                
                # 2. 校验哈希 (Verify package_hash)
                if [ -f "$target_pkg_file" ]; then
                    local actual_hash; actual_hash=$(calculate_hash "$target_pkg_file")
                    if [ "$actual_hash" != "$package_hash" ]; then
                        error "[治理] 模板 ${name} 包哈希不匹配，中止安装！(Expected: $package_hash, Actual: $actual_hash)"
                        return 1
                    fi
                else
                    error "[治理] 无法获取模板 ${name} 的程序包，安装失败！"
                    return 1
                fi
                
                # 3. 校验签名 (Verify developer_signature)
                if [ -n "$dev_sig" ] && [ "$dev_sig" != "null" ]; then
                    local sig_file="${TMP_DIR}/app_template_${package_hash}.sig"
                    if ! printf '%s' "$dev_sig" | base64 -d > "$sig_file" || ! _verify_gpg_signature "$target_pkg_file" "$sig_file" >/dev/null; then
                        error "[治理] 模板 ${name} 开发者签名验证失败！ / Template developer signature verification failed!"
                        return 1
                    fi
                fi
                
                # 4. 调用原生模板安装器完成注册 (Install using native template installer)
                if ! _internal_install_template "$pkg_id" "$target_pkg_file"; then
                    error "[治理] 模板 ${name} 包安装失败！/ Template installation failed!"
                    return 1
                fi
                
                # 获取安装后的目录
                get_pkg_id_parts "$pkg_id"
                local inst_pkg_name="${PKG_CATEGORY}/${PKG_NAME}"
                local inst_pkg_ver="${PKG_VERSION:-}"
                if [ -z "$inst_pkg_ver" ]; then
                    local build_file_tmp="${TMP_DIR}/app_build_${package_hash}"
                    tar -Oxf "$target_pkg_file" ".corium/template.build" > "$build_file_tmp" 2>/dev/null || true
                    inst_pkg_ver=$(_parse_build_file "$build_file_tmp" | grep "^pkgver=" | cut -d= -f2)
                fi
                local template_storage_dir="${VAR_LIB_CORIUM_DIR}/app_templates/${inst_pkg_name//\//_}/${inst_pkg_ver}"
                
                local schema_version=1
                if [ -d "${template_storage_dir}/schema" ]; then
                    info "  -> 发现数据库 schema，正在确定性执行 migrations... / Found database schema, executing deterministic migrations..."
                    # 按数字顺序执行 sql 文件
                    local sql_file
                    while IFS= read -r -d '' sql_file; do
                        info "    -> 执行 $sql_file"
                        sqlite3 -bail "$BLOCKCHAIN_DB" < "$sql_file" || return 1
                        schema_version=$((schema_version + 1))
                    done < <(find "${template_storage_dir}/schema" -maxdepth 1 -type f -name '*.sql' -print0 | LC_ALL=C sort -z)
                fi
                
                # 清理临时文件
                rm -rf "$target_pkg_file" "${TMP_DIR}/app_template_${package_hash}.sig"
                
                # 5. 写入数据库激活状态
                db_execute_safe "$BLOCKCHAIN_DB" \
                    "INSERT OR REPLACE INTO active_app_templates (template_name, pkg_id, package_hash, manifest_hash, developer_signature, developer_id, schema_version, handles_tx_types, activation_height) VALUES (%s, %s, %s, %s, %s, %s, %d, %s, %d);" \
                    "$name" "$pkg_id" "$package_hash" "$manifest_hash" "$dev_sig" "$developer_id" "$schema_version" "$handles_tx_types" "$current_block_height"
                ;;

            "propose_new_compute_engine")
                local engine_weight
                engine_weight=$(jq -er '(.reward_weight // 100) | select(type=="number" and floor==. and .>=1 and .<=1000000)' <<< "$change_data") || return 1
                db_execute_safe "$BLOCKCHAIN_DB" "UPDATE compute_engines SET is_active=1,reward_weight=%d WHERE engine_id=%s;" "$engine_weight" "$proposal_hash" || return 1
                ;;

            "propose_ibc_verifier")
                local target_chain verifier_id initial_hash
                target_chain=$(echo "$change_data" | jq -r .target_chain_id)
                verifier_id=$(echo "$change_data" | jq -r .verifier_id)
                initial_hash=$(echo "$change_data" | jq -r .initial_header_hash)
                
                msg "[治理] 正在激活 '${target_chain}' 的 IBC 验证器: ${verifier_id}"
                msg "[Governance] Activating IBC verifier for '${target_chain}': ${verifier_id}"

                db_execute_safe "$BLOCKCHAIN_DB" "UPDATE ibc_verifiers SET is_active = 0 WHERE target_chain_id = %s;" "$target_chain"

                db_execute_safe "$BLOCKCHAIN_DB" \
                    "INSERT INTO ibc_verifiers (target_chain_id, verifier_id, last_known_header_hash, is_active, activation_height) VALUES (%s, %s, %s, 1, %d)
                     ON CONFLICT(target_chain_id) DO UPDATE SET verifier_id=excluded.verifier_id, last_known_header_hash=excluded.last_known_header_hash, is_active=1, activation_height=excluded.activation_height;" \
                    "$target_chain" "$verifier_id" "$initial_hash" "$current_block_height"
                ;;

            "propose_federation_key")
                local gpg_key_b64 owner_id corium_sig gpg_sig
                gpg_key_b64=$(echo "$change_data" | jq -r .gpg_key_b64)
                owner_id=$(echo "$change_data" | jq -r .owner_id)
                corium_sig=$(echo "$change_data" | jq -r .proof.corium_signature_on_gpg_fingerprint)
                gpg_sig=$(echo "$change_data" | jq -r .proof.gpg_signature_on_corium_id | base64 -d)

                # --- [V100 核心安全验证] ---
                # --- [V100 CORE SECURITY VERIFICATION] ---
                info "[IBC-Trust] 正在对提案 ${proposal_hash:0:12} 执行最终的所有权验证... / Performing final ownership verification for proposal ${proposal_hash:0:12}..."
                
                # 1. 验证 Corium 签名
                # 1. Verify the Corium signature
                local owner_pubkey_file; owner_pubkey_file=$(_get_identity_pubkey "$owner_id")
                local temp_key_file; temp_key_file=$(mktemp)
                CORIUM_TEMP_ITEMS+=("$temp_key_file")
                echo "$gpg_key_b64" | base64 -d > "$temp_key_file"
                local gpg_fingerprint; gpg_fingerprint=$(gpg --with-colons --import-options show-only --import < "$temp_key_file" 2>/dev/null | awk -F: '/^fpr/ {print $10; exit}')
                
                if [ -z "$owner_pubkey_file" ] || ! verify_signature "$gpg_fingerprint" "$corium_sig" "$owner_pubkey_file"; then
                    warn "[IBC-Trust] 提案 ${proposal_hash:0:12} 验证失败：Corium 签名无效。提案被拒绝。"
                    warn "[IBC-Trust] Proposal ${proposal_hash:0:12} verification FAILED: Invalid Corium signature. Proposal rejected."
                    rm -f "$temp_key_file"
                    continue # 跳过此变更
                fi

                # 2. 验证 GPG 签名
                # 2. Verify the GPG signature
                if ! gpg_verify_signature "$owner_id" "$gpg_sig" "$(cat "$temp_key_file")"; then
                     warn "[IBC-Trust] 提案 ${proposal_hash:0:12} 验证失败：GPG 签名无效。提案被拒绝。"
                     warn "[IBC-Trust] Proposal ${proposal_hash:0:12} verification FAILED: Invalid GPG signature. Proposal rejected."
                     rm -f "$temp_key_file"
                     continue # 跳过此变更
                fi
                rm -f "$temp_key_file"
                # --- [验证结束] ---

                info "[IBC-Trust] 所有权证明有效。正在执行联邦密钥广播... / Ownership proof is valid. Executing federated key broadcast..."
                
                # 为广播消息创建签名。签名者是提案者自己。
                # Create the signature for the broadcast message. The signer is the proposer themselves.
                local signature; signature=$(sign_data "$gpg_key_b64" "$USER_IDENTITY_FILE")
                
                local ibc_payload
                ibc_payload=$(jq -n \
                    --arg key "$gpg_key_b64" \
                    --arg oid "$owner_id" \
                    --arg sig "$signature" \
                    '{gpg_key_b64: $key, owner_id: $oid, signature: $sig}')
                
                _internal_ibc_dispatch "FEDERATION_ALL" "IBC_GPG_KEY_BROADCAST" "$ibc_payload"
                ;;

        esac
        # 从计划中移除已执行的变更，以防重复执行
        # Remove the executed change from the schedule to prevent re-execution
        db_execute_safe "$BLOCKCHAIN_DB" "DELETE FROM scheduled_state_changes WHERE proposal_hash = %s;" "$proposal_hash"
    done <<< "$changes_to_execute"
}


# --- Function 5: Get a validator's full public key from their ID (hash) ---
# --- 函数 5: 根据验证者的ID (哈希) 获取其完整的公钥 ---
# =======================================================================================
# --- FUNCTION: _blockchain_get_validator_pubkey (DB-OPTIMIZED VERSION) ---
# --- 函数: _blockchain_get_validator_pubkey (数据库优化版)               ---
# =======================================================================================
_blockchain_get_validator_pubkey() {
    [ $# -eq 1 ] && [[ "$1" =~ ^[a-f0-9]{64}$ ]] || return 1
    local validator_id="$1" pubkey pubkey_cache_dir="${VAR_CACHE_CORIUM_DIR}/validator_pubkeys" staged
    pubkey=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT public_key FROM validators WHERE public_key_hash=%s;" "$validator_id") || return 1
    if [ -z "$pubkey" ]; then
        pubkey=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT json_extract(w.proof, '$.miner_public_key') FROM blocks b JOIN block_work w ON b.hash = w.hash WHERE b.validator=%s LIMIT 1;" "$validator_id" 2>/dev/null || true)
    fi
    if [ -z "$pubkey" ]; then
        pubkey=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT public_key FROM onchain_identities WHERE agent_id=%s LIMIT 1;" "$validator_id" 2>/dev/null || true)
    fi
    [ -n "$pubkey" ] && [ "$(_internal_hash_text "$pubkey")" = "$validator_id" ] || return 1
    mkdir -p "$pubkey_cache_dir" || return 1
    staged=$(mktemp "$pubkey_cache_dir/key.XXXXXX") || return 1
    printf '%s\n' "$pubkey" > "$staged" || { rm -f -- "$staged"; return 1; }
    mv -f -- "$staged" "$pubkey_cache_dir/$validator_id.pub" || return 1
    printf '%s\n' "$pubkey_cache_dir/$validator_id.pub"
}



# --- SECTION 7: P2P FILE SHARING ---

# =========================================================================================
# --- P2P Download Architecture: A Four-Layer Model                                     ---
# --- P2P 下载架构：一个四层模型                                                        ---
# =========================================================================================
#
# The P2P file download system in Corium is designed using a four-layer architectural
# model. This separation of concerns makes the system robust, modular, and easier to
# maintain. Each layer has a distinct responsibility and only communicates with the
# layer directly above or below it.
#
# Corium中的P2P文件下载系统是基于一个四层架构模型设计的。这种关注点分离的设计
# 使得整个系统更加健壮、模块化且易于维护。每一层都有明确的职责，并且只与它
# 相邻的上一层或下一层通信。
#
#
# --- Layer 4: Network Transport Layer / 第四层: 网络传输层 ---
#
#   - Responsibility: To perform a single, atomic download operation from a
#     specific, known network address (ip:port). This layer has no knowledge of
#     the DHT, providers, or retry logic. It's the "last mile" of the download.
#   - 职责: 负责执行一次单一的、原子性的下载操作，从一个具体的、已知的网络地址
#     (ip:port) 获取数据。这一层完全不知道DHT、提供者或重试逻辑的存在。它是下载的“最后一公里”。
#
#   - Key Function / 关键函数: p2p_request_chunk()
#
#   - Analogy / 类比: The Mail Carrier. Give them a precise address, and they
#     will attempt to retrieve the package from that address.
#   - 邮递员。你给他们一个精确的地址，他们就去那个地址尝试取回包裹。
#
#
# --- Layer 3: Dispatch Layer / 第三层: 调度层 ---
#
#   - Responsibility: To translate an abstract provider identity (which could be
#     a node_id or an ip:port string) into the concrete arguments needed by the
#     Network Transport Layer. It resolves the final ip:port if necessary.
#   - 职责: 负责将一个抽象的提供者身份（可能是一个node_id或一个ip:port字符串）
#     解析为网络传输层所需要的具体参数。如果需要，它会解析出最终的ip和port。
#
#   - Key Function / 关键函数: p2p_download_chunk_from_provider()
#
#   - Analogy / 类比: The Post Office Sorting Center. It receives a task for a
#     provider, looks up their concrete address in its directory (the DHT database),
#     and dispatches the Mail Carrier (Layer 4) to that address.
#   - 邮局分拣中心。它接收到一个要发给某个提供者的任务，在它的名录（DHT数据库）中
#     查找此人的具体地址，然后派遣邮递员（第四层）前往该地址。
#
#
# --- Layer 2: Unified Interface Layer / 第二层: 统一接口层 ---
#
#   - Responsibility: This is the brain of the robust download logic. It takes an
#     object hash, finds ALL available providers (both local and remote) using the
#     DHT, and then iterates through them, calling the Dispatch Layer (Layer 3) for
#     each one until the download is successful. This is where fault tolerance and
#     retry logic are implemented.
#   - 职责: 这是整个健壮下载逻辑的大脑。它接收一个对象哈希，使用DHT查找所有
#     可用的提供者（包括本地和远程），然后遍历他们，为每一个提供者调用调度层
#     （第三层），直到下载成功为止。容错和重试逻辑在这一层实现。
#
#   - Key Function / 关键函数: _p2p_download_object()
#
#   - Analogy / 类比: The Logistics Manager. They receive an order for a product
#     (the object_hash). They first check the local warehouse. If it's not there,
#     they query all known suppliers (remote providers via dht_find_chunk) and
#     send out purchase orders (call Layer 3) one by one until the product is
#     procured.
#   - 物流经理。他收到一份产品（对象哈希）的订单。他首先检查本地仓库。如果本地没有，
#     他会查询所有已知的供应商（通过dht_find_chunk找到的远程提供者），然后逐一
#     发出采购订单（调用第三层），直到产品采购成功。
#
#
# --- Layer 1: Application Layer / 第一层: 应用层 ---
#
#   - Responsibility: These are the high-level functions that need to acquire a file
#     or object from the P2P network for a specific "business" purpose. They do not
#     care about the underlying complexity. They simply call the Unified Interface
#     (Layer 2) and expect the object to be delivered.
#   - 职责: 这些是出于某个具体的“业务”目的，需要从P2P网络获取文件或对象的高层函数。
#     它们不关心底层的复杂性。它们只调用统一接口层（第二层），并期望对象被成功交付。
#
#   - Key Functions / 关键函数:
#       - p2p_reconstruct_file() (needs to download many chunks) / (需要下载多个数据块)
#       - forum_fetch_object() (needs to download a forum post or attachment) / (需要下载论坛帖子或附件)
#       - _download_file_p2p() (needs to download a source file for a package) / (需要为软件包下载源文件)
#
#   - Analogy / 类比: The Customer. They just want their final product (a reconstructed
#     file, a forum post) and place an order with the Logistics Manager (Layer 2).
#   - 客户。他们只想要最终的产品（一个重组好的文件、一篇论坛帖子），于是他们向
#     物流经理（第二层）下订单。
#
# =========================================================================================

# Takes a local file, splits it into chunks, announces the chunks, creates a manifest,
# announces the manifest, and returns the single root hash of the manifest file.
# This is the canonical function for uploading a single file to the P2P network.
# 接收一个本地文件，将其分块，宣告数据块，创建清单，宣告清单，并返回清单文件的唯一根哈希。
# 这是将单个文件上传到P2P网络的标准函数。
#
# @param $1 - file_path (The path to the file to upload / 要上传的文件的路径)
# @return The P2P root hash of the file's manifest. / 文件清单的 P2P 根哈希。
_p2p_upload_file() {
    local file_path="$1"
    [ ! -f "$file_path" ] && { error "文件未找到，无法上传: $file_path / File not found, cannot upload: $file_path"; return 1; }

    # [重构] 此函数现在调用 p2p_split_file 来处理分块和清单创建
    # [REFACTOR] This function now calls p2p_split_file to handle chunking and manifest creation.
    local manifest_path
    manifest_path=$(p2p_split_file "$file_path")
    [ ! -f "$manifest_path" ] && { error "创建清单失败: $file_path / Failed to create manifest for: $file_path"; return 1; }

    # --- [核心新增逻辑] 将清单文件本身作为 P2P 对象进行宣告 ---
    # --- [CORE NEW LOGIC] Announce the manifest file itself as a P2P object ---
    info "正在宣告清单文件到网络... / Announcing manifest file to the network..."
    local manifest_hash
    manifest_hash=$(calculate_hash "$manifest_path")
    
    # 我们需要将清单文件移动到对象目录，以使其可被文件服务器提供
    # We need to move the manifest to the objects directory to make it serveable by the file server.
    local manifest_final_path="${P2P_DIR}/objects/${manifest_hash}"
    mkdir -p "$(dirname "$manifest_final_path")"
    mv "$manifest_path" "$manifest_final_path"

    dht_store_chunk "$manifest_hash" "$manifest_final_path" 0 "$(stat -c%s "$manifest_final_path")"
    
    detail "文件根哈希 / File Root Hash: $manifest_hash"
    echo "$manifest_hash"
}

# Recursively finds all files in a directory, uploads each one to the P2P network,
# creates a root manifest mapping file paths to their P2P hashes, and returns the
# single root hash of the entire directory.
# 递归地查找目录中的所有文件，将每个文件上传到P2P网络，创建一个映射文件路径到其P2P哈希的根清单，
# 并返回代表整个目录的唯一根哈希。
#
# @param $1 - dir_path (The path to the directory to upload / 要上传的目录的路径)
# @return The P2P root hash of the directory's root manifest. / 目录的根清单的 P2P 根哈希。
_p2p_upload_directory() {
    local dir_path="$1"
    [ ! -d "$dir_path" ] && { error "目录未找到，无法上传: $dir_path / Directory not found, cannot upload: $dir_path"; return 1; }

    local temp_root_manifest
    temp_root_manifest=$(mktemp)
    CORIUM_TEMP_ITEMS+=("$temp_root_manifest")

    info "正在准备上传目录: $dir_path / Preparing to upload directory: $dir_path"

    # 使用 jq 高效地构建 JSON 对象
    # Use jq to efficiently build the JSON object
    local files_json="[]"
    while IFS= read -r file; do
        local relative_path
        relative_path=${file#"$dir_path"/}
        msg "  -> 正在上传文件... / Uploading file...: $relative_path"
        
        local file_hash
        file_hash=$(_p2p_upload_file "$file")
        [ -z "$file_hash" ] && { error "上传文件失败: $relative_path / Failed to upload file: $relative_path"; return 1; }
        
        files_json=$(echo "$files_json" | jq --arg key "$relative_path" --arg value "$file_hash" '. += [{key: $key, value: $value}]')
    done < <(find "$dir_path" -type f -print)

    # 创建最终的根清单
    # Create the final root manifest
    # 我们假设 index.html 是默认索引文件
    # We assume index.html is the default index file.
    jq -n --argjson files "$files_json" \
        '{
            "type": "directory_manifest",
            "index": "index.html",
            "files": ($files | from_entries)
        }' > "$temp_root_manifest"

    # Generator output may explicitly request SPA/WASM behavior. The export
    # receipt is data only; no generator or server-side plugin is executed.
    if [ -f "$dir_path/ziokt-export.json" ]; then
        local export_options
        export_options=$(jq -ce 'select(.schema=="ziokt.static-blog-export.v1" and (.static_routing=="clean" or .static_routing=="spa") and (.static_wasm|type=="boolean")) | {static_routing,static_wasm}' "$dir_path/ziokt-export.json") || return 1
        jq --argjson options "$export_options" '. + $options' "$temp_root_manifest" > "$temp_root_manifest.options" || return 1
        mv "$temp_root_manifest.options" "$temp_root_manifest"
    fi

    info "正在上传根清单... / Uploading root manifest..."
    local root_hash
    root_hash=$(_p2p_upload_file "$temp_root_manifest")
    
    if [ -n "$root_hash" ]; then
        msg "目录上传成功！根哈希: $root_hash / Directory upload successful! Root Hash: $root_hash"
        echo "$root_hash"
    else
        error "上传根清单失败。 / Failed to upload root manifest."
        return 1
    fi
}

# [重构] p2p_split_file 现在是一个内部函数，它分块文件并返回本地清单的路径。
# [REFACTORED] p2p_split_file is now an internal function that splits a file and returns the path to the LOCAL manifest.
p2p_split_file() {
    local file_path="$1" chunk_size="$P2P_CHUNK_SIZE" temp_dir
    [[ "$chunk_size" =~ ^[1-9][0-9]{0,8}$ ]] && [ -f "$file_path" ] || return 1
    mkdir -p "$BUILD_TMP_DIR_BASE" "$P2P_DIR/objects" || return 1
    temp_dir=$(mktemp -d -p "$BUILD_TMP_DIR_BASE" "split-work.XXXXXX") || return 1
    CORIUM_TEMP_ITEMS+=("$temp_dir")
    local file_size chunk_count i chunk_hash chunk_file
    local -a chunk_hashes=()
    file_size=$(stat -c%s -- "$file_path") || return 1
    chunk_count=$(( (file_size + chunk_size - 1) / chunk_size ))
    for (( i=0; i<chunk_count; i++ )); do
        chunk_file="$temp_dir/chunk.$i"
        dd if="$file_path" of="$chunk_file" bs="$chunk_size" skip="$i" count=1 status=none || return 1
        chunk_hash=$(sha256sum -- "$chunk_file"); chunk_hash=${chunk_hash%% *}
        chunk_hashes+=("$chunk_hash")
        mv -f -- "$chunk_file" "$P2P_DIR/objects/$chunk_hash" || return 1
        dht_store_chunk "$chunk_hash" "$P2P_DIR/objects/$chunk_hash" 0 "$(stat -c%s -- "$P2P_DIR/objects/$chunk_hash")" || return 1
    done
    printf '%s\n' "${chunk_hashes[@]}" | jq -Rsc 'split("\n") | map(select(length > 0))' > "$temp_dir/hashes.json" || return 1
    jq -n --arg name "$(basename -- "$file_path")" --argjson size "$file_size" --argjson csize "$chunk_size" \
        --slurpfile hashes "$temp_dir/hashes.json" '{file:$name,size:$size,chunk_size:$csize,chunks:$hashes[0]}' > "$temp_dir/manifest.json" || return 1
    printf '%s\n' "$temp_dir/manifest.json"
}

p2p_reconstruct_file() {
    local manifest_file="$1" output_file="$2" metadata file_size chunk_size staged_output
    metadata=$(jq -er '
        select(type=="object" and (.size|type=="number") and (.size>=0 and .size<=9007199254740991 and (.size|floor)==.size)
        and (.chunk_size|type=="number") and (.chunk_size>0 and .chunk_size<=999999999 and (.chunk_size|floor)==.chunk_size)
        and (.chunks|type=="array") and all(.chunks[]; type=="string" and test("^[a-f0-9]{64}$"))
        and (.chunks|length)==((.size/.chunk_size)|ceil)) | [.size,.chunk_size] | @tsv' "$manifest_file") || return 1
    read -r file_size chunk_size <<< "$metadata"
    staged_output=$(mktemp "${output_file}.XXXXXX") || return 1
    CORIUM_TEMP_ITEMS+=("$staged_output")
    local chunk_hash provider_info chunk_file chunk_offset provider_size digest expected_size i=0 written providers_data
    local -a providers=() chunk_hashes=()
    mapfile -t chunk_hashes < <(jq -r '.chunks[]' "$manifest_file")
    for chunk_hash in "${chunk_hashes[@]}"; do
        expected_size=$chunk_size
        ((file_size - i * chunk_size >= chunk_size)) || expected_size=$((file_size - i * chunk_size))
        providers_data=$(dht_find_chunk "$chunk_hash") || return 1
        mapfile -t providers <<< "$providers_data"
        written=false
        for provider_info in "${providers[@]}"; do
            local scratch_chunk
            scratch_chunk=$(mktemp -p "$BUILD_TMP_DIR_BASE" "chunk.XXXXXX") || return 1
            CORIUM_TEMP_ITEMS+=("$scratch_chunk")
            if [[ "$provider_info" == local:* ]]; then
                IFS='|' read -r chunk_file chunk_offset provider_size <<< "${provider_info#local:}"
                [[ "$chunk_offset" =~ ^[0-9]{1,16}$ && "$provider_size" =~ ^[0-9]{1,16}$ ]] || continue
                [ "$provider_size" -eq "$expected_size" ] || continue
                dd if="$chunk_file" of="$scratch_chunk" iflag=skip_bytes,count_bytes skip="$chunk_offset" count="$provider_size" status=none || continue
            else
                [ -n "$provider_info" ] || continue
                p2p_download_chunk_from_provider "$chunk_hash" "$scratch_chunk" "$provider_info" || continue
            fi
            [ "$(stat -c%s -- "$scratch_chunk")" -eq "$expected_size" ] || continue
            digest=$(sha256sum -- "$scratch_chunk"); digest=${digest%% *}
            [ "$digest" = "$chunk_hash" ] || continue
            cat -- "$scratch_chunk" >> "$staged_output" || return 1
            written=true
            break
        done
        $written || return 1
        ((i+=1))
    done
    [ "$(stat -c%s -- "$staged_output")" -eq "$file_size" ] || return 1
    mv -f -- "$staged_output" "$output_file"
}

# Request chunk from specific node (HARDENED, RESUMABLE, WITH TOFU CERTIFICATE VERIFICATION)
# (已加固、支持断点续传且通过 TOFU 证书验证)
#
# This is the final, production-ready version of the lowest-level network transport function.
# 这是最底层的网络传输函数的、最终的、生产就绪版本。
_internal_verify_object_hash() {
    [[ "$1" =~ ^[a-f0-9]{64}$ ]] || return 1
    if jq -e 'type=="object" and has("work")' "$2" >/dev/null 2>&1; then
        _corium_work_consensus verify-file "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$2" "$1" >/dev/null
        return $?
    fi
    if [[ "$CORIUM_NETWORK_ID" = ziokt-main-recovery-20261024 || "$CORIUM_NETWORK_ID" = ziokt-dna-side-20261024 ]] && jq -e 'type=="object" and keys==["data","public_key","signature","timestamp","type"]' "$2" >/dev/null 2>&1; then
        local scoped_body scoped_height
        scoped_height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT MAX(height)+1 FROM blocks;") || return 1
        scoped_body=$(_corium_transaction_bytes "$(jq -er .type "$2")" "$(jq -c .data "$2")" "$(jq -er .timestamp "$2")" "$(jq -er .public_key "$2")" "$scoped_height") || return 1
        if [ "$(_internal_hash_text "$scoped_body")" = "$1" ]; then
            local scoped_key
            scoped_key=$(mktemp) || return 1
            CORIUM_TEMP_ITEMS+=("$scoped_key")
            jq -jr .public_key "$2" > "$scoped_key"
            verify_signature "$scoped_body" "$(jq -er .signature "$2")" "$scoped_key"
            return $?
        fi
    fi
    "${PYTHON_CMD}" - "$2" "$1" "$BLOCKCHAIN_DB" <<'PY_OBJECT_VERIFY'
def verify_object_file(path, expected, chain_path):
    import hashlib,json,sqlite3,pathlib,re
    from cryptography.hazmat.primitives import serialization,hashes
    from cryptography.hazmat.primitives.asymmetric import ec
    with open(path,'rb') as file:
        digest=hashlib.sha256()
        for chunk in iter(lambda:file.read(1048576),b''): digest.update(chunk)
        raw_hash=digest.hexdigest()
    if raw_hash==expected: return True
    content=pathlib.Path(path).read_bytes()
    # Existing identity IDs omit the PEM trailing newline.
    if content.startswith(b'-----BEGIN PUBLIC KEY-----'):
        key=serialization.load_pem_public_key(content)
        return isinstance(key,ec.EllipticCurvePublicKey) and isinstance(key.curve,ec.SECP256K1) and hashlib.sha256(content.rstrip(b'\n')).hexdigest()==expected
    if content.endswith(b'\n'):
        try:
            legacy=json.loads(content)
            if isinstance(legacy,dict) and {'author','signature','content_hash','timestamp'}.issubset(legacy) and ('title' in legacy or 'topic_id' in legacy) and hashlib.sha256(content[:-1]).hexdigest()==expected: return True
        except (ValueError,UnicodeError): pass
    def unique(pairs):
        result={}
        for k,v in pairs:
            if k in result: raise ValueError('Duplicate object field')
            result[k]=v
        return result
    obj=json.loads(content.decode('utf-8'),object_pairs_hook=unique)
    if not isinstance(obj,dict): return False
    if set(obj)=={'type','data','timestamp','public_key','signature'}:
        if not isinstance(obj['type'],str) or not isinstance(obj['data'],dict) or type(obj['timestamp']) is not int or obj['timestamp']<0: return False
        body={k:obj[k] for k in ('type','data','timestamp')};pem=obj['public_key']
    elif set(obj)=={'height','previous_hash','timestamp','validator','signature','transactions'}:
        if type(obj['height']) is not int or type(obj['timestamp']) is not int or obj['height']<0 or obj['timestamp']<0: return False
        if not isinstance(obj['transactions'],list) or not all(isinstance(v,str) and re.fullmatch(r'[a-f0-9]{64}',v) for v in obj['transactions']): return False
        if not isinstance(obj['previous_hash'],str) or not re.fullmatch(r'[a-f0-9]{64}',obj['previous_hash']): return False
        with sqlite3.connect(pathlib.Path(chain_path).resolve().as_uri()+'?mode=ro',uri=True) as db:
            row=db.execute('SELECT public_key FROM validators WHERE public_key_hash=?',(obj['validator'],)).fetchone()
        if not row or hashlib.sha256(row[0].encode()).hexdigest()!=obj['validator']: return False
        body={k:obj[k] for k in ('height','previous_hash','timestamp','transactions')};pem=row[0]
    else: return False
    canonical=json.dumps(body,ensure_ascii=False,separators=(',',':'),allow_nan=False).encode()
    if hashlib.sha256(canonical).hexdigest()!=expected: return False
    key=serialization.load_pem_public_key(pem.encode())
    if not isinstance(key,ec.EllipticCurvePublicKey) or not isinstance(key.curve,ec.SECP256K1): return False
    key.verify(bytes.fromhex(obj['signature']),canonical,ec.ECDSA(hashes.SHA256()))
    return True
import sys
try:
    sys.exit(0 if verify_object_file(sys.argv[1],sys.argv[2],sys.argv[3]) else 1)
except Exception:
    sys.exit(1)
PY_OBJECT_VERIFY
}

p2p_request_chunk() (
    local node_ip="$1"
    local node_port="$2"
    local chunk_hash="$3"
    local destination="$4" output_file
    [[ "$chunk_hash" =~ ^[a-f0-9]{64}$ && "$node_port" =~ ^[1-9][0-9]{0,4}$ ]] || return 1
    [ "$node_port" -le "$((65535-P2P_FILE_PORT_OFFSET))" ] || return 1
    output_file=$(mktemp "${destination}.download.XXXXXX") || return 1
    trap 'rm -f -- "$output_file"' EXIT
    if [ -f "$destination" ]; then cp -- "$destination" "$output_file" || return 1; fi
    
    local endpoint_host="$node_ip"
    [[ "$endpoint_host" != *:* ]] || endpoint_host="[$endpoint_host]"
    # --- 步骤 1: TOFU (Trust On First Use) 证书验证与缓存 ---
    # --- Step 1: TOFU (Trust On First Use) Certificate Verification & Caching ---
    local peer_cert_file="${PEER_CERT_CACHE}/${node_ip//:/_}_${node_port}.pem"
    if [ ! -f "$peer_cert_file" ]; then
        local temp_cert_file; temp_cert_file=$(mktemp)
        CORIUM_TEMP_ITEMS+=("$temp_cert_file")

        # 使用 openssl s_client 连接到对方的文件服务器端口以获取证书
        # Use openssl s_client to connect to the peer's file server port to retrieve the certificate
        if ! timeout 10s openssl s_client -connect "$endpoint_host:$((node_port + P2P_FILE_PORT_OFFSET))" -showcerts </dev/null 2>/dev/null | \
           openssl x509 -outform PEM > "$temp_cert_file"; then
            error "无法获取文件服务器 ${node_ip}:${node_port} 的 TLS 证书。 (Failed to retrieve TLS certificate from file server ${node_ip}:${node_port}.)"
            return 1
        fi
        
        # 确保获取到的证书文件不为空
        # Ensure the retrieved certificate file is not empty
        if [ ! -s "$temp_cert_file" ]; then
            error "从 ${node_ip}:${node_port} 获取到的 TLS 证书为空。 (Retrieved an empty TLS certificate from ${node_ip}:${node_port}.)"
            return 1
        fi

        local fingerprint; fingerprint=$(openssl x509 -in "$temp_cert_file" -noout -fingerprint -sha256 | cut -d'=' -f2)
        local final_auto_trust_policy="${CORIUM_CONFIG_CACHE[p2p_auto_trust_new_nodes]:-${AUTO_TRUST_NEW_NODES}}"

        if [ "$final_auto_trust_policy" = "true" ]; then
            warn "自动化信任已启用: 自动信任新的文件服务器 ${node_ip}:${node_port}"
            warn "AUTO-TRUST ENABLED: Automatically trusting new file server ${node_ip}:${node_port}"
        elif [ -t 0 ]; then # 检查是否在交互式终端中
            echo; warn "文件服务器 '${node_ip}:${node_port}' 的真实性无法确认。"
            warn "The authenticity of file server '${node_ip}:${node_port}' can't be established."
            echo -e "SHA256 证书指纹 (Certificate Fingerprint): \033[1;33m${fingerprint}\033[0m"
            
            read -rp "您确定要继续连接吗？ (Are you sure you want to continue connecting?) [y/N] " choice
            if [[ ! "$choice" =~ ^[yY] ]]; then
                info "连接已取消。 (Connection cancelled.)"; return 1;
            fi
        else
            warn "在非交互式会话中，无法确认新的文件服务器指纹。连接失败。 / Cannot confirm new file server fingerprint in a non-interactive session. Connection failed."
            return 1
        fi

        mkdir -p "$(dirname "$peer_cert_file")"
        mv "$temp_cert_file" "$peer_cert_file"
        info "文件服务器已被信任并缓存。 / File server has been trusted and cached."
    fi
    
    openssl verify -CAfile "$peer_cert_file" "$peer_cert_file" >/dev/null 2>&1 || return 1
    local peer_pin
    peer_pin=$(openssl x509 -in "$peer_cert_file" -pubkey -noout | openssl pkey -pubin -outform DER | openssl dgst -sha256 -binary | openssl base64 -A) || return 1
    # --- 步骤 2: 带重试和断点续传的下载逻辑 ---
    # --- Step 2: Download logic with retries and resumable support ---
    local max_retries=3
    for (( i=1; i<=max_retries; i++ )); do
        # -L: 跟随重定向
        # -C -: 自动断点续传
        # -f: 遇到 HTTP 服务器错误时静默失败
        # --progress-bar: 显示一个简洁的进度条
        if curl --silent --show-error --fail -L -C - \
            --max-time 3600 \
            --cacert "$peer_cert_file" --pinnedpubkey "sha256//$peer_pin" --insecure \
            -o "$output_file" \
            --progress-bar \
            "https://$endpoint_host:$((node_port + P2P_FILE_PORT_OFFSET))/chunk/$chunk_hash"; then
            
            echo # 在进度条后换行以保持输出整洁
            
            # --- 步骤 3: 下载成功后进行最终的哈希校验 ---
            # --- Step 3: Final hash verification after successful download ---
            if ! _internal_verify_object_hash "$chunk_hash" "$output_file"; then
                warn "数据块哈希或签名无效。 / Invalid object hash or signature."
                return 1
            fi
            mv -f -- "$output_file" "$destination" || return 1
            return 0
        else
            local curl_exit_code=$?
            echo # 在进度条后换行
            warn "从 ${node_ip}:${node_port} 下载块失败 (尝试 ${i}/${max_retries})。将在5秒后重试..."
            warn "Download of chunk from ${node_ip}:${node_port} failed (attempt ${i}/${max_retries}). Retrying in 5 seconds..."
            
            # 如果是证书验证错误 (curl 退出码 60)，可能意味着对方证书已更新。
            # 保留固定证书，防止重试时绕过已确认的信任绑定。
            # If it's a certificate verification error (curl exit code 60), it might mean the peer's cert has been updated.
            # Retain the pin so retries cannot bypass the established trust binding.
            if [ "$curl_exit_code" -eq 60 ]; then
                 warn "检测到 TLS 证书问题。 / TLS certificate issue detected."
                 warn "已保留固定证书；需要明确重新验证。 / Pinned certificate retained; explicit revalidation required."
            fi
            sleep 5
        fi
    done
    
    # 如果所有重试都失败了
    # If all retries fail
    error "在 ${max_retries} 次尝试后，仍无法下载文件块 ${chunk_hash:0:16}... / Failed to download chunk ${chunk_hash:0:16}... after ${max_retries} attempts."
    return 1
)


# [新增] 辅助函数，用于从单个提供者下载数据块
p2p_download_chunk_from_provider() {
    local chunk_hash="$1"
    local output_file="$2"
    local provider_info="$3" # 格式: node_id 或 ip:port

    local node_ip node_port
    # provider_info 可能直接是 ip:port，也可能是 dht_find_chunk 返回的更复杂格式
    # 我们这里假设 dht_find_chunk 的远程结果格式就是 ip:port
    if [[ "$provider_info" == *":"* ]]; then
         node_ip="${provider_info%:*}"
         node_port="${provider_info##*:}"
         node_ip="${node_ip#[}"; node_ip="${node_ip%]}"
    else
        # 如果只给了node_id, 需要从DHT数据库查询IP
        local node_details
        node_details=$(db_query_safe "$DHT_DB" \
            "SELECT address, port FROM nodes WHERE id = %s;" \
            "$provider_info")
        [ -z "$node_details" ] && return 1
        IFS='|' read -r node_ip node_port <<< "$node_details"
    fi
    
    [ -n "$node_ip" ] || return 1

    p2p_request_chunk "$node_ip" "$node_port" "$chunk_hash" "$output_file"
}

# [修改] 旧的 p2p_download_chunk 不再需要，因为它只尝试从数据库记录的第一个节点下载

# 文件: corix.sh
# 函数: _p2p_download_object (新增的统一接口)

# Downloads a single object from the P2P network, trying all known providers.
# 从P2P网络下载单个对象，会尝试所有已知的提供者。
_p2p_download_object() (
    local object_hash="$1" output_file="$2" staged providers_data provider_info chunk_file offset size
    [[ "$object_hash" =~ ^[a-f0-9]{64}$ ]] || return 1
    staged=$(mktemp "${output_file}.object.XXXXXX") || return 1
    trap 'rm -f -- "$staged"' EXIT
    providers_data=$(dht_find_chunk "$object_hash") || return 1
    local -a providers=(); mapfile -t providers <<< "$providers_data"
    for provider_info in "${providers[@]}"; do
        [ -n "$provider_info" ] || continue
        : > "$staged" || return 1
        if [[ "$provider_info" == local:* ]]; then
            IFS='|' read -r chunk_file offset size <<< "${provider_info#local:}"
            [[ "$offset" =~ ^[0-9]{1,16}$ && "$size" =~ ^[0-9]{1,16}$ ]] || continue
            dd if="$chunk_file" of="$staged" iflag=skip_bytes,count_bytes skip="$offset" count="$size" status=none || continue
            [ "$(stat -c%s -- "$staged")" -eq "$size" ] || continue
        else
            p2p_download_chunk_from_provider "$object_hash" "$staged" "$provider_info" || continue
        fi
        if _internal_verify_object_hash "$object_hash" "$staged"; then
            mv -f -- "$staged" "$output_file" || return 1
            return 0
        fi
        warn "提供者对象已损坏。 / Provider object is corrupted: ${object_hash:0:12}"
    done
    warn "无法从任何提供者取得有效对象。 / No provider supplied a valid object: ${object_hash:0:12}"
    return 1
)

# --- NEW FUNCTION: Calculates the trust tier of a node ---
# --- 新增函数: 计算一个节点的信任等级 ---
_p2p_get_node_trust_tier() {
    local node_id="$1"

    local genesis_period_blocks
    genesis_period_blocks=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT param_value FROM system_params WHERE param_key = 'trust_genesis_period_blocks';")
    genesis_period_blocks=${genesis_period_blocks:-10000}

    local current_height
    current_height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT COALESCE(MAX(height), 0) FROM blocks;")

    if [ "$current_height" -lt "$genesis_period_blocks" ]; then
        echo "2" # 创世期内，所有节点都是成员级 / During genesis period, all nodes are Members.
        return
    fi

    local reputable_threshold
    reputable_threshold=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT param_value FROM system_params WHERE param_key = 'trust_reputable_tier_threshold';")
    reputable_threshold=${reputable_threshold:-1000}

    local points
    points=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT points FROM contribution_ledger WHERE node_id = %s;" "$node_id")
    points=${points:-0}

    if [ "$points" -ge "$reputable_threshold" ]; then
        echo "1" # 声誉级 / Reputable
    elif [ "$points" -gt 0 ]; then
        echo "2" # 成员级 / Member
    else
        echo "3" # 访客级 / Guest
    fi
}

# --- NEW FUNCTION: Updates a node's trust tier in the DHT database ---
# --- 新增函数: 在 DHT 数据库中更新一个节点的信任等级 ---
_p2p_update_node_trust_tier_in_db() {
    local node_id="$1"
    local new_tier
    new_tier=$(_p2p_get_node_trust_tier "$node_id")
    
    db_execute_safe "$DHT_DB" "UPDATE nodes SET trust_tier = %d WHERE id = %s;" "$new_tier" "$node_id"
}

# Check if a file is owned by any installed package
db_owns_file() {
    local file="$1"
    local manifest
    while IFS= read -r -d '' manifest; do
        grep -Fxq -- "$file" "$manifest" && return 0
    done < <(find "$INSTALLED_DB" -name files -type f -print0)
    return 1
}

# Update system caches (ldconfig, update-desktop-database, etc.)
update_system_caches() {
    # [修改] 这些命令操作的是系统级缓存，必须是 root
    # [MODIFICATION] These commands operate on system-wide caches and require root.
    if [ "${CORIUM_ROOT%/}" != "" ]; then
        info "隔离安装根目录：保留主机系统缓存。/ Isolated installation root: host caches preserved."
        return 0
    fi
    if [ "$(id -u)" -ne 0 ]; then
        warn "非 root 用户，跳过系统级缓存更新。 (Not root, skipping system-wide cache update.)"
        return 0
    fi
    # 这里没有用 _internal_check_root_privileges 然后 exit 1，而是采用了更温和的方式：如果不是 root，就打印警告并跳过。这是因为用户可能在自己的 home 目录里安装软件，这种情况下更新系统缓存既不可能也无必要。这种处理方式更灵活。
    
    info "Updating system caches..."
    
    # Update dynamic linker cache
    if command -v ldconfig >/dev/null 2>&1; then
        ldconfig 2>/dev/null || true
    fi
    
    # Update desktop database
    if command -v update-desktop-database >/dev/null 2>&1; then
        update-desktop-database /usr/share/applications 2>/dev/null || true
    fi
    
    # Update MIME database
    if command -v update-mime-database >/dev/null 2>&1; then
        update-mime-database /usr/share/mime 2>/dev/null || true
    fi
    
    # Update icon cache
    if command -v gtk-update-icon-cache >/dev/null 2>&1; then
        for icon_dir in /usr/share/icons/*/; do
            [ -d "$icon_dir" ] && gtk-update-icon-cache -q "$icon_dir" 2>/dev/null || true
        done
    fi
    
    # Update font cache
    if command -v fc-cache >/dev/null 2>&1; then
        fc-cache -f 2>/dev/null || true
    fi
}

# --- SECTION 17: PACKAGE REMOVAL ---

corix_remove() (
    local removal_committed=false
    trap 'status=$?; if ! $removal_committed; then _rollback_filesystem_transaction || status=1; db_rollback_transaction "$BLOCKCHAIN_DB" "$DHT_DB"; fi; release_lock "system"; exit "$status"' EXIT
    
    [ $# -eq 0 ] && error "No packages specified for removal."
    
    acquire_lock "system" || return 1
    _begin_transaction "$INSTALLED_DB" || return 1
    
    # Check for reverse dependencies
    local packages_to_remove=("$@")
    local deps_broken=()
    
    for pkg_id in "${packages_to_remove[@]}"; do
        get_pkg_id_parts "$pkg_id"
        local pkg_name="${PKG_CATEGORY}/${PKG_NAME}"
        
        ! db_is_installed "$pkg_id" && {
            warn "Package '$pkg_id' is not installed."
            continue
        }
        
        # Find packages that depend on this one
        local dependents
        dependents=$(find "$INSTALLED_DB" -name dependencies -exec grep -l "$pkg_name" {} \; | while read -r dep_file; do
            local dependent_pkg
            dependent_pkg=$(cat "$(dirname "$dep_file")/name")
            echo "$dependent_pkg"
        done)
        
        if [ -n "$dependents" ]; then
            warn "Package '$pkg_id' is required by:"
            while IFS= read -r dep_pkg; do
                echo "  - $dep_pkg"
                deps_broken+=("$dep_pkg")
            done <<< "$dependents"
        fi
    done
    

    if [ ${#deps_broken[@]} -gt 0 ]; then
        warn "警告: 移除这些包将会破坏以下已安装软件包的依赖："
        warn "WARNING: Removing these packages will break the dependencies of the following installed packages:"
        printf "  - %s\n" "${deps_broken[@]}"
        echo
    fi

    echo "以下软件包将被移除:"
    echo "The following packages will be REMOVED:"
    printf "  \033[1;31m- %s\n\033[0m" "${packages_to_remove[@]}"
    echo

    read -rp "您确定要继续吗？[y/N] / Are you sure you want to continue? [y/N] " choice || choice=""
    [[ ! "$choice" =~ ^[yY] ]] && {
        msg "移除操作已取消。 / Removal cancelled."
        _rollback_filesystem_transaction || return 1
        db_rollback_transaction "$BLOCKCHAIN_DB" "$DHT_DB"
        return 0
    }

    
    # Remove packages
    for pkg_id in "${packages_to_remove[@]}"; do
        get_pkg_id_parts "$pkg_id"
        local pkg_name="${PKG_CATEGORY}/${PKG_NAME}"
        
        ! db_is_installed "$pkg_id" && continue
        
        msg "Removing: $pkg_id"
        
        # Run pre-remove script if it exists
        local pkg_dir
        pkg_dir=$(db_get_pkg_dir "$pkg_name" "$PKG_SLOT")
        
        # [修正] 寻找并执行软件包自己的 pre-remove 脚本
        # [CORRECTION] Find and execute the package's OWN pre-remove script
        local pre_remove_script="${pkg_dir}/pre-remove.sh"
        
        if [ -f "$pre_remove_script" ] && [ -x "$pre_remove_script" ]; then
            info "Running package-specific pre-remove script..."
            # 在脚本执行时，注入标准的环境变量，让脚本知道自己是谁
            # Inject standard environment variables when executing, so the script knows who it is
            (
                export PKG_NAME="$pkg_name"
                export PKG_VERSION="$(cat "$pkg_dir/version")"
                export PKG_SLOT="$PKG_SLOT"
                bash "$pre_remove_script"
            ) || { warn "卸载前脚本失败，取消卸载。 / Pre-remove script failed; removal cancelled: $pkg_id"; return 1; }
        fi
        
        
        # Remove files
        info "Removing package files..."
        local files_to_remove
        files_to_remove=$(db_get_package_files "$pkg_name" "$PKG_SLOT")
        local dirs_to_remove=()
        
        # Remove files in reverse order to handle directories properly
        local removal_manifest
        removal_manifest=$(mktemp)
        CORIUM_TEMP_ITEMS+=("$removal_manifest")
        printf '%s\n' "$files_to_remove" > "$removal_manifest"
        _transaction_stage_files "$removal_manifest" || return 1
        while IFS= read -r file; do
            [ -n "$file" ] || continue
            local full_path="${CORIUM_ROOT%/}/$file"
            
            if [ -f "$full_path" ] || [ -L "$full_path" ]; then
                rm -f "$full_path"
                dirs_to_remove+=("$(dirname "$full_path")")
            elif [ -d "$full_path" ]; then
                # Only remove if empty
                rmdir "$full_path" 2>/dev/null || true
            fi
        done < <(tac "$removal_manifest")
        
        # Remove empty directories
        printf '%s\n' "${dirs_to_remove[@]}" | sort -u -r | while IFS= read -r dir; do
            [ -d "$dir" ] && [ -z "$(ls -A "$dir" 2>/dev/null)" ] && rmdir "$dir" 2>/dev/null || true
        done
        
        # Unregister from database
        db_unregister_package "$pkg_name" "$PKG_SLOT" || return 1
        
        # Remove from world file
        local world_tmp
        world_tmp=$(mktemp "${WORLD_FILE}.XXXXXX")
        awk -v package="$pkg_id" '$0 != package' "$WORLD_FILE" > "$world_tmp"
        mv -- "$world_tmp" "$WORLD_FILE"
        
        info "Successfully removed: $pkg_id"
    done
    
    # Update system caches
    update_system_caches
    
    _commit_transaction || return 1
    removal_committed=true
    msg "Removal complete. / 移除完成。"
)

# --- SECTION 18: SYSTEM UPGRADE ---

corix_upgrade() {
    check_permissions "upgrade" # Changed from generic to specific
    acquire_lock "system"
    _begin_transaction "$INSTALLED_DB"
    trap 'release_lock "system"' RETURN
    
    # Package metadata is independent of peer availability and chain mining.
    corix_sync --repositories-only || return 1
    
    msg "Checking for upgradeable packages..."
    local world_pkgs
    mapfile -t world_pkgs < "$WORLD_FILE"
    
    if [ ${#world_pkgs[@]} -eq 0 ]; then
        _commit_transaction || return 1
        msg "World file is empty. Nothing to upgrade."
        release_lock
        return 0
    fi
    
    local to_upgrade=()
    local upgrade_info=()
    
    for pkg_id in "${world_pkgs[@]}"; do
        [ -n "$pkg_id" ] || continue
        
        get_pkg_id_parts "$pkg_id"
        local pkg_name="${PKG_CATEGORY}/${PKG_NAME}"
        local pkg_slot="$PKG_SLOT"
        
        local pkg_dir
        pkg_dir=$(db_get_pkg_dir "$pkg_name" "$pkg_slot")
        
        if [ ! -d "$pkg_dir" ]; then
            # Package in world file but not installed - reinstall
            to_upgrade+=("$pkg_id")
            upgrade_info+=("$pkg_id: missing -> reinstall")
            continue
        fi
        
        local installed_ver
        installed_ver=$(cat "$pkg_dir/version" 2>/dev/null || echo "unknown")
        
        local build_file
        build_file=$(find_package_build_file "$pkg_id")
        if [ -z "$build_file" ]; then
            warn "No .build file found for $pkg_id"
            continue
        fi
        
        local meta
        meta=$(_parse_build_file "$build_file")
        local repo_ver
        repo_ver=$(echo "$meta" | grep "^pkgver=" | cut -d= -f2)
        
        if [ "$repo_ver" != "$installed_ver" ]; then
            to_upgrade+=("$pkg_id")
            upgrade_info+=("$pkg_id: $installed_ver -> $repo_ver")
        fi
    done
    
    if [ ${#to_upgrade[@]} -eq 0 ]; then
        _commit_transaction || return 1
        msg "System is up-to-date."
        release_lock
        return 0
    fi
    
    msg "The following packages will be upgraded:"
    printf '  %s\n' "${upgrade_info[@]}"
    echo
    
    if [ "$DEP_MODE" = "suggest" ]; then
        read -rp "Continue with upgrade? [Y/n] " choice
        [[ "$choice" =~ ^[nN] ]] && {
            _commit_transaction || return 1
            msg "Upgrade cancelled."
            release_lock
            return 0
        }
    fi
    
    # Perform upgrades
    # 释放锁，因为 corix_install 会自己加锁
    # Release the lock, as corix_install will add its own lock
    corix_install "${to_upgrade[@]}" || return 1
    
    msg "系统升级完成。 / System upgrade complete."
    _commit_transaction
}

# --- SECTION 21: ADVANCED PACKAGE OPERATIONS ---

corix_owns() {
    [ $# -ne 1 ] && error "Usage: corix owns <file_path>"
    local file_path="$1"
    
    # The path in the manifest is relative to root, so we need to strip any leading '/'
    local search_path="${file_path#/}"
    
    info "Searching for owner of: $file_path"
    
    local found=0
    # Use find and grep for efficiency. -l prints the filename of the manifest that matches.
    while IFS= read -r -d '' manifest_file; do
        local pkg_dir owner_info
        pkg_dir=$(dirname "$manifest_file")
        
        # We can construct the package ID from the directory name
        local pkg_id_from_dir
        pkg_id_from_dir="$(cat "$pkg_dir/name"):$(cat "$pkg_dir/slot")"

        local pkg_name pkg_ver
        pkg_name=$(cat "$pkg_dir/name" 2>/dev/null)
        pkg_ver=$(cat "$pkg_dir/version" 2>/dev/null)
        
        echo -e "File is owned by: \033[1;32m${pkg_name}:${pkg_ver}\033[0m (ID: $pkg_id_from_dir)"
        found=1
    done < <(find "$INSTALLED_DB" -name files -type f -exec grep -Fxq -- "$search_path" {} \; -print0)
    
    if [ "$found" -eq 0 ]; then
        warn "No corix-managed package owns this file."
    fi
}

# REVISED to use metadata cache for faster information retrieval.
# 已修订，使用元数据缓存以更快地检索信息。
corix_info() {
    [ $# -ne 1 ] && error "Usage: corix info <package_name> / 用法: corix info <软件包名称>"
    local pkg_name_full="$1"
    
    msg "Gathering information for: \033[1;32m$pkg_name_full\033[0m"
    
    # --- 1. Basic Info from metadata cache ---
    # --- 1. 从元数据缓存获取基本信息 ---
    local meta_from_cache
    meta_from_cache=$(_get_pkg_meta_from_cache "$pkg_name_full")
    
    if [ -z "$meta_from_cache" ]; then
        # Fallback to parsing the file directly if not in cache (e.g., a local, un-synced .build file)
        # 如果缓存中没有，则回退到直接解析文件（例如一个本地的、未同步的 .build 文件）
        local build_file
        build_file=$(find_package_build_file "$pkg_name_full")
        [ -n "$build_file" ] || error "Could not find .build file or cached metadata for '$pkg_name_full' / 未能为 '$pkg_name_full' 找到 .build 文件或缓存的元数据"
        
        local meta
        meta=$(_parse_build_file "$build_file")
        local pkgver=$(echo "$meta" | grep "^pkgver=" | cut -d= -f2)
        local depends=$(echo "$meta" | grep "^depends=" | cut -d= -f2- | tr '\n' ' ')
        local makedepends=$(echo "$meta" | grep "^makedepends=" | cut -d= -f2- | tr '\n' ' ')
        # Additional details that are not in the fast cache
        # 快速缓存中没有的额外细节
        local pkgdesc=$(echo "$meta" | grep "^pkgdesc=" | cut -d= -f2)
        local url=$(echo "$meta" | grep "^url=" | cut -d= -f2)
        local slot=$(echo "$meta" | grep "^slot=" | cut -d= -f2)
    else
        # Parse from the cached string: id|version|depends|makedepends
        # 从缓存的字符串中解析: id|版本|依赖|构建依赖
        IFS='|' read -r _ pkgver depends makedepends <<< "$meta_from_cache"
        # For description, URL etc., we still need to parse the file, but the critical path (deps) was fast.
        # 对于描述、URL等，我们仍需解析文件，但关键路径（依赖）已经很快了。
        local build_file
        build_file=$(find_package_build_file "$pkg_name_full")
        local meta
        meta=$(_parse_build_file "$build_file")
        local pkgdesc=$(echo "$meta" | grep "^pkgdesc=" | cut -d= -f2)
        local url=$(echo "$meta" | grep "^url=" | cut -d= -f2)
        local slot=$(echo "$meta" | grep "^slot=" | cut -d= -f2)
    fi

    echo -e "\n\033[1mPackage Details / 软件包详情\033[0m"
    echo -e "  Description / 描述: $pkgdesc"
    echo -e "  Latest Version / 最新版本: \033[1;33m$pkgver\033[0m"
    echo -e "  Slot / 槽: $slot"
    echo -e "  Homepage / 主页: $url"
    
    # --- 2. Dependency Info ---
    echo -e "\n\033[1mDependencies / 依赖关系\033[0m"
    echo -e "  Runtime Deps / 运行时依赖: ${depends:-<none>}"
    echo -e "  Build Deps / 构建时依赖:   ${makedepends:-<none>}"

    # --- 3. Installation Status & Trust (unchanged) ---
    # --- 3. 安装状态与信任 (无变动) ---
    # ... (The rest of the corix_info function remains the same) ...
    echo -e "\n\033[1mSystem Status / 系统状态\033[0m"
    if db_is_installed "$pkg_name_full"; then
        get_pkg_id_parts "$pkg_name_full"
        local pkg_dir installed_ver install_date
        pkg_dir=$(db_get_pkg_dir "${PKG_CATEGORY}/${PKG_NAME}" "$PKG_SLOT")
        installed_ver=$(cat "$pkg_dir/version" 2>/dev/null)
        install_date=$(cat "$pkg_dir/install_date" 2>/dev/null)
        echo -e "  Status / 状态: \033[1;32mInstalled / 已安装\033[0m"
        echo -e "  Installed Version / 已安装版本: \033[1;33m$installed_ver\033[0m"
        echo -e "  Installation Date / 安装日期: $install_date"
        
    else
        echo -e "  Status / 状态: \033[0;33mNot Installed / 未安装\033[0m"
    fi
}

corix_adopt() {
    check_permissions "adopt"
    [ $# -lt 2 ] && error "Usage: adopt <pkg_name> <version> [--slot=SLOT]"
    
    local pkg_name="$1"
    local pkg_ver="$2"
    shift 2
    
    local pkg_slot="0"
    while [ $# -gt 0 ]; do
        case "$1" in
            --slot=*) pkg_slot="${1#--slot=}"; shift ;;
            --slot) [ $# -ge 2 ] || return 1; pkg_slot="$2"; shift 2 ;;
            *) error "Unknown option: $1" ;;
        esac
    done
    
    get_pkg_id_parts "${pkg_name}:${pkg_slot}"
    [ -n "$pkg_ver" ] && [[ "$pkg_ver" != *$'\n'* && "$pkg_ver" != */* ]] || return 1

    msg "Adopting '$pkg_name' version '$pkg_ver' (slot: $pkg_slot)"
    
    # Check if package is already installed
    if db_is_installed "${pkg_name}:${pkg_slot}"; then
        warn "Package '$pkg_name:$pkg_slot' is already installed."
        read -rp "Continue anyway? [y/N] " choice || return 1
        [[ ! "$choice" =~ ^[yY] ]] && return 0
    fi
    
    # Get file manifest from user
    local manifest_file
    while true; do
        read -rp "Path to file manifest (one file per line): " manifest_file || return 1
        if [ -f "$manifest_file" ]; then
            break
        else
            error "File not found: $manifest_file"
        fi
    done
    
    info "正在校验文件清单... / Validating manifest..."
    "${PYTHON_CMD}" - "$CORIUM_ROOT" "$manifest_file" "$INSTALLED_DB" "$(db_get_pkg_dir "$pkg_name" "$pkg_slot")" <<'PY_ADOPT'
import sys, pathlib, os
root=pathlib.Path(sys.argv[1]).resolve(); manifest=pathlib.Path(sys.argv[2])
items=manifest.read_text().splitlines()
if not items or len(set(items)) != len(items): raise ValueError('Empty or duplicate manifest')
other=set()
for file in pathlib.Path(sys.argv[3]).glob('*/files'):
    if file.parent != pathlib.Path(sys.argv[4]): other.update(file.read_text().splitlines())
for name in items:
    path=pathlib.PurePosixPath(name)
    if not name or path.is_absolute() or '..' in path.parts or str(path) != name or '\x00' in name:
        raise ValueError('Invalid adopted path')
    if name in other: raise ValueError('File is already owned by another package')
    target=root/path
    for parent in target.parents:
        if parent==root: break
        if parent.is_symlink(): raise ValueError('Symlink parent in adopted path')
    if not os.path.lexists(target): raise ValueError('Missing adopted file')
PY_ADOPT
    [ $? -eq 0 ] || return 1

    # Try to find corresponding .build file
    local build_file
    if ! build_file=$(find_package_build_file "$pkg_name"); then
        warn "No .build file found for $pkg_name"
        build_file="/dev/null"
    fi
    
    # Register package
    acquire_lock "system"
    _begin_transaction "$INSTALLED_DB"
    trap 'release_lock "system"' RETURN
    db_register_package "$pkg_name" "$pkg_ver" "$pkg_slot" "$manifest_file" "" "$build_file" || return 1
    
    # Add to world file
    if ! grep -Fxq "${pkg_name}:${pkg_slot}" "$WORLD_FILE"; then
        echo "${pkg_name}:${pkg_slot}" >> "$WORLD_FILE"
        sort -u -o "$WORLD_FILE" "$WORLD_FILE"
    fi
    
    _commit_transaction
    msg "Successfully adopted '$pkg_name:$pkg_slot'"
}

corix_rollback() (
    set -e
    check_permissions "rollback"
    [ $# -eq 2 ] || { error "用法 / Usage: rollback <package_name> <version>"; return 1; }
    local pkg_id="$1" target_version="$2"
    get_pkg_id_parts "$pkg_id" || return 1
    local package_name="${PKG_CATEGORY}/${PKG_NAME}" package_slot="$PKG_SLOT" build_file metadata historical_file="" repo_root commit relative temporary original="" completed=false
    [ -n "$target_version" ] && [[ "$target_version" != */* && "$target_version" != *$'\n'* ]] || return 1
    acquire_lock "system" || return 1
    acquire_lock "network" || return 1
    db_is_installed "$pkg_id" || { warn "软件包未安装。 / Package is not installed."; return 1; }
    build_file=$(find_package_build_file "$pkg_id") || return 1
    [ -f "$build_file" ] && [ ! -L "$build_file" ] || return 1
    temporary=$(mktemp -d -p "$BUILD_TMP_DIR_BASE" rollback-work.XXXXXX) || return 1
    trap 'status=$?; if [ -n "$original" ]; then cp -- "$original" "$temporary/restore.build" && mv -f -- "$temporary/restore.build" "$build_file" || status=1; fi; if ! $completed; then _rollback_filesystem_transaction || status=1; fi; _internal_db_rollback_all_active; release_lock "network"; release_lock "system"; rm -rf -- "$temporary"; exit "$status"' EXIT
    metadata=$(_parse_build_file "$build_file") || return 1
    if [ "$(sed -n 's/^pkgver=//p' <<< "$metadata")" = "$target_version" ]; then
        historical_file="$build_file"
    elif repo_root=$(git -C "$(dirname "$build_file")" rev-parse --show-toplevel 2>/dev/null); then
        relative="${build_file#"$repo_root"/}"
        while IFS= read -r commit; do
            git -C "$repo_root" show "$commit:$relative" > "$temporary/historical.build" || return 1
            metadata=$(_parse_build_file "$temporary/historical.build") || return 1
            if [ "$(sed -n 's/^pkgver=//p' <<< "$metadata")" = "$target_version" ]; then
                historical_file="$temporary/historical.build"; break
            fi
        done < <(git -C "$repo_root" log --format=%H -- "$relative")
    fi
    [ -n "$historical_file" ] || { warn "未找到目标版本的真实构建元数据。 / Historical build metadata for target version was not found."; return 1; }
    local choice
    read -rp "回滚到目标版本？[y/N] / Roll back to version $target_version? [y/N] " choice || return 1
    [[ "$choice" =~ ^[yY] ]] || return 0
    _begin_transaction "$INSTALLED_DB" || return 1
    # Keep the repository and its cache current after the historical install finishes.
    original="$temporary/original.build"; cp -p -- "$build_file" "$original" || return 1
    cp -p -- "$historical_file" "$temporary/selected.build" || return 1
    mv -f -- "$temporary/selected.build" "$build_file" || return 1
    [ -f "$METADATA_CACHE_DB" ] || _update_metadata_cache || return 1
    db_begin_transaction "$METADATA_CACHE_DB" || return 1
    _update_metadata_cache || return 1
    # The native installer performs signature/hash/archive verification, dependency
    # resolution, ownership checks, file journaling and post-install failure rollback.
    # 原生安装器执行签名、哈希、归档、依赖、所有权及安装事务的完整校验。
    corix_install "${package_name}:${package_slot}" || return 1
    local installed_version
    installed_version=$(cat "$(db_get_pkg_dir "$package_name" "$package_slot")/version") || return 1
    [ "$installed_version" = "$target_version" ] || return 1
    db_rollback_transaction "$METADATA_CACHE_DB" || return 1
    cp -p -- "$original" "$temporary/restore.build" || return 1
    mv -f -- "$temporary/restore.build" "$build_file" || return 1
    original=""
    _commit_transaction || return 1
    completed=true
    msg "回滚成功。 / Rollback completed: ${package_name}:${package_slot} $target_version"
)


# Creates a delta (differential) patch between two binary packages.
# This is typically used by repository maintainers.
#
# 用法: corix create-delta <包名> <旧版本> <新版本>
# 示例: corix create-delta app-misc/hello-world 1.0 2.0
corix_create_delta() {
    check_permissions
    [ $# -ne 3 ] && error "用法: corix create-delta <包名> <旧版本> <新版本> (Usage: corix create-delta <pkg_name> <old_version> <new_version>)"

    local pkg_name="$1"
    local old_ver="$2"
    local new_ver="$3"
    
    msg "正在为软件包 '$pkg_name' 从版本 '$old_ver' 到 '$new_ver' 创建增量更新... (Creating delta update for package '$pkg_name' from version '$old_ver' to '$new_ver'...)"

    # 1. 获取包的元信息，主要是为了拿到 slot
    # 1. Obtaining the metadata of the package is mainly to obtain the slot
    local build_file meta pkg_slot
    build_file=$(find_package_build_file "$pkg_name")
    [ -z "$build_file" ] && error "找不到 '$pkg_name' 的 .build 文件。 (Could not find .build file for '$pkg_name'.)"
    meta=$(_parse_build_file "$build_file")
    pkg_slot=$(echo "$meta" | grep "^slot=" | cut -d= -f2)

    # 2. 定位旧版本和新版本的二进制包路径
    # 2. Locate binary package paths for old and new versions
    local old_pkg_base="${BINARY_CACHE}/${pkg_name//\//_}-${old_ver}-${pkg_slot}-$(uname -m).corix"
    local new_pkg_base="${BINARY_CACHE}/${pkg_name//\//_}-${new_ver}-${pkg_slot}-$(uname -m).corix"
    
    local old_pkg_path=""
    local new_pkg_path=""

    # 优先使用 .zst 压缩格式
    # Prioritize using .zst compression format
    [ -f "${old_pkg_base}.tar.zst" ] && old_pkg_path="${old_pkg_base}.tar.zst"
    [ -f "${new_pkg_base}.tar.zst" ] && new_pkg_path="${new_pkg_base}.tar.zst"

    # 如果 .zst 不存在，则回退到 .gz
    # If .zst does not exist, go back to .gz
    if [ -z "$old_pkg_path" ] && [ -f "${old_pkg_base}.tar.gz" ]; then
        old_pkg_path="${old_pkg_base}.tar.gz"
    fi
    if [ -z "$new_pkg_path" ] && [ -f "${new_pkg_base}.tar.gz" ]; then
        new_pkg_path="${new_pkg_base}.tar.gz"
    fi

    [ -f "$old_pkg_path" ] || error "找不到旧版本的二进制包: ${old_pkg_path} (或其 .gz 版本)。 (Could not find old binary package: ${old_pkg_path} (or its .gz version).)"
    [ -f "$new_pkg_path" ] || error "找不到新版本的二进制包: ${new_pkg_path} (或其 .gz 版本)。 (Could not find new binary package: ${new_pkg_path} (or its .gz version).)"

    info "找到旧版包 (Found old package): $old_pkg_path"
    info "找到新版包 (Found new package): $new_pkg_path"

    # 3. 定义增量包的输出路径
    # 3. Define the output path of incremental packages
    local delta_file="${BINARY_CACHE}/${pkg_name//\//_}-${old_ver}-to-${new_ver}.delta"
    
    # 4. 选择合适的工具创建增量包 (优先使用 xdelta3)
    # 4. Choose the appropriate tool to create incremental packages (prioritizing xdelta3)
    if command -v xdelta3 >/dev/null 2>&1; then
        info "使用 xdelta3 创建增量文件... (Creating delta file using xdelta3...)"
        xdelta3 -e -s "$old_pkg_path" "$new_pkg_path" "$delta_file"
    elif command -v bsdiff >/dev/null 2>&1; then
        info "警告: xdelta3 未找到，回退到 bsdiff... (Warning: xdelta3 not found, falling back to bsdiff...)"
        bsdiff "$old_pkg_path" "$new_pkg_path" "$delta_file"
    else
        error "无法创建增量包，需要安装 'xdelta3' 或 'bsdiff'。 (Cannot create delta package, 'xdelta3' or 'bsdiff' must be installed.)"
    fi

    if [ -f "$delta_file" ]; then
        msg "增量文件创建成功 (Delta file created successfully): $delta_file"
        info "文件大小 (File size): $(du -h "$delta_file" | awk '{print $1}')"
    else
        error "创建增量文件失败。 (Failed to create delta file.)"
    fi
}

corix_gateway() {
    local sub_cmd="${1:-status}"
    [ $# -gt 0 ] && shift
    case "$sub_cmd" in
        start|daemon)
            msg "启动 Corium 原生 HTTP/P2P 网关服务... / Starting Corium Native HTTP/P2P Gateway..."
            export CORIUM_PUBLIC_GATEWAY="${CORIUM_PUBLIC_GATEWAY:-true}"
            export CORIUM_HTTP_PORT="${CORIUM_GATEWAY_PORT:-7235}"
            info "网关端口设置为 / Gateway port set to: $CORIUM_HTTP_PORT (与 Ziokt 网关 8080/8081 隔离互不冲突)"
            dht_server_daemon "$@"
            ;;
        stop)
            msg "停止 Corium 原生网关服务... / Stopping Corium Native Gateway..."
            if [ -f "$DAEMON_PID_FILE" ]; then
                local pid
                pid=$(cat "$DAEMON_PID_FILE" 2>/dev/null)
                if [ -n "$pid" ] && kill -0 "$pid" 2>/dev/null; then
                    kill -TERM "$pid" && rm -f "$DAEMON_PID_FILE"
                    msg "原生网关 (PID: $pid) 已停止。 / Native Gateway stopped."
                fi
            else
                info "原生网关未在运行。 / Native Gateway is not running."
            fi
            ;;
        status)
            if [ -f "$DAEMON_PID_FILE" ] && kill -0 "$(cat "$DAEMON_PID_FILE" 2>/dev/null)" 2>/dev/null; then
                msg "Corium 原生网关正在运行 (PID: $(cat "$DAEMON_PID_FILE"), 端口: ${CORIUM_GATEWAY_PORT:-7235})"
            else
                info "Corium 原生网关当前未运行。使用 'corix gateway start' 启动原生网关。"
            fi
            ;;
        tutorial|guide)
            usage gateway
            ;;
        *)
            usage gateway
            ;;
    esac
}

# --- SECTION 22: STRATA SYSTEM (META-PM) ---

corix_strata() {
    local sub_cmd="$1"
    shift
    
    case "$sub_cmd" in
        --create)
            [ $# -lt 2 ] && error "Usage: strata --create <name> <pm_name>"
            corix_strata_create "$1" "$2"
            ;;
        --list)
            corix_strata_list
            ;;
        -e|--execute)
            [ $# -lt 2 ] && error "Usage: strata -e <name> <command...>"
            local strata_name="$1"
            shift
            corix_strata_execute "$strata_name" "$@"
            ;;
        --destroy)
            [ $# -lt 1 ] && error "Usage: strata --destroy <name>"
            corix_strata_destroy "$1"
            ;;
        # --- [NEW] Add the promote command ---
        # --- [新增] 添加提升命令 ---
        --promote)
            [ $# -lt 1 ] && error "Usage: strata --promote <name>"
            corix_strata_promote "$1"
            ;;
        *)
            error "Unknown strata command: '$sub_cmd'. Use --create, --list, -e, or --destroy."
            ;;
    esac
}

corix_strata_create() {
    # [修改] debootstrap, pacstrap 等命令必须以 root 身份运行
    # [MODIFICATION] Commands like debootstrap, pacstrap must be run as root.
    _internal_check_root_privileges
    
    local name="$1"
    # 验证名称以防止路径遍历
    # Validate name to prevent path traversal
    case "$name" in
      */* | .. | .)
        error "无效的名称。它不能包含 '/' 或 '.' 字符。/ Invalid name. It cannot contain '/' or '.' characters."
        return 1
        ;;
    esac
    local pm="$2"
    local strata_path="${STRATA_DIR}/${name}"
    
    [ -d "$strata_path" ] && error "Strata '$name' already exists at $strata_path"
    
    acquire_lock "system"
    trap 'release_lock "system"' RETURN
    
    msg "Creating strata '$name' with package manager '$pm'..."
    
    mkdir -p "$STRATA_DIR"
    _check_disk_space "$STRATA_DIR" 2048
    
    case "$pm" in
        apt|debian)
            check_dep debootstrap
            info "Creating Debian-based strata with apt..."
            local debian_mirror="${3:-http://deb.debian.org/debian/}"
            local debian_release="${4:-stable}"
            
            debootstrap "$debian_release" "$strata_path" "$debian_mirror" || return 1
            
            # Configure apt sources
            cat > "${strata_path}/etc/apt/sources.list" <<EOF
deb $debian_mirror $debian_release main
deb-src $debian_mirror $debian_release main
deb https://security.debian.org/debian-security ${debian_release}-security main
deb-src https://security.debian.org/debian-security ${debian_release}-security main
EOF
            
            # Update package database
            corix_strata_execute "$name" apt update
            ;;
            
        pacman|arch)
            check_dep pacstrap
            info "Creating Arch-based strata with pacman..."
            
            mkdir -p "$strata_path"
            pacstrap -c -K "$strata_path" base
            
            # Configure pacman
            if [ -f /etc/pacman.conf ]; then
                cp /etc/pacman.conf "${strata_path}/etc/pacman.conf"
            fi
            ;;
            
        dnf|fedora)
            check_dep dnf
            info "Creating Fedora-based strata with dnf..."
            
            local fedora_release="${3:-latest}"
            mkdir -p "$strata_path"
            
            # Create minimal filesystem
            mkdir -p "$strata_path"/{etc,var/lib/rpm,var/cache/dnf}
            
            # Initialize RPM database
            rpm --root "$strata_path" --initdb
            
            # Install base system
            local fedora_repo="$strata_path/etc/yum.repos.d"
            mkdir -p "$fedora_repo"
            cat > "$fedora_repo/fedora.repo" <<EOF_FEDORA
[fedora]
name=Fedora $fedora_release
metalink=https://mirrors.fedoraproject.org/metalink?repo=fedora-$fedora_release&arch=\$basearch
enabled=1
gpgcheck=1
gpgkey=https://src.fedoraproject.org/rpms/fedora-repos/raw/rawhide/f/RPM-GPG-KEY-fedora-$fedora_release-primary
EOF_FEDORA
            dnf --installroot="$strata_path" --releasever="$fedora_release" \
                --setopt=reposdir="$fedora_repo" install -y filesystem setup basesystem bash fedora-release || return 1
            ;;
            
        portage|gentoo)
            info "Creating Gentoo-based strata with Portage..."
            
            # Download stage3 tarball
            local stage3_url="https://distfiles.gentoo.org/releases/amd64/autobuilds/latest-stage3-amd64-openrc.txt"
            local stage3_path
            stage3_path=$(curl --fail --location --silent --show-error "$stage3_url" | awk '!/^#/ && $1 ~ /^[0-9].*stage3.*\.tar\.xz$/ {print $1; exit}') || return 1
            [[ "$stage3_path" =~ ^[0-9A-Za-z._/-]+\.tar\.xz$ ]] && [[ "$stage3_path" != *..* ]] || return 1
            local stage3_file="${stage3_path##*/}"
            local stage3_full_url="https://distfiles.gentoo.org/releases/amd64/autobuilds/$stage3_path"
            
            info "Downloading stage3: $stage3_file"
            curl --fail --location --retry 3 -o "${SOURCE_CACHE}/$stage3_file" "$stage3_full_url" || return 1
            
            # Extract stage3
            mkdir -p "$strata_path"
            tar -xpf "${SOURCE_CACHE}/$stage3_file" -C "$strata_path" || return 1
            ;;
            
        dcpm|decentralized)
            info "Creating dCPM decentralized strata with slot isolation..."
            mkdir -p "$strata_path"
            if command -v dcpm >/dev/null 2>&1; then
                dcpm init "$strata_path" || true
            else
                mkdir -p "$strata_path"/{etc,bin,lib,usr,var,slots,.dcpm}
            fi
            ;;

        *)
            error "Unsupported package manager: $pm. Supported: apt, pacman, dnf, portage, dcpm"
            ;;
    esac
    
    # Create strata metadata
    local strata_conf="${strata_path}/.corix_strata"
    cat > "$strata_conf" <<EOF
name=$name
pm=$pm
created=$(date -u --rfc-3339=seconds)
corix_version=$CORIUM_VERSION
EOF
    
    # Set up essential bind mounts for the strata
    mkdir -p "${strata_path}"/{proc,sys,dev}
    
    msg "Strata '$name' created successfully."
    info "Execute commands with: corix strata -e $name <command>"
}

corix_strata_list() {
    echo "Available strata:"
    for strata_dir in "${STRATA_DIR}"/*; do
        [ -d "$strata_dir" ] || continue
        local strata_name
        strata_name=$(basename "$strata_dir")
        local strata_conf="${strata_dir}/.corix_strata"
        
        if [ -f "$strata_conf" ]; then
            local pm created
            pm=$(grep '^pm=' "$strata_conf" | cut -d= -f2)
            created=$(grep '^created=' "$strata_conf" | cut -d= -f2)
            echo "  $strata_name ($pm) - created $created"
        else
            echo "  $strata_name (unknown type)"
        fi
    done
}

# --- SECTION 23: EXTERNAL PACKAGE MANAGER INTEGRATION ---

corix_manage() {
    check_permissions
    [ $# -lt 1 ] && error "Usage: manage <subcommand> [args...]"
    
    local sub_cmd="$1"
    shift
    
    case "$sub_cmd" in
        --sync-from)
            [ $# -lt 1 ] && error "Usage: manage --sync-from <pm_name>"
            corix_manage_sync "$1"
            ;;
        --list-external)
            corix_manage_list
            ;;
        --adopt-from)
            [ $# -lt 2 ] && error "Usage: manage --adopt-from <pm_name> <package_pattern>"
            corix_manage_adopt "$1" "$2"
            ;;
        *)
            error "Unknown manage command: $sub_cmd"
            ;;
    esac
}

# REVISED: The extended corix_manage_sync function.
# The Portage implementation now strictly requires 'equery' for accuracy
# and provides a clear message if it's not found, avoiding the unreliable
# fallback logic.
#
# 已修订: 扩展后的 corix_manage_sync 函数。
# Portage 的实现现在为保证准确性而严格要求 'equery' 命令，如果命令未找到，
# 会提供清晰的提示，避免了不可靠的后备逻辑。
corix_manage_sync() {
    local pm="$1"
    msg "正在从外部包管理器同步软件包数据库: $pm (Syncing package database from external package manager: $pm)"
    
    acquire_lock "system"
    trap 'release_lock "system"' RETURN
    
    local db_file="${EXTERNAL_PM_DB}/${pm}.db"
    mkdir -p "$(dirname "$db_file")"
    
    case "$pm" in
        apt)
            check_dep dpkg-query
            info "正在查询 dpkg 数据库... (Querying dpkg database...)"
            dpkg-query -W -f='${Package}\t${Version}\t${Status}\t${Architecture}\n' > "$db_file"
            ;;
            
        pacman)
            check_dep pacman
            info "正在查询 pacman 数据库... (Querying pacman database...)"
            pacman -Q | awk '{printf "%s\t%s\tinstalled\t%s\n", $1, $2, "any"}' > "$db_file"
            ;;
            
        dnf)
            check_dep rpm
            info "正在查询 RPM 数据库... (Querying RPM database...)"
            rpm -qa --queryformat '%{NAME}\t%{VERSION}-%{RELEASE}\tinstalled\t%{ARCH}\n' > "$db_file"
            ;;
            
        portage)
            # [已修改] 只使用 equery，不再提供脆弱的后备方案
            # [MODIFIED] Only use equery, no longer provide a fragile fallback
            if command -v equery >/dev/null 2>&1; then
                info "正在通过 equery 查询 Portage 数据库 (精确)... (Querying Portage database via equery (accurate)...)"
                # equery list '*' 的输出格式是 category/name-version
                # 我们用 sed 来将其转换为我们需要的 tab 分隔格式
                equery -q list '*' | sed -E 's|^(.*)/([^-]+)-(.+)$|\1/\2\t\3\tinstalled\tgentoo|' > "$db_file"
            else
                # 如果 equery 不存在，则给出明确错误信息并失败
                # If equery does not exist, give a clear error message and fail
                error "无法同步 Portage 数据库：需要 'equery' 命令 (由 app-portage/gentoolkit 提供)。"
                error "Cannot sync Portage database: 'equery' command (from app-portage/gentoolkit) is required."
                return 1
            fi
            ;;
            
        pip)
            if command -v pip >/dev/null 2>&1; then
                info "正在查询 pip 软件包... (Querying pip packages...)"
                pip list --format=freeze | sed 's/==/\t/g' | awk '{printf "%s\t%s\tinstalled\tpython\n", $1, $2}' > "$db_file"
            else
                warn "未找到 pip 命令。 (pip command not found)"
            fi
            ;;
            
        npm)
            if command -v npm >/dev/null 2>&1; then
                info "正在查询 npm 软件包... (Querying npm packages...)"
                : > "$db_file"
                npm list -g --depth=0 --parseable --silent | while read -r pkg_path; do
                    [ -n "$pkg_path" ] || continue
                    local pkg_json="${pkg_path}/package.json"
                    if [ -f "$pkg_json" ]; then
                        local name version
                        name=$(grep -m 1 '"name"' "$pkg_json" | cut -d'"' -f4)
                        version=$(grep -m 1 '"version"' "$pkg_json" | cut -d'"' -f4)
                        [ -n "$name" ] && [ -n "$version" ] && echo -e "${name}\t${version}\tinstalled\tnodejs" >> "$db_file"
                    fi
                done
            else
                warn "未找到 npm 命令。 (npm command not found)"
            fi
            ;;
        
        xbps)
            check_dep xbps-query
            info "正在查询 xbps 数据库... (Querying xbps database...)"
            xbps-query -l | while read -r line; do
                local status pkgver_str remainder
                read -r status pkgver_str remainder <<< "$line"
                [ "$status" = ii ] || continue
                local pkgname="${pkgver_str%-*}"
                local version="${pkgver_str##*-}"
                echo -e "${pkgname}\t${version}\tinstalled\txbps"
            done > "$db_file"
            ;;

        zypper)
            check_dep zypper
            info "正在查询 zypper 数据库... (Querying zypper database...)"
            zypper se --installed-only -s | awk '
                BEGIN { FS = " \\| " }
                /^S/ || /^-/ { next }
                {
                    gsub(/^[ \t]+|[ \t]+$/, "", $2);
                    gsub(/^[ \t]+|[ \t]+$/, "", $4);
                    gsub(/^[ \t]+|[ \t]+$/, "", $5);
                    printf "%s\t%s\tinstalled\t%s\n", $2, $4, $5
                }
            ' > "$db_file"
            ;;
            
        pkgsrc)
            check_dep pkg_info
            info "正在查询 pkgsrc 数据库... (Querying pkgsrc database...)"
            pkg_info -e '*' | while read -r line; do
                local pkgname="${line%-*}"
                local version="${line##*-}"
                echo -e "${pkgname}\t${version}\tinstalled\tpkgsrc"
            done > "$db_file"
            ;;

        dcpm|decentralized)
            if command -v dcpm >/dev/null 2>&1; then
                info "正在查询 dCPM 数据库... (Querying dCPM database...)"
                dcpm list --format=tsv > "$db_file" 2>/dev/null || : > "$db_file"
            else
                warn "未找到 dcpm 命令。 (dcpm command not found)"
                : > "$db_file"
            fi
            ;;

        *)
            error "不支持的包管理器: $pm。 (Unsupported package manager: $pm.)"
            ;;
    esac
    
    local package_count
    package_count=$(wc -l < "$db_file" 2>/dev/null || echo 0)
    info "外部数据库已更新: 来自 $pm 的 $package_count 个软件包 (External database updated: $package_count packages from $pm)"
}

corix_manage_list() {
    echo "External package manager databases:"
    for db_file in "${EXTERNAL_PM_DB}"/*.db; do
        [ -f "$db_file" ] || continue
        
        local pm_name
        pm_name=$(basename "$db_file" .db)
        local package_count
        package_count=$(wc -l < "$db_file")
        local last_updated
        last_updated=$(stat -c %y "$db_file" | cut -d. -f1)
        
        echo "  $pm_name: $package_count packages (updated: $last_updated)"
    done
}

# [修改] 重写了收养函数，以使用正确的 db_mark_installed_external 并简化逻辑
# [MODIFIED] Rewrote adopt function to use the correct db_mark_installed_external and simplify logic
corix_manage_adopt() {
    local pm="$1"
    local package_pattern="$2"
    local db_file="${EXTERNAL_PM_DB}/${pm}.db"
    
    [ -f "$db_file" ] || error "未找到 $pm 的数据库。请先运行 'corix manage --sync-from $pm'。 (No database found for $pm. Run 'corix manage --sync-from $pm' first.)"
    
    info "正在 $pm 数据库中搜索匹配 '$package_pattern' 的软件包... (Searching for packages matching '$package_pattern' in $pm database...)"
    local matches
    matches=$(grep -i "$package_pattern" "$db_file")
    
    if [ -z "$matches" ]; then
        warn "没有找到匹配 '$package_pattern' 的软件包。 (No packages found matching '$package_pattern')"
        return 1
    fi
    
    echo "找到的软件包 (Found packages):"
    echo "$matches" | while IFS=$'\t' read -r pkg_name pkg_version pkg_status pkg_arch; do
        echo "  $pkg_name ($pkg_version) [$pkg_status/$pkg_arch]"
    done
    
    echo
    read -rp "是否将所有这些软件包收养到 corix 中? [y/N] (Adopt all these packages into corix? [y/N]) " choice
    [[ ! "$choice" =~ ^[yY] ]] && return 0
    
    # [修改] 循环并调用正确的、轻量级的标记函数
    # [MODIFIED] Loop and call the correct, lightweight marking function
    acquire_lock "system"
    trap 'release_lock "system"' RETURN
    echo "$matches" | while IFS=$'\t' read -r pkg_name pkg_version pkg_status pkg_arch; do
        # 只收养确实已安装的包
        # Only adopt packages that are actually installed
        [ "$pkg_status" = "installed" ] || continue
        
        info "正在从 $pm 收养 $pkg_name $pkg_version... (Adopting $pkg_name $pkg_version from $pm...)"
        
        # [修改] 调用正确的函数，不再需要生成临时文件列表
        # [MODIFIED] Call the correct function, no longer need to generate a temporary file list
        db_mark_installed_external "$pkg_name" "$pkg_version" "$pm"
        
        detail "成功收养 $pkg_name。 (Successfully adopted $pkg_name.)"
    done
    release_lock
}

# --- SECTION 22: SEARCH AND INFORMATION ---

corix_search() {
    if [ "${1:-}" = "--update-index" ]; then
        corix_search_update_index
        return 0
    fi
    
    [ $# -eq 0 ] && error "Usage: search <keyword> or search --update-index"
    local keyword="$1"
    
    [ ! -f "$SEARCH_INDEX_FILE" ] && {
        warn "Search index not found. Building index..."
        corix_search_update_index
    }
    
    info "Searching for: $keyword"
    local results
    results=$(grep -i "$keyword" "$SEARCH_INDEX_FILE" 2>/dev/null || true)
    
    if [ -z "$results" ]; then
        warn "No packages found matching '$keyword'"
        return 1
    fi
    
    echo "$results" | while IFS=':' read -r pkg_name pkg_desc pkg_path; do
        echo -e "\033[1;32m${pkg_name}\033[0m"
        echo -e "  \033[0;37mDescription:\033[0m $pkg_desc"
        
        # Check if installed
        if db_is_installed "$pkg_name"; then
            echo -e "  \033[1;32mStatus:\033[0m Installed"
        else
            echo -e "  \033[0;33mStatus:\033[0m Available"
        fi
        
        echo -e "  \033[0;90mPath:\033[0m $pkg_path"
        echo
    done
}

# =======================================================
# --- [SECURITY HARDENED] - 修复了扫描攻击漏洞
# =======================================================
# =======================================================
# --- [FINAL BUGFIX] - 修正了安全检查和路径解析问题
# =======================================================
# =======================================================
# --- [FINAL BUGFIX V2] - 真正修正了本地仓库路径解析问题
# =======================================================
corix_search_update_index() {
    msg "Updating package search index..."
    
    local temp_index_file; temp_index_file=$(mktemp)
    trap 'rm -f "$temp_index_file"' RETURN

    find "$REPOS_CONF_DIR" -name "*.conf" -type f | while read -r repo_conf; do
        local repo_name type path_to_scan
        repo_name=$(basename "$repo_conf" .conf)
        type=$(grep -E '^\s*type\s*=' "$repo_conf" | cut -d'=' -f2- | xargs)

        if [ "$type" = "local" ]; then
            path_to_scan=$(grep -E '^\s*path\s*=' "$repo_conf" | cut -d'=' -f2- | xargs)
        else
            path_to_scan="${REPOS_DIR}/${repo_name}"
        fi

        if [ -n "$path_to_scan" ] && [ -d "$path_to_scan" ]; then
            detail "  -> Indexing repository '${repo_name}'..."
            find "$path_to_scan" -name "*.build" -type f | while read -r build_file; do
                local meta pkgname slot pkg_desc pkg_dir_relative pkg_name_full
                meta=$(_parse_build_file "$build_file") || return 1

                pkgname=$(echo "$meta" | grep "^pkgname=" | cut -d= -f2)
                slot=$(echo "$meta" | grep "^slot=" | cut -d= -f2)
                pkg_desc=$(echo "$meta" | grep "^pkgdesc=" | cut -d= -f2)
                
                # [修正] 使用正确的路径解析逻辑
                pkg_dir_relative=$(dirname "${build_file#$path_to_scan/}")
                pkg_name_full="${pkg_dir_relative}:${slot}"

                echo "${pkg_name_full}:${pkg_desc}:${build_file}" >> "$temp_index_file"
            done
        fi
    done

    mkdir -p "$(dirname "$SEARCH_INDEX_FILE")"
    mv "$temp_index_file" "$SEARCH_INDEX_FILE"
    
    info "Search index updated successfully."
    # --- [BUGFIX] 在函数返回前，取消 RETURN 陷阱 ---
    # --- This prevents the trap from leaking into the calling function's scope ---
    trap - RETURN
}

# --- [新功能] 别名解析辅助函数 / [NEW] Alias resolution helper function ---
# 将用户提供的别名或ID解析为最终的频道ID。
# Resolves a user-provided alias or ID to its final channel ID.
# @param $1 - alias_or_id (The alias or ID to resolve / 要解析的别名或ID)
# @return The resolved channel ID, or the original string if not found. / 解析后的频道ID，如果未找到则返回原字符串。
_resolve_channel_id() {
    local alias_or_id="$1"
    # 首先尝试从别名表查找
    # First, try to look up in the alias table
    local resolved_id
    resolved_id=$(db_query_safe "$FORUM_DB" "SELECT channel_id FROM aliases WHERE alias_name = %s;" "$alias_or_id")
    
    if [ -n "$resolved_id" ]; then
        echo "$resolved_id"
    else
        # 如果不是别名，则假定它本身就是ID
        # If it's not an alias, assume it is an ID itself
        echo "$alias_or_id"
    fi
}

# --- [新功能] 高级附件搜索的核心逻辑 / [NEW] Core logic for advanced attachment search ---
# @param $@ - Command line arguments passed from the user / 用户传递的命令行参数
# --- [最终版] 高级附件搜索的核心逻辑 (兼容论坛) ---
# --- [FINAL] Core logic for advanced attachment search (Forum compatible) ---
# @param $@ - Command line arguments passed from the user / 用户传递的命令行参数
# =======================================================================================
# --- [V72 FINAL VERSION] _internal_find_attachments (DM & Group compatible)      ---
# --- [V72 最终版] _internal_find_attachments (兼容DM与群组)                      ---
# =======================================================================================
# This version correctly performs a symmetric search for Direct Messages (DMs)
# by looking for messages both sent to and received from the specified user channels.
# 此版本通过查找发送给以及接收自指定用户频道的消息，正确地对直接消息(DM)执行对称搜索。
_internal_find_attachments() {
    # --- 1. 参数解析与身份识别 / Argument Parsing & Identity Recognition ---
    local -a user_channel_ids=() group_channel_ids=()
    local name_pattern="" type_pattern=""
    local search_forum=1 # 默认搜索论坛 / Search forum by default
    local my_id
    my_id=$(get_our_node_id) # 获取当前用户ID以构建对称查询 / Get current user's ID for symmetric query

    while [ $# -gt 0 ]; do
        case "$1" in
            --channels)
                IFS=',' read -ra raw_ids <<< "$2"
                for id_or_alias in "${raw_ids[@]}"; do
                    local resolved_id
                    resolved_id=$(_resolve_channel_id "$id_or_alias")
                    local id_type
                    id_type=$(_get_identity_type "$resolved_id")
                    
                    if [ "$id_type" = "user" ]; then
                        user_channel_ids+=("$resolved_id")
                    else # Groups and Broadcasts
                        group_channel_ids+=("$resolved_id")
                    fi
                done
                # 如果指定了频道，则默认不搜索公共论坛 / If channels are specified, do not search the public forum by default
                search_forum=0
                shift 2
                ;;
            --include-forum)
                search_forum=1; shift ;;
            --name-like)
                name_pattern="$2"; shift 2 ;;
            --type)
                type_pattern=".${2}"; shift 2 ;;
            *)
                error "find-attachments: Unknown option '$1' / find-attachments: 未知选项 '$1'"
                ;;
        esac
    done

    # --- 2. 动态构建 SQL 查询 (重构版) / Dynamically build the SQL query (refactored) ---
    local final_query=""
    local -a params=()
    local -a query_parts=()

    # --- Part A: 构建针对 messages 表的查询 / Build query for 'messages' table ---
    if [ ${#user_channel_ids[@]} -gt 0 ] || [ ${#group_channel_ids[@]} -gt 0 ]; then
        local query_messages="
            SELECT M.recipient_id AS channel_id, 'message' AS source_type, M.tx_hash AS source_id, 
                   json_extract(M.attachment_meta, '$.filename') AS filename, 
                   json_extract(M.attachment_meta, '$.hash') AS attachment_hash, 
                   M.timestamp, M.sender_id
            FROM messages AS M
            WHERE M.attachment_meta IS NOT NULL AND M.attachment_meta != 'null'
        "
        local -a where_messages_or_conditions=()

        # -- Condition A: Symmetric search for Direct Messages (DMs)
        # -- 条件 A: 对直接消息 (DM) 进行对称搜索
        if [ ${#user_channel_ids[@]} -gt 0 ]; then
            local user_placeholders
            user_placeholders=$(printf ",%s" "${user_channel_ids[@]}" | cut -c2- | sed 's/[^,]*/%s/g')
            # Find messages I received FROM them OR messages I sent TO them.
            # 查找我从他们那里收到的消息，或者我发送给他们的消息。
            where_messages_or_conditions+=("(M.recipient_id = %s AND M.sender_id IN (${user_placeholders})) OR (M.sender_id = %s AND M.recipient_id IN (${user_placeholders}))")
            params+=("$my_id" "${user_channel_ids[@]}" "$my_id" "${user_channel_ids[@]}")
        fi
        
        # -- Condition B: Standard search for Groups and Broadcasts
        # -- 条件 B: 对群组和广播进行标准搜索
        if [ ${#group_channel_ids[@]} -gt 0 ]; then
            local group_placeholders
            group_placeholders=$(printf ",%s" "${group_channel_ids[@]}" | cut -c2- | sed 's/[^,]*/%s/g')
            where_messages_or_conditions+=("M.recipient_id IN (${group_placeholders})")
            params+=("${group_channel_ids[@]}")
        fi

        if [ ${#where_messages_or_conditions[@]} -gt 0 ]; then
            query_messages+=" AND ($(IFS=' OR '; echo "${where_messages_or_conditions[*]}"))"
        fi
        query_parts+=("$query_messages")
    fi

    # --- Part B: 构建针对 topics 表的查询 / Build query for 'topics' table ---
    if [ "$search_forum" -eq 1 ]; then
        local query_topics="
            SELECT T.author AS channel_id, 'topic' AS source_type, T.id AS source_id, 
                   T.attachment_name AS filename, T.attachment_hash AS attachment_hash, 
                   T.timestamp, T.author AS sender_id
            FROM topics AS T
            WHERE T.attachment_hash IS NOT NULL AND T.attachment_hash != ''
        "
        query_parts+=("$query_topics")
    fi
    
    # --- Part C: 构建针对 posts 表的查询 / Build query for 'posts' table ---
    if [ "$search_forum" -eq 1 ]; then
        local query_posts="
            SELECT P.topic_id AS channel_id, 'post' AS source_type, P.id AS source_id, 
                   P.attachment_name AS filename, P.attachment_hash AS attachment_hash, 
                   P.timestamp, P.author AS sender_id
            FROM posts AS P
            WHERE P.attachment_hash IS NOT NULL AND P.attachment_hash != ''
        "
        query_parts+=("$query_posts")
    fi

    # --- Part D: 组合并过滤所有查询 / Combine and filter all queries ---
    if [ ${#query_parts[@]} -eq 0 ]; then
        msg "请指定搜索范围。使用 --channels 或 --include-forum。/ Please specify a search scope. Use --channels or --include-forum."
        return
    fi
    
    local combined_query
    combined_query=$(IFS=' UNION ALL '; echo "${query_parts[*]}")

    # Now, build the final query with the filters applied to the combined result set.
    # 现在，构建最终的查询，将过滤器应用于组合后的结果集。
    final_query="SELECT * FROM (${combined_query}) AS combined WHERE 1=1"
    
    if [ -n "$name_pattern" ]; then
        final_query+=" AND filename LIKE %s"
        params+=("%${name_pattern}%")
    fi
    if [ -n "$type_pattern" ]; then
        final_query+=" AND filename LIKE %s"
        params+=("%${type_pattern}")
    fi
    final_query+=" ORDER BY timestamp DESC LIMIT 200;"
    
    # --- 3. 执行查询并格式化输出 / 3. Execute query and format the output ---
    info "正在搜索附件... / Searching for attachments..."
    local results
    results=$(db_query_safe "$FORUM_DB" "$final_query" "${params[@]}")

    if [ -z "$results" ]; then
        msg "未找到匹配的附件。/ No matching attachments found."
        return
    fi
    
    msg "搜索结果: / Search Results:"
    echo "--------------------------------------------------------------------------------"
    
    local count=0
    while IFS='|' read -r channel_id source_type source_id filename attachment_hash timestamp sender_id; do
        count=$((count + 1))
        local channel_name
        # 对论坛的 topic 和 post 做特殊处理
        # Special handling for forum topics and posts
        if [ "$source_type" = "topic" ] || [ "$source_type" = "post" ]; then
            local topic_title
            topic_title=$(db_query_safe "$FORUM_DB" "SELECT title FROM topics WHERE id = %s;" "$channel_id")
            channel_name="论坛话题 / Forum Topic: ${topic_title:-${channel_id:0:16}...}"
        else
            channel_name=$(_get_identity_nickname "$channel_id")
        fi

        echo -e "  \033[1;32m文件名 / Filename: \033[1m${filename}\033[0m"
        echo -e "  \033[0;36m频道 / Channel:    \033[0m${channel_name}"
        echo -e "  \033[0;36m来源 / Source:     \033[0m${source_type} (from: $(_get_identity_nickname "$sender_id"))"
        echo -e "  \033[0;33m日期 / Date:       \033[0m$(date -d "@$timestamp" '+%Y-%m-%d %H:%M:%S')"
        echo -e "  \033[0;32m下载命令 / Download Command:\033[0m"
        # 为不同来源提供正确的下载命令
        # Provide correct download command for different sources
        if [ "$source_type" = "message" ]; then
            echo -e "    corix message get-attachment ${source_id} \"${filename}\""
        else
            echo -e "    corix forum get-attachment ${attachment_hash} \"${filename}\""
        fi
        echo "--------------------------------------------------------------------------------"
    done <<< "$results"
    
    info "共找到 ${count} 个匹配项。 / Found ${count} matches."
}


# ==============================================================================
# --- [NEW E2EE FUNCTION] 获取任意身份的公钥                         ---
# --- [NEW E2EE FUNCTION] Get the public key of any identity         ---
# ==============================================================================
# This function is the cornerstone of E2EE key distribution. It securely fetches
# a user's public key from the on-chain transaction history.
# 此函数是 E2EE 密钥分发的基石。它从链上交易历史中安全地获取用户的公钥。
#
# @param $1 - identity_hash (The ID hash of the user / 用户的ID哈希)
# @return The path to the cached public key file, or empty on failure.
#         返回缓存的公钥文件路径，如果失败则返回空。
# ==============================================================================
# --- [REVISED E2EE FUNCTION V72] 获取任意身份的公钥 (健壮版)        ---
# --- [REVISED E2EE FUNCTION V72] Get public key of any identity (Robust) ---
# ==============================================================================
# Lookup order: 1. P2P Network (canonical) -> 2. Local Cache -> 3. On-chain DBs
# 查找顺序: 1. P2P网络 (权威) -> 2. 本地缓存 -> 3. 链上数据库
_validate_identity_pubkey_file() {
    "${PYTHON_CMD}" - "$1" "$2" <<'PY_IDENTITY_KEY'
import sys,pathlib,hashlib
from cryptography.hazmat.primitives.serialization import load_pem_public_key
from cryptography.hazmat.primitives.asymmetric import ec
pem=pathlib.Path(sys.argv[1]).read_text().rstrip('\n')
if hashlib.sha256(pem.encode()).hexdigest()!=sys.argv[2]: raise ValueError('Public key identity mismatch')
key=load_pem_public_key(pem.encode())
if not isinstance(key,ec.EllipticCurvePublicKey) or not isinstance(key.curve,ec.SECP256K1): raise ValueError('Invalid identity key curve')
PY_IDENTITY_KEY
}

_get_identity_pubkey() {
    [ $# -eq 1 ] && [[ "$1" =~ ^[a-f0-9]{64}$ ]] || return 1
    local identity_hash="$1" pubkey_path="${FORUM_PUBKEYS_DIR}/${1}.pub" staged
    mkdir -p "$FORUM_PUBKEYS_DIR" || return 1
    if [ -f "$pubkey_path" ] && _validate_identity_pubkey_file "$pubkey_path" "$identity_hash" 2>/dev/null; then
        printf '%s\n' "$pubkey_path"; return 0
    fi
    staged=$(mktemp "$FORUM_PUBKEYS_DIR/key.XXXXXX") || return 1
    if _p2p_download_object "$identity_hash" "$staged" && _validate_identity_pubkey_file "$staged" "$identity_hash" 2>/dev/null; then
        mv -f -- "$staged" "$pubkey_path" || return 1
        printf '%s\n' "$pubkey_path"; return 0
    fi
    if ! "${PYTHON_CMD}" - "$BLOCKCHAIN_DB" "$identity_hash" "$staged" <<'PY_IDENTITY_LOOKUP'
import sqlite3,sys,hashlib,pathlib
with sqlite3.connect(pathlib.Path(sys.argv[1]).resolve().as_uri()+'?mode=ro',uri=True) as db:
    rows=db.execute('SELECT public_key FROM validators UNION SELECT public_key FROM onchain_identities UNION SELECT public_key FROM transactions WHERE block_height IS NOT NULL')
    for (key,) in rows:
        key=key.rstrip('\n')
        if hashlib.sha256(key.encode()).hexdigest()==sys.argv[2]:
            pathlib.Path(sys.argv[3]).write_text(key+'\n');break
    else: raise ValueError('Identity public key unavailable')
PY_IDENTITY_LOOKUP
    then rm -f -- "$staged"; return 1; fi
    _validate_identity_pubkey_file "$staged" "$identity_hash" || { rm -f -- "$staged"; return 1; }
    mv -f -- "$staged" "$pubkey_path" || return 1
    printf '%s\n' "$pubkey_path"
}


# ==============================================================================
# --- [NEW E2EE FUNCTION] 端到端加密荷载                             ---
# --- [NEW E2EE FUNCTION] End-to-End Encrypt a Payload               ---
# ==============================================================================
# Encrypts a plaintext payload for a specific recipient using a hybrid ECIES-like scheme.
# 使用一个类 ECIES 的混合加密方案，为特定接收者加密一个明文荷载。
#
# @param $1 - plaintext (The data to encrypt / 要加密的数据)
# @param $2 - recipient_pubkey_file (Path to the recipient's public key / 接收者的公钥文件路径)
# @return A JSON object containing the encrypted data, base64 encoded.
#         返回一个包含加密数据的 JSON 对象 (Base64编码)。
_e2ee_encrypt_payload() {
    [ $# -eq 2 ] || return 1
    "${PYTHON_CMD}" - "$1" "$2" <<'PY_E2EE_ENCRYPT'
import base64,json,os,sys
from cryptography.hazmat.primitives import hashes,serialization,padding
from cryptography.hazmat.primitives.asymmetric import ec,rsa,padding as asymmetric_padding
from cryptography.hazmat.primitives.ciphers import Cipher,algorithms,modes
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.kdf.hkdf import HKDF
public=serialization.load_pem_public_key(open(sys.argv[2],'rb').read())
plaintext=sys.argv[1].encode()
if isinstance(public,ec.EllipticCurvePublicKey):
    ephemeral=ec.generate_private_key(public.curve)
    shared=ephemeral.exchange(ec.ECDH(),public)
    key=HKDF(algorithm=hashes.SHA256(),length=32,salt=None,info=b'CORIUM-E2EE-V1').derive(shared)
    nonce=os.urandom(12)
    pem=ephemeral.public_key().public_bytes(serialization.Encoding.PEM,serialization.PublicFormat.SubjectPublicKeyInfo).decode()
    result={'scheme':'ecdh-aes256gcm-v1','ephemeral_public_key':pem,'nonce':nonce.hex(),
            'encrypted_payload':base64.b64encode(AESGCM(key).encrypt(nonce,plaintext,b'CORIUM-E2EE-V1')).decode()}
elif isinstance(public,rsa.RSAPublicKey):
    # Retain the existing RSA envelope so old clients and stored mail remain readable.
    key=os.urandom(32); iv=os.urandom(16)
    padder=padding.PKCS7(128).padder(); padded=padder.update(plaintext)+padder.finalize()
    encryptor=Cipher(algorithms.AES(key),modes.CBC(iv)).encryptor()
    payload=encryptor.update(padded)+encryptor.finalize()
    wrapped=public.encrypt((key.hex()+':'+iv.hex()).encode(),asymmetric_padding.PKCS1v15())
    result={'encrypted_session_key':base64.b64encode(wrapped).decode(),'encrypted_payload':base64.b64encode(payload).decode()}
else: raise ValueError('Unsupported recipient encryption key')
print(json.dumps(result,ensure_ascii=False,separators=(',',':')))
PY_E2EE_ENCRYPT
}

_e2ee_decrypt_payload() {
    [ $# -eq 1 ] || return 1
    "${PYTHON_CMD}" - "$1" "$USER_IDENTITY_FILE" <<'PY_E2EE_DECRYPT'
import base64,json,sys
from cryptography.hazmat.primitives import hashes,serialization,padding
from cryptography.hazmat.primitives.asymmetric import ec,rsa,padding as asymmetric_padding
from cryptography.hazmat.primitives.ciphers import Cipher,algorithms,modes
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.kdf.hkdf import HKDF
try:
    envelope=json.loads(sys.argv[1]); private=serialization.load_pem_private_key(open(sys.argv[2],'rb').read(),password=None)
    payload=base64.b64decode(envelope['encrypted_payload'],validate=True)
    if envelope.get('scheme')=='ecdh-aes256gcm-v1':
        peer=serialization.load_pem_public_key(envelope['ephemeral_public_key'].encode())
        if not isinstance(private,ec.EllipticCurvePrivateKey) or not isinstance(peer,ec.EllipticCurvePublicKey) or private.curve.name!=peer.curve.name:
            raise ValueError('Invalid recipient or ephemeral key')
        shared=private.exchange(ec.ECDH(),peer)
        key=HKDF(algorithm=hashes.SHA256(),length=32,salt=None,info=b'CORIUM-E2EE-V1').derive(shared)
        plaintext=AESGCM(key).decrypt(bytes.fromhex(envelope['nonce']),payload,b'CORIUM-E2EE-V1')
    else:
        if not isinstance(private,rsa.RSAPrivateKey): raise ValueError('Invalid legacy recipient key')
        wrapped=base64.b64decode(envelope['encrypted_session_key'],validate=True)
        key,iv=private.decrypt(wrapped,asymmetric_padding.PKCS1v15()).decode().split(':')
        decryptor=Cipher(algorithms.AES(bytes.fromhex(key)),modes.CBC(bytes.fromhex(iv))).decryptor()
        padded=decryptor.update(payload)+decryptor.finalize()
        unpadder=padding.PKCS7(128).unpadder(); plaintext=unpadder.update(padded)+unpadder.finalize()
    sys.stdout.write(plaintext.decode())
except Exception:
    print('[解密失败: 密钥或内容无效 / Decryption failed: Invalid key or payload]')
    sys.exit(1)
PY_E2EE_DECRYPT
}

# =======================================================
# --- [V100 FINAL] 统一的区块级事件处理器             ---
# --- [V100 FINAL] Unified Block-Level Event Processor  ---
# =======================================================
#
# 此函数是状态机的心脏之一。它在每个区块高度被调用一次，
# 负责处理所有与该区块高度相关的、非交易触发的确定性事件。
# This function is one of the hearts of the state machine. It is called once per block height
# to handle all deterministic, non-transaction-triggered events related to that height.
#
# @param $1 - height (The block height to process events for)
_process_onchain_events_at_height() {
    local height="$1"

    # 1. 结算“有用功证明”的挑战与确认
    # 1. Settle 'Proof of Useful Work' challenges and confirmations
    _resolve_proofs_and_challenges_at_height "$height"
    
    # 2. 结算 NNS 域名拍卖
    # 2. Settle NNS domain auctions
    _nns_tally_auction_at_height "$height" 
    
    # 3. 执行已调度的治理变更
    # 3. Execute scheduled governance changes
    _protocol_execute_scheduled_changes "$height" || return 1
    _slashing_check_for_jailed_validators "$height" || return 1
    
    # 4. 结算群组治理投票
    # 4. Tally group governance votes
    _group_tally_owner_votes_at_height "$height"
    _group_tally_admin_votes_at_height "$height"

    # 5. [V100 核心] 处理已验证的 IBC 传入消息队列
    # 5. [V100 CORE] Process the validated IBC incoming message queue
    db_query_safe "$BLOCKCHAIN_DB" \
        "SELECT source_chain_id, source_tx_hash, message_type, message_payload FROM ibc_incoming_queue WHERE status = 'PEND-VALIDATION';" | \
        while IFS='|' read -r source_chain_id source_tx_hash message_type message_payload; do
        
        detail "[IBC-Process] 正在处理来自 '${source_chain_id}' 的已验证消息 (类型: ${message_type})... / Processing validated message from '${source_chain_id}' (type: ${message_type})..."
        
        case "$message_type" in
            "IBC_NNS_TRANSFER")
                local domain_name new_owner_id
                domain_name=$(echo "$message_payload" | jq -r .domain_name)
                new_owner_id=$(echo "$message_payload" | jq -r .new_owner_id)

                info "[IBC-NNS] 正在执行跨链域名所有权转移: ${domain_name} -> ${new_owner_id:0:16}..."
                info "[IBC-NNS] Executing cross-chain domain ownership transfer: ${domain_name} -> ${new_owner_id:0:16}..."
                
                db_execute_safe "$FORUM_DB" \
                    "INSERT OR REPLACE INTO nns_records (domain_name, owner_id, target_hash, last_update_height, registration_type) VALUES (%s, %s, 'PENDING_UPDATE_BY_NEW_OWNER', %d, 'ibc_transfer');" \
                    "$domain_name" "$new_owner_id" "$height"
                ;;
            
            "IBC_IDENTITY_SYNC")
                local id_hash nickname id_type
                id_hash=$(echo "$message_payload" | jq -r .id_hash)
                nickname=$(echo "$message_payload" | jq -r .nickname)
                id_type=$(echo "$message_payload" | jq -r .type)

                info "[IBC-Identity] 正在从 '${source_chain_id}' 同步身份: ${nickname} (${id_hash:0:16}...)"
                info "[IBC-Identity] Syncing identity from '${source_chain_id}': ${nickname} (${id_hash:0:16}...)"

                # 将带有来源链标记的身份信息写入本地缓存
                # Write the identity info with its source chain tag to the local cache
                db_execute_safe "$FORUM_DB" \
                    "INSERT OR REPLACE INTO identity_cache (id_hash, nickname, type, permissions, last_updated_height, source_chain) VALUES (%s, %s, %s, '{}', %d, %s);" \
                    "$id_hash" "$nickname" "$id_type" "$height" "$source_chain_id"
                ;;

            "IBC_GPG_KEY_BROADCAST")
                local gpg_key_b64 owner_id signature
                gpg_key_b64=$(echo "$message_payload" | jq -r .gpg_key_b64)
                owner_id=$(echo "$message_payload" | jq -r .owner_id)
                signature=$(echo "$message_payload" | jq -r .signature)
                
                # 验证签名，确保 GPG 密钥确实由其声明的所有者发布
                # Verify the signature to ensure the GPG key was indeed published by its claimed owner
                local owner_pubkey_file; owner_pubkey_file=$(_get_identity_pubkey "$owner_id")
                if [ -n "$owner_pubkey_file" ] && verify_signature "$gpg_key_b64" "$signature" "$owner_pubkey_file"; then
                    info "[IBC-Trust] 收到来自 '${source_chain_id}' 的有效联邦 GPG 密钥广播，正在导入... / Received a valid federated GPG key broadcast from '${source_chain_id}', importing..."
                    
                    # 创建一个特殊的、只读的联邦信任区
                    # Create a special, read-only federation trust zone
                    local fed_zone_dir="${TRUST_ZONES_DIR}/federation"
                    mkdir -p "$fed_zone_dir"
                    local keyring_path="${fed_zone_dir}/keyring.gpg"
                    
                    local temp_key_file; temp_key_file=$(mktemp)
                    echo "$gpg_key_b64" | base64 -d > "$temp_key_file"
                    
                    # 导入密钥到联邦密钥环
                    # Import the key to the federation keyring
                    gpg --batch --no-default-keyring --keyring "$keyring_path" --import "$temp_key_file"
                    rm -f "$temp_key_file"
                else
                    warn "[IBC-Trust] 收到来自 '${source_chain_id}' 的无效 GPG 密钥广播（签名验证失败），已忽略。"
                    warn "[IBC-Trust] Received an invalid GPG key broadcast from '${source_chain_id}' (signature verification failed), ignoring."
                fi
                ;;

            "IBC_STATE_INVALIDATION")
                local invalidated_hash reason
                invalidated_hash=$(echo "$message_payload" | jq -r .invalidated_tx_hash)
                reason=$(echo "$message_payload" | jq -r .reason)

                warn "[IBC-Security] 收到来自 '${source_chain_id}' 的状态作废宣告！ / Received state invalidation notice from '${source_chain_id}'!"
                info "  -> 交易 / Transaction: ${invalidated_hash:0:16}..."
                info "  -> 原因 / Reason: ${reason}"
                
                # 在本链的数据库中记录这个外部作废事件
                # Record this external invalidation event in this chain's database
                # 注意：我们需要一个新表来存储这些跨链的作废记录
                # Note: We need a new table to store these cross-chain invalidation records.
                db_execute_safe "$BLOCKCHAIN_DB" \
                    "INSERT OR IGNORE INTO ibc_invalidated_txs (source_chain, tx_hash, reason, invalidation_height) VALUES (%s, %s, %s, %d);" \
                    "$source_chain_id" "$invalidated_hash" "$reason" "$height"
                ;;
                
            *)
                warn "[IBC-Process] 收到未知的已验证 IBC 消息类型，已忽略: ${message_type} / Received unknown validated IBC message type, ignoring: ${message_type}"
                ;;
        esac

        # 无论处理结果如何，都将消息标记为已处理，防止重放
        # Mark the message as processed regardless of the outcome to prevent replays
        db_execute_safe "$BLOCKCHAIN_DB" \
            "UPDATE ibc_incoming_queue SET status = 'PROCESSED' WHERE source_chain_id = %s AND source_tx_hash = %s;" \
            "$source_chain_id" "$source_tx_hash"
    done
}
# =======================================================
# --- SECTION 25: DECENTRALIZED FORUM SYSTEM (V2.1)    ---
# --- 第25节: 去中心化论坛系统 (V2.1 - 补完签名验证)     ---
# =======================================================

# Forum-specific paths
FORUM_DB="${FORUM_DIR}/forum.db"
FORUM_OBJECTS_DIR="${FORUM_DIR}/objects"
FORUM_MANIFESTS_DIR="${FORUM_DIR}/manifests"
FORUM_PUBKEYS_DIR="${FORUM_DIR}/pubkeys"

# --- HELPER: Get user identity hash ---
_forum_get_identity() {
    [ -f "$USER_PUBLIC_KEY_FILE" ] || error "用户身份密钥文件未找到，无法发帖。请先运行 'corix init'。 (User identity key file not found, cannot create post. Please run 'corix init' first.)"
    _internal_hash_text "$(cat "$USER_PUBLIC_KEY_FILE")"
}

# --- NEW HELPER: Get author's public key from P2P network ---
_forum_get_author_pubkey() {
    local author_hash="$1" pubkey_path="$FORUM_PUBKEYS_DIR/$1.pub" candidate canonical
    [[ "$author_hash" =~ ^[a-f0-9]{64}$ ]] || return 1
    mkdir -p "$FORUM_PUBKEYS_DIR" || return 1
    # Original v108 forum manifests identified a PEM including its final newline.
    # Preserve those signed authors locally without relaxing canonical node identity.
    if [ -f "$pubkey_path" ] && _internal_verify_object_hash "$author_hash" "$pubkey_path"; then
        canonical=$(_internal_hash_text "$(cat "$pubkey_path")") || return 1
        if _validate_identity_pubkey_file "$pubkey_path" "$canonical"; then printf '%s\n' "$pubkey_path"; return 0; fi
    fi
    if candidate=$(_get_identity_pubkey "$author_hash"); then printf '%s\n' "$candidate"; return 0; fi
    candidate=$(mktemp "$FORUM_PUBKEYS_DIR/legacy-key.XXXXXX") || return 1
    CORIUM_TEMP_ITEMS+=("$candidate")
    _p2p_download_object "$author_hash" "$candidate" || return 1
    _internal_verify_object_hash "$author_hash" "$candidate" || return 1
    canonical=$(_internal_hash_text "$(cat "$candidate")") || return 1
    _validate_identity_pubkey_file "$candidate" "$canonical" || return 1
    mv -f -- "$candidate" "$pubkey_path" || return 1
    printf '%s\n' "$pubkey_path"
}

# --- MODIFIED FUNCTION: Initialize/Upgrade forum database ---
forum_init() {
    mkdir -p "$FORUM_DIR" "$FORUM_OBJECTS_DIR" "$FORUM_MANIFESTS_DIR" "$FORUM_PUBKEYS_DIR"
    
    db_init "$FORUM_DB" "
    CREATE TABLE IF NOT EXISTS topics (
        id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        author TEXT NOT NULL,
        timestamp INTEGER NOT NULL,
        signature TEXT NOT NULL,
        content_hash TEXT NOT NULL,
        attachment_hash TEXT,
        attachment_name TEXT,
        associated_group_id TEXT DEFAULT NULL
    );
    CREATE TABLE IF NOT EXISTS posts (
        id TEXT PRIMARY KEY,
        topic_id TEXT NOT NULL,
        author TEXT NOT NULL,
        timestamp INTEGER NOT NULL,
        signature TEXT NOT NULL,
        content_hash TEXT NOT NULL,
        attachment_hash TEXT,
        attachment_name TEXT,
        parent_post TEXT,
        FOREIGN KEY(topic_id) REFERENCES topics(id)
    );
    CREATE TABLE IF NOT EXISTS objects (
        hash TEXT PRIMARY KEY,
        file_path TEXT NOT NULL,
        last_seen INTEGER NOT NULL
    );
    "
    info "论坛数据库已在 '$FORUM_DB' 初始化或验证。 (Forum database has been initialized or verified at '$FORUM_DB'.)"
}

# --- REWRITTEN FUNCTION: Create and Distribute Content ---
forum_distribute_content() {
    local content_path="$1" attachment_path="$2" path hash staged
    [ -f "$content_path" ] || return 1
    [ -z "$attachment_path" ] || [ -f "$attachment_path" ] || return 1
    mkdir -p "$FORUM_OBJECTS_DIR" || return 1
    local content_hash="" attachment_hash=""
    for path in "$content_path" "$attachment_path"; do
        [ -n "$path" ] || continue
        hash=$(calculate_hash "$path") || return 1
        staged=$(mktemp "$FORUM_OBJECTS_DIR/.publish.XXXXXX") || return 1
        CORIUM_TEMP_ITEMS+=("$staged")
        cp -- "$path" "$staged" || return 1
        [ "$(calculate_hash "$staged")" = "$hash" ] || return 1
        mv -f -- "$staged" "$FORUM_OBJECTS_DIR/$hash" || return 1
        p2p_split_file "$FORUM_OBJECTS_DIR/$hash" >/dev/null || return 1
        dht_store_chunk "$hash" "$FORUM_OBJECTS_DIR/$hash" 0 "$(stat -c%s "$FORUM_OBJECTS_DIR/$hash")" || return 1
        if [ "$path" = "$content_path" ] && [ -z "$content_hash" ]; then content_hash="$hash"; else attachment_hash="$hash"; fi
    done
    printf '%s|%s\n' "$content_hash" "$attachment_hash"
}

# =======================================================================================
# --- [V83 FINAL] forum_create_topic (支持 ACL 关联)                                ---
# --- [V83 FINAL] forum_create_topic (with ACL Association Support)                 ---
# =======================================================================================
# REWRITTEN FUNCTION: Create new forum topic
# [V83] 增加了第四个参数 associate_group_id
# [V83] Added a fourth argument: associate_group_id
forum_create_topic() (
    local published=false
    db_begin_transaction "$FORUM_DB" "$BLOCKCHAIN_DB" "$DHT_DB" || return 1
    trap 'status=$?; if ! $published; then db_rollback_transaction "$FORUM_DB" "$BLOCKCHAIN_DB" "$DHT_DB"; fi; exit "$status"' EXIT
    local title="$1"
    local content_body="$2"
    local attachment_file="$3"
    local associate_group_id="${4:-}" # 可选参数 / Optional argument

    local author timestamp
    author=$(_forum_get_identity) || return 1
    timestamp=$(date +%s)

    local tmp_content_file; tmp_content_file=$(mktemp)
    CORIUM_TEMP_ITEMS+=("$tmp_content_file")
    printf '%s' "$content_body" > "$tmp_content_file"

    local hashes; hashes=$(forum_distribute_content "$tmp_content_file" "$attachment_file") || return 1
    local content_hash="${hashes%|*}"
    local attachment_hash="${hashes#*|}"
    local attachment_name=""; [ -n "$attachment_file" ] && attachment_name=$(basename "$attachment_file")
    
    # [V105.7 SECURITY] Add rate limit to prevent content creation spam.
    # [V105.7 安全] 增加速率限制以防止内容创建垃圾信息。
    if ! _internal_rate_limiter_check "content_creation" 5 60; then
        error "内容创建操作过于频繁。请稍后再试。 / Content creation is too frequent. Please try again later."
        return 1
    fi

    # 1. 创建被签名的数据 (manifest)，现在包含了 associated_group_id
    # 1. Create the data to be signed (the manifest), now including associated_group_id
    # [V83] 使用 jq 来安全地构造 JSON，特别是处理 associate_group_id 可能为 null 的情况
    # [V83] Use jq to safely construct the JSON, especially to handle the case where associate_group_id might be null
    local manifest_unsigned
    manifest_unsigned=$(jq -n \
        --arg title "$title" \
        --arg author "$author" \
        --argjson ts "$timestamp" \
        --arg chash "$content_hash" \
        --arg ahash "$attachment_hash" \
        --arg aname "$attachment_name" \
        --arg assoc_gid "${associate_group_id:-null}" \
        '{
            "version": "2.0", 
            "title": $title,
            "author": $author,
            "timestamp": $ts,
            "content_hash": $chash,
            "attachment_hash": $ahash,
            "attachment_name": $aname,
            "associated_group_id": (if $assoc_gid == "null" then null else $assoc_gid end)
        }')

    # 2. 对其进行签名
    # 2. Sign it
    local signature; signature=$(sign_data "$manifest_unsigned" "$USER_IDENTITY_FILE") || return 1

    # 3. 创建最终分发的、包含签名的完整 manifest
    # 3. Create the final, distributable manifest including the signature
    local manifest_signed; manifest_signed=$(echo "${manifest_unsigned}" | jq --arg sig "$signature" '. + {signature: $sig}')

    # 4. 话题ID是完整、带签名 manifest 的哈希
    # 4. The topic ID is the hash of the complete, signed manifest
    local topic_id; topic_id=$(_internal_hash_text "$manifest_signed")

    # 5. [本地操作] 将元数据写入本地数据库，以便立即显示
    # 5. [LOCAL ACTION] Write metadata to the local DB for immediate display
    # 注意：这里的 associate_group_id 必须处理 jq 返回的 null 字符串
    # NOTE: The associate_group_id here must handle the null string returned by jq
    local final_assoc_gid="$associate_group_id"
    [ "$final_assoc_gid" = "null" ] || [ -z "$final_assoc_gid" ] && final_assoc_gid=""
    db_execute_safe "$FORUM_DB" \
        "INSERT INTO topics (id, title, author, timestamp, signature, content_hash, attachment_hash, attachment_name, associated_group_id) VALUES (%s, %s, %s, %d, %s, %s, %s, %s, %s);" \
        "$topic_id" "$title" "$author" "$timestamp" "$signature" "$content_hash" "$attachment_hash" "$attachment_name" "$final_assoc_gid"

    # 6. 将 manifest 和内容发布到 P2P 网络
    # 6. Publish the manifest and content to the P2P network
    local tmp_manifest_file="${FORUM_MANIFESTS_DIR}/${topic_id}.json"
    printf '%s' "$manifest_signed" > "$tmp_manifest_file" || return 1
    dht_store_chunk "$topic_id" "$tmp_manifest_file" 0 "$(stat -c%s "$tmp_manifest_file")" || return 1
    p2p_split_file "$tmp_manifest_file" >/dev/null || return 1

    # 7. 提交【未改变的】、简单的区块链交易，只作为发现信标
    # 7. Submit the [UNCHANGED], simple blockchain transaction, only as a discovery beacon
    local tx_data; tx_data=$(jq -n --arg tid "$topic_id" '{type:"forum_topic", topic_id: $tid}')
    blockchain_create_transaction "forum" "$tx_data" >/dev/null || return 1

    # rm -f "$tmp_content_file" is handled by the global trap
    db_commit_transaction "$FORUM_DB" "$BLOCKCHAIN_DB" "$DHT_DB" || return 1
    published=true
    msg "话题已创建并发布到网络。话题ID: $topic_id / Topic created and published to the network. Topic ID: $topic_id"
    
    # 将新的 topic_id 输出到标准输出，以便 set-policy 等函数可以捕获它
    # Output the new topic_id to stdout so functions like set-policy can capture it
    echo "$topic_id"
)

# --- REWRITTEN FUNCTION: Create new forum post ---
forum_create_post() (
    local published=false
    db_begin_transaction "$FORUM_DB" "$BLOCKCHAIN_DB" "$DHT_DB" || return 1
    trap 'status=$?; if ! $published; then db_rollback_transaction "$FORUM_DB" "$BLOCKCHAIN_DB" "$DHT_DB"; fi; exit "$status"' EXIT
    local topic_id="$1"
    local content_body="$2"
    local attachment_file="$3"
    
    local topic_exists
    topic_exists=$(db_query_safe "$FORUM_DB" \
        "SELECT COUNT(*) FROM topics WHERE id = %s;" \
        "$topic_id")
    [ "$topic_exists" -eq 0 ] && error "错误: 话题 '$topic_id' 不存在。 (Error: Topic '$topic_id' does not exist.)"

    local author timestamp
    author=$(_forum_get_identity) || return 1
    timestamp=$(date +%s)

    local tmp_content_file
    tmp_content_file=$(mktemp) || return 1
    CORIUM_TEMP_ITEMS+=("$tmp_content_file")
    printf '%s' "$content_body" > "$tmp_content_file"

    local hashes
    hashes=$(forum_distribute_content "$tmp_content_file" "$attachment_file") || return 1
    local content_hash="${hashes%|*}"
    local attachment_hash="${hashes#*|}"
    local attachment_name=""
    [ -n "$attachment_file" ] && attachment_name=$(basename "$attachment_file")

    local manifest_unsigned
    manifest_unsigned=$(jq -n --arg tid "$topic_id" --arg author "$author" --argjson ts "$timestamp" --arg ch "$content_hash" --arg ah "$attachment_hash" --arg an "$attachment_name" '{topic_id:$tid,author:$author,timestamp:$ts,content_hash:$ch,attachment_hash:$ah,attachment_name:$an}') || return 1
    local signature
    signature=$(sign_data "$manifest_unsigned" "$USER_IDENTITY_FILE") || return 1
    
    local manifest_signed
    manifest_signed=$(jq --arg sig "$signature" '. + {signature:$sig}' <<< "$manifest_unsigned") || return 1

    local post_id
    post_id=$(_internal_hash_text "$manifest_signed")

    db_execute_safe "$FORUM_DB" \
        "INSERT INTO posts (id, topic_id, author, timestamp, signature, content_hash, attachment_hash, attachment_name) VALUES (%s, %s, %s, %d, %s, %s, %s, %s);" \
        "$post_id" "$topic_id" "$author" "$timestamp" "$signature" "$content_hash" "$attachment_hash" "$attachment_name"

    local tmp_manifest_file="${FORUM_MANIFESTS_DIR}/${post_id}.json"
    printf '%s' "$manifest_signed" > "$tmp_manifest_file" || return 1
    dht_store_chunk "$post_id" "$tmp_manifest_file" 0 "$(stat -c%s "$tmp_manifest_file")" || return 1
    p2p_split_file "$tmp_manifest_file" >/dev/null || return 1

    local tx_data="{\"type\":\"forum_post\",\"post_id\":\"$post_id\",\"topic_id\":\"$topic_id\"}"
    blockchain_create_transaction "forum" "$tx_data" >/dev/null || return 1
    
    rm -f "$tmp_content_file"
    db_commit_transaction "$FORUM_DB" "$BLOCKCHAIN_DB" "$DHT_DB" || return 1
    published=true
    msg "回复已发布。帖子ID: $post_id (Reply published. Post ID: $post_id)"
)

# 文件: corix.sh
# 函数: forum_fetch_object (重构后)

# --- NEW FUNCTION: Fetch a single object from P2P network ---
forum_fetch_object() {
    local object_hash="$1" output_dir="$2" output_path
    [ -n "$object_hash" ] || return 0
    [[ "$object_hash" =~ ^[a-f0-9]{64}$ ]] || return 1
    mkdir -p -- "$output_dir" || return 1
    output_path="$output_dir/$object_hash"
    if ! [ -f "$output_path" ] || ! _internal_verify_object_hash "$object_hash" "$output_path"; then
        _p2p_download_object "$object_hash" "$output_path" || return 1
    fi
    db_execute_safe "$FORUM_DB" "INSERT OR REPLACE INTO objects (hash,file_path,last_seen) VALUES (%s,%s,%d);" "$object_hash" "$output_path" "$(date +%s)" || return 1
}

# =======================================================================================
# --- [V83 FINAL] forum_sync (支持 ACL 关联字段)                                    ---
# --- [V83 FINAL] forum_sync (with ACL Association Field Support)                   ---
# =======================================================================================
# REWRITTEN FUNCTION: Sync forum content from network
forum_sync() {
    msg "正在从网络同步论坛内容。 / Syncing forum content from the network."
    local rows row tx_data item_id item_type topic_id manifest_path manifest_signed manifest_unsigned author signature pubkey_path legacy content_hash attachment_hash failed=0
    rows=$(db_query_static "$BLOCKCHAIN_DB" "SELECT json_array(data) FROM transactions WHERE type='forum' AND block_height IS NOT NULL ORDER BY block_height,timestamp,hash;") || return 1
    while IFS= read -r row; do
        [ -n "$row" ] || continue
        tx_data=$(jq -er '.[0]|fromjson' <<< "$row") || { failed=1; continue; }
        item_type=$(jq -er '.type' <<< "$tx_data") || { failed=1; continue; }
        case "$item_type" in
            forum_topic) item_id=$(jq -er '.topic_id' <<< "$tx_data"); item_type=topic;;
            forum_post) item_id=$(jq -er '.post_id' <<< "$tx_data"); item_type=post;;
            *) failed=1; continue;;
        esac
        [[ "$item_id" =~ ^[a-f0-9]{64}$ ]] || { failed=1; continue; }
        manifest_path="$FORUM_MANIFESTS_DIR/$item_id.json"
        if [ -f "$manifest_path" ] && _internal_verify_object_hash "$item_id" "$manifest_path"; then
            : # A validated local manifest can repair missing DB or object state.
        else
            forum_fetch_object "$item_id" "$FORUM_MANIFESTS_DIR" || { failed=1; continue; }
            mv -f -- "$FORUM_MANIFESTS_DIR/$item_id" "$manifest_path" || return 1
        fi
        if ! "${PYTHON_CMD}" - "$manifest_path" "$item_type" "$tx_data" <<'PY_FORUM_VALIDATE'
import json,re,sys
from pathlib import Path
def unique(pairs):
    result={}
    for key,value in pairs:
        if key in result: raise ValueError('Duplicate manifest field')
        result[key]=value
    return result
m=json.loads(Path(sys.argv[1]).read_text(),object_pairs_hook=unique);kind=sys.argv[2];tx=json.loads(sys.argv[3])
hashok=lambda h:isinstance(h,str) and re.fullmatch('[a-f0-9]{64}',h) is not None
assert isinstance(m,dict) and hashok(m['author']) and hashok(m['content_hash'])
assert type(m['timestamp']) is int and 0<=m['timestamp']<=9223372036854775807
assert isinstance(m['signature'],str) and re.fullmatch('[a-f0-9]+',m['signature']) and len(m['signature'])%2==0
assert isinstance(m.get('attachment_hash',''),str) and (not m.get('attachment_hash') or hashok(m['attachment_hash']))
assert isinstance(m.get('attachment_name',''),str)
if kind=='topic':
    assert isinstance(m['title'],str) and (m.get('associated_group_id') in (None,'') or hashok(m.get('associated_group_id')))
else:
    assert hashok(m['topic_id']) and m['topic_id']==tx['topic_id']
PY_FORUM_VALIDATE
        then failed=1; continue; fi
        manifest_signed=$(cat "$manifest_path") || return 1
        author=$(jq -er '.author' <<< "$manifest_signed") || return 1
        signature=$(jq -er '.signature' <<< "$manifest_signed") || return 1
        if [ "$(jq -r '.version' <<< "$manifest_signed")" = '3.0' ]; then
            "${PYTHON_CMD}" - "$manifest_path" "${CORIUM_NETWORK_ID_OVERRIDE:-${CORIUM_NETWORK_ID:-default}}" "$item_type" <<'PY_FORUM_V3'
import hashlib,json,sys
from pathlib import Path
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey
m=json.loads(Path(sys.argv[1]).read_text())
keys={'schema','network','title','content','reply_to','timestamp','nonce','public_key'}
u={k:m[k] for k in keys}
assert u['schema']=='ziokt.forum.v3' and u['network']==sys.argv[2]
assert isinstance(u['title'],str) and len(u['title'].encode())<=256
assert isinstance(u['content'],str) and 0<len(u['content'].encode())<=65536
assert m['author']==hashlib.sha256(bytes.fromhex(u['public_key'])).hexdigest()
assert m['content_hash']==hashlib.sha256(u['content'].encode()).hexdigest()
assert not m.get('attachment_hash') and not m.get('attachment_name') and not m.get('associated_group_id')
assert (sys.argv[3]=='post' and m['topic_id']==u['reply_to']) or (sys.argv[3]=='topic' and not u['reply_to'] and u['title'].strip())
Ed25519PublicKey.from_public_bytes(bytes.fromhex(u['public_key'])).verify(bytes.fromhex(m['signature']),json.dumps(u,sort_keys=True,ensure_ascii=False,separators=(',',':'),allow_nan=False).encode())
PY_FORUM_V3
            [ "$?" -eq 0 ] || { failed=1; continue; }
        else
            pubkey_path=$(_forum_get_author_pubkey "$author") || { failed=1; continue; }
            [ -f "$pubkey_path" ] || { failed=1; continue; }
            manifest_unsigned=$(jq 'del(.signature)' <<< "$manifest_signed") || { failed=1; continue; }
            if ! verify_signature "$manifest_unsigned" "$signature" "$pubkey_path"; then
                # Preserve the original v108 post writer's whitespace-bound signatures.
                legacy=$("${PYTHON_CMD}" - "$manifest_path" <<'PY_FORUM_LEGACY'
import json,re,sys,pathlib
raw=pathlib.Path(sys.argv[1]).read_text().rstrip('\n');m=json.loads(raw)
old=re.sub(r', "signature": "[a-f0-9]+"\n}\Z','}',raw)
assert old!=raw and json.loads(old)=={k:v for k,v in m.items() if k!='signature'}
print(old,end='')
PY_FORUM_LEGACY
                ) || { failed=1; continue; }
                verify_signature "$legacy" "$signature" "$pubkey_path" || { failed=1; continue; }
            fi
        fi
        content_hash=$(jq -er '.content_hash' <<< "$manifest_signed") || return 1
        attachment_hash=$(jq -r '.attachment_hash // ""' <<< "$manifest_signed") || return 1
        forum_fetch_object "$content_hash" "$FORUM_OBJECTS_DIR" || { failed=1; continue; }
        forum_fetch_object "$attachment_hash" "$FORUM_OBJECTS_DIR" || { failed=1; continue; }
        if [ "$item_type" = topic ]; then
            db_execute_safe "$FORUM_DB" "INSERT OR REPLACE INTO topics(id,title,author,timestamp,signature,content_hash,attachment_hash,attachment_name,associated_group_id) VALUES (%s,%s,%s,%d,%s,%s,%s,%s,%s);" "$item_id" "$(jq -r .title <<< "$manifest_signed")" "$author" "$(jq -r .timestamp <<< "$manifest_signed")" "$signature" "$content_hash" "$attachment_hash" "$(jq -r '.attachment_name // ""' <<< "$manifest_signed")" "$(jq -r '.associated_group_id // ""' <<< "$manifest_signed")" || return 1
        else
            topic_id=$(jq -er '.topic_id' <<< "$manifest_signed") || return 1
            db_execute_safe "$FORUM_DB" "INSERT OR REPLACE INTO posts(id,topic_id,author,timestamp,signature,content_hash,attachment_hash,attachment_name) VALUES (%s,%s,%s,%d,%s,%s,%s,%s);" "$item_id" "$topic_id" "$author" "$(jq -r .timestamp <<< "$manifest_signed")" "$signature" "$content_hash" "$attachment_hash" "$(jq -r '.attachment_name // ""' <<< "$manifest_signed")" || return 1
        fi
    done <<< "$rows"
    if [ "$failed" -ne 0 ]; then warn "部分论坛对象未通过恢复或验证。 / Some forum objects could not be recovered or verified."; return 1; fi
    msg "论坛同步完成。 / Forum sync complete."
}

# --- REWRITTEN FUNCTION: Display forum topics ---
forum_list_topics() {
    msg "论坛主题列表:"
    local block_clause=$(_get_blocked_users_sql_clause "topics" "author")
    db_query_static "$FORUM_DB" "SELECT id, title, author, datetime(timestamp, 'unixepoch', 'localtime') FROM topics WHERE 1=1 ${block_clause} ORDER BY timestamp DESC;" | while IFS='|' read -r id title author ts; do
        [ -n "$id" ] || continue
        echo -e "\033[1;32mID: $id\033[0m"
        echo -e "  \033[1m标题:\033[0m $title"
        echo -e "  \033[0;36m作者:\033[0m ${author:0:16}...  \033[0;33m时间:\033[0m $ts"
        echo
    done
}

# --- REWRITTEN FUNCTION: Display a topic and its posts ---
forum_show_topic() {
    local topic_id="$1"
    
    local topic_info
    topic_info=$(db_query_safe "$FORUM_DB" \
        "SELECT title, author, timestamp, content_hash, attachment_hash, attachment_name FROM topics WHERE id = %s;" \
        "$topic_id")
    [ -z "$topic_info" ] && { error "话题 '$topic_id' 未找到。"; return 1; }
    
    IFS='|' read -r title author ts content_hash attachment_hash attachment_name <<< "$topic_info"

    echo -e "\n\033[1;33m=== 主题: $title ===\033[0m"
    echo -e "\033[0;36m作者: ${author:0:16}...\n时间: $(date -d "@$ts" '+%Y-%m-%d %H:%M:%S')\033[0m"
    echo -e "\033[1;34m--- 正文内容 ---\033[0m"
    
    local content_path="${FORUM_OBJECTS_DIR}/${content_hash}"
    [ -f "$content_path" ] && cat "$content_path" || echo "[内容文件本地不存在，请运行 'corix forum sync' 或 'corix forum get-attachment $content_hash']"
    
    if [ -n "$attachment_hash" ]; then
        echo -e "\n\033[1;32m--- 附件 ---\033[0m"
        echo -e "文件名: \033[1m$attachment_name\033[0m"
        echo -e "哈希: $attachment_hash"
        echo -e "下载命令: \033[0;32mcorix forum get-attachment $attachment_hash \"$attachment_name\"\033[0m"
    fi
    echo -e "\n\033[1;33m--- 回复列表 ---\033[0m"

    local block_clause=$(_get_blocked_users_sql_clause "posts" "author")
    db_query_safe "$FORUM_DB" \
        "SELECT id, author, timestamp, content_hash, attachment_hash, attachment_name, inline_content FROM posts WHERE topic_id = %s ${block_clause} ORDER BY timestamp ASC;" \
        "$topic_id" | while IFS='|' read -r p_id p_author p_ts p_chash p_ahash p_aname; do
        echo -e "\n\033[0;36m> 回复者: ${p_author:0:16}...\t时间: $(date -d "@$p_ts" '+%Y-%m-%d %H:%M')\033[0m"
        local post_content_path="${FORUM_OBJECTS_DIR}/${p_chash}"
        [ -f "$post_content_path" ] && cat "$post_content_path" | sed 's/^/  /' || echo "  [内容文件本地不存在]"
        if [ -n "$p_ahash" ]; then
            echo -e "  \033[0;32m附件:\033[0m $p_aname ($p_ahash)"
        fi
    done
    echo
}

# --- 新增函数: 下载附件/内容对象 ---
# --- NEW FUNCTION: Download an attachment/content object ---
forum_get_attachment() {
    [ $# -ge 1 ] && [ $# -le 2 ] || { echo "Usage / 用法: corix p2p get <sha256> [filename]" >&2; return 1; }
    local object_hash="$1" output_file="${2:-$1}" object_path
    [[ "$object_hash" =~ ^[0-9a-f]{64}$ ]] || { echo "Invalid hash / 无效哈希" >&2; return 1; }
    [[ "$output_file" != */* && "$output_file" != "." && "$output_file" != ".." && -n "$output_file" ]] || { echo "Invalid filename / 无效文件名" >&2; return 1; }
    object_path="${FORUM_OBJECTS_DIR}/${object_hash}"
    if [ ! -f "$object_path" ]; then
        forum_fetch_object "$object_hash" "$FORUM_OBJECTS_DIR" || return 1
    fi
    # Verify the exact bounded bytes before creating a private, exclusive output.
    python3 - "$object_path" "$output_file" "$object_hash" <<'PYGET'
import hashlib, os, stat, sys
source, target, expected = sys.argv[1:]
try:
    fd = os.open(source, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        st = os.fstat(fd)
        if not stat.S_ISREG(st.st_mode) or st.st_size > 64 * 1024 * 1024:
            raise ValueError("invalid object size/type")
        with os.fdopen(fd, "rb", closefd=False) as stream:
            data = stream.read(64 * 1024 * 1024 + 1)
        if len(data) > 64 * 1024 * 1024 or hashlib.sha256(data).hexdigest() != expected:
            raise ValueError("object integrity mismatch")
    finally:
        os.close(fd)
    out = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    try:
        with os.fdopen(out, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
    except BaseException:
        os.unlink(target)
        raise
except (OSError, ValueError) as exc:
    print("Download rejected / 下载被拒绝: " + str(exc), file=sys.stderr)
    sys.exit(1)
PYGET
}


# Exports a full topic and all its related data into a single, portable tarball.
# 将一个完整的话题及其所有相关数据导出到一个单一的、可移植的tar包中。
#
# @param $1 - topic_id  (The ID of the topic to export / 要导出的话题ID)
# @param $2 - output_file (The path for the output .tar.gz file / 输出的 .tar.gz 文件路径)
forum_export_topic() {
    local topic_id="$1"
    local output_file="$2"

    # --- 步骤 1: 验证话题是否存在 ---
    local topic_exists
    topic_exists=$(db_query_safe "$FORUM_DB" \
        "SELECT COUNT(*) FROM topics WHERE id = %s;" \
        "$topic_id")
    [ "$topic_exists" -eq 0 ] && error "错误: 话题 '$topic_id' 未找到，无法导出。 (Error: Topic '$topic_id' not found, cannot export.)"
    
    msg "正在导出话题 '$topic_id' 到 '$output_file'..."
    info "Exporting topic '$topic_id' to '$output_file'..."

    # --- 步骤 2: 创建一个临时目录用于打包 ---
    local temp_export_dir
    temp_export_dir=$(mktemp -d -p "$BUILD_TMP_DIR_BASE" "forum_export.XXXXXX")
    
    # 在临时目录中创建与真实结构匹配的子目录
    mkdir -p "${temp_export_dir}/manifests" "${temp_export_dir}/objects"

    # --- 步骤 3: 收集所有需要打包的文件哈希 ---
    local -a hashes_to_pack=()
    
    # 添加话题自身的 manifest 哈希 (就是 topic_id)
    hashes_to_pack+=("$topic_id")
    
    # 获取话题的内容和附件哈希
    local topic_hashes
    topic_hashes=$(db_query_safe "$FORUM_DB" \
        "SELECT content_hash, attachment_hash FROM topics WHERE id = %s;" \
        "$topic_id")
    IFS='|' read -r t_content_hash t_attachment_hash <<< "$topic_hashes"
    [ -n "$t_content_hash" ] && hashes_to_pack+=("$t_content_hash")
    [ -n "$t_attachment_hash" ] && hashes_to_pack+=("$t_attachment_hash")

    # 获取所有回帖的 manifest 哈希、内容哈希和附件哈希
    db_query_safe "$FORUM_DB" \
        "SELECT id, content_hash, attachment_hash FROM posts WHERE topic_id = %s;" \
        "$topic_id" | while IFS='|' read -r p_id p_content_hash p_attachment_hash; do
        [ -n "$p_id" ] && hashes_to_pack+=("$p_id")
        [ -n "$p_content_hash" ] && hashes_to_pack+=("$p_content_hash")
        [ -n "$p_attachment_hash" ] && hashes_to_pack+=("$p_attachment_hash")
    done

    # --- 步骤 4: 将所有文件复制到临时目录 ---
    info "正在收集文件... (Collecting files...)"
    local missing_files=0
    for hash in "${hashes_to_pack[@]}"; do
        # 判断是 manifest 还是 object
        local source_path=""
        if [ -f "${FORUM_MANIFESTS_DIR}/${hash}.json" ]; then
            source_path="${FORUM_MANIFESTS_DIR}/${hash}.json"
            cp "$source_path" "${temp_export_dir}/manifests/"
            detail "  -> 已打包清单 (Packed manifest): ${hash:0:16}..."
        elif [ -f "${FORUM_OBJECTS_DIR}/${hash}" ]; then
            source_path="${FORUM_OBJECTS_DIR}/${hash}"
            cp "$source_path" "${temp_export_dir}/objects/"
            detail "  -> 已打包对象 (Packed object): ${hash:0:16}..."
        else
            warn "警告: 话题依赖的对象文件 '$hash' 在本地缺失，导出包可能不完整。"
            warn "Warning: Topic dependency object '$hash' is missing locally. The exported archive may be incomplete."
            missing_files=1
        fi
    done

    # --- 步骤 5: 创建一个元数据文件，指明主话题ID ---
    echo "$topic_id" > "${temp_export_dir}/TOPIC_ID"
    
    # --- 步骤 6: 将临时目录打包成 tar.gz ---
    info "正在创建压缩包... (Creating archive...)"
    if tar -C "$temp_export_dir" -czf "$output_file" .; then
        msg "话题已成功导出到: $output_file"
        msg "Topic successfully exported to: $output_file"
        if [ "$missing_files" -eq 1 ]; then
            warn "请注意，由于部分文件缺失，此导出包不完整。"
            warn "Please note, this export is incomplete due to missing files."
        fi
    else
        error "创建压缩包失败。 (Failed to create archive.)"
    fi
    
    # --- 步骤 7: 清理临时目录 ---
    CORIUM_TEMP_ITEMS+=("$temp_export_dir")
}


# Imports a topic from a portable tarball created by forum_export_topic.
# It validates the content and merges it into the local forum database.
#
# 从一个由 forum_export_topic 创建的可移植tar包中导入话题。
# 它会验证内容并将其合并到本地的论坛数据库中。
#
# @param $1 - input_file (The path to the .tar.gz file to import / 要导入的 .tar.gz 文件路径)
forum_import_topic() {
    local input_file="$1"

    [ -f "$input_file" ] || error "错误: 导入文件未找到: $input_file (Error: Import file not found: $input_file)"
    
    msg "正在从 '$input_file' 导入话题..."
    info "Importing topic from '$input_file'..."

    # --- 步骤 1: 创建一个临时目录用于解压 ---
    local temp_import_dir
    temp_import_dir=$(mktemp -d -p "$BUILD_TMP_DIR_BASE" "forum_import.XXXXXX")

    # --- 步骤 2: 解压文件并进行基础验证 ---
    info "正在解压并验证压缩包... (Extracting and validating archive...)"
    if ! tar -C "$temp_import_dir" -xzf "$input_file"; then
        CORIUM_TEMP_ITEMS+=("$temp_import_dir")
        error "错误: 解压文件失败。文件可能已损坏或格式不正确。"
        error "Error: Failed to extract file. It may be corrupt or not a valid format."
    fi

    if [ ! -f "${temp_import_dir}/TOPIC_ID" ] || [ ! -d "${temp_import_dir}/manifests" ] || [ ! -d "${temp_import_dir}/objects" ]; then
        CORIUM_TEMP_ITEMS+=("$temp_import_dir")
        error "错误: 压缩包内容无效。缺少必要的文件或目录。"
        error "Error: Invalid archive content. Missing required files or directories."
    fi

    local topic_id
    topic_id=$(cat "${temp_import_dir}/TOPIC_ID")
    info "准备导入话题 (Preparing to import topic): $topic_id"
    
    # --- 步骤 3: 检查话题是否已存在，避免重复导入 ---
    local topic_exists
    topic_exists=$(db_query_safe "$FORUM_DB" \
        "SELECT COUNT(*) FROM topics WHERE id = %s;" \
        "$topic_id")
    if [ "$topic_exists" -gt 0 ]; then
         CORIUM_TEMP_ITEMS+=("$temp_import_dir")
        msg "话题 '$topic_id' 已存在于本地数据库中。跳过导入。"
        msg "Topic '$topic_id' already exists in the local database. Skipping import."
        return 0
    fi
    
    # --- 步骤 4: 验证所有文件哈希并复制文件 ---
    info "正在验证并合并文件... (Verifying and merging files...)"
    
    # 合并 manifests
    for manifest_file in "${temp_import_dir}/manifests"/*; do
        local hash
        hash=$(basename "$manifest_file" .json)
        local calculated_hash
        calculated_hash=$(calculate_hash "$manifest_file")

        if [ "$hash" != "$calculated_hash" ]; then
             CORIUM_TEMP_ITEMS+=("$temp_import_dir")
            error "错误: 清单文件 '$hash' 的内容哈希不匹配！文件可能已损坏。"
            error "Error: Content hash mismatch for manifest '$hash'! The file may be corrupt."
        fi
        
        # 如果本地不存在，则复制
        [ ! -f "${FORUM_MANIFESTS_DIR}/${hash}.json" ] && cp "$manifest_file" "${FORUM_MANIFESTS_DIR}/"
    done
    
    # 合并 objects
    for object_file in "${temp_import_dir}/objects"/*; do
        local hash
        hash=$(basename "$object_file")
        local calculated_hash
        calculated_hash=$(calculate_hash "$object_file")
        
        if [ "$hash" != "$calculated_hash" ]; then
             CORIUM_TEMP_ITEMS+=("$temp_import_dir")
            error "错误: 对象文件 '$hash' 的内容哈希不匹配！文件可能已损坏。"
            error "Error: Content hash mismatch for object '$hash'! The file may be corrupt."
        fi
        
        # 如果本地不存在，则复制
        [ ! -f "${FORUM_OBJECTS_DIR}/${hash}" ] && cp "$object_file" "${FORUM_OBJECTS_DIR}/"
    done

    # --- 步骤 5: 从 Manifests 文件中读取元数据并写入数据库 ---
    info "正在更新数据库索引... (Updating database index...)"
    
    # 导入主话题
    local topic_manifest_path="${FORUM_MANIFESTS_DIR}/${topic_id}.json"
    local manifest_content
    manifest_content=$(cat "$topic_manifest_path")
    
    local title author timestamp signature content_hash attachment_hash attachment_name
    # 使用 jq 安全地解析
    title=$(echo "$manifest_content" | jq -r .title)
    author=$(echo "$manifest_content" | jq -r .author)
    timestamp=$(echo "$manifest_content" | jq -r .timestamp)
    signature=$(echo "$manifest_content" | jq -r .signature)
    content_hash=$(echo "$manifest_content" | jq -r .content_hash)
    attachment_hash=$(echo "$manifest_content" | jq -r .attachment_hash)
    attachment_name=$(echo "$manifest_content" | jq -r .attachment_name)
    
    db_execute_safe "$FORUM_DB" \
        "INSERT OR IGNORE INTO topics (id, title, author, timestamp, signature, content_hash, attachment_hash, attachment_name) VALUES (%s, %s, %s, %d, %s, %s, %s, %s);" \
        "$topic_id" "$title" "$author" "$timestamp" "$signature" "$content_hash" "$attachment_hash" "$attachment_name"
    
    # 导入所有回帖
    for manifest_file in "${temp_import_dir}/manifests"/*; do
        local post_id
        post_id=$(basename "$manifest_file" .json)
        [ "$post_id" = "$topic_id" ] && continue # 跳过主话题
        
        manifest_content=$(cat "$manifest_file")
        local p_topic_id
        p_topic_id=$(echo "$manifest_content" | jq -r .topic_id)
        
        # 确保这个回帖属于我们正在导入的话题
        if [ "$p_topic_id" = "$topic_id" ]; then
            author=$(echo "$manifest_content" | jq -r .author)
            timestamp=$(echo "$manifest_content" | jq -r .timestamp)
            signature=$(echo "$manifest_content" | jq -r .signature)
            content_hash=$(echo "$manifest_content" | jq -r .content_hash)
            attachment_hash=$(echo "$manifest_content" | jq -r .attachment_hash)
            attachment_name=$(echo "$manifest_content" | jq -r .attachment_name)
            
            db_execute_safe "$FORUM_DB" \
                "INSERT OR IGNORE INTO posts (id, topic_id, author, timestamp, signature, content_hash, attachment_hash, attachment_name) VALUES (%s, %s, %s, %d, %s, %s, %s, %s);" \
                "$post_id" "$topic_id" "$author" "$timestamp" "$signature" "$content_hash" "$attachment_hash" "$attachment_name"
        fi
    done

    # --- 步骤 6: 清理 ---
     CORIUM_TEMP_ITEMS+=("$temp_import_dir")
    
    msg "话题 '$topic_id' 已成功导入。"
    msg "Topic '$topic_id' has been successfully imported."
}

_internal_get_pubkey_path() {
    # This is a minimal, internal-only function for the Python daemon to use.
    # It safely calls the existing robust function to get a pubkey path.
    # 这是一个极简的、仅供内部使用的函数，供Python守护进程调用。
    # 它安全地调用现有的健壮函数来获取公钥路径。
    _forum_get_author_pubkey "$1"
}

# This new function provides search capabilities for the decentralized forum.
forum_search() {
    local keyword="$1"
    local found=0
    
    msg "正在论坛中搜索: '\033[1;33m$keyword\033[0m' (Searching forum for: '$keyword')"
    
    # --- 1. Search in Topic Titles ---
    echo -e "\n\033[1m--- 匹配到的话题标题 (Matching Topic Titles) ---\033[0m"
    
    # 1. 调用集束化辅助函数，获取用于过滤已屏蔽用户的 SQL 子句。
    #    我们为 topics 表指定别名为 'T'，作者列为 'author'。
    # 1. Call the centralized helper to get the SQL clause for filtering blocked users.
    #    We specify the alias 'T' for the topics table and 'author' for the author column.
    local block_clause
    block_clause=$(_get_blocked_users_sql_clause "T" "author")
    
    # 2. 构建带有过滤逻辑的、安全的参数化查询。
    # 2. Construct the safe, parameterized query with the filtering logic.
    local query_topics="SELECT T.id, T.title FROM topics AS T WHERE T.title LIKE %s ${block_clause} ORDER BY T.timestamp DESC;"
    
    # 3. 执行查询。
    # 3. Execute the query.
    local topic_results
    topic_results=$(db_query_safe "$FORUM_DB" "$query_topics" "%${keyword}%")
        
    # Execute query and process results
    local topic_results
    topic_results=$(db_query_safe "$FORUM_DB" \
        "SELECT id, title FROM topics WHERE title LIKE %s ORDER BY timestamp DESC;" \
        "%${keyword}%")
    
    if [ -n "$topic_results" ]; then
        found=1
        while IFS='|' read -r id title; do
            [ -n "$id" ] || continue
            echo -e "\033[1;32m[TOPIC]\033[0m ID: $id"
            # Use grep to highlight the keyword, -i for case-insensitivity
            local highlighted_title
            highlighted_title=$(echo "$title" | grep -i --color=auto "$keyword" || echo "$title")
            echo -e "  Title: $highlighted_title"
        done <<< "$topic_results"
    else
        info "在话题标题中未找到匹配项。 (No matches found in topic titles.)"
    fi

    # --- 2. Search in Post Contents ---
    echo -e "\n\033[1m--- 匹配到的帖子内容 (Matching Post Contents) ---\033[0m"
    local posts_found_in_content=0
    
    # Get all posts and iterate through their content files
    local block_clause=$(_get_blocked_users_sql_clause "posts" "author")
    db_query_static "$FORUM_DB" "SELECT id, topic_id, content_hash FROM posts WHERE 1=1 ${block_clause} ORDER BY timestamp DESC;" | while IFS='|' read -r post_id topic_id content_hash; do
        [ -n "$post_id" ] || continue
        
        local content_path="${FORUM_OBJECTS_DIR}/${content_hash}"
        # Only search if the content file exists locally
        if [ -f "$content_path" ]; then
            # Use grep -q for a quick check without output, it's faster
            if grep -q -i "$keyword" "$content_path"; then
                found=1
                posts_found_in_content=1
                
                echo -e "\033[1;34m[POST]\033[0m ID: $post_id (in Topic: $topic_id)"
                # Now grep again with context and highlighting
                # -C 1 shows 1 line of context before and after the match
                grep -i --color=auto -C 1 "$keyword" "$content_path" | sed 's/^/  > /'
                echo # Add a newline for separation
            fi
        fi
    done

    if [ "$posts_found_in_content" -eq 0 ]; then
        info "在帖子内容中未找到匹配项。 (No matches found in post contents.)"
    fi

    # --- 3. Final Summary ---
    if [ "$found" -eq 0 ]; then
        echo
        warn "在整个论坛中未找到与 '$keyword' 相关的结果。 (No results found for '$keyword' in the entire forum.)"
    fi
}

# =======================================================
# --- SECTION 8.5: ADVANCED SOCIAL QUERIES (NEW)      ---
# --- 第8.5节: 高级社交查询 (新增)                    ---
# =======================================================

# Traverses the blockchain history to generate a human-readable event log for a group.
# 遍历区块链历史，为一个群组生成人类可读的事件日志。
#
# @param $1 - group_id (The ID of the group to generate history for / 要生成历史的群组ID)
corix_group_history() {
    local group_id="$1"
    
    # First, verify the group exists in our cache.
    # 首先，验证群组在我们的缓存中存在。
    local group_type
    group_type=$(_get_identity_type "$group_id")
    if [ "$group_type" != "group" ]; then
        error "Group with ID '${group_id}' not found. / 未找到ID为 '${group_id}' 的群组。"
        return 1
    fi
    
    local group_name
    group_name=$(_get_identity_nickname "$group_id")
    msg "History for Group: ${group_name} (${group_id:0:16}...) / 群组历史: ${group_name} (${group_id:0:16}...)"
    echo "--------------------------------------------------"

    # Query all transactions related to this group, ordered by their inclusion in blocks.
    # 查询所有与此群组相关的交易，并按它们被打包进区块的顺序排序。
    db_query_safe "$BLOCKCHAIN_DB" "
        SELECT T.type, T.public_key, T.data, B.timestamp
        FROM transactions AS T
        JOIN blocks AS B ON T.block_height = B.height
        WHERE
            (T.hash = %s AND T.type = 'group_create') OR
            (T.type IN ('group_admin_action', 'group_member_action', 'group_transfer_ownership', 'group_set_nickname', 'group_member_leave') AND json_extract(T.data, '$.group_id') = %s)
        ORDER BY T.block_height ASC, T.timestamp ASC;
    " "$group_id" "$group_id" | while IFS='|' read -r type pubkey data timestamp; do
        local event_time actor_hash actor_name event_desc
        event_time=$(date -d "@$timestamp" '+%Y-%m-%d %H:%M:%S')
        actor_hash=$(_internal_hash_text "$pubkey")
        actor_name=$(_get_identity_nickname "$actor_hash")

        echo -e "\033[1;33m[${event_time}]\033[0m"

        case "$type" in
            "group_create")
                event_desc="Group was created by ${actor_name}. / 群组由 ${actor_name} 创建。"
                ;;
            "group_admin_action")
                local action target_id target_name
                action=$(echo "$data" | jq -r .action)
                target_id=$(echo "$data" | jq -r .target_id)
                target_name=$(_get_identity_nickname "$target_id")
                case "$action" in
                    "add_admin") event_desc="${actor_name} promoted ${target_name} to Admin. / ${actor_name} 将 ${target_name} 提升为管理员。" ;;
                    "remove_admin") event_desc="${actor_name} demoted ${target_name} from Admin. / ${actor_name} 将 ${target_name} 从管理员中移除。" ;;
                esac
                ;;
            "group_member_action")
                local action target_id target_name
                action=$(echo "$data" | jq -r .action)
                target_id=$(echo "$data" | jq -r .target_id)
                target_name=$(_get_identity_nickname "$target_id")
                case "$action" in
                    "invite") event_desc="${actor_name} invited ${target_name} to the group. / ${actor_name} 邀请 ${target_name} 加入群组。" ;;
                    "kick") event_desc="${actor_name} kicked ${target_name} from the group. / ${actor_name} 将 ${target_name} 踢出群组。" ;;
                esac
                ;;
            "group_transfer_ownership")
                local new_owner_id new_owner_name
                new_owner_id=$(echo "$data" | jq -r .new_owner_id)
                new_owner_name=$(_get_identity_nickname "$new_owner_id")
                event_desc="${actor_name} transferred ownership to ${new_owner_name}. / ${actor_name} 将群主权限转让给 ${new_owner_name}。"
                ;;
            "group_set_nickname")
                local new_nickname
                new_nickname=$(echo "$data" | jq -r .new_nickname)
                event_desc="${actor_name} changed the group name to '${new_nickname}'. / ${actor_name} 将群组名称更改为 '${new_nickname}'。"
                ;;
            "group_member_leave")
                event_desc="${actor_name} left the group. / ${actor_name} 离开了群组。"
                ;;
        esac
        echo "  -> ${event_desc}"
        echo
    done
}

# --- REWRITTEN SECTION: Forum CLI ---
# --- REWRITTEN SECTION: Forum CLI (Bilingual & Complete) ---
# --- 重写部分: 论坛命令行界面 (双语 & 功能完整) ---
# =======================================================================================
# --- [V83 FINAL] corix_forum (最终、非侵入性、职责清晰版)                          ---
# --- [V83 FINAL] corix_forum (Final, Non-Invasive, Clean-Architecture)             ---
# =======================================================================================
corix_forum() {
    local sub_cmd="${1:-}"; shift || true
    
    case "$sub_cmd" in
        init)
            msg "Initializing or checking forum database... / 正在初始化或检查论坛数据库..."
            forum_init
            ;;
        sync)
            acquire_lock "network"; trap 'release_lock "network"' RETURN
            forum_sync
            ;;
        list)
            acquire_lock "network" "ro"; trap 'release_lock "network"' RETURN
            forum_list_topics
            ;;
        show)
            acquire_lock "network" "ro"; trap 'release_lock "network"' RETURN
            [ $# -lt 1 ] && error "Usage: corix forum show <Topic_ID> / 用法: corix forum show <话题ID>"
            forum_show_topic "$1"
            ;;
        search|se)
            acquire_lock "network" "ro"; trap 'release_lock "network"' RETURN
            [ $# -lt 1 ] && error "Usage: corix forum search <keyword> / 用法: corix forum search <关键词>"
            forum_search "$1"
            ;;
        get-attachment)
            acquire_lock "network"; trap 'release_lock "network"' RETURN
            forum_get_attachment "$@"
            ;;
        export|export-topic)
            acquire_lock "network" "ro"; trap 'release_lock "network"' RETURN
            [ $# -ne 2 ] && error "Usage: corix forum export <Topic_ID> <output_file.tar.gz> / 用法: corix forum export <话题ID> <输出文件名.tar.gz>"
            msg "Exporting topic '$1' to '$2'... / 正在导出话题 '$1' 到 '$2'..."
            forum_export_topic "$1" "$2"
            ;;
        import|import-topic)
            acquire_lock "network"; trap 'release_lock "network"' RETURN
            [ $# -ne 1 ] && error "Usage: corix forum import <input_file.tar.gz> / 用法: corix forum import <输入文件名.tar.gz>"
            msg "Importing topic from '$1'... / 正在从 '$1' 导入话题..."
            forum_import_topic "$1"
            ;;
        new-topic)
            acquire_lock "network"; trap 'release_lock "network"' RETURN

            local title="" body_text="" attach_file="" associate_group_id=""
            while [ $# -gt 0 ]; do
                case "$1" in
                    --title) title="$2"; shift 2 ;;
                    --body) body_text="$2"; shift 2 ;;
                    --attach) attach_file="$2"; shift 2 ;;
                    --associate-group) associate_group_id="$2"; shift 2 ;;
                    *) title="$1"; shift ;;
                esac
            done
            [ -z "$title" ] && { usage_forum; exit 1; }
            if [ -z "$body_text" ]; then
                info "未提供 --body，从标准输入读取... / No --body provided, reading from stdin..."
                body_text=$(cat)
            fi

            if [ -n "$associate_group_id" ]; then
                local author=$(_forum_get_identity)
                if ! _is_authorized_by_acl "$associate_group_id" "$author" "member"; then
                    error "权限不足：您不是群组 '${associate_group_id:0:16}...' 的成员。/ Permission denied: You are not a member of group '${associate_group_id:0:16}...'"
                    return 1
                fi
            fi
            
            forum_create_topic "$title" "$body_text" "$attach_file" "$associate_group_id"
            ;;

        post)
            acquire_lock "network"; trap 'release_lock "network"' RETURN
            
            local topic_id="$1"; shift
            local body_text="" attach_file=""
            while [ $# -gt 0 ]; do
                case "$1" in
                    --body) body_text="$2"; shift 2 ;;
                    --attach) attach_file="$2"; shift 2 ;;
                    *) error "post: Unknown parameter: $1 / 未知参数: $1" ;;
                esac
            done
            [ -z "$topic_id" ] && { usage_forum; exit 1; }
            if [ -z "$body_text" ]; then
                 info "未提供 --body，从标准输入读取... / No --body provided, reading from stdin..."
                 body_text=$(cat)
            fi

            local associated_group_id; associated_group_id=$(db_query_safe "$FORUM_DB" "SELECT associated_group_id FROM topics WHERE id = %s;" "$topic_id")
            if [ -z "$associated_group_id" ]; then
                local temp_manifest; temp_manifest=$(mktemp)
                CORIUM_TEMP_ITEMS+=("$temp_manifest")
                if _p2p_download_object "$topic_id" "$temp_manifest"; then
                    associated_group_id=$(jq -r '.associated_group_id // "NULL"' "$temp_manifest")
                fi
            fi
            
            if [ -n "$associated_group_id" ] && [ "$associated_group_id" != "NULL" ]; then
                local author=$(_forum_get_identity)
                info "此话题受群组 '${associated_group_id:0:16}...' 保护。正在检查成员资格... / This topic is protected by group '${associated_group_id:0:16}...'. Checking membership..."
                if ! _is_authorized_by_acl "$associated_group_id" "$author" "member"; then
                    error "权限不足：您不是该话题关联群组的成员，无法回复。/ Permission denied: You are not a member of the associated group and cannot reply."
                    return 1
                fi
            fi
            
            forum_create_post "$topic_id" "$body_text" "$attach_file"
            ;;

        set-policy)
            acquire_lock "network"; trap 'release_lock "network"' RETURN
            [ $# -lt 2 ] && { usage_forum; exit 1; }
            local topic_id="$1"; shift
            local associate_group_id="" disassociate=0
            while [ $# -gt 0 ]; do
                case "$1" in
                    --associate-group) associate_group_id="$2"; shift 2 ;;
                    --disassociate-group) disassociate=1; shift ;;
                    *) error "set-policy: Unknown option '$1' / 未知选项 '$1'";;
                esac
            done
            
            local author_id; author_id=$(db_query_safe "$FORUM_DB" "SELECT author FROM topics WHERE id = %s;" "$topic_id")
            [ -z "$author_id" ] && { error "话题未找到。请先运行 'sync'。 / Topic not found. Please run 'sync' first."; return 1; }
            
            local my_id=$(_forum_get_identity)
            if [ "$my_id" != "$author_id" ]; then
                 error "权限不足：只有话题作者才能修改策略。/ Permission denied: Only the topic author can modify the policy."
                 return 1
            fi

            local temp_manifest; temp_manifest=$(mktemp); CORIUM_TEMP_ITEMS+=("$temp_manifest")
            _p2p_download_object "$topic_id" "$temp_manifest" || { error "无法获取旧话题的 manifest。/ Failed to fetch old topic's manifest."; return 1; }
            
            local old_manifest_unsigned; old_manifest_unsigned=$(cat "$temp_manifest" | jq 'del(.signature)')
            local title; title=$(echo "$old_manifest_unsigned" | jq -r .title)
            local content_hash; content_hash=$(echo "$old_manifest_unsigned" | jq -r .content_hash)
            local temp_content; temp_content=$(mktemp); CORIUM_TEMP_ITEMS+=("$temp_content")
            _p2p_download_object "$content_hash" "$temp_content" || { error "无法获取旧话题的内容。/ Failed to fetch old topic's content."; return 1; }
            local body_text; body_text=$(cat "$temp_content")
            
            local attach_hash; attach_hash=$(echo "$old_manifest_unsigned" | jq -r .attachment_hash)
            local temp_attach=""
            if [ -n "$attach_hash" ] && [ "$attach_hash" != "null" ]; then
                temp_attach=$(mktemp); CORIUM_TEMP_ITEMS+=("$temp_attach")
                _p2p_download_object "$attach_hash" "$temp_attach" || { error "无法获取旧话题的附件。/ Failed to fetch old topic's attachment."; return 1; }
            fi
            
            msg "正在重新发布话题以更新策略... 这将创建一个新的话题 ID。/ Re-publishing topic to update policy... This will create a NEW topic ID."
            local new_topic_id=""
            if [ "$disassociate" -eq 1 ]; then
                new_topic_id=$(forum_create_topic "$title" "$body_text" "$temp_attach" "")
            else
                new_topic_id=$(forum_create_topic "$title" "$body_text" "$temp_attach" "$associate_group_id")
            fi
            
            info "策略更新完成。新话题ID / Policy update complete. New Topic ID: ${new_topic_id}"
            
            # --- 自动迁移通知 ---
            # --- Automatic Migration Notification ---
            local migration_notice="--- (此话题已被作者迁移 / This topic has been migrated by the author) ---\n新话题ID / New Topic ID: ${new_topic_id}"
            warn "正在旧话题下发布迁移通知... / Posting a migration notice in the old topic..."
            forum_create_post "$topic_id" "$migration_notice" ""
            ;;

        *)
            usage_forum
            ;;
    esac
}

usage_forum(){
            cat <<EOF
corix Forum System - Usage: corix forum <command> [arguments...]
corix 论坛系统 - 用法: corix forum <命令> [参数...]

--------------------------------------------------------------------------------
Core Commands (核心命令):
--------------------------------------------------------------------------------
  sync                Sync new topics and posts from the P2P network.
                      从P2P网络同步新的话题和帖子。

  list                List all locally known topics.
                      列出所有本地已知的话题。

  show <Topic_ID>     Show the full content, replies, and attachment info for a topic.
                      显示一个话题的完整内容、回复和附件信息。

  search <keyword>    Search topic titles and post contents.
                      在话题标题与帖子内容中进行搜索。
--------------------------------------------------------------------------------
Publishing Commands (发布命令):
--------------------------------------------------------------------------------
  new-topic --title "Title" [--body "Content"] [--attach /path/to/file]
                      Publish a new topic. If --body is not provided, reads from standard input.
                      发布一个新话题。如果 --body 未提供，则从标准输入读取。

  post <Topic_ID> --body "Content" [--attach /path/to/file]
                      Reply to an existing topic.
                      回复一个已有的话题。

--------------------------------------------------------------------------------
File & Data Operations (文件与数据操作):
--------------------------------------------------------------------------------
  get-attachment <object_hash> <output_filename>
                      Download an attachment or post body from the network. The hash can be found in the 'show' command's output.
                      从网络下载一个附件或帖子正文。哈希值可以从 'show' 命令的输出中获取。

  export <Topic_ID> <file.tar.gz>
                      Export a full topic with all its posts and attachments to a single portable archive (.tar.gz).
                      将一个完整的话题及其所有帖子和附件，导出一个单一的可移植压缩包 (.tar.gz) 中。

  import <file.tar.gz>
                      Import a topic from a portable archive (.tar.gz).
                      从一个可移植的压缩包 (.tar.gz) 导入话题。


--------------------------------------------------------------------------------
Management Commands (管理命令):
--------------------------------------------------------------------------------
  init                Initialize or check the forum database.
                      初始化或检查论坛数据库。
                      
  set-policy <topic_id> --associate-group <group_id>
                      (Topic author only) Associate an existing topic with a group.
                      ((仅限话题作者) 将一个已存在的话题关联到一个群组)
  set-policy <topic_id> --disassociate-group
                      (Topic author/Group owner only) Remove the group association.
                      ((仅限话题作者/群组所有者) 移除群组关联)
EOF
}

# =======================================================================================
# --- SECTION 5: DATABASE INITIALIZATION (V62.1 - FINAL BASED ON V60)                 ---
# --- 第5节: 数据库初始化 (V62.1版 - 基于 V60 的最终版)                               ---
# =======================================================================================

# --- [新增] 检查并确认新启用的 Unboxed Agents ---
# --- [NEW] Check for and confirm newly enabled Unboxed Agents ---
_check_for_unconfirmed_unboxed_agents() {
    local enabled_mods_file="${ETC_CORIUM_DIR}/mods_enabled.conf"
    local confirmation_log="${VAR_LIB_CORIUM_DIR}/.unboxed_confirmations"
    
    [ ! -f "$enabled_mods_file" ] && return 0
    touch "$confirmation_log"

    local needs_confirmation=0
    local -a unconfirmed_agents=()

    # 遍历所有启用的 Mod
    # Iterate through all enabled Mods
    while IFS= read -r pkg_id || [[ -n "$pkg_id" ]]; do
        [[ "$pkg_id" =~ ^# || -z "$pkg_id" ]] && continue
        
        # 检查是否是 Unboxed Agent
        # Check if it is an Unboxed Agent
        local is_unboxed=$(_get_mod_metadata_value "$pkg_id" "unboxed_execution")
        if [[ "$is_unboxed" != "true" ]]; then
            continue
        fi

        # 检查是否已经被确认过
        # Check if it has already been confirmed
        if ! grep -Fxq "$pkg_id" "$confirmation_log"; then
            needs_confirmation=1
            unconfirmed_agents+=("$pkg_id")
        fi
    done < "$enabled_mods_file"

    if [ "$needs_confirmation" -eq 1 ]; then
        echo
        _apply_theme "error" "!!! 危险操作确认 / DANGEROUS ACTION CONFIRMATION !!!"
        _apply_theme "warn" "----------------------------------------------------------------"
        _apply_theme "warn" "您已启用一个或多个 Unboxed Agents。这些 Agents 将在**沙箱之外**运行，"
        _apply_theme "warn" "拥有与 Corium 核心同等的权限，可能危害您的系统和网络安全。"
        _apply_theme "warn" "You have enabled one or more Unboxed Agents. These will run OUTSIDE"
        _apply_theme "warn" "the secure sandbox with permissions equal to the Corium core, potentially"
        _apply_theme "warn" "harming your system and network security."
        _apply_theme "warn" "----------------------------------------------------------------"
        
        for agent_id in "${unconfirmed_agents[@]}"; do
            echo
            _apply_theme "primary" "要确认启用 Unboxed Agent '${agent_id}',"
            _apply_theme "primary" "请输入其完整的软件包 ID 并按 Enter 键："
            _apply_theme "primary" "To confirm enabling the Unboxed Agent '${agent_id}',"
            _apply_theme "primary" "please type its full package ID and press Enter:"
            
            local user_input=""
            read -r user_input
            
            if [ "$user_input" = "$agent_id" ]; then
                _apply_theme "success" "  -> 已确认 / Confirmed: ${agent_id}"
                echo "$agent_id" >> "$confirmation_log"
            else
                _apply_theme "error" "  -> 输入不匹配。操作已中止。 / Input mismatch. Operation aborted."
                _apply_theme "error" "  -> ${agent_id} 将保持未激活状态。 / ${agent_id} will remain inactive."
                # 从 enabled_mods.conf 中注释掉这个未确认的 Agent
                # Comment out the unconfirmed Agent from enabled_mods.conf
                sed -i "s|^${agent_id}$|# DISABLED-UNCONFIRMED: ${agent_id}|" "$enabled_mods_file"
                exit 1 # 强制中止当前 Corium 命令
            fi
        done
        echo
        _apply_theme "success" "所有 Unboxed Agents 已确认。正在继续执行 '${main_command}'... / All Unboxed Agents confirmed. Continuing with '${main_command}'..."
    fi
}

# =======================================================================================
# --- [V80 Template Install] _internal_install_template (模板包专用安装器)        ---
# --- [V80 Template Install] _internal_install_template (Specialized Template Installer) ---
# =======================================================================================
# 此函数是一个轻量级的、无依赖的安装器，专门用于应用模板包。
# 它直接操作二进制包，不涉及构建、依赖解析或仓库同步。
# This is a lightweight, dependency-free installer specifically for App Template packages.
# It operates directly on a binary package, without involving building, dependency resolution, or repo syncing.
_internal_install_template() {
    local template_pkg_id="$1"
    local binary_pkg_path="$2" # 已经下载并验证过的二进制包的路径

    get_pkg_id_parts "$template_pkg_id"
    local pkg_name="${PKG_CATEGORY}/${PKG_NAME}"
    local pkg_slot="$PKG_SLOT"

    info "[模板安装器] 正在为 '${template_pkg_id}' 注册... / [Template Installer] Registering '${template_pkg_id}'..."

    local temp_extract_dir; temp_extract_dir=$(mktemp -d -p "$BUILD_TMP_DIR_BASE" "template-install.XXXXXX")
    CORIUM_TEMP_ITEMS+=("$temp_extract_dir")

    _validate_archive "$binary_pkg_path" || return 1
    if [[ "$binary_pkg_path" =~ \.zst$ ]]; then
        tar -I zstd -xf "$binary_pkg_path" -C "$temp_extract_dir" || return 1
    else
        tar -xf "$binary_pkg_path" -C "$temp_extract_dir" || return 1
    fi

    local build_file_in_pkg="${temp_extract_dir}/.corium/template.build"
    local files_manifest_in_pkg="${temp_extract_dir}/.corium/manifest.files"

    if [ ! -f "$build_file_in_pkg" ] || [ ! -f "$files_manifest_in_pkg" ]; then
        error "[模板安装器] 模板包 '${template_pkg_id}' 格式无效：缺少内嵌的元数据。 / [Template Installer] Template package '${template_pkg_id}' is malformed: missing embedded metadata."
        return 1
    fi

    local meta pkg_ver; meta=$(_parse_build_file "$build_file_in_pkg") || return 1; pkg_ver=$(echo "$meta" | grep "^pkgver=" | cut -d= -f2)

    if [ -z "$pkg_ver" ]; then
        error "[模板安装器] 无法从模板包中解析出版本号。/ [Template Installer] Could not parse version from the template package."
        return 1
    fi

    local template_storage_dir="${VAR_LIB_CORIUM_DIR}/app_templates/${pkg_name//\//_}/${pkg_ver}"
    if [ "${CORIUM_REPLAY:-0}" != 1 ]; then
        if [ -z "$CURRENT_TRANSACTION_BACKUP_PATH" ]; then
            [ -f "$WORLD_FILE" ] || : > "$WORLD_FILE" || return 1
            _begin_transaction "$INSTALLED_DB" || return 1
        fi
        local staging_manifest; staging_manifest=$(mktemp) || return 1
        CORIUM_TEMP_ITEMS+=("$staging_manifest")
        "${PYTHON_CMD}" - "$temp_extract_dir" "$template_storage_dir" "$CORIUM_ROOT" "$staging_manifest" <<'PY_TEMPLATE_FILES'
from pathlib import Path
import sys
source,target,root,output=map(Path,sys.argv[1:]);root=root.resolve()
entries=[target]+[target/path.relative_to(source) for path in sorted(source.rglob('*'))]
with output.open('w') as f:
    for path in entries:
        name=str(path.relative_to(root))
        if '\n' in name: raise ValueError('Invalid template file path')
        f.write(name+'\n')
PY_TEMPLATE_FILES
        [ $? -eq 0 ] || return 1
        _transaction_stage_files "$staging_manifest" || return 1
    fi
    mkdir -p "$template_storage_dir" || return 1
    cp -aT "$temp_extract_dir/" "$template_storage_dir/" || return 1

    local final_manifest; final_manifest=$(mktemp)
    CORIUM_TEMP_ITEMS+=("$final_manifest")
    sed "s|^|${template_storage_dir#${CORIUM_ROOT%/}/}/|" "$files_manifest_in_pkg" > "$final_manifest"

    _internal_db_register_minimal "$pkg_name" "$pkg_ver" "$pkg_slot" "$final_manifest" "$build_file_in_pkg" || return 1
    
    msg "[模板安装器] 应用模板 '${template_pkg_id}' v${pkg_ver} 已成功安装并激活。/ [Template Installer] App Template '${template_pkg_id}' v${pkg_ver} has been successfully installed and activated."
}

# --- [V80] 一个极简的、内部使用的数据库注册函数 ---
# --- [V80] A minimal, internal-use database registration function ---
_internal_db_register_minimal() {
    local pkg_name="$1"
    local pkg_ver="$2" 
    local pkg_slot="$3"
    local files_manifest="$4"
    local build_file_path="$5"

    local pkg_dir; pkg_dir=$(db_get_pkg_dir "$pkg_name" "$pkg_slot")
    
    mkdir -p "$pkg_dir"
    echo "$pkg_ver" > "$pkg_dir/version"
    echo "$pkg_name" > "$pkg_dir/name"
    echo "$pkg_slot" > "$pkg_dir/slot"
    # 模板包没有运行时依赖
    # Template packages have no runtime dependencies
    : > "$pkg_dir/dependencies"
    # 将 .build 文件和清单复制到数据库条目中，以便 corix info 等命令可以工作
    # Copy the .build file and manifest to the db entry so commands like corix info can work
    cp "$build_file_path" "$pkg_dir/build_file"
    cp "$files_manifest" "$pkg_dir/files"
    date -u --rfc-3339=seconds > "$pkg_dir/install_date"
}



# =======================================================================================
# --- [V79 Gen3 FINAL] _handle_dynamic_application_transaction (完整生产版)         ---
# --- [V79 Gen3 FINAL] _handle_dynamic_application_transaction (Full Production)    ---
# =======================================================================================
# 此函数是 Gen3 应用的状态转换调度中心。它处理所有未被 Corium 核心硬编码的交易类型。
# 它的职责包括：查找、验证、下载并安全地执行相应的应用模板逻辑。
#
# This function is the state transition dispatch center for Gen3 applications. It handles all
# transaction types not hardcoded into the Corium core. Its responsibilities include:
# finding, verifying, downloading, and securely executing the corresponding App Template logic.
_handle_dynamic_application_transaction() {
    local tx_type="$1"
    local tx_payload="$2"
    local tx_hash="$3"
    local sender_id="$4"
    local height="$5"

    # 1. 在链上注册中心精确地查找能够处理此交易类型的模板
    # 1. Precisely look up the registry for the template that can handle this transaction type
    local template_info
    # 使用 SQLite 的 json_each 功能来高效查询 JSON 数组
    # Use SQLite's json_each function to efficiently query the JSON array
    template_info=$(db_query_safe "$BLOCKCHAIN_DB" \
        "SELECT T.pkg_id, T.package_hash, T.developer_id FROM active_app_templates AS T, json_each(T.handles_tx_types) AS J WHERE J.value = %s;" \
        "$tx_type")

    if [ -z "$template_info" ]; then
        # --- 如果链上没有任何模板声明能处理此交易，则触发“未知交易”的用户确认流程 ---
        # --- If no template on-chain claims to handle this, trigger the "Unknown Transaction" user confirmation flow ---
        warn "区块 ${height} 包含一个您的客户端无法识别的交易类型: '${tx_type}'。/ Block ${height} contains a transaction type your client cannot recognize: '${tx_type}'."
        warn "在当前链的共识中，没有任何已激活的应用模板声明要处理它。这可能是无效交易或来自未来版本的交易。/ No activated App Template in this chain's consensus claims to handle it. This might be an invalid transaction or one from a future version."
        
        # 为了保持状态同步，用户必须选择是忽略它还是中止
        # To maintain state sync, the user must choose to ignore it or abort
        local user_choice_key="unknown_tx_policy_${tx_type}"
        local cached_choice="${CORIUM_SESSION_CACHE[$user_choice_key]:-}"

        if [ -n "$cached_choice" ]; then
            if [ "$cached_choice" = "ignore" ]; then
                info "根据会话策略，已自动忽略此类型的未知交易。/ Automatically ignoring this type of unknown transaction based on session policy."
                return 0
            fi
        else
            read -rp "您希望如何处理？[I]gnore (忽略此交易并继续), [A]lways Ignore (本次会话中总是忽略此类型), [Q]uit (中止同步): / How to proceed? [I]gnore this tx and continue, [A]lways Ignore this type for the session, [Q]uit sync: " choice || return 1
            case "$choice" in
                [aA]*)
                    CORIUM_SESSION_CACHE[$user_choice_key]="ignore"
                    info "将在本次会话中总是忽略 '${tx_type}' 类型的交易。/ Will always ignore transactions of type '${tx_type}' for this session."
                    return 0
                    ;;
                [qQ]*)
                    error "用户选择中止同步。/ Sync aborted by user."
                    exit 1 # 这是一个致命错误，因为无法达成状态一致
                    ;;
                *) # 默认行为是忽略一次
                    info "已忽略未知交易 '${tx_type}'。 / Ignored unknown transaction '${tx_type}'."
                    return 0
                    ;;
            esac
        fi
        return 0
    fi

    local template_pkg_id template_p2p_hash developer_id
    IFS='|' read -r template_pkg_id template_p2p_hash developer_id <<< "$template_info"

    # 2. 检查本地是否已安装该模板包
    if ! db_is_installed "$template_pkg_id"; then
        info "需要安装新的应用模板 '${template_pkg_id}' 才能处理交易 '${tx_type}'。/ New App Template '${template_pkg_id}' is required to process transaction '${tx_type}'."
        
        # 3. 下载并验证模板包
        # 3. Download and verify the template package
        local temp_pkg_path; temp_pkg_path=$(mktemp)
        CORIUM_TEMP_ITEMS+=("$temp_pkg_path") # 注册以便自动清理

        info "正在从P2P网络下载应用模板 (哈希: ${template_p2p_hash:0:16})... / Downloading App Template from P2P network (hash: ${template_p2p_hash:0:16})..."
        if ! _p2p_download_object "$template_p2p_hash" "$temp_pkg_path"; then
            error "无法下载应用模板包 '${template_pkg_id}'。状态转换失败。/ Failed to download App Template package '${template_pkg_id}'. State transition failed."
            exit 1 # 致命错误
        fi
        
        # 4. GPG 签名验证
        # 4. GPG Signature Verification
        local sig_file="${temp_pkg_path}.sig.gpg"
        # 签名文件的哈希约定为 "包哈希.sig"
        # The signature file's hash is conventionally "package_hash.sig"
        _p2p_download_object "${template_p2p_hash}.sig" "$sig_file" >/dev/null 2>&1 

        if [ -f "$sig_file" ]; then
            info "正在验证模板包的 GPG 签名... / Verifying GPG signature of the template package..."
            local validating_zone; validating_zone=$(_verify_gpg_signature "$temp_pkg_path" "$sig_file")
            if [ $? -ne 0 ]; then
                error "应用模板包 GPG 签名无效！为了您的安全，将不会执行此交易。/ App Template package has an INVALID GPG signature! For your security, this transaction will not be executed."
                exit 1 # 致命错误
            fi
            info "GPG 签名有效，由信任区 '${validating_zone}' 签署。/ GPG signature is valid, signed by Trust Zone '${validating_zone}'."
        else
            warn "未找到应用模板包的 GPG 签名。正在继续，但建议谨慎。/ No GPG signature found for the App Template package. Proceeding with caution is advised."
        fi
        
        # 5. 【已替换】调用专门的、自包含的模板安装器
        # 5. [REPLACED] Call the dedicated, self-contained template installer
        if ! _internal_install_template "$template_pkg_id" "$temp_pkg_path"; then
             error "应用模板 '${template_pkg_id}' 安装失败。无法继续。/ Failed to install App Template '${template_pkg_id}'. Cannot proceed."
             exit 1
        fi
        
        # 清理下载的临时文件
        # Clean up downloaded temporary files
        rm -f "$temp_pkg_path" "$sig_file" 2>/dev/null
    fi
    
    # 6. 调用内部执行器
    # 6. Call the internal executor
    info "正在动态执行 '${tx_type}' 的状态转换逻辑... / Dynamically executing state transition logic for '${tx_type}'..."
    # 将完整的交易对象（包括type, data, sender等）编码后传递
    # Encode and pass the full transaction object (including type, data, sender, etc.)
    local full_tx_obj; full_tx_obj=$(jq -n \
        --arg hash "$tx_hash" \
        --arg type "$tx_type" \
        --argjson payload "$tx_payload" \
        --arg sender "$sender_id" \
        --argjson height "$height" \
        '{hash: $hash, type: $type, data: $payload, sender_id: $sender, block_height: $height}')

    local full_tx_obj_b64; full_tx_obj_b64=$(echo -n "$full_tx_obj" | base64 -w0)

    # 我们将脚本自身的路径传递给子进程，以便它能被递归调用
    # We pass the script's own path to the child process so it can be recursively called
    if ! "$SCRIPT_PATH" _internal_run_state_logic "$template_pkg_id" "$full_tx_obj_b64" "$FORUM_DB"; then
        local exit_code=$?
        if [ "$exit_code" -eq 111 ]; then
            error "状态转换失败：在模板包 '${template_pkg_id}' 中未找到 'state_logic.py' 或其处理函数。/ State transition failed: 'state_logic.py' or its handler function not found in template package '${template_pkg_id}'."
        elif [ "$exit_code" -eq 112 ]; then
            error "状态转换失败：模板 '${template_pkg_id}' 的逻辑脚本执行时返回了错误。/ State transition failed: Logic script for template '${template_pkg_id}' returned an error during execution."
        else
            error "状态转换失败：未知的沙箱执行错误 (代码: ${exit_code})。/ State transition failed: Unknown sandbox execution error (code: ${exit_code})."
        fi
        # 这是致命的，因为状态无法达成一致
        # This is fatal, as state cannot be agreed upon
        exit 1
    fi

    info "动态状态转换成功。/ Dynamic state transition successful."
}

# =======================================================================================
# --- [V75 Sign-Svc] _check_for_unconfirmed_auto_signers() - 自动签名权限防火墙 ---
# --- [V75 Sign-Svc] _check_for_unconfirmed_auto_signers() - Auto-Sign Permission Firewall ---
# =======================================================================================
_check_for_unconfirmed_auto_signers() {
    local acl_file="${ETC_CORIUM_DIR}/local_acl.conf"
    local confirmation_log="${VAR_LIB_CORIUM_DIR}/.auto_signer_confirmations"
    
    [ ! -f "$acl_file" ] && return 0
    touch "$confirmation_log"

    # 查找所有被授予 allow_auto 权限但尚未被确认的 Mod
    # Find all Mods granted 'allow_auto' permission that have not yet been confirmed
    local unconfirmed_signers
    unconfirmed_signers=$(awk -v conf_log="$confirmation_log" '
        BEGIN { in_section=0; mod_name="" }
        /^\[mod:(.+)\]$/ { in_section=1; mod_name=gensub(/^\[mod:(.+)\]$/, "\\1", 1); next }
        /\[.*\]/ { in_section=0 }
        in_section && $1 == "api.request_signature" && $3 == "allow_auto" {
            # 检查 mod_name 是否在确认日志中
            # Check if the mod_name is in the confirmation log
            if (system("grep -Fxq \"" mod_name "\" \"" conf_log "\"") != 0) {
                print mod_name
            }
        }
    ' "$acl_file")

    if [ -n "$unconfirmed_signers" ]; then
        echo
        _apply_theme "error" "!!! 极度危险操作确认 / EXTREMELY DANGEROUS ACTION CONFIRMATION !!!"
        _apply_theme "warn" "----------------------------------------------------------------"
        _apply_theme "warn" "您已为一个或多个 Mod/DApp 授予了【自动签名】权限。这意味着它们"
        _apply_theme "warn" "将可以在**无需您每次确认**的情况下，代表您创建交易、转移资产、投票等。"
        _apply_theme "warn" "You have granted [AUTOMATIC SIGNING] permission to one or more Mods/DApps."
        _apply_theme "warn" "This means they can create transactions, transfer assets, vote, etc. on your"
        _apply_theme "warn" "behalf **WITHOUT asking for your confirmation each time**."
        _apply_theme "warn" "----------------------------------------------------------------"
        
        for signer_id in $unconfirmed_signers; do
            echo
            _apply_theme "primary" "要确认授予 '${signer_id}' 自动签名权限,"
            _apply_theme "primary" "请输入其完整的 ID 并按 Enter 键："
            _apply_theme "primary" "To confirm granting automatic signing permission to '${signer_id}',"
            _apply_theme "primary" "please type its full ID and press Enter:"
            
            local user_input=""
            read -r user_input
            
            if [ "$user_input" = "$signer_id" ]; then
                _apply_theme "success" "  -> 已确认 / Confirmed: ${signer_id}"
                echo "$signer_id" >> "$confirmation_log"
            else
                _apply_theme "error" "  -> 输入不匹配。操作已中止。 / Input mismatch. Operation aborted."
                _apply_theme "error" "  -> ${signer_id} 的自动签名权限将保持未激活状态。 / Automatic signing for ${signer_id} will remain inactive."
                # 我们不修改用户的 ACL 文件，只记录确认状态。未确认就等于拒绝。
                # We don't modify the user's ACL file, just log confirmation. Unconfirmed equals denied.
                exit 1
            fi
        done
        echo
        _apply_theme "success" "所有自动签名权限已确认。/ All automatic signing permissions confirmed."
    fi
}

# --- [最终版][V55.5] 拆分出的 DHT 数据库初始化函数 ---
# --- [FINAL][V55.5] Split-out initialization function for the DHT database ---
_init_dht_db() {
    local DHT_DB="${1:-$DHT_DB}"
    # 包含了您原始设计中的所有 DHT 相关表
    # Includes all DHT-related tables from your original design
    db_init "$DHT_DB" "
    CREATE TABLE IF NOT EXISTS nodes (
        id TEXT PRIMARY KEY,
        address_type TEXT NOT NULL,
        address TEXT NOT NULL,
        port INTEGER,
        capabilities TEXT,
        last_seen INTEGER NOT NULL,
        distance INTEGER NOT NULL,
        trust_tier INTEGER NOT NULL DEFAULT 3 -- 3:Guest, 2:Member, 1:Reputable
    );
    CREATE UNIQUE INDEX IF NOT EXISTS idx_nodes_address ON nodes(address_type, address, port);
    CREATE INDEX IF NOT EXISTS idx_nodes_distance ON nodes(distance);
    
    CREATE TABLE IF NOT EXISTS chunks (
        hash TEXT PRIMARY KEY, size INTEGER, nodes TEXT, last_updated INTEGER
    );
    CREATE TABLE IF NOT EXISTS local_chunks (
        hash TEXT PRIMARY KEY, file_path TEXT NOT NULL, offset INTEGER NOT NULL, size INTEGER NOT NULL
    );
    CREATE TABLE IF NOT EXISTS network_latency_map (
        source_node_id TEXT NOT NULL,
        target_node_id TEXT NOT NULL,
        latency_ms INTEGER NOT NULL,
        last_updated_block INTEGER NOT NULL,
        PRIMARY KEY (source_node_id, target_node_id)
    );
    CREATE TABLE IF NOT EXISTS distrusted_peers (
    blocker_id TEXT NOT NULL,       -- 拉黑的发起者 (The ID of the one who blocks)
    blocked_id TEXT NOT NULL,       -- 被拉黑者 (The ID of the one being blocked)
    distrust_until INTEGER NOT NULL,
    grievance_token_used INTEGER NOT NULL DEFAULT 0, -- 0 = 未使用, 1 = 已使用 (0 = unused, 1 = used)
    PRIMARY KEY (blocker_id, blocked_id)
    );
    -- [NEW] 用于 PoUW 验证请求的数据库驱动的速率限制表
    -- [NEW] Database-driven rate-limiting table for PoUW validation requests
    CREATE TABLE IF NOT EXISTS pouw_rate_limit_log (
        requester_id TEXT NOT NULL,
        timestamp INTEGER NOT NULL
    );
    CREATE INDEX IF NOT EXISTS idx_pouw_rate_limit ON pouw_rate_limit_log(requester_id, timestamp);

    -- [NEW] 用于节点活跃度跟踪的表 (替代占位符)
    -- [NEW] Table for peer activity tracking (replaces placeholder)
    CREATE TABLE IF NOT EXISTS peer_activity (
        node_id TEXT PRIMARY KEY,
        last_successful_ping_out INTEGER, -- The last time we successfully pinged them
        last_successful_ping_in INTEGER,  -- The last time they successfully pinged us
        last_seen_active INTEGER          -- A composite timestamp of their last known activity
    );
    "
}

# =======================================================================================
# --- [V82 FINAL] _init_blockchain_db (支持 IBC 与 On-Chain Agents)                   ---
# --- [V82 FINAL] _init_blockchain_db (with IBC & On-Chain Agent Support)           ---
# =======================================================================================
_init_blockchain_db() {
    local BLOCKCHAIN_DB="${1:-$BLOCKCHAIN_DB}"
    db_init "$BLOCKCHAIN_DB" "
    -- 核心区块与交易表 (Core Block & Transaction Tables)
    CREATE TABLE IF NOT EXISTS blocks (
        height INTEGER PRIMARY KEY,
        hash TEXT UNIQUE NOT NULL,
        previous_hash TEXT NOT NULL,
        timestamp INTEGER NOT NULL,
        validator TEXT NOT NULL,
        signature TEXT NOT NULL,
        transactions TEXT NOT NULL,
        total_weight INTEGER DEFAULT 0
    );
    CREATE TABLE IF NOT EXISTS transactions (
        hash TEXT PRIMARY KEY,
        type TEXT NOT NULL,
        data TEXT NOT NULL,
        signature TEXT NOT NULL,
        public_key TEXT NOT NULL,
        timestamp INTEGER NOT NULL,
        block_height INTEGER
    );
    CREATE INDEX IF NOT EXISTS transactions_block_height_hash ON transactions(block_height, hash);
    CREATE TABLE IF NOT EXISTS block_work (
        hash TEXT PRIMARY KEY,
        proof TEXT NOT NULL
    );
    
    -- 链状态表 (Chain State Table)
    CREATE TABLE IF NOT EXISTS chain_state (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL
    );
    
    -- 验证者与权益表 (Validator & Stake Tables)
    -- [MODIFIED] 增加了用于惩罚机制的状态字段
    -- [MODIFIED] Added status fields for the slashing mechanism
    CREATE TABLE IF NOT EXISTS validators (
        public_key TEXT PRIMARY KEY,
        public_key_hash TEXT UNIQUE,
        stake INTEGER NOT NULL,
        last_block INTEGER DEFAULT 0,
        status TEXT NOT NULL DEFAULT 'active', -- 'active' 或 'jailed' / 'active' or 'jailed'
        missed_blocks_counter INTEGER NOT NULL DEFAULT 0,
        jailed_until_height INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS idx_validators_hash ON validators(public_key_hash);

    -- [NEW] 可治理的系统级参数表
    -- [NEW] Table for governable system-level parameters
    CREATE TABLE IF NOT EXISTS system_params (
        param_key TEXT PRIMARY KEY,
        param_value TEXT NOT NULL
    );

    -- [NEW] 插入所有新功能的默认治理参数
    -- [NEW] Insert default governance parameters for all new features
    INSERT OR IGNORE INTO system_params (param_key, param_value) VALUES
        ('pouw_points_per_day_uptime', '100'),
        ('pouw_validation_peers_required', '3'),
        ('pouw_report_validity_window_blocks', '100'),
        ('slashing_downtime_threshold_blocks', '50'),
        ('slashing_downtime_penalty_percent', '1'),
        ('slashing_double_sign_penalty_percent', '50'),
        ('slashing_jailing_duration_blocks', '1000'),
        ('slashing_report_reward_percent', '5'),
        ('trust_genesis_period_blocks', '10000'),
        ('trust_reputable_tier_threshold', '1000'),
        -- [NEW] 为 PoUW 验证请求添加可治理的速率限制参数 (每分钟请求数)
        -- [NEW] Add governable rate limit parameter for PoUW validation requests (requests per minute)
        ('pouw_validation_request_rate_limit_per_minute', '5');
        

    -- [NEW] “有用功证明” 贡献分总账本
    -- [NEW] General ledger for 'Proof of Useful Work' contribution points
    CREATE TABLE IF NOT EXISTS contribution_ledger (
        node_id TEXT PRIMARY KEY,
        points INTEGER NOT NULL DEFAULT 0,
        last_updated_height INTEGER NOT NULL
    );

    -- [NEW] PoUW 报告的最终链上记录
    -- [NEW] Final on-chain records for PoUW reports
    CREATE TABLE IF NOT EXISTS pouw_reports (
        tx_hash TEXT PRIMARY KEY,
        reporter_id TEXT NOT NULL,
        reported_node_id TEXT NOT NULL,
        proof_payload TEXT NOT NULL,
        peer_signatures TEXT NOT NULL, -- Stored as a JSON array
        reward_amount INTEGER NOT NULL,
        block_height INTEGER NOT NULL
    );

    -- [NEW] PoUW 验证日志，用于防止重放攻击
    -- [NEW] PoUW validation log to prevent replay attacks
    CREATE TABLE IF NOT EXISTS pouw_validation_log (
        validator_id TEXT NOT NULL,
        proof_hash TEXT NOT NULL,
        block_height INTEGER NOT NULL,
        PRIMARY KEY (validator_id, proof_hash)
    );

    -- 链上治理表 (On-chain Governance Tables)
    CREATE TABLE IF NOT EXISTS scheduled_state_changes (
        proposal_hash TEXT PRIMARY KEY,
        enactment_height INTEGER NOT NULL,
        type TEXT NOT NULL,
        data TEXT NOT NULL
    );

    -- [Gen 3] 应用模板注册中心表
    -- [Gen 3] App Template Registry Table
    CREATE TABLE IF NOT EXISTS active_app_templates (
        template_name TEXT PRIMARY KEY,
        pkg_id TEXT NOT NULL,
        package_hash TEXT NOT NULL UNIQUE,
        manifest_hash TEXT NOT NULL,
        developer_signature TEXT,
        developer_id TEXT NOT NULL,
        schema_version INTEGER DEFAULT 1,
        handles_tx_types TEXT NOT NULL, -- 存储一个 JSON 数组字符串 / Stores a JSON array string
        activation_height INTEGER NOT NULL
    );

    -- [批次三] 有用功证明与贡献度表
    -- [Batch Three] Proof of Useful Work & Contribution Tables
    CREATE TABLE IF NOT EXISTS nns_locked_funds (
        domain_name TEXT,
        user_id TEXT,
        amount INTEGER NOT NULL,
        PRIMARY KEY (domain_name, user_id)
    );
    CREATE TABLE IF NOT EXISTS contribution_scores (
        user_id TEXT PRIMARY KEY,
        score INTEGER NOT NULL DEFAULT 0,
        last_update_height INTEGER NOT NULL
    );
    CREATE TABLE IF NOT EXISTS compute_engines (
        engine_id TEXT PRIMARY KEY,
        pkg_id TEXT NOT NULL,
        description TEXT,
        compute_program_hash TEXT NOT NULL,
        verifier_script_hash TEXT NOT NULL,
        is_active INTEGER NOT NULL DEFAULT 0,
        -- [V86 新增] 贡献分奖励权重
        -- [V86 NEW] Contribution score reward weight
        reward_weight INTEGER NOT NULL DEFAULT 100
    );
    CREATE TABLE IF NOT EXISTS problem_sets (
        set_id TEXT PRIMARY KEY,
        engine_id TEXT NOT NULL,
        metadata TEXT NOT NULL,
        activation_height INTEGER,
        FOREIGN KEY(engine_id) REFERENCES compute_engines(engine_id)
    );
    CREATE TABLE IF NOT EXISTS pending_proofs (
        problem_id TEXT PRIMARY KEY,
        proof_tx_hash TEXT NOT NULL,
        proposer_id TEXT NOT NULL,
        proposed_result TEXT NOT NULL,
        confirmation_deadline_height INTEGER NOT NULL
    );
    CREATE TABLE IF NOT EXISTS completed_compute_tasks (
        engine_id TEXT,
        problem_id TEXT,
        proof_tx_hash TEXT NOT NULL,
        PRIMARY KEY (engine_id, problem_id)
    );
    CREATE TABLE IF NOT EXISTS challenges (
        challenge_tx_hash TEXT PRIMARY KEY,
        target_proof_tx_hash TEXT NOT NULL,
        challenger_id TEXT NOT NULL,
        challenge_data TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending'
    );

    # --- [V81+V82 Federation START] 新增 IBC 与链上 Agent 表 ---
    # --- [V81+V82 Federation START] Add new tables for IBC & On-Chain Agents ---
    -- 存储由代码控制的链上身份
    -- Stores on-chain identities controlled by code
    CREATE TABLE IF NOT EXISTS onchain_identities (
        agent_id TEXT PRIMARY KEY,          -- Agent 的唯一身份哈希 / The Agent's unique identity hash
        owner_id TEXT NOT NULL,             -- 创建并控制此 Agent 的用户 ID / The user ID that created and controls this Agent
        pkg_id TEXT NOT NULL,               -- 驱动此 Agent 行为的 Mod 软件包 ID / The Mod package ID that drives this Agent's behavior
        public_key TEXT NOT NULL,           -- [核心] Agent公钥
        activation_height INTEGER NOT NULL
    );
    -- 存储待发送到其他链的消息
    -- Stores outgoing messages to be sent to other chains
    CREATE TABLE IF NOT EXISTS ibc_outgoing_queue (
        source_tx_hash TEXT PRIMARY KEY,
        target_chain_id TEXT NOT NULL,
        message_type TEXT NOT NULL,
        message_payload TEXT NOT NULL,
        postage INTEGER NOT NULL,
        status TEXT NOT NULL DEFAULT 'PENDING',
        relayer_id TEXT,
        relayed_at_block INTEGER
    );
    -- 存储从其他链接收到的、等待处理的消息
    -- Stores incoming messages from other chains waiting to be processed
    CREATE TABLE IF NOT EXISTS ibc_incoming_queue (
        source_chain_id TEXT NOT NULL,
        source_tx_hash TEXT NOT NULL,
        message_type TEXT NOT NULL,
        message_payload TEXT NOT NULL,
        proof_data TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'PEND-VALIDATION',
        PRIMARY KEY (source_chain_id, source_tx_hash)
    );
    # --- [V81+V82 Federation END] ---
    
    # --- [IBC V1] 新增 IBC 验证器注册表 ---
    # --- [IBC V1] Add new table for IBC verifier registry ---
    CREATE TABLE IF NOT EXISTS ibc_verifiers (
        target_chain_id TEXT PRIMARY KEY,       -- 目标链的ID / The ID of the target chain
        verifier_id TEXT NOT NULL,              -- 验证器ID (pkg_id or BUILT_IN:...) / The verifier ID
        is_active INTEGER NOT NULL DEFAULT 0,
        last_known_header_hash TEXT,            -- 哈希链验证器的信任锚 / Trust anchor for hash-chain verifiers
        activation_height INTEGER
    );
    -- [V94 安全升级] 用于记录被状态修正交易宣布无效的交易哈希
    -- [V94 SECURITY UPGRADE] Table to record transaction hashes invalidated by a state_correction_tx
    CREATE TABLE IF NOT EXISTS invalidated_transactions (
        tx_hash TEXT PRIMARY KEY,
        reason TEXT,
        invalidation_height INTEGER NOT NULL
    );
    -- [V95 Phoenix Protocol] 用于记录其他链的最终状态共识
    -- [V95 Phoenix Protocol] Table to record the final state consensus of other chains
    CREATE TABLE IF NOT EXISTS ibc_finalized_states (
        source_chain_id TEXT PRIMARY KEY,
        final_block_height INTEGER NOT NULL,
        state_root_hash TEXT NOT NULL,
        proof_of_consensus TEXT NOT NULL, -- 存储 >2/3 签名的 JSON 数组 / Store the JSON array of >2/3 signatures
        finalized_at_height INTEGER NOT NULL -- 在本链上确认此状态的高度 / The height on this chain where this state was finalized
    );
    -- [V100 新增] 用于记录从其他链同步过来的、已被宣布无效的交易哈希
    -- [V100 NEW] Table to record tx hashes from other chains that have been invalidated
    CREATE TABLE IF NOT EXISTS ibc_invalidated_txs (
        source_chain TEXT NOT NULL,
        tx_hash TEXT NOT NULL,
        reason TEXT,
        invalidation_height INTEGER NOT NULL, -- The height on THIS chain where it was recorded
        PRIMARY KEY (source_chain, tx_hash)
    );
    -- [V105.6 HEARTBEAT] Table to store on-chain node registrations and liveness data.
    -- [V105.6 心跳] 用于存储链上节点注册和存活数据的表。
    CREATE TABLE IF NOT EXISTS node_directory (
        node_id TEXT PRIMARY KEY,
        owner_id TEXT NOT NULL,
        p2p_addresses TEXT NOT NULL, -- Stored as a JSON array of address strings
        last_heartbeat_height INTEGER NOT NULL,
        first_seen_height INTEGER NOT NULL
    );
    "
}


# --- [最终版][V55.5] 拆分出的应用层数据库初始化函数 ---
# --- [FINAL][V55.5] Split-out initialization function for the Application Layer database ---
_init_app_db() {
    local FORUM_DB="${1:-$FORUM_DB}"
    # 包含了您原始设计中的所有应用层表，并加入了新的 aliases 表
    # Includes all Application Layer tables from your original design, and adds the new aliases table
    db_init "$FORUM_DB" "
    CREATE TABLE IF NOT EXISTS subscriptions (
        id TEXT PRIMARY KEY,
        type TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS identity_cache (
        id_hash TEXT PRIMARY KEY,
        nickname TEXT,
        type TEXT NOT NULL,
        permissions TEXT,
        last_updated_height INTEGER NOT NULL,
        source_chain TEXT DEFAULT NULL -- [V100 NEW] 记录身份来源链
    );
    CREATE TABLE IF NOT EXISTS messages (
        tx_hash TEXT PRIMARY KEY,
        sender_id TEXT NOT NULL,
        recipient_id TEXT NOT NULL,
        source_type TEXT NOT NULL,
        content_hash TEXT,
        attachment_meta TEXT,
        -- [新增] 用于存储短文本或特殊消息内容
        -- [NEW] For storing short text or special message content
        inline_content TEXT,
        -- ========================================================== --
        -- --- [E2EE MODIFICATION START] 新增加密模式字段           --- --
        -- --- [E2EE MODIFICATION START] Add new encryption mode field --- --
        -- ========================================================== --
        encryption_mode TEXT DEFAULT 'none', -- e.g., 'none', 'e2ee-v1'
        -- ========================================================== --
        -- --- [E2EE MODIFICATION END]                            --- --
        -- ========================================================== --
        timestamp INTEGER NOT NULL,
        priority TEXT DEFAULT 'low',
        is_read INTEGER DEFAULT 0
    );
    CREATE TABLE IF NOT EXISTS acl_state (
        acl_id TEXT NOT NULL,
        grantee_id TEXT NOT NULL,
        permissions TEXT NOT NULL,
        PRIMARY KEY (acl_id, grantee_id)
    );
    CREATE TABLE IF NOT EXISTS wiki_pages (
        page_tx_hash TEXT PRIMARY KEY,
        group_id TEXT NOT NULL,
        slug TEXT NOT NULL,
        latest_version_hash TEXT,
        locked_by_user_id TEXT,
        lock_tx_hash TEXT,
        attachment_hash TEXT,
        UNIQUE(group_id, slug)
    );
    CREATE TABLE IF NOT EXISTS wiki_versions (
        version_tx_hash TEXT PRIMARY KEY,
        page_tx_hash TEXT NOT NULL,
        previous_version_hash TEXT,
        author_id TEXT NOT NULL,
        content_hash TEXT NOT NULL,
        format TEXT DEFAULT 'md',
        commit_message TEXT,
        timestamp INTEGER NOT NULL
    );
    CREATE TABLE IF NOT EXISTS nns_records (
        domain_name TEXT PRIMARY KEY,
        owner_id TEXT NOT NULL,
        target_hash TEXT NOT NULL,
        last_update_height INTEGER NOT NULL,
        registration_type TEXT,
        expires_at INTEGER NOT NULL DEFAULT 0
    );
    CREATE TABLE IF NOT EXISTS nns_auctions (
        domain_name TEXT PRIMARY KEY,
        start_block INTEGER NOT NULL,
        end_bid_block INTEGER NOT NULL,
        end_reveal_block INTEGER NOT NULL,
        status TEXT NOT NULL,
        highest_bidder TEXT,
        second_highest_bid INTEGER
    );
    CREATE TABLE IF NOT EXISTS aliases (
        alias_name TEXT PRIMARY KEY,
        channel_id TEXT NOT NULL UNIQUE
    );
    CREATE TABLE IF NOT EXISTS local_user_blocks (
    blocked_id TEXT PRIMARY KEY
    );
    # --- [V76 Mail Svc START] 新增邮件元数据表 ---
    # --- [V76 Mail Svc START] Add new table for mail metadata ---
    CREATE TABLE IF NOT EXISTS mails (
        tx_hash TEXT PRIMARY KEY,           -- 邮件分发交易的哈希 / Hash of the mail dispatch transaction
        sender_id TEXT NOT NULL,            -- 发件人ID / Sender's ID
        recipient_id TEXT NOT NULL,         -- 收件人ID (可以是用户或作为邮件列表的群组) / Recipient's ID (can be a user or a group acting as a maillist)
        mail_object_hash TEXT NOT NULL,     -- 指向加密/明文邮件内容的P2P哈希 / P2P hash pointing to the encrypted/plaintext mail content
        timestamp INTEGER NOT NULL,
        is_read INTEGER NOT NULL DEFAULT 0,
        local_path TEXT                     -- 本地缓存的邮件对象路径 / Local cached path of the mail object
    );
    CREATE INDEX IF NOT EXISTS idx_mails_recipient ON mails(recipient_id, timestamp);
    # --- [V76 Mail Svc END] ---
    
    -- [V95 Phoenix Protocol] 停机公告板 (CBB) 与 Exodus 协议表
    -- [V95 Phoenix Protocol] Tables for Ceasefire Bulletin Board (CBB) and Exodus Protocol
    CREATE TABLE IF NOT EXISTS cbb_messages (
        msg_hash TEXT PRIMARY KEY,
        author_id TEXT NOT NULL,
        timestamp INTEGER NOT NULL,
        message TEXT NOT NULL,
        signature TEXT NOT NULL,
        expires_at INTEGER NOT NULL
    );
    CREATE INDEX IF NOT EXISTS idx_cbb_expiry ON cbb_messages(expires_at);

    CREATE TABLE IF NOT EXISTS exodus_proposals (
        proposal_hash TEXT PRIMARY KEY,
        author_id TEXT NOT NULL,
        target_block_height INTEGER NOT NULL,
        target_block_hash TEXT NOT NULL,
        timestamp INTEGER NOT NULL,
        full_proposal_object TEXT NOT NULL,
        expires_at INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS exodus_notarizations (
        proposal_hash TEXT NOT NULL,
        notary_id TEXT NOT NULL,
        signature TEXT NOT NULL,
        full_notarization_object TEXT NOT NULL,
        PRIMARY KEY (proposal_hash, notary_id)
    );

    -- [V95 Phoenix Protocol] 链上 Agent 的紧急任务队列
    -- [V95 Phoenix Protocol] Emergency Task Queue for On-Chain Agents
    CREATE TABLE IF NOT EXISTS agent_emergency_queue (
        task_hash TEXT PRIMARY KEY,
        target_agent_id TEXT NOT NULL,
        task_payload TEXT NOT NULL,
        proposer_id TEXT NOT NULL,
        proposer_signature TEXT NOT NULL,
        submitted_at INTEGER NOT NULL,
        expires_at INTEGER NOT NULL
    );
    
    -- [V98 新增] 用于存储链上信任背书的表
    -- [V98 NEW] Table for storing on-chain trust endorsements
    CREATE TABLE IF NOT EXISTS trust_endorsements (
        endorser_id TEXT NOT NULL,          -- 签名背书者的身份ID
        endorsee_id TEXT NOT NULL,          -- 被背书者的身份ID
        endorsement_type TEXT NOT NULL,     -- 'identity' 或 'gpg_key'
        signature TEXT NOT NULL,            -- 背书签名
        tx_hash TEXT PRIMARY KEY,           -- 背书交易的哈希
        block_height INTEGER NOT NULL
    );
    CREATE INDEX IF NOT EXISTS idx_endorsements_on_endorsee ON trust_endorsements(endorsee_id);
    "
}


# --- [最终版][V55.5] init_databases (总指挥) ---
# --- [FINAL][V55.5] init_databases (dispatcher) ---
init_databases() {
    # 现在它会调用包含了完整 Schema 的初始化函数
    # Now it calls the initialization functions that contain the complete schemas
    _init_dht_db
    _init_blockchain_db
    _init_app_db
    forum_init

    # Initialize genesis block if blockchain is empty (logic unchanged)
    # 如果区块链为空，则初始化创世区块 (逻辑不变)
    local genesis_count
    genesis_count=$(db_query_static "$BLOCKCHAIN_DB" "SELECT COUNT(*) FROM blocks;" 2>/dev/null || echo 0)
    if [ "$genesis_count" -eq 0 ]; then
        blockchain_create_genesis_block
    fi
}

# --- [最终版][V55.6] load_config (完整且使用内存缓存) ---
# --- [FINAL][V55.6] load_config (complete and uses in-memory cache) ---
load_config() {
    # --- 1. 将所有可配置项的默认值预加载到缓存 ---
    # --- 1. Pre-load default values for all configurable items into the cache ---
    # [main]
    CORIUM_CONFIG_CACHE[main_dep_mode]="${DEP_MODE}"
    CORIUM_CONFIG_CACHE[main_build_jobs]="${BUILD_JOBS}"
    CORIUM_CONFIG_CACHE[main_build_tmp_dir]="${BUILD_TMP_DIR_BASE}"
    CORIUM_CONFIG_CACHE[main_editor]="${DEFAULT_EDITOR}"
    CORIUM_CONFIG_CACHE[main_canary_policy]="${CANARY_POLICY:-block}" # 假设默认是 block

    # [network]
    CORIUM_CONFIG_CACHE[network_download_protocol_priority]="${DOWNLOAD_PROTO_PRIORITY}"
    CORIUM_CONFIG_CACHE[network_download_jobs]="${DOWNLOAD_JOBS}"
    CORIUM_CONFIG_CACHE[network_bt_download_timeout]="${BT_DOWNLOAD_TIMEOUT}"
    CORIUM_CONFIG_CACHE[network_proxy]="${P2P_GENERAL_PROXY}" # 兼容旧的 network_proxy

    # [strata]
    CORIUM_CONFIG_CACHE[strata_sandbox_tool]="${SANDBOX_TOOL}"

    # [p2p]
    CORIUM_CONFIG_CACHE[p2p_port]="${P2P_PORT}"
    CORIUM_CONFIG_CACHE[p2p_chunk_size]="${P2P_CHUNK_SIZE}"
    CORIUM_CONFIG_CACHE[p2p_http_port_offset]="${P2P_HTTP_PORT_OFFSET}"
    CORIUM_CONFIG_CACHE[p2p_file_port_offset]="${P2P_FILE_PORT_OFFSET}"
    CORIUM_CONFIG_CACHE[p2p_message_timeout]="${P2P_MESSAGE_TIMEOUT:-5}"
    CORIUM_CONFIG_CACHE[p2p_simulate_nodes]="${P2P_SIMULATE_NODES:-0}"
    CORIUM_CONFIG_CACHE[p2p_dht_alpha]="${P2P_DHT_ALPHA}"
    CORIUM_CONFIG_CACHE[p2p_auto_trust_new_nodes]="${AUTO_TRUST_NEW_NODES}"
    CORIUM_CONFIG_CACHE[p2p_stun_servers]="${P2P_STUN_SERVERS}"
    CORIUM_CONFIG_CACHE[p2p_enable_upnp]="${P2P_ENABLE_UPNP}"
    CORIUM_CONFIG_CACHE[p2p_enable_hole_punching]="${P2P_ENABLE_HOLE_PUNCHING}"
    CORIUM_CONFIG_CACHE[p2p_announce_ipv6]="${P2P_ANNOUNCE_IPV6}"
    CORIUM_CONFIG_CACHE[p2p_tor_proxy]="${P2P_TOR_PROXY}"
    CORIUM_CONFIG_CACHE[p2p_i2p_proxy]="${P2P_I2P_PROXY}"
    CORIUM_CONFIG_CACHE[p2p_onion_service_address]="${P2P_ONION_SERVICE_ADDRESS}"
    CORIUM_CONFIG_CACHE[p2p_i2p_destination]="${P2P_I2P_DESTINATION}"
    CORIUM_CONFIG_CACHE[p2p_public_ip]="" # 新增：默认为空
    CORIUM_CONFIG_CACHE[p2p_tls_ech_enabled]="${TLS_ECH_ENABLED:-false}"
    CORIUM_CONFIG_CACHE[p2p_tls_no_sni_client]="${TLS_NO_SNI_CLIENT:-true}"
    # --- [功能补完] 预加载引导节点配置 (默认为空字符串) ---
    # --- [FEATURE COMPLETE] Pre-load bootstrap nodes config (defaults to empty string) ---
    CORIUM_CONFIG_CACHE[p2p_dht_bootstrap_nodes]=""

    # [blockchain]
    CORIUM_CONFIG_CACHE[blockchain_consensus]="${BLOCKCHAIN_CONSENSUS}"
    CORIUM_CONFIG_CACHE[blockchain_validator_stake]="${BLOCKCHAIN_VALIDATOR_STAKE:-100}"
    # --- [V105.5 SECURITY] Add the new config key to the caching logic ---
    # --- [V105.5 安全] 将新的配置键加入缓存逻辑 ---
    CORIUM_CONFIG_CACHE[blockchain_weak_subjectivity_checkpoints]="${BLOCKCHAIN_WSC}"
    
    # [trust]
    CORIUM_CONFIG_CACHE[trust_gpg_signing_key]="${GPG_SIGNING_KEY:-}"
    CORIUM_CONFIG_CACHE[trust_require_gpg_signature]="${trust_require_gpg_signature:-true}"
    
    # [forum]
    CORIUM_CONFIG_CACHE[forum_enabled]="${FORUM_ENABLED:-true}"
    CORIUM_CONFIG_CACHE[forum_auto_sync]="${FORUM_AUTO_SYNC:-true}"
    
    # --- 2. 从文件读取并覆盖缓存 ---
    # --- 2. Read from file and overwrite the cache ---
    [ ! -f "$CONFIG_FILE" ] && return
    
    local config_data
    config_data=$(awk '
        # 去除行首和行尾的空格
        function trim(s) {
            gsub(/^[ \t]+|[ \t]+$/, "", s);
            return s;
        }
        # 跳过注释和空行
        /^\s*($|#|;)/ { next }
        # 匹配 section 标题, 例如 [p2p]
        /^\s*\[(.*)\]\s*$/ {
            current_section = gensub(/^\s*\[(.*)\]\s*$/, "\\1", 1);
            next;
        }
        # 匹配 key = value 格式的行
        /.+=.*/ {
            if (current_section) {
                # 找到第一个等号的位置
                eq_pos = index($0, "=");
                # 提取 key 和 value
                key = substr($0, 1, eq_pos - 1);
                val = substr($0, eq_pos + 1);
                # 清理 key 和 value 的空格
                key = trim(key);
                val = trim(val);
                print current_section "_" key " " val;
            }
        }
    ' "$CONFIG_FILE" 2>/dev/null)
    
    while read -r var_name var_value; do
        [ -n "$var_name" ] || continue
        CORIUM_CONFIG_CACHE["$var_name"]="$var_value"
    done <<< "$config_data"
    
    # --- 3. 从缓存中将所有值赋给全局变量 ---
    # --- 3. Assign all values from the cache to global variables ---
    # [main]
    DEP_MODE="${CORIUM_CONFIG_CACHE[main_dep_mode]:-}"
    BUILD_JOBS="${CORIUM_CONFIG_CACHE[main_build_jobs]:-}"
    BUILD_TMP_DIR_BASE="${CORIUM_CONFIG_CACHE[main_build_tmp_dir]:-}"
    DEFAULT_EDITOR="${CORIUM_CONFIG_CACHE[main_editor]:-}"
    CANARY_POLICY="${CORIUM_CONFIG_CACHE[main_canary_policy]:-}"
    ENABLE_FUZZY_FINDER="${CORIUM_CONFIG_CACHE[main_enable_fuzzy_finder]:-}"

    # [network]
    DOWNLOAD_PROTO_PRIORITY="${CORIUM_CONFIG_CACHE[network_download_protocol_priority]:-}"
    DOWNLOAD_JOBS="${CORIUM_CONFIG_CACHE[network_download_jobs]:-}"
    BT_DOWNLOAD_TIMEOUT="${CORIUM_CONFIG_CACHE[network_bt_download_timeout]:-}"
    P2P_GENERAL_PROXY="${CORIUM_CONFIG_CACHE[network_proxy]:-}"

    # [strata]
    SANDBOX_TOOL="${CORIUM_CONFIG_CACHE[strata_sandbox_tool]:-}"
    
    # [p2p]
    P2P_PORT="${CORIUM_CONFIG_CACHE[p2p_port]:-}"
    P2P_CHUNK_SIZE="${CORIUM_CONFIG_CACHE[p2p_chunk_size]:-}"
    P2P_HTTP_PORT_OFFSET="${CORIUM_CONFIG_CACHE[p2p_http_port_offset]:-}"
    P2P_FILE_PORT_OFFSET="${CORIUM_CONFIG_CACHE[p2p_file_port_offset]:-}"
    P2P_MESSAGE_TIMEOUT="${CORIUM_CONFIG_CACHE[p2p_message_timeout]:-}"
    P2P_SIMULATE_NODES="${CORIUM_CONFIG_CACHE[p2p_simulate_nodes]:-}"
    P2P_DHT_ALPHA="${CORIUM_CONFIG_CACHE[p2p_dht_alpha]:-}"
    AUTO_TRUST_NEW_NODES="${CORIUM_CONFIG_CACHE[p2p_auto_trust_new_nodes]:-}"
    CORIUM_EXCLUDED_NODES="${CORIUM_CONFIG_CACHE[p2p_excluded_nodes]:-}"
    CORIUM_EXCLUDED_NODES="${CORIUM_EXCLUDED_NODES// /}"
    [[ ${#CORIUM_EXCLUDED_NODES} -le 4159 ]] || return 1
    [[ -z "$CORIUM_EXCLUDED_NODES" || "$CORIUM_EXCLUDED_NODES" =~ ^[a-f0-9]{64}(,[a-f0-9]{64})*$ ]] || return 1
    export CORIUM_EXCLUDED_NODES
    P2P_STUN_SERVERS="${CORIUM_CONFIG_CACHE[p2p_stun_servers]:-}"
    P2P_ENABLE_UPNP="${CORIUM_CONFIG_CACHE[p2p_enable_upnp]:-}"
    P2P_ENABLE_HOLE_PUNCHING="${CORIUM_CONFIG_CACHE[p2p_enable_hole_punching]:-}"
    P2P_ANNOUNCE_IPV6="${CORIUM_CONFIG_CACHE[p2p_announce_ipv6]:-}"
    P2P_TOR_PROXY="${CORIUM_CONFIG_CACHE[p2p_tor_proxy]:-}"
    P2P_I2P_PROXY="${CORIUM_CONFIG_CACHE[p2p_i2p_proxy]:-}"
    P2P_ONION_SERVICE_ADDRESS="${CORIUM_CONFIG_CACHE[p2p_onion_service_address]:-}"
    P2P_I2P_DESTINATION="${CORIUM_CONFIG_CACHE[p2p_i2p_destination]:-}"
    if [[ -n "${CORIUM_TEST_P2P_PORT:-}" ]]; then P2P_PORT="$CORIUM_TEST_P2P_PORT"; fi
    if [[ -n "${CORIUM_TEST_GATEWAY_PORT:-}" ]]; then CORIUM_GATEWAY_PORT="$CORIUM_TEST_GATEWAY_PORT"; fi
    # Convert explicit host:port seeds into the native typed address format.
    # Neither option has implicit peers; reject malformed endpoints before networking.
    DHT_BOOTSTRAP_NODES_STRING=$("${PYTHON_CMD:-python3}" - "${CORIUM_CONFIG_CACHE[p2p_seed_peers]:-}" "${CORIUM_CONFIG_CACHE[p2p_dht_bootstrap_nodes]:-}" <<'PY_CORIUM_SEEDS'
import ipaddress,re,sys
from urllib.parse import urlsplit
seeds,legacy=sys.argv[1:]
if seeds and legacy:raise SystemExit('Configure seed_peers or dht_bootstrap_nodes, not both')
items=[]
for raw in seeds.split(',') if seeds else []:
 raw=raw.strip();value=urlsplit('//'+raw)
 try:port=value.port
 except ValueError:raise SystemExit('Invalid seed port')
 if not value.hostname or not port or value.path or value.query or value.fragment or value.username or value.password or any(c.isspace() for c in raw):raise SystemExit('Invalid seed endpoint')
 host=value.hostname
 try:kind='ipv'+str(ipaddress.ip_address(host).version)
 except ValueError:
  if not re.fullmatch(r'[A-Za-z0-9](?:[A-Za-z0-9.-]{0,251}[A-Za-z0-9])?',host):raise SystemExit('Invalid seed hostname')
  kind='dns'
 if ':' in host:host='['+host+']'
 items.append(kind+':'+host+':'+str(port))
if legacy:
 for raw in legacy.split(','):
  raw=raw.strip();kind,sep,address=raw.partition(':')
  if kind not in {'ipv4','ipv6','dns','tor','i2p','tcp'} or not sep or any(c.isspace() for c in raw):raise SystemExit('Invalid native bootstrap address')
  value=urlsplit('//'+address)
  try:port=value.port
  except ValueError:raise SystemExit('Invalid native bootstrap port')
  if not value.hostname or not port or value.path or value.query or value.fragment or value.username or value.password:raise SystemExit('Invalid native bootstrap endpoint')
  items.append(raw)
if len(items)>32:raise SystemExit('Too many explicit seed peers')
print(','.join(items))
PY_CORIUM_SEEDS
    ) || return 1
    P2P_PUBLIC_IP_OVERRIDE="${CORIUM_CONFIG_CACHE[p2p_public_ip]:-}" # 新增：赋给全局变量
    TLS_ECH_ENABLED="${CORIUM_CONFIG_CACHE[p2p_tls_ech_enabled]:-}"
    TLS_NO_SNI_CLIENT="${CORIUM_CONFIG_CACHE[p2p_tls_no_sni_client]:-}"


    # [blockchain]
    BLOCKCHAIN_CONSENSUS="${CORIUM_CONFIG_CACHE[blockchain_consensus]:-}"
    BLOCKCHAIN_VALIDATOR_STAKE="${CORIUM_CONFIG_CACHE[blockchain_validator_stake]:-}"
    # --- [V105.5 SECURITY] Assign the final value (from file or default) back to the global var ---
    # --- [V105.5 安全] 将最终值（来自文件或默认值）赋回给全局变量 ---
    BLOCKCHAIN_WSC="${CORIUM_CONFIG_CACHE[blockchain_weak_subjectivity_checkpoints]:-}"
    
    # [trust]
    GPG_SIGNING_KEY="${CORIUM_CONFIG_CACHE[trust_gpg_signing_key]:-}"
    trust_require_gpg_signature="${CORIUM_CONFIG_CACHE[trust_require_gpg_signature]:-}"
    
    # [forum]
    FORUM_ENABLED="${CORIUM_CONFIG_CACHE[forum_enabled]:-}"
    FORUM_AUTO_SYNC="${CORIUM_CONFIG_CACHE[forum_auto_sync]:-}"
}



# --- [新增] 用于重新加载路径变量的内部函数 ---
_reload_path_variables() {
    # 这是一个关键的新函数，用于在交互式设置中动态更新路径
    # This is a critical new function to dynamically update paths during interactive setup.
    CORIUM_NETWORK_ID="${CORIUM_NETWORK_ID_OVERRIDE:-default}"
    [[ "$CORIUM_NETWORK_ID" =~ ^[a-zA-Z0-9][a-zA-Z0-9._-]*$ ]] || error "网络 ID 无效。/ Invalid network ID."
    export CORIUM_NETWORK_ID
    ETC_CORIUM_DIR="${CORIUM_ROOT%/}/etc/corix/networks/${CORIUM_NETWORK_ID}"
    CONFIG_FILE="${ETC_CORIUM_DIR}/corix.conf"
    WORLD_FILE="${ETC_CORIUM_DIR}/world"
    export WORLD_FILE
    REPOS_CONF_DIR="${ETC_CORIUM_DIR}/repos.conf.d"
    USER_IDENTITY_FILE="${ETC_CORIUM_DIR}/identity.key"
    USER_PUBLIC_KEY_FILE="${USER_IDENTITY_FILE}.pub"
    GENESIS_CONFIG_FILE="${ETC_CORIUM_DIR}/genesis.json"
    TLS_KEY_FILE="${ETC_CORIUM_DIR}/tls.key"
    TLS_CERT_FILE="${ETC_CORIUM_DIR}/tls.crt"
    VAR_LIB_CORIUM_DIR="${CORIUM_ROOT%/}/var/lib/corix/networks/${CORIUM_NETWORK_ID}"
    INSTALLED_DB="${VAR_LIB_CORIUM_DIR}/installed"
    EXTERNAL_PM_DB="${VAR_LIB_CORIUM_DIR}/external"
    BLOCKCHAIN_DIR="${VAR_LIB_CORIUM_DIR}/blockchain"
    BLOCKCHAIN_DB="${BLOCKCHAIN_DIR}/chain.db"
    FORUM_DIR="${VAR_LIB_CORIUM_DIR}/forum"
    FORUM_DB="${FORUM_DIR}/forum.db"
    FORUM_OBJECTS_DIR="${FORUM_DIR}/objects"
    FORUM_MANIFESTS_DIR="${FORUM_DIR}/manifests"
    FORUM_PUBKEYS_DIR="${FORUM_DIR}/pubkeys"
    TRUST_ZONES_DIR="${ETC_CORIUM_DIR}/trust_zones"
    P2P_DIR="${CORIUM_ROOT%/}/var/lib/corix/p2p"
    DHT_DB="${P2P_DIR}/dht.db"
    SNAPSHOTS_DIR="${VAR_LIB_CORIUM_DIR}/snapshots"
    DAPP_DATA_DIR="${VAR_LIB_CORIUM_DIR}/dapp_data"
    MOD_DATA_DIR="${VAR_LIB_CORIUM_DIR}/mod_data"
    REPOS_DIR="${CORIUM_ROOT%/}/usr/corix/repos/networks/${CORIUM_NETWORK_ID}"
    STRATA_DIR="${CORIUM_ROOT%/}/usr/corix/strata/networks/${CORIUM_NETWORK_ID}"
    NETWORK_LOCK_FILE="${LOCK_DIR}/${CORIUM_NETWORK_ID}.network.lock"
}


# --- [新增] 将 `init` 中的静态文件创建逻辑提取出来 ---
# --- [V103.4 最终修复] 将 `init` 中的静态文件创建逻辑提取出来 (幂等版) ---
_init_create_default_files() {
    info "正在检查并创建基础配置文件... / Checking and creating base configuration files..."

    if [ ! -f "$WORLD_FILE" ]; then
        detail "  -> 正在创建空的 world 文件... / Creating empty world file..."
        touch "$WORLD_FILE"
    fi

    local gitignore_file="${ETC_CORIUM_DIR}/.gitignore"
    if [ ! -f "$gitignore_file" ]; then
        detail "  -> 正在创建 .gitignore... / Creating .gitignore..."
        cat > "$gitignore_file" <<'EOF'
# Corium private keys - DO NOT COMMIT TO VERSION CONTROL
# Corium 私钥 - 不要提交到版本控制
*.key
*.crt
EOF
    fi

    local local_acl_file="${ETC_CORIUM_DIR}/local_acl.conf"
    if [ ! -f "$local_acl_file" ]; then
        detail "  -> 正在创建本地ACL配置文件... / Creating local ACL configuration file..."
        touch "$local_acl_file"
    fi
    
    local theme_file="${ETC_CORIUM_DIR}/theme.conf"
    if [ ! -f "$theme_file" ]; then
        detail "  -> 正在初始化默认主题配置... / Initializing default theme configuration..."
        corix_theme_init >/dev/null # corix_theme_init 内部已经有存在性检查
    fi

    local core_repo_conf="${REPOS_CONF_DIR}/00-core.conf"
    if [ ! -f "$core_repo_conf" ]; then
        detail "  -> 正在生成默认仓库配置... / Generating default repository configuration..."
        cat > "$core_repo_conf" <<'EOF'
[core]
type = local
path = /usr/corix/repos/core
priority = 10
#
# 对于高级网络配置，您可以添加 'repo_purpose' 标志。
# For advanced network configuration, you can add a 'repo_purpose' flag.
#
# repo_purpose = build_logic      # (默认) 此仓库提供 .build 文件。
#                                 # (Default) This repository provides .build files.
#
# repo_purpose = trust_overlay    # 此仓库提供一个 packages.trust 文件，用于覆盖默认的区块链验证。
#                                 # This repository provides a packages.trust file to override default blockchain verification.
#
# =============================================================================
# --- 高级仓库配置示例 / Advanced Repository Configuration Examples ---
# =============================================================================
#
# --- P2P 仓库 (静态哈希) / P2P Repository (Static Hash) ---
# type = p2p
# hash = a1b2c3d4e5f6...
#
# --- P2P 仓库 (动态 NNS 域名) / P2P Repository (Dynamic NNS Domain) ---
# type = p2p
# nomen-name = community-main-repo
#
# --- 信任覆盖层 (推荐使用动态 NNS 域名) ---
# --- Trust Overlay (Dynamic NNS Domain Recommended) ---
# type = p2p
# nomen-name = security.corium
# repo_purpose = trust_overlay
#
EOF
    fi
}

# --- [新增] 将 `init` 中的配置文件生成逻辑提取出来 ---
_init_generate_config_file() {
    cat > "$CONFIG_FILE" <<'EOF'
# corix - The Next-Generation Meta Package Manager
# 主配置文件 / Main Configuration File: /etc/corix/networks/${CORIUM_NETWORK_ID}/corix.conf

[main]
# 依赖处理模式 (auto, suggest, manual)
# Dependency handling mode (auto, suggest, manual)
dep_mode = auto
# 并行构建任务数
# Number of parallel build jobs
build_jobs = 4
# 默认文本编辑器
# Default text editor
editor = nano
# 在需要输入ID时，是否自动启用交互式模糊查找器 (fzf)
# Enable the interactive fuzzy finder (fzf) when an ID is required
enable_fuzzy_finder = true

[network]
# P2P网络隔离ID
# P2P network isolation ID
id = default
# 下载协议优先级
# Download protocol priority
download_protocol_priority = p2p,http,git
# Socks5 代理
# Socks5 proxy
proxy = 

[p2p]
# P2P网络监听端口
# P2P network listening port
port = 7234
# STUN 服务器列表，用于NAT穿透
# List of STUN servers for NAT traversal
stun_servers = stun.l.google.com:19302,stun.nextcloud.com:443
# 是否启用UPnP进行自动端口转发
# Enable automatic port forwarding via UPnP
enable_upnp = true
# (可选) 手动指定您的公网IP地址。当Corium运行在NAT或VPS后方时，
# 强烈建议设置此项，以确保生成的邀请码是正确的。
# (Optional) Manually specify your public IP address. This is highly recommended when running behind NAT or on a VPS to ensure correct identity strings are generated.
# public_ip = 
# [安全] 是否自动信任新的P2P节点 (禁用中间人攻击防护)
# [SECURITY] Automatically trust new P2P peers (disables MITM protection)
auto_trust_new_nodes = false

# --- [V86] 高级抗审查 TLS 设置 ---
# --- [V86] Advanced Anti-Censorship TLS Settings ---
# (实验性) 启用加密客户端问候 (ECH) 以隐藏 SNI。需要 curl 7.87+ 和兼容的 SSL 库。
# (Experimental) Enable Encrypted Client Hello (ECH) to hide the SNI. Requires curl 7.87+ and a compatible SSL library.
tls_ech_enabled = false

# (实验性) 作为客户端连接时，不发送服务器名称指示 (SNI)。可以帮助绕过一些审查系统。
# (Experimental) As a client, do not send the Server Name Indication (SNI). Can help bypass some censors.
tls_no_sni_client = true

[blockchain]
# 共识机制 (目前仅支持pos)
# Consensus mechanism (only pos is currently supported)
consensus = pos

# [安全] 弱主观性检查点。这是一个极其重要的长程攻击防御机制。
# 格式: "高度1:哈希前缀1,高度2:哈希前缀2,..."
# Corium客户端将拒绝任何不包含这些检查点的链，无论其权重多高。
# 检查点应从社区可信来源（如项目官网、开发者公告）获取。
# [SECURITY] Weak Subjectivity Checkpoints. A critical defense against long-range attacks.
# Format: "height1:hash_prefix1,height2:hash_prefix2,..."
# The Corium client will reject any chain that does not contain these checkpoints, regardless of its weight.
# Checkpoints should be obtained from trusted community sources (e.g., project website, developer announcements).
weak_subjectivity_checkpoints = ""

[trust]
# 用于为二进制包签名的GPG密钥ID。如果留空，则不进行签名。
# The GPG Key ID to use for signing binary packages. If empty, no signing is performed.
gpg_signing_key = 

# 是否强制要求所有包都必须有有效的GPG签名。
# Whether to require all packages to have a valid GPG signature.
# 可选值: true (强制), false (允许回退到区块链验证)
# Options: true (enforce), false (allow fallback to blockchain verification)
require_gpg_signature = true

[gateway]
# 本地HTTP网关监听端口
# Local HTTP gateway listening port
port = 8080
# 是否启用网关守护进程
# Enable the gateway daemon
enabled = true
EOF
}

# =======================================================
# --- [v45] REVISED corix_init & load_config            ---
# --- [v45] 已修订的 corix_init 和 load_config          ---
# =======================================================

# Initializes the entire Corium system on a new machine.
# This function is idempotent, meaning it's safe to run multiple times.
# 在一台新机器上初始化整个 Corium 系统。
# 此函数是幂等的，意味着可以安全地多次运行。
corix_init() {
    # 'init' modifies the core system layout and databases, requiring a system-level lock.
    # 'init' 会修改核心系统布局和数据库，因此需要一个系统级的锁。
    check_permissions "init"
    
    # --- [V97 新增] 参数解析 / [V97 NEW] Argument Parsing ---
    local interactive_mode=0 state_only=0 init_option
    for init_option in "$@"; do
        case "$init_option" in
            --interactive) interactive_mode=1 ;;
            --state-only) state_only=1 ;;
            *) error "init 参数无效。/ Invalid init arguments." ;;
        esac
    done
    # -------------------------------------------
    
    local encrypt_flag=""
    
    # --- [V97 新增] 交互式初始化流程 ---
    # --- [V97 NEW] Interactive Initialization Flow ---
    if [ "$interactive_mode" -eq 1 ]; then
        _apply_theme "primary" "欢迎来到 Corium 交互式安装向导！"
        _apply_theme "primary" "Welcome to the Corium Interactive Setup Wizard!"
        _apply_theme "info" "本向导将帮助您完成 Corium 节点的首次配置。"
        _apply_theme "info" "This wizard will guide you through the initial configuration of your Corium node."
        echo

        # 1. 网络 ID
        local custom_network_id=""
        _apply_theme "accent" "第一步：网络ID (Network ID)"
        _apply_theme "info" "网络ID用于隔离不同的 Corium 网络（如主网、测试网）。"
        _apply_theme "info" "The Network ID is used to isolate different Corium networks (e.g., mainnet, testnet)."
        read -rp "请输入您的网络ID (留空则使用 'default'): / Please enter your Network ID (leave blank for 'default'): " custom_network_id
        if [ -n "$custom_network_id" ]; then
            # 如果用户输入了自定义 ID，则立即导出环境变量以影响后续所有路径变量
            # If the user enters a custom ID, export the environment variable immediately to affect all subsequent path variables
            export CORIUM_NETWORK_ID_OVERRIDE="$custom_network_id"
            # 重新加载路径变量
            # Reload path variables
            _reload_path_variables 
        fi
        
        # 2. 身份密钥
        _apply_theme "accent" "\n第二步：身份密钥 (Identity Key)"
        if [ -f "$USER_IDENTITY_FILE" ]; then
            _apply_theme "success" "检测到已存在的身份密钥。将跳过生成步骤。"
            _apply_theme "success" "Existing identity key detected. Skipping generation."
        else
            _apply_theme "info" "您的身份密钥是您在网络上的唯一凭证，至关重要。"
            _apply_theme "info" "Your identity key is your unique credential on the network and is critically important."
                        
            # --- [V98 新增] 询问是否加密 ---
            local encrypt_choice=""
            read -rp "您希望稍后为您的私钥设置密码保护吗？(强烈推荐) [Y/n]: / Do you want to password-protect your private key later? (Highly Recommended) [Y/n]: " encrypt_choice
            
            if [[ ! "$encrypt_choice" =~ ^[nN]$ ]]; then
                encrypt_flag="--encrypt"
            fi
        fi
        
        # 3. 配置文件
        _apply_theme "accent" "\n第三步：核心配置 (Core Configuration)"
        _apply_theme "info" "我们将为您生成一份默认的配置文件，您可以稍后通过 'corix config' 命令修改。"
        _apply_theme "info" "We will now generate a default configuration file for you. You can modify it later with the 'corix config' command."
        read -rp "按 Enter 键继续... / Press Enter to continue..."
    fi
    # --- [交互式流程结束] ---
    
    acquire_lock "system"
    trap 'release_lock "system"' RETURN
    
    info "正在创建密码学身份... / Generating cryptographic identity..."
    if [ ! -f "$USER_IDENTITY_FILE" ]; then
        # 先确保父目录存在
        mkdir -p "$ETC_CORIUM_DIR"
        
        # 在这里调用 generate_keypair
        # 如果用户密码输错或取消，脚本会在这里失败退出，
        # 此时只创建了一个空目录，影响最小。
        generate_keypair "$USER_IDENTITY_FILE" "$USER_PUBLIC_KEY_FILE" "$encrypt_flag"
        info "身份已生成 / Identity generated: $(cat "$USER_PUBLIC_KEY_FILE" | calculate_hash)"
    fi
    
    msg "正在开始 Corium 系统初始化/服务启动... / Starting Corium system initialization / service startup..."

    info "正在检查关键的外部依赖…… / Checking for critical external dependencies..."
    info "您需要安装Coreutils与Findutils，这在绝大多数系统上默认都有安装。/ You need to install Coreutilis and Findutilis, which are installed by default on the vast majority of systems."
    info "本程序用到了很多特定于GNU风格的工具的参数，这使得在非GNU/Linux上的运行可能存在问题，需要修改代码。 / This program uses many parameters specific to GNU style tools, which may cause issues when running on non GNU/Linux platforms and require code modifications."
    local core_deps=(curl git tar sha256sum patch make gcc openssl awk sqlite3 python3 bc jq xxd rsync ip pgrep pkill lsof unzip numfmt getopt timeout)
    # ip              # (from iproute2) 用于P2P网络
    # pgrep pkill     # (from procps-ng) 用于停止守护进程
    # lsof            # 用于 corix stop --force
    # unzip           # 用于解压.zip源码包
    # [新增] 包含 RestrictedPython 在内的所有核心Python库
    # [NEW] All core Python libraries, including RestrictedPython
    local core_py_deps=(cryptography pystun3 miniupnpc RestrictedPython sqlparse psutil)    
    
    for dep in "${core_deps[@]}"; do check_dep "$dep"; done
    
    info "正在检查关键的 Python 库... / Checking for critical Python libraries..."
    for dep in "${core_py_deps[@]}"; do check_py_dep "$dep"; done
    
    # [IMPROVEMENT] Call the new context-aware function to check optional dependencies.
    # [改进] 调用新的上下文感知函数来检查可选依赖。
    _check_relevant_optional_deps
    
    # --- Special check for "OR" dependencies for a specific feature ---
    # --- 为特定功能的 "或" 依赖关系进行特殊检查 ---
    if ! command -v xdelta3 >/dev/null 2>&1 && ! command -v bsdiff >/dev/null 2>&1; then
        warn "Delta package tools not found. To enable the 'create-delta' and 'delta-update' features, please install either 'xdelta3' (recommended) or 'bsdiff'."
        warn "未找到增量包工具。要启用 'create-delta' 和 'delta-update' 功能，请安装 'xdelta3' (推荐) 或 'bsdiff'。"
    fi
    
    info "正在创建基础目录结构... / Creating base directory structure..."
    
    # --- [最终修复] 在创建任何文件之前，先创建所有必需的目录 ---
    # --- [FINAL FIX] Create all necessary directories before creating any files ---
    # 1. (安全) 总是先确保所有目录都存在
    # 1. (Safe) Always ensure all directories exist first
    mkdir -p \
        "$ETC_CORIUM_DIR" \
        "$REPOS_CONF_DIR" \
        "$TRUST_ZONES_DIR/default" \
        "$VAR_LIB_CORIUM_DIR" \
        "$INSTALLED_DB" \
        "$EXTERNAL_PM_DB" \
        "$BLOCKCHAIN_DIR" \
        "$FORUM_DIR" \
        "$SNAPSHOTS_DIR" \
        "$DAPP_DATA_DIR" \
        "$MOD_DATA_DIR" \
        "$VAR_CACHE_CORIUM_DIR" \
        "$METADATA_CACHE_DIR" \
        "$SOURCE_CACHE" \
        "$BINARY_CACHE" \
        "$PEER_CERT_CACHE" \
        "$BUILD_TMP_DIR_BASE" \
        "$LOCK_DIR" \
        "$P2P_DIR" \
        "${VAR_LIB_CORIUM_DIR}/logs/agents"
    # --- [修复结束] ---
    
     # 2. (幂等) 创建所有基础配置文件 (如果它们不存在)
    # 2. (Idempotent) Create all base configuration files (if they don't exist)
    _init_create_default_files
    
    # 3. (幂等) 创建 corix.conf (如果它不存在)
    # 3. (Idempotent) Create corix.conf (if it doesn't exist)
    if [ ! -f "$CONFIG_FILE" ]; then
        info "正在生成主配置文件... / Generating main configuration file..."
        _init_generate_config_file
    else
        info "已找到现有的主配置文件，跳过生成。 / Existing main configuration file found, skipping generation."
    fi

    # 4. (幂等) 创建身份密钥 (如果不存在)
    # 4. (Idempotent) Create identity keys (if they don't exist)
    if [ ! -f "$USER_IDENTITY_FILE" ]; then
        info "正在创建密码学身份... / Generating cryptographic identity..."
        generate_keypair "$USER_IDENTITY_FILE" "$USER_PUBLIC_KEY_FILE" "$encrypt_flag"
        info "身份已生成 / Identity generated: $(cat "$USER_PUBLIC_KEY_FILE" | calculate_hash)"
    fi
    
    # 5. (幂等) 创建 TLS 证书 (如果不存在)
    # 5. (Idempotent) Create TLS certificate (if it doesn't exist)
    if [ ! -f "$TLS_CERT_FILE" ] || [ ! -f "$TLS_KEY_FILE" ]; then
        info "正在为P2P通信生成TLS证书... / Generating TLS certificate for P2P communication..."
        openssl req -x509 -newkey ec:<(openssl ecparam -name prime256v1) -keyout "$TLS_KEY_FILE" -out "$TLS_CERT_FILE" -nodes -days 3650 -subj "/CN=$(get_our_node_id)"
        chmod 600 "$TLS_KEY_FILE"
        info "TLS证书与私钥已生成。/ TLS certificate and private key generated."
    fi
    
    # 6. (幂等) 创建创世文件和区块 (如果不存在)
    # 6. (Idempotent) Create genesis file and block (if they don't exist)
    info "正在检查创世配置文件... / Checking for Genesis configuration file..."
    if [ ! -f "$GENESIS_CONFIG_FILE" ]; then
        msg "未找到创世文件。正在为新网络创建一个默认文件... / No genesis file found. Creating a default for a new network..."
        local my_public_key
        my_public_key=$(cat "$USER_PUBLIC_KEY_FILE")
        
        # 为创世承诺创建一个规范化的、已签名的载荷
        # Create a canonical, signed payload for the genesis commitment
        local reservations_payload
        reservations_payload="[{\"domains\":[\"corium\",\"nomen\",\"status\"],\"owner_id\":\"$(_internal_hash_text "$my_public_key")\"}]"
        local signature
        signature=$(sign_data "$reservations_payload" "$USER_IDENTITY_FILE")

        jq -n \
            --arg pubkey "$my_public_key" \
            --arg payload "$reservations_payload" \
            --arg sig "$signature" \
            '{
                "genesis_validators": [ { "public_key": $pubkey, "stake": 1000 } ],
                "nomen_genesis_commitment": {
                    "reservations_payload": $payload,
                    "signature": $sig
                }
            }' > "$GENESIS_CONFIG_FILE"
        info "默认创世文件已创建，您是第一个验证者。/ Default genesis file created with you as the first validator."
    fi

    info "正在初始化所有数据库... / Initializing all databases..."
    init_databases

    # Deterministic local integration tests need the durable node state without
    # inheriting long-lived consensus/P2P processes. Production keeps the
    # historical daemon startup path unless this explicit test-only switch is set.
    if [[ "$state_only" == "1" || "${CORIUM_TEST_NO_DAEMONS:-0}" == "1" ]]; then
        info "测试模式：已完成状态初始化，跳过常驻 daemon 启动。 / Test mode: state initialized; persistent daemons skipped."
        release_lock "system"
        return 0
    fi

    msg "正在启动 Corium 系统服务... / Starting Corium system services..."
    
    # --- 步骤 2: 创建一个临时的命名管道 (FIFO) 用于日志传递 ---
    local log_pipe
    local log_pipe_dir
    log_pipe_dir=$(mktemp -d -p "$BUILD_TMP_DIR_BASE" "startup-log.XXXXXX") || return 1
    CORIUM_TEMP_ITEMS+=("$log_pipe_dir")
    log_pipe="$log_pipe_dir/events"
    mkfifo -m 600 "$log_pipe" || return 1
    trap 'rm -f "$log_pipe"' RETURN # 确保管道文件总是被清理

    # --- 步骤 3: 在后台启动“发射程序” ---
    # 这个后台进程负责启动所有守护进程，并将主守护进程的日志导入管道。
    # 它在启动完所有任务后立即退出，让守护进程们被系统接管。
    (
        # 启动所有守护进程
        _internal_relayer_daemon >/dev/null 2>&1 &
        _consensus_daemon_loop &
        
        # 启动 dht_bootstrap，它内部会调用 dht_server_daemon。
        # 关键：我们将 dht_bootstrap 的标准错误流重定向到日志管道。
        dht_bootstrap 2> "$log_pipe" &
    ) &
    
    # --- 步骤 4: init 进程本身成为“地面控制中心”，监控发射过程 ---
    info "正在等待守护进程初始化... (日志将实时显示) / Waiting for daemons to initialize... (logs will be shown in real-time)"
    local startup_complete=0
    local timeout=45 # 增加超时以应对较慢的系统

    # 从管道读取日志，直到超时或看到成功信号
    while IFS= read -r -t "$timeout" line; do
        # 实时打印从管道中读到的日志
        echo "$line"
        
        # 检查我们等待的那条“启动成功”的关键日志
        if [[ "$line" == *"Agent resource monitor thread started"* ]]; then
            startup_complete=1
            # 即使成功了，我们也可以选择再多读几秒钟，以防后面紧跟着重要的信息
            # Even on success, we can choose to read for a few more seconds for any trailing important messages.
            sleep 2 
            break
        fi
        
        # 每次成功读取后，重置超时计时器
        timeout=30 
    done < "$log_pipe"

    # --- 步骤 5: 根据发射结果，向用户报告并退出 ---
    if [ "$startup_complete" -eq 1 ]; then
        msg "✅ 所有 Corium 服务已在后台成功启动！ / All Corium services have started successfully in the background!"
        
        # 恢复您原有的所有最终提示信息
        info "节点ID / Node ID: $(get_our_node_id)"
        info "You can run sudo corix setup-completion. It will only take effect after restarting the shell. / 你可以运行sudo corix setup-completion。然后重启Shell之后才会生效。"
        info "Also, please run corix setup-prover. / 另外，请也运行corix setup-prover。"

    else
        warn "⚠️ 守护进程启动超时或失败。请检查上面的日志。 / Daemon startup timed out or failed. Please check the logs above."
        warn "   您可能需要手动运行 'corix stop -f' 来清理任何残留的进程。 / You may need to manually run 'corix stop -f' to clean up any lingering processes."
    fi

    # 无论成功与否，init 命令到此结束，返还命令行
    release_lock "system"
}

# =======================================================================================
# --- [V97 UX] 命令行配置管理 (Command-Line Configuration Management)             ---
# =======================================================================================

# --- 配置管理 帮助函数 ---
# --- Configuration Management Help Function ---
usage_config() {
    echo "corix config: Safely manage settings in corix.conf."
    echo "corix config: 安全地管理 corix.conf 中的设置。"
    echo
    echo "Usage: corix config <subcommand> [arguments...]"
    echo "用法:  corix config <子命令> [参数...]"
    echo
    echo "Subcommands (子命令):"
    echo "  get <section.key>              Get the current value of a configuration key."
    echo "                                 (获取一个配置键的当前值)"
    echo "  set <section.key> <value>      Set a new value for a configuration key."
    echo "                                 (为一个配置键设置新值)"
    echo "  list                           List all current configurations from the file."
    echo "                                 (列出文件中的所有当前配置)"
}

# --- 配置管理 主分发器 ---
# --- Configuration Management Main Dispatcher ---
# --- [V103.3 最终修复] 配置管理 (更健壮的版本) ---
# =======================================================
# --- [V103.5 最终修复] 配置管理 (保留格式的健壮版) ---
# =======================================================
corix_config() {
    local sub_cmd="${1:-}"
    shift || true
    
    # 配置文件路径在函数外已经被正确设置
    if [ ! -f "$CONFIG_FILE" ]; then
        error "Configuration file not found: ${CONFIG_FILE}"
        info "Please run 'corix init' first to create it."
        return 1
    fi

    case "$sub_cmd" in
        get)
            [ $# -ne 1 ] && { usage_config; return 1; }
            local key_path="$1"
            local section="${key_path%%.*}"
            local key="${key_path#*.}"
            
            # 使用 awk 精确查找，避免匹配到注释
            awk -F'=' -v s="[${section}]" -v k="${key}" '
                $0 == s {in_section=1}
                /\[.*\]/ && $0 != s {in_section=0}
                in_section && $1 ~ "^[ \t]*" k "[ \t]*$" {
                    # 移除值前后的空格
                    val = $0; sub(/.*=[ \t]*/, "", val);
                    gsub(/^[ \t]+|[ \t]+$/, "", val);
                    print val;
                    exit;
                }
            ' "$CONFIG_FILE"
            ;;

        set)
            acquire_lock "system"
            trap 'release_lock "system"' RETURN
            [ $# -ne 2 ] && { usage_config; return 1; }
            local key_path="$1"
            local value="$2"
            local section="${key_path%%.*}"
            local key="${key_path#*.}"
            
            local temp_conf_file
            temp_conf_file=$(mktemp)
            
            # 这个修正后的 awk 脚本能够正确地：
            # 1. 找到正确的节（section）。
            # 2. 如果键（key）已存在，就更新它的值。
            # 3. 如果键不存在，就在正确的节内追加这个键值对。
            # 4. 如果连节都不存在，就在文件末尾创建节和键值对。
            awk -v section_name="${section}" -v key="${key}" -v value="${value}" '
                BEGIN { 
                    in_section = 0; 
                    key_found_and_updated = 0;
                    # 构建正确的正则表达式来匹配节，例如 `^\[p2p\]`
                    section_pattern = "^\\s*\\[" section_name "\\]\\s*$";
                    # 构建匹配键的正则表达式，例如 `^port\s*=`
                    key_pattern = "^\\s*" key "\\s*=";
                }

                # 匹配到目标节
                $0 ~ section_pattern {
                    in_section = 1;
                }

                # 匹配到任何其他节
                /^\s*\[.*\]/ && $0 !~ section_pattern {
                    # 如果我们刚离开目标节，但还没找到要更新的键，就在这里插入新键
                    if (in_section && !key_found_and_updated) {
                        print key " = " value;
                        key_found_and_updated = 1;
                    }
                    in_section = 0;
                }

                # 如果我们在目标节内，并且找到了要更新的键
                in_section && $0 ~ key_pattern {
                    # 替换整行，保留可能存在的前导空格
                    match($0, /^\s*/);
                    print substr($0, RSTART, RLENGTH) key " = " value;
                    key_found_and_updated = 1;
                    # 使用 next 跳过打印原始行
                    next;
                }
                
                # 打印所有其他行
                { print }

                END {
                    # 处理两种特殊情况：
                    # 1. 目标节存在，但要设置的键是该节的最后一个，或者该节为空
                    if (in_section && !key_found_and_updated) {
                        print key " = " value;
                        key_found_and_updated = 1;
                    }
                    # 2. 整个文件都没有找到目标节
                    if (!key_found_and_updated) {
                        print ""; # 为了格式美观，先加个换行
                        print "[" section_name "]";
                        print key " = " value;
                    }
                }
            ' "$CONFIG_FILE" > "$temp_conf_file"

            # 只有在 awk 成功执行后才替换原文件
            if [ $? -eq 0 ]; then
                mv "$temp_conf_file" "$CONFIG_FILE"
                msg "Configuration updated: ${key_path} = ${value}"
            else
                rm -f "$temp_conf_file"
                error "Failed to update configuration file."
            fi
            ;;
        
        list)
            msg "当前配置 / Current Configuration (${CONFIG_FILE}):"
            grep -vE '^\s*(#|;|$)' "$CONFIG_FILE"
            ;;

        *)
            usage_config
            ;;
    esac
}


# --- SECTION 11: PACKAGE MANAGEMENT CORE ---

# =======================================================
# --- [SECURITY HARDENED] - 增加了路径遍历防御
# =======================================================
get_pkg_id_parts() {
    local id="$1"
    local name_part="${id%%:*}"
    local slot_part="${id##*:}"

    PKG_CATEGORY="${name_part%/*}"
    [ "$PKG_CATEGORY" == "$name_part" ] && PKG_CATEGORY=""
    PKG_NAME="${name_part##*/}"
    
    # --- [安全加固] 路径遍历攻击防御 ---
    # 显式地禁止在包的分类和名称中使用 '..' 或 '/'
    # This prevents malicious package names like 'a/../../etc/passwd:0'
    case "$PKG_CATEGORY" in
      *..*|*/*)
        error "安全错误：软件包分类中包含无效字符。 / Security Error: Invalid characters in package category."
        exit 1
        ;;
    esac
    case "$PKG_NAME" in
      *..*|*/*)
        error "安全错误：软件包名称中包含无效字符。 / Security Error: Invalid characters in package name."
        exit 1
        ;;
    esac
    # --- [加固结束] ---

    if [ "$slot_part" == "$id" ]; then
        PKG_SLOT="0"
        PKG_SUBSLOT="0"
    else
        PKG_SLOT="${slot_part%/*}"
        [ "$PKG_SLOT" == "$slot_part" ] && PKG_SLOT="$slot_part"
        PKG_SUBSLOT="${slot_part##*/}"
        [ "$PKG_SUBSLOT" == "$PKG_SLOT" ] && PKG_SUBSLOT="0"
    fi
    return 0
}


find_package_build_file() {
    local pkg_name_full="$1" repo_conf repo_path repo_type repo_name cached
    get_pkg_id_parts "$pkg_name_full" || return 1
    local pkg_path="${PKG_CATEGORY}/${PKG_NAME}" build_file_path="${METADATA_CACHE_DIR}/paths/${PKG_CATEGORY}/${PKG_NAME}"
    if [ -f "$build_file_path" ]; then
        cached=$(cat "$build_file_path") || return 1
        if [ -f "$cached" ] && [ ! -L "$cached" ]; then printf '%s\n' "$cached"; return 0; fi
    fi
    while IFS= read -r -d '' repo_conf; do
        repo_type=$(sed -nE 's/^[[:space:]]*type[[:space:]]*=[[:space:]]*(.*)/\1/p' "$repo_conf" | xargs) || return 1
        if [ "$repo_type" = local ] || [ -z "$repo_type" ]; then
            repo_path=$(sed -nE 's/^[[:space:]]*path[[:space:]]*=[[:space:]]*(.*)/\1/p' "$repo_conf" | xargs) || return 1
        else
            repo_name=$(basename "$repo_conf" .conf); repo_path="$REPOS_DIR/$repo_name"
        fi
        if [ -n "$repo_path" ] && [ -f "$repo_path/$pkg_path/${pkg_path##*/}.build" ]; then
            printf '%s\n' "$repo_path/$pkg_path/${pkg_path##*/}.build"; return 0
        fi
    done < <(find "$REPOS_CONF_DIR" -name '*.conf' -type f -print0 | LC_ALL=C sort -z)
    return 1
}

# REVISED FOR SECURITY & ARRAY SUPPORT: This function now safely parses .build files
# without executing them, and correctly handles both string and array variables.
#
# 为安全与数组支持而修订: 此函数现在可以安全地解析 .build 文件而无需执行它们，
# 并且能正确处理字符串和数组类型的变量。
_parse_build_file() {
    [ $# -eq 1 ] && [ -f "$1" ] || return 1
    "${PYTHON_CMD}" - "$1" <<'PY_BUILD_METADATA'
import re,sys,shlex
allowed='pkgname pkgver pkgdesc url slot source sha256sums depends makedepends options corix_event_hooks corix_mod_type executable memory_limit_mb cpu_time_limit_s network_access persistent_service restart_policy unboxed_execution'.split()
lines=open(sys.argv[1],encoding='utf-8').readlines(); values={}; index=0; in_function=False
while index<len(lines):
    line=lines[index]; index+=1
    if re.match(r'^\s*(?:function\s+)?[a-zA-Z_][a-zA-Z0-9_]*\s*\(\s*\)\s*\{',line):
        in_function=not bool(re.search(r'\}\s*$',line)); continue
    if in_function:
        if re.match(r'^\}\s*(?:#.*)?$',line): in_function=False
        continue
    match=re.match(r'^\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*=(.*)$',line,re.S)
    if not match or match[1] not in allowed: continue
    name=match[1]; text=match[2].strip()
    if name in values: raise ValueError('Duplicate metadata field: '+name)
    while True:
        try:
            lexer=shlex.shlex(text,posix=True,punctuation_chars='()'); lexer.whitespace_split=True; lexer.commenters='#'
            tokens=list(lexer)
            if tokens==['()']: tokens=[]
            incomplete=tokens and tokens[0]=='(' and tokens[-1]!=')'
        except ValueError: incomplete=True
        if not incomplete: break
        if index>=len(lines): raise ValueError('Unterminated metadata field: '+name)
        text+='\n'+lines[index]; index+=1
    if tokens and tokens[0]=='(':
        if tokens[-1]!=')' or any(t in ('(',')') for t in tokens[1:-1]): raise ValueError('Invalid metadata array')
        value=' '.join(tokens[1:-1])
    else:
        if len(tokens)>1: raise ValueError('Unquoted scalar metadata: '+name)
        value=tokens[0] if tokens else ''
    if '\n' in value or '\r' in value or '\x00' in value: raise ValueError('Multiline metadata value')
    values[name]=value
# These values become existing cache and installation path components.
for field in ('pkgname','pkgver'):
    if field in values:
        value=values[field]
        if not value or '/' in value or value in ('.','..'): raise ValueError('Invalid metadata path component: '+field)
if 'slot' in values:
    if not re.fullmatch(r'[A-Za-z0-9._+-]+(?:/[A-Za-z0-9._+-]+)?',values['slot']) or any(part in ('.','..') for part in values['slot'].split('/')): raise ValueError('Invalid metadata slot')
for name in allowed: print(name+'='+values.get(name,'0' if name=='slot' else ''))
PY_BUILD_METADATA
}

# =======================================================
# --- FILE: corix.sh (NEW HELPER FUNCTION 1/1)        ---
# --- 文件: corix.sh (全新辅助函数 1/1)                 ---
# =======================================================

# Resolves a repository's root hash, supporting both static hashes and dynamic NNS domains.
# 解析一个仓库的根哈希，支持静态哈希和动态 NNS 域名两种方式。
#
# @param $1 - repo_conf_path (Path to the repository's .conf file / 仓库的 .conf 文件路径)
# @return The final P2P root hash to stdout, or empty string on failure.
#         向标准输出返回最终的 P2P 根哈希，如果失败则返回空字符串。
_resolve_repo_hash() {
    local repo_conf="$1"

    # 优先检查 nomen-name 配置
    # Prioritize checking for the nomen-name configuration
    local nomen_name
    nomen_name=$(grep -E '^\s*nomen-name\s*=' "$repo_conf" | cut -d'=' -f2- | xargs)

    if [ -n "$nomen_name" ]; then
        detail "  -> 正在通过 NNS 解析动态仓库 / Resolving dynamic repository via NNS: ${nomen_name}"
        # 调用内部的 NNS 解析函数
        # Call the internal NNS resolver function
        local resolved_hash
        resolved_hash=$(_internal_nns_resolve "$nomen_name")

        if [ -z "$resolved_hash" ]; then
            warn "   ! NNS 解析失败：无法找到域名 '${nomen_name}' 对应的哈希。 / NNS resolution failed: Could not find hash for domain '${nomen_name}'."
            return 1
        fi
        
        info "  -> NNS 解析成功 / NNS resolution successful: ${nomen_name} -> ${resolved_hash:0:32}..."
        echo "$resolved_hash"
        return 0
    fi

    # 如果没有 nomen-name，则回退到静态 hash 配置
    # If no nomen-name is found, fall back to the static hash configuration
    local static_hash
    static_hash=$(grep -E '^\s*hash\s*=' "$repo_conf" | cut -d'=' -f2- | xargs)
    
    if [ -n "$static_hash" ]; then
        detail "  -> 正在使用静态仓库哈希 / Using static repository hash: ${static_hash:0:32}..."
        echo "$static_hash"
        return 0
    fi

    # 如果两者都未找到，则报错
    # If neither is found, report an error
    warn "   ! 仓库配置错误：P2P 仓库必须定义 'nomen-name' 或 'hash'。 / Repository configuration error: P2P repository must define either 'nomen-name' or 'hash'."
    return 1
}

# =======================================================================================
# --- [V105.5 SECURITY] 内部辅助函数：获取新区块到暂存区 (最重链+检查点)           ---
# --- [V105.5 SECURITY] Internal Helper: Fetch New Blocks to Staging (Heaviest+WSC) ---
# =======================================================================================
# This function connects to the P2P network, robustly finds the tip of the heaviest
# chain, validates it against WSC, and downloads all missing blocks into a
# temporary staging database for pre-scan.
# 此函数连接P2P网络，健壮地找到最重链的链顶，对照WSC进行验证，并将所有缺失的
# 区块下载到一个临时的暂存数据库中，以供预扫描。
#
# @param $1 - staging_db_path
# @param $2 - last_known_height
# @return 0 on success, 1 on failure. Also returns the peer_id of the sync source via stdout.
#         成功返回0，失败返回1。同时通过stdout返回同步源的peer_id。
_internal_sync_fetch_new_blocks_to_stage() {
    _internal_consensus_safety_check || return 1
    local staging_db_path="$1" last_known_height="$2"
    local my_node_id; my_node_id=$(get_our_node_id) || return 1
    db_init "$staging_db_path" "
    CREATE TABLE IF NOT EXISTS staged_blocks (height INTEGER PRIMARY KEY, hash TEXT UNIQUE NOT NULL, data TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS staged_transactions (hash TEXT PRIMARY KEY, type TEXT NOT NULL, data TEXT NOT NULL, public_key TEXT NOT NULL, signature TEXT NOT NULL, timestamp INTEGER NOT NULL, block_height INTEGER NOT NULL);
    " || return 1
    info "[SYNC-FETCH] 正在查询最重链... / Querying heaviest chain..."
    local -a peers=() pids=()
    local peer_list
    peer_list=$(dht_find_closest_nodes "$my_node_id" 8) || {
        warn "[SYNC-FETCH] 未找到对等节点，无法确认同步状态。 / No peers found; synchronization is unverified."
        return 1
    }
    mapfile -t peers <<< "$peer_list"
    [ ${#peers[@]} -gt 0 ] || return 1
    local temp_state_dir; temp_state_dir=$(mktemp -d) || return 1
    CORIUM_TEMP_ITEMS+=("$temp_state_dir")
    local peer_addr_string
    for peer_addr_string in "${peers[@]}"; do
        (
            _parse_full_address "$peer_addr_string" || exit 1
            local peer_id="$ADDR_NODE_ID" response
            [[ "$peer_id" =~ ^[a-f0-9]{64}$ ]] || exit 1
            response=$(dht_send_message "$peer_id" "GET_CHAIN_STATE" "") || exit 1
            if [[ "$response" =~ ^[a-f0-9]{64}\|[0-9]{1,10}\|[0-9]{1,19}$ ]]; then
                printf '%s|%s\n' "$response" "$peer_id" > "$temp_state_dir/$peer_id"
            fi
        ) &
        pids+=("$!")
    done
    wait_all 10 "${pids[@]}" || true
    local best_chain_weight=-1 best_chain_height=-1 best_chain_hash="" best_chain_peer_id=""
    local state_file hash height weight peer_id
    for state_file in "$temp_state_dir"/*; do
        [ -f "$state_file" ] || continue
        IFS='|' read -r hash height weight peer_id < "$state_file" || continue
        # Decimal validation before shell arithmetic prevents overflow and octal input.
        "${PYTHON_CMD}" - "$height" "$weight" <<'PY_CHAIN_NUM'
import sys
for value in sys.argv[1:]:
    if str(int(value))!=value or not 0<=int(value)<=9223372036854775807: sys.exit(1)
PY_CHAIN_NUM
        [ $? -eq 0 ] || continue
        if [ "$weight" -gt "$best_chain_weight" ]; then
            best_chain_weight="$weight"; best_chain_height="$height"; best_chain_hash="$hash"; best_chain_peer_id="$peer_id"
        fi
    done
    rm -rf -- "$temp_state_dir"
    [ -n "$best_chain_hash" ] || { warn "[SYNC-FETCH] 没有有效的对等节点响应。 / No valid peer response."; return 1; }
    local local_weight; local_weight=$(db_query_static "$BLOCKCHAIN_DB" "SELECT COALESCE(MAX(total_weight),0) FROM blocks;") || return 1
    [ "$best_chain_weight" -gt "$local_weight" ] || return 0
    if [ -n "$BLOCKCHAIN_WSC" ]; then
        local checkpoint chk_height chk_hash_prefix remote_hash_at_height
        local -a checkpoints=(); IFS=',' read -r -a checkpoints <<< "$BLOCKCHAIN_WSC"
        for checkpoint in "${checkpoints[@]}"; do
            IFS=':' read -r chk_height chk_hash_prefix <<< "$checkpoint"
            [[ "$chk_height" =~ ^(0|[1-9][0-9]{0,9})$ && "$chk_hash_prefix" =~ ^[a-f0-9]{1,64}$ ]] || return 1
            if [ "$chk_height" -le "$best_chain_height" ]; then
                remote_hash_at_height=$(dht_send_message "$best_chain_peer_id" "GET_BLOCK_HASH_AT_HEIGHT" "$chk_height") || return 1
                [[ "$remote_hash_at_height" =~ ^[a-f0-9]{64}$ && "$remote_hash_at_height" == "$chk_hash_prefix"* ]] || return 1
            fi
        done
    fi
    db_begin_transaction "$staging_db_path" || return 1
    local current_hash_to_fetch="$best_chain_hash" block_json tx_hash tx_obj_json h
    for ((h=best_chain_height; h>=0; h--)); do
        # Fetch to the common ancestor, including competing branches of equal height.
        [ -z "$(db_query_safe "$BLOCKCHAIN_DB" "SELECT hash FROM blocks WHERE hash=%s;" "$current_hash_to_fetch")" ] || break
        [ "$h" -gt 0 ] || { db_rollback_transaction "$staging_db_path"; return 1; }
        block_json=$(dht_send_message "$best_chain_peer_id" "GET_FULL_BLOCK" "$current_hash_to_fetch") || return 1
        [[ "$block_json" == BLOCK:* ]] || return 1
        block_json="${block_json#BLOCK:}"
        jq -e --argjson h "$h" 'type=="object" and .height==$h and (.previous_hash|type=="string" and test("^[a-f0-9]{64}$")) and (.transactions|type=="array" and all(.[];type=="string" and test("^[a-f0-9]{64}$")) and length==(unique|length))' <<< "$block_json" >/dev/null || return 1
        db_execute_safe "$staging_db_path" "INSERT INTO staged_blocks VALUES (%d,%s,%s);" "$h" "$current_hash_to_fetch" "$block_json" || return 1
        while IFS= read -r tx_hash; do
            tx_obj_json=$(dht_send_message "$best_chain_peer_id" "GET_TRANSACTION" "$tx_hash") || return 1
            jq -e 'type=="object" and (.type|type=="string") and (.data|type=="object") and (.public_key|type=="string") and (.signature|type=="string") and (.timestamp|type=="number" and floor==. and .>=0 and .<=9007199254740991)' <<< "$tx_obj_json" >/dev/null || return 1
            db_execute_safe "$staging_db_path" "INSERT INTO staged_transactions VALUES (%s,%s,%s,%s,%s,%d,%d);" "$tx_hash" "$(jq -r .type <<< "$tx_obj_json")" "$(jq -c .data <<< "$tx_obj_json")" "$(jq -r .public_key <<< "$tx_obj_json")" "$(jq -r .signature <<< "$tx_obj_json")" "$(jq -r .timestamp <<< "$tx_obj_json")" "$h" || return 1
        done < <(jq -r '.transactions[]' <<< "$block_json")
        current_hash_to_fetch=$(jq -er .previous_hash <<< "$block_json") || return 1
    done
    db_commit_transaction "$staging_db_path" || return 1
    printf '%s\n' "$best_chain_peer_id"
}

# =======================================================================================
# --- [V105.5 FINAL] corix_sync (带仓库同步与两阶段安全提交的最终版)               ---
# --- [V105.5 FINAL] corix_sync (Final Version with Repo Sync & 2PC Security)       ---
# =======================================================================================
# This is the definitive, production-ready sync function. It seamlessly integrates:
# 1. Synchronization of all repository types (local, git, p2p).
# 2. A two-phase commit model for blockchain synchronization, featuring:
#    - Heaviest chain discovery to prevent simple fork attacks.
#    - Weak Subjectivity Checkpoint (WSC) validation to defeat long-range attacks.
#    - Automated purification of the sync plan by processing in-band veto transactions.
#
# 这是确定性的、生产就绪的同步函数。它无缝整合了：
# 1. 所有仓库类型（本地、git、p2p）的同步。
# 2. 用于区块链同步的两阶段提交模型，其特性包括：
#    - 最重链发现，以防止简单的分叉攻击。
#    - 弱主观性检查点（WSC）验证，以抵御长程攻击。
#    - 通过处理带内否决交易，自动净化同步计划。
# =======================================================================================
# --- [V105.5 FINAL] corix_sync (带仓库同步与两阶段安全提交的最终版)               ---
# --- [BUGFIX APPLIED] - 修正了单机网络下不更新搜索索引的问题
# =======================================================================================
# =======================================================================================
# --- [FINAL BUGFIX V3] - 确保 sync 命令同时更新所有必要的缓存
# =======================================================================================
corix_sync() (
    set -e
    local scope="${1:-full}"
    [[ "$scope" == full || "$scope" == --repositories-only ]] && [ "$#" -le 1 ] || return 2
    check_permissions "sync"
    acquire_lock "network"
    local staging_db; staging_db=$(mktemp)
    trap 'status=$?; _internal_db_rollback_all_active; release_lock "network"; rm -f "$staging_db"; exit "$status"' EXIT
    
    msg "正在同步所有仓库和网络内容... / Syncing all repositories and network content..."
    _run_hooks "pre-sync"
    
    # --- 阶段 0: 同步软件仓库 (Git, P2P, etc.) ---
    info "[SYNC-REPOS] 正在同步所有已配置的软件包仓库... / Syncing all configured package repositories..."
    local repo_conf
    while IFS= read -r -d '' repo_conf; do
        local repo_name type; repo_name=$(basename "$repo_conf" .conf)
        type=$(grep -E '^\s*type\s*=' "$repo_conf" | cut -d'=' -f2- | xargs)
        
        detail "[SYNC-REPOS]  -> 正在处理仓库 / Processing repository: $repo_name (type: $type)"
        case "$type" in
            local)
                detail "  -> 本地仓库，无需网络同步。 / Local repository, no network sync needed."
                ;;
            git)
                local url branch repo_path
                url=$(grep -E '^\s*url\s*=' "$repo_conf" | cut -d'=' -f2- | xargs)
                branch=$(grep -E '^\s*branch\s*=' "$repo_conf" | cut -d'=' -f2- | xargs)
                repo_path="${REPOS_DIR}/${repo_name}"
                
                if [ -d "$repo_path/.git" ]; then
                    detail "  -> 正在更新已存在的克隆... / Updating existing clone..."
                    (cd "$repo_path" && git pull origin "$branch") || warn "  -> 更新仓库 '$repo_name' 失败。 / Failed to update repository '$repo_name'."
                else
                    detail "  -> 正在克隆新仓库... / Cloning new repository..."
                    git clone --depth 1 --branch "$branch" "$url" "$repo_path" || warn "  -> 克隆仓库 '$repo_name' 失败。 / Failed to clone repository '$repo_name'."
                fi
                ;;
            p2p)
                local repo_hash; repo_hash=$(_resolve_repo_hash "$repo_conf")
                local repo_path="${REPOS_DIR}/${repo_name}"
                
                if [ -n "$repo_hash" ]; then
                    p2p_sync_repository "$repo_name" "$repo_hash" || return 1
                else
                    warn "  -> 跳过 P2P 仓库 '$repo_name' 因为无法确定其根哈希。 / Skipping P2P repository '$repo_name' due to unresolved root hash."
                fi
                ;;
        esac
    done < <(find "${REPOS_CONF_DIR}" -name "*.conf" -type f -print0 | sort -z)
    
    # --- [核心修正] 在仓库同步后，更新所有缓存 ---
    _update_metadata_cache
    corix_search_update_index >/dev/null
    if [ "$scope" = --repositories-only ]; then
        _run_hooks "post-sync"
        return 0
    fi

    # --- 阶段 1: 预取与预扫描 (区块链部分) ---
    local last_processed_height; last_processed_height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT COALESCE((SELECT value FROM chain_state WHERE key = 'last_processed_height'),'-1');") || return 1
    
    local best_peer_id
    if ! best_peer_id=$(_internal_sync_fetch_new_blocks_to_stage "$staging_db" "${last_processed_height:--1}"); then
        error "[SYNC] 从网络获取新区块失败。同步中止。 / Failed to fetch new blocks from the network. Sync aborted."
        return 1
    fi

    local new_blocks_count; new_blocks_count=$(db_query_static "$staging_db" "SELECT COUNT(*) FROM staged_blocks;")
    if [ "$new_blocks_count" -eq 0 ]; then
        msg "区块链状态已是最新。 / Blockchain state is already up-to-date."
        _update_chain_state_cache
        _run_hooks "post-sync"; blockchain_mine_block
        return 0
    fi

    # Vetoes invalidate transactions, never remove a block from its signed ancestry.
    # 否决仅作用于交易；不能跳过区块后仍然接纳其子块。
    local veto_count; veto_count=$(db_query_static "$staging_db" "SELECT COUNT(*) FROM staged_transactions WHERE type='state_correction_tx';") || return 1
    info "[SYNC-PLAN] 候选区块 / Candidate blocks: $new_blocks_count; 状态修正 / State corrections: $veto_count"
    local choice
    read -rp "是否继续执行同步？[Y/n] / Proceed with synchronization? [Y/n] " choice || return 1
    if [[ "$choice" =~ ^[nN]$ ]]; then msg "同步已取消。 / Sync cancelled."; return 1; fi
    local peer_ip peer_port peer_address
    peer_address=$(db_query_safe "$DHT_DB" "SELECT address,port FROM nodes WHERE id=%s ORDER BY address_type,address,port LIMIT 1;" "$best_peer_id") || return 1
    [ -n "$peer_address" ] || return 1
    IFS='|' read -r peer_ip peer_port <<< "$peer_address"
    # Journal staged transactions as well as derived state before validation.
    db_begin_transaction "$BLOCKCHAIN_DB" "$FORUM_DB" "$DHT_DB" || return 1
    local row
    while IFS= read -r row; do
        db_execute_safe "$BLOCKCHAIN_DB" "INSERT OR IGNORE INTO transactions (hash,type,data,public_key,signature,timestamp,block_height) VALUES (%s,%s,%s,%s,%s,%d,NULL);" \
            "$(jq -er '.[0]' <<< "$row")" "$(jq -er '.[1]' <<< "$row")" "$(jq -er '.[2]' <<< "$row")" \
            "$(jq -er '.[3]' <<< "$row")" "$(jq -er '.[4]' <<< "$row")" "$(jq -er '.[5]' <<< "$row")" || return 1
    done < <(db_query_static "$staging_db" "SELECT json_array(hash,type,data,public_key,signature,timestamp) FROM staged_transactions;")
    local tip; tip=$(db_query_static "$staging_db" "SELECT hash FROM staged_blocks ORDER BY height DESC LIMIT 1;") || return 1
    _blockchain_reorganize_to "$tip" "$peer_ip" "$peer_port" || return 1
    db_commit_transaction "$BLOCKCHAIN_DB" "$FORUM_DB" "$DHT_DB" || return 1

    # --- 阶段 4: 触发最终的状态更新与后同步任务 ---
    _update_chain_state_cache
    _run_hooks "post-sync"
    blockchain_mine_block
    
    msg "同步完成。 / Sync complete."
)


# Sync P2P repository
# 同步 P2P 仓库
p2p_sync_repository() (
    set -e
    local repo_name="$1" repo_hash="$2"
    [[ "$repo_name" =~ ^[A-Za-z0-9_.-]+$ && "$repo_name" != . && "$repo_name" != .. ]] || return 1
    local repo_path="${REPOS_DIR}/${repo_name}" temporary backup="" committed=false
    mkdir -p "$REPOS_DIR" || return 1
    [ ! -L "$repo_path" ] || return 1
    temporary=$(mktemp -d "$REPOS_DIR/.sync.XXXXXX") || return 1
    trap 'status=$?; if ! $committed && [ -n "$backup" ]; then rm -rf -- "$repo_path"; mv -- "$backup" "$repo_path" || status=1; fi; rm -rf -- "$temporary"; exit "$status"' EXIT
    _download_file_p2p "$repo_hash" "$temporary/archive.tar.gz" || return 1
    _validate_archive "$temporary/archive.tar.gz" || return 1
    mkdir "$temporary/repo" || return 1
    tar --no-same-owner -C "$temporary/repo" -xzf "$temporary/archive.tar.gz" || return 1
    if [ -e "$repo_path" ]; then
        backup="$temporary/original"
        mv -- "$repo_path" "$backup" || return 1
    fi
    mv -- "$temporary/repo" "$repo_path" || return 1
    committed=true
    msg "P2P 仓库同步完成。 / P2P repository synchronized: $repo_name"
)

# --- SECTION 12: DATABASE MANAGEMENT ---

db_get_pkg_dir() { 
    echo "${INSTALLED_DB}/${1//\//_}-${2}" 
}

_installed_package_ids() {
    local directory
    [ -d "$INSTALLED_DB" ] || return 0
    for directory in "$INSTALLED_DB"/*; do
        [ -d "$directory" ] && [ -r "$directory/name" ] && [ -r "$directory/slot" ] || continue
        printf '%s:%s\n' "$(cat "$directory/name")" "$(cat "$directory/slot")"
    done
}

db_is_installed() { 
    get_pkg_id_parts "$1"
    local pkg_dir
    pkg_dir=$(db_get_pkg_dir "$PKG_CATEGORY/$PKG_NAME" "$PKG_SLOT")
    [ -d "$pkg_dir" ]
}

db_register_package() {
    local pkg_name="$1"
    local pkg_ver="$2" 
    local pkg_slot="$3"
    local files_manifest="$4"
    local deps_list="$5"
    local build_file="$6" artifact_file="${7:-$4}"
    local pkg_dir
    pkg_dir=$(db_get_pkg_dir "$pkg_name" "$pkg_slot")
    
    mkdir -p "$pkg_dir"
    echo "$pkg_ver" > "$pkg_dir/version"
    echo "$pkg_name" > "$pkg_dir/name"
    echo "$pkg_slot" > "$pkg_dir/slot"
    echo "$deps_list" > "$pkg_dir/dependencies"
    cp "$build_file" "$pkg_dir/build_file"
    cp "$files_manifest" "$pkg_dir/files"
    date -u --rfc-3339=seconds > "$pkg_dir/install_date"
    
    # Register package on blockchain
    local pkg_hash
    pkg_hash=$(calculate_hash "$artifact_file") || return 1
    local build_hash
    build_hash=$(calculate_hash "$build_file")
    blockchain_register_package "$pkg_name" "$pkg_ver" "$pkg_hash" "$build_hash"
}

db_unregister_package() { 
    local pkg_dir
    pkg_dir=$(db_get_pkg_dir "$1" "$2")
    [ -d "$pkg_dir" ] && rm -rf "$pkg_dir"
}

db_get_package_files() { 
    local pkg_dir
    pkg_dir=$(db_get_pkg_dir "$1" "$2")
    [ -f "$pkg_dir/files" ] && cat "$pkg_dir/files"
}

# =======================================================
# --- [PERFORMANCE] Metadata Cache Functions          ---
# --- [性能优化] 元数据缓存函数                        ---
# =======================================================

# Defines the path for the new metadata SQLite database.
# 定义新的元数据 SQLite 数据库的路径。
readonly METADATA_CACHE_DB="${METADATA_CACHE_DIR}/meta.db"

# Updates the metadata cache by parsing all .build files.
# Should be called after 'corix sync'.
# 通过解析所有 .build 文件来更新元数据缓存。
# 应该在 'corix sync' 之后调用。
_update_metadata_cache() {
    msg "Updating package metadata cache... / 正在更新软件包元数据缓存..."
    
    # [修正部分 A] 升级数据库 Schema，增加 source_repo 列（此操作只会成功执行一次）
    db_init "$METADATA_CACHE_DB" "
    CREATE TABLE IF NOT EXISTS packages (
        id TEXT PRIMARY KEY,
        version TEXT NOT NULL,
        depends TEXT,
        makedepends TEXT,
        source_repo TEXT
    );
    "

    if [ "$(db_query_static "$METADATA_CACHE_DB" "SELECT COUNT(*) FROM pragma_table_info('packages') WHERE name='source_repo';")" -eq 0 ]; then
        db_execute_safe "$METADATA_CACHE_DB" "ALTER TABLE packages ADD COLUMN source_repo TEXT;" || return 1
    fi
    local temp_sql_file repo_conf build_file; temp_sql_file=$(mktemp) || return 1
    CORIUM_TEMP_ITEMS+=("$temp_sql_file")
    
    echo "BEGIN TRANSACTION;" > "$temp_sql_file"

    while IFS= read -r -d '' repo_conf; do
        local repo_name type path_to_scan
        repo_name=$(basename "$repo_conf" .conf)
        type=$(grep -E '^\s*type\s*=' "$repo_conf" | cut -d'=' -f2- | xargs)
        
        if [ "$type" = "local" ]; then
            path_to_scan=$(grep -E '^\s*path\s*=' "$repo_conf" | cut -d'=' -f2- | xargs)
        else
            path_to_scan="${REPOS_DIR}/${repo_name}"
        fi

        if [ -n "$path_to_scan" ] && [ -d "$path_to_scan" ]; then
            detail "  -> Caching metadata from repository '${repo_name}'..."
            
            # [修正部分 B] 在处理这个仓库之前，先删除所有源自于它的旧记录
            local repo_name_sql="'${repo_name//\'/\'\'}'"
            echo "DELETE FROM packages WHERE source_repo = ${repo_name_sql};" >> "$temp_sql_file"
            
            while IFS= read -r -d '' build_file; do
                local meta pkgname slot version depends makedepends pkg_dir_relative pkg_id_full
                meta=$(_parse_build_file "$build_file") || { rm -f "$temp_sql_file"; return 1; }
                
                pkgname=$(echo "$meta" | grep "^pkgname=" | cut -d= -f2)
                slot=$(echo "$meta" | grep "^slot=" | cut -d= -f2)
                version=$(echo "$meta" | grep "^pkgver=" | cut -d= -f2)
                depends=$(echo "$meta" | grep "^depends=" | cut -d= -f2- | tr '\n' ' ' | xargs)
                makedepends=$(echo "$meta" | grep "^makedepends=" | cut -d= -f2- | tr '\n' ' ' | xargs)
                
                # [修正部分 C - 路径解析]
                pkg_dir_relative=$(dirname "${build_file#$path_to_scan/}")
                pkg_id_full="${pkg_dir_relative}:${slot}"
                
                local id_sql version_sql depends_sql makedepends_sql repo_name_sql
                id_sql="'${pkg_id_full//\'/\'\'}'"
                version_sql="'${version//\'/\'\'}'"
                depends_sql="'${depends//\'/\'\'}'"
                makedepends_sql="'${makedepends//\'/\'\'}'"
                repo_name_sql="'${repo_name//\'/\'\'}'"

                # [修正部分 D] 插入时包含 source_repo
                echo "INSERT OR REPLACE INTO packages (id, version, depends, makedepends, source_repo) VALUES (${id_sql}, ${version_sql}, ${depends_sql}, ${makedepends_sql}, ${repo_name_sql});" >> "$temp_sql_file"
                
            done < <(find "$path_to_scan" -name '*.build' -type f -print0 | LC_ALL=C sort -z)
        fi
    done < <(find "$REPOS_CONF_DIR" -name '*.conf' -type f -print0 | LC_ALL=C sort -z)

    echo "COMMIT;" >> "$temp_sql_file"
    
    if ! sqlite3 -bail "$METADATA_CACHE_DB" < "$temp_sql_file"; then
        error "更新元数据缓存时发生数据库错误。 / A database error occurred while updating the metadata cache."
        return 1
    fi
    
    rm -f -- "$temp_sql_file" || return 1
    info "Metadata cache updated successfully. / 元数据缓存更新成功。"
}


# Retrieves a package's metadata from the cache.
# 从缓存中获取一个软件包的元数据。
# @return A string with fields separated by '|' (id|version|depends|makedepends)
# @返回 一个由'|'分隔的字符串 (id|版本|依赖|构建依赖)
_get_pkg_meta_from_cache() {
    local pkg_id="$1"
    # 绕过有问题的 db_query_safe，使用直接的、经过安全转义的查询。
    # Bypass the problematic db_query_safe and use a direct, safely escaped query.
    local safe_pkg_id="${pkg_id//\'/\'\'}" # Escape single quotes for safety.
    db_query_safe "$METADATA_CACHE_DB" "SELECT id, version, depends, makedepends FROM packages WHERE id=%s;" "$pkg_id"
}

# --- SECTION 13: DEPENDENCY RESOLUTION ---

dep_check_external() {
    local dep="$1"
    for pm_db in "$EXTERNAL_PM_DB"/*.db; do
        [ -f "$pm_db" ] || continue
        if awk -v dep="$dep" '$1==dep {found=1} END {exit !found}' "$pm_db"; then
            return 0
        fi
    done
    return 1
}

# Resolves a dependency graph using a topological sort (Kahn's algorithm).
# It correctly handles native Corium packages and Mod packages.
# 使用拓扑排序 (Kahn算法) 来解析依赖关系图。
# 它可以正确处理原生的 Corium 软件包和 Mod 软件包。
#
# @param $@ - A list of initial packages to resolve. / 要解析的初始软件包列表。
# @return A space-separated list of packages in the correct installation order. / 以空格分隔的、按正确安装顺序列出的软件包。
# Resolves a dependency graph using a topological sort (Kahn's algorithm).
# It correctly handles native Corium packages and Mod packages.
# 使用拓扑排序 (Kahn算法) 来解析依赖关系图。
# 它可以正确处理原生的 Corium 软件包和 Mod 软件包。
#
# @param $@ - A list of initial packages to resolve. / 要解析的初始软件包列表。
# @return A space-separated list of packages in the correct installation order. / 以空格分隔的、按正确安装顺序列出的软件包。
dep_resolve_topological() {
    acquire_lock "network"
    trap 'release_lock "network"' RETURN

    local initial_pkgs=("$@")
    declare -A adj_list=() in_degree=() pkg_info=() edges=()
    local -A initial_set=()
    local initial
    for initial in "$@"; do [[ "$initial" == *:* ]] || initial="$initial:0"; initial_set["$initial"]=1; done
    local pkg_queue=() final_order=()
    
    pkg_queue+=("${initial_pkgs[@]}")
    local processed_pkgs=()
    local i=0
    
    while [ $i -lt ${#pkg_queue[@]} ]; do
        local pkg="${pkg_queue[$i]}"
        i=$((i+1))
        
        if [[ "$pkg" != *":"* ]]; then
            pkg="${pkg}:0"
        fi

        [[ " ${processed_pkgs[*]} " =~ " ${pkg} " ]] && continue
        processed_pkgs+=("$pkg")

        if db_is_installed "$pkg" || dep_check_external "$pkg"; then
            local is_initial=0
            for initial_pkg in "${initial_pkgs[@]}"; do
                local normalized_initial_pkg="$initial_pkg"
                if [[ "$normalized_initial_pkg" != *":"* ]]; then
                    normalized_initial_pkg="${normalized_initial_pkg}:0"
                fi
                if [ "$pkg" = "$normalized_initial_pkg" ]; then
                    is_initial=1; break;
                fi
            done
            if [ "$is_initial" -eq 0 ] && [ "${CORIUM_DEP_RESOLVE_ALL:-0}" != 1 ]; then continue; fi
        fi

        [[ "$pkg" =~ ^[a-zA-Z0-9][a-zA-Z0-9._+/-]*:[a-zA-Z0-9._+-]+(/[a-zA-Z0-9._+-]+)?$ ]] || return 1
        local meta
        meta=$(_get_pkg_meta_from_cache "$pkg") || return 1
        [ -z "$meta" ] && error "无法解析 '${pkg}': 在元数据缓存中未找到。请运行 'corix sync'。 / Cannot resolve '${pkg}': not found in metadata cache. Please run 'corix sync'."
        
        pkg_info["$pkg"]="$meta"
        [ -z "${in_degree[$pkg]+_}" ] && in_degree["$pkg"]=0
        
        local depends
        depends=$(echo "$meta" | cut -d'|' -f3)
        local makedepends
        makedepends=$(echo "$meta" | cut -d'|' -f4)
        local all_deps="${depends} ${makedepends}"
        
        # --- [最终核心修正 V3] ---
        # 使用 xargs 来剔除所有空格，然后检查字符串是否为空。
        # 这可以正确处理 all_deps 只包含空格的情况。
        # Use xargs to trim all whitespace and then check if the string is empty.
        # This correctly handles the case where all_deps contains only spaces.
        if [ -n "$(echo "$all_deps" | xargs)" ]; then
            for dep in $all_deps; do
                [ -n "$dep" ] || continue
                
                if [[ "$dep" != *":"* ]]; then
                    dep="${dep}:0"
                fi

                [[ "$dep" =~ ^[a-zA-Z0-9][a-zA-Z0-9._+/-]*:[a-zA-Z0-9._+-]+(/[a-zA-Z0-9._+-]+)?$ ]] || return 1
                if [ -z "${initial_set[$dep]+set}" ] && [ "${CORIUM_DEP_RESOLVE_ALL:-0}" != 1 ] && { db_is_installed "$dep" || dep_check_external "$dep"; }; then continue; fi
                [ -z "${edges[$dep|$pkg]+set}" ] || continue
                edges["$dep|$pkg"]=1
                adj_list["$dep"]="${adj_list[$dep]-} $pkg"
                in_degree["$pkg"]=$((in_degree["$pkg"] + 1))
                pkg_queue+=("$dep")
            done
        fi
        # --- [修正结束] ---
    done

    local queue=()
    for pkg in "${!in_degree[@]}"; do
        if [ "${in_degree[$pkg]}" -eq 0 ]; then 
            queue+=("$pkg")
        fi
    done

    while [ ${#queue[@]} -gt 0 ]; do
        local u="${queue[0]}"
        queue=("${queue[@]:1}")
        final_order+=("$u")
        
        for v in ${adj_list[$u]-}; do
            in_degree["$v"]=$((in_degree["$v"] - 1))
            if [ "${in_degree[$v]}" -eq 0 ]; then 
                queue+=("$v")
            fi
        done
    done
    
    # adj_list: Adjacency list for the graph (dep -> pkg) / 邻接表
    # in_degree: Stores the number of incoming edges for each package / 存储每个包的入度
    # pkg_info: Caches parsed .build file metadata for performance / 缓存已解析的.build文件元数据以提高性能
    # [V105 BUG FIX] Explicitly initialize arrays to prevent 'unbound variable' errors on empty input.
    # [V105 BUG修复] 显式初始化数组以防止在输入为空时出现 'unbound variable' 错误。

    # --- 步骤 3: 循环依赖检测 ---
    # --- Step 3: Circular Dependency Detection ---
    if [ "${#final_order[@]}" -ne "${#in_degree[@]}" ]; then
        error "循环依赖检测到！无法解析安装顺序。 / Circular dependency detected! Cannot resolve installation order."
        info "以下是可能涉及循环的软件包及其依赖关系: / The following packages and their dependencies may be involved in the cycle:"
        declare -A final_order_map
        for pkg in "${final_order[@]}"; do final_order_map["$pkg"]=1; done
        for pkg in "${!in_degree[@]}"; do
            if [ -z "${final_order_map[$pkg]+_}" ]; then
                local deps
                deps=$(echo "${pkg_info[$pkg]}" | cut -d'|' -f3)
                echo -e "  -> \033[1;31m${pkg}\033[0m"
                [ -n "$deps" ] && echo "     依赖于 / depends on: $deps" || echo "     (无显式依赖 / no explicit dependencies)"
            fi
        done
        # Do not release lock here, trap will handle it.
        # 此处不释放锁，trap会处理。
        exit 1
    fi

    # --- 步骤 4: 过滤并返回最终安装列表 ---
    # --- Step 4: Filter and return the final installation list ---
    local to_install=()
    for pkg in "${final_order[@]}"; do
        if [ "${CORIUM_DEP_RESOLVE_ALL:-0}" = 1 ]; then
            to_install+=("$pkg")
        elif db_is_installed "$pkg"; then
            get_pkg_id_parts "$pkg"
            local installed_version
            installed_version=$(cat "$(db_get_pkg_dir "$PKG_CATEGORY/$PKG_NAME" "$PKG_SLOT")/version") || return 1
            if [ "$installed_version" != "$(cut -d'|' -f2 <<< "${pkg_info[$pkg]}")" ]; then to_install+=("$pkg"); fi
        elif ! dep_check_external "$pkg"; then
            to_install+=("$pkg")
        fi
    done
    echo "${to_install[*]}"
}



# =======================================================================================
# --- SECTION 32: CLI - WIKI & NOMEN WEB (WIKI COMMANDS)                              ---
# --- 第32节: 命令行界面 - 维基与Nomen网络 (维基命令)                                 ---
# =======================================================================================

# Displays detailed help for the wiki command.
# 显示 wiki 命令的详细帮助信息。
usage_wiki() {
    echo "corix wiki: A decentralized, version-controlled wiki system for groups."
    echo "corix wiki: 一个为群组设计的、去中心化的、版本控制的维基系统。"
    echo
    echo "Usage: corix wiki <subcommand> [arguments...]"
    echo "用法:  corix wiki <子命令> [参数...]"
    echo
    echo "Subcommands (子命令):"
    echo "  list <group_id>"
    echo "      List all wiki pages within a group. / 列出群组内的所有维基页面。"
    echo "  create <group_id>/<page_slug> --file <path> --message \"...\" [--attach <dir>]"
    echo "      Create a new wiki page from a local file. / 从本地文件创建一个新的维基页面。"
    echo "  show <group_id>/<page_slug> [--version <tx_hash>]"
    echo "      Display the content of a wiki page (latest or specific version)."
    echo "      (显示维基页面的内容 (最新或指定版本))"
    echo "  edit <group_id>/<page_slug>"
    echo "      Lock, download, open in editor, and submit changes for a page."
    echo "      (锁定、下载、在编辑器中打开并提交对页面的更改)"
    echo "  history <group_id>/<page_slug>"
    echo "      Show the version history of a page. / 显示页面的版本历史。"
    echo "  status <group_id>/<page_slug>"
    echo "      Check the lock status of a page. / 检查页面的锁定状态。"
    echo "  unlock <group_id>/<page_slug>"
    echo "      Manually release a lock you hold on a page. / 手动释放您持有的页面锁。"
}

# The user-facing command dispatcher for 'corix wiki'.
# 'corix wiki' 的用户侧命令分发器。
corix_wiki() {
    acquire_lock "network"
    trap 'release_lock "network"' RETURN

    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        list)
            [ $# -ne 1 ] && { usage_wiki; exit 1; }
            local group_id="$1"
            msg "Wiki pages in group '${group_id:0:16}...': / 群组 '${group_id:0:16}...' 中的维基页面:"
            db_query_safe "$FORUM_DB" "SELECT slug, latest_version_hash FROM wiki_pages WHERE group_id = %s;" "$group_id" | while IFS='|' read -r slug hash; do
                echo "  - ${slug}  (Version: ${hash:0:16}...)"
            done
            ;;
        create)
            local group_slug="" file_path="" commit_message="" attachment_dir=""
            group_slug="${1:-}"; shift || true
            while [ $# -gt 0 ]; do
                case "$1" in
                    --file) file_path="$2"; shift 2 ;;
                    --message) commit_message="$2"; shift 2 ;;
                    --attach) attachment_dir="$2"; shift 2 ;;
                    *) error "wiki create: Unknown option '$1' / 未知选项 '$1'";;
                esac
            done
            [ -z "$group_slug" ] || [ -z "$file_path" ] || [ -z "$commit_message" ] && { usage_wiki; exit 1; }
            [ ! -f "$file_path" ] && { error "文件未找到 / File not found: $file_path"; exit 1; }
            
            local group_id="${group_slug%/*}"
            local page_slug="${group_slug#*/}"
            
            info "正在将页面内容上传到P2P网络... / Uploading page content to P2P network..."
            local content_hash
            content_hash=$(_p2p_upload_file "$file_path")
            
            local attachment_hash=""
            if [ -n "$attachment_dir" ]; then
                [ ! -d "$attachment_dir" ] && { error "附件目录未找到 / Attachment directory not found: $attachment_dir"; exit 1; }
                info "正在上传附件目录... / Uploading attachment directory..."
                attachment_hash=$(_p2p_upload_directory "$attachment_dir")
            fi

            local format="md"
            [[ "$file_path" == *.html ]] && format="html"

            local tx_data
            tx_data=$(jq -n \
                --arg gid "$group_id" --arg slug "$page_slug" --arg chash "$content_hash" \
                --arg ahash "$attachment_hash" --arg msg "$commit_message" --arg fmt "$format" \
                '{group_id:$gid, page_slug:$slug, content_hash:$chash, attachment_hash:$ahash, commit_message:$msg, format:$fmt}')
            
            info "正在提交 'wiki_page_create' 交易... / Submitting 'wiki_page_create' transaction..."
            blockchain_create_transaction "wiki_page_create" "$tx_data"
            ;;
        show)
            [ $# -lt 1 ] && { usage_wiki; exit 1; }
            local group_slug="${1:-}"; local version_hash="${2:-}"; version_hash="${version_hash#--version=}"
            local group_id="${group_slug%/*}"; local page_slug="${group_slug#*/}"
            
            local content_hash author timestamp commit_message
            if [ -z "$version_hash" ]; then
                # 获取最新版本 / Get latest version
                local page_info
                page_info=$(db_query_safe "$FORUM_DB" "SELECT latest_version_hash FROM wiki_pages WHERE group_id = %s AND slug = %s;" "$group_id" "$page_slug")
                version_hash="${page_info}"
            fi
            [ -z "$version_hash" ] && { error "页面未找到或版本无效。 / Page not found or version is invalid."; exit 1; }

            local version_info
            version_info=$(db_query_safe "$FORUM_DB" "SELECT content_hash, author_id, timestamp, commit_message FROM wiki_versions WHERE version_tx_hash = %s;" "$version_hash")
            IFS='|' read -r content_hash author timestamp commit_message <<< "$version_info"

            echo "--- Wiki Page: ${group_slug} ---"
            echo "Version / 版本: ${version_hash}"
            echo "Author / 作者: $author"
            echo "Date / 日期: $(date -d "@$timestamp")"
            echo "Commit / 提交信息: $commit_message"
            echo "--------------------------------------------------"
            
            local temp_content_file
            temp_content_file=$(mktemp)
            CORIUM_TEMP_ITEMS+=("$temp_content_file")
            if _download_file_p2p "$content_hash" "$temp_content_file"; then
                cat "$temp_content_file"
            else
                error "无法下载页面内容。/ Failed to download page content."
            fi
            ;;
        edit)
            [ $# -ne 1 ] && { usage_wiki; exit 1; }
            local group_slug="$1"; local group_id="${group_slug%/*}"; local page_slug="${group_slug#*/}"

            local page_info
            page_info=$(db_query_safe "$FORUM_DB" "SELECT page_tx_hash, latest_version_hash FROM wiki_pages WHERE group_id = %s AND slug = %s;" "$group_id" "$page_slug")
            [ -z "$page_info" ] && { error "页面未找到 / Page not found: $group_slug"; exit 1; }
            
            local page_tx_hash latest_version_hash
            IFS='|' read -r page_tx_hash latest_version_hash <<< "$page_info"

            info "步骤 1/5: 正在请求编辑锁... / Step 1/5: Requesting edit lock..."
            local lock_tx_hash
            lock_tx_hash=$(blockchain_create_transaction "wiki_page_lock" "$(jq -n --arg pth "$page_tx_hash" '{page_create_tx_hash: $pth}')")

            info "步骤 2/5: 正在等待锁确认... (最多等待60秒) / Step 2/5: Waiting for lock confirmation... (waiting up to 60s)"
            local i=0
            while [ $i -lt 30 ]; do
                _update_chain_state_cache >/dev/null 2>&1
                local lock_holder
                lock_holder=$(db_query_safe "$FORUM_DB" "SELECT locked_by_user_id FROM wiki_pages WHERE page_tx_hash = %s;" "$page_tx_hash")
                if [ "$lock_holder" = "$(get_our_node_id)" ]; then
                    msg "成功获取编辑锁！ / Edit lock acquired successfully!"; break
                fi
                sleep 2; i=$((i+1))
            done
            [ $i -ge 30 ] && { error "获取编辑锁超时或失败。/ Timed out or failed to acquire edit lock."; exit 1; }

            info "步骤 3/5: 正在下载当前页面内容... / Step 3/5: Downloading current page content..."
            local content_hash
            content_hash=$(db_query_safe "$FORUM_DB" "SELECT content_hash FROM wiki_versions WHERE version_tx_hash = %s;" "$latest_version_hash")
            
            local temp_edit_file
            temp_edit_file=$(mktemp --suffix ".md")
            CORIUM_TEMP_ITEMS+=("$temp_edit_file")
            _p2p_download_object "$content_hash" "$temp_edit_file"
            local original_content_hash
            original_content_hash=$(calculate_hash "$temp_edit_file")

            info "步骤 4/5: 正在启动编辑器... (保存并退出以继续) / Step 4/5: Launching editor... (save and exit to continue)"
            ${DEFAULT_EDITOR} "$temp_edit_file"

            local new_content_hash
            new_content_hash=$(calculate_hash "$temp_edit_file")
            if [ "$new_content_hash" = "$original_content_hash" ]; then
                info "内容未更改。正在自动释放锁... / Content unchanged. Releasing lock automatically..."
                blockchain_create_transaction "wiki_page_unlock" "$(jq -n --arg pth "$page_tx_hash" '{page_create_tx_hash: $pth}')"
                msg "编辑已取消。/ Edit cancelled."
                exit 0
            fi

            info "步骤 5/5: 内容已更改，正在上传并提交... / Step 5/5: Content has changed, uploading and submitting..."
            local new_p2p_hash
            new_p2p_hash=$(_p2p_upload_file "$temp_edit_file")
            
            local commit_message
            read -rp "请输入提交信息 / Enter commit message: " commit_message

            local tx_data
            tx_data=$(jq -n \
                --arg pth "$page_tx_hash" --arg prev "$latest_version_hash" \
                --arg chash "$new_p2p_hash" --arg msg "$commit_message" \
                '{page_create_tx_hash:$pth, previous_version_hash:$prev, content_hash:$chash, commit_message:$msg}')
            
            blockchain_create_transaction "wiki_page_edit" "$tx_data"
            msg "页面已成功编辑并提交！ / Page successfully edited and submitted!"
            ;;
        history)
            [ $# -ne 1 ] && { usage_wiki; exit 1; }
            local group_slug="$1"; local group_id="${group_slug%/*}"; local page_slug="${group_slug#*/}"
            local page_tx_hash
            page_tx_hash=$(db_query_safe "$FORUM_DB" "SELECT page_tx_hash FROM wiki_pages WHERE group_id = %s AND slug = %s;" "$group_id" "$page_slug")
            
            msg "版本历史 / Version History for: $group_slug"
            db_query_safe "$FORUM_DB" "SELECT version_tx_hash, author_id, timestamp, commit_message FROM wiki_versions WHERE page_tx_hash = %s ORDER BY timestamp DESC;" "$page_tx_hash" | while IFS='|' read -r vhash author ts msg; do
                echo "----------------------------------------"
                echo "  版本 / Version: ${vhash}"
                echo "  作者 / Author:  ${author:0:32}..."
                echo "  日期 / Date:    $(date -d "@$ts")"
                echo "  信息 / Message: ${msg}"
            done
            ;;
        status)
            [ $# -ne 1 ] && { usage_wiki; exit 1; }
            local group_slug="$1"; local group_id="${group_slug%/*}"; local page_slug="${group_slug#*/}"
            local lock_holder
            lock_holder=$(db_query_safe "$FORUM_DB" "SELECT locked_by_user_id FROM wiki_pages WHERE group_id = %s AND slug = %s;" "$group_id" "$page_slug")
            if [ -n "$lock_holder" ]; then
                warn "页面 '${group_slug}' 当前已被锁定。 / Page '${group_slug}' is currently LOCKED."
                info "  锁定者 / Locked by: $lock_holder"
            else
                msg "页面 '${group_slug}' 当前未锁定。/ Page '${group_slug}' is currently UNLOCKED."
            fi
            ;;
        unlock)
            [ $# -ne 1 ] && { usage_wiki; exit 1; }
            local group_slug="$1"; local group_id="${group_slug%/*}"; local page_slug="${group_slug#*/}"
            local page_tx_hash
            page_tx_hash=$(db_query_safe "$FORUM_DB" "SELECT page_tx_hash FROM wiki_pages WHERE group_id = %s AND slug = %s;" "$group_id" "$page_slug")
            info "正在提交手动解锁交易... / Submitting manual unlock transaction..."
            blockchain_create_transaction "wiki_page_unlock" "$(jq -n --arg pth "$page_tx_hash" '{page_create_tx_hash: $pth}')"
            ;;
        *)
            usage_wiki
            ;;
    esac
}

# =======================================================================================
# --- SECTION 32: CLI - WIKI & NOMEN WEB (NOMEN SITE COMMANDS)                        ---
# --- 第32节: 命令行界面 - 维基与Nomen网络 (Nomen站点命令)                            ---
