# Displays detailed help for the site and domain commands.
# 显示 site 和 domain 命令的详细帮助信息。
usage_site() {
    echo "corix site: Publish and manage decentralized websites on the Nomen Name Service."
    echo "corix site: 在 Nomen 名称服务上发布和管理去中心化网站。"
    echo
    echo "Usage: corix site <subcommand> [arguments...]"
    echo "用法:  corix site <子命令> [参数...]"
    echo
    echo "Website Commands (网站命令):"
    echo "  publish <directory> --domain <name>"
    echo "      Recursively upload a directory and link it to a Nomen domain name."
    echo "      (递归上传一个目录并将其链接到一个Nomen域名)"
    echo
    echo "Domain Commands (域名命令): corix site domain <subcommand> ..."
    echo "  query <name>                      Query the owner and content hash of a domain."
    echo "                                    (查询一个域名的所有者和内容哈希)"
    echo "  transfer <name> --to <user_id>    Transfer ownership of a domain you own."
    echo "                                    (转让您拥有的一个域名的所有权)"
    echo
    echo "Domain Auction (创世期后 / Post-Genesis Period):"
    echo "  domain auction <name>             Start a new auction for an available domain name."
    echo "                                    (为一个可用的域名发起新的拍卖)"
    echo "  domain bid <name> <amount>        Place a secret bid in an ongoing auction."
    echo "                                    (在进行中的拍卖中进行一次秘密出价)"
    echo "  domain reveal <name>              Reveal your secret bid to claim a domain."
    echo "                                    (揭示您的秘密出价以竞争域名)"
}

#------------------------------------------------------------------------------
# 核心辅助函数与治理函数的完整实现
# Full Implementation of Core Helper and Governance Functions
#------------------------------------------------------------------------------

get_my_node_id() {
    # 从标准身份文件中安全地读取当前用户的节点ID。
    # Securely reads the current user's node ID from the standard identity file.
    local id_file="${VAR_LIB_CORIUM_DIR}/identity/node.id"
    if [ ! -f "$id_file" ]; then
        error "无法找到节点ID文件。请先初始化Corium身份。 / Node ID file not found. Please initialize Corium identity first."
        return 1
    fi
    cat "$id_file"
}

get_my_contribution_points() {
    # 从本地数据库查询经过共识验证的、当前用户的最新贡献分。
    # Queries the local database for the latest consensus-validated contribution points of the current user.
    local my_id
    my_id=$(get_my_node_id)
    [ -z "$my_id" ] && return 1

    local points
    points=$(db_query_safe "$FORUM_DB" "SELECT points FROM contribution_ledger WHERE node_id = %s;" "$my_id" | cut -d'|' -f1)
    
    # 如果在账本中找不到记录（例如新用户），则返回0。
    # If no record is found in the ledger (e.g., a new user), return 0.
    echo "${points:-0}"
}

# 'corix system' 的用户侧命令分发器。
# The user-facing command dispatcher for 'corix system'.
corix_system() {
    local sub_cmd="${1:-}"
    shift || true
    case "$sub_cmd" in
        param-set)
            # 设置一个系统级的可治理参数。
            # Sets a system-level governable parameter.
            # 警告：此操作需要特殊权限，由链上状态机进行验证。
            # WARNING: This operation requires special privileges, verified by the on-chain state machine.
            local param_name="${1:-}"
            local param_value="${2:-}"
            [ -z "$param_name" ] || [ -z "$param_value" ] && { error "用法: corix system param-set <参数名> <参数值>"; exit 1; }

            local tx_data
            tx_data=$(jq -n --arg key "$param_name" --arg value "$param_value" '{param_key:$key, new_value:$value}')
            info "正在提交系统参数 '${param_name}' 的更新提案... / Submitting update proposal for system parameter '${param_name}'..."
            blockchain_create_transaction "sys_update_param" "$tx_data"
            ;;
        *)
            echo "用法: corix system param-set <参数名> <参数值>"
            echo "Usage: corix system param-set <param_key> <param_value>"
            ;;
    esac
}


#------------------------------------------------------------------------------
# NNS 经济模型辅助函数 (从链上参数读取)
# NNS Economic Model Helper Functions (Reads from on-chain parameters)
#------------------------------------------------------------------------------

_nns_calculate_genesis_cost() {
    local name="$1"
    local db_path="$2"
    local len=${#name}
    
    # 从数据库读取经济模型参数，如果不存在则使用安全的默认值
    # Read economic model parameters from the database, using safe defaults if not present
    local cost_len3=$(db_query_safe "$db_path" "SELECT param_value FROM system_params WHERE param_key = 'nns_cost_len3';" | sed 's/^$/10000/')
    local cost_len5=$(db_query_safe "$db_path" "SELECT param_value FROM system_params WHERE param_key = 'nns_cost_len5';" | sed 's/^$/2000/')
    local cost_len8=$(db_query_safe "$db_path" "SELECT param_value FROM system_params WHERE param_key = 'nns_cost_len8';" | sed 's/^$/500/')
    local cost_long=$(db_query_safe "$db_path" "SELECT param_value FROM system_params WHERE param_key = 'nns_cost_long';" | sed 's/^$/50/')
    local mult_alpha=$(db_query_safe "$db_path" "SELECT param_value FROM system_params WHERE param_key = 'nns_multiplier_alpha';" | sed 's/^$/2.0/')
    local mult_alnum=$(db_query_safe "$db_path" "SELECT param_value FROM system_params WHERE param_key = 'nns_multiplier_alnum';" | sed 's/^$/1.2/')
    
    local base_cost
    if [ "$len" -le 3 ]; then base_cost=$cost_len3;
    elif [ "$len" -le 5 ]; then base_cost=$cost_len5;
    elif [ "$len" -le 8 ]; then base_cost=$cost_len8;
    else base_cost=$cost_long;
    fi

    local multiplier=1.0
    if [[ "$name" =~ ^[a-z]+$ ]]; then multiplier=$mult_alpha;
    elif [[ "$name" =~ ^[a-z0-9]+$ ]]; then multiplier=$mult_alnum;
    fi
    
    printf "%.0f\n" $(echo "$base_cost * $multiplier" | bc)
}

_nns_calculate_renewal_cost() {
    local name="$1"
    local owner_id="$2"
    local db_path="$3"

    local genesis_cost
    genesis_cost=$(_nns_calculate_genesis_cost "$name" "$db_path")
    
    local renewal_factor=$(db_query_safe "$db_path" "SELECT param_value FROM system_params WHERE param_key = 'nns_renewal_factor_percent';" | sed 's/^$/10/')
    
    local base_renewal_cost=$(( (genesis_cost * renewal_factor) / 100 ))
    [ "$base_renewal_cost" -eq 0 ] && base_renewal_cost=1
    
    echo "$base_renewal_cost"
}

#------------------------------------------------------------------------------
# corix_site() 的用户侧命令分发器 (终极完整版)
# The user-facing command dispatcher for 'corix site' (Ultimate Full Version)
#------------------------------------------------------------------------------
corix_site() {
    acquire_lock "network"
    trap 'release_lock "network"' RETURN

    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        my-id)
            # 显示当前用户的节点ID。
            # Displays the current user's node ID.
            local my_id
            my_id=$(get_my_node_id)
            if [ -n "$my_id" ]; then
                msg "您的节点ID / Your Node ID: ${my_id}"
            fi
            ;;
        my-points)
            # 显示当前用户的贡献分。
            # Displays the current user's contribution points.
            local my_points
            my_points=$(get_my_contribution_points)
            msg "您当前的贡献分 / Your Current Contribution Points: ${my_points}"
            ;;
        publish)
            # 发布一个目录到NNS，这会消耗贡献分并注册域名。
            # Publishes a directory to NNS, consuming contribution points and registering the domain.
            local dir_path domain_name
            dir_path="${1:-}"; shift || true
            if [ "$1" != "--domain" ]; then usage_site; exit 1; fi
            domain_name="${2:-}";

            [ ! -d "$dir_path" ] && { error "目录未找到 / Directory not found: $dir_path"; exit 1; }
            [ -z "$domain_name" ] && { usage_site; exit 1; }

            info "正在检查域名 '${domain_name}' 的可用性... / Checking availability for domain '${domain_name}'..."
            local existing_record
            existing_record=$(db_query_safe "$FORUM_DB" "SELECT owner_id FROM nns_records WHERE domain_name = %s;" "$domain_name")
            [ -n "$existing_record" ] && { error "域名 '${domain_name}' 已被注册。 / Domain '${domain_name}' is already registered."; exit 1; }
            
            info "正在从链上状态读取经济参数并计算成本... / Reading economic parameters from on-chain state and calculating cost..."
            local registration_cost
            registration_cost=$(_nns_calculate_genesis_cost "$domain_name" "$BLOCKCHAIN_DB")
            info "域名 '${domain_name}' 的注册成本为: ${registration_cost} 贡献分。 / Registration cost for '${domain_name}' is: ${registration_cost} contribution points."
            
            local current_contribution
            current_contribution=$(get_my_contribution_points)
            
            if [ "$current_contribution" -lt "$registration_cost" ]; then
                error "贡献分不足。需要: ${registration_cost}, 您有: ${current_contribution}。 / Insufficient contribution points. Required: ${registration_cost}, You have: ${current_contribution}."
                exit 1
            fi

            info "正在将目录内容上传到P2P网络... / Uploading directory contents to the P2P network..."
            local root_hash
            root_hash=$(_p2p_upload_directory "$dir_path")
            [ -z "$root_hash" ] && { error "目录上传失败。/ Directory upload failed."; exit 1; }

            info "贡献分充足，正在构建创世注册交易... / Contribution points sufficient, building genesis registration transaction..."
            local tx_data
            tx_data=$(jq -n \
                --arg name "$domain_name" \
                --arg hash "$root_hash" \
                --argjson cost "$registration_cost" \
                '{domain_name:$name, target_hash:$hash, proof_of_genesis_contribution:{burned_amount:$cost}}')
            
            info "正在提交域名 '${domain_name}' 的注册交易... / Submitting registration transaction for domain '${domain_name}'..."
            blockchain_create_transaction "nns_register" "$tx_data"
            ;;
        domain)
            local domain_cmd="${1:-}"; shift || true
            case "$domain_cmd" in
                query)
                    # 查询一个NNS域名的详细信息，支持联邦化查询。
                    # Queries detailed information about an NNS domain, with federated query support.
                    local full_name="$1"
                    local name target_chain
                    
                    if [[ "$full_name" == *"@"* ]]; then
                        # 这是一个联邦化查询 / This is a federated query
                        name="${full_name%@*}"
                        target_chain="${full_name#*@}"
                        
                        info "正在为域名 '${name}' 向链 '${target_chain}' 发起跨链查询... / Initiating cross-chain query for domain '${name}' to chain '${target_chain}'..."
                        local tx_payload
                        tx_payload=$(jq -n --arg dname "$name" '{domain_name:$dname}')
                        local query_tx_hash
                        query_tx_hash=$(blockchain_create_transaction "ibc_dispatch" "$(jq -n --arg tc "$target_chain" --arg mt "IBC_NNS_QUERY" --argjson p "$tx_payload" '{target_chain_id:$tc, message_type:$mt, message_payload:$p}')")
                        
                        msg "跨链查询已发出。交易哈希: ${query_tx_hash}"
                        msg "请稍后使用 'corix ibc query-result ${query_tx_hash}' 查看结果。"
                        msg "Cross-chain query dispatched. TX Hash: ${query_tx_hash}"
                        msg "Please use 'corix ibc query-result ${query_tx_hash}' to view the result later."
                    else
                        # 这是一个本地查询 / This is a local query
                        name="$full_name"
                        local record
                        record=$(db_query_safe "$FORUM_DB" "SELECT owner_id, target_hash, registration_type, expires_at FROM nns_records WHERE domain_name = %s;" "$name")
                        if [ -z "$record" ]; then
                            msg "域名 '${name}' 未在本链注册。 / Domain '${name}' is not registered on this chain."
                        else
                            local owner target reg_type expires_at
                            IFS='|' read -r owner target reg_type expires_at <<< "$record"
                            local expires_str
                            expires_str=$(date -d "@${expires_at}" '+%Y-%m-%d %H:%M:%S %Z')
                            msg "域名信息 / Domain Info: ${name}"
                            echo "  所有者 / Owner: ${owner}"
                            echo "  内容哈希 / Content Hash: ${target}"
                            echo "  注册类型 / Registration Type: ${reg_type}"
                            echo "  到期时间 / Expires At: ${expires_str}"
                        fi
                    fi
                    ;;
                transfer)
                    # 将一个域名的所有权转让给另一个用户，无税费。
                    # Transfers the ownership of a domain to another user, with no tax.
                    local name to_user
                    name="$1"; shift
                    if [ "$1" != "--to" ]; then usage_site; exit 1; fi
                    to_user="$2"

                    local my_id
                    my_id=$(get_my_node_id)
                    local current_owner
                    current_owner=$(db_query_safe "$FORUM_DB" "SELECT owner_id FROM nns_records WHERE domain_name = %s;" "$name")
                    [ "$current_owner" != "$my_id" ] && { error "您不是该域名的所有者。/ You are not the owner of this domain."; exit 1; }

                    local tx_data
                    tx_data=$(jq -n --arg name "$name" --arg to "$to_user" '{domain_name:$name, new_owner_id:$to}')
                    info "正在提交域名 '${name}' 的转让交易... / Submitting domain transfer transaction for '${name}'..."
                    blockchain_create_transaction "nns_transfer" "$tx_data"
                    ;;
                renew)
                    # 为拥有的域名续期，这将消耗贡献分。
                    # Renews a domain you own, which consumes contribution points.
                    local name="$1"
                    
                    local my_id
                    my_id=$(get_my_node_id)
                    local current_owner
                    current_owner=$(db_query_safe "$FORUM_DB" "SELECT owner_id FROM nns_records WHERE domain_name = %s;" "$name")
                    [ "$current_owner" != "$my_id" ] && { error "您不是该域名的所有者。/ You are not the owner of this domain."; exit 1; }
                    
                    info "正在从链上状态计算域名 '${name}' 的续期成本... / Calculating renewal cost for domain '${name}' from on-chain state..."
                    local renewal_cost
                    renewal_cost=$(_nns_calculate_renewal_cost "$name" "$my_id" "$BLOCKCHAIN_DB")
                    info "域名 '${name}' 的续期成本为: ${renewal_cost} 贡献分。 / Renewal cost for '${name}' is: ${renewal_cost} contribution points."
                    
                    local current_contribution
                    current_contribution=$(get_my_contribution_points)
                    if [ "$current_contribution" -lt "$renewal_cost" ]; then
                        error "贡献分不足以续期。需要: ${renewal_cost}, 您有: ${current_contribution}。 / Insufficient contribution points for renewal. Required: ${renewal_cost}, You have: ${current_contribution}."
                        exit 1
                    fi

                    info "正在为域名 '${name}' 提交续期交易... / Submitting renewal transaction for domain '${name}'..."
                    local tx_data
                    tx_data=$(jq -n --arg name "$name" --argjson cost "$renewal_cost" '{domain_name:$name, renewal_contribution:{burned_amount:$cost}}')
                    blockchain_create_transaction "nns_renew" "$tx_data"
                    ;;
                auction)
                    # 为一个尚未被注册的域名发起拍卖。
                    # Starts an auction for an unregistered domain.
                    local name="$1"
                    # [V105.7 SECURITY] Add rate limit to prevent auction spamming.
                    # [V105.7 安全] 增加速率限制以防止拍卖垃圾信息。
                    if ! _internal_rate_limiter_check "nns_auction_start" 10 360; then
                        error "发起拍卖操作过于频繁。请稍后再试。 / Auction start requests are too frequent. Please try again later."
                        return 1
                    fi
                    local tx_data
                    tx_data=$(jq -n --arg name "$name" '{domain_name:$name}')
                    info "正在为域名 '${name}' 发起拍卖... / Starting auction for domain '${name}'..."
                    blockchain_create_transaction "nns_start_auction" "$tx_data"
                    ;;
                bid)
                    # 在拍卖期间，提交一个盲化出价。
                    # Submits a blinded bid during an auction.
                    local name amount salt blind_hash
                    name="$1"; amount="$2"
                    [ -z "$amount" ] || ! [[ "$amount" =~ ^[0-9]+$ ]] && { error "出价金额必须是一个正整数。/ Bid amount must be a positive integer."; exit 1; }

                    salt=$(openssl rand -hex 16)
                    blind_hash=$(_internal_hash_text "${amount}|${salt}")
                    
                    local bid_dir="${VAR_LIB_CORIUM_DIR}/nns_bids"
                    mkdir -p "$bid_dir"
                    echo "${amount}|${salt}" > "${bid_dir}/${name}.bid"
                    
                    local tx_data
                    tx_data=$(jq -n --arg name "$name" --arg hash "$blind_hash" '{domain_name:$name, blind_hash:$hash}')
                    info "正在为域名 '${name}' 提交盲化出价... / Submitting blinded bid for domain '${name}'..."
                    blockchain_create_transaction "nns_bid" "$tx_data"
                    ;;
                reveal)
                    # 在揭示阶段，公开你的出价。
                    # Reveals your bid during the reveal phase.
                    local name amount salt
                    name="$1"
                    local bid_file="${VAR_LIB_CORIUM_DIR}/nns_bids/${name}.bid"
                    [ ! -f "$bid_file" ] && { error "未找到 '${name}' 的本地出价记录。无法揭示。 / No local bid record found for '${name}'. Cannot reveal."; exit 1; }
                    IFS='|' read -r amount salt < "$bid_file"
                    
                    local tx_data
                    tx_data=$(jq -n --arg name "$name" --argjson amt "$amount" --arg s "$salt" '{domain_name:$name, amount:$amt, salt:$s}')
                    info "正在揭示您对 '${name}' 的出价 (${amount} 贡献分)... / Revealing your bid for '${name}' (${amount} contribution points)..."
                    blockchain_create_transaction "nns_reveal" "$tx_data"
                    rm -f "$bid_file" # 揭示后清理 / Cleanup after reveal
                    ;;
                *)
                    usage_site
                    ;;
            esac
            ;;
        *)
            usage_site
            ;;
    esac
}


