# Displays detailed help for the find command.
# 显示 find 命令的详细帮助信息。
usage_find() {
    echo "corix find: A powerful tool to search for users, groups, and broadcasts."
    echo "corix find: 一个用于搜索用户、群组和广播的强大工具。"
    echo
    echo "Usage: corix find [--type <type>] [--id <id_hash>] [--name <nickname>]"
    echo "用法:  corix find [--type <类型>] [--id <ID哈希>] [--name <昵称>]"
    echo
    echo "Options (选项):"
    echo "  --type <type>   Filter by entity type. Can be 'user', 'group', or 'broadcast'."
    echo "                  (按实体类型过滤。可以是 'user', 'group', 或 'broadcast')"
    echo "  --id <id_hash>  Find an entity by its exact ID hash."
    echo "                  (通过精确的 ID 哈希查找实体)"
    echo "  --name <name>   Find entities by nickname (case-insensitive, partial match)."
    echo "                  (通过昵称查找实体 (不区分大小写，部分匹配))"
    echo
    echo "Examples (示例):"
    echo "  corix find --type group --name 'dev'"
    echo "  corix find --id 'a1b2c3d4...'"
}

# The user-facing command for finding identities.
# 用于查找身份的用户侧命令。
corix_find() {
    acquire_lock "network"
    trap 'release_lock "network"' RETURN

    local type_filter="" id_filter="" name_filter=""
    while [ $# -gt 0 ]; do
        case "$1" in
            --type) type_filter="$2"; shift 2;;
            --id) id_filter="$2"; shift 2;;
            --name) name_filter="$2"; shift 2;;
            *) error "find: Unknown option '$1' / 未知选项 '$1'";;
        esac
    done

    if [ -z "$type_filter" ] && [ -z "$id_filter" ] && [ -z "$name_filter" ]; then
        usage_find
        exit 1
    fi

    # 确保在同步后执行查找，以获得最新结果
    # Ensure find is run after a sync for up-to-date results
    _update_chain_state_cache >/dev/null 2>&1

    local query="SELECT id_hash, nickname, type FROM identity_cache WHERE 1=1"
    local -a params=()

    if [ -n "$type_filter" ]; then
        query+=" AND type = %s"
        params+=("$type_filter")
    fi
    if [ -n "$id_filter" ]; then
        query+=" AND id_hash = %s"
        params+=("$id_filter")
    fi
    if [ -n "$name_filter" ]; then
        query+=" AND nickname LIKE %s"
        params+=("%${name_filter}%")
    fi
    query+=" ORDER BY type, nickname;"

    msg "正在查找匹配项... / Searching for matches..."
    local results
    results=$(db_query_safe "$FORUM_DB" "$query" "${params[@]}")

    if [ -z "$results" ]; then
        info "未找到匹配项。 / No matches found."
    else
        echo "--------------------------------------------------------------------"
        printf "%-12s | %-32s | %s\n" "TYPE (类型)" "NICKNAME (昵称)" "ID HASH (ID哈希)"
        echo "--------------------------------------------------------------------"
        while IFS='|' read -r id_hash nickname type; do
            printf "%-12s | %-32s | %s\n" "$type" "${nickname:-<N/A>}" "$id_hash"
        done <<< "$results"
        echo "--------------------------------------------------------------------"
    fi
}

