# --- [V99] 身份管理 帮助函数 (已扩展) ---
# --- [V99] Identity Management Help Function (Extended) ---
usage_identity() {
    echo "corix identity: Manage your local Corium identity."
    echo "corix identity: 管理您的本地 Corium 身份。"
    echo
    echo "Usage: corix identity <subcommand> [arguments...]"
    echo "用法:  corix identity <子命令> [参数...]"
    echo
    echo "Subcommands (子命令):"
    echo "  export [--private] [--output <file>]   Export your identity keys."
    echo "                                           (导出您的身份密钥)"
    echo "      --private                        : (危险 / DANGEROUS) Include the private key in the export."
    echo "                                         (在导出中包含私钥)"
    echo "      --output <file>                  : Output to a file instead of stdout."
    echo "                                         (输出到文件而非标准输出)"
    echo
    echo "  import <key_file> [--password-from-env]  Import a new identity, replacing the current one."
    echo "                                           (导入一个新身份，替换当前身份)"
    echo "      --password-from-env              : Read the key's password from the CORIUM_PASSPHRASE environment variable."
    echo "                                         (从 CORIUM_PASSPHRASE 环境变量中读取密钥密码)"
    echo
    echo "  migrate --new-pubkey-file <path>       (Legacy) Migrate local package ownership records."
    echo "                                         ((遗留功能) 迁移本地软件包的所有权记录)"
}


# --- [V99] 身份管理 主分发器 (已扩展) ---
# --- [V99] Identity Management Main Dispatcher (Extended) ---
corix_identity() {
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        export)
            acquire_lock "system" "ro" # Export is read-only
            trap 'release_lock "system"' RETURN
            
            local export_private=0
            local output_file=""
            while [ $# -gt 0 ]; do
                case "$1" in
                    --private) export_private=1; shift ;;
                    --output) output_file="$2"; shift 2 ;;
                    *) error "export: Unknown option '$1'";;
                esac
            done

            if [ ! -f "$USER_PUBLIC_KEY_FILE" ]; then
                error "身份不存在，无法导出。请先运行 'corix init'。 / Identity does not exist, cannot export. Please run 'corix init' first."
            fi

            local output_content=""
            if [ "$export_private" -eq 1 ]; then
                warn "!!! 正在导出您的私钥。请妥善保管此文件！ / Exporting your PRIVATE KEY. Handle this file with extreme care!"
                [ ! -f "$USER_IDENTITY_FILE" ] && error "私钥文件未找到！ / Private key file not found!"
                output_content=$(cat "$USER_IDENTITY_FILE")
            else
                output_content=$(cat "$USER_PUBLIC_KEY_FILE")
            fi
            
            if [ -n "$output_file" ]; then
                echo "$output_content" > "$output_file"
                msg "身份已成功导出到 / Identity successfully exported to: $output_file"
            else
                echo "$output_content"
            fi
            ;;

        import)
            acquire_lock "system"
            trap 'release_lock "system"' RETURN
            
            local key_file="$1"; shift
            local pass_from_env=0
            if [ "${1:-}" = "--password-from-env" ]; then
                pass_from_env=1
            fi

            [ -z "$key_file" ] && { usage_identity; exit 1; }
            [ ! -f "$key_file" ] && error "密钥文件未找到 / Key file not found: $key_file"

            warn "!!! 危险操作：身份导入 !!!"
            warn "!!! DANGEROUS ACTION: IDENTITY IMPORT !!!"
            warn "此操作将用新密钥【永久覆盖】您当前的身份。旧身份将丢失！"
            warn "This will [PERMANENTLY OVERWRITE] your current identity with the new key. The old one will be lost!"
            read -rp "您确定要继续吗？[y/N] / Are you sure you want to proceed? [y/N] " choice
            [[ ! "$choice" =~ ^[yY] ]] && { msg "导入已取消。 / Import cancelled."; return 0; }

            # 验证新密钥并从中提取公钥
            # Validate the new key and extract the public key from it
            local temp_pub_key; temp_pub_key=$(mktemp)
            CORIUM_TEMP_ITEMS+=("$temp_pub_key")
            
            local openssl_ec_opts=("-in" "$key_file" "-pubout" "-out" "$temp_pub_key")
            if [ "$pass_from_env" -eq 1 ]; then
                [ -z "$CORIUM_PASSPHRASE" ] && error "错误: --password-from-env 已指定，但 CORIUM_PASSPHRASE 环境变量为空。 / Error: --password-from-env was specified, but the CORIUM_PASSPHRASE environment variable is empty."
                openssl_ec_opts+=("-passin" "env:CORIUM_PASSPHRASE")
            elif grep -q "Proc-Type: 4,ENCRYPTED" "$key_file"; then
                # 如果密钥已加密但未提供环境变量，则交互式提示
                # If key is encrypted but env var is not provided, prompt interactively
                openssl_ec_opts+=("-passin" "stdin")
                info "新密钥已加密，请输入密码以继续。 / New key is encrypted, please enter its password to continue."
            fi

            if ! openssl ec "${openssl_ec_opts[@]}"; then
                error "导入失败：无法从提供的文件中提取公钥。文件可能已损坏或密码错误。"
                error "Import failed: Could not extract public key from the provided file. It may be corrupt or the password is incorrect."
            fi
            
            # 覆盖现有密钥
            # Overwrite existing keys
            cp "$key_file" "$USER_IDENTITY_FILE"
            cp "$temp_pub_key" "$USER_PUBLIC_KEY_FILE"
            chmod 600 "$USER_IDENTITY_FILE"
            chmod 644 "$USER_PUBLIC_KEY_FILE"

            msg "✅ 身份已成功导入！ / Identity successfully imported!"
            info "新身份ID / New Identity ID: $(get_our_node_id)"
            ;;
            
        migrate)
            local new_pubkey_file=""
            if [ "$1" != "--new-pubkey-file" ]; then usage_identity; exit 1; fi
            new_pubkey_file="$2"
            
            [ ! -f "$new_pubkey_file" ] && { error "新公钥文件未找到 / New public key file not found: $new_pubkey_file"; exit 1; }
            [ ! -f "$USER_PUBLIC_KEY_FILE" ] && { error "当前身份公钥文件未找到。 / Current identity public key file not found."; exit 1; }

            warn "!!! 危险操作：账户迁移 !!!"
            warn "!!! DANGER ZONE: ACCOUNT MIGRATION !!!"
            warn "此操作将修改本地已安装软件包的所有权记录。 / This operation will modify the ownership records of locally installed packages."
            warn "它不会产生任何区块链交易，完全是本地行为。 / It creates NO blockchain transactions and is a purely local action."
            warn "请确保您已备份好新的私钥，并且此操作在替换旧私钥之前进行。/ Ensure you have backed up your new private key and are running this BEFORE replacing the old one."
            
            read -rp "您完全理解并希望继续吗？ [y/N] / Do you fully understand and wish to proceed? [y/N] " choice
            [[ ! "$choice" =~ ^[yY] ]] && { msg "迁移已取消。/ Migration cancelled."; exit 0; }
            
            acquire_lock "system"
            trap 'release_lock "system"' RETURN

            local current_id new_id
            current_id=$(_internal_hash_text "$(cat "$USER_PUBLIC_KEY_FILE")")
            new_id=$(_internal_hash_text "$(cat "$new_pubkey_file")")
            
            msg "正在将所有权从 ${current_id:0:16}... 迁移到 ${new_id:0:16}... / Migrating ownership from ${current_id:0:16}... to ${new_id:0:16}..."
            
            local migrated_count=0
            while read -r pkg_dir; do
                local owner_file="${pkg_dir}/owner"
                if [ -f "$owner_file" ] && [ "$(cat "$owner_file")" = "$current_id" ]; then
                    detail "  -> 正在迁移 / Migrating: $(basename "$pkg_dir")"
                    echo "$new_id" > "$owner_file"
                    migrated_count=$((migrated_count + 1))
                fi
            done < <(find "$INSTALLED_DB" -mindepth 1 -maxdepth 1 -type d)

            msg "迁移完成！/ Migration complete!"
            info "共 ${migrated_count} 个软件包的所有权已更新。 / Ownership of ${migrated_count} packages has been updated."
            info "您现在可以安全地用新的 identity.key 文件替换旧文件了。 / You may now safely replace your old identity.key file with the new one."
            ;;
            
        *)
            usage_identity
            ;;
    esac
}

