}

if chain_db and os.path.exists(chain_db):
    try:
        conn = sqlite3.connect(f'file:{chain_db}?mode=ro', uri=True, timeout=1.0)
        c = conn.cursor()
        c.execute('SELECT count(*) FROM blocks')
        ctx['blockchain']['block_count'] = c.fetchone()[0]
        c.execute('SELECT count(*) FROM transactions')
        ctx['blockchain']['tx_count'] = c.fetchone()[0]
        c.execute('SELECT height, hash, previous_hash, timestamp, validator FROM blocks ORDER BY height DESC LIMIT 10')
        blocks = []
        for r in c.fetchall():
            blocks.append({
                'height': r[0], 'hash': r[1], 'previous_hash': r[2], 'timestamp': r[3], 'validator': r[4]
            })
        ctx['blockchain']['blocks'] = blocks
        if blocks:
            ctx['blockchain']['height'] = blocks[0]['height']
        conn.close()
    except Exception:
        pass

if forum_db and os.path.exists(forum_db):
    try:
        conn = sqlite3.connect(f'file:{forum_db}?mode=ro', uri=True, timeout=2.0)
        c = conn.cursor()
        c.execute('SELECT domain_name, target_hash, owner_id FROM nns_records LIMIT 50')
        ctx['nns'] = [{'domain': r[0], 'target': r[1], 'owner': r[2]} for r in c.fetchall()]

        obj_dirs = [
            os.path.join(os.path.dirname(forum_db), 'objects'),
            os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(forum_db))), 'p2p', 'objects')
        ]
        def _read_content(h):
            if not h: return ""
            for od in obj_dirs:
                op = os.path.join(od, h)
                if os.path.isfile(op):
                    try:
                        with open(op, 'r', encoding='utf-8', errors='replace') as of:
                            return of.read()
                    except Exception:
                        pass
            return ""

        c.execute('SELECT id, title, author, timestamp, content_hash FROM topics ORDER BY timestamp DESC LIMIT 50')
        topics_rows = c.fetchall()
        topics_list = []
        for trow in topics_rows:
            tid, ttitle, tauthor, ttime, tchash = trow
            tcontent = _read_content(tchash)
            c2 = conn.cursor()
            c2.execute('SELECT id, author, timestamp, content_hash FROM posts WHERE topic_id=? ORDER BY timestamp ASC', (tid,))
            replies_list = []
            for prow in c2.fetchall():
                pid, pauthor, ptime, pchash = prow
                pcontent = _read_content(pchash)
                replies_list.append({
                    'id': pid,
                    'author': pauthor,
                    'timestamp': ptime,
                    'content': pcontent,
                    'content_hash': pchash
                })
            c2.close()
            topics_list.append({
                'id': tid,
                'topic': ttitle,
                'author': tauthor,
                'timestamp': ttime,
                'content_hash': tchash,
                'content': tcontent,
                'replies': replies_list
            })
        ctx['forum'] = {'topics': topics_list}
        conn.close()
    except Exception:
        pass

if dht_db and os.path.exists(dht_db):
    try:
        conn = sqlite3.connect(f'file:{dht_db}?mode=ro', uri=True, timeout=1.0)
        c = conn.cursor()
