# 此函数允许Python守护进程请求Bash脚本向一个具体的网络地址字符串发送消息。
# 这对于执行NAT打洞至关重要，因为目标地址是从信令中获取的，可能尚未记录在本地路由表中。
# This function allows the Python daemon to request the Bash script send a message to a specific network address string.
# This is crucial for NAT hole punching, as the target address is learned from a signal and may not yet be in the local routing table.
#
# @param $1 - address_string (Full address string, e.g., "nodeid:ipv4:1.2.3.4:7234")
# @param $2 - message_type
# @param $3 - payload
_internal_dht_send_to_addr() {
    local addr_str="$1" type="$2" payload="$3"
    
    # 我们需要先解析地址字符串，以获取发送消息所需的全部信息
    # We first need to parse the address string to get all the info needed to send the message
    _parse_full_address "$addr_str" || return 1
    
    # 调用底层的直接发送函数
    # Call the low-level direct sending function
    _dht_send_message_direct "$ADDR_NODE_ID" "$type" "$payload"
}



corix_strata_execute() {
    local strata_name="$1"
    shift
    [ $# -eq 0 ] && error "No command provided to execute in strata."

    local strata_path="${STRATA_DIR}/${strata_name}"
    [ -d "$strata_path" ] || error "Strata '$strata_name' not found."

    local strata_conf="${strata_path}/.corix_strata"
    local pm=""
    if [ -f "$strata_conf" ]; then
        pm=$(grep '^pm=' "$strata_conf" | cut -d= -f2)
    fi

    local strata_command=""
    if [ $# -eq 1 ]; then strata_command="$1"; else printf -v strata_command '%q ' "$@"; fi

    # Support dCPM package manager execution directly against strata root
    if [ "$pm" = "dcpm" ] || [ "$pm" = "decentralized" ]; then
        if [ "$1" = "dcpm" ]; then
            shift
            dcpm --root "$strata_path" "$@"
            return $?
        elif [[ "$1" == "dcpm "* ]] || [[ "$strata_command" =~ ^dcpm[[:space:]] ]] || [ "$strata_command" = "dcpm" ]; then
            local -a _dcpm_args=()
            local _dcpm_parsed
            _dcpm_parsed=$("${PYTHON_CMD:-python3}" -c 'import json,shlex,sys; print(json.dumps(shlex.split(sys.argv[1])))' "$strata_command") || return 1
            mapfile -t _dcpm_args < <(printf '%s' "$_dcpm_parsed" | jq -r '.[]')
            dcpm --root "$strata_path" "${_dcpm_args[@]:1}"
            return $?
        fi
    fi

    msg "Executing in strata '$strata_name' ($pm): $strata_command"

    # Decide sandbox tool (prefer bwrap, fallback to chroot)
    local tool="${SANDBOX_TOOL:-auto}"
    if [ "$tool" = "auto" ]; then
        if command -v bwrap >/dev/null 2>&1; then
            tool="bwrap"
        else
            tool="chroot"
        fi
    fi

    case "$tool" in
        bwrap|bubblewrap)
            check_dep bwrap
            # Ensure minimal FS layout exists
            mkdir -p "${strata_path}"/{proc,sys,dev,run,tmp,var,tmp/root,root}
            chmod 1777 "${strata_path}/tmp" 2>/dev/null || true

            # Common bind options
            # - Bind the strata root as / inside the namespace
            # - Provide read-only views of host /usr, /lib etc. if not present in strata
            # - Pass through networking by default
            # - Mount proc, sys, dev from the host (dev in new tmpfs, then selective passthrough)
            local -a bind_opts=(
                --bind "${strata_path}" /
                --proc /proc
                --dev-bind /dev /dev
                --bind /sys /sys
            )

            # If strata root lacks standalone /bin/sh or /bin/bash, provide host base system read-only
            if [ ! -x "${strata_path}/bin/sh" ] && [ ! -x "${strata_path}/bin/bash" ]; then
                mkdir -p "${strata_path}"/{bin,lib,lib64,usr}
                bind_opts+=(
                    --ro-bind-try /bin /bin
                    --ro-bind-try /lib /lib
                    --ro-bind-try /lib64 /lib64
                    --ro-bind-try /usr /usr
                )
            fi

            # --- [最终修复] 健壮的 DNS 处理逻辑 ---
            # --- [FINAL FIX] Robust DNS Handling Logic ---
            #
            # 优先尝试只读绑定主机的 /etc/resolv.conf。
            # --ro-bind-try 在源文件不存在时不会报错，非常适合这种情况。
            #
            # Prioritize a read-only bind of the host's /etc/resolv.conf.
            # --ro-bind-try does not error if the source file is missing, making it perfect for this.
            bind_opts+=( --ro-bind-try /etc/resolv.conf /etc/resolv.conf )

            # 只有当主机文件不存在时，才创建并绑定一个包含备用 DNS 的文件。
            # Only if the host file does not exist, create and bind a file with fallback DNS servers.
            if [ ! -f /etc/resolv.conf ]; then
                info "Host /etc/resolv.conf not found, generating a fallback DNS config for strata."
                info "未找到主机的 /etc/resolv.conf，正在为 strata 生成备用 DNS 配置。"
                
                # 我们需要在 strata 内部的 /etc 目录中创建这个文件，以便 bwrap 可以找到它。
                # We need to create this file inside the strata's /etc so bwrap can find it.
                local fallback_resolv_conf="${strata_path}/etc/resolv.conf.corix_fallback"
                printf 'nameserver %s\n' "${FALLBACK_DNS_SERVERS[@]}" > "$fallback_resolv_conf"
                
                # 将我们生成的备用文件绑定到沙箱内的 /etc/resolv.conf
                # Bind our generated fallback file to /etc/resolv.conf inside the sandbox.
                bind_opts+=( --ro-bind "$fallback_resolv_conf" /etc/resolv.conf )
            fi
            # --- [最终修复结束] ---
            
            # Optional convenience: expose host caches to speed up operations (read-only)
            # 可选的便利性设置: 只读暴露主机的缓存以加速操作
            [ -d /var/cache ] && bind_opts+=( --bind /var/cache /var/cache )
            [ -d /var/tmp ] && bind_opts+=( --bind /var/tmp /var/tmp )

            # Pass through home (read-only by default unless user opts in)
            # 传递 home 目录 (默认只读，除非用户选择加入)
            case "${STRATA_HOME_MODE:-ro}" in
                rw) [ -d "$HOME" ] && bind_opts+=( --bind "$HOME" "$HOME" ) ;;
                ro) [ -d "$HOME" ] && bind_opts+=( --ro-bind "$HOME" "$HOME" ) ;;
                none) : ;;
                *) [ -d "$HOME" ] && bind_opts+=( --ro-bind "$HOME" "$HOME" ) ;;
            esac

            # Expose host package caches optionally
            if [ "${STRATA_EXPOSE_HOST_PKGCACHE:-1}" = "1" ]; then
                [ -d "$BINARY_CACHE" ] && bind_opts+=( --bind "$BINARY_CACHE" "$BINARY_CACHE" )
                [ -d "$SOURCE_CACHE" ] && bind_opts+=( --bind "$SOURCE_CACHE" "$SOURCE_CACHE" )
            fi

            # Build PATH inside strata (fallback to sane defaults)
            local _path="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
            [ -d "${strata_path}/usr/bin" ] && _path="/usr/local/bin:/usr/bin:/bin:/usr/local/sbin:/usr/sbin:/sbin"

            # Shell selection
            local _shell="/bin/bash"
            [ -x "${strata_path}/bin/bash" ] || [ -x "${strata_path}/usr/bin/bash" ] || _shell="/bin/sh"

            # Environment passthrough (minimal)
            local -a env_opts=(
                --setenv PATH "$_path"
                --setenv HOME "${HOME:-/root}"
                --setenv TERM "${TERM:-xterm-256color}"
                --setenv LANG "${LANG:-C.UTF-8}"
                --setenv LC_ALL "${LC_ALL:-}"
            )

            # Workdir
            local _cwd="/"
            [ -d "${strata_path}${PWD}" ] && _cwd="$PWD"

            bwrap "${bind_opts[@]}" \
                  "${env_opts[@]}" \
                  --chdir "$_cwd" \
                  "$_shell" -c "$strata_command"
            ;;
        chroot)
            _internal_check_root_privileges
            
            # [修复] DNS
            # [FIX] DNS
            if [ -f /etc/resolv.conf ]; then
                cp -L /etc/resolv.conf "${strata_path}/etc/resolv.conf" 2>/dev/null || true
            else
                info "Host /etc/resolv.conf not found, generating a fallback DNS config for strata."
                info "未找到主机的 /etc/resolv.conf，正在为 strata 生成备用 DNS 配置。"
                printf 'nameserver %s\n' "${FALLBACK_DNS_SERVERS[@]}" > "${strata_path}/etc/resolv.conf"
            fi

            # Prepare mounts
            mkdir -p "${strata_path}"/{proc,sys,dev}
            mountpoint -q "${strata_path}/proc" || mount --bind /proc "${strata_path}/proc"
            mountpoint -q "${strata_path}/sys"  || mount --bind /sys  "${strata_path}/sys"
            mountpoint -q "${strata_path}/dev"  || mount --bind /dev  "${strata_path}/dev"

            # Workdir
            local _cwd="/"
            [ -d "${strata_path}${PWD}" ] && _cwd="$PWD"

            chroot "$strata_path" /bin/bash -c "cd \"$_cwd\" && $strata_command"
            local rc=$?

            # Cleanup mounts (best-effort)
            umount -l "${strata_path}/proc" 2>/dev/null || true
            umount -l "${strata_path}/sys"  2>/dev/null || true
            umount -l "${strata_path}/dev"  2>/dev/null || true

            return $rc
            ;;
        *)
            error "Unknown sandbox tool: $SANDBOX_TOOL"
            ;;
    esac
}

corix_strata_destroy() {
    _internal_check_root_privileges
    local name="$1"
    local strata_path="${STRATA_DIR}/${name}"

    [ -n "$name" ] || error "Usage: strata --destroy <name>"
    [ -d "$strata_path" ] || error "Strata '$name' does not exist."

    warn "This will completely remove strata '$name' and all its contents."
    read -rp "Are you sure? [y/N] " choice
    [[ ! "$choice" =~ ^[yY] ]] && { info "Cancelled."; return 0; }

    acquire_lock "system"
    trap 'release_lock "system"' RETURN
    
    msg "Destroying strata '$name'..."

    # Best-effort unmount
    if command -v mountpoint >/dev/null 2>&1; then
        mountpoint -q "${strata_path}/proc" && umount -l "${strata_path}/proc" 2>/dev/null || true
        mountpoint -q "${strata_path}/sys"  && umount -l "${strata_path}/sys"  2>/dev/null || true
        mountpoint -q "${strata_path}/dev"  && umount -l "${strata_path}/dev"  2>/dev/null || true
    else
        umount -l "${strata_path}/proc" 2>/dev/null || true
        umount -l "${strata_path}/sys"  2>/dev/null || true
        umount -l "${strata_path}/dev"  2>/dev/null || true
    fi

    # Remove
    rm -rf --one-file-system "${strata_path:?Error: strata_path variable is unset or empty}"

    info "Strata '$name' removed."
}

# [NEW] Exports a list of installed packages from a Strata environment.
# [新增] 从一个 Strata 环境中导出已安装软件包的列表。
#
# Scans the Strata's internal package manager database and prints a list of
# 'strata-pkg:' declarations suitable for inclusion in the world file.
# 扫描 Strata 内部的包管理器数据库，并打印出一系列适用于 world 文件的 'strata-pkg:' 声明。
corix_strata_export_pkgs() {
    local strata_name="$1"
    local strata_path="${STRATA_DIR}/${strata_name}"
    [ -d "$strata_path" ] || error "Strata '$strata_name' not found. / 未找到 Strata '$strata_name'。"

    local strata_conf="${strata_path}/.corix_strata"
    local pm=""
    [ -f "$strata_conf" ] && pm=$(grep '^pm=' "$strata_conf" | cut -d= -f2)

    msg "Exporting package list from Strata '$strata_name' (type: $pm)... / 正在从 Strata '$strata_name' (类型: $pm) 导出软件包列表..."
    
    local list_cmd output
    case "$pm" in
        apt|debian)
            # -W shows packages, -f specifies format. '${Package}\n' gives a clean list.
            # -W 显示包, -f 指定格式。'${Package}\n' 给出干净的列表。
            # We filter out essential packages that are always part of the base system.
            # 我们过滤掉那些总是作为基础系统一部分的核心包。
            list_cmd="dpkg-query -W -f='\${Package}\n' | grep -vE '^(apt|base-files|base-passwd|bash|coreutils|dash|debconf|debian-archive-keyring|debianutils|diffutils|dpkg|e2fsprogs|findutils|grep|gzip|hostname|init-system-helpers|login|mount|ncurses-base|ncurses-bin|perl-base|sed|sysvinit-utils|tar|util-linux)$'"
            ;;
        pacman|arch)
            # -Q lists installed packages, -q makes it quiet (name only).
            # -Q 列出已安装的包, -q 使其安静(只输出包名)。
            list_cmd="pacman -Qq"
            ;;
        dnf|fedora)
            # rpm is faster and cleaner for just listing names.
            # 只列出名称时，rpm 更快、更干净。
            list_cmd="rpm -qa --qf '%{NAME}\n' | grep -vx gpg-pubkey"
            ;;
        portage|gentoo)
            # [修复] 改用 equery 工具进行精确查询，避免手动解析文件名带来的错误。
            # [FIX] Use the equery tool for accurate queries, avoiding errors from manual filename parsing.
            # -F '$category/$name' 选项直接输出我们需要的格式。
            # The -F '$category/$name' option directly outputs the format we need.
            #
            # 我们先检查 equery 是否存在，如果不存在则给出清晰的错误提示。
            # We first check if equery exists and provide a clear error message if it does not.
            list_cmd="
                if ! command -v equery >/dev/null 2>&1; then
                    echo 'Error: equery (from app-portage/gentoolkit) is required to export packages from a Portage strata.' >&2
                    exit 1
                fi
                equery -q list -F '\$category/\$name' '*'
            "
            ;;
        dcpm|decentralized)
            list_cmd="dcpm list --quiet"
            ;;
        *)
            error "Unsupported package manager '$pm' for package export. / 不支持的包管理器 '$pm' 无法导出软件包列表。"
            ;;
    esac

    # Execute the command inside the strata and capture the output
    # 在 strata 内部执行命令并捕获输出
    output=$(corix_strata_execute "$strata_name" "$list_cmd")
    
    echo
    echo "# Packages exported from Strata '$strata_name' on $(date)"
    echo "# 从 Strata '$strata_name' 导出的软件包，导出时间: $(date)"
    echo "# You can copy these lines into your world file. / 您可以将这些行复制到您的 world 文件中。"
    echo
    
    while IFS= read -r pkg_name; do
        [ -n "$pkg_name" ] && echo "strata-pkg:${strata_name}:${pkg_name}"
    done <<< "$output"
}

# [NEW] Promotes an existing Strata environment to the world file.
# [新增] 将一个已存在的 Strata 环境“提升”到 world 文件中。
#
# This command adds the necessary 'strata:' and 'strata-pkg:' declarations
# for a given Strata to the world file, effectively making it part of the
# declarative system state.
# 此命令会将指定 Strata 所需的 'strata:' 和 'strata-pkg:' 声明
# 添加到 world 文件中，从而有效地将其纳为声明式系统状态的一部分。
corix_strata_promote() {
    local strata_name="$1"
    local strata_path="${STRATA_DIR}/${strata_name}"
    [ -d "$strata_path" ] || error "Strata '$strata_name' not found. Cannot promote it. / 未找到 Strata '$strata_name'，无法提升。"

    local strata_conf="${strata_path}/.corix_strata"
    local pm=""
    [ -f "$strata_conf" ] && pm=$(grep '^pm=' "$strata_conf" | cut -d= -f2)
    [ -z "$pm" ] && error "Could not determine the type of Strata '$strata_name'. Promotion failed. / 无法确定 Strata '$strata_name' 的类型，提升失败。"

    msg "Promoting Strata '$strata_name' to the world file... / 正在将 Strata '$strata_name' 提升到 world 文件..."

    # --- Step 1: Prepare the declarations ---
    # --- 步骤 1: 准备声明内容 ---
    info "Generating declarations... / 正在生成声明..."

    # Generate the main strata declaration
    # 生成主 strata 声明
    local strata_declaration="strata:${strata_name}:${pm}"

    # Generate the package declarations by calling the export function internally
    # 通过内部调用导出函数来生成软件包声明
    # We capture the output and process it
    # 我们捕获输出并进行处理
    local exported_pkgs_output
    exported_pkgs_output=$(corix_strata_export_pkgs "$strata_name")
    
    local -a pkg_declarations=()
    # Read the output, skipping the header comments
    # 读取输出，跳过头部的注释行
    mapfile -t pkg_declarations < <(echo "$exported_pkgs_output" | grep '^strata-pkg:')

    # --- Step 2: Check if declarations already exist to avoid duplicates ---
    # --- 步骤 2: 检查声明是否已存在以避免重复 ---
    info "Checking for existing entries in world file... / 正在检查 world 文件中的现有条目..."

    local temp_world_file
    temp_world_file=$(mktemp)
    mkdir -p "$(dirname "$WORLD_FILE")"
    [ -f "$WORLD_FILE" ] || touch "$WORLD_FILE"
    cp "$WORLD_FILE" "$temp_world_file"

    local new_content_to_add=""

    # Check the main strata declaration
    # 检查主 strata 声明
    if ! grep -Fxq "$strata_declaration" "$temp_world_file"; then
        new_content_to_add+="${strata_declaration}\n"
    else
        info "Strata declaration for '$strata_name' already exists. / '$strata_name' 的 Strata 声明已存在。"
    fi

    # Check each package declaration
    # 检查每个软件包声明
    for decl in "${pkg_declarations[@]}"; do
        if ! grep -Fxq "$decl" "$temp_world_file"; then
            new_content_to_add+="${decl}\n"
        fi
    done
    
    # --- Step 3: Append new declarations to the world file ---
    # --- 步骤 3: 将新的声明追加到 world 文件中 ---
    if [ -n "$new_content_to_add" ]; then
        info "Adding new declarations to $WORLD_FILE... / 正在将新的声明添加到 $WORLD_FILE..."
        
        # Add a header comment for clarity
        # 为清晰起见，添加一个头部注释
        printf "\n# Promoted Strata: %s (on %s)\n" "$strata_name" "$(date)" >> "$WORLD_FILE"
        printf "%b" "$new_content_to_add" >> "$WORLD_FILE"
        
        # Clean up by sorting and removing duplicate lines
        # 通过排序和去重来清理文件
        sort -u -o "$WORLD_FILE" "$WORLD_FILE"
        
        msg "Successfully promoted Strata '$strata_name'. / 成功提升 Strata '$strata_name'。"
        info "It is now part of the declarative system state. / 它现在是声明式系统状态的一部分。"
    else
        msg "Strata '$strata_name' and its packages are already fully declared in the world file. Nothing to do. / Strata '$strata_name' 及其软件包已在 world 文件中完全声明。无需操作。"
    fi

    rm -f "$temp_world_file"
}

# 参数: <分类/名称> <版本> <所有者> (Arguments: <category/name> <version> <owner>)
# 在 $INSTALLED_DB 下创建一个最小化记录，用于记载外部所有权。
# (Creates a minimal record under $INSTALLED_DB to record foreign ownership.)
db_mark_installed_external() {
    local pkg_id="$1"
    local ver="$2"
    local owner="$3"

    local cat="${pkg_id%/*}"
    local name="${pkg_id##*/}"
    # [修改] 修正了目录拼接方式以处理没有分类的包
    # [MODIFIED] Corrected directory concatenation to handle packages without a category
    local dst
    if [ -n "$cat" ] && [ "$cat" != "$name" ]; then
        dst="${INSTALLED_DB}/${cat//\//_}/${name}"
    else
        dst="${INSTALLED_DB}/_/${name}" # 使用"_"作为无分类包的目录
    fi

    mkdir -p "$dst"
    echo "$ver" > "${dst}/version"
    echo "$owner" > "${dst}/owner"
    : > "${dst}/files"      # 未知的文件列表 (unknown file list)
    : > "${dst}/metadata"   # 预留字段 (reserved)
}

corix_delta_update() {
    local pkg_id="$1"
    get_pkg_id_parts "$pkg_id"
    local pkg_name="${PKG_CATEGORY}/${PKG_NAME}"
    
    # Get current installed version
    local pkg_dir
    pkg_dir=$(db_get_pkg_dir "$pkg_name" "$PKG_SLOT")
    local current_ver
    current_ver=$(cat "$pkg_dir/version" 2>/dev/null)
    [ -z "$current_ver" ] && return 1
    
    # Find latest version
    local build_file
    build_file=$(find_package_build_file "$pkg_id")
    local meta
    meta=$(_parse_build_file "$build_file")
    local latest_ver
    latest_ver=$(echo "$meta" | grep "^pkgver=" | cut -d= -f2)
    
    # Check if delta update is available
    local delta_url=""
    if echo "$meta" | grep -q "^delta_${current_ver}_${latest_ver}="; then
        delta_url=$(echo "$meta" | grep "^delta_${current_ver}_${latest_ver}=" | cut -d= -f2)
    elif [ -f "$build_file" ] && grep -q "^deltas=" "$build_file"; then
        # Check if build file has delta base URLs
        local delta_base
        delta_base=$(grep "^deltas=" "$build_file" | cut -d= -f2)
        delta_url="${delta_base}/${pkg_name//\//_}-${current_ver}-to-${latest_ver}.delta"
    fi
    
    if [ -n "$delta_url" ]; then
        msg "Found delta update from $current_ver to $latest_ver"
        local delta_file="${SOURCE_CACHE}/${pkg_name//\//_}-${current_ver}-to-${latest_ver}.delta"
        
        # Download delta
        if ! download_source "$delta_url" "$delta_file"; then
            warn "Delta download failed, falling back to full update"
            return 1
        fi
        
        # Apply delta to existing binary package
        local old_pkg="${BINARY_CACHE}/${pkg_name//\//_}-${current_ver}-${PKG_SLOT}-$(uname -m).corix.tar.zst"
        local new_pkg="${BINARY_CACHE}/${pkg_name//\//_}-${latest_ver}-${PKG_SLOT}-$(uname -m).corix.tar.zst"
        
        if command -v xdelta3 >/dev/null 2>&1; then
            info "Applying delta patch with xdelta3..."
            xdelta3 -d -s "$old_pkg" "$delta_file" "$new_pkg" || return 1
        elif command -v bsdiff >/dev/null 2>&1; then
            info "Applying delta patch with bsdiff..."
            bsdiff patch "$old_pkg" "$delta_file" "$new_pkg" || return 1
        else
            warn "No delta patch tool available (need xdelta3 or bsdiff)"
            return 1
        fi
        
        # Verify new package
        local expected_hash
        expected_hash=$(echo "$meta" | grep "^sha256sums=" | cut -d= -f2 | head -1)
        local actual_hash
        actual_hash=$(calculate_hash "$new_pkg")
        
        if [ "$expected_hash" = "$actual_hash" ]; then
            info "Delta update verified successfully"
            echo "$new_pkg"
            return 0
        else
            warn "Delta update verification failed (expected $expected_hash, got $actual_hash)"
            rm -f "$new_pkg"
            return 1
        fi
    fi
    
    return 1
}

# ==============================================================================================
# --- [V72 UPGRADE] corix_gen_build - 智能构建文件生成器 (Smart Build File Generator) ---
# ==============================================================================================
# ==============================================================================================
# --- [V72 UPGRADE] corix_gen_build - 智能构建文件生成器 (Smart Build File Generator) ---
# --- [BUGFIX APPLIED] - 修正了处理本地目录时的 unbound variable 问题
# ==============================================================================================
corix_gen_build() {
    # --- 1. 参数解析 (使用 getopt) / Argument Parsing (with getopt) ---
    local options; options=$(getopt -o '' --long "template:,auto-detect,output-dir:,pkgname:,pkgver:,pkgdesc:,slot:,depends:,makedepends:,executable:,dapp-entrypoint:,handles-tx-types:,help" -n 'gen-build' -- "$@")
    [ $? -ne 0 ] && { usage_gen_build; return 1; }

    local template="" auto_detect=1 output_dir="" pkgname="" pkgver="" pkgdesc="Automatically generated package"
    local slot="0" depends_str="" makedepends_str="" executable="" dapp_entrypoint="app.py" url_or_dir="" handles_tx_types_str=""

    eval set -- "$options"
    while true; do
        case "$1" in
            --template) template="$2"; auto_detect=0; shift 2 ;;
            --auto-detect) auto_detect=1; shift ;;
            --output-dir) output_dir="$2"; shift 2 ;;
            --pkgname) pkgname="$2"; shift 2 ;;
            --pkgver) pkgver="$2"; shift 2 ;;
            --pkgdesc) pkgdesc="$2"; shift 2 ;;
            --slot) slot="$2"; shift 2 ;;
            --depends) depends_str=$(echo "$2" | tr ',' ' '); shift 2 ;;
            --makedepends) makedepends_str=$(echo "$2" | tr ',' ' '); shift 2 ;;
            --executable) executable="$2"; shift 2 ;;
            --dapp-entrypoint) dapp_entrypoint="$2"; shift 2 ;;
            --handles-tx-types) handles_tx_types_str=$(echo "$2" | tr ',' ' '); shift 2 ;; # 新增
            --help) usage_gen_build; return 0 ;;
            --) shift; break ;;
        esac
    done
    url_or_dir="$1"

    [ -z "$url_or_dir" ] && { usage_gen_build; return 0; }
    
    # --- [BUGFIX] 步骤 2: 元数据猜测 (提前) ---
    [ -z "$pkgname" ] && pkgname=$(basename "$url_or_dir" | sed -E 's/(\.tar\.gz|\.tar\.bz2|\.tar\.xz|\.tar\.zst|\.zip)//' | sed -E 's/(-|_)[vV]?[0-9].*//' | sed 's/\.git$//')
    [ -z "$pkgver" ] && pkgver=$(basename "$url_or_dir" | grep -oE '[0-9]+\.[0-9]+(\.[0-9]+)?' | head -1)
    [ -z "$pkgver" ] && pkgver="1.0.0" # Fallback
    
    # --- 3. [核心重构] 源码处理与哈希生成 ---
    local source_line=""
    local sha_line=""

    if [ -d "$url_or_dir" ]; then
        info "正在为本地目录生成元数据... / Generating metadata for local directory..."
        
        # 关键：source 指向目录名本身。我们假设 .build 文件会和源码目录在同一个父目录下。
        # The key: source points to the directory name itself. We assume the .build file
        # will live in the same parent directory as the source directory.
        local src_dir_name=$(basename "$url_or_dir")
        source_line="source=(\"${src_dir_name}\")"
        
        # 为了得到一个确定性的哈希，我们将目录打包到标准输出，然后计算哈希。
        # To get a deterministic hash, we tar the directory to stdout and then calculate the hash.
        info "正在计算目录内容的确定性哈希... / Calculating deterministic hash of directory contents..."
        local dir_content_hash
        dir_content_hash=$(tar -C "$(dirname "$url_or_dir")" -cf - "$src_dir_name" | sha256sum | awk '{print $1}')
        
        sha_line="sha256sums=(\"${dir_content_hash}\")"
        
    else
        # 处理远程URL的逻辑保持不变
        info "正在下载源码以生成元数据... / Downloading source to generate metadata..."
        local temp_dl_file; temp_dl_file=$(mktemp)
        CORIUM_TEMP_ITEMS+=("$temp_dl_file")
        download_source "$url_or_dir" "$temp_dl_file"
        
        source_line="source=(\"${url_or_dir}\")"
        sha_line="sha256sums=(\"$(calculate_hash "$temp_dl_file")\")"
    fi

    # --- 4. 模板自动检测 / Template Auto-Detection ---
    if [ "$auto_detect" -eq 1 ] && [ -z "$template" ]; then
        info "正在自动检测项目类型... / Auto-detecting project type..."
        if [ -f "${temp_source_dir}/CMakeLists.txt" ]; then template="cmake";
        elif [ -f "${temp_source_dir}/meson.build" ]; then template="meson";
        elif [ -f "${temp_source_dir}/setup.py" ] || [ -f "${temp_source_dir}/pyproject.toml" ]; then template="python";
        elif [ -f "${temp_source_dir}/Makefile" ]; then template="plain-make";
        else template="regular"; fi
        msg "检测到类型 / Detected type: \033[1;32m${template}\033[0m"
    fi

    # --- 5. 准备输出 / Prepare Output ---
    # (此部分及之后的模板渲染部分保持不变)
    local build_file_content=""
    local final_build_file=""
    if [ -n "$output_dir" ]; then
        mkdir -p "$output_dir"
        final_build_file="${output_dir}/${pkgname}.build"
        info "将在以下位置生成文件 / Build file will be generated at: ${final_build_file}"
    else
        info "将 .build 文件内容输出到标准输出 / Outputting .build file content to stdout:"
        echo "--------------------------------------------------"
    fi
    
    # --- 6. 模板渲染 / Template Rendering ---
    local build_file_content="" final_build_file=""
    if [ -n "$output_dir" ]; then
        mkdir -p "$output_dir"
        final_build_file="${output_dir}/${pkgname}.build"
        info "将在以下位置生成文件 / Build file will be generated at: ${final_build_file}"
    else
        info "将 .build 文件内容输出到标准输出 / Outputting .build file content to stdout:"
        echo "--------------------------------------------------"
    fi
    
    local depends_line="depends=(${depends_str})"
    local makedepends_line="makedepends=(${makedepends_str})"

    # Common Header
    build_file_content+=$(cat <<EOF
# Corium Build File (模板 / Template: ${template})
# 生成时间 / Generated on: $(date)

pkgname="${pkgname}"
pkgver="${pkgver}"
pkgdesc="${pkgdesc}"
url="${url_or_dir}"
slot="${slot}"

${source_line}
${sha_line}

${depends_line}
${makedepends_line}
EOF
)

    # [最终智能修复] 动态生成 prepare() 函数
    # [FINAL SMART FIX] Dynamically generate the prepare() function
    local prepare_function=""
    # 只有当源码是一个压缩包时 (即不是一个 git repo)，我们才需要 cd
    # We only need to cd if the source is an archive (i.e., not a git repo)
    if [[ "$url_or_dir" != git* ]]; then
        prepare_function=$(cat <<'EOP'
# prepare() 函数负责进入解压后正确的源码子目录。
# The prepare() function is responsible for entering the
# correct source subdirectory after extraction.
prepare() {
    cd "${pkgname}-${pkgver}"
}
EOP
)
fi
    case "$template" in
        cmake)
            build_file_content+=$(cat <<EOF

makedepends+=("cmake" "make")
${prepare_function}
build() {
    cmake -B build -S . -DCMAKE_INSTALL_PREFIX=/usr
    cmake --build build --parallel \${MAKEFLAGS}
}

package() {
    DESTDIR="\${pkgdir}" cmake --install build
}
EOF
)
            ;;
        meson)
            build_file_content+=$(cat <<EOF

makedepends+=("meson" "ninja")
${prepare_function}
build() {
    meson setup build --prefix=/usr
    meson compile -C build -j \${MAKEFLAGS}
}

package() {
    DESTDIR="\${pkgdir}" meson install -C build
}
EOF
)
            ;;
        python)
            build_file_content+=$(cat <<EOF

makedepends+=("python-pip" "python-build" "python-installer")
${prepare_function}
build() {
    python -m build --wheel --no-isolation
}

package() {
    pip install --root="\${pkgdir}" --no-deps --no-build-isolation dist/*.whl
}
EOF
)
            ;;
        "plain-make")
            build_file_content+=$(cat <<EOF
${prepare_function}
makedepends+=("make")

build() {
    make \${MAKEFLAGS}
}

package() {
    make DESTDIR="\${pkgdir}" PREFIX=/usr install
}
EOF
)
            ;;
            "mod-cli")
        [ -z "$executable" ] && error "错误: --template=mod-cli 需要 --executable 参数。 / Error: --template=mod-cli requires --executable argument."
        build_file_content+=$(cat <<EOF

# --- Mod 元数据 ---
corix_mod_type="cli_command"
executable="${executable}"
${prepare_function}
package() {
    # [最终修正] 我们现在可以直接引用可执行文件，因为 prepare() 确保了我们在正确的目录
    # [FINAL FIX] We can now directly reference the executable, as prepare() ensures we are in the correct directory.
    install -D -m 0755 "${executable}" "\${pkgdir}/usr/bin/\${pkgname}"
}
EOF
)
        ;;
        
        dapp)
            build_file_content+=$(cat <<EOF

# --- DApp 元数据 ---
corix_mod_type="dapp_engine"
${prepare_function}
# DApp 'package' 函数将整个源码目录复制到安装目录
# The DApp 'package' function copies the entire source dir to the installation dir
package() {
    cp -a . "\${pkgdir}/usr/share/corix/dapps/\${pkgname}"
}
EOF
)
            # Create a basic DApp file structure if an output dir is specified
            if [ -n "$output_dir" ] && [ "$source_is_local" -eq 1 ]; then
                info "正在为 DApp 创建基本文件结构... / Creating basic file structure for DApp..."
                local dapp_src_path="$output_dir" # Now generate inside the target dir
                if [ ! -f "${dapp_src_path}/index.html" ]; then
                    echo "<h1>Welcome to ${pkgname}!</h1>" > "${dapp_src_path}/index.html"
                fi
                if [ ! -f "${dapp_src_path}/${dapp_entrypoint}" ]; then
                    cat > "${dapp_src_path}/${dapp_entrypoint}" <<PYEOF
# Corium DApp Entrypoint for ${pkgname}
# This script runs in a secure, sandboxed environment.

# 'request' is a dictionary injected by the gateway, containing path and query info.
# 'request' 是由网关注入的字典，包含路径和查询参数。

# 'api' is the bridge to the Corium core.
# 'api' 是通往 Corium 核心的桥梁。

page_title = "My First Cor-Web DApp"
page_content = f"Hello from {page_title}! You requested path: {request.get('path')}"

# The 'response' variable will be sent to the user's browser.
# 'response' 变量的内容将被发送到用户的浏览器。
response = f"""
<!DOCTYPE html>
<html>
<head>
    <title>{page_title}</title>
</head>
<body>
    <h1>{page_content}</h1>
</body>
</html>
"""
PYEOF
                fi
            fi
            ;;
        # --- [V83 新增] App Template 的模板 ---
        # --- [V83 NEW] Template for App Templates ---
        "app-template")
            [ -z "$handles_tx_types_str" ] && error "错误: --template=app-template 需要 --handles-tx-types 参数。/ Error: --template=app-template requires --handles-tx-types argument."
            
            build_file_content+=$(cat <<EOF

# --- 应用模板元数据 / App Template Metadata ---
corix_mod_type="application_template"
handles_tx_types=(${handles_tx_types_str})
${prepare_function}
# 应用模板的 package() 函数负责创建我们约定的特殊结构。
# The package() function for an App Template is responsible for creating
# the special structure we have agreed upon.
package() {
    # 1. 复制应用逻辑文件
    # 1. Copy the application logic files
    install -D -m 0644 "\${srcdir}/state_logic.py" "\${pkgdir}/state_logic.py"
    install -D -m 0644 "\${srcdir}/schema.sql" "\${pkgdir}/schema.sql"
    install -D -m 0644 "\${srcdir}/db_permissions.json" "\${pkgdir}/db_permissions.json"

    # 2. 创建 .corium 元数据目录
    # 2. Create the .corium metadata directory
    mkdir -p "\${pkgdir}/.corium"

    # 3. 将本 .build 文件自身复制到包内
    # 3. Copy this very .build file into the package
    cp "\${build_file}" "\${pkgdir}/.corium/template.build"

    # 4. 生成文件清单
    # 4. Generate the file manifest
    (cd "\${pkgdir}" && find . -type f | sed 's|^\./||' | grep -v '^\.corium' | sort) > "\${pkgdir}/.corium/manifest.files"
}
EOF
)
            # 如果指定了输出目录，则为开发者创建模板文件的骨架
            # If an output directory is specified, create skeleton template files for the developer
            if [ -n "$output_dir" ]; then
                info "正在为应用模板创建骨架文件... / Creating skeleton files for the App Template..."
                local src_path="$output_dir" # 在目标目录内生成
                
                # state_logic.py
                if [ ! -f "${src_path}/state_logic.py" ]; then
                    local handlers=""
                    for type in $handles_tx_types_str; do
                        handlers+="def on_${type}(api, tx_data):\n    if not isinstance(tx_data, dict) or not tx_data.get('hash'):\n        raise ValueError('transaction requires hash')\n    if api is not None and hasattr(api, 'record_event'):\n        api.record_event('${type}', tx_data)\n    bilingual_print(f'Processing transaction {tx_data[\"hash\"]}', f'正在处理交易 {tx_data[\"hash\"]}')\n    return {'type': '${type}', 'hash': tx_data['hash']}\n\n"
                    done
                    printf "#!/usr/bin/env python3\n\n%s" "$handlers" > "${src_path}/state_logic.py"
                fi
                # schema.sql
                [ ! -f "${src_path}/schema.sql" ] && echo "-- 为您的应用在此处定义 CREATE TABLE 语句 / Define CREATE TABLE statements for your app here" > "${src_path}/schema.sql"
                # db_permissions.json
                [ ! -f "${src_path}/db_permissions.json" ] && echo '{ "permissions": { "my_table": ["SELECT", "INSERT"] } }' > "${src_path}/db_permissions.json"
            fi
            ;;
        regular|*)
            build_file_content+=$(cat <<EOF

# This is a generic template. You will likely need to edit build() and package().
# 这是一个通用模板，您很可能需要编辑 build() 和 package() 函数。
${prepare_function}
build() {
    # e.g., ./configure --prefix=/usr
    echo "No build() steps defined. / 未定义 build() 步骤。"
}

package() {
    # e.g., make DESTDIR="\${pkgdir}" install
    error "package() function is not defined! / package() 函数未定义！"
}
EOF
)
            
            ;;
    esac

    if [ -n "$output_dir" ]; then
        echo "$build_file_content" > "$final_build_file"
        msg "✅ .build 文件已成功生成！ / .build file generated successfully!"
    else
        echo "$build_file_content"
    fi
}

