# --- SECTION 23.5: VALIDATOR GOVERNANCE CLI (NEW)    ---
# --- 第23.5节: 验证者治理命令行界面 (新增)           ---
# =======================================================

# The user-facing command dispatcher for 'corix validator' (extended)
# 'corix validator' 的用户侧命令分发器 (扩展版)
corix_validator() {
    # check_permissions is called in the main dispatcher.
    # check_permissions 会在主分发器中被调用。
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        propose-add)
            [ $# -ne 2 ] && { usage_validator; exit 1; }
            corix_validator_propose_add "$1" "$2"
            ;;
        propose-remove)
            [ $# -ne 1 ] && { usage_validator; exit 1; }
            corix_validator_propose_remove "$1"
            ;;
        vote)
            [ $# -ne 2 ] && { usage_validator; exit 1; }
            corix_validator_vote "$1" "$2"
            ;;
        list-proposals)
            msg "Active Governance Proposals / 进行中的治理提议"
            echo "-------------------------------------------------"
            local VOTE_WINDOW=100
            db_query_safe "$BLOCKCHAIN_DB" "
                SELECT T.hash, T.type, T.data, B.height
                FROM transactions AS T
                JOIN blocks AS B ON T.block_height = B.height
                WHERE (T.type = 'validator_propose_addition' OR T.type = 'validator_propose_removal')
                AND (B.height + %d) > (SELECT MAX(height) FROM blocks);
            " "$VOTE_WINDOW" | while IFS='|' read -r hash type data height; do
                local current_height
                current_height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT MAX(height) FROM blocks;")
                local end_height=$((height + VOTE_WINDOW))
                echo -e "  \033[1;32mProposal Hash\033[0m: ${hash}"
                echo "  Type: ${type}"
                echo "  Details: $(echo "$data" | jq -c .)"
                echo -e "  Voting ends at block \033[1;33m${end_height}\033[0m (~${end_height - current_height} blocks remaining)"
                echo
            done
            ;;
        *)
            usage_validator
            ;;
    esac
}

# Displays detailed help for the validator command.
# 显示 validator 命令的详细帮助信息。
usage_validator() {
    echo "corix validator: On-chain validator governance command set."
    echo "corix validator: 链上验证者治理命令集。"
    echo
    echo "Usage: corix validator <subcommand> [arguments...]"
    echo "用法:  corix validator <子命令> [参数...]"
    echo
    echo "Subcommands (子命令):"
    echo "  propose-add <pubkey_file> <stake>    Propose to add a new validator to the network."
    echo "                                       (提议增加一个新验证者到网络中。)"
    echo "  propose-remove <pubkey_hash>         Propose to remove an existing validator from the active set."
    echo "                                       (提议从活跃集合中移除一个现有验证者。)"
    echo "  vote <proposal_hash> <yes|no>        Vote on an active proposal."
    echo "                                       (对一个进行中的提议进行投票。)"
    echo "  list-proposals                       List all active proposals that can be voted on."
    echo "                                       (列出所有可以进行投票的、正在进行中的提议。)"
}

# Creates a transaction to propose adding a new validator.
# 创建一个提议增加新验证者的交易。
corix_validator_propose_add() {
    # 接收来自 corix_validator 分发器的参数
    # Receives arguments from the corix_validator dispatcher
    local pubkey_file="$1"
    local initial_stake="$2"
    
    # 1. 输入验证 (Input Validation)
    [ ! -f "$pubkey_file" ] && error "Public key file not found: $pubkey_file / 未找到公钥文件: $pubkey_file"
    # 使用更严格的正则表达式，确保 stake 是一个没有前导零的正整数
    # Use a stricter regex to ensure stake is a positive integer without leading zeros
    [[ "$initial_stake" =~ ^[1-9][0-9]*$ ]] || error "Stake must be a positive integer. / Stake 必须是一个正整数。"

    # 2. 准备交易数据 (Prepare Transaction Data)
    local pubkey
    pubkey=$(cat "$pubkey_file")
    
    # 构造 validator_propose_addition 交易的 payload
    # Construct the payload for the validator_propose_addition transaction
    local tx_data
    tx_data=$(jq -n \
        --arg pubkey "$pubkey" \
        --argjson stake "$initial_stake" \
        '{target_pubkey: $pubkey, initial_stake: $stake}')
    
    # 3. 执行并向用户反馈 (Execute and Provide Feedback)
    info "Submitting proposal to add a new validator... / 正在提交增加新验证者的提议..."
    detail "  -> Public Key from: $(basename "$pubkey_file")"
    detail "  -> Initial Stake: $initial_stake"
    
    # 调用核心函数创建并广播交易
    # Call the core function to create and broadcast the transaction
    blockchain_create_transaction "validator_propose_addition" "$tx_data"
}

# Creates a transaction to propose removing an existing validator.
# 创建一个提议移除现有验证者的交易。
corix_validator_propose_remove() {
    local pubkey_hash="$1"
    local tx_data
    tx_data=$(jq -n --arg hash "$pubkey_hash" '{target_pubkey_hash: $hash}')

    info "Submitting proposal to remove validator ${pubkey_hash:0:16}... / 正在提交移除验证者 ${pubkey_hash:0:16} 的提议..."
    blockchain_create_transaction "validator_propose_removal" "$tx_data"
}

# Creates a transaction to vote on a proposal.
# 创建一个对提议进行投票的交易。
corix_validator_vote() {
    local proposal_hash="$1"
    local vote_choice="$2"
    
    # 1. 输入验证 (Input Validation)
    [[ "$vote_choice" =~ ^(yes|no)$ ]] || { error "Vote must be 'yes' or 'no'. / 投票必须是 'yes' 或 'no'。"; usage_validator; return 1; }
    
    # 2. “No”票的逻辑处理
    #    'no' 票通过不提交交易来表示。向用户解释后直接返回。
    # 2. Logic handling for 'no' votes
    #    'no' votes are cast by not submitting a transaction. Explain to the user and return.
    if [ "$vote_choice" = "no" ]; then
        info "A 'no' vote is cast by not submitting a 'yes' vote. No transaction will be created."
        info "'no' 票通过不提交 'yes' 票来表示。不会创建任何交易。"
        return 0
    fi
    
    # 3. 确定提案类型，以决定正确的投票交易类型
    # 3. Determine the proposal type to decide the correct vote transaction type
    local proposal_type
    proposal_type=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT type FROM transactions WHERE hash = %s;" "$proposal_hash")

    local vote_tx_type=""
    case "$proposal_type" in
        "validator_propose_addition")
            vote_tx_type="validator_vote_addition" ;;
        "validator_propose_removal")
            vote_tx_type="validator_vote_removal" ;;
        "propose_new_compute_engine")
            vote_tx_type="vote_on_compute_engine" ;;
        "propose_app_template")
            vote_tx_type="vote_app_template" ;;
        "propose_ibc_verifier")
            vote_tx_type="vote_ibc_verifier" ;;
        "propose_federation_key")
            vote_tx_type="vote_federation_key" ;;
        *)
            # 如果提案不存在或类型不可投票，则报错
            # Error out if the proposal does not exist or is not a votable type
            error "Cannot vote on transaction type '${proposal_type:-not found}'. Is this a valid, active proposal? / 无法对 '${proposal_type:-未找到}' 类型的交易进行投票。这是一个有效的、进行中的提案吗？"
            return 1
            ;;
    esac
    
    # 4. 构造并提交交易
    # 4. Construct and submit the transaction
    local tx_data
    tx_data=$(jq -n --arg hash "$proposal_hash" --arg vote "$vote_choice" '{proposal_tx_hash: $hash, vote: $vote}')

    info "Casting 'yes' vote for proposal ${proposal_hash:0:16}... / 正在为提议 ${proposal_hash:0:16} 投出 'yes' 票..."
    
    blockchain_create_transaction "$vote_tx_type" "$tx_data"
}


