# --- [新功能] alias 命令分发器 / [NEW] alias command dispatcher ---
corix_alias() {
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        set)
            [ $# -ne 2 ] && { echo "Usage: corix alias set <alias_name> <channel_id>" >&2; echo "用法: corix alias set <别名> <频道ID>" >&2; exit 1; }
            local alias_name="$1"
            local channel_id="$2"
            if db_execute_safe "$FORUM_DB" "INSERT OR REPLACE INTO aliases (alias_name, channel_id) VALUES (%s, %s);" "$alias_name" "$channel_id"; then
                msg "别名已设置 / Alias set: '${alias_name}' -> '${channel_id:0:16}...'"
            else
                error "设置别名失败。可能是ID或名称无效。 / Failed to set alias. The ID or name may be invalid."
            fi
            ;;
        unset)
            [ $# -ne 1 ] && { echo "Usage: corix alias unset <alias_name>" >&2; echo "用法: corix alias unset <别名>" >&2; exit 1; }
            db_execute_safe "$FORUM_DB" "DELETE FROM aliases WHERE alias_name = %s;" "$1"
            msg "别名已移除 / Alias unset: '$1'"
            ;;
        list|ls)
            msg "频道别名列表: / List of Channel Aliases:"
            db_query_static "$FORUM_DB" "SELECT alias_name, channel_id FROM aliases ORDER BY alias_name;" | while IFS='|' read -r alias_name channel_id; do
                echo "  ${alias_name} -> $(_get_identity_nickname "$channel_id") (${channel_id:0:16}...)"
            done
            ;;
        *)
            echo "corix alias: Manage local aliases for channel IDs."
            echo "corix alias: 管理频道ID的本地别名。"
            echo
            echo "Usage: corix alias <set|unset|list> [arguments...]"
            echo "用法:  corix alias <set|unset|list> [参数...]"
            echo
            echo "  set <alias> <id>      Create or update an alias. / 创建或更新一个别名。"
            echo "  unset <alias>       Remove an alias. / 移除一个别名。"
            echo "  list                List all defined aliases. / 列出所有已定义的别名。"
            ;;
    esac
}

