    echo "  admin <broadcast_id> <add|remove> <user_id>"
    echo "                                     Propose to add or remove an admin. / 提议增加或移除一个管理员。"
    echo "  vote <proposal_hash> yes           Vote 'yes' on an admin change proposal. / 对管理员变更提议投赞成票。"
    echo "  list-subscriptions                 List all your subscribed channels. / 列出您所有已订阅的频道。"
}
corix_broadcast() {
    local sub_cmd="${1:-}"
    shift || true
    case "$sub_cmd" in
        create)
            [ $# -ne 1 ] && { usage_broadcast; exit 1; }
            local nickname="$1"
            local my_hash=$(_forum_get_identity)
            local tx_data=$(jq -n --arg name "$nickname" --arg owner "$my_hash" '{nickname: $name, owners: [$owner]}')
            info "Submitting transaction to create broadcast channel '${nickname}'... / 正在提交创建广播频道 '${nickname}' 的交易..."
            blockchain_create_transaction "broadcast_create" "$tx_data"
            ;;
        subscribe)
            [ $# -ne 1 ] && { usage_broadcast; exit 1; }
            db_execute_safe "$FORUM_DB" "INSERT OR IGNORE INTO subscriptions (id, type) VALUES (%s, 'broadcast');" "$1"
            msg "Successfully subscribed to broadcast ${1:0:16}... / 已成功订阅广播 ${1:0:16}..."
            ;;
        unsubscribe)
            [ $# -ne 1 ] && { usage_broadcast; exit 1; }
            db_execute_safe "$FORUM_DB" "DELETE FROM subscriptions WHERE id = %s AND type = 'broadcast';" "$1"
            msg "Successfully unsubscribed from broadcast ${1:0:16}... / 已成功取消订阅广播 ${1:0:16}..."
            ;;
        post)
            [ $# -lt 1 ] && { usage_broadcast; exit 1; }
            corix_message send "$@"
            ;;
        admin)
            [ $# -ne 3 ] && { usage_broadcast; exit 1; }
            local broadcast_id="$1" action="$2" target_id="$3"
            [[ "$action" =~ ^(add|remove)$ ]] || { usage_broadcast; exit 1; }
            local tx_data=$(jq -n --arg bid "$broadcast_id" --arg act "$action" --arg tid "$target_id" '{broadcast_id: $bid, action: $act, target_id: $tid}')
            info "Proposing to ${action} admin ${target_id:0:12} for broadcast ${broadcast_id:0:12}... / 正在提议为广播 ${broadcast_id:0:12} ${action} 管理员 ${target_id:0:12}..."
            blockchain_create_transaction "broadcast_propose_admin_change" "$tx_data"
            ;;
        vote)
            [ $# -ne 2 ] || [ "$2" != "yes" ] && { usage_broadcast; exit 1; }
            local proposal_hash="$1"
            local tx_data=$(jq -n --arg hash "$proposal_hash" --arg vote "yes" '{proposal_tx_hash: $hash, vote: $vote}')
            info "Casting 'yes' vote for proposal ${proposal_hash:0:16}... / 正在为提议 ${proposal_hash:0:16} 投出 'yes' 票..."
            blockchain_create_transaction "broadcast_vote_admin_change" "$tx_data"
            ;;
        list-subscriptions)
            msg "Your broadcast subscriptions: / 您的广播订阅:"
            db_query_static "$FORUM_DB" "SELECT id FROM subscriptions WHERE type = 'broadcast';" | while IFS= read -r bid; do
                local nickname=$(_get_identity_nickname "$bid" "broadcast")
                echo "  - ${nickname} (${bid:0:16}...)"
            done
            ;;
        *) usage_broadcast ;;
    esac
}

