    echo "                                                 (邀请一个用户加入群组 (管理员及以上))"
    echo "  kick <group_id> <user_id>                    Kick a user from the group (Admin+)."
    echo "                                                 (从群组中踢出一个用户 (管理员及以上))"
    echo "  admin <group_id> <add|remove> <user_id>      Add or remove an admin (Owner only)."
    echo "                                                 (增加或移除一个管理员 (仅群主))"
    echo "  set-owner <group_id> <new_owner_id>          Transfer ownership of the group (Owner only)."
    echo "                                                 (转移群组所有权 (仅群主))"
    echo "  set-policy <group_id> --join-mode <open|invite-only> --desc \"...\""
    echo "                                                 Set the group's join policy and description (Owner only)."
    echo "                                                 (设置群组的加入策略和描述 (仅群主))"
}


# The user-facing command dispatcher for 'corix group'.
# This version is fully refactored to use the unified on-chain ACL system.
# 'corix group' 的用户侧命令分发器。
# 此版本已完全重构，以使用统一的链上 ACL 系统。
# The user-facing command dispatcher for 'corix group'.
# 'corix group' 的用户侧命令分发器。
# =======================================================
# --- FILE: corix.sh (FINAL CORRECTED FUNCTION)         ---
# --- 文件: corix.sh (最终修正版函数)                   ---
# =======================================================

# The user-facing command dispatcher for 'corix group'.
# 'corix group' 的用户侧命令分发器。
corix_group() {
    acquire_lock "network"
    trap 'release_lock "network"' RETURN

    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        create)
            [ $# -ne 1 ] && { usage_group; exit 1; }
            local nickname="$1"
            local my_hash=$(_forum_get_identity)
            local tx_data=$(jq -n --arg name "$nickname" --arg owner "$my_hash" '{nickname: $name, initial_owner: $owner}')
            info "正在提交创建群组 '${nickname}' 的交易... / Submitting transaction to create group '${nickname}'..."
            blockchain_create_transaction "group_create" "$tx_data"
            ;;
        info)
            [ $# -ne 1 ] && { usage_group; exit 1; }
            _update_chain_state_cache >/dev/null 2>&1
            local group_id="$1"
            local group_info=$(db_query_safe "$FORUM_DB" "SELECT nickname, json(permissions) FROM identity_cache WHERE id_hash = %s AND type = 'group';" "$group_id")
            [ -z "$group_info" ] && { error "群组未找到。 / Group not found."; exit 1; }
            local nickname perms; IFS='|' read -r nickname perms <<< "$group_info"
            echo -e "群组信息 / Group Info for: \033[1;32m${nickname}\033[0m"; echo -e "ID: ${group_id}"
            local join_mode desc; join_mode=$(echo "$perms" | jq -r '.policy.join_mode // "invite-only"'); desc=$(echo "$perms" | jq -r '.policy.description // ""')
            echo "策略 / Policy: ${join_mode}"; echo "描述 / Description: ${desc}"; echo "---------------------------------"
            db_query_safe "$FORUM_DB" "SELECT grantee_id, json(permissions) FROM acl_state WHERE acl_id = %s;" "$group_id" | while IFS='|' read -r user_id user_perms; do
                local perms_str=$(echo "$user_perms" | jq -r 'join(", ")'); echo "  - $(_get_identity_nickname "$user_id") (${user_id:0:16}...) -> [${perms_str}]"; done;;
        history)
            [ $# -ne 1 ] && { usage_group; exit 1; }; corix_group_history "$1";;
        join)
            [ $# -ne 1 ] && { usage_group; exit 1; }; local group_id="$1"; local tx_data=$(jq -n --arg gid "$group_id" '{group_id: $gid}')
            info "正在尝试加入群组... / Attempting to join group..."; blockchain_create_transaction "group_member_join" "$tx_data";;
        leave)
            [ $# -ne 1 ] && { usage_group; exit 1; }; local group_id="$1"; local my_hash=$(_forum_get_identity)
            local tx_data=$(jq -n --arg aid "$group_id" --arg gid "$my_hash" --argjson p '["member", "admin"]' '{acl_id:$aid, grantee_id:$gid, permissions:$p}')
            info "正在提交离开群组的交易... / Submitting transaction to leave group..."; blockchain_create_transaction "acl_revoke" "$tx_data";;
        invite)
            [ $# -ne 2 ] && { usage_group; exit 1; }; local group_id="$1"; local user_id="$2"
            local tx_data=$(jq -n --arg aid "$group_id" --arg gid "$user_id" --argjson p '["member"]' '{acl_id:$aid, grantee_id:$gid, permissions:$p}')
            info "正在提交邀请交易... / Submitting invite transaction..."; blockchain_create_transaction "acl_grant" "$tx_data";;
        kick)
            [ $# -ne 2 ] && { usage_group; exit 1; }; local group_id="$1"; local user_id="$2"
            local tx_data=$(jq -n --arg aid "$group_id" --arg gid "$user_id" --argjson p '["member", "admin"]' '{acl_id:$aid, grantee_id:$gid, permissions:$p}')
            info "正在提交踢出交易... / Submitting kick transaction..."; blockchain_create_transaction "acl_revoke" "$tx_data";;
            
        # --- [已修复] admin 命令现在是一个完整的分发器 ---
        # --- [FIXED] The 'admin' command is now a full dispatcher ---
        admin)
            [ $# -lt 2 ] && { usage_group; exit 1; }
            local group_id="$1"
            local action="$2"
            shift 2
            
            local tx_data
            case "$action" in
                add|remove)
                    [ $# -ne 1 ] && { usage_group; exit 1; }
                    local user_id="$1"
                    local tx_type="acl_grant"; [ "$action" = "remove" ] && tx_type="acl_revoke"
                    tx_data=$(jq -n --arg aid "$group_id" --arg gid "$user_id" --argjson p '["admin"]' '{acl_id:$aid, grantee_id:$gid, permissions:$p}')
                    info "正在提交管理员变更交易 (群主直接操作)... / Submitting admin change transaction (Owner direct action)..."
                    blockchain_create_transaction "$tx_type" "$tx_data"
                    ;;
                
                wiki-force-unlock)
                    [ $# -ne 1 ] && { usage_group; exit 1; }
                    local page_slug="$1"
                    tx_data=$(jq -n --arg gid "$group_id" --arg act "$action" --arg slug "$page_slug" '{group_id:$gid, action:$act, target:{page_slug:$slug}}')
                    info "正在提交强制解锁交易... / Submitting force-unlock transaction..."
                    blockchain_create_transaction "group_admin_action" "$tx_data"
                    ;;

                wiki-rename-slug)
                    [ $# -ne 2 ] && { usage_group; exit 1; }
                    local old_slug="$1" new_slug="$2"
                    tx_data=$(jq -n --arg gid "$group_id" --arg act "$action" --arg old "$old_slug" --arg new "$new_slug" '{group_id:$gid, action:$act, target:{old_slug:$old, new_slug:$new}}')
                    info "正在提交 Wiki 页面重命名交易... / Submitting wiki page rename transaction..."
                    blockchain_create_transaction "group_admin_action" "$tx_data"
                    ;;

                wiki-delete-page)
                    [ $# -ne 1 ] && { usage_group; exit 1; }
                    local page_slug="$1"
                    warn "!!! 危险操作: 这将永久删除页面 '${page_slug}' 及其所有历史记录。"
                    warn "!!! DANGEROUS ACTION: This will permanently delete the page '${page_slug}' and all of its history."
                    read -rp "您确定吗？[y/N] / Are you sure? [y/N] " choice
                    [[ ! "$choice" =~ ^[yY] ]] && { msg "操作已取消。 / Operation cancelled."; return 0; }
                    
                    tx_data=$(jq -n --arg gid "$group_id" --arg act "$action" --arg slug "$page_slug" '{group_id:$gid, action:$act, target:{page_slug:$slug}}')
                    info "正在提交 Wiki 页面删除交易... / Submitting wiki page deletion transaction..."
                    blockchain_create_transaction "group_admin_action" "$tx_data"
                    ;;
                    
                *)
                    error "未知的管理员操作 / Unknown admin action: '$action'"; usage_group; exit 1;;
            esac
            ;;
            
        set-owner)
            [ $# -ne 2 ] && { usage_group; exit 1; }; local group_id="$1"; local new_owner_id="$2"
            local tx_data=$(jq -n --arg gid "$group_id" --arg noid "$new_owner_id" '{group_id:$gid, new_owner_id:$noid}')
            info "正在提交所有权转移交易... / Submitting ownership transfer transaction..."; blockchain_create_transaction "group_transfer_ownership" "$tx_data";;
        propose-owner)
            [ $# -ne 2 ] && { usage_group; exit 1; }; local group_id="$1"; local candidate_id="$2"
            local tx_data=$(jq -n --arg gid "$group_id" --arg cid "$candidate_id" '{group_id: $gid, candidate_id: $cid}')
            info "正在提交群主提名... / Submitting owner proposal..."; blockchain_create_transaction "group_propose_owner" "$tx_data";;
        vote-owner)
            [ $# -ne 2 ] && { usage_group; exit 1; }; local proposal_hash="$1"; local vote_choice="$2"
            [ "$vote_choice" = "yes" ] || { info "'no' 票通过不作为来表示。/'no' votes are cast by inaction."; return 0; }
            local tx_data=$(jq -n --arg hash "$proposal_hash" --arg vote "$vote_choice" '{proposal_tx_hash: $hash, vote: $vote}')
            info "正在为群主提名投出赞成票... / Casting 'yes' vote for owner proposal..."; blockchain_create_transaction "group_vote_owner" "$tx_data";;
        propose-admin)
            [ $# -ne 3 ] && { usage_group; exit 1; }; local group_id="$1"; local action="$2"; local target_id="$3"
            [[ "$action" =~ ^(add|remove)$ ]] || { error "Action must be 'add' or 'remove'."; exit 1; }
            local tx_data=$(jq -n --arg gid "$group_id" --arg act "$action" --arg tid "$target_id" '{group_id: $gid, action: $act, target_id: $tid}')
            info "正在提交管理员变更提案... / Submitting admin change proposal..."; blockchain_create_transaction "group_propose_admin" "$tx_data";;
        vote-admin)
            [ $# -ne 2 ] && { usage_group; exit 1; }; local proposal_hash="$1"; local vote_choice="$2"
            [ "$vote_choice" = "yes" ] || { info "'no' 票通过不作为来表示。/'no' votes are cast by inaction."; return 0; }
            local tx_data=$(jq -n --arg hash "$proposal_hash" --arg vote "$vote_choice" '{proposal_tx_hash: $hash, vote: $vote}')
            info "正在为管理员变更提案投出赞成票... / Casting 'yes' vote for admin change proposal..."; blockchain_create_transaction "group_vote_admin" "$tx_data";;
        set-policy)
            local group_id join_mode desc; group_id="${1:-}"; shift || true
            while [ $# -gt 0 ]; do case "$1" in --join-mode) join_mode="$2"; shift 2 ;; --desc) desc="$2"; shift 2 ;; *) error "set-policy: Unknown option '$1'";; esac; done
            [ -z "$group_id" ] || [ -z "$join_mode" ] && { usage_group; exit 1; }
            local tx_data=$(jq -n --arg gid "$group_id" --arg mode "$join_mode" --arg d "$desc" '{group_id:$gid, policy:{join_mode:$mode, description:$d}}')
            info "正在提交群组策略变更交易... / Submitting group policy change transaction..."; blockchain_create_transaction "group_set_policy" "$tx_data";;
        *)
            usage_group;;
    esac
}

# =======================================================================================
# --- [V76 Mail Svc START] 邮件与邮件列表服务 (Mail & Maillist Service)           ---
# =======================================================================================

# --- 邮件服务 帮助函数 ---
# --- Mail Service Help Function ---
usage_mail() {
cat <<'EOF'
corix mail: A decentralized, E2EE asynchronous postal service.
corix mail: 一个去中心化的、端到端加密的异步邮政服务。

Usage: corix mail <subcommand> [arguments...]
用法:  corix mail <子命令> [参数...]

Subcommands (子命令):
  inbox [--all]                  Show your mail inbox. Use --all to see read messages.
                                 (显示您的收件箱。使用 --all 查看已读邮件)
  send <recipient_id> --subject "..." [--body "..."] [--attach /path/to/file]
                                 Send a private, End-to-End Encrypted mail to a user.
                                 (向一个用户发送一封私密的、端到端加密的邮件)
  read <mail_tx_hash>            Read a specific mail from your inbox.
                                 (从您的收件箱中阅读一封指定的邮件)
  delete <mail_tx_hash>          Delete a mail from your local inbox (does not affect the blockchain).
                                 (从您的本地收件箱删除一封邮件 (不影响区块链))
EOF
}

# --- 邮件列表 帮助函数 ---
# --- Maillist Help Function ---
usage_maillist() {
cat <<'EOF'
corix maillist: Public, asynchronous mailing lists for group discussions.
corix maillist: 用于群组讨论的、公开的、异步的邮件列表。

Usage: corix maillist <subcommand> [arguments...]
用法:  corix maillist <子命令> [参数...]

Subcommands (子命令):
  create <group_nickname>        Create a new public mailing list.
                                 (创建一个新的公开邮件列表)
  subscribe <list_id>            Subscribe to a mailing list (join the group).
                                 (订阅一个邮件列表 (即加入群组))
  unsubscribe <list_id>          Unsubscribe from a mailing list (leave the group).
                                 (退订一个邮件列表 (即离开群组))
  post <list_id> --subject "..." [--body "..."] [--attach /path/to/file]
                                 Post a public, unencrypted message to a mailing list.
                                 (向一个邮件列表发布一条公开的、未加密的消息)
  list                           List all mailing lists you are subscribed to.
                                 (列出您所有已订阅的邮件列表)
  archive <list_id>              View the message archive of a mailing list.
                                 (查看一个邮件列表的消息存档)
EOF
}

# --- 邮件服务 主分发器 ---
# --- Mail Service Main Dispatcher ---
corix_mail() {
    acquire_lock "network"
    trap 'release_lock "network"' RETURN
    
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        send)
            _internal_mail_send "e2ee" "$@"
            ;;
        inbox)
            _internal_mail_inbox "user" "$@"
            ;;
        read)
            [ $# -ne 1 ] && { usage_mail; exit 1; }
            _internal_mail_read "$1"
            ;;
        delete)
            [ $# -ne 1 ] && { usage_mail; exit 1; }
            db_execute_safe "$FORUM_DB" "DELETE FROM mails WHERE tx_hash = %s;" "$1"
            msg "邮件已从本地收件箱删除。 / Mail deleted from local inbox."
            ;;
        *)
            usage_mail
            ;;
    esac
}

# --- 邮件列表 主分发器 ---
# --- Maillist Main Dispatcher ---
corix_maillist() {
    acquire_lock "network"
    trap 'release_lock "network"' RETURN
    
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        create)
            [ $# -ne 1 ] && { usage_maillist; exit 1; }
            # 创建一个邮件列表本质上是创建一个开放的群组
            # Creating a maillist is essentially creating an open group
            local group_id
            group_id=$(corix_group create "$1")
            corix_group set-policy "$group_id" --join-mode open --desc "Public Mailing List: $1"
            msg "邮件列表已创建。ID / Maillist created. ID: ${group_id}"
            ;;
        subscribe)
            [ $# -ne 1 ] && { usage_maillist; exit 1; }
            corix_group join "$1"
            ;;
        unsubscribe)
            [ $# -ne 1 ] && { usage_maillist; exit 1; }
            corix_group leave "$1"
            ;;
        post)
            _internal_mail_send "plaintext" "$@"
            ;;
        list)
            _update_chain_state_cache >/dev/null 2>&1
            msg "您订阅的邮件列表 / Your subscribed mailing lists:"
            # 查找所有你作为成员的、且描述中包含 "Mailing List" 的群组
            # Find all groups you are a member of and whose description contains "Mailing List"
            local my_id=$(_forum_get_identity)
            db_query_safe "$FORUM_DB" "SELECT acl_id FROM acl_state WHERE grantee_id = %s AND permissions LIKE '%\"member\"%';" "$my_id" | while IFS= read -r group_id; do
                local group_info=$(db_query_safe "$FORUM_DB" "SELECT nickname, permissions FROM identity_cache WHERE id_hash = %s;" "$group_id")
                if [[ "$group_info" == *"Mailing List"* ]]; then
                    echo "  - $(echo "$group_info" | cut -d'|' -f1) (${group_id:0:16}...)"
                fi
            done
            ;;
        archive)
            [ $# -ne 1 ] && { usage_maillist; exit 1; }
            _internal_mail_inbox "maillist" "$1"
            ;;
        *)
            usage_maillist
            ;;
    esac
}

# --- 内部邮件发送逻辑 (由 mail 和 maillist 共享) ---
# --- Internal Mail Sending Logic (shared by mail and maillist) ---
_internal_mail_send() {
    local send_mode="$1" # "e2ee" or "plaintext"
    shift
    
    local recipient_id="$1"; shift
    local subject="" body_text="" attach_file=""
    while [ $# -gt 0 ]; do
        case "$1" in
            --subject) subject="$2"; shift 2 ;;
            --body) body_text="$2"; shift 2 ;;
            --attach) attach_file="$2"; shift 2 ;;
            *) error "send/post: Unknown option '$1' / 未知选项 '$1'";;
        esac
    done

    [ -z "$recipient_id" ] || [ -z "$subject" ] && { echo "Error: Recipient and subject are required."; echo "错误: 必须提供收件人和主题。"; exit 1; }
    if [ -z "$body_text" ]; then
         info "未提供 --body，从标准输入读取正文内容 (按 Ctrl+D 结束): / No --body provided, reading content from stdin (Press Ctrl+D to end):"
         body_text=$(cat)
    fi

    # 1. 上传附件 (Upload attachments)
    local attachment_hash="" attachment_name="" attachments_json="[]"
    if [ -n "$attach_file" ]; then
        info "正在将附件上传到P2P网络... / Uploading attachment to P2P network..."
        attachment_hash=$(_p2p_upload_file "$attach_file")
        attachment_name=$(basename "$attach_file")
        attachments_json=$(jq -n --arg name "$attachment_name" --arg hash "$attachment_hash" '[{filename: $name, hash: $hash}]')
    fi
    
    # 2. 构造邮件正文对象 (Construct the mail body object)
    local mail_body_json
    mail_body_json=$(jq -n \
        --arg subject "$subject" \
        --arg body "$body_text" \
        --argjson attachments "$attachments_json" \
        --argjson ts "$(date +%s)" \
        '{subject: $subject, body: $body, attachments: $attachments, timestamp: $ts}')
    
    local content_to_upload="$mail_body_json"
    
    # 3. 加密 (如果需要) / Encrypt (if needed)
    if [ "$send_mode" = "e2ee" ]; then
        info "正在对邮件进行端到端加密... / End-to-end encrypting the mail..."
        local recipient_pubkey_file
        recipient_pubkey_file=$(_get_identity_pubkey "$recipient_id")
        [ -z "$recipient_pubkey_file" ] && { error "无法获取收件人的公钥，加密失败。/ Could not get recipient's public key, encryption failed."; return 1; }
        content_to_upload=$(_e2ee_encrypt_payload "$mail_body_json" "$recipient_pubkey_file")
    fi

    # 4. 上传邮件内容对象 (Upload the mail content object)
    info "正在将邮件内容上传到P2P网络... / Uploading mail content to P2P network..."
    local temp_content_file; temp_content_file=$(mktemp)
    echo "$content_to_upload" > "$temp_content_file"
    local mail_object_hash; mail_object_hash=$(_p2p_upload_file "$temp_content_file")
    rm -f "$temp_content_file"
    
    # 5. 构造并提交区块链交易 (Construct and submit the blockchain transaction)
    local tx_data
    tx_data=$(jq -n --arg rid "$recipient_id" --arg moh "$mail_object_hash" \
        '{recipient_id: $rid, mail_object_hash: $moh}')

    info "正在提交邮件分发交易... / Submitting mail dispatch transaction..."
    local tx_hash; tx_hash=$(blockchain_create_transaction "mail_dispatch" "$tx_data")

    if [ -n "$tx_hash" ]; then
        msg "邮件已成功分发！交易哈希 / Mail dispatched successfully! Tx Hash: ${tx_hash}"
    else
        error "邮件分发失败。 / Mail dispatch failed."
    fi
}

# --- 内部邮件收件箱/存档逻辑 ---
# --- Internal Mail Inbox/Archive Logic ---
_internal_mail_inbox() {
    local inbox_mode="$1" # "user" or "maillist"
    shift
    
    _update_chain_state_cache >/dev/null 2>&1

    local query=""
    local -a params=()
    
    if [ "$inbox_mode" = "user" ]; then
        local my_id=$(_forum_get_identity)
        msg "您的收件箱 / Your Inbox"
        query="SELECT tx_hash, sender_id, timestamp, is_read FROM mails WHERE recipient_id = %s"
        params+=("$my_id")
        if [ "$1" != "--all" ]; then
            query+=" AND is_read = 0"
        fi
    else
        local list_id="$1"
        msg "邮件列表存档 / Archive for Maillist: $(_get_identity_nickname "$list_id")"
        query="SELECT tx_hash, sender_id, timestamp, is_read FROM mails WHERE recipient_id = %s"
        params+=("$list_id")
    fi
    query+=" ORDER BY timestamp DESC LIMIT 100;"
    
    local results; results=$(db_query_safe "$FORUM_DB" "$query" "${params[@]}")

    if [ -z "$results" ]; then
        info "没有邮件。 / No mails found."
        return
    fi
    
    echo "--------------------------------------------------------------------------------"
    while IFS='|' read -r tx_hash sender_id timestamp is_read; do
        local read_status="[未读 / Unread]"
        [ "$is_read" -eq 1 ] && read_status="[已读 / Read  ]"
        local sender_name=$(_get_identity_nickname "$sender_id")
        local subject=$(_internal_mail_get_subject "$tx_hash")
        
        echo -e "\033[1;33m${read_status}\033[0m \033[1;32m发件人 / From:\033[0m ${sender_name} \033[0;36m(${sender_id:0:12}...)\033[0m"
        echo -e "  \033[1;32m主题 / Subject:\033[0m ${subject}"
        echo -e "  \033[0;90mID: ${tx_hash} | 时间 / Time: $(date -d "@$timestamp" '+%Y-%m-%d %H:%M')\033[0m"
    done <<< "$results"
    echo "--------------------------------------------------------------------------------"
    
    # Mark as read for user inbox
    if [ "$inbox_mode" = "user" ]; then
        db_execute_safe "$FORUM_DB" "UPDATE mails SET is_read = 1 WHERE recipient_id = %s AND is_read = 0;" "$my_id"
    fi
}

# --- 内部邮件读取/主题获取逻辑 ---
# --- Internal Mail Read/Subject Fetch Logic ---
_internal_mail_read() {
    local tx_hash="$1"
    local mail_info; mail_info=$(db_query_safe "$FORUM_DB" "SELECT sender_id, recipient_id, mail_object_hash, local_path, timestamp FROM mails WHERE tx_hash = %s;" "$tx_hash")
    [ -z "$mail_info" ] && { error "未找到该邮件。 / Mail not found."; return 1; }
    
    IFS='|' read -r sender_id recipient_id mail_object_hash local_path timestamp <<< "$mail_info"
    
    if [ -z "$local_path" ] || [ ! -f "$local_path" ]; then
        info "邮件内容不在本地，正在从P2P网络获取... / Mail content not cached, fetching from P2P network..."
        local mail_dir="${VAR_LIB_CORIUM_DIR}/mail/objects"
        mkdir -p "$mail_dir"
        local_path="${mail_dir}/${mail_object_hash}"
        _download_file_p2p "$mail_object_hash" "$local_path" || { error "无法下载邮件内容。/ Failed to download mail content."; return 1; }
        db_execute_safe "$FORUM_DB" "UPDATE mails SET local_path = %s WHERE tx_hash = %s;" "$local_path" "$tx_hash"
    fi
    
    local content; content=$(cat "$local_path")
    local recipient_type=$(_get_identity_type "$recipient_id")
    
    # Decrypt if it's a private mail to us
    if jq -e 'type=="object" and has("encrypted_payload")' <<< "$content" >/dev/null; then
        content=$(_e2ee_decrypt_payload "$content") || return 1
        if [[ "$content" == \[解密失败* ]]; then
            error "无法解密邮件！您可能不是收件人，或者密钥已损坏。/ Failed to decrypt mail! You may not be the recipient or your key is corrupt."
            return 1
        fi
    fi
    
    local subject body attachments
    subject=$(echo "$content" | jq -r .subject)
    body=$(echo "$content" | jq -r .body)
    attachments=$(echo "$content" | jq -c .attachments)

    echo "================================================================================"
    echo -e "\033[1;32m发件人 / From:\033[0m    $(_get_identity_nickname "$sender_id")"
    echo -e "\033[1;32m收件人 / To:\033[0m      $(_get_identity_nickname "$recipient_id")"
    echo -e "\033[1;32m时间 / Date:\033[0m      $(date -d "@$timestamp")"
    echo -e "\033[1;32m主题 / Subject:\033[0m   ${subject}"
    echo "--------------------------------------------------------------------------------"
    echo "$body"
    
    if [ "$(echo "$attachments" | jq 'length')" -gt 0 ]; then
        echo "--------------------------------------------------------------------------------"
        echo -e "\033[1;32m附件 / Attachments:\033[0m"
        echo "$attachments" | jq -r '.[] | "  - \(.filename) (Hash: \(.hash))"'
    fi
    echo "================================================================================"
}

# Internal helper to just get a subject line for inbox view
_internal_mail_get_subject() {
    local tx_hash="$1"
    # This is a simplified version of _internal_mail_read for performance
    local mail_info; mail_info=$(db_query_safe "$FORUM_DB" "SELECT mail_object_hash, local_path, recipient_id FROM mails WHERE tx_hash = %s;" "$tx_hash")
    local mail_object_hash local_path recipient_id
    IFS='|' read -r mail_object_hash local_path recipient_id <<< "$mail_info"
    
    [ -z "$local_path" ] || [ ! -f "$local_path" ] && echo "[内容未下载 / Content not downloaded]" && return
    
    local content; content=$(cat "$local_path")
    local recipient_type=$(_get_identity_type "$recipient_id")
    
    if jq -e 'type=="object" and has("encrypted_payload")' <<< "$content" >/dev/null; then
        content=$(_e2ee_decrypt_payload "$content") || return 1
    fi
    
    if [[ "$content" == \[解密失败* ]]; then
        echo "🔒 [加密邮件，无法预览主题 / Encrypted Mail, Cannot Preview Subject]"
    else
        echo "$content" | jq -r .subject
    fi
}
