# --- MESSAGE COMMANDS ---

# Displays detailed help for the message command.
# 显示 message 命令的详细帮助信息。
usage_message() {
    echo "corix message: Send, receive, and query P2P messages."
    echo "corix message: 发送、接收和查询P2P消息。"
    echo
    echo "Usage: corix message <subcommand> [arguments...]"
    echo "用法:  corix message <子命令> [参数...]"
    echo
    echo -e "\033[1;33mPRIVACY NOTE / 隐私提示:\033[0m"
    echo -e "  - 🔒 Direct Messages to users are \033[1;32mEnd-to-End Encrypted\033[0m."
    echo -e "    (发送给单个用户的直接消息是 \033[1;32m端到端加密\033[0m 的，只有您和接收者能阅读内容。)"
    echo -e "  - 👥 Group and Broadcast messages are \033[1;33mNOT encrypted\033[0m and are publicly readable."
    echo -e "    (群组和广播消息 \033[1;33m未加密\033[0m，是公开可读的。)"
    echo
    echo "Subcommands (子命令):"
    echo "  send <recipient_id> --body '...' [--attach /path/to/file] [--priority high]"
    echo "      Send a message. Recipient can be a user, group, or broadcast ID."
    echo "      (发送消息。接收者可以是用户、群组或广播的ID。)"
    echo "  inbox"
    echo "      Check your unread messages. / 检查您的未读消息。"
    echo "  query <channel_id> [--sender <id>] [--before <date>] [--after <date>]"
    echo "      Query the historical messages of a group or broadcast channel."
    echo "      (查询一个群组或广播频道的历史消息)"
    echo "  get-attachment <msg_tx_hash> [output_file]"
    echo "      Download an attachment from a message. / 从一条消息中下载附件。"
}

# The user-facing command dispatcher for 'corix message'.
# 'corix message' 的用户侧命令分发器。
corix_message() {
    acquire_lock "network"
    trap 'release_lock "network"' RETURN
    
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        # --- [REWRITE WITH E2EE] 'send' 子命令的完整实现 ---
        # --- [REWRITE WITH E2EE] Full implementation of the 'send' subcommand ---
        send)
            # --- [V72 UX FIX START] 存储用户输入的原始接收者，用于用户反馈 ---
            # --- [V72 UX FIX START] Store the original recipient input for user feedback ---
            local original_recipient_input="${1:-}" # Capture the original input before any processing.
            # --- [V72 UX FIX END] ---

            local recipient_id="$1"; shift
            local body_text="" attach_file="" priority="low"
            while [ $# -gt 0 ]; do
                case "$1" in
                    --body) body_text="$2"; shift 2 ;;
                    --attach) attach_file="$2"; shift 2 ;;
                    --priority) priority="$2"; shift 2 ;;
                    *) error "send: Unknown option '$1' / send: 未知选项 '$1'";;
                esac
            done
            
            [ -z "$recipient_id" ] && { usage_message; exit 1; }
            if [ -z "$body_text" ]; then
                 info "未提供 --body，从标准输入读取正文内容 (按 Ctrl+D 结束): / No --body provided, reading content from stdin (Press Ctrl+D to end):"
                 body_text=$(cat)
            fi
            
            # Resolve alias to get the final ID and type.
            # 解析别名以获取最终ID和类型。
            local final_recipient_id
            final_recipient_id=$(_resolve_channel_id "$recipient_id")
            local recipient_type
            recipient_type=$(_get_identity_type "$final_recipient_id")
        
            # This is the plaintext payload we will either send directly or encrypt.
            # 这是我们将要直接发送或加密的明文荷载。
            local attachment_hash="" attachment_name=""
            if [ -n "$attach_file" ]; then
                info "正在将附件上传到P2P网络... / Uploading attachment to P2P network..."
                attachment_hash=$(_p2p_upload_file "$attach_file")
                attachment_name=$(basename "$attach_file")
            fi
            local plaintext_payload
            plaintext_payload=$(jq -n \
                --arg body "$body_text" \
                --arg ah "$attachment_hash" \
                --arg an "$attachment_name" \
                '{body: $body, attachment_hash: $ah, attachment_name: $an}')
        
            local content_to_upload="$plaintext_payload"
            local encryption_mode="none"
            
            # ========================================================== --
            # --- [E2EE MODIFICATION START] 加密分支逻辑             --- --
            # --- [E2EE MODIFICATION START] Encryption Branch Logic    --- --
            # ========================================================== --
            if [ "$recipient_type" = "user" ]; then
                info "检测到直接消息，正在启用端到端加密... / Direct Message detected, enabling End-to-End Encryption..."
                local recipient_pubkey_file
                recipient_pubkey_file=$(_get_identity_pubkey "$final_recipient_id")
                if [ -z "$recipient_pubkey_file" ]; then
                    error "无法获取接收者的公钥，加密失败。消息未发送。/ Could not get recipient's public key, encryption failed. Message not sent."
                    return 1
                fi
                
                content_to_upload=$(_e2ee_encrypt_payload "$plaintext_payload" "$recipient_pubkey_file")
                encryption_mode="e2ee-v1"
                detail "荷载已成功加密。/ Payload successfully encrypted."
            fi
            # ========================================================== --
            # --- [E2EE MODIFICATION END]                            --- --
            # ========================================================== --
        
            info "正在将消息内容上传到P2P网络... / Uploading message content to P2P network..."
            local tmp_content_file; tmp_content_file=$(mktemp); echo -n "$content_to_upload" > "$tmp_content_file"
            local content_hash; content_hash=$(_p2p_upload_file "$tmp_content_file"); rm -f "$tmp_content_file"
        
            # Construct the blockchain transaction payload.
            # 构造区块链交易荷载。
            local tx_data
            tx_data=$(jq -n \
                --arg rid "$final_recipient_id" \
                --arg chash "$content_hash" \
                --arg prio "$priority" \
                --arg enc "$encryption_mode" \
                '{recipient_id: $rid, content_hash: $chash, priority: $prio, encryption: $enc}')
        
            local tx_type="user_message"
            [ "$recipient_type" = "group" ] && tx_type="group_post"
            [ "$recipient_type" = "broadcast" ] && tx_type="broadcast_post"
        
            info "正在向网络提交消息交易... / Submitting message transaction to the network..."
            local tx_hash
            tx_hash=$(blockchain_create_transaction "$tx_type" "$tx_data")
            
            if [ -z "$tx_hash" ]; then
                error "创建区块链交易失败。消息未发送。/ Failed to create blockchain transaction. Message not sent."
                return 1
            fi
        
            # --- [V72 UX FIX START] 在成功消息中使用原始输入 ---
            # --- [V72 UX FIX START] Use the original input in the success message ---
            msg "消息交易已成功提交至 '${original_recipient_input}' (Tx: ${tx_hash:0:16}...) / Message transaction submitted successfully to '${original_recipient_input}' (Tx: ${tx_hash:0:16}...)."
            # --- [V72 UX FIX END] ---
            
            if [ "$recipient_type" = "user" ]; then
                _notify_recipient_of_new_message "$final_recipient_id" "$tx_hash"
            fi
            ;;
        inbox)
            _sync_and_display_messages
            ;;
        query)
            local channel_id="$1"; shift
            local sender_filter="" before_filter="" after_filter=""
            while [ $# -gt 0 ]; do
                case "$1" in
                    --sender) sender_filter="$2"; shift 2 ;;
                    --before) before_filter=$(date -d "$2" +%s); shift 2 ;;
                    --after) after_filter=$(date -d "$2" +%s); shift 2 ;;
                    *) error "message query: Unknown option '$1' / 未知选项 '$1'";;
                esac
            done
            
            [ -z "$channel_id" ] && { usage_message; exit 1; }

            _update_chain_state_cache >/dev/null 2>&1
            local block_clause=$(_get_blocked_users_sql_clause "messages" "sender_id")

            # --- [E2EE MODIFICATION] 在 SELECT 列表中增加了 encryption_mode ---
            # --- [E2EE MODIFICATION] Added encryption_mode to the SELECT list ---
            local query="SELECT tx_hash, sender_id, timestamp, content_hash, inline_content, attachment_meta, encryption_mode FROM messages WHERE recipient_id = %s ${block_clause}"
            local -a params=("$channel_id")
            
            if [ -n "$sender_filter" ]; then
                query+=" AND sender_id = %s"
                params+=("$sender_filter")
            fi
            if [ -n "$before_filter" ]; then
                query+=" AND timestamp < %d"
                params+=("$before_filter")
            fi
            if [ -n "$after_filter" ]; then
                query+=" AND timestamp > %d"
                params+=("$after_filter")
            fi
            query+=" ORDER BY timestamp DESC LIMIT 100;"

            msg "查询频道历史记录 / Querying Channel History: $(_get_identity_nickname "$channel_id") (${channel_id:0:16}...)"
            
            # --- [E2EE REWRITE] 整个消息显示循环被替换为新的、支持解密和图标的版本 ---
            # --- [E2EE REWRITE] The entire message display loop is replaced with the new version supporting decryption and icons ---
            db_query_safe "$FORUM_DB" "$query" "${params[@]}" | while IFS='|' read -r tx_hash sender_id timestamp content_hash inline_content attachment_meta encryption_mode; do
                local sender_name source_label icon
                sender_name=$(_get_identity_nickname "$sender_id")

                # ========================================================== --
                # --- [E2EE LOGIC START] 根据类型选择图标和标签          --- --
                # --- [E2EE LOGIC START] Choose icon and label by type     --- --
                # ========================================================== --
                local recipient_type
                recipient_type=$(_get_identity_type "$channel_id")
                
                case "$recipient_type" in
                    "user")
                        icon="🔒"; source_label="[DIRECT] From: ${sender_name}" ;;
                    "group")
                        icon="👥"; source_label="[GROUP] From: ${sender_name}" ;;
                    "broadcast")
                        icon="📢"; source_label="[BROADCAST] From: ${sender_name}" ;;
                    *)
                        icon="✉️"; source_label="[${recipient_type}] From: ${sender_name}" ;;
                esac
                
                echo "--------------------------------------------------"
                echo -e "${icon} \033[1;33m${source_label}\033[0m"
                echo "Date: $(date -d "@$timestamp" '+%Y-%m-%d %H:%M:%S') (ID: ${tx_hash:0:16}...)"
                echo "Content:"

                # ========================================================== --
                # --- [E2EE LOGIC START] 解密和渲染逻辑                --- --
                # --- [E2EE LOGIC START] Decryption and Render Logic     --- --
                # ========================================================== --
                if [ "$encryption_mode" = "e2ee-v1" ]; then
                    local encrypted_content_path="${FORUM_OBJECTS_DIR}/${content_hash}"
                    # 如果本地没有加密荷载，尝试下载
                    # If the encrypted payload is not local, try to download it
                    if [ ! -f "$encrypted_content_path" ]; then
                        detail "  [正在下载加密内容... / Downloading encrypted content...]"
                        forum_fetch_object "$content_hash" "$FORUM_OBJECTS_DIR" >/dev/null 2>&1
                    fi
                    
                    if [ -f "$encrypted_content_path" ]; then
                        local decrypted_payload
                        decrypted_payload=$(_e2ee_decrypt_payload "$(cat "$encrypted_content_path")")
                        
                        # 检查解密是否成功
                        # Check if decryption was successful
                        if [[ "$decrypted_payload" == \[解密失败* ]]; then
                             echo "  ${decrypted_payload}"
                        else
                            local decrypted_body decrypted_attach_hash decrypted_attach_name
                            decrypted_body=$(echo "$decrypted_payload" | jq -r .body)
                            decrypted_attach_hash=$(echo "$decrypted_payload" | jq -r .attachment_hash)
                            decrypted_attach_name=$(echo "$decrypted_payload" | jq -r .attachment_name)
                            
                            echo "$decrypted_body" | sed 's/^/  /'
                            
                            if [ -n "$decrypted_attach_hash" ] && [ "$decrypted_attach_hash" != "null" ]; then
                                echo -e "\n  \033[1;32mAttachment:\033[0m ${decrypted_attach_name}"
                                echo "    -> corix message get-attachment $tx_hash \"${decrypted_attach_name}\""
                            fi
                        fi
                    else
                         echo "  [无法下载加密的消息内容 / Could not download encrypted message content]"
                    fi
                else
                    # 未加密的消息 (群组, 广播, 申诉)
                    # Unencrypted messages (groups, broadcasts, grievances)
                    _render_message_content "$content_hash" "$inline_content" "  "
                    
                    # 附件显示逻辑 (未加密)
                    # Attachment display logic (unencrypted)
                    if [ -n "$attachment_meta" ] && [ "$attachment_meta" != "null" ]; then
                        local filename size
                        filename=$(echo "$attachment_meta" | jq -r .filename)
                        size=$(echo "$attachment_meta" | jq -r .size | numfmt --to=iec)
                        echo -e "\n  \03_3[1;32mAttachment:\033[0m ${filename} (${size})"
                        echo "    -> corix message get-attachment $tx_hash \"${filename}\""
                    fi
                fi
                # ========================================================== --
                # --- [E2EE LOGIC END]                                   --- --
                # ========================================================== --
            done
            ;;
        get-attachment)
            [ $# -lt 1 ] && { usage_message; exit 1; }
            local msg_tx_hash="$1"
            local output_file="${2:-}"
            local attachment_meta; attachment_meta=$(db_query_safe "$FORUM_DB" "SELECT attachment_meta FROM messages WHERE tx_hash = %s;" "$msg_tx_hash")
            [ -z "$attachment_meta" ] || [ "$attachment_meta" = "null" ] && error "此消息没有附件。 / No attachment found for this message."
            
            local attach_hash attach_filename
            attach_hash=$(echo "$attachment_meta" | jq -r .hash)
            attach_filename=$(echo "$attachment_meta" | jq -r .filename)
            [ -z "$output_file" ] && output_file="$attach_filename"

            info "正在下载附件 '${attach_filename}'... / Downloading attachment '${attach_filename}'..."
            _p2p_download_object "$attach_hash" "$output_file"
            msg "附件已下载至 / Attachment downloaded to: ${output_file}"
            ;;
        *)
            usage_message
            ;;
    esac
}


# =======================================================================================
# --- SECTION 23.9: INTERNAL API & ADVANCED P2P (IMPLEMENTED)                         ---
# --- 第23.9节: 内部API与高级P2P功能 (已实现)                                         ---
# =======================================================================================

# =======================================================================================
# --- [已实现] 供 Python 守护进程使用的内部函数 (申诉权杖)                             ---
# --- [IMPLEMENTED] Internal Functions for Python Daemon (Grievance Token)                  ---
# =======================================================================================

# --- [已实现] 处理并存储一条高优先级的申诉消息 ---
# --- [IMPLEMENTED] Process and store a high-priority grievance message ---
# 此函数被 Python 守护进程在验证并通过一条申诉消息后调用。
# It is called by the Python daemon after validating and accepting a grievance message.
#
# @param $1 - sender_id (申诉消息的发送者 / The sender of the grievance message)
# @param $2 - text_payload (申诉消息的纯文本内容 / The plain-text content of the message)
_internal_process_grievance_message() {
    [ $# -eq 2 ] && [[ "$1" =~ ^[a-f0-9]{64}$ ]] || return 1
    "${PYTHON_CMD}" - "$FORUM_DB" "$DHT_DB" "$1" "$(get_our_node_id)" "$2" <<'PY_GRIEVANCE'
import sqlite3,sys,time,hashlib,json
forum,dht,sender,recipient,text=sys.argv[1:]; timestamp=int(time.time())
identity=hashlib.sha256(json.dumps([sender,recipient,text],ensure_ascii=False,separators=(',',':')).encode()).hexdigest()
db=sqlite3.connect(forum,timeout=10);db.execute('ATTACH DATABASE ? AS transport',(dht,))
try:
    db.execute('BEGIN IMMEDIATE')
    result=db.execute('UPDATE transport.distrusted_peers SET grievance_token_used=1 WHERE blocker_id=? AND blocked_id=? AND grievance_token_used=0 AND (distrust_until=0 OR distrust_until>?)',(recipient,sender,timestamp))
    if result.rowcount!=1: raise ValueError('No available grievance token')
    db.execute("INSERT OR IGNORE INTO messages (tx_hash,sender_id,recipient_id,source_type,inline_content,priority,is_read,timestamp) VALUES (?,?,?,'GRIEVANCE',?,'high',0,?)",(identity,sender,recipient,text,timestamp))
    db.commit()
except BaseException: db.rollback(); raise
finally: db.close()
PY_GRIEVANCE
}

# --- [新增实现] 内部IPC函数: 标记申诉权杖为已使用 ---
# --- [NEW IMPLEMENTATION] Internal IPC Function: Mark Grievance Token as Used ---
# 此函数被 Python 守护进程调用，以在数据库中原子性地将一个申诉权杖标记为已使用。
# This function is called by the Python daemon to atomically mark a grievance token as used in the database.
#
# @param $1 - blocker_id (The one who set the block / 设置屏蔽的发起者)
# @param $2 - blocked_id (The one who used the token / 使用权杖的被屏蔽者)
_internal_mark_token_used() {
    # 检查参数数量是否正确
    # Check if the number of arguments is correct
    [ $# -ne 2 ] && { echo "Internal Error: _internal_mark_token_used requires 2 arguments." >&2; return 1; }
    
    local blocker_id="$1"
    local blocked_id="$2"
    
    # 对 DHT 数据库执行一次写操作，将 grievance_token_used 字段更新为 1 (表示已使用)。
    # Perform a write operation on the DHT database, updating the grievance_token_used field to 1 (meaning used).
    db_execute_safe "$DHT_DB" \
        "UPDATE distrusted_peers SET grievance_token_used = 1 WHERE blocker_id = %s AND blocked_id = %s;" \
        "$blocker_id" "$blocked_id"

    # 记录日志以便追踪此重要安全事件
    # Log this important security event for traceability
    info "[GRIEVANCE] 节点 ${blocked_id:0:12}... 的申诉权杖已被标记为已使用。 / [GRIEVANCE] Grievance token for peer ${blocked_id:0:12}... has been marked as used."
}

# --- [NEW V72 UX HELPER] Compact info provider for fzf preview ---
# --- [V72 UX 新增辅助] 为 fzf 预览提供紧凑信息的函数 ---
_internal_info_preview() {
    local pkg_id="$1"
    local meta
    meta=$(_get_pkg_meta_from_cache "$pkg_id")
    if [ -z "$meta" ]; then
        echo "正在从 .build 文件解析... / Parsing from .build file..."
        local build_file; build_file=$(find_package_build_file "$pkg_id")
        [ -z "$build_file" ] && { echo "未找到包 / Package not found."; exit 1; }
        meta=$(_parse_build_file "$build_file")
    fi

    # Use awk for structured, colorful output
    # 使用 awk 实现结构化、带颜色的输出
    echo "$meta" | awk -F'=' '
        BEGIN {
            # ANSI Color Codes
            C_RESET="\033[0m"; C_BOLD="\033[1m"; C_GREEN="\033[1;32m";
            C_YELLOW="\033[1;33m"; C_CYAN="\033[0;36m";
        }
        /^pkgver=/ { pkgver=$2 }
        /^pkgdesc=/ { pkgdesc=$2 }
        /^depends=/ { gsub("\n", " ", $2); depends=$2 }
        /^makedepends=/ { gsub("\n", " ", $2); makedepends=$2 }
        END {
            printf C_BOLD C_GREEN "%s" "'"$pkg_id"'" C_RESET " - " C_YELLOW "%s\n", pkgver;
            printf "\n%s\n", pkgdesc;
            printf "\n" C_BOLD "Depends On / 依赖:" C_RESET "\n" C_CYAN "  %s\n", (depends ? depends : "<none>");
            printf C_BOLD "Build Depends / 构建依赖:" C_RESET "\n" C_CYAN "  %s\n", (makedepends ? makedepends : "<none>");
        }
    '
}

# =======================================================================================
# --- [IBC V1.2] 内置中继者 Agent 守护进程 (BUILT-IN RELAYER AGENT DAEMON)            ---
# =======================================================================================
# This function contains the complete Python code for the built-in Relayer Agent.
# It is designed to be run as a standalone, persistent background service.
# It starts the Python script in the background and returns its PID.
#
# 此函数包含了内置中继者 Agent 的完整 Python 代码。
# 它被设计为一个独立的、持久化的后台服务来运行，
# 并在后台启动 Python 脚本后返回其 PID。
_internal_relayer_daemon() {
    # Export necessary environment variables for the Python script.
    # 为 Python 脚本导出必要的环境变量。
    export CORIUM_SCRIPT_PATH="$SCRIPT_PATH"
    export CORIUM_NETWORK_ID="$CORIUM_NETWORK_ID" # Let it know its "home" chain.
    export CORIUM_ROOT="$CORIUM_ROOT"
    
    info "[Relayer] 正在启动内置的 IBC 中继者守护进程... / Starting built-in IBC Relayer Daemon..."
    
    # Execute the Python code inline and capture its PID.
    # 内联执行 Python 代码并捕获其 PID。
    ${PYTHON_CMD} - <<'EOF_RELAYER' &
# ==============================================================================
# --- Corium Built-in IBC Relayer Agent (v1.1 - Multi-Network)               ---
# --- Corium 内置 IBC 中继者 Agent (v1.1 - 支持多网络)                     ---
# ==============================================================================
import time
import json
import base64
import subprocess
import os
import sys
import configparser

# --- 全局配置与状态 / Global Configuration & State ---
SCRIPT_PATH = os.environ.get('CORIUM_SCRIPT_PATH')
HOME_NETWORK_ID = os.environ.get('CORIUM_NETWORK_ID', 'default')
CORIUM_ROOT = os.environ.get('CORIUM_ROOT', '/')
RELAYER_CONFIG = {
    "scan_interval_seconds": 30,
    "max_retries": 3,
    "retry_delay_seconds": 10,
    "networks_to_scan": [HOME_NETWORK_ID] # Default: only scan the home network.
}

# --- 辅助函数 / Helper Functions ---
def bilingual_print(message_en, message_zh, level="INFO"):
    """Prints a bilingual message to stderr."""
    print(f"RELAYER_LOG|{level}| {message_en} / {message_zh}", file=sys.stderr)

def corix_ipc_call(network_id, command, *args, is_json=False):
    """
    A robust IPC caller that can switch network contexts.
    一个可以切换网络上下文的、健壮的 IPC 调用器。
    """
    env = os.environ.copy()
    env['CORIUM_NETWORK_ID_OVERRIDE'] = network_id
    
    cmd = [SCRIPT_PATH, '--quiet', command] + list(args)
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, check=True, timeout=120, env=env)
        output = result.stdout.strip()
        if is_json:
            return json.loads(output) if output else None
        return output
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired, json.JSONDecodeError) as e:
        stderr = e.stderr.strip() if hasattr(e, 'stderr') and e.stderr else str(e)
        bilingual_print(f"IPC call failed ({network_id} -> {command}): {stderr}",
                        f"IPC 调用失败 ({network_id} -> {command}): {stderr}", "ERROR")
        return None

def load_relayer_config():
    """
    Loads configuration from mods.conf.d/relayer.conf if it exists.
    如果存在，则从 mods.conf.d/relayer.conf 加载配置。
    """
    global RELAYER_CONFIG
    config_file = os.path.join(CORIUM_ROOT, 'etc', 'corix', 'networks', HOME_NETWORK_ID, 'mods.conf.d', 'relayer.conf')
    if not os.path.exists(config_file):
        if HOME_NETWORK_ID not in RELAYER_CONFIG['networks_to_scan']:
            RELAYER_CONFIG['networks_to_scan'].append(HOME_NETWORK_ID)
        return

    bilingual_print(f"Loading custom relayer config from {config_file}",
                    f"正在从 {config_file} 加载自定义中继者配置", "INFO")
    try:
        config = configparser.ConfigParser()
        config.read(config_file)
        if 'relayer' in config:
            settings = config['relayer']
            RELAYER_CONFIG['scan_interval_seconds'] = settings.getint('scan_interval_seconds', 30)
            RELAYER_CONFIG['max_retries'] = settings.getint('max_retries', 3)
            RELAYER_CONFIG['retry_delay_seconds'] = settings.getint('retry_delay_seconds', 10)
            networks_str = settings.get('networks_to_scan', HOME_NETWORK_ID).strip()
            RELAYER_CONFIG['networks_to_scan'] = [n.strip() for n in networks_str.split(',')]
            if HOME_NETWORK_ID not in RELAYER_CONFIG['networks_to_scan']:
                RELAYER_CONFIG['networks_to_scan'].append(HOME_NETWORK_ID)
                
    except Exception as e:
        bilingual_print(f"Failed to parse relayer config: {e}",
                        f"解析中继者配置失败: {e}", "WARN")

# --- 核心中继逻辑 / Core Relaying Logic ---

def get_proof_for_tx(network_id, tx_hash):
    """
    Fetches the necessary proof components for a transaction from a source chain.
    从源链获取一笔交易所必需的证明组件。
    """
    proof_data = corix_ipc_call(network_id, "_internal_ibc_generate_proof", tx_hash, is_json=True)
    return proof_data

def process_outgoing_queue(network_id):
    """
    Scans the outgoing queue of a network and relays pending messages.
    扫描一个网络的待发送队列，并中继待处理的消息。
    """
    bilingual_print(f"Scanning outgoing queue for network '{network_id}'...",
                    f"正在扫描网络 '{network_id}' 的待发送队列...", "DEBUG")
    
    pending_txs = corix_ipc_call(network_id, "_internal_ibc_get_outgoing", is_json=True)
    
    if not pending_txs:
        return

    for tx in pending_txs:
        try:
            source_tx_hash = tx.get('source_tx_hash')
            target_chain_id = tx.get('target_chain_id')
            
            bilingual_print(f"Found pending message {source_tx_hash[:16]}... ({network_id} -> {target_chain_id})",
                            f"发现待处理消息 {source_tx_hash[:16]}... ({network_id} -> {target_chain_id})", "INFO")

            proof_data = get_proof_for_tx(network_id, source_tx_hash)
            if not proof_data or not proof_data.get('final_header'):
                bilingual_print(f"Failed to generate valid proof for {source_tx_hash[:16]}... Skipping.",
                                f"为 {source_tx_hash[:16]}... 生成有效证明失败，跳过。", "WARN")
                continue

            payload_and_proof = {
                "source_tx_hash": source_tx_hash,
                "message_type": tx.get('message_type'),
                "message_payload": json.loads(tx.get('message_payload')),
                "proof_data": proof_data
            }
            payload_and_proof_b64 = base64.b64encode(json.dumps(payload_and_proof).encode()).decode()

            bilingual_print(f"Submitting proof to target chain '{target_chain_id}'...",
                            f"正在向目标链 '{target_chain_id}' 提交证明...", "INFO")
            
            final_tx_payload = {
                "source_chain_id": network_id,
                "payload_and_proof": payload_and_proof_b64
            }
            tx_data_json = json.dumps(final_tx_payload)
            
            result_tx_hash = corix_ipc_call(target_chain_id, "_internal_create_transaction", "ibc_receive", tx_data_json)
            
            if result_tx_hash:
                bilingual_print(f"Successfully relayed message! Target Tx: {result_tx_hash[:16]}",
                                f"消息中继成功！目标链交易哈希: {result_tx_hash[:16]}", "OK")
                corix_ipc_call(network_id, "_internal_ibc_mark_relayed", source_tx_hash, result_tx_hash)
            else:
                bilingual_print(f"Failed to submit 'ibc_receive' transaction on chain '{target_chain_id}'.",
                                f"在链 '{target_chain_id}' 上提交 'ibc_receive' 交易失败。", "ERROR")
        
        except Exception as e:
            bilingual_print(f"An unexpected error occurred while relaying a message: {e}",
                            f"中继消息时发生意外错误: {e}", "FATAL")
            import traceback
            traceback.print_exc()

def main_loop():
    """The main event loop for the relayer daemon."""
    bilingual_print(f"Relayer Agent started. Scanning networks: {RELAYER_CONFIG['networks_to_scan']}",
                    f"中继者 Agent 已启动。正在扫描网络: {RELAYER_CONFIG['networks_to_scan']}", "OK")
    
    while True:
        try:
            for network_id in RELAYER_CONFIG['networks_to_scan']:
                process_outgoing_queue(network_id)
        except Exception as e:
            bilingual_print(f"Error in main loop: {e}",
                            f"主循环出错: {e}", "FATAL")

        time.sleep(RELAYER_CONFIG['scan_interval_seconds'])

if __name__ == "__main__":
    load_relayer_config()
    main_loop()

EOF_RELAYER
    echo $!
}

# =======================================================================================
# --- [IBC V1.2] 中继者 Agent 使用的内部命令 (INTERNAL COMMANDS FOR RELAYER AGENT)    ---
# =======================================================================================
_internal_ibc_get_outgoing() {
    db_query_safe "$BLOCKCHAIN_DB" \
        "SELECT source_tx_hash, target_chain_id, message_type, message_payload FROM ibc_outgoing_queue WHERE status = 'PENDING' LIMIT 20;" | \
        jq -R -s '
            split("\n") | 
            map(select(length > 0) | split("|")) | 
            map({
                source_tx_hash: .[0], 
                target_chain_id: .[1],
                message_type: .[2],
                message_payload: .[3]
            })
        '
}

# Checkpoint proofs authenticate historical block contents, not new consensus.
# A proof cannot advance the governance-configured trust anchor.
_internal_ibc_codec() {
    "${PYTHON_CMD}" - "$@" <<'PY_IBC_CODEC'
import base64, hashlib, json, pathlib, re, sqlite3, sys
FORMAT = 'CORIUM_IBC_CHECKPOINT_V2'
def unique_object(pairs):
    out = {}
    for key, value in pairs:
        if key in out: raise ValueError('Duplicate JSON key')
        out[key] = value
    return out
def load(raw):
    return json.loads(raw, object_pairs_hook=unique_object,
                      parse_constant=lambda value: (_ for _ in ()).throw(ValueError('Nonfinite JSON number')))
def dump(value):
    return json.dumps(value, ensure_ascii=False, separators=(',', ':'))
def digest(raw):
    return hashlib.sha256(raw.encode()).hexdigest()
def valid_hash(value):
    return isinstance(value, str) and re.fullmatch('[a-f0-9]{64}', value) is not None

def checked_nodes(nodes):
    if not isinstance(nodes, list) or not all(valid_hash(x) for x in nodes):
        raise ValueError('Invalid Merkle leaves')
    return nodes

def next_level(nodes):
    return [digest(nodes[i] + (nodes[i+1] if i+1 < len(nodes) else nodes[i]))
            for i in range(0, len(nodes), 2)]

def merkle_root(nodes):
    nodes = checked_nodes(nodes)
    if not nodes: return digest('')
    while len(nodes) > 1: nodes = next_level(nodes)
    return nodes[0]

def siblings(target, nodes):
    nodes = checked_nodes(nodes)
    if not valid_hash(target) or target not in nodes:
        raise ValueError('Target transaction is absent')
    index = nodes.index(target)
    proof = []
    while len(nodes) > 1:
        if index % 2:
            proof.append({'hash': nodes[index-1], 'position': 'left'})
        else:
            proof.append({'hash': nodes[index+1] if index+1 < len(nodes) else nodes[index],
                          'position': 'right'})
        nodes = next_level(nodes)
        index //= 2
    return proof

def verify_merkle(header, proof):
    expected, target = header['transactions_root'], proof['target_tx_hash']
    if not valid_hash(expected) or not valid_hash(target): raise ValueError('Invalid root or target')
    path = proof['siblings']
    if not isinstance(path, list): raise ValueError('Invalid sibling path')
    value = target
    for item in path:
        sibling, position = item['hash'], item['position']
        if not valid_hash(sibling) or position not in ('left', 'right'):
            raise ValueError('Invalid sibling')
        value = digest(value+sibling if position == 'right' else sibling+value)
    if value != expected: raise ValueError('Merkle root mismatch')

def block_header(row):
    height, block_hash, previous, timestamp, validator, signature, raw_txs = row[:7]
    nodes = load(raw_txs)
    header = {'height': height, 'hash': block_hash, 'previous_hash': previous,
              'timestamp': timestamp, 'transactions': nodes,
              'transactions_root': merkle_root(nodes), 'validator': validator, 'signature': signature}
    check_header(header)
    return header

def check_header(header):
    height, timestamp, previous = header['height'], header['timestamp'], header['previous_hash']
    if type(height) is not int or type(timestamp) is not int or not 0 <= height < 2**63 or not 0 <= timestamp < 2**63:
        raise ValueError('Invalid block height or timestamp')
    if not (previous == '0' if height == 0 else valid_hash(previous)):
        raise ValueError('Invalid previous block hash')
    nodes = checked_nodes(header['transactions'])
    if len(nodes) != len(set(nodes)): raise ValueError('Duplicate block transaction')
    body = {'height': height, 'previous_hash': previous, 'timestamp': timestamp, 'transactions': nodes}
    if not valid_hash(header['hash']) or digest(dump(body)) != header['hash']:
        raise ValueError('Block content hash mismatch')
    if merkle_root(nodes) != header['transactions_root']: raise ValueError('Unbound Merkle root')
    return header['hash']

mode, *args = sys.argv[1:]
if mode == 'siblings':
    print(dump(siblings(args[0], args[1:])))
elif mode == 'merkle':
    verify_merkle(load(args[0]), load(args[1]))
elif mode == 'generate':
    path, target = args
    if not valid_hash(target): raise ValueError('Invalid target transaction')
    with sqlite3.connect(pathlib.Path(path).resolve().as_uri()+'?mode=ro', uri=True) as db:
        # One read transaction gives all rows the same SQLite snapshot.
        db.execute('BEGIN')
        tx = db.execute('SELECT type,data,timestamp,block_height FROM transactions WHERE hash=?', (target,)).fetchone()
        if tx is None or tx[3] is None: raise ValueError('Transaction is not committed')
        block = db.execute('SELECT * FROM blocks WHERE height=?', (tx[3],)).fetchone()
        if block is None: raise ValueError('Missing transaction block')
        final = block_header(block)
        proof = {'target_tx_hash': target, 'siblings': siblings(target, final['transactions'])}
        # Preserve the exact transaction data bytes committed by its hash.
        source_tx = '{"type":'+json.dumps(tx[0])+',"data":'+tx[1]+',"timestamp":'+str(tx[2])+'}'
        if digest(source_tx) != target: raise ValueError('Source transaction content hash mismatch')
        chain = [block_header(row) for row in db.execute('SELECT * FROM blocks WHERE height>? ORDER BY height DESC', (tx[3],))]
    print(dump({'format': FORMAT, 'final_header': final, 'header_chain': chain,
                'merkle_proof': proof, 'source_transaction': source_tx}))
elif mode == 'verify':
    encoded, anchor, destination = args
    if not valid_hash(anchor): raise ValueError('Missing trusted checkpoint')
    payload = load(base64.b64decode(encoded, validate=True).decode())
    proof = payload['proof_data']
    if proof['format'] != FORMAT: raise ValueError('Unsupported IBC proof format')
    final = proof['final_header']
    final_hash = check_header(final)
    headers = proof['header_chain']
    if not isinstance(headers, list): raise ValueError('Invalid header chain')
    reached = final_hash == anchor
    expected, expected_height, child_time = None, None, None
    if not reached:
        for header in headers:
            block_hash = check_header(header)
            if expected is None:
                if block_hash != anchor: continue
            elif block_hash != expected or header['height'] != expected_height or header['timestamp'] > child_time:
                raise ValueError('Broken checkpoint history')
            expected, expected_height, child_time = header['previous_hash'], header['height']-1, header['timestamp']
            if expected == final_hash:
                if final['height'] != expected_height or final['timestamp'] > child_time:
                    raise ValueError('Invalid final block position')
                reached = True
                break
    if not reached: raise ValueError('Proof is not historical to the trusted checkpoint')
    verify_merkle(final, proof['merkle_proof'])
    target = proof['merkle_proof']['target_tx_hash']
    if target not in final['transactions'] or payload['source_tx_hash'] != target:
        raise ValueError('Source transaction binding mismatch')
    raw_tx = proof['source_transaction']
    if not isinstance(raw_tx, str) or digest(raw_tx) != target:
        raise ValueError('Source transaction hash mismatch')
    tx = load(raw_tx)
    data = tx['data']
    if tx['type'] != 'ibc_dispatch' or data['target_chain_id'] != destination:
        raise ValueError('Wrong source transaction type or destination')
    canonical = lambda value: json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(',', ':'))
    if data['message_type'] != payload['message_type'] or canonical(data['message_payload']) != canonical(payload['message_payload']):
        raise ValueError('Relayed message differs from committed source transaction')
else:
    raise ValueError('Unknown IBC codec mode')
PY_IBC_CODEC
}

_internal_generate_merkle_siblings() {
    [ $# -ge 1 ] || return 1
    _internal_ibc_codec siblings "$@"
}

_internal_ibc_generate_proof() {
    [ $# -eq 1 ] || return 1
    _internal_ibc_codec generate "$BLOCKCHAIN_DB" "$1"
}

_internal_ibc_mark_relayed() {
    local source_tx="$1"
    local target_tx="$2"
    local relayer_id=$(get_our_node_id) # The relayer is the one running this command.
    
    db_execute_safe "$BLOCKCHAIN_DB" \
        "UPDATE ibc_outgoing_queue SET status = 'RELAYED', relayer_id = %s, relayed_at_block = (SELECT MAX(height) FROM blocks) WHERE source_tx_hash = %s;" \
        "$relayer_id" "$source_tx"
}

# =======================================================================================
# --- [新增] 供 Python 守护进程使用的内部函数 (申诉权杖)                             ---
# --- [NEW] Internal Functions for Python Daemon (Grievance Token)                  ---
# =======================================================================================

# --- [已实现] 处理并存储一条高优先级的申诉消息 ---
# --- [IMPLEMENTED] Process and store a high-priority grievance message ---
# 此函数被 Python 守护进程在验证并通过一条申诉消息后调用。
# It is called by the Python daemon after validating and accepting a grievance message.
#
# @param $1 - sender_id (申诉消息的发送者 / The sender of the grievance message)
# @param $2 - text_payload (申诉消息的纯文本内容 / The plain-text content of the message)

# =======================================================================================
# --- [新增] 供 Agent Supervisor 使用的内部函数                                       ---
# --- [NEW] Internal functions for use by the Agent Supervisor                      ---
# =======================================================================================

# --- [已实现] 获取一个 Mod 的所有相关元数据，并以 JSON 格式输出 ---
# --- [IMPLEMENTED] Get all relevant metadata for a Mod and output as JSON ---
# 此函数被 Python Supervisor 调用，以决定如何启动和管理一个 Agent。
# Called by the Python Supervisor to decide how to start and manage an Agent.
# @param $1 - pkg_id
_internal_get_mod_meta_all() {
    [ $# -ne 1 ] && return 1
    local pkg_id="$1"
    
    # 复用现有的 _get_mod_metadata_value 函数来安全地读取元数据
    # Reuse the existing _get_mod_metadata_value function to safely read metadata
    local executable=$(_get_mod_metadata_value "$pkg_id" "executable")
    local unboxed=$(_get_mod_metadata_value "$pkg_id" "unboxed_execution")
    local persistent=$(_get_mod_metadata_value "$pkg_id" "persistent_service")
    local restart_policy=$(_get_mod_metadata_value "$pkg_id" "restart_policy")
    
    # 使用 jq 安全地构造 JSON 输出
    # Use jq to safely construct the JSON output
    jq -n \
        --arg exec "${executable:-}" \
        --arg unboxed "${unboxed:-false}" \
        --arg persistent "${persistent:-false}" \
        --arg policy "${restart_policy:-on-failure}" \
        '{
            "executable": $exec,
            "unboxed_execution": $unboxed,
            "persistent_service": $persistent,
            "restart_policy": $policy
        }'
}

_internal_p2p_get_to_temp(){
 # This is a helper for the Python daemon to get an object into a temp file
            # and return the path, avoiding large data on stdout.
            local object_hash="$1"
            local temp_file=$(mktemp)
            if _p2p_download_object "$object_hash" "$temp_file"; then
                echo "$temp_file"
            else
                rm -f "$temp_file"
                exit 1
            fi
}

# --- [已实现] 启动一个 Agent 进程 ---
# --- [IMPLEMENTED] Launch an Agent process ---
# 此函数被 Python Supervisor 的 subprocess.Popen 调用。
# 它会成为一个新的、独立的进程，然后用 Agent 的可执行文件替换自己 (exec)。
# Called by subprocess.Popen from the Python Supervisor.
# It becomes a new, separate process, then replaces itself with the Agent's executable (exec).
# @param $1 - pkg_id
_internal_launch_agent() {
    [ $# -ne 1 ] && return 1
    local pkg_id="$1"

    # 获取元数据以决定执行方式
    # Get metadata to decide the execution method
    local meta_json
    meta_json=$(_internal_get_mod_meta_all "$pkg_id")
    local executable_path
    executable_path=$(_get_mod_executable_path "$pkg_id")
    local is_unboxed
    is_unboxed=$(echo "$meta_json" | jq -r .unboxed_execution)

    if [ -z "$executable_path" ] || [ ! -x "$executable_path" ]; then
        echo "Error: Agent executable for '${pkg_id}' not found or not executable." >&2
        exit 127
    fi

    if [[ "$is_unboxed" == "true" ]]; then
        # Unboxed Agent: 直接执行，不使用沙箱
        # Unboxed Agent: Direct execution, no sandbox
        # 使用 exec 会让 Agent 进程替换掉当前的 corix shell 进程，
        # 这样可以避免多一层不必要的 shell 进程嵌套。
        # Using exec replaces the current corix shell process with the Agent's process,
        # avoiding an unnecessary layer of shell process nesting.
        exec "$executable_path"
    else
        # 普通沙箱服务: 调用修改后的沙箱函数
        # Regular sandboxed service: Call the modified sandbox function
        # 我们传递 "0" 作为 timeout 参数来禁用它
        # We pass "0" as the timeout parameter to disable it
        _execute_mod_in_sandbox "$pkg_id" "generic_service" "0" "$executable_path"
    fi
}

