# =======================================================================================
# --- [新增] 统一消息内容渲染器 v1.0                                                  ---
# --- [NEW] Unified Message Content Renderer v1.0                                     ---
# =======================================================================================
# 此函数负责显示一条消息的内容，自动处理内联内容和需要从P2P网络下载的内容。
# This function is responsible for displaying a message's content, automatically handling
# both inline content and content that needs to be downloaded from the P2P network.
#
# @param $1 - content_hash (The content hash, can be empty / 内容哈希，可为空)
# @param $2 - inline_content (The inline content, can be empty / 内联内容，可为空)
# @param $3 - indentation (Optional: A string to prepend to each line, e.g., "    ")
#             (可选: 加在每行前面的缩进字符串，例如 "    ")
_render_message_content() {
    local content_hash="$1"
    local inline_content="$2"
    local indentation="${3:-}" # 默认为空字符串

    if [ -n "$inline_content" ]; then
        # 场景 A: 存在内联内容 (例如申诉消息)
        # Scenario A: Inline content exists (e.g., a grievance message)
        # 直接打印内联内容，并应用缩进
        # Print the inline content directly, applying indentation.
        echo "$inline_content" | sed "s/^/${indentation}/"
    elif [ -n "$content_hash" ]; then
        # 场景 B: 存在内容哈希，需要从 P2P 下载
        # Scenario B: A content hash exists, needs download from P2P
        local content_path="${FORUM_OBJECTS_DIR}/${content_hash}"
        
        # 检查本地缓存
        # Check local cache
        if [ ! -f "$content_path" ]; then
            # 如果本地没有，则尝试下载一次
            # If not local, attempt to download it once
            detail "${indentation}[正在从 P2P 网络下载消息内容... / Downloading message content from P2P network...]"
            # 将下载函数的输出重定向到 /dev/null 以保持界面干净
            # Redirect download function's output to /dev/null to keep the interface clean
            forum_fetch_object "$content_hash" "$FORUM_OBJECTS_DIR" >/dev/null 2>&1
        fi
        
        # 再次检查，并显示内容或错误信息
        # Check again, and display content or an error message
        if [ -f "$content_path" ]; then
            cat "$content_path" | sed "s/^/${indentation}/"
        else
            echo "${indentation}[无法下载或找到内容 (哈希: ${content_hash:0:16}...) / Could not download or find content (hash: ${content_hash:0:16}...)]"
        fi
    else
        # 场景 C: 两者都为空 (不应发生，但作为保障)
        # Scenario C: Both are empty (should not happen, but as a safeguard)
        echo "${indentation}[消息内容为空 / Message content is empty]"
    fi
}

# --- [最终版] 获取身份的显示名称 (优先使用别名) ---
# --- [FINAL] Get an identity's display name (prioritizing alias) ---
# 从本地缓存获取一个身份的显示名称。
# Gets an identity's display name from the local cache.
#
# 查找顺序: 1. 本地别名 (aliases) -> 2. 链上昵称 (identity_cache) -> 3. 截断的哈希
# Lookup Order: 1. Local Alias -> 2. On-chain Nickname -> 3. Truncated Hash
#
# @param $1 - id_hash (The ID hash to look up / 要查找的ID哈希)
# @return The display name. / 显示名称。
_get_identity_nickname() {
    local id_hash="$1"
    
    # --- 1. 优先查找本地别名 / 1. Prioritize looking up local alias ---
    local alias_name
    alias_name=$(db_query_safe "$FORUM_DB" "SELECT alias_name FROM aliases WHERE channel_id = %s;" "$id_hash")
    if [ -n "$alias_name" ]; then
        # 在别名后附加一个星号(*)，以向用户明确提示这是一个本地别名
        # Append an asterisk (*) to the alias to clearly indicate to the user that it is a local alias.
        echo "${alias_name}*"
        return
    fi

    # --- 2. 其次查找链上昵称 / 2. Secondly, look up on-chain nickname ---
    local nickname
    nickname=$(db_query_safe "$FORUM_DB" "SELECT nickname FROM identity_cache WHERE id_hash = %s;" "$id_hash")
    if [ -n "$nickname" ]; then
        echo "$nickname"
        return
    fi
    
    # --- 3. 最终回退到截断哈希 / 3. Finally, fall back to truncated hash ---
    local fallback_name="${id_hash:0:16}..."
    echo "$fallback_name"
}

# Get an identity's type from the local cache. Requires a full sync to be accurate.
# 从本地缓存获取一个身份的类型。需要完全同步才能保证准确性。
_get_identity_type() {
    local id_hash="$1"
    db_query_safe "$FORUM_DB" "SELECT type FROM identity_cache WHERE id_hash = %s;" "$id_hash"
}

# Checks if a user has a certain role (owner, admin, post) in a channel (group/broadcast).
# This is a critical permission checking function that consults the local state cache.
# 检查一个用户在一个频道 (群组/广播) 中是否拥有特定角色 (owner, admin, post)。
# 这是一个关键的权限检查函数，它会查询本地状态缓存。
_is_identity_authorized() {
    local channel_id="$1"
    local user_hash="$2"
    local required_role="$3" # "owner", "admin", or "post"

    local perms
    perms=$(db_query_safe "$FORUM_DB" "SELECT permissions FROM identity_cache WHERE id_hash = %s;" "$channel_id")
    [ -z "$perms" ] && return 1

    local owner
    owner=$(echo "$perms" | jq -r .owner 2>/dev/null)
    
    case "$required_role" in
        "owner")
            [ "$user_hash" = "$owner" ] && return 0
            ;;
        "admin")
            if [ "$user_hash" = "$owner" ]; then return 0; fi
            echo "$perms" | jq -e ".admins[] | select(. == \"$user_hash\")" >/dev/null && return 0
            ;;
        "post")
            local id_type
            id_type=$(db_query_safe "$FORUM_DB" "SELECT type FROM identity_cache WHERE id_hash = %s;" "$channel_id")
            if [ "$id_type" = "broadcast" ]; then
                if [ "$user_hash" = "$owner" ]; then return 0; fi
                echo "$perms" | jq -e ".admins[] | select(. == \"$user_hash\")" >/dev/null && return 0
            elif [ "$id_type" = "group" ]; then
                echo "$perms" | jq -e ".members[] | select(. == \"$user_hash\")" >/dev/null && return 0
            fi
            ;;
    esac
    return 1
}

# =======================================================================================
# --- [批次三 新增] 状态修正执行函数 (完整实现)                                       ---
# --- [BATCH THREE NEW] State Correction Execution Function (Full Implementation)     ---
# =======================================================================================
_execute_state_correction() {
    local transitions_json="$1"
    "${PYTHON_CMD}" - "$BLOCKCHAIN_DB" "$transitions_json" <<'PY_CORRECTION'
import sqlite3,json,sys,re,math,pathlib
transitions=json.loads(sys.argv[2])
if isinstance(transitions,dict): transitions=transitions.get('state_transitions')
if not isinstance(transitions,list): raise ValueError('State transitions must be an array')
db=sqlite3.connect(pathlib.Path(sys.argv[1]).resolve().as_uri()+'?mode=rw',uri=True,timeout=10)
def identifier(value):
    if not isinstance(value,str) or not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*',value): raise ValueError('Invalid SQL identifier')
    return '"'+value+'"'
def integer(value):
    if type(value) is not int or not 0<=value<=9223372036854775807: raise ValueError('Invalid correction integer')
    return value
def text(value):
    if not isinstance(value,str) or '\x00' in value: raise ValueError('Invalid correction text')
    return value
try:
    with db:
        for item in transitions:
            if not isinstance(item,dict): raise ValueError('Invalid state transition')
            operation=item.get('operation')
            if operation=='INVALIDATE_TX':
                digest=text(item.get('tx_hash'))
                if not re.fullmatch(r'[a-f0-9]{64}',digest): raise ValueError('Invalid veto target')
                height=integer(item.get('height'));reason=text(item.get('reason','No reason provided.'))
                db.execute('INSERT OR IGNORE INTO invalidated_transactions VALUES (?,?,?)',(digest,reason,height))
                continue
            table=identifier(item.get('table'))
            columns={r[1] for r in db.execute('PRAGMA table_info('+table+')')}
            if operation in ('DEBIT','CREDIT'):
                if not {'score','user_id'}<=columns: raise ValueError('Invalid score table')
                user=text(item.get('user_id'));amount=integer(item.get('amount'))
                row=db.execute('SELECT score FROM '+table+' WHERE user_id=?',(user,)).fetchone()
                if row:
                    score=row[0]-amount if operation=='DEBIT' else row[0]+amount
                    if type(score) is not int or not -9223372036854775808<=score<=9223372036854775807: raise ValueError('Score overflow')
                    db.execute('UPDATE '+table+' SET score=? WHERE user_id=?',(score,user))
            elif operation=='UPDATE':
                updates=item.get('update_fields');target=text(item.get('set_id'))
                if 'set_id' not in columns or not isinstance(updates,dict) or not updates: raise ValueError('Invalid update target')
                for name,value in updates.items():
                    identifier(name)
                    if name not in columns: raise ValueError('Unknown update column')
                    if value is not None and type(value) not in (str,int,float): raise ValueError('Invalid update value')
                    if isinstance(value,float) and not math.isfinite(value): raise ValueError('Nonfinite update value')
                clause=','.join(identifier(name)+'=?' for name in updates)
                db.execute('UPDATE '+table+' SET '+clause+' WHERE set_id=?',tuple(updates.values())+(target,))
            else: raise ValueError('Unknown state correction operation')
finally: db.close()
PY_CORRECTION
}

# =======================================================================================
# --- [批次三 新增] 争议解决辅助函数 (完整实现)                                       ---
# --- [BATCH THREE NEW] Dispute Resolution Helper Function (Full Implementation)      ---
# =======================================================================================
_resolve_proofs_and_challenges_at_height() {
    local current_height="$1"

    # ... (unchallenged proofs confirmation logic) ...
    db_query_safe "$BLOCKCHAIN_DB" \
        "SELECT P.proposer_id, P.proof_tx_hash, P.problem_id FROM pending_proofs AS P LEFT JOIN challenges AS C ON P.proof_tx_hash = C.target_proof_tx_hash WHERE P.confirmation_deadline_height = %d AND C.challenge_tx_hash IS NULL AND NOT EXISTS(SELECT 1 FROM transactions T JOIN compute_engines E ON E.engine_id=json_extract(T.data,'$.engine_id') WHERE T.hash=P.proof_tx_hash AND E.pkg_id IN ('compute/openci-attested:1','corium/built-in-gimps'));" \
        "$current_height" | while IFS='|' read -r proposer_id proof_tx_hash problem_id; do
        
        msg "[PoM] 证明 ${proof_tx_hash:0:12} 已通过挑战期并被确认！ / [PoM] Proof ${proof_tx_hash:0:12} passed challenge window and is confirmed!"
        
        # --- [V86 修改] 获取引擎的奖励权重并应用 ---
        # --- [V86 MODIFICATION] Get the engine's reward weight and apply it ---
        local engine_id
        engine_id=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT json_extract(data, '$.engine_id') FROM transactions WHERE hash = %s;" "$proof_tx_hash")
        local reward_weight
        reward_weight=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT reward_weight FROM compute_engines WHERE engine_id = %s;" "$engine_id")
        
        # 如果是内置引擎或找不到权重，则默认为 1
        # Default to 1 for built-in engines or if weight not found
        [ -z "$reward_weight" ] && reward_weight=1 
        
        local BASE_REWARD=100 # 基础奖励值
        local REWARD=$((BASE_REWARD * reward_weight))
        detail "  -> 应用奖励权重 / Applying reward weight: ${reward_weight}x. 最终奖励 / Final Reward: ${REWARD}"
        # --- [修改结束] ---

        db_execute_safe "$BLOCKCHAIN_DB" \
            "INSERT INTO contribution_scores (user_id, score, last_update_height) VALUES (%s, %d, %d) ON CONFLICT(user_id) DO UPDATE SET score = score + %d, last_update_height = %d;" \
            "$proposer_id" "$REWARD" "$current_height" "$REWARD" "$current_height"
            
        # [Batch 4] 记录已解决的 Compute 任务，防止 Double Redeem
        db_execute_safe "$BLOCKCHAIN_DB" \
            "INSERT OR IGNORE INTO completed_compute_tasks (engine_id, problem_id, proof_tx_hash) VALUES (%s, %s, %s);" \
            "$engine_id" "$problem_id" "$proof_tx_hash"
        
        db_execute_safe "$BLOCKCHAIN_DB" "DELETE FROM pending_proofs WHERE proof_tx_hash = %s;" "$proof_tx_hash"
    done
    
    # --- 阶段 2: 解决当前高度的所有待定挑战 ---
    # --- Stage 2: Resolve all pending challenges at the current height ---
    db_query_safe "$BLOCKCHAIN_DB" \
        "SELECT C.challenger_id, P.proposer_id, C.challenge_tx_hash, C.target_proof_tx_hash, C.challenge_data, P.problem_id, P.proposed_result FROM challenges AS C JOIN pending_proofs AS P ON C.target_proof_tx_hash = P.proof_tx_hash WHERE C.status = 'pending';" | while IFS='|' read -r challenger_id proposer_id challenge_tx target_tx challenge_data problem_id proposed_result; do
        
        local engine_id
        # The signed proof selects its engine. A challenge may be a block hash,
        # not a problem_sets key; never guess the engine from that key.
        engine_id=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT json_extract(data, '$.engine_id') FROM transactions WHERE hash = %s AND type = 'submit_math_proof';" "$target_tx") || return 1
        [ -n "$engine_id" ] || return 1
        
        local challenge_succeeded=1
        
        if [[ "$engine_id" == "corium/internal-engine-zero-v1" ]]; then
            # [Batch 4] Engine Zero 内部验证逻辑 (包含跨链重放防御)
            # proposed_result 包含 JSON
            local nonce network_id submitter_id target_hash
            nonce=$(echo "$proposed_result" | jq -r '.nonce' 2>/dev/null)
            network_id=$(echo "$proposed_result" | jq -r '.network_id' 2>/dev/null)
            submitter_id=$(echo "$proposed_result" | jq -r '.submitter_id' 2>/dev/null)
            target_hash="$problem_id"
            
            # 校验 Network ID
            if [[ "$network_id" != "${CORIUM_NETWORK_ID:-mainnet}" || "$submitter_id" != "$proposer_id" ]]; then
                challenge_succeeded=0 # 防御成功，证明无效，挑战成功
            else
                local difficulty=3
                local leading_zeros
                leading_zeros=$(printf "%0*d" "$difficulty" 0)
                local current_hash
                current_hash=$(echo -n "${network_id}${submitter_id}${nonce}${target_hash}" | sha256sum | awk '{print $1}')
                if [[ "${current_hash}" == ${leading_zeros}* ]]; then
                    challenge_succeeded=1 # 证明有效，挑战失败
                else
                    challenge_succeeded=0 # 证明无效，挑战成功
                fi
            fi
        elif [ "$(db_query_safe "$BLOCKCHAIN_DB" "SELECT pkg_id FROM compute_engines WHERE engine_id=%s;" "$engine_id")" = compute/openci-attested:1 ]; then
            local original_payload original_height
            original_payload=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT data FROM transactions WHERE hash=%s;" "$target_tx") || return 1
            original_height=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT block_height FROM transactions WHERE hash=%s;" "$target_tx") || return 1
            if _corium_openci_consensus validate "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$original_payload" "$proposer_id" "$original_height" "$target_tx" >/dev/null; then
                challenge_succeeded=1
            else
                challenge_succeeded=0
            fi
        elif [ "$(db_query_safe "$BLOCKCHAIN_DB" "SELECT pkg_id FROM compute_engines WHERE engine_id=%s;" "$engine_id")" = corium/built-in-gimps ]; then
            local challenge_result
            challenge_result=$(_corium_gimps_consensus validate-challenge "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$target_tx" 2>/dev/null)
            if [ "$challenge_result" = "1" ]; then
                challenge_succeeded=1 # proof is valid, challenge fails
            else
                challenge_succeeded=0 # proof is invalid, challenge succeeds
            fi
        else
            local verifier_hash verifier_path
            verifier_hash=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT verifier_script_hash FROM compute_engines WHERE engine_id = %s;" "$engine_id")
            verifier_path=$(mktemp)
            CORIUM_TEMP_ITEMS+=("$verifier_path")

            if ! _p2p_download_object "$verifier_hash" "$verifier_path"; then
                warn "[PoM] 关键错误: 无法获取验证脚本来解决争议！跳过挑战 ${challenge_tx:0:12}。 / [PoM] CRITICAL ERROR: Could not fetch verifier script to resolve dispute! Skipping challenge ${challenge_tx:0:12}."
                continue
            fi

            # 在沙箱中运行验证脚本来验证挑战的有效性
            # [Batch 4] 注入 proposer_id 和 network_id 以支持防重放验证
            if echo "$challenge_data" | _execute_mod_in_sandbox "verifier/${engine_id}" "generic" "$verifier_path" "challenge" "$proposed_result" "$proposer_id" "${CORIUM_NETWORK_ID:-mainnet}"; then
                challenge_succeeded=0 # 退出码为 0 代表挑战成功 (证明无效)
            else
                challenge_succeeded=1 # 退出码非 0 代表挑战失败 (证明有效)
            fi
        fi

        if [ "$challenge_succeeded" -eq 0 ]; then
            # --- 挑战成功 ---
            # --- Challenge Succeeded ---
            warn "[PoM] 挑战 ${challenge_tx:0:12} 成功！证明 ${target_tx:0:12} 无效。 / [PoM] Challenge ${challenge_tx:0:12} SUCCEEDED! Proof ${target_tx:0:12} is invalid."
            local PENALTY=200 REWARD=200
            # 惩罚提交者，奖励挑战者
            # Penalize proposer, reward challenger
            db_execute_safe "$BLOCKCHAIN_DB" "UPDATE contribution_scores SET score = score - %d WHERE user_id = %s;" "$PENALTY" "$proposer_id"
            db_execute_safe "$BLOCKCHAIN_DB" "UPDATE contribution_scores SET score = score + %d WHERE user_id = %s;" "$REWARD" "$challenger_id"
            
            db_execute_safe "$BLOCKCHAIN_DB" "UPDATE challenges SET status = 'confirmed' WHERE challenge_tx_hash = %s;" "$challenge_tx"
            db_execute_safe "$BLOCKCHAIN_DB" "DELETE FROM pending_proofs WHERE proof_tx_hash = %s;" "$target_tx"
        else
            # --- 挑战失败 ---
            # --- Challenge Failed ---
             warn "[PoM] 挑战 ${challenge_tx:0:12} 失败或无效。 / [PoM] Challenge ${challenge_tx:0:12} FAILED or was invalid."
            local PENALTY=50
            # 惩罚恶意挑战者
            # Penalize malicious challenger
             db_execute_safe "$BLOCKCHAIN_DB" "UPDATE contribution_scores SET score = score - %d WHERE user_id = %s;" "$PENALTY" "$challenger_id"
             db_execute_safe "$BLOCKCHAIN_DB" "UPDATE challenges SET status = 'rejected' WHERE challenge_tx_hash = %s;" "$challenge_tx"
        fi
    done || return 1
    local gimps_due_tx
    while IFS= read -r gimps_due_tx; do
        [ -n "$gimps_due_tx" ] || continue
        _corium_gimps_consensus settle "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$gimps_due_tx" "$current_height" >/dev/null || return 1
    done < <(db_query_safe "$BLOCKCHAIN_DB" "SELECT P.proof_tx_hash FROM pending_proofs P JOIN transactions T ON T.hash=P.proof_tx_hash JOIN compute_engines E ON E.engine_id=json_extract(T.data,'$.engine_id') WHERE E.pkg_id='corium/built-in-gimps' AND P.confirmation_deadline_height<=%d AND NOT EXISTS(SELECT 1 FROM challenges C WHERE C.target_proof_tx_hash=P.proof_tx_hash AND C.status!='rejected') ORDER BY P.proof_tx_hash;" "$current_height")
    # Only this versioned engine uses bounded quorum settlement. Ordinary engines
    # retain their native dispute rules. Rejected challenges cannot starve payout.
    local openci_due_tx
    while IFS= read -r openci_due_tx; do
        [ -n "$openci_due_tx" ] || continue
        _corium_openci_consensus settle "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$openci_due_tx" "$current_height" >/dev/null || return 1
    done < <(db_query_safe "$BLOCKCHAIN_DB" "SELECT P.proof_tx_hash FROM pending_proofs P JOIN transactions T ON T.hash=P.proof_tx_hash JOIN compute_engines E ON E.engine_id=json_extract(T.data,'$.engine_id') WHERE E.pkg_id='compute/openci-attested:1' AND P.confirmation_deadline_height<=%d AND NOT EXISTS(SELECT 1 FROM challenges C WHERE C.target_proof_tx_hash=P.proof_tx_hash AND C.status!='rejected') ORDER BY P.proof_tx_hash;" "$current_height")
}


# =======================================================================================
# --- [批次三 新增] NNS 拍卖计票与结算函数 (完整实现)                                 ---
# --- [BATCH THREE NEW] NNS Auction Tally & Settlement Function (Full Implementation) ---
# =======================================================================================
# This function is called for every block to check if any auctions have just concluded
# their reveal period. If so, it tallies the bids and determines the winner.
# 每个区块都会调用此函数，以检查是否有拍卖的揭示期正好结束。
# 如果有，它将统计出价并确定赢家。
#
# @param $1 - current_height (The current block height being processed)
_nns_tally_auction_at_height() {
    local current_height="$1"

    # Find all auctions whose reveal period ends exactly at the current block height
    while IFS= read -r domain_name; do
        [ -z "$domain_name" ] && continue
        msg "[NNS-Auction] 正在结算域名 '${domain_name}' 的拍卖... / [NNS-Auction] Settling auction for domain '${domain_name}'..."
        
        local -A bids
        local highest_bid=0
        local second_highest_bid=0
        local winner_id=""

        # Read bids from locked funds
        while IFS='|' read -r bidder_id amount; do
            [ -z "$bidder_id" ] && continue
            bids["$bidder_id"]="$amount"
        done < <(db_query_safe "$BLOCKCHAIN_DB" "SELECT user_id, amount FROM nns_locked_funds WHERE domain_name = %s;" "$domain_name")

        # Determine the winner (Vickrey auction)
        for bidder in "${!bids[@]}"; do
            local bid_amount=${bids[$bidder]}
            if (( bid_amount > highest_bid )); then
                second_highest_bid=$highest_bid
                highest_bid=$bid_amount
                winner_id=$bidder
            elif (( bid_amount > second_highest_bid )); then
                second_highest_bid=$bid_amount
            fi
        done

        if [[ -n "$winner_id" ]]; then
            msg "[NNS-Auction] 拍卖结束！域名 '${domain_name}' 的赢家是 ${winner_id:0:16}... / [NNS-Auction] Auction ended! Winner for domain '${domain_name}' is ${winner_id:0:16}..."
            info "  -> 最高出价 / Highest Bid: ${highest_bid}"
            info "  -> 成交价格 (第二高价) / Winning Price (Second Highest): ${second_highest_bid}"

            local block_ts=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT timestamp FROM blocks WHERE height = %d;" "$current_height")
            local expiry=$((block_ts + 31536000))
            db_execute_safe "$FORUM_DB" "INSERT OR REPLACE INTO nns_records (domain_name, owner_id, target_hash, last_update_height, registration_type, expires_at) VALUES (%s, %s, %s, %d, 'auction', %d);" "$domain_name" "$winner_id" "UNCONFIGURED" "$current_height" "$expiry"
            db_execute_safe "$FORUM_DB" "UPDATE nns_auctions SET status = 'concluded', highest_bidder = %s, second_highest_bid = %d WHERE domain_name = %s;" "$winner_id" "$second_highest_bid" "$domain_name"
            
            # Refund difference to winner
            local winner_locked=${bids[$winner_id]}
            local winner_refund=$((winner_locked - second_highest_bid))
            if [ "$winner_refund" -gt 0 ]; then
                db_execute_safe "$BLOCKCHAIN_DB" "UPDATE contribution_scores SET score = score + %d WHERE user_id = %s;" "$winner_refund" "$winner_id"
            fi
            
            # Refund losers
            for bidder in "${!bids[@]}"; do
                if [ "$bidder" != "$winner_id" ]; then
                    db_execute_safe "$BLOCKCHAIN_DB" "UPDATE contribution_scores SET score = score + %d WHERE user_id = %s;" "${bids[$bidder]}" "$bidder"
                fi
            done
        else
            msg "[NNS-Auction] 域名 '${domain_name}' 的拍卖因无有效出价而结束。 / [NNS-Auction] Auction for domain '${domain_name}' concluded with no valid bids."
            db_execute_safe "$FORUM_DB" "UPDATE nns_auctions SET status = 'failed' WHERE domain_name = %s;" "$domain_name"
        fi
        
        # Clear locked funds
        db_execute_safe "$BLOCKCHAIN_DB" "DELETE FROM nns_locked_funds WHERE domain_name = %s;" "$domain_name"
    done < <(db_query_safe "$FORUM_DB" "SELECT domain_name FROM nns_auctions WHERE end_reveal_block = %d AND status = 'REVEAL';" "$current_height")
}
_group_tally_owner_votes_at_height() {
    local current_height="$1"; local VOTE_WINDOW=500
    db_query_safe "$BLOCKCHAIN_DB" "SELECT T.hash, T.data FROM transactions AS T WHERE T.type = 'group_propose_owner' AND (T.block_height + %d) = %d;" "$VOTE_WINDOW" "$current_height" | while IFS='|' read -r proposal_hash proposal_data; do
        local group_id=$(echo "$proposal_data" | jq -r .group_id); local candidate_id=$(echo "$proposal_data" | jq -r .candidate_id)
        msg "[治理] 正在结算群组 '${group_id:0:12}...' 的群主选举..."
        if ! _is_authorized_by_acl "$group_id" "$candidate_id" "member"; then warn "[治理] 提案 ${proposal_hash:0:12}... 已失效，因为候选人不再是群组成员。"; continue; fi
        local current_owner_id=$(db_query_safe "$FORUM_DB" "SELECT grantee_id FROM acl_state WHERE acl_id = %s AND permissions LIKE '%\"owner\"%';" "$group_id")
        if [ -z "$current_owner_id" ]; then warn "[治理] 无法找到群组的现任群主，无法结算选举。"; continue; fi
        local -a required_voters=(); while IFS= read -r user_id; do if [ "$user_id" != "$current_owner_id" ]; then required_voters+=("$user_id"); fi; done < <(db_query_safe "$FORUM_DB" "SELECT grantee_id FROM acl_state WHERE acl_id = %s AND permissions LIKE '%\"admin\"%';" "$group_id")
        local required_vote_count=${#required_voters[@]}
        if [ "$required_vote_count" -eq 0 ]; then detail "  -> 无其他管理员，无法达成罢免共识。提案已失效。"; continue; fi
        detail "  -> 共识需要 ${required_vote_count} 票。 / Consensus requires ${required_vote_count} votes."
        local -a actual_voters=(); while IFS= read -r pubkey; do actual_voters+=("$(_internal_hash_text "$pubkey")"); done < <(db_query_safe "$BLOCKCHAIN_DB" "SELECT public_key FROM transactions WHERE type = 'group_vote_owner' AND json_extract(data, '$.proposal_tx_hash') = %s;" "$proposal_hash")
        local consensus_achieved=1; for required_voter in "${required_voters[@]}"; do if ! [[ " ${actual_voters[*]} " =~ " ${required_voter} " ]]; then consensus_achieved=0; detail "  -> 管理员 ${required_voter:0:12}... 未投票。"; break; fi; done
        if [ "$consensus_achieved" -eq 1 ]; then
            _execute_owner_transfer "$group_id" "$current_owner_id" "$candidate_id" "$proposal_hash"
        else warn "[治理] 提案 ${proposal_hash:0:12}... 未能达成管理员共识，已失效。"; fi
    done
}

_group_tally_admin_votes_at_height() {
    local current_height="$1"; local VOTE_WINDOW=500
    db_query_safe "$BLOCKCHAIN_DB" "SELECT T.hash, T.data FROM transactions AS T WHERE T.type = 'group_propose_admin' AND (T.block_height + %d) = %d;" "$VOTE_WINDOW" "$current_height" | while IFS='|' read -r proposal_hash proposal_data; do
        local group_id=$(echo "$proposal_data" | jq -r .group_id); local action=$(echo "$proposal_data" | jq -r .action); local target_id=$(echo "$proposal_data" | jq -r .target_id)
        msg "[治理] 正在结算群组 '${group_id:0:12}...' 的管理员选举 (提案: ${proposal_hash:0:12})..."
        if [ "$action" = "add" ] && ! _is_authorized_by_acl "$group_id" "$target_id" "member"; then warn "[治理] 提案失效：目标用户已不是群组成员。"; continue; fi
        local -a required_voters=(); while IFS= read -r user_id; do if ! _is_authorized_by_acl "$group_id" "$user_id" "admin"; then required_voters+=("$user_id"); fi; done < <(db_query_safe "$FORUM_DB" "SELECT grantee_id FROM acl_state WHERE acl_id = %s AND permissions LIKE '%\"member\"%';" "$group_id")
        local required_vote_count=${#required_voters[@]}; if [ "$required_vote_count" -eq 0 ]; then detail "  -> 无普通成员可投票，提案失效。"; continue; fi
        detail "  -> 成员共识需要 ${required_vote_count} 票。 / Member consensus requires ${required_vote_count} votes."
        local -a actual_voters=(); while IFS= read -r pubkey; do actual_voters+=("$(_internal_hash_text "$pubkey")"); done < <(db_query_safe "$BLOCKCHAIN_DB" "SELECT public_key FROM transactions WHERE type = 'group_vote_admin' AND json_extract(data, '$.proposal_tx_hash') = %s;" "$proposal_hash")
        local consensus_achieved=1; for required_voter in "${required_voters[@]}"; do if ! [[ " ${actual_voters[*]} " =~ " ${required_voter} " ]]; then consensus_achieved=0; detail "  -> 成员 ${required_voter:0:12}... 未投票。"; break; fi; done
        if [ "$consensus_achieved" -eq 1 ]; then
            msg "[治理] 成员共识达成！正在执行管理员变更..."; db_begin_transaction "$FORUM_DB"
            local current_perms=$(db_query_safe "$FORUM_DB" "SELECT permissions FROM acl_state WHERE acl_id = %s AND grantee_id = %s;" "$group_id" "$target_id" | jq -r '. // []')
            if [ "$action" = "add" ]; then
                local new_perms=$(jq -n --argjson p "$current_perms" '($p + ["admin"]) | unique')
                db_execute_safe "$FORUM_DB" "INSERT OR REPLACE INTO acl_state (acl_id, grantee_id, permissions) VALUES (%s, %s, %s);" "$group_id" "$target_id" "$new_perms"
                msg "[治理] 用户 ${target_id:0:16} 已被提升为管理员。"
            elif [ "$action" = "remove" ]; then
                local new_perms=$(jq -n --argjson p "$current_perms" '$p - ["admin"]')
                db_execute_safe "$FORUM_DB" "UPDATE acl_state SET permissions = %s WHERE acl_id = %s AND grantee_id = %s;" "$new_perms" "$group_id" "$target_id"
                msg "[治理] 管理员 ${target_id:0:16} 已被移除。"
            fi
            db_commit_transaction "$FORUM_DB"
        else warn "[治理] 提案 ${proposal_hash:0:12}... 未能达成成员共识，已失效。"; fi
    done
}

_execute_owner_transfer() {
    local group_id="$1"; local current_owner_id="$2"; local candidate_id="$3"; local proposal_hash="$4"
    msg "[治理] 共识达成！正在罢免现任群主并转移权限 (提案: ${proposal_hash:0:12})。[Governance] Consensus reached! Removing the current group leader and transferring permissions (proposal: ${proposal_hash:0:12})"; db_begin_transaction "$FORUM_DB"
    local old_owner_perms=$(db_query_safe "$FORUM_DB" "SELECT permissions FROM acl_state WHERE acl_id = %s AND grantee_id = %s;" "$group_id" "$current_owner_id")
    local new_perms_for_old_owner=$(echo "$old_owner_perms" | jq 'del(.[] | select(. == "owner" or . == "admin"))')
    db_execute_safe "$FORUM_DB" "UPDATE acl_state SET permissions = %s WHERE acl_id = %s AND grantee_id = %s;" "$new_perms_for_old_owner" "$group_id" "$current_owner_id"
    local candidate_perms=$(db_query_safe "$FORUM_DB" "SELECT permissions FROM acl_state WHERE acl_id = %s AND grantee_id = %s;" "$group_id" "$candidate_id" | jq -r '. // []')
    local new_perms_for_candidate=$(jq -n --argjson p "$candidate_perms" '($p + ["owner", "admin", "member"]) | unique')
    db_execute_safe "$FORUM_DB" "INSERT OR REPLACE INTO acl_state (acl_id, grantee_id, permissions) VALUES (%s, %s, %s);" "$group_id" "$candidate_id" "$new_perms_for_candidate"
    db_commit_transaction "$FORUM_DB"; msg "[治理] 群主已成功变更为 ${candidate_id:0:16}... / [Governance] Owner successfully changed to ${candidate_id:0:16}..."
}

# =======================================================
# --- [AGENT] 内部辅助函数：获取 Mod 的事件钩子声明 ---
# =======================================================
# @param $1 - pkg_id
# @return Space-separated list of hook names (e.g., "on_forum_post on_set_nickname")
_get_mod_event_hooks() {
    local pkg_id="$1"
    local raw_hooks
    
    # 复用 _get_mod_metadata_value 安全地解析元数据
    raw_hooks=$(_get_mod_metadata_value "$pkg_id" "corix_event_hooks")
    
    # 替换所有换行符和逗号为空格，并清理多余空格
    echo "$raw_hooks" | tr '\n,' ' ' | xargs
}

# =======================================================
# --- [AGENT] 核心事件调度函数 (CORE EVENT DISPATCHER) ---
# =======================================================
# Finds and executes all active Agent Mods that are listening for the given event.
# 查找并执行所有正在监听给定事件的、处于活跃状态的 Agent Mod。
#
# @param $1 - event_name (e.g., "group_post", "set_nickname") / 事件名称
# @param $2 - tx_hash (The transaction that triggered the event) / 触发事件的交易哈希
# @param $3 - tx_payload (The raw JSON payload of the transaction data) / 交易数据的原始JSON载荷
_internal_agent_event_dispatch() {
    local event_name="$1"
    local tx_hash="$2"
    local tx_payload="$3"

    local enabled_mods_file="${ETC_CORIUM_DIR}/mods_enabled.conf"
    if [[ ! -r "$enabled_mods_file" ]]; then return 0; fi
    
    # 标准化事件钩子名称（例如，从交易类型 "group_post" 转换为钩子 "on_group_post"）
    # Standardize the event hook name (e.g., convert transaction type "group_post" to hook "on_group_post")
    local required_hook_name="on_${event_name}"

    detail "[Agent-Dispatch] Dispatching event: ${required_hook_name} (Tx: ${tx_hash:0:16}...)"

    # 遍历所有已启用的 Mod
    # Iterate through all enabled Mods
    while IFS= read -r pkg_id || [[ -n "$pkg_id" ]]; do
        [[ "$pkg_id" =~ ^# || -z "$pkg_id" ]] && continue
        
        local hooks
        hooks=$(_get_mod_event_hooks "$pkg_id")

        # 检查 Mod 的声明是否包含所需的钩子
        # Check if the Mod's declaration includes the required hook
        if [[ " ${hooks} " =~ " ${required_hook_name} " ]]; then
            local executable_path mod_type
            
            mod_type=$(_get_mod_metadata_value "$pkg_id" "corix_mod_type")
            
            # 确保只有声明为 "onchain_agent_logic" 或 "agent" 类型的 Mod 才会被调度
            # Ensure only Mods declared as "onchain_agent_logic" or "agent" types are scheduled
            if [[ "$mod_type" != "onchain_agent_logic" && "$mod_type" != "agent" ]]; then
                detail "  -> Mod '${pkg_id}' 声明了钩子，但类型无效 (${mod_type})，跳过。"
                continue
            fi
            
            executable_path=$(_get_mod_executable_path "$pkg_id")
            if [[ -z "$executable_path" || ! -x "$executable_path" ]]; then
                warn "Agent Mod '${pkg_id}' 已启用但找不到其可执行文件，无法响应事件。"
                continue
            fi
            
            detail "   -> Executing Agent: ${pkg_id}"
            
            # --- 设置传递给 Agent 的环境变量 ---
            # CORIUM_EVENT_NAME 告诉 Agent 触发了哪个事件
            export CORIUM_EVENT_NAME="$required_hook_name"
            # CORIUM_TRIGGER_TX_HASH 告诉 Agent 是哪个交易触发了它
            export CORIUM_TRIGGER_TX_HASH="$tx_hash"
            
            # 核心：将交易的载荷 JSON 作为 Agent 的标准输入 (stdin)
            # CORE: Pipe the transaction payload JSON as the Agent's standard input (stdin)
            # **注意**: 实际执行时，Agent将会在沙箱中直接读取stdin
            (
                echo "$tx_payload" | \
                _execute_mod_in_sandbox "$pkg_id" "$mod_type" "$executable_path"
            )

            # 清理环境变量
            unset CORIUM_EVENT_NAME CORIUM_TRIGGER_TX_HASH
        fi
    done < "$enabled_mods_file"
}

# REPLACES _sync_social_state(). This function is the single source of truth for building
# the application-layer state. This version has been heavily optimized with a batched
# event dispatch system for Agent activation and includes the dynamic execution engine
# for 3rd-generation applications.
#
# 取代 _sync_social_state()。此函数是构建应用层状态的唯一真相来源。
# 此版本经过深度优化，包含了一个用于激活 Agent 的集束化事件分发系统，
# 并整合了用于第三代应用的动态执行引擎。
_update_chain_state_cache() {
    # Paths are already resolved by the dispatcher or isolated replay caller.
    # 路径由命令分发器或隔离重放调用者确定，不能在重放中切回当前节点。
    
    # 它会修改多个数据库，所以请求最高级别的 system 锁
    acquire_lock "system"
    trap 'release_lock "system"' RETURN
    
    # [V105.9 FINAL FIX] Unified guard clause.
    # If the blockchain database file doesn't exist OR it contains no blocks,
    # there is nothing to sync. This single check handles all uninitialized states.
    # [V105.9 最终修复] 统一的卫兵子句。
    # 如果区块链数据库文件不存在，或者其中不包含任何区块，那就没有任何东西可以同步。
    # 这一个检查就能处理所有未初始化的状态。
    if [ ! -f "$BLOCKCHAIN_DB" ] || [ "$(db_query_static "$BLOCKCHAIN_DB" "SELECT COUNT(*) FROM blocks;" 2>/dev/null || echo 0)" -eq 0 ]; then
        detail "[State Engine] Blockchain database is not ready or is empty. Skipping state cache update."
        detail "[状态机] 区块链数据库未就绪或为空。跳过状态缓存更新。"
        return 0
    fi
    
    info "[状态机] 正在更新应用层状态缓存... / [State Engine] Updating application-layer state cache..."
    
    local last_processed_height current_chain_height
    
    last_processed_height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT value FROM chain_state WHERE key = 'last_processed_height' LIMIT 1;" 2>/dev/null || echo -1)
    # 对空字符串进行最终的默认值处理
    last_processed_height=${last_processed_height:--1}
    
    current_chain_height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT COALESCE(MAX(height), -1) FROM blocks;" 2>/dev/null || echo -1)
    current_chain_height=${current_chain_height:--1}
    
    if [ "${last_processed_height:--1}" -ge "${current_chain_height:--1}" ]; then
        detail "[状态机] 应用层状态已是最新。/ [State Engine] Application-layer state is already up-to-date."
        return 0
    fi

    detail "[状态机] 从区块 ${last_processed_height} 同步到 ${current_chain_height}... / [State Engine] Syncing from block ${last_processed_height} to ${current_chain_height}..."
   
    # --- [V86 事务强化] 在所有数据库上开始一个事务 ---
    # --- [V86 TX Hardening] Begin a transaction on all databases ---
    _begin_db_transaction "$FORUM_DB" "$BLOCKCHAIN_DB" "$DHT_DB"
    
    
    {
        local current_processing_height=$((last_processed_height + 1)) correction_scanned_height=-1

        # --- [集束化] 定义一个数组来收集本批次中发生的所有事件 ---
        # --- [BATCHING] Define an array to collect all events that occurred in this batch ---
        declare -a _EVENT_QUEUE_FOR_THIS_BATCH=()

        # 启动外层数据库事务
        # Start outer database transactions
        # All three databases already participate in the outer transaction.
        
        while IFS= read -r transaction_row; do
            local tx_hash tx_type tx_payload tx_pubkey tx_timestamp height
            tx_hash=$(jq -er '.[0]' <<< "$transaction_row")
            tx_type=$(jq -er '.[1]' <<< "$transaction_row")
            tx_payload=$(jq -ec '.[2] | fromjson' <<< "$transaction_row")
            tx_pubkey=$(jq -er '.[3]' <<< "$transaction_row")
            tx_timestamp=$(jq -er '.[4]' <<< "$transaction_row")
            height=$(jq -er '.[5]' <<< "$transaction_row")
            # --- [关键逻辑] 检测区块高度变化，处理区块级事件 ---
            # --- [CRITICAL LOGIC] Detect block height changes to process block-level events ---
            if [ "$height" -gt "$current_processing_height" ]; then
                # 在处理新区块之前，处理完上一个区块的所有区块级事件
                # Before processing the new block, handle all block-level events for the previous one(s)
                for (( h = current_processing_height < 0 ? 0 : current_processing_height; h < height; h++ )); do
                    detail "[状态机] 正在处理区块 ${h} 的区块级事件... / [State Engine] Processing block-level events for block ${h}..."
                    # _resolve_proofs_and_challenges_at_height is called by _process_onchain_events_at_height
                    # _nns_tally_auction_at_height is called by _process_onchain_events_at_height 
                    _protocol_tally_votes_and_schedule_changes "$h"
                    # _protocol_execute_scheduled_changes is called by _process_onchain_events_at_height
                    # _group_tally_owner_votes_at_height is called by _process_onchain_events_at_height
                    # _group_tally_admin_votes_at_height is called by _process_onchain_events_at_height
                    # --- [V82] 调用新的通用事件总线 ---
                    # --- [V82] Call the new universal event bus ---
                    _process_onchain_events_at_height "$h"
                done
                current_processing_height="$height"
            fi

            # --- [交易处理逻辑] ---
            # --- [Transaction Processing Logic] ---
            [ -z "$tx_hash" ] && continue
            
            # Pre-scan vetoes only within this block; its other transitions run once in order.
            # 仅预扫描当前区块的否决，其余状态修正按交易顺序执行一次。
            if [ "$correction_scanned_height" != "$height" ]; then
                local correction_row correction_payload
                while IFS= read -r correction_row; do
                    correction_payload=$(jq -ec --argjson h "$height" '.[0]|fromjson|[.state_transitions[]|select(.operation=="INVALIDATE_TX")|. + {height:$h}]' <<< "$correction_row") || return 1
                    _execute_state_correction "$correction_payload" || return 1
                done < <(db_query_safe "$BLOCKCHAIN_DB" "SELECT json_array(T.data) FROM blocks B JOIN json_each(B.transactions) J JOIN transactions T ON T.hash=J.value WHERE B.height=%d AND T.type='state_correction_tx' ORDER BY CAST(J.key AS INTEGER);" "$height")
                correction_scanned_height="$height"
            fi

            # --- [V94 安全升级] 交易处理前的最终否决检查 ---
            # --- [V94 SECURITY UPGRADE] Final Veto Check Before Transaction Processing ---
            local invalidation_record
            invalidation_record=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT reason FROM invalidated_transactions WHERE tx_hash = %s;" "$tx_hash")

            if [ -n "$invalidation_record" ]; then
                warn "[状态机] 已跳过被宣布无效的交易 ${tx_hash:0:16}... (原因 / Reason: $invalidation_record) / [State Engine] Skipped invalidated transaction ${tx_hash:0:16}... (Reason: $invalidation_record)"
                continue # 直接跳到下一笔交易 / Skip directly to the next transaction
            fi
            # --- [V94 安全升级结束] ---

            local sender_id
            sender_id=$(_internal_hash_text "$tx_pubkey")

            # --- 步骤 1: 纯粹的状态转换 ---
            # --- Step 1: Pure State Transition ---
            # The case statement is now ONLY responsible for changing the database state.
            # case 语句现在只负责改变数据库状态。
            case "$tx_type" in
                ziokt_identity_register|ziokt_content|zkn_mint|zkn_transfer|zkn_private_transfer|zkc_issue|zkn_shield_deposit|zkn_shield_transfer|zkn_shield_withdraw|privacy_review_request|privacy_review_vote|privacy_review_revoke|privacy_review_disclose)
                    _ziokt_asset_engine apply "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$tx_type" "$tx_payload" "$sender_id" "$tx_hash" "$height" || return 1
                    ;;
                ziokt_identity_register|zkn_mint|zkn_transfer)
                    _ziokt_asset_engine apply "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$tx_type" "$tx_payload" "$sender_id" "$tx_hash" "$height" || return 1
                    ;;
                "user_message"|"group_post"|"broadcast_post")
                    local recipient_id content_hash attachment_meta encryption_mode
                    recipient_id=$(echo "$tx_payload" | jq -r .recipient_id)
                    
                    if [ "$tx_type" = "group_post" ]; then
                        if ! _is_authorized_by_acl "$recipient_id" "$sender_id" "member"; then
                            warn "[Consensus] group_post rejected: Sender ${sender_id:0:8} is not a member of group ${recipient_id:0:8}"
                            continue
                        fi
                    elif [ "$tx_type" = "broadcast_post" ]; then
                        if ! _is_authorized_by_acl "$recipient_id" "$sender_id" "write"; then
                            warn "[Consensus] broadcast_post rejected: Sender ${sender_id:0:8} is not authorized to write to broadcast ${recipient_id:0:8}"
                            continue
                        fi
                    fi
                    
                    content_hash=$(echo "$tx_payload" | jq -r .content_hash)
                    attachment_meta=$(echo "$tx_payload" | jq -c '.attachment // null') # Store as compact JSON
                    encryption_mode=$(echo "$tx_payload" | jq -r '.encryption // "none"')
                    local source_type="DIRECT"
                    [ "$tx_type" = "group_post" ] && source_type="GROUP"
                    [ "$tx_type" = "broadcast_post" ] && source_type="BROADCAST"
                    db_execute_safe "$FORUM_DB" \
                        "INSERT OR IGNORE INTO messages (tx_hash, sender_id, recipient_id, source_type, content_hash, attachment_meta, encryption_mode, timestamp) VALUES (%s, %s, %s, %s, %s, %s, %s, %d);" \
                        "$tx_hash" "$sender_id" "$recipient_id" "$source_type" "$content_hash" "$attachment_meta" "$encryption_mode" "$tx_timestamp"
                    ;;
                "group_admin_action")
                    local group_id action
                    group_id=$(echo "$tx_payload" | jq -r .group_id)
                    action=$(echo "$tx_payload" | jq -r .action)
                    case "$action" in
                        "wiki_force_unlock")
                            local page_slug page_tx_hash
                            page_slug=$(echo "$tx_payload" | jq -r .target.page_slug)
                            page_tx_hash=$(db_query_safe "$FORUM_DB" "SELECT page_tx_hash FROM wiki_pages WHERE group_id = %s AND slug = %s;" "$group_id" "$page_slug")
                            if [ -n "$page_tx_hash" ]; then
                                db_execute_safe "$FORUM_DB" "UPDATE wiki_pages SET locked_by_user_id = NULL, lock_tx_hash = NULL WHERE page_tx_hash = %s;" "$page_tx_hash"
                            fi
                            ;;
                        "wiki_rename_slug")
                            local old_slug new_slug
                            old_slug=$(echo "$tx_payload" | jq -r .target.old_slug)
                            new_slug=$(echo "$tx_payload" | jq -r .target.new_slug)
                            local is_taken=$(db_query_safe "$FORUM_DB" "SELECT COUNT(*) FROM wiki_pages WHERE group_id = %s AND slug = %s;" "$group_id" "$new_slug")
                            if [ "$is_taken" -eq 0 ]; then
                                db_execute_safe "$FORUM_DB" "UPDATE wiki_pages SET slug = %s WHERE group_id = %s AND slug = %s;" "$new_slug" "$group_id" "$old_slug"
                            fi
                            ;;
                        "wiki_delete_page")
                            local page_slug page_tx_hash
                            page_slug=$(echo "$tx_payload" | jq -r .target.page_slug)
                            page_tx_hash=$(db_query_safe "$FORUM_DB" "SELECT page_tx_hash FROM wiki_pages WHERE group_id = %s AND slug = %s;" "$group_id" "$page_slug")
                            if [ -n "$page_tx_hash" ]; then
                                db_begin_transaction "$FORUM_DB"
                                db_execute_safe "$FORUM_DB" "DELETE FROM wiki_versions WHERE page_tx_hash = %s;" "$page_tx_hash"
                                db_execute_safe "$FORUM_DB" "DELETE FROM wiki_pages WHERE page_tx_hash = %s;" "$page_tx_hash"
                                db_commit_transaction "$FORUM_DB"
                            fi
                            ;;
                    esac
                    ;;
                "mail_dispatch")
                    local recipient_id mail_object_hash
                    recipient_id=$(echo "$tx_payload" | jq -r .recipient_id)
                    mail_object_hash=$(echo "$tx_payload" | jq -r .mail_object_hash)
                    db_execute_safe "$FORUM_DB" \
                        "INSERT OR IGNORE INTO mails (tx_hash, sender_id, recipient_id, mail_object_hash, timestamp) VALUES (%s, %s, %s, %s, %d);" \
                        "$tx_hash" "$sender_id" "$recipient_id" "$mail_object_hash" "$tx_timestamp"
                    ;;
                "submit_math_proof")
                    [ "$(db_query_safe "$BLOCKCHAIN_DB" "SELECT pkg_id FROM compute_engines WHERE engine_id=%s;" "$(jq -r .engine_id <<< "$tx_payload")")" != consensus/work-weight:2 ] || return 1
                    if [ "$(db_query_safe "$BLOCKCHAIN_DB" "SELECT pkg_id FROM compute_engines WHERE engine_id=%s;" "$(jq -r .engine_id <<< "$tx_payload")")" = compute/openci-attested:1 ]; then
                        _corium_openci_consensus validate "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$tx_payload" "$sender_id" "$height" >/dev/null || return 1
                    fi
                    if [ "$(db_query_safe "$BLOCKCHAIN_DB" "SELECT pkg_id FROM compute_engines WHERE engine_id=%s;" "$(jq -r .engine_id <<< "$tx_payload")")" = corium/built-in-gimps ]; then
                        _corium_gimps_consensus validate "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$tx_payload" "$sender_id" "$height" >/dev/null || return 1
                    fi
                    local problem_id proposed_result CHALLENGE_WINDOW=10 deadline
                    deadline=$((height + CHALLENGE_WINDOW))
                    problem_id=$(echo "$tx_payload" | jq -r .problem_id)
                    proposed_result=$(echo "$tx_payload" | jq -r .proposed_result)
                    db_execute_safe "$BLOCKCHAIN_DB" "INSERT INTO pending_proofs (problem_id, proof_tx_hash, proposer_id, proposed_result, confirmation_deadline_height) VALUES (%s, %s, %s, %s, %d);" "$problem_id" "$tx_hash" "$sender_id" "$proposed_result" "$deadline"
                    ;;
                "challenge_proof")
                    local target_proof_tx_hash challenge_data
                    target_proof_tx_hash=$(echo "$tx_payload" | jq -r .target_proof_tx_hash)
                    challenge_data=$(echo "$tx_payload" | jq -r .challenge_data)
                    db_execute_safe "$BLOCKCHAIN_DB" "INSERT INTO challenges (challenge_tx_hash, target_proof_tx_hash, challenger_id, challenge_data, status) VALUES (%s, %s, %s, %s, 'pending');" "$tx_hash" "$target_proof_tx_hash" "$sender_id" "$challenge_data"
                    ;;
                "state_correction_tx")
                    _execute_state_correction "$(jq -ec '[.state_transitions[]|select(.operation!="INVALIDATE_TX")]' <<< "$tx_payload")" || return 1
                    if [ "${CORIUM_REPLAY:-0}" != 1 ]; then
                        local veto_payload
                        while IFS= read -r veto_payload; do
                            _internal_ibc_dispatch "FEDERATION_ALL" "IBC_STATE_INVALIDATION" "$veto_payload" || return 1
                        done < <(jq -c '.state_transitions[]|select(.operation=="INVALIDATE_TX")|{invalidated_tx_hash:.tx_hash,reason:(.reason//"No reason provided.")}' <<< "$tx_payload")
                    fi
                    ;;
                "propose_new_compute_engine")
                    local description pkg_id compute_hash verifier_hash
                    description=$(echo "$tx_payload" | jq -r .description)
                    pkg_id=$(echo "$tx_payload" | jq -r .pkg_id)
                    compute_hash=$(echo "$tx_payload" | jq -r .compute_program_hash)
                    verifier_hash=$(echo "$tx_payload" | jq -r .verifier_script_hash)
                    local engine_reward_weight
                    engine_reward_weight=$(jq -er '.reward_weight // 100' <<< "$tx_payload") || return 1
                    db_execute_safe "$BLOCKCHAIN_DB" "INSERT INTO compute_engines (engine_id, pkg_id, description, compute_program_hash, verifier_script_hash, is_active, reward_weight) VALUES (%s, %s, %s, %s, %s, 0, %d);" "$tx_hash" "$pkg_id" "$description" "$compute_hash" "$verifier_hash" "$engine_reward_weight"
                    ;;
                "set_nickname")
                    local nickname=$(echo "$tx_payload" | jq -r .nickname)
                    db_execute_safe "$FORUM_DB" "INSERT OR REPLACE INTO identity_cache (id_hash, nickname, type, permissions, last_updated_height) VALUES (%s, %s, 'user', '{}', %d);" "$sender_id" "$nickname" "$height"
                    
                    # --- [V100 IBC TRIGGER] ---
                    # 当昵称被设置时，自动广播一个 IBC_IDENTITY_SYNC 消息
                    # When a nickname is set, automatically broadcast an IBC_IDENTITY_SYNC message.
                    local ibc_payload; ibc_payload=$(jq -n --arg id "$sender_id" --arg nick "$nickname" --arg type "user" '{id_hash: $id, nickname: $nick, type: $type}')
                    # "FEDERATION_ALL" 是一个特殊的目标链ID，表示广播给所有已知的联邦成员
                    # "FEDERATION_ALL" is a special target chain ID meaning broadcast to all known federation members.
                    [ "${CORIUM_REPLAY:-0}" = 1 ] || _internal_ibc_dispatch "FEDERATION_ALL" "IBC_IDENTITY_SYNC" "$ibc_payload"
                    ;;
                "acl_create")
                    db_execute_safe "$FORUM_DB" "INSERT OR IGNORE INTO acl_state (acl_id, grantee_id, permissions) VALUES (%s, %s, '[\"owner\"]');" "$tx_hash" "$sender_id"
                    ;;
                "acl_grant")
                    local acl_id grantee_id perms_to_add current_perms new_perms
                    acl_id=$(echo "$tx_payload" | jq -r .acl_id); grantee_id=$(echo "$tx_payload" | jq -r .grantee_id)
                    perms_to_add=$(echo "$tx_payload" | jq '.permissions')
                    current_perms=$(db_query_safe "$FORUM_DB" "SELECT permissions FROM acl_state WHERE acl_id = %s AND grantee_id = %s;" "$acl_id" "$grantee_id" | jq -r '. // []')
                    current_perms=${current_perms:-[]}
                    new_perms=$(jq -n --argjson p1 "$current_perms" --argjson p2 "$perms_to_add" '($p1 + $p2) | unique')
                    db_execute_safe "$FORUM_DB" "INSERT OR REPLACE INTO acl_state (acl_id, grantee_id, permissions) VALUES (%s, %s, %s);" "$acl_id" "$grantee_id" "$new_perms"
                    ;;
                "acl_revoke")
                    local acl_id grantee_id perms_to_remove current_perms new_perms VOTE_WINDOW=500
                    acl_id=$(echo "$tx_payload" | jq -r .acl_id); grantee_id=$(echo "$tx_payload" | jq -r .grantee_id)
                    perms_to_remove=$(echo "$tx_payload" | jq '.permissions')
                    current_perms=$(db_query_safe "$FORUM_DB" "SELECT permissions FROM acl_state WHERE acl_id = %s AND grantee_id = %s;" "$acl_id" "$grantee_id" | jq -r '. // []')
                    current_perms=${current_perms:-[]}
                    new_perms=$(jq -n --argjson p1 "$current_perms" --argjson p2 "$perms_to_remove" '$p1 - $p2')
                    db_execute_safe "$FORUM_DB" "INSERT OR REPLACE INTO acl_state (acl_id, grantee_id, permissions) VALUES (%s, %s, %s);" "$acl_id" "$grantee_id" "$new_perms"
                    if _is_authorized_by_acl "$acl_id" "$sender_id" "owner" && [[ "$perms_to_remove" == *'"admin"'* ]]; then
                        local active_proposal=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT hash, data, public_key FROM transactions WHERE type = 'group_propose_owner' AND json_extract(data, '$.group_id') = %s AND (block_height + %d) > %d;" "$acl_id" "$VOTE_WINDOW" "$height" | head -n 1)
                        if [ -n "$active_proposal" ]; then
                            local non_owner_admins_count=$(db_query_safe "$FORUM_DB" "SELECT COUNT(*) FROM acl_state WHERE acl_id = %s AND permissions LIKE '%\"admin\"%' AND permissions NOT LIKE '%\"owner\"%';" "$acl_id")
                            local proposer_id=$(_internal_hash_text "$(echo "$active_proposal" | cut -d'|' -f3)")
                            if [ "$non_owner_admins_count" -eq 1 ] && [ "$(db_query_safe "$FORUM_DB" "SELECT grantee_id FROM acl_state WHERE acl_id = %s AND permissions LIKE '%\"admin\"%' AND permissions NOT LIKE '%\"owner\"%';" "$acl_id")" = "$proposer_id" ]; then
                                warn "[治理] 检测到独裁者否决！罢免提案即刻生效！[Governance] Detected dictator veto! The recall proposal takes effect immediately!"; local proposal_hash candidate_id; proposal_hash=$(echo "$active_proposal" | cut -d'|' -f1); candidate_id=$(echo "$active_proposal" | jq -r .candidate_id)
                                _execute_owner_transfer "$acl_id" "$sender_id" "$candidate_id" "$proposal_hash"
                            fi
                        fi
                    fi
                    ;;
                "group_create")
                    local group_id nickname initial_owner perms
                    group_id="$tx_hash"; nickname=$(echo "$tx_payload" | jq -r .nickname); initial_owner=$(echo "$tx_payload" | jq -r .initial_owner)
                    perms=$(jq -n --arg o "$initial_owner" '{"owner":$o, "policy":{"join_mode":"invite-only", "description":""}}')
                    db_execute_safe "$FORUM_DB" "INSERT OR IGNORE INTO identity_cache (id_hash, nickname, type, permissions, last_updated_height) VALUES (%s, %s, 'group', %s, %d);" "$group_id" "$nickname" "$perms" "$height"
                    db_execute_safe "$FORUM_DB" "INSERT OR IGNORE INTO acl_state (acl_id, grantee_id, permissions) VALUES (%s, %s, '[\"owner\",\"admin\",\"member\"]');" "$group_id" "$initial_owner"
                    ;;
                "group_set_policy")
                    local group_id policy current_perms new_perms
                    group_id=$(echo "$tx_payload" | jq -r .group_id); policy=$(echo "$tx_payload" | jq .policy)
                    current_perms=$(db_query_safe "$FORUM_DB" "SELECT permissions FROM identity_cache WHERE id_hash = %s;" "$group_id")
                    new_perms=$(echo "$current_perms" | jq --argjson p "$policy" '.policy = $p')
                    db_execute_safe "$FORUM_DB" "UPDATE identity_cache SET permissions = %s, last_updated_height = %d WHERE id_hash = %s;" "$new_perms" "$height" "$group_id"
                    ;;
                "group_member_join")
                    local group_id current_perms new_perms
                    group_id=$(echo "$tx_payload" | jq -r .group_id)
                    current_perms=$(db_query_safe "$FORUM_DB" "SELECT permissions FROM acl_state WHERE acl_id = %s AND grantee_id = %s;" "$group_id" "$sender_id" | jq -r '. // []')
                    current_perms=${current_perms:-[]}
                    new_perms=$(jq -n --argjson p "$current_perms" '($p + ["member"]) | unique')
                    db_execute_safe "$FORUM_DB" "INSERT OR REPLACE INTO acl_state (acl_id, grantee_id, permissions) VALUES (%s, %s, %s);" "$group_id" "$sender_id" "$new_perms"
                    ;;
                "wiki_page_create")
                    local page_tx_hash group_id slug content_hash msg format attachment_hash
                    page_tx_hash="$tx_hash"; group_id=$(echo "$tx_payload" | jq -r .group_id); slug=$(echo "$tx_payload" | jq -r .page_slug)
                    content_hash=$(echo "$tx_payload" | jq -r .content_hash); attachment_hash=$(echo "$tx_payload" | jq -r '.attachment_hash // ""')
                    msg=$(echo "$tx_payload" | jq -r .commit_message); format=$(echo "$tx_payload" | jq -r '.format // "md"')
                    db_execute_safe "$FORUM_DB" "INSERT OR IGNORE INTO wiki_pages (page_tx_hash, group_id, slug, latest_version_hash, attachment_hash) VALUES (%s, %s, %s, %s, %s);" "$page_tx_hash" "$group_id" "$slug" "$page_tx_hash" "$attachment_hash"
                    db_execute_safe "$FORUM_DB" "INSERT OR IGNORE INTO wiki_versions (version_tx_hash, page_tx_hash, author_id, content_hash, commit_message, format, timestamp) VALUES (%s, %s, %s, %s, %s, %s, %d);" "$page_tx_hash" "$page_tx_hash" "$sender_id" "$content_hash" "$msg" "$format" "$tx_timestamp"
                    ;;
                "wiki_page_lock")
                    local page_tx_hash=$(echo "$tx_payload" | jq -r .page_create_tx_hash)
                    db_execute_safe "$FORUM_DB" "UPDATE wiki_pages SET locked_by_user_id = %s, lock_tx_hash = %s WHERE page_tx_hash = %s;" "$sender_id" "$tx_hash" "$page_tx_hash"
                    ;;
                "wiki_page_unlock")
                    local page_tx_hash=$(echo "$tx_payload" | jq -r .page_create_tx_hash)
                    db_execute_safe "$FORUM_DB" "UPDATE wiki_pages SET locked_by_user_id = NULL, lock_tx_hash = NULL WHERE page_tx_hash = %s;" "$page_tx_hash"
                    ;;
                "wiki_page_edit")
                    local page_tx_hash prev_ver content_hash msg format attachment_hash
                    page_tx_hash=$(echo "$tx_payload" | jq -r .page_create_tx_hash); prev_ver=$(echo "$tx_payload" | jq -r .previous_version_hash)
                    content_hash=$(echo "$tx_payload" | jq -r .content_hash); attachment_hash=$(echo "$tx_payload" | jq -r '.attachment_hash // ""')
                    msg=$(echo "$tx_payload" | jq -r .commit_message); format=$(echo "$tx_payload" | jq -r '.format // "md"')
                    db_execute_safe "$FORUM_DB" "INSERT OR IGNORE INTO wiki_versions (version_tx_hash, page_tx_hash, previous_version_hash, author_id, content_hash, commit_message, format, timestamp) VALUES (%s, %s, %s, %s, %s, %s, %s, %d);" "$tx_hash" "$page_tx_hash" "$prev_ver" "$sender_id" "$content_hash" "$msg" "$format" "$tx_timestamp"
                    db_execute_safe "$FORUM_DB" "UPDATE wiki_pages SET latest_version_hash = %s, attachment_hash = %s, locked_by_user_id = NULL, lock_tx_hash = NULL WHERE page_tx_hash = %s;" "$tx_hash" "$attachment_hash" "$page_tx_hash"
                    ;;
                cooperative_command)
                    _corium_work_consensus cooperative-apply "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$height" "$tx_payload" >/dev/null || return 1
                    ;;
                "nns_register")
                    local domain_name target_hash registration_type probes_json expires_at
                    domain_name=$(echo "$tx_payload" | jq -r .domain_name); target_hash=$(echo "$tx_payload" | jq -r .target_hash)
                    [ "$height" -le 5000 ] && registration_type="genesis_contribution" || registration_type="auction"
                    expires_at=$((tx_timestamp + 31536000)) # 1 year
                    db_execute_safe "$FORUM_DB" "INSERT OR REPLACE INTO nns_records (domain_name, owner_id, target_hash, last_update_height, registration_type, expires_at) VALUES (%s, %s, %s, %d, %s, %d);" "$domain_name" "$sender_id" "$target_hash" "$height" "$registration_type" "$expires_at"
                    probes_json=$(echo "$tx_payload" | jq -r '.proof_of_contribution.probes // .proof_of_genesis_contribution.probes // "[]"')
                    for probe in $(echo "$probes_json" | jq -r '.[] | @base64'); do
                        local decoded_probe=$(echo "$probe" | base64 --decode)
                        local target_node_id=$(echo "$decoded_probe" | jq -r .node_id); local latency=$(echo "$decoded_probe" | jq -r .latency_ms)
                        db_execute_safe "$DHT_DB" "INSERT OR REPLACE INTO network_latency_map (source_node_id, target_node_id, latency_ms, last_updated_block) VALUES (%s, %s, %d, %d);" "$sender_id" "$target_node_id" "$latency" "$height"
                    done
                    ;;
                "nns_update")
                    local nns_record
                    while IFS= read -r nns_record; do
                        db_execute_safe "$FORUM_DB" "UPDATE nns_records SET target_hash=%s,last_update_height=%d WHERE domain_name=%s AND owner_id=%s;" "$(jq -r .target_hash <<< "$nns_record")" "$height" "$(jq -r .domain_name <<< "$nns_record")" "$sender_id" || return 1
                    done < <(jq -c '.records[]' <<< "$tx_payload")
                    ;;
                "nns_transfer")
                    local domain_name new_owner tax_json
                    domain_name=$(echo "$tx_payload" | jq -r .domain_name); new_owner=$(echo "$tx_payload" | jq -r .new_owner_id)
                    db_execute_safe "$FORUM_DB" "UPDATE nns_records SET owner_id = %s, last_update_height = %d WHERE domain_name = %s;" "$new_owner" "$height" "$domain_name"
                    tax_json=$(echo "$tx_payload" | jq -r '.contribution_tax.probes // "[]"')
                    for probe in $(echo "$tax_json" | jq -r '.[] | @base64'); do
                        local decoded_probe=$(echo "$probe" | base64 --decode)
                        local target_node_id=$(echo "$decoded_probe" | jq -r .node_id); local latency=$(echo "$decoded_probe" | jq -r .latency_ms)
                        db_execute_safe "$DHT_DB" "INSERT OR REPLACE INTO network_latency_map (source_node_id, target_node_id, latency_ms, last_updated_block) VALUES (%s, %s, %d, %d);" "$sender_id" "$target_node_id" "$latency" "$height"
                    done
                    ;;
                "nns_start_auction")
                    local domain_name end_bid_block=$((height + 100)) end_reveal_block=$((height + 150))
                    domain_name=$(echo "$tx_payload" | jq -r .domain_name)
                    local current_expiry=$(db_query_safe "$FORUM_DB" "SELECT expires_at FROM nns_records WHERE domain_name = %s;" "$domain_name")
                    if [ -z "$current_expiry" ] || [ "$current_expiry" -lt "$tx_timestamp" ]; then
                        db_execute_safe "$FORUM_DB" "INSERT OR IGNORE INTO nns_auctions (domain_name, start_block, end_bid_block, end_reveal_block, status) VALUES (%s, %d, %d, %d, 'BIDDING');" "$domain_name" "$height" "$end_bid_block" "$end_reveal_block"
                    fi
                    ;;
                "nns_reveal")
                    local domain_name=$(echo "$tx_payload" | jq -r .domain_name)
                    local amount=$(echo "$tx_payload" | jq -r .amount)
                    local salt=$(echo "$tx_payload" | jq -r .salt)
                    
                    local blind_hash=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT json_extract(data, '$.blind_hash') FROM transactions WHERE type = 'nns_bid' AND public_key = (SELECT public_key FROM transactions WHERE hash = %s LIMIT 1) AND json_extract(data, '$.domain_name') = %s;" "$tx_hash" "$domain_name")
                    local calculated_hash=$(_internal_hash_text "${amount}|${salt}")
                    if [ "$calculated_hash" == "$blind_hash" ]; then
                        local balance=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT score FROM contribution_scores WHERE user_id = %s;" "$sender_id")
                        if [ -n "$balance" ] && [ "$balance" -ge "$amount" ]; then
                            db_execute_safe "$BLOCKCHAIN_DB" "UPDATE contribution_scores SET score = score - %d WHERE user_id = %s;" "$amount" "$sender_id"
                            db_execute_safe "$BLOCKCHAIN_DB" "INSERT INTO nns_locked_funds (domain_name, user_id, amount) VALUES (%s, %s, %d);" "$domain_name" "$sender_id" "$amount"
                            db_execute_safe "$FORUM_DB" "UPDATE nns_auctions SET status = 'REVEAL' WHERE domain_name = %s AND end_bid_block < %d;" "$domain_name" "$height"
                        fi
                    fi
                    ;;
                "nns_renew")
                    local domain_name=$(echo "$tx_payload" | jq -r .domain_name)
                    local cost=$(_nns_calculate_renewal_cost "$domain_name" "$sender_id" "$BLOCKCHAIN_DB")
                    
                    local owner_id=$(db_query_safe "$FORUM_DB" "SELECT owner_id FROM nns_records WHERE domain_name = %s;" "$domain_name")
                    if [ "$owner_id" == "$sender_id" ]; then
                        local balance=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT score FROM contribution_scores WHERE user_id = %s;" "$sender_id")
                        if [ -n "$balance" ] && [ "$balance" -ge "$cost" ]; then
                            db_execute_safe "$BLOCKCHAIN_DB" "UPDATE contribution_scores SET score = score - %d WHERE user_id = %s;" "$cost" "$sender_id"
                            db_execute_safe "$FORUM_DB" "UPDATE nns_records SET expires_at = expires_at + 31536000 WHERE domain_name = %s;" "$domain_name"
                        fi
                    fi
                    ;;
                "ibc_dispatch")
                    local target_chain_id message_type message_payload postage
                    target_chain_id=$(echo "$tx_payload" | jq -r .target_chain_id)
                    message_type=$(echo "$tx_payload" | jq -r .message_type)
                    message_payload=$(echo "$tx_payload" | jq -c .message_payload)
                    postage=$(( $(echo -n "$message_payload" | wc -c) / 1024 + 1 ))
                    db_execute_safe "$BLOCKCHAIN_DB" "UPDATE contribution_scores SET score = score - %d WHERE user_id = %s;" "$postage" "$sender_id"
                    db_execute_safe "$BLOCKCHAIN_DB" \
                        "INSERT OR IGNORE INTO ibc_outgoing_queue (source_tx_hash, target_chain_id, message_type, message_payload, postage) VALUES (%s, %s, %s, %s, %d);" \
                        "$tx_hash" "$target_chain_id" "$message_type" "$message_payload" "$postage"
                    ;;
                "ibc_receive")
                    local source_chain_id payload_and_proof_b64 verifier_id
                    source_chain_id=$(echo "$tx_payload" | jq -r .source_chain_id)
                    payload_and_proof_b64=$(echo "$tx_payload" | jq -r .payload_and_proof)
                    verifier_id=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT verifier_id FROM ibc_verifiers WHERE target_chain_id = %s AND is_active = 1;" "$source_chain_id")
                    if [ -z "$verifier_id" ]; then
                        warn "[IBC] 收到来自'${source_chain_id}'的跨链消息，但本链未注册任何验证器。消息被忽略。"
                        warn "[IBC] Received cross-chain message from '${source_chain_id}', but no verifier is registered for it on this chain. Message ignored."
                        continue
                    fi
                    local is_proof_valid=false
                    if [[ "$verifier_id" == BUILT_IN:* ]]; then
                        local verifier_type="${verifier_id#BUILT_IN:}"
                        case "$verifier_type" in
                            "hash-chain-v1")
                                if _internal_verify_hash_chain_proof "$source_chain_id" "$payload_and_proof_b64"; then
                                    is_proof_valid=true
                                fi
                                ;;
                            *) warn "[IBC] 未知的内置验证器类型 / Unknown built-in verifier type: ${verifier_type}" ;;
                        esac
                    else
                        local verifier_executable=$(_get_mod_executable_path "$verifier_id")
                        if [ -n "$verifier_executable" ]; then
                            info "[IBC] 正在使用 Mod '${verifier_id}' 验证证明... / Verifying proof using Mod '${verifier_id}'..."
                            if echo "$payload_and_proof_b64" | base64 -d | _execute_mod_in_sandbox "$verifier_id" "ibc_verifier" "$verifier_executable"; then
                                is_proof_valid=true
                            fi
                        else
                            warn "[IBC] 验证器 Mod '${verifier_id}' 未找到或不可执行。 / Verifier Mod '${verifier_id}' not found or not executable."
                        fi
                    fi
                    if $is_proof_valid; then
                        local source_tx_hash message_payload proof_data message_type
                        local payload_and_proof_json=$(echo "$payload_and_proof_b64" | base64 -d)
                        source_tx_hash=$(echo "$payload_and_proof_json" | jq -r .source_tx_hash)
                        message_payload=$(echo "$payload_and_proof_json" | jq -c .message_payload)
                        proof_data=$(echo "$payload_and_proof_json" | jq -c .proof_data)
                        message_type=$(echo "$payload_and_proof_json" | jq -r .message_type)
                        
                        # [V107 Security Fix] Ensure source_tx_hash matches the target_tx_hash in the proof
                        local verified_tx_hash
                        verified_tx_hash=$(echo "$proof_data" | jq -r .merkle_proof.target_tx_hash)
                        if [ "$source_tx_hash" != "$verified_tx_hash" ]; then
                            warn "[IBC] 跨链消息验证失败: source_tx_hash 与证明中的 target_tx_hash 不匹配！消息被拒绝。"
                            continue
                        fi
                        
                        db_execute_safe "$BLOCKCHAIN_DB" \
                            "INSERT OR IGNORE INTO ibc_incoming_queue (source_chain_id, source_tx_hash, message_type, message_payload, proof_data) VALUES (%s, %s, %s, %s, %s);" \
                            "$source_chain_id" "$source_tx_hash" "$message_type" "$message_payload" "$proof_data"
                    else
                        warn "[IBC] 来自'${source_chain_id}'的跨链消息验证失败！消息被拒绝。"
                        warn "[IBC] Cross-chain message from '${source_chain_id}' FAILED verification! Message rejected."
                    fi
                    ;;
                "agent_create")
                    local agent_pkg_id=$(echo "$tx_payload" | jq -r .pkg_id)
                    local agent_pubkey=$(echo "$tx_payload" | jq -r .agent_pubkey)
                    local agent_id=$(echo "$tx_payload" | jq -r .agent_id)
                    db_execute_safe "$BLOCKCHAIN_DB" \
                        "INSERT INTO onchain_identities (agent_id, owner_id, pkg_id, public_key, activation_height) VALUES (%s, %s, %s, %s, %d);" \
                        "$agent_id" "$sender_id" "$agent_pkg_id" "$agent_pubkey" "$height"
                    ;;
                "endow_agent")
                    local agent_id amount purpose balance
                    agent_id=$(echo "$tx_payload" | jq -r .agent_id); amount=$(echo "$tx_payload" | jq -r .amount)
                    purpose=$(echo "$tx_payload" | jq -r '.purpose // ""')
                    if ! [[ "$amount" =~ ^[1-9][0-9]*$ ]]; then
                        warn "[Endowment] 交易 ${tx_hash:0:12} 无效：赋予的数量不是一个有效的正整数。"
                        continue
                    fi
                    balance=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT score FROM contribution_scores WHERE user_id = %s;" "$sender_id")
                    if [ -z "$balance" ] || [ "$balance" -lt "$amount" ]; then
                        warn "[Endowment] 交易 ${tx_hash:0:12} 失败：余额不足。"
                        continue
                    fi
                    db_execute_safe "$BLOCKCHAIN_DB" "UPDATE contribution_scores SET score = score - %d WHERE user_id = %s;" "$amount" "$sender_id"
                    db_execute_safe "$BLOCKCHAIN_DB" \
                        "INSERT INTO contribution_scores (user_id, score, last_update_height) VALUES (%s, %d, %d) ON CONFLICT(user_id) DO UPDATE SET score = score + excluded.score, last_update_height = excluded.last_update_height;" \
                        "$agent_id" "$amount" "$height"
                    ;;
                "forum"|"package_register"|"validator_propose_addition"|"validator_propose_removal"|"propose_app_template"|"vote_app_template"|"propose_federation_key"|"vote_federation_key"|"propose_ibc_verifier"|"vote_on_compute_engine"|"vote_ibc_verifier"|"group_propose_owner"|"group_vote_owner"|"group_propose_admin"|"group_vote_admin")
                    # Package registrations are canonical transaction records, queried directly by package verification.
                    # 包注册以已验证的链上交易为准；治理交易由区块级计票处理。
                    # These governance transactions are handled by block-level tallying functions.
                    # 这些治理交易由区块级的计票函数处理。
                    ;;
                # --- NEW CASE BRANCH for PoUW Reports ---
                # --- PoUW 报告的新 case 分支 ---
                "pouw_submit_report")
                    local proof_payload peer_signatures reporter_id
                    reporter_id="$sender_id"
                    proof_payload=$(echo "$tx_payload" | jq -c .proof_payload)
                    peer_signatures=$(echo "$tx_payload" | jq -c .peer_signatures)

                    local reported_node_id proof_sig
                    reported_node_id=$(echo "$proof_payload" | jq -r .node_id)
                    proof_sig=$(echo "$proof_payload" | jq -r .signature)
                    
                    if [ "$reporter_id" != "$reported_node_id" ]; then
                        warn "[PoUW-Verify] 交易 ${tx_hash:0:12} 无效：报告者与证明所有者不符。/ Invalid tx ${tx_hash:0:12}: Reporter does not match proof owner."
                        continue
                    fi

                    local data_to_verify
                    data_to_verify="$(echo "$proof_payload" | jq -r '.node_id, .start_timestamp, .end_timestamp' | tr '\n' '|' | sed 's/|$//')"
                    local reporter_pubkey_file=$(_get_identity_pubkey "$reporter_id")
                    if ! verify_signature "$data_to_verify" "$proof_sig" "$reporter_pubkey_file"; then
                        warn "[PoUW-Verify] 交易 ${tx_hash:0:12} 无效：主证明签名无效。/ Invalid tx ${tx_hash:0:12}: Main proof signature is invalid."
                        continue
                    fi

                    local required_peers valid_peer_sigs=0
                    required_peers=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT param_value FROM system_params WHERE param_key = 'pouw_validation_peers_required';")
                    required_peers=${required_peers:-3}
                    
                    local proof_hash
                    proof_hash=$(_internal_hash_text "$proof_payload")

                    declare -A validators_in_this_report=()
                    for sig_obj_b64 in $(echo "$peer_signatures" | jq -r '.[] | @base64'); do
                        local sig_obj=$(echo "$sig_obj_b64" | base64 -d)
                        local validator_id validation_sig
                        validator_id=$(echo "$sig_obj" | jq -r .validator_id)
                        validation_sig=$(echo "$sig_obj" | jq -r .signature)

                        [ -n "${validators_in_this_report[$validator_id]:-}" ] && continue
                        
                        local validator_pubkey_file=$(_get_identity_pubkey "$validator_id")
                        if [ -n "$validator_pubkey_file" ] && verify_signature "$proof_hash" "$validation_sig" "$validator_pubkey_file"; then
                            local prev_validation=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT COUNT(*) FROM pouw_validation_log WHERE validator_id = %s AND proof_hash = %s;" "$validator_id" "$proof_hash")
                            if [ "$prev_validation" -eq 0 ]; then
                                valid_peer_sigs=$((valid_peer_sigs + 1))
                                validators_in_this_report["$validator_id"]=1
                            fi
                        fi
                    done

                    if [ "$valid_peer_sigs" -lt "$required_peers" ]; then
                        warn "[PoUW-Verify] 交易 ${tx_hash:0:12} 无效：有效的同行签名数量不足 (${valid_peer_sigs}/${required_peers})。/ Invalid tx ${tx_hash:0:12}: Insufficient valid peer signatures (${valid_peer_sigs}/${required_peers})."
                        continue
                    fi

                    local reward_amount
                    reward_amount=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT param_value FROM system_params WHERE param_key = 'pouw_points_per_day_uptime';")
                    reward_amount=${reward_amount:-100}

                    db_execute_safe "$BLOCKCHAIN_DB" \
                        "INSERT INTO contribution_ledger (node_id, points, last_updated_height) VALUES (%s, %d, %d) ON CONFLICT(node_id) DO UPDATE SET points = points + %d, last_updated_height = %d;" \
                        "$reporter_id" "$reward_amount" "$height" "$reward_amount" "$height"

                    for validator_id in "${!validators_in_this_report[@]}"; do
                        db_execute_safe "$BLOCKCHAIN_DB" "INSERT INTO pouw_validation_log (validator_id, proof_hash, block_height) VALUES (%s, %s, %d);" "$validator_id" "$proof_hash" "$height"
                    done
                    
                    info "[PoUW] 已为节点 ${reporter_id:0:16}... 发放 ${reward_amount} 贡献分。/ Granted ${reward_amount} contribution points to node ${reporter_id:0:16}..."
                    ;;

                # --- NEW CASE BRANCH for Slashing Reports ---
                # --- Slashing 报告的新 case 分支 ---
                "slashing_report_double_sign")
                    local reporter_id="$sender_id"
                    local header1=$(echo "$tx_payload" | jq -c .header1)
                    local header2=$(echo "$tx_payload" | jq -c .header2)

                    local validator1=$(echo "$header1" | jq -r .validator)
                    local validator2=$(echo "$header2" | jq -r .validator)
                    local height1=$(echo "$header1" | jq -r .height)
                    local height2=$(echo "$header2" | jq -r .height)
                    local sig1=$(echo "$header1" | jq -r .signature)
                    local sig2=$(echo "$header2" | jq -r .signature)

                    if [ "$validator1" != "$validator2" ] || [ "$height1" != "$height2" ]; then continue; fi
                    
                    local offender_id="$validator1"
                    local offender_status=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT status FROM validators WHERE public_key_hash = %s;" "$offender_id")
                    [ "$offender_status" = "jailed" ] && continue
                    
                    local hash1=$(_internal_hash_text "$(echo "$header1" | jq -c 'del(.signature)')")
                    local hash2=$(_internal_hash_text "$(echo "$header2" | jq -c 'del(.signature)')")
                    [ "$hash1" = "$hash2" ] && continue

                    local offender_pubkey_file=$(_get_identity_pubkey "$offender_id")
                    if ! verify_signature "$(echo "$header1" | jq -c 'del(.signature)')" "$sig1" "$offender_pubkey_file" || ! verify_signature "$(echo "$header2" | jq -c 'del(.signature)')" "$sig2" "$offender_pubkey_file"; then
                        continue
                    fi

                    msg "[SLASHER] 检测到双签行为！正在惩罚验证者 ${offender_id:0:16}... / Double-signing detected! Slashing validator ${offender_id:0:16}..."
                    
                    local penalty_percent=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT param_value FROM system_params WHERE param_key = 'slashing_double_sign_penalty_percent';")
                    local current_stake=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT stake FROM validators WHERE public_key_hash = %s;" "$offender_id")
                    local penalty_amount=$(( (current_stake * penalty_percent) / 100 ))

                    local reporter_reward_percent=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT param_value FROM system_params WHERE param_key = 'slashing_report_reward_percent';")
                    local reporter_reward=$(( (penalty_amount * reporter_reward_percent) / 100 ))

                    db_execute_safe "$BLOCKCHAIN_DB" "UPDATE validators SET stake = stake - %d WHERE public_key_hash = %s;" "$penalty_amount" "$offender_id"
                    db_execute_safe "$BLOCKCHAIN_DB" "UPDATE contribution_ledger SET points = points + %d WHERE node_id = %s;" "$reporter_reward" "$reporter_id"

                    local jailing_duration=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT param_value FROM system_params WHERE param_key = 'slashing_jailing_duration_blocks';")
                    local jailed_until=$((height + jailing_duration))
                    db_execute_safe "$BLOCKCHAIN_DB" "UPDATE validators SET status = 'jailed', jailed_until_height = %d WHERE public_key_hash = %s;" "$jailed_until" "$offender_id"

                    info "[SLASHER] ${offender_id:0:12} 被扣除 ${penalty_amount} 质押并被监禁。/ ${offender_id:0:12} was slashed ${penalty_amount} stake and jailed."
                    ;;
                "trust_endorse")
                local endorsee_id endorsement_type signature
                endorsee_id=$(echo "$tx_payload" | jq -r .endorsee_id)
                endorsement_type=$(echo "$tx_payload" | jq -r .type)
                signature=$(echo "$tx_payload" | jq -r .signature)

                # 状态转换：将背书记录写入数据库
                # State Transition: Write the endorsement record to the database
                db_execute_safe "$FORUM_DB" \
                    "INSERT OR IGNORE INTO trust_endorsements (endorser_id, endorsee_id, endorsement_type, signature, tx_hash, block_height) VALUES (%s, %s, %s, %s, %s, %d);" \
                    "$sender_id" "$endorsee_id" "$endorsement_type" "$signature" "$tx_hash" "$height"
                    ;;
                # --- [V105.6 HEARTBEAT] Handle node directory transactions ---
                # --- [V105.6 心跳] 处理节点目录交易 ---
                "node_announce")
                    local p2p_addrs_json; p2p_addrs_json=$(echo "$tx_payload" | jq -c .p2p_addresses)
                    db_execute_safe "$BLOCKCHAIN_DB" \
                        "INSERT OR IGNORE INTO node_directory (node_id, owner_id, p2p_addresses, last_heartbeat_height, first_seen_height) VALUES (%s, %s, %s, %d, %d);" \
                        "$sender_id" "$sender_id" "$p2p_addrs_json" "$height" "$height"
                    ;;
                "node_heartbeat")
                    db_execute_safe "$BLOCKCHAIN_DB" \
                        "UPDATE node_directory SET last_heartbeat_height = %d WHERE node_id = %s;" \
                        "$height" "$sender_id"
                    ;;
                *)
                    # This is the entry point for 3rd-generation App Templates.
                    # 这是第三代应用模板的入口点。
                    _handle_dynamic_application_transaction "$tx_type" "$tx_payload" "$tx_hash" "$sender_id" "$height"
                    # We do not add to the event queue here, as the dynamic handler is responsible for its own events.
                    # 我们不在这里添加事件到队列，因为动态处理器负责其自身的事件。
                    continue # Skip to the next transaction in the 'while' loop. / 跳到 'while' 循环的下一个交易。
                    ;;
            esac

            # --- 步骤 2: 将事件放入队列 (集束化核心) ---
            # --- Step 2: Enqueue the event (Core of the batching) ---
            # We encode the event data into a single, parsable string. Base64 is perfect for this.
            # 我们将事件数据编码成一个单一的、可解析的字符串。Base64非常适合这个任务。
            local event_payload_b64
            event_payload_b64=$(echo "$tx_payload" | base64 -w0)
            _EVENT_QUEUE_FOR_THIS_BATCH+=("${tx_type}|${tx_hash}|${event_payload_b64}")

        done # --- End of transaction processing loop ---

        # --- [收尾工作] ---
        # --- [FINISHING UP] ---

        # 处理最后一个区块到链顶之间的所有区块级事件
        # Process block-level events for the last block up to the chain tip
        for (( h = current_processing_height < 0 ? 0 : current_processing_height; h <= current_chain_height; h++ )); do
             detail "[状态机] 正在处理区块 ${h} 的区块级事件... / [State Engine] Processing block-level events for block ${h}..."
            # _resolve_proofs_and_challenges_at_height is called by _process_onchain_events_at_height
            # _nns_tally_auction_at_height is called by _process_onchain_events_at_height 
            _protocol_tally_votes_and_schedule_changes "$h"
            # _protocol_execute_scheduled_changes is called by _process_onchain_events_at_height
            # _group_tally_owner_votes_at_height is called by _process_onchain_events_at_height
            # _group_tally_admin_votes_at_height is called by _process_onchain_events_at_height
            _process_onchain_events_at_height "$h"
        done
        
        # _begin_db_transaction 设置了 trap '...' ERR，如果上面的管道块失败，会自动回滚。
        # 如果管道成功执行到这里，我们就可以安全地提交。
        # _begin_db_transaction sets up a trap '...' ERR, which will auto-rollback if the pipe block above fails.
        # If the pipe succeeds and we reach here, it's safe to commit.
        
        # [V86 事务强化] 成功处理完所有事务后，提交所有数据库变更
        # [V86 TX Hardening] After successfully processing all txs, commit all DB changes
        db_execute_safe "$BLOCKCHAIN_DB" "UPDATE validators SET last_block=COALESCE((SELECT MAX(B.height) FROM blocks B WHERE B.validator=validators.public_key_hash),last_block);" || return 1
        db_execute_safe "$BLOCKCHAIN_DB" "INSERT OR REPLACE INTO chain_state (key, value) VALUES ('last_processed_height', %d);" "$current_chain_height"
        _commit_db_transaction "$FORUM_DB" "$BLOCKCHAIN_DB" "$DHT_DB"
        
        # --- 步骤 3: 统一的、集束化的事件分发 ---
        # --- Step 3: Unified, Batched Event Dispatch ---
        # After all database transactions are safely committed, we process the event queue.
        # 在所有数据库事务都被安全地提交后，我们再来处理事件队列。
        if [ "${CORIUM_REPLAY:-0}" != 1 ] && [ ${#_EVENT_QUEUE_FOR_THIS_BATCH[@]} -gt 0 ]; then
            info "[Agent-Dispatch] 正在分发 ${#_EVENT_QUEUE_FOR_THIS_BATCH[@]} 个已处理的事件... / Dispatching ${#_EVENT_QUEUE_FOR_THIS_BATCH[@]} processed events..."
            for event_data in "${_EVENT_QUEUE_FOR_THIS_BATCH[@]}"; do
                local event_name tx_hash event_payload_b64 tx_payload
                IFS='|' read -r event_name tx_hash event_payload_b64 <<< "$event_data"
                tx_payload=$(echo "$event_payload_b64" | base64 -d)
                
                # Call the dispatcher for each event.
                # 为每个事件调用分发器。
                _internal_agent_event_dispatch "$event_name" "$tx_hash" "$tx_payload"
            done
        fi
        
        info "[状态机] 成功处理至区块 ${current_chain_height}。/ [State Engine] Successfully processed up to block ${current_chain_height}."
    } < <(db_query_safe "$BLOCKCHAIN_DB" "
        SELECT json_array(T.hash, T.type, T.data, T.public_key, B.timestamp, B.height)
        FROM blocks AS B JOIN json_each(B.transactions) AS J
        JOIN transactions AS T ON T.hash = J.value
        WHERE B.height > %d AND B.height <= %d
        ORDER BY B.height ASC, CAST(J.key AS INTEGER) ASC;
    " "$last_processed_height" "$current_chain_height")
}

# =======================================================
# --- [V98 TRUST] 信任管理命令行 (Trust Management CLI) ---
# =======================================================

usage_trust() {
    echo "corix trust: Manage the on-chain Web of Trust."
    echo "corix trust: 管理链上的信任网络。"
    echo
    echo "Usage: corix trust <subcommand> [arguments...]"
    echo
    echo "Subcommands:"
    echo "  endorse <user_id>    Sign and endorse another user's identity."
    echo "                         (签名并背书另一个用户的身份)"
    echo "  show <user_id>       Show who has endorsed a specific user."
    echo "                         (显示谁为一个指定的用户进行了背书)"
}

corix_trust() {
    acquire_lock "network"
    trap 'release_lock "network"' RETURN

    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        endorse)
            [ $# -ne 1 ] && { usage_trust; exit 1; }
            local endorsee_id="$1"

            # 使用被背书者的ID作为被签名的数据
            # Use the endorsee's ID as the data to be signed
            local signature
            signature=$(sign_data "$endorsee_id" "$USER_IDENTITY_FILE")
            
            local tx_data
            tx_data=$(jq -n --arg eid "$endorsee_id" --arg type "identity" --arg sig "$signature" '{endorsee_id: $eid, type: $type, signature: $sig}')
            
            info "正在提交对用户 ${endorsee_id:0:16}... 的身份背书交易... / Submitting identity endorsement transaction for user ${endorsee_id:0:16}..."
            blockchain_create_transaction "trust_endorse" "$tx_data"
            ;;

        show)
            [ $# -ne 1 ] && { usage_trust; exit 1; }
            local user_id="$1"
            _update_chain_state_cache >/dev/null 2>&1
            
            msg "为用户 ${user_id:0:16}... 找到的背书: / Endorsements found for user ${user_id:0:16}...:"
            local endorsements
            endorsements=$(db_query_safe "$FORUM_DB" "SELECT endorser_id, endorsement_type FROM trust_endorsements WHERE endorsee_id = %s;" "$user_id")
            
            if [ -z "$endorsements" ]; then
                info "  (无) / (None)"
            else
                while IFS='|' read -r endorser_id type; do
                    echo "  - 由 $(_get_identity_nickname "$endorser_id") (${endorser_id:0:16}...) 背书 (类型: ${type})"
                    echo "    Endorsed by $(_get_identity_nickname "$endorser_id") (${endorser_id:0:16}...) (type: ${type})"
                done <<< "$endorsements"
            fi
            ;;
        *)
            usage_trust
            ;;
    esac
}


# =======================================================================================
# --- [IBC V1.1] 内置的默克尔证明验证器 (BUILT-IN MERKLE PROOF VERIFIER)             ---
# =======================================================================================
# This function verifies that a given transaction hash is included in a block header's
# transaction Merkle root, using a provided list of sibling hashes.
#
# 此函数使用一个给定的“兄弟哈希”列表，来验证一个交易哈希确实被包含在
# 某个区块头的交易默克尔树根中。
#
# @param $1 - final_header_json (The JSON of the final block header containing the root hash)
#             (包含了根哈希的最终区块头的JSON)
# @param $2 - merkle_proof_json (The JSON object containing the Merkle proof)
#             (包含了默克尔证明的JSON对象)
# @return 0 on successful verification, 1 on failure.
#         验证成功返回 0，失败返回 1。
_internal_verify_merkle_proof() {
    [ $# -eq 2 ] || return 1
    _internal_ibc_codec merkle "$1" "$2"
}

# =======================================================================================
# --- [IBC V1] 内置的“哈希链”证明验证器 (BUILT-IN "HASH-CHAIN" PROOF VERIFIER)        ---
# =======================================================================================
# The legacy hash-chain-v1 registry identifier now accepts CHECKPOINT_V2 proofs.
# Governance must supply a trusted block hash at or after the transaction block.
# Verifying descendants of an older anchor would require a separate consensus
# proof; a previous_hash link alone cannot authenticate a new block.
_internal_verify_hash_chain_proof() {
    [ $# -eq 2 ] || return 1
    local anchor
    anchor=$(db_query_safe "$BLOCKCHAIN_DB" \
        "SELECT last_known_header_hash FROM ibc_verifiers WHERE target_chain_id = %s AND is_active = 1;" "$1") || return 1
    _internal_ibc_codec verify "$2" "$anchor" "$CORIUM_NETWORK_ID"
}

