# =======================================================================================
# --- [IBC V1.1] 中继者证明数据格式指南 (Relayer Proof Data Format Guide)             ---
# =======================================================================================
usage_ibc_proof_format() {
cat <<'EOF'
Corium IBC proof format: CORIUM_IBC_CHECKPOINT_V2

proof_data fields:
  format: "CORIUM_IBC_CHECKPOINT_V2"
  final_header: height, hash, previous_hash, timestamp, transactions,
                transactions_root, validator, signature
  header_chain: newer blocks in descending height order, leading from a
                governance-trusted checkpoint back to final_header
  merkle_proof: target_tx_hash and siblings ({hash, position: left|right})
  source_transaction: exact signed/hashed transaction payload as a JSON string

The block hash commits to {height,previous_hash,timestamp,transactions} in that
order with compact JSON. transactions_root is computed separately by SHA-256
pairing and duplicating an odd final node; an empty block uses SHA-256("").

The trusted checkpoint must be final_header.hash or a newer supplied block hash.
Its ancestor links authenticate the historical final block and transaction list.
The source transaction must be ibc_dispatch and bind the destination network,
message_type and message_payload. Merkle root and source_tx_hash must also match.

The legacy BUILT_IN:hash-chain-v1 identifier remains registered, but old proof
objects are rejected. Proofs do not advance the checkpoint. Governance must
update checkpoints independently; validators' consensus is not inferred from
an unauthenticated chain of descendants.
EOF
}

# --- IBC 与 Agent 内部辅助函数 ---
_internal_ibc_dispatch() {
    local target_chain="$1" msg_type="$2" payload="$3"
    local tx_data; tx_data=$(jq -n --arg tc "$target_chain" --arg mt "$msg_type" --argjson mp "$payload" \
        '{target_chain_id:$tc, message_type:$mt, message_payload:$mp}')
    info "正在提交 IBC 分发交易 (类型: ${msg_type})... / Submitting IBC dispatch transaction (type: ${msg_type})..."
    blockchain_create_transaction "ibc_dispatch" "$tx_data"
}

# [Redundant function, to be deleted]
_execute_agent() {
    local agent_pkg_id="$1" agent_id="$2"
    local executable_path; executable_path=$(_get_mod_executable_path "$agent_pkg_id")
    [ -z "$executable_path" ] && return 1

    export CORIUM_AGENT_ID="$agent_id"
    export CORIUM_AGENT_PRIVATE_KEY_PATH="${VAR_LIB_CORIUM_DIR}/agent_keys/${agent_id}.key" 
    
    local exit_code=0
    _execute_mod_in_sandbox "$agent_pkg_id" "onchain_agent" "$executable_path" || exit_code=$?
    
    unset CORIUM_AGENT_ID CORIUM_AGENT_PRIVATE_KEY_PATH
    return $exit_code
}

# --- IBC 主分发器 ---
_internal_ibc_generate_state_proof() {
    [ $# -eq 3 ] && [[ "$1" =~ ^[0-9]{1,10}$ && "$3" =~ ^[a-f0-9]{64}$ ]] || return 1
    case "$2" in contribution_score|nns_record|group_membership) ;; *) return 1 ;; esac
    local replay_dir database
    replay_dir=$(mktemp -d -p "$BUILD_TMP_DIR_BASE" "state-proof.XXXXXX") || return 1
    CORIUM_TEMP_ITEMS+=("$replay_dir")
    _internal_replay_chain_state "$1" "$replay_dir" || return 1
    database="$replay_dir/forum.db"
    [ "$2" != contribution_score ] || database="$replay_dir/chain.db"
    _corix_get_state_prover_source > "$replay_dir/prover.py" || return 1
    CORIUM_NETWORK_ID="$CORIUM_NETWORK_ID" "${PYTHON_CMD}" "$replay_dir/prover.py" --db-path "$database" --height "$1" --asset-type "$2" --owner-id "$3"
}

corix_ibc() {
    acquire_lock "network"; trap 'release_lock "network"' RETURN
    local sub_cmd="${1:-}"; shift || true
    case "$sub_cmd" in
        msg)
            [ $# -lt 3 ] && { usage_ibc; exit 1; }
            local target_chain="$1" recipient="$2" body=""
            shift 2
            while [ $# -gt 0 ]; do
                case "$1" in
                    --body) [ $# -ge 2 ] || return 1; body="$2"; shift 2 ;;
                    *) return 1 ;;
                esac
            done
            [ -z "$body" ] && body=$(cat)
            local payload; payload=$(jq -n --arg to "$recipient" --arg body "$body" '{recipient:$to, body:$body}')
            _internal_ibc_dispatch "$target_chain" "IBC_TEXT_MESSAGE" "$payload"
            ;;
        get-build)
            [ $# -ne 2 ] && { usage_ibc; exit 1; }
            local target_chain="$1" pkg_id="$2"
            local payload; payload=$(jq -n --arg pid "$pkg_id" '{pkg_id:$pid}')
            _internal_ibc_dispatch "$target_chain" "IBC_REQUEST_BUILD" "$payload"
            ;;
        generate-state-proof)
            local height="" asset_type="" owner_id=""
            while [ $# -gt 0 ]; do
                case "$1" in
                    --height) height="$2"; shift 2;;
                    --asset-type) asset_type="$2"; shift 2;;
                    --owner-id) owner_id="$2"; shift 2;;
                    *) error "未知选项 / Unknown option: '$1'";;
                esac
            done
            [ -z "$height" ] || [ -z "$asset_type" ] || [ -z "$owner_id" ] && { usage_ibc; exit 1; }
            
            # 直接调用我们新实现的、依赖外部工具的内部函数
            # Directly call our newly implemented internal function that relies on the external tool
            _internal_ibc_generate_state_proof "$height" "$asset_type" "$owner_id"
            ;;

        redeem)
            [ $# -ne 2 ] && { usage_ibc; exit 1; }
            local target_chain="$1"
            local proof_file="$2"
            
            [ ! -f "$proof_file" ] && { error "证明文件未找到 / Proof file not found: $proof_file"; exit 1; }

            local proof_json=$(cat "$proof_file")
            local source_chain=$(echo "$proof_json" | jq -r .source_chain)
            
            local tx_data; tx_data=$(jq -n --arg sc "$source_chain" --argjson p "$proof_json" \
                '{source_chain_id: $sc, state_proof: $p}')
            
            _apply_theme "warn" "警告：您即将向网络 '${target_chain}' 提交资产赎回交易。/ WARNING: You are about to submit an asset redemption transaction to the '${target_chain}' network."
            read -rp "请确认操作 [y/N] / Please confirm [y/N] " choice
            [[ ! "$choice" =~ ^[yY] ]] && { msg "操作已取消。 / Operation cancelled."; return 0; }
            
            CORIUM_NETWORK_ID_OVERRIDE="$target_chain" blockchain_create_transaction "ibc_emergency_redeem" "$tx_data"
            ;;
        transfer-nns)
            [ $# -ne 2 ] && { usage_ibc; exit 1; }
            local domain_at_source="$1"
            local new_owner_at_target="$2"
            
            local domain="${domain_at_source%@*}"
            local source_chain="${domain_at_source#*@}"
            local new_owner="${new_owner_at_target%@*}"
            local target_chain="${new_owner_at_target#*@}"

            # 构造 IBC 消息的 payload
            # Construct the payload for the IBC message
            local payload; payload=$(jq -n --arg d "$domain" --arg no "$new_owner" '{domain_name:$d, new_owner_id:$no}')
            
            # 使用正确的网络ID上下文来创建 "ibc_dispatch" 交易
            # Use the correct network ID context to create the "ibc_dispatch" transaction
            CORIUM_NETWORK_ID_OVERRIDE="$source_chain" _internal_ibc_dispatch "$target_chain" "IBC_NNS_TRANSFER" "$payload"
            ;;
        *) usage_ibc ;;
    esac
}

# =======================================================================================
# --- [V95+CBB Game] usage_ceasefire (已扩展游戏功能)                               ---
# --- [V95+CBB Game] usage_ceasefire (Extended with Game Functionality)             ---
# =======================================================================================
usage_ceasefire() {
