# =======================================================================================
# --- [V95+CBB Game] corix_ceasefire (已扩展游戏功能)                               ---
# --- [V95+CBB Game] corix_ceasefire (Extended with Game Functionality)             ---
# =======================================================================================
corix_ceasefire() {
    acquire_lock "network"
    trap 'release_lock "network"' RETURN
    
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        read)
            _cbb_prune_expired # 在读取前，先清理过期的旧消息 / Before reading, prune expired old messages
            _apply_theme "primary" "停机公告板 (仅显示24小时内消息) / Ceasefire Bulletin Board (showing messages from the last 24 hours):"
            echo "--------------------------------------------------------------------------------"
            db_query_static "$FORUM_DB" "SELECT author_id, timestamp, message FROM cbb_messages ORDER BY timestamp DESC;" | while IFS='|' read -r author_id timestamp message; do
                # 过滤掉游戏消息，让read保持纯净 / Filter out game messages to keep 'read' clean
                if [[ "$message" != GAME:* ]]; then
                    echo -e "\033[1;33m发件人 / From:\033[0m $(_get_identity_nickname "$author_id") (${author_id:0:16}...)"
                    echo -e "\033[0;36m时间 / Time:  \033[0m $(date -d "@$timestamp")"
                    echo
                    echo "$message" | sed 's/^/  /'
                    echo "--------------------------------------------------------------------------------"
                fi
            done
            ;;
        post)
            local body=""
            if [ "${1:-}" = "--body" ]; then
                body="$2"
            else
                _apply_theme "info" "请输入您的紧急公告 (按 Ctrl+D 结束): / Please enter your emergency message (Press Ctrl+D to end):"
                body=$(cat)
            fi
            
            [ -z "$body" ] && { _apply_theme "error" "错误: 消息内容不能为空。/ Error: Message body cannot be empty."; return 1; }

            _cbb_post_and_broadcast "$body"
            ;;
        sync)
            _cbb_sync_messages
            ;;
        
        # --- [CBB Game] 游戏命令分发器 / Game Command Dispatcher ---
        game)
            local game_cmd="${1:-}"
            shift || true
            case "$game_cmd" in
                list)
                    _apply_theme "primary" "正在进行的 CBB 游戏 / Active CBB Games:"
                    # 扫描所有 NEW 消息，并检查它们的最新状态 / Scan all NEW messages and check their latest status
                    db_query_static "$FORUM_DB" "SELECT message FROM cbb_messages WHERE message LIKE 'GAME:TICTACTOE|ID:%|ACTION:NEW%';" | while IFS= read -r msg; do
                        local game_id=$(echo "$msg" | cut -d'|' -f2 | cut -d':' -f2)
                        local state=$(_cbb_game_get_state "$game_id")
                        local status=$(echo "$state" | cut -d'|' -f5)
                        if [[ "$status" == "ACTIVE" || "$status" == "WAITING" ]]; then
                            local player_x=$(echo "$state" | cut -d'|' -f1)
                            local player_o=$(echo "$state" | cut -d'|' -f2)
                            echo "  - ID: ${game_id}"
                            echo "    状态 / Status: ${status}"
                            echo "    玩家 / Players: $(_get_identity_nickname "$player_x") (X) vs $(_get_identity_nickname "${player_o:-<waiting>}") (O)"
                        fi
                    done
                    ;;
                new)
                    local my_id=$(get_our_node_id)
                    local invite_id=""
                    [ "${1:-}" = "--invite" ] && invite_id="$2"
                    local game_id="game-$(random_bytes 8)" # 生成一个随机游戏ID / Generate a random game ID
                    local payload="${my_id},${invite_id}"
                    _cbb_post_and_broadcast "GAME:TICTACTOE|ID:${game_id}|ACTION:NEW|PAYLOAD:${payload}"
                    _apply_theme "success" "✅ 游戏已创建！/ Game created!"
                    _apply_theme "info" "游戏ID / Game ID: ${game_id}"
                    [ -n "$invite_id" ] && _apply_theme "info" "已邀请 / Invited: $(_get_identity_nickname "$invite_id")" || _apply_theme "info" "正在等待对手加入... / Waiting for an opponent to join..."
                    ;;
                view)
                    [ $# -ne 1 ] && { usage_ceasefire; exit 1; }
                    local game_id="$1"
                    local state=$(_cbb_game_get_state "$game_id")
                    local player_x=$(echo "$state" | cut -d'|' -f1); local player_o=$(echo "$state" | cut -d'|' -f2); local board=$(echo "$state" | cut -d'|' -f3); local turn=$(echo "$state" | cut -d'|' -f4); local status=$(echo "$state" | cut -d'|' -f5)
                    
                    if [ "$status" = "NOT_FOUND" ]; then _apply_theme "error" "错误: 找不到游戏 '${game_id}'。/ Error: Game '${game_id}' not found."; exit 1; fi
                    
                    echo "--- 游戏状态 / Game Status: ${game_id} ---"
                    _cbb_game_render_board "$board"
                    echo "玩家X / Player X: $(_get_identity_nickname "$player_x")"
                    echo "玩家O / Player O: $(_get_identity_nickname "${player_o:-<waiting...>}")"
                    
                    case "$status" in
                        WAITING) _apply_theme "warn" "状态: 正在等待玩家O加入... / Status: Waiting for Player O to join..." ;;
                        ACTIVE) _apply_theme "primary" "状态: 轮到 ${turn} (${turn}的回合) / Status: It's ${turn}'s turn" ;;
                        WIN_X) _apply_theme "success" "游戏结束! 玩家X (${player_x:0:12}...) 胜利! / Game Over! Player X (${player_x:0:12}...) wins!" ;;
                        WIN_O) _apply_theme "success" "游戏结束! 玩家O (${player_o:0:12}...) 胜利! / Game Over! Player O (${player_o:0:12}...) wins!" ;;
                        DRAW) _apply_theme "info" "游戏结束! 平局。/ Game Over! It's a draw." ;;
                    esac
                    ;;
                move)
                    [ $# -ne 2 ] && { usage_ceasefire; exit 1; }
                    local game_id="$1"; local position="$2"; local my_id=$(get_our_node_id)
                    local state=$(_cbb_game_get_state "$game_id"); local turn=$(echo "$state" | cut -d'|' -f4); local status=$(echo "$state" | cut -d'|' -f5); local player_x=$(echo "$state" | cut -d'|' -f1); local player_o=$(echo "$state" | cut -d'|' -f2); local board=$(echo "$state" | cut -d'|' -f3)

                    if [ "$status" != "ACTIVE" ]; then _apply_theme "error" "错误: 游戏未处于可进行状态。 / Error: Game is not in an active state."; exit 1; fi
                    if ([ "$turn" = "X" ] && [ "$my_id" != "$player_x" ]) || ([ "$turn" = "O" ] && [ "$my_id" != "$player_o" ]); then _apply_theme "error" "错误: 现在不是您的回合。/ Error: It is not your turn."; exit 1; fi
                    if ! [[ "$position" =~ ^[1-9]$ ]]; then _apply_theme "error" "错误: 位置必须是 1-9 之间的一个数字。/ Error: Position must be a number between 1-9."; exit 1; fi
                    if [ "${board:$((position-1)):1}" != "-" ]; then _apply_theme "error" "错误: 该位置已被占据。/ Error: That position is already taken."; exit 1; fi
                    
                    _cbb_post_and_broadcast "GAME:TICTACTOE|ID:${game_id}|ACTION:MOVE|PAYLOAD:${turn},${position}"
                    _apply_theme "success" "✅ 您已在位置 ${position} 走棋。正在等待对手... / Move made at position ${position}. Waiting for opponent..."
                    ;;
                join)
                    [ $# -ne 1 ] && { usage_ceasefire; exit 1; }
                    local game_id="$1"; local my_id=$(get_our_node_id)
                    local state=$(_cbb_game_get_state "$game_id")
                    if [ "$(echo "$state" | cut -d'|' -f5)" != "WAITING" ]; then _apply_theme "error" "错误: 无法加入该游戏。/ Error: Cannot join this game."; exit 1; fi
                    
                    _cbb_post_and_broadcast "GAME:TICTACTOE|ID:${game_id}|ACTION:JOIN|PAYLOAD:${my_id}"
                    _apply_theme "success" "✅ 您已成功加入游戏! / Successfully joined the game!"
                    ;;
                forfeit)
                    [ $# -ne 1 ] && { usage_ceasefire; exit 1; }
                    local game_id="$1"; local my_id=$(get_our_node_id)
                    _cbb_post_and_broadcast "GAME:TICTACTOE|ID:${game_id}|ACTION:FORFEIT|PAYLOAD:${my_id}"
                    _apply_theme "warn" "您已认输。 / You have forfeited the game."
                    ;;
                *)
                    usage_ceasefire ;;
            esac
            ;;

        *)
            usage_ceasefire
            ;;
    esac
}

_cbb_post_and_broadcast() {
    local message="$1"
    local my_id timestamp expires_at data_to_sign signature msg_hash network_id
    my_id=$(get_our_node_id)
    timestamp=$(date +%s)
    expires_at=$((timestamp + 86400))
    network_id="${CORIUM_NETWORK_ID:-mainnet}"

    [ -n "$message" ] && [ "${#message}" -le 65536 ] && [ "$(printf '%s' "$message" | wc -c)" -le 65536 ] || return 1
    data_to_sign="CORIUM-CBB-V1
${network_id}
${my_id}
${timestamp}
${message}"
    signature=$(sign_data "$data_to_sign" "$USER_IDENTITY_FILE") || return 1
    msg_hash=$(_internal_hash_text "$data_to_sign")

    db_execute_safe "$FORUM_DB" \
        "INSERT OR IGNORE INTO cbb_messages (msg_hash, author_id, timestamp, message, signature, expires_at) VALUES (%s, %s, %d, %s, %s, %d);" \
        "$msg_hash" "$my_id" "$timestamp" "$message" "$signature" "$expires_at" || return 1

    local payload
    payload=$(jq -n --arg author "$my_id" --arg ts "$timestamp" --arg msg "$message" --arg sig "$signature" \
        '{author_id: $author, timestamp: $ts, message: $msg, signature: $sig}')

    _apply_theme "info" "正在向网络广播紧急公告... / Broadcasting emergency message to the network..."
    local peers pid failed=0
    local pids=()
    peers=$(dht_find_closest_nodes "$my_id" 10) || peers="" # 广播给10个最近的节点
    while IFS= read -r node_addr_string; do
        _parse_full_address "$node_addr_string" || continue; local node_id="$ADDR_NODE_ID"
        [ -n "$node_id" ] || continue
        dht_send_message "$node_id" "CBB_POST" "$payload" >/dev/null 2>&1 &
        pids+=("$!")
    done <<< "$peers"
    for pid in "${pids[@]}"; do wait "$pid" || failed=1; done
    [ "$failed" -eq 0 ] || { warn "公告已保存在本地，但广播失败。/ Message saved locally; broadcast failed."; return 1; }
    
    _apply_theme "success" "紧急公告已发布并广播。/ Emergency message posted and broadcast."
}

_cbb_prune_expired() {
    db_execute_safe "$FORUM_DB" "DELETE FROM cbb_messages WHERE expires_at <= %d;" "$(date +%s)"
}

_cbb_sync_messages() {
    _apply_theme "info" "正在向网络请求同步紧急公告... / Requesting emergency message sync from the network..."
    local my_id=$(get_our_node_id)
    local peers
    peers=$(dht_find_closest_nodes "$my_id" 5) # 向5个最近的节点请求
    
    local pids=()
    while IFS= read -r node_addr_string; do
        ( # 在子 shell 中并行执行以提速
            _parse_full_address "$node_addr_string" || continue; local node_id="$ADDR_NODE_ID"
            [ -z "$node_id" ] && exit
            
            # 请求对方节点的所有 CBB 消息
            local response
            response=$(dht_send_message "$node_id" "CBB_SYNC_REQUEST" "") || exit 1
            jq -e 'type=="array" and all(.[];type=="object")' <<< "$response" >/dev/null || exit 1
            if [ -n "$response" ]; then
                # 收到 JSON 数组后，将每一条消息都通过 ANNOUNCE_SSPO 广播给自己
                # 这样可以复用 Python 守护进程中已有的、健壮的验证和入库逻辑
                for row in $(echo "$response" | jq -r '.[] | @base64'); do
                    dht_send_message "$my_id" "CBB_POST" "$(echo "$row" | base64 -d)" >/dev/null 2>&1 || exit 1
                done
            fi
        ) &
        pids+=($!)
    done <<< "$peers"
    local sync_pid sync_failed=0
    for sync_pid in "${pids[@]}"; do wait "$sync_pid" || sync_failed=1; done
    [ "$sync_failed" -eq 0 ] || return 1
    
    _apply_theme "success" "紧急公告同步完成。/ Emergency message sync complete."
}


# --- Agent 主分发器 ---
corix_agent() {
    acquire_lock "network"; trap 'release_lock "network"' RETURN
    local sub_cmd="${1:-}"; shift || true
    case "$sub_cmd" in
        create)
            [ $# -ne 1 ] && { usage_agent; exit 1; }
            local pkg_id="$1"
            
            local agent_key_dir="${VAR_LIB_CORIUM_DIR}/agent_keys"; mkdir -p "$agent_key_dir"
            local tmp_key=$(mktemp); local tmp_pub="${tmp_key}.pub"
            generate_keypair "$tmp_key" "$tmp_pub"
            local agent_pubkey=$(cat "$tmp_pub")
            local agent_id=$(_internal_hash_text "$agent_pubkey")
            
            local agent_priv_key="${agent_key_dir}/${agent_id}.key"; local agent_pub_key="${agent_priv_key}.pub"
            mv "$tmp_key" "$agent_priv_key"
            mv "$tmp_pub" "$agent_pub_key"
            
            local tx_data; tx_data=$(jq -n --arg pid "$pkg_id" --arg pub "$agent_pubkey" --arg aid "$agent_id" '{pkg_id:$pid, agent_pubkey:$pub, agent_id:$aid}')
            info "正在提交创建链上 Agent 的交易... / Submitting transaction to create On-Chain Agent..."
            blockchain_create_transaction "agent_create" "$tx_data"
            ;;
        list)
            msg "本链已注册的链上 Agent / On-Chain Agents Registered on This Chain:"
            db_query_static "$BLOCKCHAIN_DB" "SELECT agent_id, owner_id, pkg_id FROM onchain_identities;" | while IFS='|' read -r aid oid pid; do
                echo "  - Agent ID: ${aid}"
                echo "    Owner:    ${oid}"
                echo "    Pkg ID:   ${pid}"
            done
            ;;
        endow)
            [ $# -lt 2 ] && { usage_agent; exit 1; }
            local agent_id="$1"
            local amount="$2"
            local purpose=""

            # (可选) 解析 --purpose 参数
            # (Optional) Parse the --purpose argument
            if [ "${3:-}" = "--purpose" ]; then
                purpose="${4:-}"
            fi

            # --- 防投机设计：用户意图确认 ---
            # --- Anti-Speculation Design: User Intent Confirmation ---
            warn "您即将进行一次贡献分赋予操作。/ You are about to perform a contribution score endowment."
            echo "--------------------------------------------------"
            _apply_theme "info" "  接收 Agent / Recipient Agent: ${agent_id}"
            _apply_theme "info" "  赋予数量 / Amount to Endow:   ${amount}"
            if [ -n "$purpose" ]; then
            _apply_theme "info" "  声明用途 / Declared Purpose:  ${purpose}"
            fi
            echo "--------------------------------------------------"
            _apply_theme "warn" "请注意：贡献分代表您在网络中的声誉和治理权。/ Please note: Contribution score represents your reputation and governance power in the network."
            _apply_theme "warn" "此操作是一次性的、不可逆的资本委托，而非金融交易。/ This action is a one-way, irreversible delegation of capital, not a financial transaction."
            
            read -rp "您理解并确认要继续吗？[y/N] / Do you understand and confirm to proceed? [y/N] " choice
            [[ ! "$choice" =~ ^[yY] ]] && { msg "操作已取消。/ Operation cancelled."; return 0; }

            # 构造交易载荷
            # Construct the transaction payload
            local tx_data
            tx_data=$(jq -n \
                --arg aid "$agent_id" \
                --argjson amt "$amount" \
                --arg p "$purpose" \
                '{agent_id: $aid, amount: $amt, purpose: $p}')
            
            info "正在提交贡献分赋予交易... / Submitting contribution score endowment transaction..."
            local tx_hash; tx_hash=$(blockchain_create_transaction "endow_agent" "$tx_data")

            if [ -n "$tx_hash" ]; then
                msg "贡献分已成功赋予。/ Contribution score endowed successfully."
                info "  交易哈希 / Transaction Hash: ${tx_hash}"
            else
                error "操作失败。/ Operation failed."
            fi
            ;;
        call)
            local use_cbb=0; local agent_id=""; local payload_json=""
            while [ $# -gt 0 ]; do
                case "$1" in
                    --cbb|--emergency) use_cbb=1; shift ;;
                    *) if [ -z "$agent_id" ]; then agent_id="$1"; else payload_json="$1"; fi; shift ;;
                esac
            done
            [ -z "$agent_id" ] || [ -z "$payload_json" ] && { usage_agent; return 1; }

            if [ "$use_cbb" -eq 1 ]; then
                warn "[AGENT-CBB] 正在通过 CBB 发送紧急 Agent 任务... / Sending emergency agent task via CBB..."
                local my_id signature unsigned_task
                my_id=$(get_our_node_id)
                unsigned_task=$(jq -ncS --arg aid "$agent_id" --argjson p "$payload_json" --arg pid "$my_id" '{type:"AGENT_EMERGENCY_TASK",target_agent_id:$aid,task_payload:$p,proposer_id:$pid}') || return 1
                signature=$(sign_data "$unsigned_task" "$USER_IDENTITY_FILE") || return 1
                
                # CBB 消息的载荷，是另一个 P2P 消息的完整 JSON
                # The payload of the CBB message is the full JSON of another P2P message
                local agent_task_p2p_msg
                agent_task_p2p_msg=$(jq -n --arg aid "$agent_id" --argjson p "$payload_json" --arg pid "$my_id" --arg sig "$signature" \
                    '{type: "AGENT_EMERGENCY_TASK", target_agent_id: $aid, task_payload: $p, proposer_id: $pid, signature: $sig}')
                
                # 将这个 P2P 消息作为 CBB 消息的正文来广播
                # Broadcast this P2P message as the body of a CBB message
                _cbb_post_and_broadcast "$agent_task_p2p_msg"
            else
                info "正在发起常规 Agent 调用... / Initiating regular Agent call..."
                local my_id
                my_id=$(get_our_node_id)
                local timestamp
                timestamp=$(date +%s)
                local expires_at=$((timestamp + 300))
                local nonce=$RANDOM
                
                # Canonical data for signature
                local data_to_sign="CORIUM-AGENT-CALL-V1
${agent_id}
${my_id}
${payload_json}
${nonce}
${timestamp}"
                local signature
                signature=$(sign_data "$data_to_sign" "$USER_IDENTITY_FILE")
                
                local agent_call_msg
                agent_call_msg=$(jq -n --arg protocol "CORIUM_AGENT_CALL_V1" --arg aid "$agent_id" --arg cid "$my_id" --argjson p "$payload_json" --arg nonce "$nonce" --arg ts "$timestamp" --arg exp "$expires_at" --arg sig "$signature"                     '{protocol: $protocol, target_agent_id: $aid, caller_id: $cid, payload: $p, nonce: $nonce, created_at: ($ts|tonumber), expires_at: ($exp|tonumber), signature: $sig}')
                
                # 发送给本地守护进程（或可通过 P2P 路由到目标节点，这里为了原型直接发给自己本地）
                # (Send to local daemon or route via P2P. Here we send to local for prototype)
                local response
                response=$(dht_send_message "$my_id" "AGENT_REGULAR_CALL" "$agent_call_msg")
                if [ $? -eq 0 ]; then
                    msg "Agent 调用成功！/ Agent call succeeded!"
                    echo "$response" | jq .
                else
                    error "Agent 调用失败。/ Agent call failed."
                    echo "$response"
                fi
            fi
            ;;
        *) usage_agent ;;
    esac
}

# =======================================================================================
# --- [V95 Phoenix Protocol] 核心状态导出引擎 (最终版)                          ---
# --- [V95 Phoenix Protocol] Core State Export Engine (Final Version)             ---
# =======================================================================================
# 此函数查询指定区块高度的完整应用层和共识层状态，并将其序列化为一个
# 可用于启动新链的、符合规范的 genesis.json 文件。
# This function queries the full application and consensus state at a specific block
# height and serializes it into a spec-compliant genesis.json file suitable for
# bootstrapping a new chain.
#
# @param $1 - height (要导出状态的区块高度 / The block height of the state to export)
# @param $2 - output_file (生成的 genesis.json 的输出路径 / Output path for the generated genesis.json)
# @param $3 - new_validators_str (可选，逗号分隔的新验证者公钥列表 / Optional, comma-separated list of new validator public keys)
# Replay the accepted canonical history into independent databases and object metadata.
# 在独立数据库中从恢复锚点重放，不使用当前节点的派生状态或安装记录。
_internal_replay_chain_state() (
    set -e
    local -A CORIUM_DB_TX_BACKUPS=() CORIUM_DB_TX_DEPTH=() CORIUM_DB_TX_OWNERS=()
    local -a CORIUM_ACTIVE_DB_TRANSACTIONS=()
    local height="$1" replay_dir="$2" source_chain="$BLOCKCHAIN_DB"
    local BLOCKCHAIN_DB="$replay_dir/chain.db" FORUM_DB="$replay_dir/forum.db"
    local DHT_DB="$replay_dir/dht.db" INSTALLED_DB="$replay_dir/installed"
    local FORUM_DIR="$replay_dir/forum" FORUM_OBJECTS_DIR="$replay_dir/forum/objects"
    local FORUM_MANIFESTS_DIR="$replay_dir/forum/manifests" FORUM_PUBKEYS_DIR="$replay_dir/forum/pubkeys"
    local VAR_LIB_CORIUM_DIR="$replay_dir" DAPP_DATA_DIR="$replay_dir/dapp_data" MOD_DATA_DIR="$replay_dir/mod_data"
    local CORIUM_REPLAY=1
    mkdir -p "$replay_dir" "$INSTALLED_DB" "$DAPP_DATA_DIR" "$MOD_DATA_DIR"
    _init_blockchain_db; _init_app_db; _init_dht_db; forum_init
    # Immutable objects are shared by hash; local discovery records are only retrieval aids.
    "${PYTHON_CMD}" - "$source_chain" "$BLOCKCHAIN_DB" "$height" "$DHT_DB" "${CORIUM_ROOT%/}/var/lib/corix/p2p/dht.db" <<'PY_HISTORY'
import sqlite3, sys, json, pathlib
source = sqlite3.connect(pathlib.Path(sys.argv[1]).resolve().as_uri()+'?mode=ro', uri=True)
target = sqlite3.connect(sys.argv[2]); height = int(sys.argv[3])
blocks = source.execute('SELECT * FROM blocks WHERE height <= ? ORDER BY height', (height,)).fetchall()
if not blocks or [b[0] for b in blocks] != list(range(height+1)): raise ValueError('Missing canonical history')
seen = set()
with target:
    for b in blocks:
        if b[0] and b[2] != blocks[b[0]-1][1]: raise ValueError('Broken parent link')
        txs = json.loads(b[6])
        if not isinstance(txs,list) or len(txs)!=len(set(txs)): raise ValueError('Duplicate or malformed transaction list')
        target.execute('INSERT INTO blocks VALUES (?,?,?,?,?,?,?,?)', b)
        if source.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='block_work'").fetchone():
            proof=source.execute('SELECT proof FROM block_work WHERE hash=?',(b[1],)).fetchone()
            if proof:target.execute('INSERT INTO block_work VALUES(?,?)',(b[1],proof[0]))
        for txhash in txs:
            if txhash in seen: raise ValueError('Replayed canonical transaction')
            seen.add(txhash)
            tx = source.execute('SELECT * FROM transactions WHERE hash=? AND block_height=?',(txhash,b[0])).fetchone()
            if tx is None: raise ValueError('Missing transaction or inconsistent block binding')
            target.execute('INSERT INTO transactions VALUES (?,?,?,?,?,?,?)',tx)
with target:
    target.executemany('INSERT OR REPLACE INTO chain_state VALUES (?,?)',source.execute("SELECT key,value FROM chain_state WHERE key='core_gpg_authority'"))
source.close(); target.close()
if pathlib.Path(sys.argv[5]).exists():
    with sqlite3.connect(sys.argv[5]) as lookup, sqlite3.connect(sys.argv[4]) as replay:
        replay.executemany('INSERT OR REPLACE INTO local_chunks VALUES (?,?,?,?)', lookup.execute('SELECT * FROM local_chunks'))
PY_HISTORY
    # Seed the original genesis assets while retaining the copied canonical genesis row.
    local genesis_row
    genesis_row=$(db_query_static "$BLOCKCHAIN_DB" "SELECT json_array(height,hash,previous_hash,timestamp,validator,signature,transactions,total_weight) FROM blocks WHERE height=0;")
    local later_blocks="$replay_dir/later_blocks.json"
    "${PYTHON_CMD}" - "$BLOCKCHAIN_DB" "$later_blocks" <<'PY_SAVE_BLOCKS'
import sqlite3,sys,json
with sqlite3.connect(sys.argv[1]) as db:
    rows=db.execute('SELECT * FROM blocks WHERE height>0 ORDER BY height').fetchall()
    open(sys.argv[2],'w').write(json.dumps(rows))
    db.execute('DELETE FROM blocks')
PY_SAVE_BLOCKS
    db_execute_safe "$BLOCKCHAIN_DB" "UPDATE transactions SET block_height=NULL;" || return 1
    blockchain_create_genesis_block || return 1
    local expected_genesis_hash
    expected_genesis_hash=$(db_query_static "$BLOCKCHAIN_DB" "SELECT hash FROM blocks WHERE height=0;") || return 1
    [ "$expected_genesis_hash" = "$(jq -r '.[1]' <<< "$genesis_row")" ] || return 1
    _update_chain_state_cache || return 1
    local block_row bh hash previous timestamp validator signature transactions weight parent_weight=0 parent_time=0 pubfile body txhash
    local -A replay_validations=()
    while IFS= read -r block_row; do
        bh=$(jq -er '.[0]' <<< "$block_row") || return 1
        hash=$(jq -er '.[1]' <<< "$block_row") || return 1
        previous=$(jq -er '.[2]' <<< "$block_row") || return 1
        timestamp=$(jq -er '.[3]' <<< "$block_row") || return 1
        validator=$(jq -er '.[4]' <<< "$block_row") || return 1
        signature=$(jq -er '.[5]' <<< "$block_row") || return 1
        transactions=$(jq -ec '.[6]|fromjson' <<< "$block_row") || return 1
        weight=$(jq -er '.[7]' <<< "$block_row") || return 1
        [[ "$timestamp" =~ ^[0-9]{1,16}$ ]] && [ "$timestamp" -ge "$parent_time" ] || return 1
        body="{\"height\":$bh,\"previous_hash\":\"$previous\",\"timestamp\":$timestamp,\"transactions\":$transactions}"
        _protocol_execute_scheduled_changes "$bh" || return 1
        _slashing_check_for_jailed_validators "$bh" || return 1
        local replay_work_mode replay_work_proof replay_work_block replay_work_check
        replay_work_mode=$(_corium_work_consensus mode "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$bh" | jq -er .mode) || return 1
        if [ "$replay_work_mode" = pow-v2 ]; then
            replay_work_proof=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT proof FROM block_work WHERE hash=%s;" "$hash") || return 1
            replay_work_block=$(jq -cn --argjson row "$block_row" --argjson work "$replay_work_proof" '{height:$row[0],previous_hash:$row[2],timestamp:$row[3],validator:$row[4],signature:$row[5],transactions:($row[6]|fromjson),work:$work}') || return 1
            replay_work_check=$(_corium_work_consensus verify "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$replay_work_block" "$hash") || return 1
            [ "$weight" = "$(jq -er .total_weight <<< "$replay_work_check")" ] || return 1
        else
            [ -z "$(db_query_safe "$BLOCKCHAIN_DB" "SELECT proof FROM block_work WHERE hash=%s;" "$hash")" ] || return 1
            [ "$(_internal_hash_text "$body")" = "$hash" ] || return 1
            pubfile=$(_blockchain_get_validator_pubkey "$validator") || return 1
        verify_signature "$body" "$signature" "$pubfile" || return 1
        local stake
        stake=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT stake FROM validators WHERE public_key_hash=%s AND status='active';" "$validator") || return 1
        [[ "$stake" =~ ^[1-9][0-9]{0,18}$ ]] && [ "$stake" -le "$((9223372036854775807-parent_weight))" ] || return 1
        [ "$weight" -eq "$((parent_weight+stake))" ] || return 1
        fi
        local -A block_tracker=()
        while IFS= read -r txhash; do
            [ -n "$txhash" ] || continue
            _validate_single_transaction "$txhash" "" "" "$bh" block_tracker replay_validations || return 1
        done < <(jq -r '.[]' <<< "$transactions")
        db_execute_safe "$BLOCKCHAIN_DB" "INSERT INTO blocks VALUES (%d,%s,%s,%d,%s,%s,%s,%d);" "$bh" "$hash" "$previous" "$timestamp" "$validator" "$signature" "$transactions" "$weight" || return 1
        while IFS= read -r txhash; do
            [ -n "$txhash" ] || continue
            db_execute_safe "$BLOCKCHAIN_DB" "UPDATE transactions SET block_height=%d WHERE hash=%s;" "$bh" "$txhash" || return 1
        done < <(jq -r '.[]' <<< "$transactions")
        _update_chain_state_cache || return 1
        db_execute_safe "$BLOCKCHAIN_DB" "UPDATE validators SET last_block=%d WHERE public_key_hash=%s;" "$bh" "$validator" || return 1
        parent_weight="$weight"; parent_time="$timestamp"
    done < <(jq -c '.[]' "$later_blocks")

)

# Serialize named tables with complete type boundaries and stable row ordering.
# 对表名、字段、类型和行顺序作规范序列化，避免分隔符与插入顺序影响状态根。
_internal_semantic_state() {
    "${PYTHON_CMD}" - "$BLOCKCHAIN_DB" "$FORUM_DB" "$SCRIPT_PATH" <<'PY_STATE'
import sqlite3, json, sys, pathlib, re
state = {}
custom_schemas={}
builtin=set(re.findall(r'CREATE TABLE IF NOT EXISTS\s+([A-Za-z_][A-Za-z_0-9]*)',pathlib.Path(sys.argv[3]).read_text()))
def cell(value):
    return {'$corium_blob':value.hex()} if isinstance(value,bytes) else value
local_tables = {'subscriptions','aliases','local_user_blocks','objects','topics','posts','cbb_messages','exodus_proposals','exodus_notarizations','agent_emergency_queue'}
for label, path in zip(('chain','application'),sys.argv[1:3]):
    db = sqlite3.connect(pathlib.Path(path).resolve().as_uri()+'?mode=ro', uri=True)
    if db.execute('PRAGMA integrity_check').fetchall()!=[('ok',)]: raise ValueError('Corrupted state database')
    tables = {}
    for (table,) in db.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name"):
        if table in local_tables or table == 'staged_blocks': continue
        columns = [row[1] for row in db.execute('PRAGMA table_info("'+table.replace('"','""')+'")')]
        query = 'SELECT * FROM "'+table.replace('"','""')+'"'
        if table == 'transactions': query += ' WHERE block_height IS NOT NULL'
        if table == 'chain_state': query += " WHERE key='core_gpg_authority'"
        rows = [dict(zip(columns,map(cell,row))) for row in db.execute(query)]
        if table not in builtin:
            custom_schemas.setdefault(label,{})[table]=db.execute("SELECT sql FROM sqlite_master WHERE type='table' AND name=?",(table,)).fetchone()[0]
        if table == 'chain_state' and not rows: continue
        if table in ('messages','mails'):
            for row in rows:
                row.pop('is_read',None); row.pop('priority',None); row.pop('local_path',None)
        tables[table] = sorted(rows,key=lambda row: json.dumps(row,sort_keys=True,ensure_ascii=False,separators=(',',':')))
    state[label] = tables
    db.close()
if custom_schemas: state['_custom_schemas']=custom_schemas
print(json.dumps(state,sort_keys=True,ensure_ascii=False,separators=(',',':')))
PY_STATE
}

# Import the existing Phoenix V2 state only after validating its signed canonical root.
# 先验证签名、规范状态根与完整表结构，再原子恢复 Phoenix V2 状态。
_internal_import_phoenix_state() {
    _internal_consensus_safety_check || return 1
    [ $# -eq 1 ] || return 1
    db_begin_transaction "$BLOCKCHAIN_DB" "$FORUM_DB" || return 1
    if ! "${PYTHON_CMD}" - "$1" "$BLOCKCHAIN_DB" "$FORUM_DB" <<'PY_PHOENIX_IMPORT'
import json, sys, hashlib, sqlite3, re
from cryptography.hazmat.primitives.serialization import load_pem_public_key
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives import hashes

def unique(pairs):
    result={}
    for k,v in pairs:
        if k in result: raise ValueError('Duplicate JSON field')
        result[k]=v
    return result
with open(sys.argv[1],encoding='utf-8') as f: snapshot=json.load(f,object_pairs_hook=unique)
if snapshot.get('format')!='CORIUM_PHOENIX_GENESIS_V2': raise ValueError('Invalid snapshot format')
root=snapshot.pop('state_root'); signature=snapshot.pop('snapshot_signature')
canonical=json.dumps(snapshot,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()
if hashlib.sha256(canonical).hexdigest()!=root: raise ValueError('Snapshot state root mismatch')
pem=snapshot['snapshot_public_key']; key=load_pem_public_key(pem.encode())
if not isinstance(key,ec.EllipticCurvePublicKey) or not isinstance(key.curve,ec.SECP256K1): raise ValueError('Invalid snapshot key')
key.verify(bytes.fromhex(signature),root.encode(),ec.ECDSA(hashes.SHA256()))
state=snapshot['state']; chain=state['chain_tables']; application=state['application_tables']
custom_schemas=state.get('custom_schemas',{})
if not isinstance(custom_schemas,dict) or set(custom_schemas)-{'chain','application'}: raise ValueError('Invalid custom schemas')
def decoded(value):
    if isinstance(value,dict) and set(value)=={'$corium_blob'}: return bytes.fromhex(value['$corium_blob'])
    return value
identity=hashlib.sha256(pem.rstrip('\n').encode()).hexdigest()
if not any(v['public_key_hash']==identity and v['public_key'].rstrip('\n')==pem.rstrip('\n') for v in chain['validators']):
    raise ValueError('Snapshot signer is not a recovered validator')
anchor=snapshot['recovery_anchor']
if type(anchor['height']) is not int or anchor['height']<0 or not re.fullmatch('[a-f0-9]{64}',anchor['block_hash']): raise ValueError('Invalid recovery anchor')
# Validate all tables, field names and scalar types against the actual v108 schemas.
dbs=[sqlite3.connect(sys.argv[2]),sqlite3.connect(sys.argv[3])]
try:
    for label,db,tables in zip(('chain','application'),dbs,(chain,application)):
        schemas=custom_schemas.get(label,{})
        if not isinstance(schemas,dict): raise ValueError('Invalid custom schema mapping')
        for table,sql in schemas.items():
            if not re.fullmatch('[A-Za-z_][A-Za-z_0-9]*',table) or not isinstance(sql,str): raise ValueError('Invalid custom schema name')
            if not re.match(r'^CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?["`\[]?'+re.escape(table)+r'["`\]]?\s*\(',sql,re.I): raise ValueError('Invalid custom CREATE TABLE')
            if table not in tables: raise ValueError('Custom schema has no recovered table')
            existing=db.execute("SELECT sql FROM sqlite_master WHERE type='table' AND name=?",(table,)).fetchone()
            if existing and existing[0]!=sql: raise ValueError('Custom schema differs from recovered table')
            if not existing: db.execute(sql)
        available={r[0] for r in db.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")}
        if not isinstance(tables,dict): raise ValueError('Malformed recovered tables')
        excluded={'blocks','transactions','chain_state','staged_blocks'} if db is dbs[0] else {'subscriptions','aliases','local_user_blocks','objects','topics','posts','cbb_messages','exodus_proposals','exodus_notarizations','agent_emergency_queue'}
        optional={'chain_state'} if db is dbs[0] else set()
        if set(tables)-optional!=available-excluded: raise ValueError('Incomplete recovered tables: missing='+str(sorted((available-excluded)-(set(tables)-optional)))+', unexpected='+str(sorted((set(tables)-optional)-(available-excluded))))
        for table,rows in tables.items():
            if table not in available or table in ('blocks','transactions','staged_blocks'): raise ValueError('Unknown recovery table')
            if table=='chain_state' and (len(rows)!=1 or rows[0].get('key')!='core_gpg_authority'): raise ValueError('Invalid recovered protocol authority')
            fields={r[1]:r for r in db.execute('PRAGMA table_info("'+table+'")')}
            if not isinstance(rows,list): raise ValueError('Malformed recovery rows')
            for row in rows:
                if not isinstance(row,dict) or set(row)-set(fields): raise ValueError('Unknown recovery field')
                for name,info in fields.items():
                    if name not in row and info[3] and info[4] is None: raise ValueError('Missing required recovery field')
                for name,value in row.items():
                    kind=fields[name][2].upper()
                    if value is None:
                        if fields[name][3]: raise ValueError('NULL recovery field')
                    elif 'INT' in kind:
                        if type(value) is not int or not -2**63<=value<2**63: raise ValueError('Invalid recovery integer')
                    elif 'BLOB' in kind and isinstance(value,dict) and set(value)=={'$corium_blob'}:
                        if not isinstance(value['$corium_blob'],str) or not re.fullmatch('(?:[a-f0-9]{2})*',value['$corium_blob']): raise ValueError('Invalid recovery blob')
                    elif not isinstance(value,str): raise ValueError('Invalid recovery string')
    validators=snapshot['validators']; seen=set()
    if not isinstance(validators,list) or not validators: raise ValueError('Missing validators')
    for v in validators:
        public=v['public_key'].rstrip('\n'); validator=load_pem_public_key(public.encode())
        ident=hashlib.sha256(public.encode()).hexdigest()
        if not isinstance(validator,ec.EllipticCurvePublicKey) or not isinstance(validator.curve,ec.SECP256K1): raise ValueError('Invalid validator')
        if ident in seen or v.get('public_key_hash',ident)!=ident or type(v['stake']) is not int or not 0<=v['stake']<2**63: raise ValueError('Invalid validator binding or stake')
        validator_fields={r[1]:r[2].upper() for r in dbs[0].execute('PRAGMA table_info(validators)')}
        if set(v)-set(validator_fields): raise ValueError('Unknown validator field')
        for field,value in v.items():
            if 'INT' in validator_fields[field] and (type(value) is not int or not -2**63<=value<2**63): raise ValueError('Invalid validator integer')
            if 'INT' not in validator_fields[field] and not isinstance(value,str): raise ValueError('Invalid validator field type')
        seen.add(ident)
    if not any(v['stake']>0 for v in validators): raise ValueError('No staked recovery validator')
    # A single attached SQLite transaction updates both databases; snapshot backups
    # also allow rollback if a subsequent operation fails before the shell commit.
    dbs[1].close(); db=dbs[0]; db.execute('ATTACH DATABASE ? AS app',(sys.argv[3],)); db.execute('BEGIN IMMEDIATE')
    db.execute("DELETE FROM chain_state WHERE key='core_gpg_authority'")
    for label,tables in (('main',chain),('app',application)):
        for table,rows in tables.items():
            db.execute('DELETE FROM '+label+'."'+table+'"')
            for row in rows:
                if row:
                    fields=list(row)
                    db.execute('INSERT INTO '+label+'."'+table+'" ('+','.join('"'+n+'"' for n in fields)+') VALUES ('+','.join('?' for n in fields)+')',tuple(decoded(row[n]) for n in fields))
    db.execute('DELETE FROM validators')
    for v in validators:
        public=v['public_key'].rstrip('\n'); ident=hashlib.sha256(public.encode()).hexdigest()
        recovered=dict(v,public_key=public,public_key_hash=ident)
        fields=list(recovered)
        db.execute('INSERT INTO validators('+','.join('"'+f+'"' for f in fields)+') VALUES ('+','.join('?' for f in fields)+')',tuple(recovered[f] for f in fields))
    block=json.dumps({'height':0,'previous_hash':'0','timestamp':0,'transactions':[],'state_root':root},separators=(',',':'))
    genesis_hash=hashlib.sha256(block.encode()).hexdigest()
    db.execute('INSERT INTO blocks VALUES (0,?,\'0\',0,\'genesis_node\',?,\'[]\',0)',(genesis_hash,signature))
    db.execute("INSERT OR REPLACE INTO chain_state VALUES ('chain_info',?)",(genesis_hash+'|0',))
    db.execute("INSERT OR REPLACE INTO chain_state VALUES ('last_processed_height','0')")
    db.commit()
except BaseException:
    for db in dbs:
        try: db.rollback()
        except sqlite3.Error: pass
    raise
finally:
    for db in dbs:
        try: db.close()
        except sqlite3.Error: pass
PY_PHOENIX_IMPORT
    then
        db_rollback_transaction "$BLOCKCHAIN_DB" "$FORUM_DB"
        return 1
    fi
    db_commit_transaction "$BLOCKCHAIN_DB" "$FORUM_DB"
}

# Replace every chain-derived table with a fresh canonical replay while preserving
# local subscriptions, pending transactions and transport metadata.
# 用规范链重放重建派生状态，保留本地订阅、待确认交易和传输元数据。
_internal_rebuild_derived_state() {
    _internal_consensus_safety_check || return 1
    local replay_dir height
    height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT MAX(height) FROM blocks;") || return 1
    replay_dir=$(mktemp -d -p "$BUILD_TMP_DIR_BASE" "reorg-replay.XXXXXX") || return 1
    CORIUM_TEMP_ITEMS+=("$replay_dir")
    _internal_replay_chain_state "$height" "$replay_dir" || return 1
    ( BLOCKCHAIN_DB="$replay_dir/chain.db"; FORUM_DB="$replay_dir/forum.db"; _internal_semantic_state ) > "$replay_dir/state.json" || return 1
    "${PYTHON_CMD}" - "$replay_dir/state.json" "$BLOCKCHAIN_DB" "$FORUM_DB" "$height" <<'PY_REBUILD'
import sqlite3,json,sys
state=json.load(open(sys.argv[1])); db=sqlite3.connect(sys.argv[2]); db.execute('ATTACH DATABASE ? AS app',(sys.argv[3],))
def decoded(value):
    return bytes.fromhex(value['$corium_blob']) if isinstance(value,dict) and set(value)=={'$corium_blob'} else value
try:
    db.execute('BEGIN IMMEDIATE')
    for label,tables in (('main',state['chain']),('app',state['application'])):
        schemas=state.get('_custom_schemas',{}).get('chain' if label=='main' else 'application',{})
        for table,sql in schemas.items():
            existing=db.execute("SELECT sql FROM "+label+".sqlite_master WHERE type='table' AND name=?",(table,)).fetchone()
            if not existing: db.execute(sql if label=='main' else sql.replace('CREATE TABLE ', 'CREATE TABLE app.',1))
        for table,rows in tables.items():
            if table in ('blocks','transactions'): continue
            db.execute('DELETE FROM '+label+'."'+table+'"')
            for row in rows:
                fields=list(row)
                db.execute('INSERT INTO '+label+'."'+table+'" ('+','.join('"'+f+'"' for f in fields)+') VALUES ('+','.join('?' for f in fields)+')',tuple(decoded(row[f]) for f in fields))
    db.execute("INSERT OR REPLACE INTO chain_state VALUES ('last_processed_height',?)",(sys.argv[4],))
    tip=db.execute('SELECT hash,height FROM blocks ORDER BY height DESC LIMIT 1').fetchone()
    db.execute("INSERT OR REPLACE INTO chain_state VALUES ('chain_info',?)",(tip[0]+'|'+str(tip[1]),))
    db.commit()
except BaseException: db.rollback(); raise
finally: db.close()
PY_REBUILD
}

_internal_export_chain_state() {
    [ $# -eq 3 ] || return 1
    local height="$1" output_file="$2" new_validators_str="$3" replay_dir
    [[ "$height" =~ ^[0-9]{1,10}$ ]] || return 1
    height=$((10#$height))
    [ -d "$(dirname "$output_file")" ] || return 1
    acquire_lock "system"
    replay_dir=$(mktemp -d -p "$BUILD_TMP_DIR_BASE" "phoenix_replay.XXXXXX") || return 1
    CORIUM_TEMP_ITEMS+=("$replay_dir")
    _internal_replay_chain_state "$height" "$replay_dir" || return 1
    local state_file="$replay_dir/semantic.json"
    ( BLOCKCHAIN_DB="$replay_dir/chain.db"; FORUM_DB="$replay_dir/forum.db"; _internal_semantic_state ) > "$state_file" || return 1
    local staged_output
    staged_output=$(mktemp "${output_file}.XXXXXX") || return 1
    CORIUM_TEMP_ITEMS+=("$staged_output")
    "${PYTHON_CMD}" - "$state_file" "$GENESIS_CONFIG_FILE" "$height" "$new_validators_str" "$USER_PUBLIC_KEY_FILE" "$staged_output" <<'PY_PHOENIX_EXPORT'
import json, sys, hashlib, pathlib
from cryptography.hazmat.primitives.serialization import load_pem_public_key
from cryptography.hazmat.primitives.asymmetric import ec
state=json.loads(pathlib.Path(sys.argv[1]).read_text()); height=int(sys.argv[3])
chain=state['chain']; app=state['application']
validators=chain['validators']
if sys.argv[4]:
    keys=sys.argv[4].split(','); validators=[]; seen=set()
    for pem in keys:
        pem=pem.rstrip('\n'); key=load_pem_public_key(pem.encode())
        if not isinstance(key,ec.EllipticCurvePublicKey) or not isinstance(key.curve,ec.SECP256K1): raise ValueError('Invalid validator key')
        identity=hashlib.sha256(pem.encode()).hexdigest()
        if identity in seen: raise ValueError('Duplicate validator')
        seen.add(identity); validators.append({'public_key':pem,'public_key_hash':identity,'stake':1000})
if not validators: raise ValueError('No recovery validators')
result={'format':'CORIUM_PHOENIX_GENESIS_V2','validators':validators,
        'recovery_anchor':{'height':height,'block_hash':chain['blocks'][-1]['hash'] if chain['blocks'][-1]['height']==height else next(b['hash'] for b in chain['blocks'] if b['height']==height),'genesis':json.loads(pathlib.Path(sys.argv[2]).read_text())},
        'snapshot_public_key':pathlib.Path(sys.argv[5]).read_text().rstrip('\n'),
        'state':{'contribution_scores':chain['contribution_scores'],'nns_records':app['nns_records'],
                 'groups':[dict(id=r['id_hash'],nickname=r['nickname'],permissions=json.loads(r['permissions'])) for r in app['identity_cache'] if r['type']=='group'],
                 'acls':[dict(r,permissions=json.loads(r['permissions'])) for r in app['acl_state']],
                 'packages':[], 'chain_tables':{k:v for k,v in chain.items() if k not in ('blocks','transactions')}, 'application_tables':app}}
if state.get('_custom_schemas'): result['state']['custom_schemas']=state['_custom_schemas']
# Only canonical package registrations belong to the recovery history. Installed local packages do not.
for tx in sorted(chain['transactions'],key=lambda row:(row['block_height'],row['hash'])):
    if tx['type']=='package_register':
        data=json.loads(tx['data']); result['state']['packages'].append(data)
canonical=json.dumps(result,sort_keys=True,ensure_ascii=False,separators=(',',':'))
result['state_root']=hashlib.sha256(canonical.encode()).hexdigest()
pathlib.Path(sys.argv[6]).write_text(json.dumps(result,sort_keys=True,ensure_ascii=False,separators=(',',':')))
PY_PHOENIX_EXPORT
    [ $? -eq 0 ] || return 1
    local state_root signature
    state_root=$(jq -er .state_root "$staged_output") || return 1
    signature=$(sign_data "$state_root" "$USER_IDENTITY_FILE") || return 1
    jq -cS --arg sig "$signature" '.snapshot_signature=$sig' "$staged_output" > "$replay_dir/signed.json" || return 1
    cat "$replay_dir/signed.json" > "$staged_output" || return 1
    mv -f -- "$staged_output" "$output_file" || return 1
    msg "Phoenix 快照导出成功。/ Phoenix snapshot exported successfully."
    release_lock "system"
}


# The main function for the 'inbox' command and high-priority checks.
# 'inbox' 命令和高优先级检查的主函数。
_sync_and_display_messages() {
    _update_chain_state_cache
    
    msg "Your Inbox (unread messages): / 您的收件箱 (未读消息):"
    local unread_messages
    local block_clause=$(_get_blocked_users_sql_clause "messages" "sender_id")
    
    # --- [SQL 修改] 在 SELECT 列表中增加了 inline_content ---
    # --- [SQL MODIFICATION] Added inline_content to the SELECT list ---
    # --- [SQL & READ MODIFICATION] 增加了 encryption_mode ---
    # --- [SQL & READ MODIFICATION] Added encryption_mode ---
    unread_messages=$(db_query_static "$FORUM_DB" "SELECT tx_hash, sender_id, recipient_id, source_type, timestamp, content_hash, attachment_meta, inline_content, encryption_mode FROM messages WHERE is_read = 0 ${block_clause} ORDER BY timestamp DESC;")
    
    if [ -z "$unread_messages" ]; then
        info "No new messages. / 没有新消息。"
        return
    fi
    
    # --- [READ 修改] 在 read 命令中增加了 inline_content 变量 ---
    # --- [READ MODIFICATION] Added inline_content variable to the read command ---
    while IFS='|' read -r tx_hash sender_id recipient_id source_type timestamp content_hash attachment_meta inline_content encryption_mode; do
        local sender_name source_label
        sender_name=$(_get_identity_nickname "$sender_id")
        
        # ========================================================== --
        # --- [E2EE MODIFICATION START] 根据类型选择图标和标签     --- --
        # --- [E2EE MODIFICATION START] Choose icon and label by type --- --
        # ========================================================== --
        case "$source_type" in
            "DIRECT")
                icon="🔒"; source_label="[DIRECT] From: ${sender_name}" ;;
            "GROUP")
                icon="👥"; source_label="[GROUP: $(_get_identity_nickname "$recipient_id")] From: ${sender_name}" ;;
            "BROADCAST")
                icon="📢"; source_label="[BROADCAST: $(_get_identity_nickname "$recipient_id")] From: ${sender_name}" ;;
            "GRIEVANCE")
                icon="❗"; source_label="\033[1;35m[GRIEVANCE] From: ${sender_name}\033[1;33m" ;;
            *)
                icon="✉️"; source_label="[${source_type}] From: ${sender_name}" ;;
        esac
        
        echo "--------------------------------------------------"
        echo -e "${icon} \033[1;33m${source_label}\033[0m"
        echo "Date: $(date -d "@$timestamp" '+%Y-%m-%d %H:%M:%S') (ID: ${tx_hash:0:16}...)"
        echo "Content:"

        # ========================================================== --
        # --- [E2EE MODIFICATION START] 解密和渲染逻辑           --- --
        # --- [E2EE MODIFICATION START] Decryption and Render Logic --- --
        # ========================================================== --
        if [ "$encryption_mode" = "e2ee-v1" ]; then
            local encrypted_content_path="${FORUM_OBJECTS_DIR}/${content_hash}"
            if [ ! -f "$encrypted_content_path" ]; then
                forum_fetch_object "$content_hash" "$FORUM_OBJECTS_DIR" >/dev/null 2>&1
            fi
            
            if [ -f "$encrypted_content_path" ]; then
                local decrypted_payload
                decrypted_payload=$(_e2ee_decrypt_payload "$(cat "$encrypted_content_path")")
                local decrypted_body decrypted_attach_hash decrypted_attach_name
                decrypted_body=$(echo "$decrypted_payload" | jq -r .body)
                decrypted_attach_hash=$(echo "$decrypted_payload" | jq -r .attachment_hash)
                decrypted_attach_name=$(echo "$decrypted_payload" | jq -r .attachment_name)
                
                echo "$decrypted_body" | sed 's/^/  /'
                
                if [ -n "$decrypted_attach_hash" ] && [ "$decrypted_attach_hash" != "null" ]; then
                    echo -e "\n  \033[1;32mAttachment:\033[0m ${decrypted_attach_name}"
                    echo "    -> corix message get-attachment $tx_hash"
                fi
            else
                 echo "  [无法下载加密的消息内容 / Could not download encrypted message content]"
            fi
        else
            # Unencrypted messages (groups, broadcasts, grievances)
            # 未加密消息 (群组, 广播, 申诉)
            _render_message_content "$content_hash" "$inline_content" "  "
            if [ -n "$attachment_meta" ] && [ "$attachment_meta" != "null" ]; then
                local filename size=$(echo "$attachment_meta" | jq -r .size | numfmt --to=iec)
                filename=$(echo "$attachment_meta" | jq -r .filename)
                echo -e "\n  \033[1;32mAttachment:\033[0m ${filename} (${size})"
                echo "    -> corix message get-attachment $tx_hash"
            fi
        fi
            echo
        done <<< "$unread_messages"

        db_execute_safe "$FORUM_DB" "UPDATE messages SET is_read = 1 WHERE is_read = 0;"
}
    
# HIGH-PRIORITY MESSAGE BLOCKER. This runs before ANY command.
# 高优先级消息阻塞器。它在任何命令之前运行。
_check_high_priority_messages() {
    # Paths are already resolved by the dispatcher or isolated replay caller.
    # 路径由命令分发器或隔离重放调用者确定，不能在重放中切回当前节点。
    
    [ ! -t 1 ] && return 0

    # [Batch 5 FIX] Guard: skip if forum DB does not exist or has no messages table
    if [ ! -f "$FORUM_DB" ]; then
        return 0
    fi
    local has_messages_table
    has_messages_table=$(sqlite3 "$FORUM_DB" "SELECT name FROM sqlite_master WHERE type='table' AND name='messages';" 2>/dev/null || true)
    if [ -z "$has_messages_table" ]; then
        return 0
    fi

    _update_chain_state_cache

    local high_prio_msgs
    # [Batch 5 FIX] Query only from forum.db's messages table without cross-DB JOIN.
    # The transactions table is in blockchain.db, not forum.db.
    high_prio_msgs=$(sqlite3 "$FORUM_DB" "SELECT M.tx_hash, M.sender_id, M.source_type, M.timestamp, '', M.inline_content FROM messages M WHERE M.is_read = 0 AND M.priority = 'high' ORDER BY M.timestamp ASC;" 2>/dev/null || true)
    [ -z "$high_prio_msgs" ] && return 0

    echo -e "\n\033[1;31m--- URGENT: HIGH-PRIORITY MESSAGES REQUIRE YOUR ATTENTION ---"
    echo -e "--- 紧急: 您有高优先级消息需要处理 ---\033[0m"
    echo "You must acknowledge these messages before you can proceed."
    echo "在继续操作前，您必须确认这些消息。"
    
    # --- [READ 修改] 在 read 命令中增加了 inline_content 变量 ---
    # --- [READ MODIFICATION] Added inline_content variable to the read command ---
    while IFS='|' read -r tx_hash sender_id source_type timestamp tx_data inline_content; do
        echo "--------------------------------------------------"
        local subject="High-Priority Message"
        local from_label="FROM: [${source_type}] $(_get_identity_nickname "$sender_id")"
        if [ "$source_type" = "GRIEVANCE" ]; then
            subject="Grievance Message / 申诉消息"
            from_label="\033[1;35mFROM: [${source_type}] $(_get_identity_nickname "$sender_id")\033[0m"
        elif [ -n "$tx_data" ]; then
             subject="Governance Proposal / 治理提议"
        fi
        
        echo -e "$from_label"
        echo "SUBJECT: $subject"
        echo "ID: ${tx_hash}"

        # --- [逻辑修改] 使用统一渲染器或 jq 显示内容 ---
        # --- [LOGIC MODIFICATION] Use unified renderer or jq to display content ---
        echo "Content/Details:"
        if [ -n "$inline_content" ]; then
            _render_message_content "" "$inline_content" "  "
        elif [ -n "$tx_data" ]; then
            # 美化打印治理提案的详情
            # Pretty-print the details of the governance proposal
            echo "$tx_data" | jq -c . | sed 's/^/  /'
        else
            echo "  [No content available / 无可用内容]"
        fi

        read -rp "Acknowledge this message? [Y]es to continue, [Q]uit Corium session: / 确认此消息? [Y]es 继续, [Q]uit 退出 Corium 会话: " choice
        case "$choice" in
            [qQ]*)
                db_execute_safe "$FORUM_DB" "UPDATE messages SET is_read = 1 WHERE tx_hash = %s;" "$tx_hash"
                error "Session quit by user due to high-priority message. / 用户因高优先级消息退出会话。"
                ;;
            *)
                db_execute_safe "$FORUM_DB" "UPDATE messages SET is_read = 1 WHERE tx_hash = %s;" "$tx_hash"
                info "Message acknowledged. / 消息已确认。"
                ;;
        esac
    done <<< "$high_prio_msgs"
    
    echo -e "\033[1;32mAll high-priority messages handled. Proceeding... / 所有高优先级消息处理完毕。正在继续...\033[0m\n"
}


# =======================================================
# --- SECTION 23.8: NEW CLI FUNCTIONS (USER REQUEST)  ---
# --- 第23.8节: 新的 CLI 函数 (用户请求)              ---
# =======================================================

# =======================================================================================
# --- [批次三 新增] corix compute 主命令 (最终版)                                     ---
# --- [BATCH THREE NEW] corix compute Main Command (Final Version)                    ---
# =======================================================================================
# The user-facing command dispatcher for 'corix compute'.
# 'corix compute' 的用户侧命令分发器。
corix_compute() {
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        run)
            local specific_engine_id=""
            if [ "${1:-}" = "--engine" ]; then
                specific_engine_id="$2"
            fi
            _internal_compute_run "$specific_engine_id"
            ;;
        submit)
            [ $# -lt 1 ] && { _apply_theme "error" "用法: corix compute submit <proof_file_path> / Usage: corix compute submit <proof_file_path>"; exit 1; }
            _internal_compute_submit "$1"
            ;;
        status)
            _internal_compute_status
            ;;
        *)
            _apply_theme "primary" "corix compute: 参与“有用功证明”共识 / Participate in 'Proof of Useful Work' consensus"
            echo
            _apply_theme "info" "用法: corix compute <子命令> [参数...] / Usage: corix compute <subcommand> [arguments...]"
            echo
            _apply_theme "accent" "子命令 / Subcommands:"
            _apply_theme "primary" "  run [--engine <engine_id>] - 获取并执行计算任务。可指定引擎，否则将交互式选择。"
            _apply_theme "info"    "                             - Fetch and execute a computation task. Specify an engine, or choose interactively."
            _apply_theme "primary" "  submit <proof_file>        - 提交一个已完成的计算证明 / Submit a completed computation proof."
            _apply_theme "primary" "  status                     - 显示您当前的贡献分和状态 / Display your current contribution score and status."
            ;;
    esac
}


# =======================================================================================
# --- [批次三 新增] 'compute run' 的核心逻辑 (V62.5 - 最终修复版)                     ---
# --- [BATCH THREE NEW] Core Logic for 'compute run' (V62.5 - Final Corrected Version) ---
# =======================================================================================
_internal_compute_run() {
    local specific_engine_id="$1"
    
    msg "正在获取当前可用的网络计算任务... / Fetching available network computation tasks..."
    
    local -a available_tasks=()
    mapfile -t available_tasks < <(_get_current_compute_task "$specific_engine_id")

    if [ ${#available_tasks[@]} -eq 0 ]; then
        error "无法获取计算任务。网络可能暂时没有可用的任务。 / Failed to get computation task. The network may not have an available task at the moment."
        return 1
    fi

    local selected_task=""
    if [ -n "$specific_engine_id" ]; then
        for task in "${available_tasks[@]}"; do
            if [[ "$task" == "${specific_engine_id}|"* ]]; then
                selected_task="$task"
                break
            fi
        done
        if [ -z "$selected_task" ]; then
            error "指定的引擎ID '${specific_engine_id}' 不是一个当前激活的任务。 / Specified engine ID '${specific_engine_id}' is not a currently active task."
            return 1
        fi
    elif [ ${#available_tasks[@]} -eq 1 ]; then
        selected_task="${available_tasks[0]}"
    else
        # --- [V86 新增] 交互式任务选择菜单 ---
        info "发现多个可用的计算任务。请选择一个来运行： / Multiple computation tasks available. Please select one to run:"
        local i=1
        for task in "${available_tasks[@]}"; do
            local engine_id desc
            IFS='|' read -r engine_id _ _ _ _ desc <<< "$task"
            echo "  [${i}] ${engine_id} - ${desc}"
            i=$((i+1))
        done
        
        local choice
        read -rp "输入您的选择 (1-${#available_tasks[@]}): / Enter your choice (1-${#available_tasks[@]}): " choice
        if [[ "$choice" =~ ^[0-9]+$ ]] && [ "$choice" -gt 0 ] && [ "$choice" -le ${#available_tasks[@]} ]; then
            selected_task="${available_tasks[$((choice-1))]}"
        else
            error "无效的选择。操作已取消。 / Invalid selection. Operation cancelled."
            return 1
        fi
    fi

    local engine_id problem_id task_data compute_hash verifier_hash
    if [[ "$selected_task" == corium/internal-engine-zero-v1\|* ]]; then
        local zero_target zero_difficulty
        IFS='|' read -r engine_id problem_id zero_target zero_difficulty compute_hash verifier_hash _ <<< "$selected_task"
        task_data="${zero_target}|${zero_difficulty}"
    else
        IFS='|' read -r engine_id problem_id task_data compute_hash verifier_hash _ <<< "$selected_task"
    fi

    _apply_theme "info" "任务已获取 / Task Acquired:"
    _apply_theme "accent" "  引擎ID / Engine ID:   ${engine_id}"
    _apply_theme "accent" "  问题ID / Problem ID:  ${problem_id}"
    _apply_theme "accent" "  任务数据 / Task Data: ${task_data}"
    echo

    local native_package
    native_package=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT pkg_id FROM compute_engines WHERE engine_id=%s;" "$engine_id")
    if [ "$native_package" = corium/built-in-gimps ]; then
        local proof_file="proof-gimps-${problem_id}-${RANDOM}.json" proof_document
        proof_document=$(_corium_gimps_consensus solve "$BLOCKCHAIN_DB" "$CORIUM_NETWORK_ID" "$engine_id" "$problem_id" "$(get_our_node_id)") || return 1
        printf '%s\n' "$proof_document" | "${PYTHON_CMD:-python3}" -c 'import os,sys; fd=os.open(sys.argv[1],os.O_WRONLY|os.O_CREAT|os.O_EXCL|getattr(os,"O_NOFOLLOW",0),0o600); f=os.fdopen(fd,"w"); f.write(sys.stdin.read()); f.close()' "$proof_file" || return 1
        msg "GIMPS native proof: $proof_file; submit with corix compute submit $proof_file"
        return 0
    fi

    if [[ "$compute_hash" == "BUILT_IN" ]]; then
        # --- 场景 A: 执行内置的“零号引擎”（哈希挑战） ---
        # --- Scenario A: Execute the built-in "Engine Zero" (Hash Challenge) ---
        msg "正在执行协议内置的哈希挑战... / Executing protocol-integrated hash challenge..."
        
        local target_hash difficulty
        IFS='|' read -r target_hash difficulty <<< "$task_data"
        
        local leading_zeros
        leading_zeros=$(printf "%0*d" "$difficulty" 0)

        local nonce=0
        local start_time=$(date +%s)
        
        local my_id=$(get_our_node_id)
        local network_id="${CORIUM_NETWORK_ID:-mainnet}"
        
        while true; do
            local current_hash
            current_hash=$(echo -n "${network_id}${my_id}${nonce}${target_hash}" | sha256sum | awk '{print $1}')

            if [[ "${current_hash}" == ${leading_zeros}* ]]; then
                local end_time=$(date +%s)
                _apply_theme "success" "✅ 成功！在 $((end_time - start_time)) 秒后找到有效 Nonce！ / Success! Found a valid nonce after $((end_time - start_time)) seconds!"
                _apply_theme "info" "  Nonce: ${nonce}"
                _apply_theme "info" "  哈希 / Hash: ${current_hash}"
                
                # 创建 proof 文件
                # Create the proof file
                local proof_file="proof-${problem_id:0:12}.json"
                # [Batch 4] Bind Engine Zero proof to the proposer's ID and Network ID to prevent cross-chain replay
                local my_id=$(get_our_node_id)
                local network_id="${CORIUM_NETWORK_ID:-mainnet}"
                
                jq -n \
                    --arg eid "$engine_id" \
                    --arg pid "$problem_id" \
                    --arg td "$task_data" \
                    --arg pd_nonce "$nonce" \
                    --arg sub "$my_id" \
                    --arg net "$network_id" \
                    '{
                        "engine_id": $eid,
                        "problem_id": $pid,
                        "task_data": $td,
                        "proof_data": {
                            "nonce": $pd_nonce,
                            "submitter_id": $sub,
                            "network_id": $net
                        }
                    }' > "$proof_file"
                
                echo
                _apply_theme "primary" "计算证明已保存到 / Computation proof has been saved to: ${proof_file}"
                _apply_theme "info" "现在，您可以使用 'corix compute submit ${proof_file}' 来提交您的贡献。 / You can now submit your contribution using 'corix compute submit ${proof_file}'."
                break
            fi
            
            # 增加 nonce 并提供进度反馈
            # Increment nonce and provide progress feedback
            nonce=$((nonce + 1))
            if (( nonce % 100000 == 0 )); then
                echo -ne "  -> 正在尝试 Nonce / Trying Nonce: ${nonce}\r" >&2
            fi
        done
        
    else
        # --- 场景 B: 执行基于 Mod 的计算任务 ---
        # --- Scenario B: Execute a Mod-based computation task ---
        msg "正在准备基于 Mod 的计算环境... / Preparing Mod-based computation environment..."

        # --- [核心修复] 从链上状态获取 engine_id 对应的 pkg_id ---
        # --- [CORE FIX] Get the pkg_id for the engine_id from the on-chain state ---
        local pkg_id
        pkg_id=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT pkg_id FROM compute_engines WHERE engine_id = %s;" "$engine_id")
        
        if [[ -z "$pkg_id" ]]; then
            error "致命状态错误：在数据库中找不到引擎 '${engine_id}' 对应的软件包ID (pkg_id)。 / FATAL STATE ERROR: Could not find package ID (pkg_id) for engine '${engine_id}' in the database."
            return 1
        fi
        
        _apply_theme "info" "正在为软件包 / Preparing to run for package: ${pkg_id}"

        # 2. 从 P2P 网络下载计算程序 Mod
        # 2. Download the compute program Mod from the P2P network
        local compute_mod_path
        compute_mod_path=$(mktemp -d)/compute_mod
        
        _apply_theme "info" "正在下载计算程序 (哈希: ${compute_hash:0:12})... / Downloading compute program (hash: ${compute_hash:0:12})..."
        if ! _download_file_p2p "$compute_hash" "$compute_mod_path"; then
            error "无法下载计算程序 Mod。 / Failed to download the compute program Mod."
            return 1
        fi
        chmod +x "$compute_mod_path"

        # 3. 在沙箱中执行计算 Mod
        # 3. Execute the compute Mod in a sandbox
        msg "正在沙箱中启动计算... 这可能需要很长时间。 / Starting computation in sandbox... This may take a long time."
        
        # --- [核心修复] 现在我们将正确的 pkg_id 传递给沙箱执行引擎 ---
        # --- [CORE FIX] We now pass the correct pkg_id to the sandbox execution engine ---
        if ! _execute_mod_in_sandbox "$pkg_id" "contribution_compute" "$compute_mod_path" "$task_data"; then
             error "计算 Mod 执行失败或返回了错误。 / The compute Mod failed or returned an error."
             return 1
        fi
        
        _apply_theme "success" "✅ 计算 Mod 执行完成！ / Compute Mod execution finished!"
        _apply_theme "info" "请检查 Mod 生成的证明文件，然后使用 'corix compute submit' 提交。 / Please check for the proof file generated by the Mod, then submit it with 'corix compute submit'."
    fi
}

# =======================================================================================
# --- [批次三 新增] 'compute submit' 的核心逻辑 (最终版)                              ---
# --- [BATCH THREE NEW] Core Logic for 'compute submit' (Final Version)               ---
# =======================================================================================
_internal_compute_submit() {
    local proof_file="$1"

    if [[ ! -f "$proof_file" ]]; then
        error "证明文件未找到: ${proof_file} / Proof file not found: ${proof_file}"
        return 1
    fi

    msg "正在从 ${proof_file} 读取并验证证明... / Reading and validating proof from ${proof_file}..."

    local proof_json
    proof_json=$(cat "$proof_file")
    jq -e 'type == "object" and (.engine_id | type == "string" and length > 0) and (.problem_id | type == "string" and length > 0) and (.proof_data | type == "object")' <<< "$proof_json" >/dev/null || return 1

    # 验证 proof 文件的基本格式
    # Validate the basic format of the proof file
    local engine_id problem_id proof_data
    engine_id=$(echo "$proof_json" | jq -r .engine_id 2>/dev/null)
    problem_id=$(echo "$proof_json" | jq -r .problem_id 2>/dev/null)
    proof_data=$(echo "$proof_json" | jq -c .proof_data 2>/dev/null) # 保持为紧凑的 JSON 字符串

    if [[ -z "$engine_id" || -z "$problem_id" || -z "$proof_data" ]]; then
        error "证明文件格式无效。必须包含 'engine_id', 'problem_id', 和 'proof_data' 字段。 / Invalid proof file format. Must contain 'engine_id', 'problem_id', and 'proof_data' fields."
        return 1
    fi

    _apply_theme "info" "证明格式有效。正在构造交易... / Proof format is valid. Constructing transaction..."

    # 构造 submit_math_proof 交易的 data 字段
    # Construct the data field for the submit_math_proof transaction
    local tx_data engine_hash verifier_hash
    engine_hash=$(echo "$proof_json" | jq -r .engine_hash 2>/dev/null || echo "")
    verifier_hash=$(echo "$proof_json" | jq -r .verifier_hash 2>/dev/null || echo "")
    
    tx_data=$(jq -n \
        --arg eid "$engine_id" \
        --arg pid "$problem_id" \
        --arg eh "$engine_hash" \
        --arg vh "$verifier_hash" \
        --argjson pd "$proof_data" \
        '{
            "engine_id": $eid,
            "problem_id": $pid,
            "engine_hash": $eh,
            "verifier_hash": $vh,
            "proof_data": $pd
        }')

    # 提交交易
    # Submit the transaction
    local tx_hash
    tx_hash=$(blockchain_create_transaction "submit_math_proof" "$tx_data")

    if [[ -n "$tx_hash" ]]; then
        _apply_theme "success" "✅ 证明已成功提交！ / Proof submitted successfully!"
        _apply_theme "info" "  交易哈希 / Transaction Hash: ${tx_hash}"
        _apply_theme "info" "您的贡献将在挑战期结束后被确认并计入贡献分。 / Your contribution will be confirmed and scored after the challenge period."
    else
        error "提交证明失败。 / Failed to submit proof."
    fi
}

# =======================================================================================
# --- [批次三 新增] 'compute status' 的核心逻辑 (最终版)                              ---
# --- [BATCH THREE NEW] Core Logic for 'compute status' (Final Version)               ---
# =======================================================================================
_internal_compute_status() {
    # 确保状态缓存是同步的
    # Ensure the state cache is synchronized
    _update_chain_state_cache >/dev/null 2>&1

    local my_id
    my_id=$(get_our_node_id)

    msg "您的贡献状态 / Your Contribution Status"
    _apply_theme "info" "用户ID / User ID: ${my_id}"

    local current_score
    current_score=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT score FROM contribution_scores WHERE user_id = %s;" "$my_id")

    _apply_theme "success" "当前贡献分 / Current Contribution Score: ${current_score:-0}"
    
    echo
    _apply_theme "primary" "正在等待确认的证明 / Proofs Pending Confirmation:"
    
    local pending_proofs
    pending_proofs=$(db_query_safe "$BLOCKCHAIN_DB" \
        "SELECT problem_id, confirmation_deadline_height FROM pending_proofs WHERE proposer_id = %s;" \
        "$my_id")
        
    if [[ -z "$pending_proofs" ]]; then
        _apply_theme "info" "  (无) / (None)"
    else
        local current_height
        current_height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT MAX(height) FROM blocks;")
        while IFS='|' read -r problem_id deadline_height; do
            _apply_theme "accent" "  - 问题ID / Problem ID: ${problem_id}"
            _apply_theme "info" "    将在区块 ${deadline_height} 后确认 (~$((deadline_height - current_height)) 个区块) / Confirms after block ${deadline_height} (~$((deadline_height - current_height)) blocks remaining)"
        done <<< "$pending_proofs"
    fi
}

# =======================================================================================
# --- [批次三 新增] corix discoveries 主命令 (最终版)                                 ---
# --- [BATCH THREE NEW] corix discoveries Main Command (Final Version)                ---
# =======================================================================================
# This command scans the blockchain for significant, confirmed scientific discoveries
# made by the network and presents them in a human-readable hall of fame.
#
# 此命令扫描区块链，寻找由本网络做出的、已被确认的重大科学发现，
# 并将它们以人类可读的荣誉殿堂形式呈现。
corix_discoveries() {
    # 确保状态缓存是同步的，以便能访问到所有已确认的证明
    # Ensure the state cache is synchronized to access all confirmed proofs
    _update_chain_state_cache >/dev/null 2>&1

    _apply_theme "primary" "=============================================="
    _apply_theme "accent"  " Corium 网络科学发现荣誉殿堂"
    _apply_theme "accent"  " Corium Network Hall of Scientific Discoveries"
    _apply_theme "primary" "=============================================="
    echo

    # 我们需要一个方法来确定哪些 proof 是“重大发现”。
    # 我们将通过查询所有已确认的、非内置引擎的、且 proof_data 中包含 'is_discovery' 标志的交易来实现。
    #
    # We need a way to determine which proofs are "significant discoveries".
    # We'll achieve this by querying all confirmed, non-built-in proofs where
    # the proof_data contains an 'is_discovery' flag.

    local discovery_count=0
    # 注意: 此处我们需要一个方法来识别已确认的 proof。一个简单的方法是，所有不在 pending_proofs 表中，
    # 且未被成功挑战的 submit_math_proof 交易，都视为已确认。
    # NOTE: We need a way to identify confirmed proofs. A simple method is to consider
    # all 'submit_math_proof' transactions that are NOT in pending_proofs and were not
    # successfully challenged as confirmed.
    db_query_safe "$BLOCKCHAIN_DB" \
        "SELECT T.hash, T.data, T.public_key, T.block_height FROM transactions AS T WHERE T.type = 'submit_math_proof' AND T.block_height IS NOT NULL AND NOT json_extract(T.data, '$.engine_id') LIKE 'corium/internal-engine-zero%' AND json_extract(T.data, '$.proof_data.is_discovery') = 1;" | while IFS='|' read -r tx_hash data pubkey block_height; do
        
        discovery_count=$((discovery_count + 1))

        local discoverer_id discoverer_name problem_id discovery_details
        discoverer_id=$(_internal_hash_text "$pubkey")
        discoverer_name=$(_get_identity_nickname "$discoverer_id")
        problem_id=$(echo "$data" | jq -r .problem_id)
        discovery_details=$(echo "$data" | jq -r .proof_data.discovery_details)

        _apply_theme "success" "【发现 #${discovery_count}】/ [Discovery #${discovery_count}]"
        _apply_theme "info"    "  细节 / Details:      ${discovery_details}"
        _apply_theme "accent"  "  发现者 / Discovered by: ${discoverer_name} (${discoverer_id:0:16}...)"
        _apply_theme "primary" "  问题 ID / Problem ID:   ${problem_id}"
        _apply_theme "debug"   "  确认区块 / Confirmed at: Block #${block_height}"
        _apply_theme "debug"   "  证明交易 / Proof Tx:      ${tx_hash}"
        echo
    done

    if [[ "$discovery_count" -eq 0 ]]; then
        _apply_theme "warn" "网络尚未记录任何重大的科学发现。 / No significant scientific discoveries have been recorded by the network yet."
        _apply_theme "info" "让我们一起努力，为人类知识的宝库添砖加瓦！ / Let's work together to contribute to the treasury of human knowledge!"
    fi
}

# =======================================================================================
# --- [V100 GOV] 治理命令行 (最终安全版)                                              ---
# --- [V100 GOV] Governance CLI (Final Secure Version)                                ---
# =======================================================================================
# --- [V100 修改] 'governance' 命令的帮助函数 (已扩展) ---
usage_governance() {
    _apply_theme "primary" "corix governance: 参与 Corium 网络的链上治理 / Participate in the on-chain governance of the Corium network."
    echo
    _apply_theme "info" "用法: corix governance <子命令> [参数...] / Usage: corix governance <subcommand> [arguments...]"
    echo
    _apply_theme "accent" "“有用功证明” 治理 / 'Proof of Useful Work' Governance:"
    _apply_theme "primary" "  propose-engine --desc \"...\" --pkg-id <id> --compute-hash <hash> --verifier-hash <hash> [--reward-weight <int>]"
    _apply_theme "info"    "      提议激活一个新的计算引擎。权重默认为 100。"
    _apply_theme "info"    "      Propose to activate a new compute engine. Weight defaults to 100."
    _apply_theme "primary" "  vote-engine <proposal_hash> <yes|no>"
    _apply_theme "info"    "      对一个计算引擎提案进行投票 / Vote on a compute engine proposal."
    _apply_theme "primary" "  list-proposals"
    _apply_theme "info"    "      列出所有正在进行中的治理提案 / List all active governance proposals."
    echo
    _apply_theme "accent" "跨链通信治理 / Inter-Blockchain Communication (IBC) Governance:"
    _apply_theme "primary" "  propose-verifier <chain_id> <verifier_id> [initial_header_hash]"
    _apply_theme "info"    "      提议为目标链注册一个新的验证器 / Propose to register a new verifier for a target chain."
    _apply_theme "primary" "  vote-verifier <proposal_hash> <yes|no>"
    _apply_theme "info"    "      对一个验证器提案进行投票 / Vote on a verifier proposal."
    echo
    _apply_theme "accent" "联邦信任治理 / Federation Trust Governance:"
    _apply_theme "primary" "  propose-federation-key <gpg_key_file.asc>"
    _apply_theme "info"    "      提议将一个 GPG 公钥广播为联邦可信密钥。"
    _apply_theme "info"    "      (您必须是该 GPG 密钥和当前 Corium 身份的共同所有者)"
    _apply_theme "info"    "      (You must be the owner of both the GPG key and the current Corium identity)"
}

# --- [V100 修改] 'governance' 主分发器 ---
corix_governance() {
    acquire_lock "network"
    trap 'release_lock "network"' RETURN
    
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        propose-engine)
            local options; options=$(getopt -o '' --long "desc:,pkg-id:,compute-hash:,verifier-hash:,reward-weight:" -n 'propose-engine' -- "$@")
            if [ $? -ne 0 ]; then usage_governance; exit 1; fi
            
            local desc="" pkg_id="" compute_hash="" verifier_hash="" reward_weight=100
            eval set -- "$options"
            while true; do
                case "$1" in
                    --desc) desc="$2"; shift 2;;
                    --pkg-id) pkg_id="$2"; shift 2;;
                    --compute-hash) compute_hash="$2"; shift 2;;
                    --verifier-hash) verifier_hash="$2"; shift 2;;
                    --reward-weight) reward_weight="$2"; shift 2;;
                    --) shift; break;;
                esac
            done
            
            if [[ -z "$pkg_id" || -z "$compute_hash" || -z "$verifier_hash" ]]; then
                _apply_theme "error" "错误：--pkg-id, --compute-hash, 和 --verifier-hash 是必须参数。 / Error: --pkg-id, --compute-hash, and --verifier-hash are required arguments."
                usage_governance
                exit 1
            fi

            _internal_governance_propose_engine "$desc" "$pkg_id" "$compute_hash" "$verifier_hash" "$reward_weight"
            ;;

        vote-engine)
            [ $# -ne 2 ] && { usage_governance; exit 1; }
            _internal_governance_vote_engine "$1" "$2"
            ;;

        list-proposals)
            _internal_governance_list_proposals
            ;;
            
        propose-verifier)
            [ $# -lt 2 ] && { usage_governance; exit 1; }
            local target_chain="$1" verifier_id="$2" initial_hash="${3:-}"
            
            local tx_data; tx_data=$(jq -n \
                --arg tc "$target_chain" \
                --arg vid "$verifier_id" \
                --arg ih "$initial_hash" \
                '{target_chain_id: $tc, verifier_id: $vid, initial_header_hash: $ih}')
            
            info "正在提交 IBC 验证器提案... / Submitting IBC verifier proposal..."
            blockchain_create_transaction "propose_ibc_verifier" "$tx_data"
            ;;
        vote-verifier)
            [ $# -ne 2 ] && { usage_governance; exit 1; }
            local proposal_hash="$1" vote_choice="$2"
            [[ "$vote_choice" =~ ^(yes|no)$ ]] || { error "Vote must be 'yes' or 'no'."; exit 1; }
            
            local tx_data; tx_data=$(jq -n --arg hash "$proposal_hash" --arg vote "$vote_choice" '{proposal_tx_hash: $hash, vote: $vote}')
            info "正在为 IBC 验证器提案投票... / Voting on IBC verifier proposal..."
            blockchain_create_transaction "vote_ibc_verifier" "$tx_data"
            ;;

        propose-federation-key)
            [ $# -ne 1 ] && { usage_governance; exit 1; }
            local key_file="$1"
            
            [ ! -f "$key_file" ] && { error "GPG 密钥文件未找到 / GPG key file not found: $key_file"; exit 1; }

            # 1. 获取 GPG 密钥指纹
            local gpg_fingerprint; gpg_fingerprint=$(gpg --with-colons --import-options show-only --import < "$key_file" 2>/dev/null | awk -F: '/^fpr/ {print $10; exit}')
            [ -z "$gpg_fingerprint" ] && { error "无法从文件中解析 GPG 指纹。 / Could not parse GPG fingerprint from file."; exit 1; }
            
            # 2. 获取当前的 Corium 身份 ID (这就是 owner_id)
            local owner_id; owner_id=$(get_our_node_id)

            info "正在创建所有权证明... / Creating proof of ownership..."
            
            # 3. 证明一：用 Corium 私钥签名 GPG 指纹
            detail "  -> 正在使用 Corium 密钥签名 GPG 指纹... / Signing GPG fingerprint with Corium key..."
            local corium_sig; corium_sig=$(sign_data "$gpg_fingerprint" "$USER_IDENTITY_FILE")
            
            # 4. 证明二：用 GPG 私钥签名 Corium ID
            detail "  -> 正在使用 GPG 密钥签名 Corium ID... (可能需要您输入 GPG 密码) / Signing Corium ID with GPG key... (may prompt for GPG password)"
            local gpg_sig
            gpg_sig=$(echo -n "$owner_id" | gpg --detach-sign --armor --local-user "$gpg_fingerprint" | base64 -w0)
            if [ $? -ne 0 ]; then
                error "GPG 签名失败。请确保您拥有该 GPG 密钥的私钥，并且 GPG Agent 配置正确。"
                error "GPG signing failed. Ensure you own the private key and your GPG agent is configured correctly."
                return 1
            fi

            # 5. 准备交易
            local gpg_key_b64; gpg_key_b64=$(base64 -w0 < "$key_file")
            local tx_data
            tx_data=$(jq -n \
                --arg key "$gpg_key_b64" \
                --arg oid "$owner_id" \
                --arg csig "$corium_sig" \
                --arg gsig "$gpg_sig" \
                '{
                    gpg_key_b64: $key,
                    owner_id: $oid,
                    proof: {
                        corium_signature_on_gpg_fingerprint: $csig,
                        gpg_signature_on_corium_id: $gsig
                    }
                }')
            
            info "正在提交包含所有权证明的联邦密钥提案... / Submitting federated key proposal with proof of ownership..."
            blockchain_create_transaction "propose_federation_key" "$tx_data"
            ;;
        *)
            usage_governance
            ;;
    esac
}

# --- [新增] 'propose-engine' 的内部实现 ---
_internal_governance_propose_engine() {
    local desc="$1"
    local pkg_id="$2"
    local compute_hash="$3"
    local verifier_hash="$4"
    local reward_weight="$5"

    msg "正在构造激活新计算引擎的提案... / Constructing proposal to activate new compute engine..."
    _apply_theme "info" "  软件包ID / Package ID: ${pkg_id}"
    _apply_theme "info"  "  计算程序哈希 / Compute Hash: ${compute_hash:0:32}..."
    _apply_theme "info"  "  奖励权重 / Reward Weight: ${reward_weight}"

    local tx_data
    tx_data=$(jq -n \
        --arg d "$desc" \
        --arg pid "$pkg_id" \
        --arg chash "$compute_hash" \
        --arg vhash "$verifier_hash" \
        --argjson weight "$reward_weight" \
        '{
            "description": $d,
            "pkg_id": $pid,
            "compute_program_hash": $chash,
            "verifier_script_hash": $vhash,
            "reward_weight": $weight
        }')

    local tx_hash tx_output
    if ! tx_output=$(blockchain_create_transaction "propose_new_compute_engine" "$tx_data"); then
        error "原生交易提交失败，请检查本地待处理状态后重试。 / Native submission failed; inspect local pending state before retry."
        return 1
    fi
    tx_hash="${tx_output##*$'\n'}"
    if [[ "$tx_hash" =~ ^[a-f0-9]{64}$ ]]; then
        _apply_theme "success" "提案已在本地保存，等待原生共识确认。 / Proposal stored locally; native consensus confirmation pending."
        _apply_theme "info" "  交易哈希 / Transaction Hash: ${tx_hash}"
    else
        error "提交提案失败。 / Failed to submit proposal."
        return 1
    fi
}


# --- [新增] 'vote-engine' 的内部实现 ---
_internal_governance_vote_engine() {
    local proposal_hash="$1"
    local vote_choice="$2"
    [[ "$vote_choice" =~ ^(yes|no)$ ]] || { _apply_theme "error" "错误: 投票必须是 'yes' 或 'no'。 / Error: Vote must be 'yes' or 'no'."; usage_governance; exit 1; }
    
    if [ "$vote_choice" = "no" ]; then
        _apply_theme "info" "“弃权”或“反对”通过不投票来表示。将不会创建任何交易。 / Abstention or 'no' votes are cast by not voting. No transaction will be created."
        return 0
    fi
    
    local tx_data
    tx_data=$(jq -n --arg hash "$proposal_hash" --arg vote "$vote_choice" '{proposal_tx_hash: $hash, vote: $vote}')

    info "正在为提案 ${proposal_hash:0:16} 投出赞成票... / Casting 'yes' vote for proposal ${proposal_hash:0:16}..."
    
    local tx_hash tx_output
    if ! tx_output=$(blockchain_create_transaction "vote_on_compute_engine" "$tx_data"); then
        error "原生交易提交失败，请检查本地待处理状态后重试。 / Native submission failed; inspect local pending state before retry."
        return 1
    fi
    tx_hash="${tx_output##*$'\n'}"
    if [[ "$tx_hash" =~ ^[a-f0-9]{64}$ ]]; then
        _apply_theme "success" "投票已在本地保存，等待原生共识确认。 / Vote stored locally; native consensus confirmation pending."
        _apply_theme "info" "  交易哈希 / Transaction Hash: ${tx_hash}"
    else
        error "提交投票失败。 / Failed to submit vote."
        return 1
    fi
}

# --- [新增] 'list-proposals' 的内部实现 ---
_internal_governance_list_proposals() {
    _update_chain_state_cache >/dev/null 2>&1
    
    _apply_theme "primary" "正在进行中的治理提案 / Active Governance Proposals"
    echo "-------------------------------------------------"
    
    local VOTE_WINDOW=1000 # 协议参数
    local current_height
    current_height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT MAX(height) FROM blocks;")

    db_query_safe "$BLOCKCHAIN_DB" \
        "SELECT T.hash, T.type, T.data, T.block_height FROM transactions AS T WHERE (T.type = 'propose_new_compute_engine' OR T.type = 'validator_propose_addition' OR T.type = 'validator_propose_removal') AND T.block_height IS NOT NULL AND (%d - T.block_height) <= %d;" \
        "$current_height" "$VOTE_WINDOW" | while IFS='|' read -r hash type data height; do

        local end_height=$((height + VOTE_WINDOW))
        
        echo -e "\033[1;32m提案哈希 / Proposal Hash\033[0m: ${hash}"
        _apply_theme "info" "  类型 / Type:    ${type}"
        _apply_theme "info" "  细节 / Details:   $(echo "$data" | jq -c .)"
        _apply_theme "accent" "  投票截止区块 / Voting ends at block: \033[1;33m${end_height}\033[0m (~$((end_height - current_height)) 个区块剩余 / blocks remaining)"
        echo
    done
}


# =======================================================================================
# --- [V95 FINAL] corix setup-completion (幂等的、内嵌式补全脚本安装器)             ---
# --- [V95 FINAL] corix setup-completion (Idempotent, Embedded Completion Installer)  ---
# =======================================================================================
# 此函数负责将内嵌的 Bash 补全脚本安装到用户的系统中。
# This function is responsible for installing the embedded Bash completion script into the user's system.
corix_setup_completion() {
    # --- 步骤 1: 将内嵌的补全脚本内容加载到变量中 ---
    # --- Step 1: Load the embedded completion script content into a variable ---
    local completion_script_content
    # 使用 HEREDOC 来安全地嵌入整个脚本
    # Use a HEREDOC to safely embed the entire script
    read -r -d '' completion_script_content <<'EOF_COMPLETION'
#!/bin/bash
#
# corix - Bash Completion Script v10.0 (Release Candidate)
# corix - Bash 自动补全脚本 v10.0 (发布候选版)
#
# Author: People
# Version: 10.0 (Includes all features up to Corium V100, including interactive selectors,
#                config management, encrypted keys, on-chain trust, and developer tools)
#
# 此脚本为 corix 包管理器提供丰富的、上下文感知的 Tab 自动补全功能。
# This script provides rich, context-aware tab-completion for the corix package manager.

# --- 辅助函数：定义数据库路径 ---
# --- Helper Function: Define Database Paths ---
_corix_get_db_path() {
    local db_name="$1"
    local network_id="${CORIUM_NETWORK_ID_OVERRIDE:-default}"
    local corium_root="${CORIUM_ROOT:-/}"
    case "$db_name" in
        blockchain) echo "${corium_root%/}/var/lib/corix/networks/${network_id}/blockchain/chain.db" ;;
        forum)      echo "${corium_root%/}/var/lib/corix/networks/${network_id}/forum/forum.db" ;;
    esac
}

# --- 辅助函数：获取各种动态列表 ---
# --- Helper Functions: Get various dynamic lists ---

_corix_get_packages() {
    local index_file="${CORIUM_ROOT:-/}/var/cache/corix/metadata/search.index"
    [ -f "${index_file}" ] && cut -d: -f1 "${index_file}"
}

_corix_get_installed_packages() {
    local directory
    [ -d "${CORIUM_ROOT%/}/var/lib/corix/networks/${CORIUM_NETWORK_ID_OVERRIDE:-default}/installed" ] || return 0
    for directory in "${CORIUM_ROOT%/}/var/lib/corix/networks/${CORIUM_NETWORK_ID_OVERRIDE:-default}/installed"/*; do
        [ -d "$directory" ] && [ -r "$directory/name" ] && [ -r "$directory/slot" ] || continue
        printf '%s:%s\n' "$(cat "$directory/name")" "$(cat "$directory/slot")"
    done
}

_corix_get_stratas() {
    local strata_dir="${CORIUM_ROOT:-/}/usr/corix/strata/networks/default"
    [ -d "$strata_dir" ] && find "$strata_dir" -mindepth 1 -maxdepth 1 -type d -printf '%f\n'
}

_corix_get_snapshots() {
    local snapshots_dir="${CORIUM_ROOT:-/}/var/lib/corix/networks/default/snapshots"
    [ -d "$snapshots_dir" ] && find "$snapshots_dir" -mindepth 1 -maxdepth 1 -type d -printf '%f\n'
}

_corix_get_trust_zones() {
    local zones_dir="${CORIUM_ROOT:-/}/etc/corix/networks/default/trust_zones"
    [ -d "$zones_dir" ] && find "$zones_dir" -mindepth 1 -maxdepth 1 -type d -printf '%f\n'
}

_corix_get_forum_topics() {
    local db_path=$(_corix_get_db_path "forum")
    [ -f "$db_path" ] && sqlite3 "$db_path" "SELECT id FROM topics ORDER BY timestamp DESC;" 2>/dev/null
}

_corix_get_all_identities() {
    local db_path=$(_corix_get_db_path "forum")
    [ -f "$db_path" ] && sqlite3 "$db_path" "SELECT id_hash FROM identity_cache;" 2>/dev/null
}

_corix_get_groups() {
    local db_path=$(_corix_get_db_path "forum")
    [ -f "$db_path" ] && sqlite3 "$db_path" "SELECT id_hash FROM identity_cache WHERE type = 'group';" 2>/dev/null
}

_corix_get_channels_and_aliases() {
    local db_path=$(_corix_get_db_path "forum")
    if [ -f "$db_path" ]; then
        sqlite3 "$db_path" "SELECT id_hash FROM identity_cache WHERE type = 'group' OR type = 'broadcast';" 2>/dev/null
        sqlite3 "$db_path" "SELECT alias_name FROM aliases;" 2>/dev/null
    fi
}

_corix_get_aliases() {
    local db_path=$(_corix_get_db_path "forum")
    [ -f "$db_path" ] && sqlite3 "$db_path" "SELECT alias_name FROM aliases;" 2>/dev/null
}

_corix_get_governance_proposals() {
    local db_path=$(_corix_get_db_path "blockchain")
    if [ -f "$db_path" ]; then
        local proposal_types="'propose_new_compute_engine', 'validator_propose_addition', 'validator_propose_removal', 'group_propose_owner', 'group_propose_admin', 'propose_app_template', 'propose_ibc_verifier'"
        local VOTE_WINDOW=1000 # Must match the value in corix.sh
        local current_height
        current_height=$(sqlite3 "$db_path" "SELECT MAX(height) FROM blocks;" 2>/dev/null)
        sqlite3 "$db_path" "SELECT T.hash FROM transactions AS T WHERE T.type IN (${proposal_types}) AND T.block_height IS NOT NULL AND (${current_height:-0} - T.block_height) <= ${VOTE_WINDOW};" 2>/dev/null
    fi
}

_corix_get_validators() {
    local db_path=$(_corix_get_db_path "blockchain")
    [ -f "$db_path" ] && sqlite3 "$db_path" "SELECT public_key_hash FROM validators WHERE stake > 0 AND status = 'active';" 2>/dev/null
}

_corix_get_domains() {
    local db_path=$(_corix_get_db_path "forum")
    [ -f "$db_path" ] && sqlite3 "$db_path" "SELECT domain_name FROM nns_records;" 2>/dev/null
}

_corix_get_mods() {
    _corix_get_packages | grep -E '^(mods|community)/'
}

_corix_get_gpg_keys() {
    local keyring_path
    local active_zone_file="${CORIUM_ROOT:-/}/etc/corix/networks/default/trust_zones/active_zone"
    local active_zone
    active_zone=$(cat "${active_zone_file}" 2>/dev/null || echo "default")
    keyring_path="${CORIUM_ROOT:-/}/etc/corix/networks/default/trust_zones/${active_zone}/keyring.gpg"
    [ -f "$keyring_path" ] && gpg --batch --no-default-keyring --keyring "$keyring_path" --with-colons --list-keys | awk -F: '/^pub/ {print $5}'
}

_corix_get_persistent_agents() {
    local enabled_mods_file="${CORIUM_ROOT:-/}/etc/corix/networks/default/mods_enabled.conf"
    local repos_dir="${CORIUM_ROOT:-/}/usr/corix/repos/networks/default"
    
    [ ! -f "$enabled_mods_file" ] && return

    grep -v '^#' "$enabled_mods_file" | while IFS= read -r pkg_id; do
        [ -z "$pkg_id" ] && continue
        local name_part="${pkg_id%%:*}"
        local name_base="${name_part##*/}"
        local build_file
        build_file=$(find "$repos_dir" -type f -name "${name_base}.build" -path "*/${name_part}" -print -quit 2>/dev/null)
        if [ -f "$build_file" ]; then
            if grep -q '^\s*persistent_service\s*=\s*"\?true"\?' "$build_file"; then
                echo "$pkg_id"
            fi
        fi
    done
}

_corix_get_maillists() {
    local db_path=$(_corix_get_db_path "forum")
    [ -f "$db_path" ] && sqlite3 "$db_path" "SELECT id_hash FROM identity_cache WHERE type = 'group' AND permissions LIKE '%\"Public Mailing List\"%';" 2>/dev/null
}

_corix_get_app_template_proposals() {
    local db_path=$(_corix_get_db_path "blockchain")
    [ -f "$db_path" ] && sqlite3 "$db_path" "SELECT hash FROM transactions WHERE type = 'propose_app_template';" 2>/dev/null
}

_corix_get_onchain_agents() {
    local db_path=$(_corix_get_db_path "blockchain")
    [ -f "$db_path" ] && sqlite3 "$db_path" "SELECT agent_id FROM onchain_identities;" 2>/dev/null
}

_corix_get_all_mails() {
    local db_path=$(_corix_get_db_path "forum")
    [ -f "$db_path" ] && sqlite3 "$db_path" "SELECT tx_hash FROM mails;" 2>/dev/null
}

_corix_get_exodus_proposals() {
    local db_path=$(_corix_get_db_path "forum")
    [ -f "$db_path" ] && sqlite3 "$db_path" "SELECT proposal_hash FROM exodus_proposals WHERE expires_at > strftime('%s', 'now');" 2>/dev/null
}

# --- 主补全函数 (已升级) ---
# --- Main Completion Function (Upgraded) ---
_corix_completion() {
    local cur prev words cword command
    _get_comp_words_by_ref -n : cur prev words cword

    # Get the main command, handling aliases
    command="${words[1]}"
    case "$command" in
        in) command="install" ;;
        rm) command="remove" ;;
        up) command="upgrade" ;;
        se) command="search" ;;
        auto|autorm) command="autoremove" ;;
        h) command="help" ;;
    esac
    
    if [ "$cword" -eq 1 ]; then
        # --- [V10] 最终完整命令列表 ---
        # --- [V10] Final Complete Command List ---
        local commands="acl agent alias app adopt autoremove backup blockchain build ceasefire clean compute config consensus create-delta csi"
        commands+=" discoveries exodus find find-attachments forum gen-build governance group help ibc identity info install key manage"
        commands+=" mail maillist message network owns p2p rebuild remove rollback search service site snapshot status stop strata sync theme trust"
        commands+=" upgrade user validator verify wiki work setup-completion setup-prover _seminternal_gen_docs _seminternal_gen_i18n_template _seminternal_random_bytes _seminternal_base64_encode _seminternal_base64_decode"
        local global_opts="--help -h --version --debug --verbose -q --quiet"
        COMPREPLY=( $(compgen -W "${commands} ${global_opts}" -- "${cur}") )
        return 0
    fi

    case "$command" in
        install)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "--allow-canary" -- "${cur}") )
            else
                COMPREPLY=( $(compgen -W "$(_corix_get_packages)" -- "${cur}") )
            fi
            ;;
        remove|upgrade|info|build|autoremove|owns|rollback|delta-update|csi)
            COMPREPLY=( $(compgen -W "$(_corix_get_packages)" -- "${cur}") )
            ;;
        search)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "--update-index" -- "${cur}") )
            else
                # No completion for search terms
                COMPREPLY=()
            fi
            ;;
        rebuild)
            COMPREPLY=( $(compgen -W "--dry-run --prune -y --yes --force" -- "${cur}") )
            ;;
        
        verify)
            _filedir ".corix.tar"
            ;;

        strata)
            if [ "$cword" -eq 2 ]; then
                local subcommands="--create --list -e --execute --destroy --promote"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ "${words[2]}" == "--execute" || "${words[2]}" == "-e" || "${words[2]}" == "--destroy" || "${words[2]}" == "--promote" ]]; then
                COMPREPLY=( $(compgen -W "$(_corix_get_stratas)" -- "${cur}") )
            fi
            ;;

        forum)
            if [ "$cword" -eq 2 ]; then
                local subcommands="init sync list show search new-topic post get-attachment export import set-policy"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ "${words[2]}" == "show" || "${words[2]}" == "post" || "${words[2]}" == "export" || "${words[2]}" == "set-policy" ]]; then
                COMPREPLY=( $(compgen -W "$(_corix_get_forum_topics)" -- "${cur}") )
            fi
            ;;

        site)
            if [ "$cword" -eq 2 ]; then
                local subcommands="publish domain my-id my-points"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ "${words[2]}" == "domain" ]]; then
                if [ "$cword" -eq 3 ]; then
                    local domain_cmds="query transfer auction bid reveal renew"
                    COMPREPLY=( $(compgen -W "${domain_cmds}" -- "${cur}") )
                elif [[ " query transfer bid reveal auction renew " =~ " ${words[3]} " ]]; then
                    COMPREPLY=( $(compgen -W "$(_corix_get_domains)" -- "${cur}") )
                fi
            fi
            ;;
        
        group)
            if [ "$cword" -eq 2 ]; then
                local subcommands="create info history join leave invite kick admin set-owner set-policy propose-owner vote-owner propose-admin vote-admin"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ " create set-policy " =~ " ${words[2]} " ]]; then
                : # No completion for new names
            elif [[ " vote-owner vote-admin " =~ " ${words[2]} " ]]; then
                COMPREPLY=( $(compgen -W "$(_corix_get_governance_proposals)" -- "${cur}") )
            else
                if [[ " invite kick admin set-owner propose-owner " =~ " ${words[2]} " && "$cword" -eq 4 ]]; then
                    # For these commands, the 2nd argument is a user ID
                    # 对于这些命令，第二个参数是用户ID
                    COMPREPLY=( $(compgen -W "$(_corix_get_all_identities)" -- "${cur}") )
                else
                    # All other group commands take a group_id as the first argument
                    # 所有其他的 group 命令都以一个 group_id 作为第一个参数
                    COMPREPLY=( $(compgen -W "$(_corix_get_groups)" -- "${cur}") )
                fi
            fi
            ;;

        message)
            if [ "$cword" -eq 2 ]; then
                local subcommands="send inbox query get-attachment"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ "${words[2]}" == "send" || "${words[2]}" == "query" ]]; then
                COMPREPLY=( $(compgen -W "$(_corix_get_channels_and_aliases)" -- "${cur}") )
            fi
            ;;

        validator)
            if [ "$cword" -eq 2 ]; then
                local subcommands="propose-add propose-remove vote list-proposals"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ "${words[2]}" == "propose-add" ]]; then
                _filedir ".pub"
            elif [[ "${words[2]}" == "propose-remove" ]]; then
                COMPREPLY=( $(compgen -W "$(_corix_get_validators)" -- "${cur}") )
            elif [[ "${words[2]}" == "vote" ]]; then
                if [ "$cword" -eq 3 ]; then
                    COMPREPLY=( $(compgen -W "$(_corix_get_governance_proposals)" -- "${cur}") )
                elif [ "$cword" -eq 4 ]; then
                    COMPREPLY=( $(compgen -W "yes no" -- "${cur}") )
                fi
            fi
            ;;

        compute)
            if [ "$cword" -eq 2 ]; then
                local subcommands="run submit status"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ "${words[2]}" == "submit" ]]; then
                _filedir
            fi
            ;;

        key)
            if [ "$cword" -eq 2 ]; then
                local subcommands="--list --import --delete --list-zones --create-zone --switch-zone"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ "${words[2]}" == "--import" ]]; then
                _filedir ".asc"
            elif [[ "${words[2]}" == "--switch-zone" ]]; then
                COMPREPLY=( $(compgen -W "$(_corix_get_trust_zones)" -- "${cur}") )
            elif [[ "${words[2]}" == "--delete" ]]; then
                COMPREPLY=( $(compgen -W "$(_corix_get_gpg_keys)" -- "${cur}") )
            fi
            ;;

        acl)
            if [ "$cword" -eq 2 ]; then
                COMPREPLY=( $(compgen -W "local" -- "${cur}") )
            elif [[ "${words[2]}" == "local" ]]; then
                if [ "$cword" -eq 3 ]; then
                    local acl_cmds="show set unset"
                    COMPREPLY=( $(compgen -W "${acl_cmds}" -- "${cur}") )
                elif [[ "${words[3]}" == "show" || "${words[3]}" == "set" || "${words[3]}" == "unset" ]]; then
                     COMPREPLY=( $(compgen -W "$(_corix_get_mods)" -- "${cur}") )
                fi
            fi
            ;;

        p2p)
            if [ "$cword" -eq 2 ]; then
                local subcommands="get list-peers add-peer find-providers share-identity distrust trust unblock"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ " distrust trust unblock " =~ " ${words[2]} " ]]; then
                # Complete all known peer IDs for distrust/trust commands
                # 为不信任/信任命令补全所有已知的节点ID
                COMPREPLY=( $(compgen -W "$(_corix_get_all_identities)" -- "${cur}") )
            fi
            ;;
            
        user)
            if [ "$cword" -eq 2 ]; then
                local subcommands="set-nickname info block unblock"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ " info block unblock " =~ " ${words[2]} " ]]; then
                # Complete all known identity IDs for info/block etc.
                # 为 info/block 等命令补全所有已知的身份ID
                COMPREPLY=( $(compgen -W "$(_corix_get_all_identities)" -- "${cur}") )
            fi
            ;;

        stop)
            COMPREPLY=( $(compgen -W "-f --force" -- "${cur}") )
            ;;

        clean)
            COMPREPLY=( $(compgen -W "--sources --binaries --tmp --all --dry-run --force -y --older-than --keep-last" -- "${cur}") )
            ;;

        backup)
             if [ "$cword" -eq 2 ]; then
                COMPREPLY=( $(compgen -W "create restore" -- "${cur}") )
             elif [[ "${words[2]}" == "create" && "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "--encrypt --no-private-keys" -- "${cur}") )
             elif [[ "${words[2]}" == "restore" ]]; then
                _filedir
             fi
             ;;
        
        snapshot)
             if [ "$cword" -eq 2 ]; then
                COMPREPLY=( $(compgen -W "create list delete rollback" -- "${cur}") )
             elif [[ "${words[2]}" == "delete" || "${words[2]}" == "rollback" ]]; then
                 COMPREPLY=( $(compgen -W "$(_corix_get_snapshots)" -- "${cur}") )
             fi
             ;;
        
        alias)
            if [ "$cword" -eq 2 ]; then
                COMPREPLY=( $(compgen -W "set unset list ls" -- "${cur}") )
            elif [[ "${words[2]}" == "set" && "$cword" -eq 4 ]]; then
                COMPREPLY=( $(compgen -W "$(_corix_get_all_identities)" -- "${cur}") )
            elif [[ "${words[2]}" == "unset" ]]; then
                COMPREPLY=( $(compgen -W "$(_corix_get_aliases)" -- "${cur}") )
            fi
            ;;

        find-attachments)
            if [[ "$cur" == -* ]]; then
                local flags="--channels --include-forum --name-like --type"
                COMPREPLY=( $(compgen -W "${flags}" -- "${cur}") )
            fi
            ;;
        
        gen-build)
            if [[ "$cur" == -* ]]; then
                local flags="--template --auto-detect --output-dir --pkgname --pkgver --pkgdesc --slot --depends --makedepends --executable --dapp-entrypoint --handles-tx-types --help"
                COMPREPLY=( $(compgen -W "${flags}" -- "${cur}") )
            fi
            ;;
        mail)
            if [ "$cword" -eq 2 ]; then
                local subcommands="inbox send read delete"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ "${words[2]}" == "send" ]]; then
                COMPREPLY=( $(compgen -W "$(_corix_get_all_identities)" -- "${cur}") )
            elif [[ "${words[2]}" == "read" || "${words[2]}" == "delete" ]]; then
                COMPREPLY=( $(compgen -W "$(_corix_get_all_mails)" -- "${cur}") )
            fi
            ;;
        
        maillist)
            if [ "$cword" -eq 2 ]; then
                local subcommands="create subscribe unsubscribe post list archive"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ "${words[2]}" == "subscribe" || "${words[2]}" == "unsubscribe" || "${words[2]}" == "post" || "${words[2]}" == "archive" ]]; then
                COMPREPLY=( $(compgen -W "$(_corix_get_maillists)" -- "${cur}") )
            fi
            ;;

        app)
            if [ "$cword" -eq 2 ]; then
                local subcommands="propose vote list"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ "${words[2]}" == "vote" ]]; then
                if [ "$cword" -eq 3 ]; then
                    COMPREPLY=( $(compgen -W "$(_corix_get_app_template_proposals)" -- "${cur}") )
                elif [ "$cword" -eq 4 ]; then
                    COMPREPLY=( $(compgen -W "yes no" -- "${cur}") )
                fi
            fi
            ;;

        agent)
            if [ "$cword" -eq 2 ]; then
                local subcommands="create list endow call"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ "${words[2]}" == "endow" || "${words[2]}" == "call" ]]; then
                if [ "$cword" -eq 3 ]; then
                    COMPREPLY=( $(compgen -W "$(_corix_get_onchain_agents)" -- "${cur}") )
                fi
            elif [[ "${words[2]}" == "create" ]]; then
                 COMPREPLY=( $(compgen -W "$(_corix_get_mods)" -- "${cur}") )
            fi
            ;;
            
        work)
            if [ "$cword" -eq 2 ]; then
                COMPREPLY=( $(compgen -W "report status" -- "${cur}") )
            fi
            ;;

        consensus)
            if [ "$cword" -eq 2 ]; then
                COMPREPLY=( $(compgen -W "report-double-sign" -- "${cur}") )
            elif [[ "${words[2]}" == "report-double-sign" ]]; then
                if [[ "$cur" == --header* ]]; then
                    COMPREPLY=( $(compgen -W "--header1 --header2" -- "${cur}") )
                else
                    _filedir ".json"
                fi
            fi
            ;;

        service)
            if [ "$cword" -eq 2 ]; then
                local subcommands="list ls status start stop restart logs"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ " start stop restart logs " =~ " ${words[2]} " ]]; then
                COMPREPLY=( $(compgen -W "$(_corix_get_persistent_agents)" -- "${cur}") )
            fi
            ;;

        governance)
            if [ "$cword" -eq 2 ]; then
                local subcommands="propose-engine vote-engine list-proposals propose-verifier vote-verifier"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ ("${words[2]}" == "vote-engine" || "${words[2]}" == "vote-verifier") && "$cword" -eq 3 ]]; then
                COMPREPLY=( $(compgen -W "$(_corix_get_governance_proposals)" -- "${cur}") )
            fi
            ;;

        ceasefire)
            if [ "$cword" -eq 2 ]; then
                local subcommands="read post sync"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            fi
            ;;
        
        # --- [V97+] 新增和修改的命令补全 ---
        config)
            if [ "$cword" -eq 2 ]; then
                local subcommands="get set list"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ "${words[2]}" == "get" || "${words[2]}" == "set" ]]; then
                # 动态生成所有可能的配置键
                # Dynamically generate all possible config keys
                local keys="main.dep_mode main.build_jobs main.editor main.enable_fuzzy_finder"
                keys+=" network.download_protocol_priority network.proxy p2p.port p2p.auto_trust_new_nodes"
                COMPREPLY=( $(compgen -W "${keys}" -- "${cur}") )
            fi
            ;;

        init)
            COMPREPLY=( $(compgen -W "--interactive" -- "${cur}") )
            ;;
        
        trust)
            if [ "$cword" -eq 2 ]; then
                local subcommands="endorse show"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ "${words[2]}" == "endorse" || "${words[2]}" == "show" ]]; then
                COMPREPLY=( $(compgen -W "$(_corix_get_all_identities)" -- "${cur}") )
            fi
            ;;
            
        identity)
            if [ "$cword" -eq 2 ]; then
                local subcommands="export import migrate"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ "${words[2]}" == "export" ]]; then
                 COMPREPLY=( $(compgen -W "--private --output" -- "${cur}") )
            elif [[ "${words[2]}" == "import" ]]; then
                 if [[ "$cur" == -* ]]; then
                    COMPREPLY=( $(compgen -W "--password-from-env" -- "${cur}") )
                 else
                    _filedir
                 fi
            fi
            ;;

        ibc)
             if [ "$cword" -eq 2 ]; then
                # [V99] 新增 transfer-nns
                local subcommands="msg get-build generate-state-proof redeem transfer-nns"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            fi
            ;;

        exodus)
            if [ "$cword" -eq 2 ]; then
                local subcommands="propose-snapshot notarize tally"
                COMPREPLY=( $(compgen -W "${subcommands}" -- "${cur}") )
            elif [[ "${words[2]}" == "notarize" || "${words[2]}" == "tally" ]]; then
                if [[ "$cur" == -* ]]; then
                    COMPREPLY=( $(compgen -W "--dry-run" -- "${cur}") ) # V100
                else
                    COMPREPLY=( $(compgen -W "$(_corix_get_exodus_proposals)" -- "${cur}") )
                fi
            fi
            ;;

        help|h)
            local commands="acl agent alias app adopt autoremove backup blockchain build ceasefire clean compute consensus create-delta csi"
            commands+=" discoveries exodus find find-attachments forum gen-build governance group help ibc identity info install key manage"
            commands+=" mail maillist message network owns p2p rebuild remove rollback search service site snapshot status stop strata sync theme"
            commands+=" upgrade user validator verify wiki work setup-completion setup-prover _seminternal_gen_docs _seminternal_gen_i18n_template _seminternal_random_bytes _seminternal_base64_encode _seminternal_base64_decode"
            local topics="lifecycle python-compat dev declarative cor-web nomen-philosophy modding agents acl useful-work gateway list-installed view-dapp-source dapp-models app-dev ibc-proof-format agent-dev design-philosophy relayer repo-config gimps-example consensus-core third-party-clients pm-philosophy local-interop migration-guide exodus-migration ccip"
            COMPREPLY=( $(compgen -W "${commands} ${topics}" -- "${cur}") )
            ;;
            
        *)
            COMPREPLY=()
            ;;
    esac
}

complete -F _corix_completion corix
EOF_COMPLETION

    # --- 步骤 2: 确定正确的安装路径 ---
    # --- Step 2: Determine the correct installation path ---
    local -a BASH_COMPLETION_DIRS=(
        "${CORIUM_ROOT%/}/etc/bash_completion.d"
        "${CORIUM_ROOT%/}/usr/share/bash-completion/completions"
    )
    local dest_dir=""
    for dir in "${BASH_COMPLETION_DIRS[@]}"; do
        if [ -d "$dir" ] && [ -w "$dir" ]; then
            dest_dir="$dir"
            break
        fi
    done

    if [ -z "$dest_dir" ]; then
        error "未能找到可写的 Bash 补全目录。 / Could not find a writable Bash completion directory."
        info "请尝试使用 'sudo' 运行此命令。 / Please try running this command with 'sudo'."
        return 1
    fi
    
    local dest_file="${dest_dir}/corix"

    # --- 步骤 3: 实现幂等性检查 ---
    # --- Step 3: Implement idempotency checks ---
    info "正在检查补全脚本状态... / Checking completion script status..."
    local new_hash
    new_hash=$(echo "$completion_script_content" | calculate_hash)

    if [ -f "$dest_file" ]; then
        local old_hash
        old_hash=$(calculate_hash "$dest_file")
        if [ "$new_hash" = "$old_hash" ]; then
            msg "Bash 补全脚本已安装且为最新版本。 / Bash completion script is already installed and up-to-date."
            return 0
        else
            warn "一个不同版本的补全脚本已存在。 / A different version of the completion script already exists."
            read -rp "您希望覆盖它吗？ [y/N] / Do you want to overwrite it? [y/N] " choice
            if [[ ! "$choice" =~ ^[yY] ]]; then
                msg "操作已取消。 / Operation cancelled."
                return 1
            fi
        fi
    fi

    # --- 步骤 4: 安装或覆盖文件 ---
    # --- Step 4: Install or overwrite the file ---
    info "正在将补全脚本安装到: ${dest_file} / Installing completion script to: ${dest_file}"
    if ! echo "$completion_script_content" > "$dest_file"; then
        error "写入文件失败！请检查权限。 / Failed to write file! Please check permissions."
        return 1
    fi
    
    chmod 644 "$dest_file"
    
    msg "✅ Bash 补全脚本已成功安装。 / Bash completion script installed successfully."
    info "请重新启动您的 Shell 或运行以下命令来激活它："
    info "Please restart your shell or run the following command to activate it:"
    info "  source \"${dest_file}\""
}

#==============================================================================
# 函数: _get_proxy_args_for_curl() [新增的微型辅助函数]
# 功能: 从主配置文件读取唯一的代理设置，并生成 curl 参数。
# Function: _get_proxy_args_for_curl() [New Micro-Helper Function]
# Purpose: Reads the single proxy setting from the main config and generates curl arguments.
#==============================================================================
_get_proxy_args_for_curl() {
    if [[ ! -r "$CONFIG_FILE" ]]; then
        return 1
    fi
    
    # 读取唯一的 'proxy' 键
    # Read the single 'proxy' key
    local proxy_address
    proxy_address=$(grep -oP '(?<=^\s*proxy\s*=\s*).*' "$CONFIG_FILE" 2>/dev/null)
    
    if [[ -n "$proxy_address" ]]; then
        # 如果设置了代理，则输出 curl 的 SOCKS5 参数
        # If a proxy is set, output the SOCKS5 argument for curl
        echo "--socks5-hostname ${proxy_address}"
    fi
}


#==============================================================================
# 函数: _initialize_theme_engine() [修正版]
# 功能: 初始化主题引擎，使用简化的代理逻辑获取 MOTD。
# Function: _initialize_theme_engine() [Corrected Version]
# Purpose: Initializes the theme engine, using the simplified proxy logic to fetch MOTD.
#==============================================================================
_initialize_theme_engine() {
    local theme_file="${ETC_CORIUM_DIR}/theme.conf"
    if [[ -r "$theme_file" ]]; then
        while IFS='=' read -r key value; do
            key=$(echo "$key" | tr -d '[:space:]')
            value=$(echo "$value" | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')
            if [[ -n "$key" && -n "$value" ]]; then THEME_COLORS_CACHE["$key"]="$value"; fi
        done < <(sed -n '/\[colors\]/,/\[.*\]/p' "$theme_file" | grep '=')
    fi

    local motd_enabled=$(grep -oP '(?<=motd\.enabled=).*' "$theme_file" 2>/dev/null || echo "true")
    if [[ "$motd_enabled" != "true" ]]; then return 0; fi
    
    local motd_cache_file="${VAR_CACHE_CORIUM_DIR}/.motd_cache"
    if [[ -f "$motd_cache_file" ]] && ! find "$motd_cache_file" -mmin "+60" -print | grep -q .; then return 0; fi
    mkdir -p "$VAR_CACHE_CORIUM_DIR" && touch "$motd_cache_file"

    local motd_type=$(grep -oP '(?<=motd\.type=).*' "$theme_file" 2>/dev/null || echo "random")
    if [[ "$motd_type" == "random" ]]; then ((RANDOM % 2 == 0)) && motd_type="cat" || motd_type="oneliner"; fi

    local motd_output=""
    if [[ "$motd_type" == "oneliner" ]]; then
        # [修正] 直接调用 curl，并使用新的辅助函数获取代理参数
        # [CORRECTION] Call curl directly, using the new helper to get proxy arguments
        local proxy_args=$(_get_proxy_args_for_curl)
        local hitokoto_json=$(curl -L --connect-timeout 10 -sS ${proxy_args} "https://v1.hitokoto.cn/?encode=json&charset=utf-8")
        
        if [[ $? -eq 0 && -n "$hitokoto_json" ]]; then
            local hitokoto=$(echo "$hitokoto_json" | grep -oP '(?<="hitokoto":").*?(?=")')
            local from=$(echo "$hitokoto_json" | grep -oP '(?<="from":").*?(?=")')
            motd_output="“${hitokoto}” -- ${from}"
        fi
    elif [[ "$motd_type" == "cat" ]]; then
        local cats=(' /\\_/\\ \n( o.o )\n > ^ < ' ' /\\_/\\ \n( >.< )\n  ” ” ')
        motd_output=${cats[$((RANDOM % ${#cats[@]}))]}
    fi

    if [[ -n "$motd_output" ]]; then
        echo; _apply_theme "motd" "$motd_output"; echo
    fi
}


#==============================================================================
# 函数: corix_theme_init() [最终默认值版]
# 功能: 在正确的、网络特定的 ETC_CORIUM_DIR 中幂等地初始化一个功能完整的、
#       包含与旧版颜色兼容的默认值的 theme.conf 文件。
#
# Function: corix_theme_init() [Final Defaults Version]
# Purpose: Idempotently initializes a full-featured theme.conf with backward-compatible
#          default colors in the correct, network-specific ETC_CORIUM_DIR.
#==============================================================================
corix_theme_init() {
    local theme_file="${ETC_CORIUM_DIR}/theme.conf"
    if [[ ! -f "$theme_file" ]]; then
        _apply_theme "info" "主题配置文件未找到, 正在为您创建一份默认配置... / Theme config not found, creating a default for you..." >&2
        
        # 使用 cat 和 EOF 创建一个包含完整注释和默认值的文件
        # Use cat and EOF to create a file with full comments and default values
        cat > "$theme_file" <<'EOF'
# Corium Theme Configuration File
# Corium 主题配置文件 (Network: ${CORIUM_NETWORK_ID})
#
# 您可以在这里自定义 Corium 命令行界面的所有颜色。
# You can customize all colors of the Corium CLI here.
#
# 颜色格式 / Color Format:
#   - 标准 ANSI 转义码, 例如: \e[1;32m (粗体绿色)
#     Standard ANSI escape codes, e.g., \e[1;32m (bold green)
#   - 256色代码, 例如: \e[38;5;81m (一种漂亮的蓝色)
#     256-color codes, e.g., \e[38;5;81m (a nice blue)

[colors]
# --------------------------------------------------------------------
# --- [默认颜色主题] 此主题旨在与旧版 Corium 的硬编码颜色保持一致 ---
# --- [DEFAULT THEME] This theme is designed to be consistent with   ---
# ---               the hardcoded colors of older Corium versions.   ---
# --------------------------------------------------------------------

# 主要颜色，用于标题、重要标识等
# Primary color, used for titles, important identifiers, etc.
primary=\e[1;34m

# 强调色，用于次要标题或高亮
# Accent color, for subheadings or highlights.
accent=\e[1;36m

# 普通信息 (info)
# General information (info)
info=\e[1;34m

# 警告信息 (warn)
# Warning messages (warn)
warn=\e[1;33m

# 错误信息 (error)
# Error messages (error)
error=\e[1;31m

# 成功信息 (success)
# Success messages (success)
success=\e[1;32m

# 调试信息 (debug)，通常使用低调的颜色
# Debug messages (debug), usually in a discreet color.
debug=\e[0;35m

# 每日消息 (MOTD) 的颜色
# Color for the Message of the Day (MOTD).
motd=\e[0;36m

[motd]
# 是否启用每日消息 / Enable Message of the Day
# 可选值 / Options: true | false
enabled=true

# MOTD 的类型 / Type of MOTD
# 可选值 / Options: oneliner (一言), cat (ASCII猫), random (随机)
type=random

# MOTD 的来源 (仅当 type=oneliner 时有效)
# Source for MOTD (only for type=oneliner)
source=hitokoto
EOF
    fi
}

#==============================================================================
# 函数: _apply_theme() [最终管道版本 - 已激活]
# 功能: 实现了美化系统的基础层与扩展层。优先通过 Mod 管道处理文本。
# Function: _apply_theme() [Final Pipeline Version - Activated]
# Purpose: Implements both base and extension layers of the theming system. Prioritizes text processing through the Mod pipeline.
#==============================================================================
_apply_theme() {
    local style_name="$1"
    local initial_text="$2"
    local processed_text="$initial_text"

    # --- 1. 主题渲染管道 (已激活) ---
    # Theming Render Pipeline (Now Activated)
    local active_theme_mods
    active_theme_mods=$(_get_active_mods "theme") || true

    if [[ $? -eq 0 && -n "$active_theme_mods" ]]; then
        # 读取 _get_active_mods 输出的 "<mod_name> <executable_path>" 列表
        # Read the "<mod_name> <executable_path>" list output by _get_active_mods
        while IFS=' ' read -r mod_name mod_path; do
            # 调用我们全新的、基于文件清单的沙箱引擎
            # Call our new, manifest-based sandbox engine
            # Mod 的约定：从 stdin 读取文本，向 stdout 输出处理后的文本。
            # Mod convention: read text from stdin, write processed text to stdout.
            processed_text=$(echo "$processed_text" | _execute_mod_in_sandbox "$mod_name" "theme" "$mod_path" "theme_apply" "$style_name")
        done <<< "$active_theme_mods"
    fi

    # --- 2. 内置渲染回退逻辑 (逻辑不变) ---
    # Fallback to Built-in Rendering Engine (logic unchanged)
    if [[ "$processed_text" == "$initial_text" ]]; then
        # Mod 未对文本做任何处理，使用内置 theme.conf
        # Mods did not process the text, use built-in theme.conf
        local color_code=${THEME_COLORS_CACHE[$style_name]:-}
        if [[ -z "$color_code" ]]; then
            echo -e "$initial_text"
        else
            echo -e "${color_code}${initial_text}${COLOR_RESET}"
        fi
    else
        # Mod 已处理文本，直接输出其最终结果。脚本的 EXIT trap 会保证最终的颜色重置。
        # Mods have processed the text. Output their final result directly. The script's EXIT trap will guarantee the final color reset.
        echo -e "$processed_text"
    fi
}

#==============================================================================
# 函数: corix_theme() [最终修正版]
# 功能: corix theme 主命令，所有路径都与权威定义一致。
# Function: corix_theme() [Final Corrected Version]
# Purpose: The main corix theme command, with all paths aligned to authoritative definitions.
#==============================================================================
corix_theme() {
    local subcommand="$1"
    # [修正] 使用您定义的权威 ETC_CORIUM_DIR 变量。
    # [CORRECTION] Using the authoritative ETC_CORIUM_DIR variable you defined.
    local theme_file="${ETC_CORIUM_DIR}/theme.conf"
    corix_theme_init >/dev/null

    case "$subcommand" in
        set)
            local key="$2"
            local value="$3"
            if [[ -z "$key" || -z "$value" ]]; then _apply_theme "error" "错误: 'set' 命令需要 key 和 value. / Error: 'set' command requires a key and a value."; return 1; fi
            if grep -q "^${key}=" "$theme_file"; then sed -i "s|^${key}=.*|${key}=${value}|" "$theme_file"; else
                if [[ "$key" == motd.* ]]; then sed -i "/\[motd\]/a\\${key}=${value}" "$theme_file"; else sed -i "/\[colors\]/a\\${key}=${value}" "$theme_file"; fi
            fi
            _apply_theme "success" "✅ 主题设置已更新 / Theme setting updated: ${key} -> ${value}"
            ;;
        list)
            _apply_theme "primary" "--- 当前主题配置 (网络: ${CORIUM_NETWORK_ID}) ---"
            _apply_theme "info" "文件路径: ${theme_file}"
            while IFS= read -r line; do
                if [[ "$line" =~ ^\[.*\]$ ]]; then _apply_theme "accent" "$line";
                elif [[ "$line" =~ = ]]; then printf "%s=%s\n" "$(_apply_theme 'primary' "$(echo "$line" | cut -d'=' -f1)")" "$(_apply_theme 'info' "$(echo "$line" | cut -d'=' -f2-)")";
                else _apply_theme "debug" "$line"; fi
            done < "$theme_file"
            ;;
        preview)
            _apply_theme "primary" "--- 主题预览 (网络: ${CORIUM_NETWORK_ID}) ---"
            _initialize_theme_engine > /dev/null
            _apply_theme "primary" "这是 'primary' 样式的文本 / This is 'primary' style text."
            _apply_theme "accent" "这是 'accent' 样式的文本 / This is 'accent' style text."
            _apply_theme "info" "这是 'info' 样式的文本 / This is 'info' style text."
            _apply_theme "warn" "这是 'warn' 样式的文本 / This is 'warn' style text."
            _apply_theme "error" "这是 'error' 样式的文本 / This is 'error' style text."
            _apply_theme "success" "这是 'success' 样式的文本 / This is 'success' style text."
            _apply_theme "debug" "这是 'debug' 样式的文本 / This is 'debug' style text."
            _apply_theme "motd" "这是 'motd' 样式的文本 / This is 'motd' style text."
            ;;
        import)
            local url="$2"
            if [[ -z "$url" ]]; then _apply_theme "error" "错误: 'import' 命令需要一个 URL. / Error: 'import' command requires a URL."; return 1; fi
            _apply_theme "info" "正在从 URL 导入主题... / Importing theme from URL..."
            
            # [修正] 直接调用 curl，并使用新的辅助函数获取代理参数
            # [CORRECTION] Call curl directly, using the new helper to get proxy arguments
            local proxy_args=$(_get_proxy_args_for_curl)
            local new_theme_content=$(curl -L --connect-timeout 10 -sS ${proxy_args} "$url")

            if [[ $? -ne 0 || -z "$new_theme_content" || ! "$new_theme_content" =~ \[colors\] ]]; then
                _apply_theme "error" "❌ 导入失败。URL 无效或内容不是主题文件。 / Import failed. Invalid URL or content is not a theme file."; return 1; fi
            
            local theme_file="${ETC_CORIUM_DIR}/theme.conf"
            echo "$new_theme_content" > "$theme_file"
            _apply_theme "success" "✅ 主题已成功导入到网络 '${CORIUM_NETWORK_ID}'！ / Theme successfully imported to network '${CORIUM_NETWORK_ID}'!"
            ;;
        random)
            _apply_theme "info" "正在为网络 '${CORIUM_NETWORK_ID}' 生成随机主题... / Generating random theme for network '${CORIUM_NETWORK_ID}'..."
            local color_keys=("primary" "accent" "info" "warn" "error" "success" "motd")
            for key in "${color_keys[@]}"; do sed -i "s|^${key}=.*|${key}=\\e[38;5;$((RANDOM % 256))m|" "$theme_file"; done
            _apply_theme "success" "🎨 新的随机主题已生成！ / New random theme generated!"
            corix_theme "preview"
            ;;
        *)
            _apply_theme "primary" "Corium 主题管理 / Corium Theme Management"
            _apply_theme "info" "用法: corix theme [子命令] / Usage: corix theme [subcommand]"
            echo; _apply_theme "accent" "子命令 / Subcommands:"
            _apply_theme "primary" "  set <key> <value>   - 为当前网络设置主题键值 / Set a theme key-value for the current network."
            _apply_theme "primary" "  list                  - 列出当前网络的主题配置 / List the current network's theme configuration."
            _apply_theme "primary" "  preview               - 预览当前网络的主题效果 / Preview the current network's theme effects."
            _apply_theme "primary" "  import <url>          - 为当前网络导入主题 / Import a theme for the current network."
            _apply_theme "primary" "  random                - 为当前网络生成随机主题 / Generate a random theme for the current network."
            ;;
    esac
}

# =======================================================================================
# --- [V78 Gen3 START] 应用模板治理命令行接口 (App Template Governance CLI)         ---
# =======================================================================================

# --- 应用模板 帮助函数 ---
# --- App Template Help Function ---
usage_app() {
cat <<'EOF'
corix app: Manage 3rd-generation, dynamically loaded Application Templates.
corix app: 管理第三代的、动态加载的应用模板。

Usage: corix app <subcommand> [arguments...]
用法:  corix app <子命令> [参数...]

Subcommands (子命令):
  propose --pkg-id <id> [--name <template_name>]
                                 Propose a new Application Template to the network.
                                 (向网络提议一个新的应用模板)
                                 The package must be built and published to P2P first.
                                 (该软件包必须已被构建并发布到P2P网络)

  vote <proposal_hash> <yes|no>  Vote on an active Application Template proposal.
                                 (对一个进行中的应用模板提案进行投票)

  list [--all]                   List all activated Application Templates on this chain.
                                 (列出此链上所有已激活的应用模板)
EOF
}

# --- 应用模板 主分发器 ---
# --- App Template Main Dispatcher ---
corix_app() {
    acquire_lock "network"
    trap 'release_lock "network"' RETURN
    
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        propose)
            local pkg_id="" template_name=""
            while [ $# -gt 0 ]; do
                case "$1" in
                    --pkg-id) pkg_id="$2"; shift 2 ;;
                    --name) template_name="$2"; shift 2 ;;
                    *) error "app propose: Unknown option '$1' / 未知选项 '$1'";;
                esac
            done

            [ -z "$pkg_id" ] && { usage_app; exit 1; }
            [ -z "$template_name" ] && template_name=$(get_pkg_id_parts "$pkg_id"; echo "$PKG_NAME")

            # 1. 验证软件包是否已安装在本地 (这是获取其P2P哈希的最可靠方式)
            # 1. Verify the package is installed locally (most reliable way to get its P2P hash)
            if ! db_is_installed "$pkg_id"; then
                error "软件包 '${pkg_id}' 未在本地安装。请先构建并安装它。/ Package '${pkg_id}' is not installed locally. Please build and install it first."
                return 1
            fi

            # 2. 获取真正的二进制包和元数据
            # 2. Get the real binary package and metadata
            local pkg_dir; pkg_dir=$(get_pkg_id_parts "$pkg_id"; db_get_pkg_dir "${PKG_CATEGORY}/${PKG_NAME}" "$PKG_SLOT")
            local build_file="${pkg_dir}/build_file"
            
            # 找到最新的二进制包和签名 (Find the latest binary package and signature)
            local binary_pkg_path
            binary_pkg_path=$(ls -t "${BINARY_CACHE}/${PKG_CATEGORY}_${PKG_NAME}-"*.corix.tar.* 2>/dev/null | head -n 1)
            [ -z "$binary_pkg_path" ] && { error "未找到二进制包，请先运行 corix build。/ Binary package not found, run corix build first."; return 1; }
            
            local package_hash; package_hash=$(calculate_hash "$binary_pkg_path")
            
            info "正在将二进制包上传至 P2P 网络... / Uploading binary package to P2P network..."
            local manifest_hash; manifest_hash=$(_p2p_upload_file "$binary_pkg_path")
            [ -z "$manifest_hash" ] && { error "上传失败，请检查 P2P 网络。/ Upload failed, please check P2P network."; return 1; }
            
            local developer_signature=""
            if [ -f "${binary_pkg_path}.sig.gpg" ]; then
                developer_signature=$(base64 -w0 < "${binary_pkg_path}.sig.gpg")
            else
                warn "未找到二进制包的签名文件，提案将不包含签名。/ Signature file not found, proposal will not include a signature."
            fi

            msg "正在为应用模板 '${template_name}' (${pkg_id}) 构造提案... / Constructing proposal for App Template '${template_name}' (${pkg_id})..."
            
            # 3. 构造交易载荷
            # 3. Construct transaction payload
            
            # 从 .build 文件中解析出 handles_tx_types
            local handles_tx_types_str
            handles_tx_types_str=$(grep -oP '(?<=handles_tx_types=\().*?(?=\))' "$build_file" | tr -d '"')
            local handles_tx_types_json
            handles_tx_types_json=$(echo "$handles_tx_types_str" | jq -R -s 'split(" ") | map(select(length > 0))')
            
            local tx_data
            tx_data=$(jq -n \
                --arg name "$template_name" \
                --arg pid "$pkg_id" \
                --arg phash "$package_hash" \
                --arg mhash "$manifest_hash" \
                --arg sig "$developer_signature" \
                --arg developer "$(get_our_node_id)" \
                --argjson types "$handles_tx_types_json" \
                '{template_name: $name, pkg_id: $pid, package_hash: $phash, manifest_hash: $mhash, developer_signature: $sig, developer_id:$developer, handles_tx_types: $types}')

            # 4. 提交交易
            # 4. Submit the transaction
            local tx_hash; tx_hash=$(blockchain_create_transaction "propose_app_template" "$tx_data")
            if [ -n "$tx_hash" ]; then
                msg "应用模板提案已成功提交！/ App Template proposal submitted successfully!"
                info "  交易哈希 / Transaction Hash: ${tx_hash}"
            else
                error "提交提案失败。 / Failed to submit proposal."
            fi
            ;;
        vote)
            [ $# -ne 2 ] && { usage_app; exit 1; }
            local proposal_hash="$1" vote_choice="$2"
            [[ "$vote_choice" =~ ^(yes|no)$ ]] || { error "Vote must be 'yes' or 'no'. / 投票必须是 'yes' 或 'no'。"; exit 1; }

            local tx_data; tx_data=$(jq -n --arg hash "$proposal_hash" --arg vote "$vote_choice" '{proposal_tx_hash: $hash, vote: $vote}')
            info "正在为提案 ${proposal_hash:0:16} 投出 '${vote_choice}' 票... / Casting '${vote_choice}' vote for proposal ${proposal_hash:0:16}..."
            blockchain_create_transaction "vote_app_template" "$tx_data"
            ;;
        list)
            _update_chain_state_cache >/dev/null 2>&1
            msg "已激活的应用模板 / Activated Application Templates"
            echo "--------------------------------------------------------------------------------"
            db_query_static "$BLOCKCHAIN_DB" "SELECT template_name, pkg_id, developer_id, activation_height FROM active_app_templates ORDER BY activation_height;" | while IFS='|' read -r name pid dev_id height; do
                echo -e "\033[1;32m模板名称 / Template Name:\033[0m ${name}"
                echo "  - 软件包ID / Package ID: ${pid}"
                echo "  - 开发者 / Developer:  ${dev_id}"
                echo "  - 激活于区块 / Activated at Block: ${height}"
            done
            echo "--------------------------------------------------------------------------------"
            ;;
        *)
            usage_app
            ;;
    esac
}

usage_network() {
    echo "corix network: Interact with and query the on-chain node directory."
    echo "corix network: 与链上节点目录进行交互和查询。"
    echo
    echo "Usage: corix network <subcommand>"
    echo "用法:  corix network <子命令>"
    echo
    echo "Subcommands (子命令):"
    echo "  status [--active-within <blocks>]  Show network statistics from the on-chain directory."
    echo "                                     (从链上目录显示网络统计信息)"
    echo "                                     --active-within: Define 'active' as having sent a heartbeat within the last N blocks (default: 2880, approx. 24 hours)."
    echo "                                                      (定义“活跃”为在过去 N 个区块内发送过心跳 (默认为2880，约24小时))"
    echo
    echo "  announce                             (First time only) Announce your node to the on-chain directory."
    echo "                                     ((仅限首次) 将您的节点宣告到链上目录)"
    echo
    echo "  heartbeat                            Send a liveness heartbeat to keep your node in the active list."
    echo "                                     (发送一次存活心跳，以保持您的节点位于活跃列表)"
}

# =======================================================================================
# --- [V105.6 HEARTBEAT] 新增网络状态命令                                             ---
# --- [V105.6 HEARTBEAT] NEW Network Status Commands                                  ---
# =======================================================================================
corix_network() {
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        announce)
            acquire_lock "network"
            trap 'release_lock "network"' RETURN

            local my_id; my_id=$(get_our_node_id)
            local existing_record; existing_record=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT 1 FROM node_directory WHERE node_id = %s;" "$my_id")
            if [ -n "$existing_record" ]; then
                warn "您的节点已在链上宣告过。请使用 'heartbeat' 命令来更新您的在线状态。"
                warn "Your node has already been announced on-chain. Please use the 'heartbeat' command to update your liveness status."
                return 1
            fi

            local p2p_addresses; p2p_addresses=$(_discover_network_identities)
            local p2p_addresses_json; p2p_addresses_json=$(echo "$p2p_addresses" | tr '|' '\n' | jq -R -s 'split("\n") | map(select(length > 0))')
            
            local tx_data; tx_data=$(jq -n --argjson addrs "$p2p_addresses_json" '{p2p_addresses: $addrs}')
            
            info "正在提交您的节点宣告交易... / Submitting your node announcement transaction..."
            blockchain_create_transaction "node_announce" "$tx_data"
            ;;

        heartbeat)
            acquire_lock "network"
            trap 'release_lock "network"' RETURN

            info "正在提交您的节点心跳交易... / Submitting your node heartbeat transaction..."
            # 心跳交易的 payload 可以为空，因为发送者身份已经包含了所有需要的信息
            # The heartbeat transaction payload can be empty, as the sender's identity contains all the necessary information.
            blockchain_create_transaction "node_heartbeat" "{}"
            ;;

        status)
            # 这是一个只读命令，不需要锁
            _update_chain_state_cache >/dev/null 2>&1

            local active_threshold=2880 # 约 24 小时 (假设 30 秒/区块)
            if [ "${1:-}" = "--active-within" ] && [ -n "${2:-}" ]; then
                active_threshold="$2"
            fi
            
            msg "Corium 网络状态 (来自链上黄页) / Corium Network Status (from On-Chain Directory)"
            echo "--------------------------------------------------"
            
            local total_nodes; total_nodes=$(db_query_static "$BLOCKCHAIN_DB" "SELECT COUNT(*) FROM node_directory;")
            local current_height; current_height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT MAX(height) FROM blocks;")
            local active_nodes; active_nodes=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT COUNT(*) FROM node_directory WHERE last_heartbeat_height >= %d;" "$((current_height - active_threshold))")
            
            echo -e "  已注册节点总数 / Total Registered Nodes: \033[1;33m${total_nodes:-0}\033[0m"
            echo -e "  活跃节点数 / Active Nodes (last ${active_threshold} blocks): \033[1;32m${active_nodes:-0}\033[0m"
            echo "--------------------------------------------------"
            ;;
            
        *)
            usage_network
            ;;
    esac
}


# Displays a comprehensive status of the Corium system, including network health.
# 显示 Corium 系统的综合状态，包括网络健康状况。
corix_status() {
    # This is a read-only command and does not require a lock.
    # 这是一个只读命令，不需要锁。
    msg "Corium 系统状态 / Corium System Status"
    echo "--------------------------------------------------"
    
    # --- 身份与网络 / Identity & Network ---
    info "身份与网络 / Identity & Network"
    local node_id
    node_id=$(get_our_node_id)
    echo "  节点ID / Node ID: ${node_id}"
    echo "  公网 IP:端口 / Public IP:Port: ${PUBLIC_IP:-Unknown}:${PUBLIC_PORT:-Unknown} (由STUN发现 / Discovered by STUN)"
    echo "  NAT 类型 / NAT Type: ${NAT_TYPE:-Unknown} (由STUN发现 / Discovered by STUN)"
    
    local dht_peers
    dht_peers=$(db_query_static "$DHT_DB" "SELECT COUNT(*) FROM nodes;" 2>/dev/null || echo 0)
    echo "  已知 DHT 节点数 / Known DHT Peers: ${dht_peers}"

    # --- [新增] 网络连接性与延迟检查 ---
    # --- [NEW] Network Connectivity & Latency Check ---
    info "网络连接性检查 (最多等待5秒)... / Network Connectivity Check (waiting up to 5s)..."
    local reachable_peers=0
    local total_latency=0
    local pids_and_files=()
    
    # Ping up to 5 random peers from our routing table
    # 从我们的路由表中随机 Ping 最多5个节点
    db_query_static "$DHT_DB" "SELECT ip, port FROM nodes ORDER BY RANDOM() LIMIT 5;" 2>/dev/null | while IFS='|' read -r ip port; do
        local temp_file; temp_file=$(mktemp)
        temp_files+=("$temp_file")
        (
            local start_time end_time latency
            start_time=$(date +%s%N)
            if dht_send_message "$ip" "$port" "PING" >/dev/null; then
                end_time=$(date +%s%N)
                latency=$(((end_time - start_time) / 1000000))
                echo "$latency" > "$temp_file"
            fi
        ) &
        pids+=("$!")
    done
    
    # Waiting for all pings to complete with timeout
    # 等待所有 ping 完成，带有超时
    wait_all 5 "${pids[@]}"
    
    # Collect results
    # 收集结果
    for file in "${temp_files[@]}"; do
        if [ -s "$file" ]; then # -s checks if file is not empty
            local lat; lat=$(cat "$file")
            reachable_peers=$((reachable_peers + 1))
            total_latency=$((total_latency + lat))
        fi
        rm -f "$file"
    done


    if [ "$reachable_peers" -gt 0 ]; then
        local avg_latency=$((total_latency / reachable_peers))
        echo -e "  连接性 / Connectivity: \033[1;32m良好 (Good)\033[0m - ${reachable_peers} 个节点可达 / peers reachable"
        echo "  平均延迟 / Average Latency: ${avg_latency} ms"
    else
        echo -e "  连接性 / Connectivity: \033[1;31m差 (Poor)\033[0m - 无法访问任何节点 / no peers reachable"
    fi
    
    # --- 区块链 / Blockchain ---
    info "区块链 / Blockchain"
    local latest_hash latest_height
    latest_hash=$(blockchain_get_latest_hash)
    latest_height=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT height FROM blocks WHERE hash = %s;" "$latest_hash" 2>/dev/null || echo "?")
    echo "  最新区块高度 / Latest Block Height: ${latest_height}"
    echo "  最新区块哈希 / Latest Block Hash: ${latest_hash:0:32}..."
    local pending_tx
    pending_tx=$(db_query_static "$BLOCKCHAIN_DB" "SELECT COUNT(*) FROM transactions WHERE block_height IS NULL;" 2>/dev/null || echo 0)
    echo "  待处理交易 / Pending Transactions: ${pending_tx}"

    # --- 系统状态 / System State ---
    info "系统状态 / System State"
    local installed_count
    installed_count=$(find "$INSTALLED_DB" -mindepth 2 -maxdepth 2 -type d 2>/dev/null | wc -l)
    echo "  已安装包数量 / Installed Packages: ${installed_count}"
    local strata_count
    strata_count=$(find "$STRATA_DIR" -mindepth 1 -maxdepth 1 -type d 2>/dev/null | wc -l)
    echo "  已管理 Strata 数量 / Managed Strata: ${strata_count}"
    echo "--------------------------------------------------"
}

# Verifies a local binary package against the blockchain record.
# 对照区块链记录来验证一个本地的二进制包。
#
# @param $1 - path_to_package (The local path to the .corix.tar.zst/.gz file / 本地 .corix.tar.zst/.gz 文件的路径)
corix_verify() {
    local pkg_file="$1"
    [ ! -f "$pkg_file" ] && error "File not found: ${pkg_file} / 未找到文件: ${pkg_file}"
    
    msg "Verifying local package file: $(basename "$pkg_file") / 正在验证本地软件包文件: $(basename "$pkg_file")"

    # 1. Parse filename to get metadata
    # 1. 解析文件名以获取元数据
    local filename pkg_base_name pkg_ver pkg_slot pkg_name
    filename=$(basename "$pkg_file")
    if [[ "$filename" =~ ^(.*)-([0-9].*)-([0-9]+)-.*\.corix\.tar\..*$ ]]; then
        pkg_base_name="${BASH_REMATCH[1]}"
        pkg_ver="${BASH_REMATCH[2]}"
        pkg_slot="${BASH_REMATCH[3]}"
        pkg_name=$(echo "$pkg_base_name" | tr '_' '/')
    else
        error "Could not parse package name and version from filename. / 无法从文件名中解析包名和版本。"
        return 1
    fi
    info "Parsed Info / 解析信息: Name=${pkg_name}, Version=${pkg_ver}, Slot=${pkg_slot}"

    # 2. Calculate hash of the local file
    # 2. 计算本地文件的哈希值
    info "Calculating local file hash... / 正在计算本地文件哈希..."
    local local_hash
    local_hash=$(calculate_hash "$pkg_file")
    detail "  -> Local Hash / 本地哈希: ${local_hash}"
    
    # 3. Verify against the blockchain
    # 3. 对照区块链进行验证
    info "Querying blockchain for matching record... / 正在查询区块链以查找匹配记录..."
    if blockchain_verify_package "$pkg_name" "$pkg_ver" "$local_hash"; then
        msg "SUCCESS: The package file is authentic and matches the blockchain record. / 成功: 软件包文件真实有效，与区块链记录匹配。"
    else
        error "FAILURE: The package file is either tampered with or not registered on the blockchain. / 失败: 软件包文件可能被篡改，或未在区块链上注册。"
    fi
}

usage_blockchain() {
    echo "Usage: corix blockchain <subcommand> / 用法: corix blockchain <子命令>"
    echo "  mempool     Show transactions waiting to be mined. / 显示等待被打包的交易。"
    echo "  export-state <height> <file> [--new-validators <keys...>]"
    echo "              (灾难恢复) 导出链在指定高度的状态为创世文件。"
    echo "              (Disaster Recovery) Export chain state at a specific height to a genesis file."
    echo "  verify-state"
    echo "              [Batch 5] 生成当前全网共识状态的哈希根 (Consensus State Root)。"
    # --- [V105.5 WSC TOOL] 新增用法说明 ---
    # --- [V105.5 WSC TOOL] Add new usage instruction ---
    echo "  info --height <height>"
    echo "              (安全工具) 获取指定高度区块的详细信息，用于验证检查点。"
    echo "              (Security Tool) Get detailed information for a block at a specific height, used for verifying checkpoints."
}

# =======================================================================================
# --- [V105.5 WSC TOOL] corix_blockchain (已扩展检查点验证工具)                     ---
# --- [V105.5 WSC TOOL] corix_blockchain (Extended with Checkpoint Verification Tool) ---
# =======================================================================================
# Command dispatcher for 'corix blockchain'
# 'corix blockchain' 的命令分发器
corix_blockchain() {
    local sub_cmd="${1:-}"
    shift || true
    case "$sub_cmd" in
        mempool)
            msg "Pending Transactions (Mempool) / 待处理交易 (交易池)"
            echo "------------------------------------"
            blockchain_get_pending_transactions | while IFS='|' read -r hash type data signature public_key timestamp; do
                echo -e "  \033[1;32mTx Hash\033[0m: ${hash:0:32}..."
                echo "  Type: ${type}"
                echo "  From: $(_internal_hash_text "$public_key")"
                echo "  Data: $(echo "$data" | jq -c .)"
                echo
            done
            ;;
        export-state)
            { [ $# -eq 2 ] || { [ $# -eq 4 ] && [ "${3:-}" = --new-validators ]; }; } || { usage_blockchain; return 1; }
            local block_height="$1"
            local output_file="$2"
            local new_validators_str=""
            if [ "${3:-}" = "--new-validators" ]; then
                new_validators_str="${4:-}"
            fi
            
            _internal_export_chain_state "$block_height" "$output_file" "$new_validators_str"
            ;;
            
        verify-state)
            [ $# -eq 0 ] || return 1
            local semantic_state state_root
            semantic_state=$(_internal_semantic_state) || return 1
            state_root=$(printf '%s' "$semantic_state" | calculate_hash) || return 1
            printf 'Consensus State Root / 规范状态根: %s\n' "$state_root"
            printf '%s\n' "$state_root" > "${VAR_LIB_CORIUM_DIR}/current_state_root.txt"
            ;;

        # --- [V105.5 WSC TOOL] 新增功能分支 ---
        # --- [V105.5 WSC TOOL] New functionality branch ---
        info)
            local block_height=""
            if [ "${1:-}" = "--height" ] && [ -n "${2:-}" ]; then
                block_height="$2"
            else
                usage_blockchain
                exit 1
            fi

            # 确保输入的高度是数字
            if ! [[ "$block_height" =~ ^[0-9]+$ ]]; then
                error "错误: 区块高度必须是一个非负整数。 / Error: Block height must be a non-negative integer."
                exit 1
            fi

            info "正在查询区块 #${block_height} 的信息... / Querying information for block #${block_height}..."

            # 一次性从数据库查询出所有需要的字段
            local block_info
            block_info=$(db_query_safe "$BLOCKCHAIN_DB" \
                "SELECT hash, previous_hash, timestamp, validator, total_weight, transactions FROM blocks WHERE height = %d;" \
                "$block_height")

            if [ -z "$block_info" ]; then
                error "错误: 在本地链上未找到区块 #${block_height}。 / Error: Block #${block_height} not found on the local chain."
                return 1
            fi

            local hash prev_hash timestamp validator total_weight transactions_json
            IFS='|' read -r hash prev_hash timestamp validator total_weight transactions_json <<< "$block_info"
            
            local tx_count
            tx_count=$(echo "$transactions_json" | jq 'length')

            # 以清晰、人类可读的格式输出信息
            echo "--------------------------------------------------"
            _apply_theme "accent" "区块信息 / Block Information"
            echo "--------------------------------------------------"
            _apply_theme "primary" "  高度 / Height:         \033[1;33m${block_height}\033[0m"
            _apply_theme "primary" "  哈希 / Hash:             \033[1;33m${hash}\033[0m"
            _apply_theme "info"    "  父哈希 / Previous Hash:  ${prev_hash}"
            _apply_theme "info"    "  时间戳 / Timestamp:      ${timestamp} ($(date -u -d "@$timestamp" '+%Y-%m-%d %H:%M:%S %Z'))"
            _apply_theme "info"    "  验证者 / Validator:      ${validator}"
            _apply_theme "info"    "  总权重 / Total Weight:   ${total_weight}"
            _apply_theme "info"    "  交易数 / Transactions:   ${tx_count}"
            echo "--------------------------------------------------"
            ;;

        *)
            usage_blockchain
            ;;
    esac
}


# Command dispatcher for 'corix user' (extended)
# 'corix user' 的命令分发器 (扩展版)
corix_user_extended() {
    local sub_cmd="${1:-}"
    shift || true
    case "$sub_cmd" in
        set-nickname)
            [ $# -lt 1 ] && { usage_user; exit 1; }
            corix_user "$@" # Calls the original simple version / 调用原始的简单版本
            ;;
        info)
            [ $# -ne 1 ] && { echo "Usage: corix user info <user_id>"; exit 1; }
            local user_id="$1"
            _update_chain_state_cache
            local user_info=$(db_query_safe "$FORUM_DB" "SELECT nickname, type FROM identity_cache WHERE id_hash = %s;" "$user_id")
            [ -z "$user_info" ] && { error "User not found. / 未找到用户。"; exit 1; }
            IFS='|' read -r nickname type <<< "$user_info"
            
            echo -e "User Info for: \033[1;32m${user_id:0:16}...\033[0m"
            echo "  ID: ${user_id}"
            echo "  Type: ${type}"
            echo "  Nickname: ${nickname:-<not set>}"
            ;;
        block)
            [ $# -ne 1 ] && { echo "Usage: corix user block <user_id>"; exit 1; }
            db_execute_safe "$FORUM_DB" "INSERT OR IGNORE INTO local_user_blocks (blocked_id) VALUES (%s);" "$1"
            msg "用户 ${1:0:16}... 已被屏蔽。将不再显示其内容。 / User ${1:0:16}... has been blocked. Their content will no longer be displayed."
            ;;
        unblock)
            [ $# -ne 1 ] && { echo "Usage: corix user unblock <user_id>"; exit 1; }
            db_execute_safe "$FORUM_DB" "DELETE FROM local_user_blocks WHERE blocked_id = %s;" "$1"
            msg "用户 ${1:0:16}... 已被解除屏蔽。 / User ${1:0:16}... has been unblocked."
            ;;
        *)
            usage_user_extended
            ;;
    esac
}
