# =======================================================
# --- corix_p2p (MERGED & FINAL VERSION)              ---
# --- 第XX节: corix_p2p (合并后的最终版本)            ---
# =======================================================

# This version combines the superior 'add-peer' logic from V2 
# with the 'share-identity' command from V1, creating a complete and functional command.
# 此版本结合了 V2 中更优越的 'add-peer' 逻辑和 V1 中的 'share-identity' 命令，
# 从而创建了一个功能完整且正确的命令。
corix_p2p() {
    local sub_cmd="${1:-}"
    shift || true
    case "$sub_cmd" in
        list-peers)
            msg "Known DHT Peers (from local routing table) / 已知 DHT 节点 (来自本地路由表)"
            db_query_static "$DHT_DB" "SELECT id, address, port, last_seen FROM nodes ORDER BY last_seen DESC;" | while IFS='|' read -r id ip port last_seen; do
                echo "  - ${id:0:16}... @ ${ip}:${port} (Last seen: $(date -d "@$last_seen"))"
            done
            ;;
        add-peer)
            [ $# -ne 1 ] && { echo "Usage: corix p2p add-peer <ip:port_or_identity_string>"; exit 1; }
            local peer_str="$1"
            local ip port node_id
            if [[ "$peer_str" == *@* ]]; then
                # 新格式: node_id@ip:port (来自 'share-identity')
                # New format: node_id@ip:port (from 'share-identity')
                node_id="${peer_str%%@*}"
                local ipport="${peer_str#*@}"
                ip="${ipport%:*}"
                port="${ipport##*:}"
                ip="${ip#[}"; ip="${ip%]}"
                dht_add_node "$node_id" tcp "$ip" "$port" || return 1
                msg "已通过邀请码直接添加节点 / Peer added directly from identity string."
                dht_send_message "$ip" "$port" "PING" >/dev/null # 尝试 Ping 一下 / Try to ping
            else
                # 旧格式: ip:port (为了向后兼容和手动添加)
                # Old format: ip:port (for backward compatibility and manual adding)
                ip="${peer_str%:*}"; port="${peer_str##*:}"
                ip="${ip#[}"; ip="${ip%]}"
                [[ "$port" =~ ^[0-9]{1,5}$ ]] && [ "$port" -gt 0 ] && [ "$port" -le 64535 ] || return 1
                local bootstrap_id
                bootstrap_id=$(_internal_hash_text "tcp:$ip:$port")
                dht_add_node "$bootstrap_id" tcp "$ip" "$port" || return 1
                info "正在 Ping ${ip}:${port} 以获取节点 ID... / Pinging ${ip}:${port} to get Node ID..."
                local response
                response=$(dht_send_message "$bootstrap_id" "PING") || { db_execute_safe "$DHT_DB" "DELETE FROM nodes WHERE id=%s;" "$bootstrap_id"; return 1; }
                if [[ "$response" =~ ^PONG:(.+) ]]; then
                    node_id="${BASH_REMATCH[1]}"
                    [[ "$node_id" =~ ^[a-f0-9]{64}$ ]] || return 1
                    db_execute_safe "$DHT_DB" "DELETE FROM nodes WHERE id=%s;" "$bootstrap_id"
                    dht_add_node "$node_id" tcp "$ip" "$port" || return 1
                    msg "成功添加节点 ${node_id:0:16}... 到路由表。/ Peer ${node_id:0:16}... added to routing table."
                else
                    error "无法联系节点或获取有效的 PONG 响应。/ Failed to contact peer or get a valid PONG response."
                fi
            fi
            ;;
        find-providers)
            [ $# -ne 1 ] && { echo "Usage: corix p2p find-providers <object_hash>"; exit 1; }
            msg "Finding providers for object ${1:0:16}... / 正在为对象 ${1:0:16} 查找提供者..."
            dht_find_chunk "$1"
            ;;
        # --- [MERGED FROM V1] ---
        # --- [从 V1 合并而来] ---
        share-identity)
            # [V105.7 SECURITY] Add rate limit to prevent abuse of external IP discovery services.
            if ! _internal_rate_limiter_check "share_identity" 3 60; then
                error "身份分享查询过于频繁。您的IP地址短时间内不会改变。 / Identity sharing query is too frequent. Your IP address does not change rapidly."
                return 1
            fi
            local display_ip
            if [ -n "$P2P_PUBLIC_IP_OVERRIDE" ]; then
                display_ip="$P2P_PUBLIC_IP_OVERRIDE"
                info "正在使用配置文件中指定的公网IP / Using configured public_ip: ${display_ip}"
            else
                display_ip=$(get_our_ip)
            fi
            msg "您的 P2P 身份邀请码 (分享给朋友): / Your P2P Identity String (share with a friend):"
            echo -e "\033[1;32m$(get_our_node_id)@${display_ip}:$P2P_PORT\033[0m"
            ;;
        # --- [新增] P2P 不信任机制 CLI / [NEW] P2P Distrust Mechanism CLI ---
        distrust)
            [ $# -lt 1 ] && { echo "Usage: corix p2p distrust <node_id> [duration_days]"; echo "用法: corix p2p distrust <节点ID> [持续天数]"; exit 1; }
            local my_id
            my_id=$(get_our_node_id)
            local blocked_id="$1"
            local duration_days="${2:-0}" # 默认 0, 表示永久 / Default 0, means permanent
            local distrust_until=0
            
            if [[ "$duration_days" =~ ^[0-9]+$ ]] && [ "$duration_days" -gt 0 ]; then
                # 使用 date 命令安全地计算未来的时间戳
                # Use the date command to safely calculate a future timestamp
                distrust_until=$(date -d "+${duration_days} days" +%s)
            fi
            
            # 每次拉黑都会将 grievance_token_used 重置为 0，相当于授予对方一枚新的申诉权杖
            # Each block action resets grievance_token_used to 0, granting a new Grievance Token.
            db_execute_safe "$DHT_DB" "INSERT OR REPLACE INTO distrusted_peers (blocker_id, blocked_id, distrust_until, grievance_token_used) VALUES (%s, %s, %d, 0);" \
                "$my_id" "$blocked_id" "$distrust_until"
            
            local expiry_info="永久 (permanently)"
            [ "$distrust_until" -gt 0 ] && expiry_info="直到 (until) $(date -d "@$distrust_until")"
            msg "节点 ${blocked_id:0:16}... 已被您屏蔽 (${expiry_info})。"
            msg "Peer ${blocked_id:0:16}... has been blocked by you (${expiry_info})."
            ;;

        trust|unblock) # 增加一个别名 / Add an alias
            [ $# -ne 1 ] && { echo "Usage: corix p2p trust <node_id>"; echo "用法: corix p2p trust <节点ID>"; exit 1; }
            local my_id
            my_id=$(get_our_node_id)
            local blocked_id="$1"

            # 只删除由我们自己发起的屏蔽记录
            # Only delete block records initiated by us
            db_execute_safe "$DHT_DB" "DELETE FROM distrusted_peers WHERE blocker_id = %s AND blocked_id = %s;" "$my_id" "$blocked_id"
            msg "节点 ${blocked_id:0:16}... 已被您解除屏蔽。 / Peer ${blocked_id:0:16}... has been unblocked by you."
            ;;
        get)
            [ $# -lt 1 ] && { echo "Usage: corix p2p get <object_hash> [output_filename]" >&2; echo "用法: corix p2p get <对象哈希> [输出文件名]" >&2; exit 1; }
            # 此命令是底层获取机制的一个通用别名，论坛、DApp等功能都依赖它。
            # This command is a generic alias for the underlying fetch mechanism,
            # which is used by the forum, DApps, and other features.
            # 它直接调用了 forum_get_attachment，因为该函数已经实现了我们需要的功能。
            # It directly calls forum_get_attachment because that function already implements the needed functionality.
            forum_get_attachment "$@"
            ;;
        # --- [新增结束] ---
        *)
            # --- [修改] 更新帮助文本 / [MODIFIED] Update the help text ---
            echo "Usage: corix p2p <subcommand> / 用法: corix p2p <子命令>"
            echo "  get <object_hash> [file]  Download any object from the P2P network by its hash."
            echo "                          (通过哈希从 P2P 网络下载任何对象)"
            echo "  list-peers               List peers in the local DHT routing table. / 列出本地 DHT 路由表中的节点。"
            echo "  add-peer <id_string>     Manually add a peer using ip:port or the full identity string. / 使用 ip:port 或完整的身份邀请码手动添加节点。"
            echo "  find-providers <hash>    Find which peers are providing a specific data object. / 查找哪些节点正在提供一个特定的数据对象。"
            echo "  share-identity           Display your full P2P identity string to share with others. / 显示您完整的P2P身份邀请码以分享给他人。"
            echo "  distrust <node_id> [days]  Add a peer to your distrust list, blocking communication. / 将一个节点加入您的不信任列表，以屏蔽通信。"
            echo "  trust <node_id>            Remove a peer from your distrust list. / 从您的不信任列表中移除一个节点。"
            echo
            echo "网络提示 (Networking Note):"
            echo "  如果您的节点在NAT或VPS后方，自动检测的IP可能不正确。请在 corix.conf 的 [p2p] 段中设置 'public_ip = YOUR_PUBLIC_IP' 来修正。"
            ;;
    esac
}

# --- SECTION 19: SYSTEM STATE RECONSTRUCTION ---

# --- [V99 修改] _internal_rebuild_parse_world_files (新的递归解析器) ---
# --- [V99 MODIFICATION] _internal_rebuild_parse_world_files (New Recursive Parser) ---
#
# 这是一个新的内部辅助函数，用于递归地解析 world 文件及其 include 指令。
# This is a new internal helper function to recursively parse world files and their includes.
#
# @param $1 - file_path (要解析的 world 文件的路径)
# @param $2 - (内部使用) 防止循环引用的已处理文件列表
#             (Internal use) List of processed files to prevent circular includes
# =======================================================
# --- [SECURITY HARDENED] - 增加了递归深度限制和路径逃逸防御
# =======================================================
_internal_rebuild_parse_world_files() {
    local file_path="$1"
    local processed_files="${2:-}"
    local _depth="${3:-0}" # 新增：递归深度跟踪器

    # --- [安全加固] 递归深度限制 ---
    if [ "$_depth" -gt 10 ]; then
        error "安全错误：world 文件 'include' 嵌套过深 (>10层)，可能存在递归攻击。/ Security Error: World file 'include' nesting is too deep (>10 levels), possible recursion attack."
        exit 1
    fi

    # --- [安全加固] 循环引用防御 (逻辑不变) ---
    if [[ "$processed_files" == *"$file_path"* ]]; then
        warn "在 world 文件中检测到循环引用，已跳过: $file_path"
        warn "Circular include detected in world files, skipping: $file_path"
        return
    fi
    processed_files+=" $file_path"

    [ ! -f "$file_path" ] && { warn "World 文件或其引用的文件未找到: $file_path"; return; }

    while IFS= read -r line || [[ -n "$line" ]]; do
        [[ "$line" =~ ^\s*(#|$) ]] && continue
        
        if [[ "$line" =~ ^include[[:space:]]+(.+) ]]; then
            local include_path="${BASH_REMATCH[1]}"
            
            # --- [安全加固] 路径净化与逃逸攻击防御 ---
            local resolved_path
            # 使用 realpath -m 来处理相对路径和 ".."，并规范化
            resolved_path=$(realpath -m "$(dirname "$file_path")/${include_path}")

            # 核心检查：确保最终解析的路径仍然在 Corium 的配置目录下
            # This is the crucial check to prevent escaping the config directory
            if [[ "$resolved_path" != "${ETC_CORIUM_DIR}"* ]]; then
                error "安全错误：world 文件尝试引用一个位于配置目录之外的文件，操作已禁止。/ Security Error: World file attempted to include a file outside of the configuration directory. Action denied."
                error "  -> Attempted Path: ${resolved_path}"
                exit 1
            fi
            # --- [加固结束] ---

            # 递归调用，深度加一
            _internal_rebuild_parse_world_files "$resolved_path" "$processed_files" $((_depth + 1))
        else
            echo "$line"
        fi
    done < "$file_path"
}


# Reconstructs the system state to match the world file, providing a declarative management interface.
# v2.0 with Strata Integration
#
# 重建系统状态以匹配 world 文件，提供一个声明式的管理界面。
# v2.0 版本，已集成 Strata 环境管理

# --- [V99 修改] corix_rebuild_from_world (现在调用新的解析器) ---
# --- [V99 MODIFICATION] corix_rebuild_from_world (Now calls the new parser) ---

corix_rebuild_from_world() {
    local CORIUM_DEP_RESOLVE_ALL=1
    check_permissions "rebuild"
    local dry_run=0
    local prune=0
    local force=0

    # --- Argument Parsing (unchanged) ---
    # --- 参数解析 (无变动) ---
    while [ $# -gt 0 ]; do
        case "$1" in
            --dry-run) dry_run=1; shift ;;
            --prune) prune=1; shift ;;
            -y|--yes|--force) force=1; shift ;;
            *)
                error "rebuild-from-world: Unknown option '$1' / 未知选项 '$1'"
                ;;
        esac
    done

    [ -f "$WORLD_FILE" ] || error "World file not found: $WORLD_FILE / world 文件未找到: $WORLD_FILE"

    msg "Reconstructing system state from $WORLD_FILE (and includes)... / 正在从 $WORLD_FILE (及其引用的文件) 重建系统状态..."
    
    # --- [V99 核心修改] ---
    # 调用新的递归解析器来获取完整的、扁平化的目标状态列表
    # Call the new recursive parser to get the complete, flattened list of target states
    local full_world_content
    full_world_content=$(_internal_rebuild_parse_world_files "$WORLD_FILE")
    
    # 后续的解析逻辑现在作用于 full_world_content，而不是直接读取 $WORLD_FILE
    # The subsequent parsing logic now operates on full_world_content instead of directly reading $WORLD_FILE

    # --- [MODIFIED] Step 1: Parse world file and categorize targets ---
    # --- [已修改] 步骤 1: 解析 world 文件并对目标进行分类 ---
    info "Parsing world file for target state... / 正在解析 world 文件以确定目标状态..."
    local -a target_corix_pkgs=()
    local -a target_strata=() # Format: "name:type" / 格式: "名称:类型"
    # [V105 BUG FIX] Explicitly initialize array to prevent 'unbound variable' on empty world files.
    # [V105 BUG修复] 显式初始化数组以防止在 world 文件为空时出现 'unbound variable' 错误。
    declare -A target_strata_pkgs=() # Associative array: Key=strata_name, Value="pkg1 pkg2..." / 关联数组: 键=strata名称, 值="包1 包2..."
    
    while IFS= read -r line || [[ -n "$line" ]]; do
        # Ignore comments and empty lines / 忽略注释和空行
        [[ "$line" =~ ^\s*(#|$) ]] && continue
        
        case "$line" in
            strata:*:*)
                # Declaration for a Strata environment: strata:<name>:<type>
                # Strata 环境声明: strata:<名称>:<类型>
                local name type
                name=$(echo "$line" | cut -d':' -f2)
                type=$(echo "$line" | cut -d':' -f3)
                target_strata+=("${name}:${type}")
                ;;
            strata-pkg:*:*)
                # Declaration for a package inside a Strata: strata-pkg:<strata_name>:<pkg_name>
                # Strata 内部软件包声明: strata-pkg:<strata名称>:<软件包名称>
                local strata_name pkg_name
                strata_name=$(echo "$line" | cut -d':' -f2)
                pkg_name=$(echo "$line" | cut -d':' -f3-)
                # Append package to the list for that strata / 将软件包追加到对应 strata 的列表中
                target_strata_pkgs["$strata_name"]+="${pkg_name} "
                ;;
            *)
                # Default is a native Corium package / 默认为是原生 Corium 软件包
                target_corix_pkgs+=("$line")
                ;;
        esac
    done <<< "$full_world_content"

    # --- [MODIFIED] Step 2: Get current system state for all categories ---
    # --- [已修改] 步骤 2: 获取所有类别的当前系统状态 ---
    info "Getting current system state... / 正在获取当前系统状态..."
    
    # Get currently installed Corium packages (logic unchanged)
    # 获取当前已安装的 Corium 软件包 (逻辑无变动)
    local -a installed_pkgs_sorted=()
    if [ -d "$INSTALLED_DB" ] && [ -n "$(ls -A "$INSTALLED_DB")" ]; then
        mapfile -t installed_pkgs_sorted < <(_installed_package_ids | sort -u)
    fi

    # [NEW] Get currently existing Strata environments
    # [新增] 获取当前已存在的 Strata 环境
    local -a current_strata_sorted=()
    if [ -d "$STRATA_DIR" ]; then
        mapfile -t current_strata_sorted < <(find "$STRATA_DIR" -mindepth 1 -maxdepth 1 -type d -printf '%f\n' | while read -r name; do
            local type="unknown"
            local conf_file="$STRATA_DIR/$name/.corix_strata"
            [ -f "$conf_file" ] && type=$(grep '^pm=' "$conf_file" | cut -d= -f2)
            echo "${name}:${type}"
        done | sort -u)
    fi

    # --- [MODIFIED] Step 3: Calculate the diff for all categories ---
    # --- [已修改] 步骤 3: 计算所有类别的差异 ---
    info "Calculating system state change plan... / 正在计算系统状态变更计划..."
    local -a to_install=() to_remove=() to_keep=()
    local -a strata_to_create=() strata_to_destroy=() strata_to_keep=()
    
    # Use comm for efficient, sorted list comparison (logic unchanged for Corium packages)
    # 使用 comm 进行高效的有序列表比较 (Corium 软件包的逻辑无变动)
    mapfile -t to_install < <(comm -13 <(printf '%s\n' "${installed_pkgs_sorted[@]}") <(printf '%s\n' "${target_corix_pkgs[@]}" | sort -u))
    mapfile -t to_keep < <(comm -12 <(printf '%s\n' "${installed_pkgs_sorted[@]}") <(printf '%s\n' "${target_corix_pkgs[@]}" | sort -u))
    [ "$prune" -eq 1 ] && mapfile -t to_remove < <(comm -23 <(printf '%s\n' "${installed_pkgs_sorted[@]}") <(printf '%s\n' "${target_corix_pkgs[@]}" | sort -u))

    # Installation records alone do not prove that a package's files still exist.
    local kept_pkg package_dir file_entry installed_path files_present
    local -a intact_packages=()
    for kept_pkg in "${to_keep[@]}"; do
        [ -n "$kept_pkg" ] || continue
        get_pkg_id_parts "$kept_pkg" || return 1
        package_dir=$(db_get_pkg_dir "$PKG_CATEGORY/$PKG_NAME" "$PKG_SLOT")
        files_present=1
        if [ -r "$package_dir/files" ]; then
            while IFS= read -r file_entry || [ -n "$file_entry" ]; do
                [ -n "$file_entry" ] || continue
                installed_path="${CORIUM_ROOT%/}/${file_entry}"
                if [ ! -e "$installed_path" ] && [ ! -L "$installed_path" ]; then
                    files_present=0
                    break
                fi
            done < "$package_dir/files"
        else
            files_present=0
        fi
        if [ "$files_present" -eq 1 ]; then
            intact_packages+=("$kept_pkg")
        else
            to_install+=("$kept_pkg")
        fi
    done
    to_keep=("${intact_packages[@]}")
    
    # [NEW] Use comm to calculate Strata changes
    # [新增] 使用 comm 计算 Strata 环境的变更
    mapfile -t strata_to_create < <(comm -13 <(printf '%s\n' "${current_strata_sorted[@]}") <(printf '%s\n' "${target_strata[@]}" | sort -u))
    mapfile -t strata_to_keep < <(comm -12 <(printf '%s\n' "${current_strata_sorted[@]}") <(printf '%s\n' "${target_strata[@]}" | sort -u))
    [ "$prune" -eq 1 ] && mapfile -t strata_to_destroy < <(comm -23 <(printf '%s\n' "${current_strata_sorted[@]}") <(printf '%s\n' "${target_strata[@]}" | sort -u))

    # --- [MODIFIED] Plan Presentation (Dry Run or Confirmation) ---
    # --- [已修改] 计划展示 (演习模式或用户确认) ---
    local has_changes=0
    echo
    info "System state change plan: / 系统状态变更计划:"

    if [ ${#to_install[@]} -gt 0 ]; then
        echo -e "\033[1;32m[+] To be INSTALLED (Corium):\033[0m / \033[1;32m将要被安装 (Corium):\033[0m"
        printf "      %s\n" "${to_install[@]}"
        has_changes=1
    fi
    if [ ${#strata_to_create[@]} -gt 0 ]; then
        echo -e "\033[1;32m[+] To be CREATED (Strata):\033[0m / \033[1;32m将要被创建 (Strata):\033[0m"
        printf "      %s\n" "${strata_to_create[@]}"
        has_changes=1
    fi
    if [ ${#target_strata_pkgs[@]} -gt 0 ]; then
        echo -e "\033[1;34m[*] To be ENSURED (Packages in Strata):\033[0m / \033[1;34m将要被确保 (Strata 内的包):\033[0m"
        for name in "${!target_strata_pkgs[@]}"; do
             printf "      in %s: %s\n" "$name" "${target_strata_pkgs[$name]}"
        done
        has_changes=1 # Ensuring packages is also a change
    fi
    if [ ${#to_remove[@]} -gt 0 ]; then
        echo -e "\033[1;31m[-] To be REMOVED (Corium, pruned):\033[0m / \033[1;31m将要被移除 (Corium, 清理):\033[0m"
        printf "      %s\n" "${to_remove[@]}"
        has_changes=1
    fi
    if [ ${#strata_to_destroy[@]} -gt 0 ]; then
        echo -e "\033[1;31m[-] To be DESTROYED (Strata, pruned):\033[0m / \033[1;31m将要被销毁 (Strata, 清理):\033[0m"
        printf "      %s\n" "${strata_to_destroy[@]}"
        has_changes=1
    fi
    if [ ${#to_keep[@]} -gt 0 ]; then
        echo -e "\033[0;34m[=] To be KEPT (Corium):\033[0m / \033[0;34m将要被保留 (Corium):\033[0m"
        printf "      %s\n" "${to_keep[@]}"
    fi
    if [ ${#strata_to_keep[@]} -gt 0 ]; then
        echo -e "\033[0;34m[=] To be KEPT (Strata):\033[0m / \033[0;34m将要被保留 (Strata):\033[0m"
        printf "      %s\n" "${strata_to_keep[@]}"
    fi

    if [ "$has_changes" -eq 0 ]; then
        msg "System is already in sync with the world file. Nothing to do. / 系统已与 world 文件同步。无需任何操作。"
        return 0
    fi
    echo

    if [ "$dry_run" -eq 1 ]; then
        msg "Dry run complete. No changes were made. / 演习运行完毕。未做任何更改。"
        return 0
    fi

    # --- Execution Confirmation (unchanged) ---
    # --- 执行确认 (无变动) ---
    if [ "$force" -eq 0 ]; then
        read -rp "Proceed with these changes? [y/N] / 确认执行这些变更吗？[y/N] " choice
        [[ ! "$choice" =~ ^[yY]([eE][sS])?$ ]] && {
            msg "Rebuild cancelled by user. / 用户已取消重建操作。"
            return 1
        }
    fi

    # --- [MODIFIED] Execution Phase (ordered for safety) ---
    # --- [已修改] 执行阶段 (为保证安全进行了排序) ---
    acquire_lock "system"
    _begin_transaction "$INSTALLED_DB"
    trap 'release_lock "system"' RETURN
    
    # 1. Perform removals and destructions first
    # 1. 首先执行移除和销毁操作
    if [ ${#strata_to_destroy[@]} -gt 0 ]; then
        msg "Destroying orphaned Strata environments... / 正在销毁孤儿 Strata 环境..."
        for s in "${strata_to_destroy[@]}"; do
            local name=${s%:*}
            corix strata --destroy "$name"
        done
    fi
    if [ ${#to_remove[@]} -gt 0 ]; then
        msg "Pruning orphaned Corium packages... / 正在清理孤儿 Corium 软件包..."
        release_lock
        corix_remove "${to_remove[@]}"
        acquire_lock "system"
        trap 'release_lock "system"' RETURN
    fi

    # 2. Perform creations and installations
    # 2. 然后执行创建和安装操作
    if [ ${#strata_to_create[@]} -gt 0 ]; then
        msg "Creating new Strata environments... / 正在创建新的 Strata 环境..."
        for s in "${strata_to_create[@]}"; do
            local name=${s%:*}
            local type=${s#*:}
            corix strata --create "$name" "$type"
        done
    fi
    if [ ${#to_install[@]} -gt 0 ]; then
        msg "Installing missing packages to match world state... / 正在安装缺失的软件包以匹配 world 状态..."
        release_lock
        corix_install "${to_install[@]}"
        acquire_lock "system"
        trap 'release_lock "system"' RETURN
    fi
    
    # 3. Finally, ensure packages within Strata
    # 3. 最后，确保 Strata 内部的软件包
    if [ ${#target_strata_pkgs[@]} -gt 0 ]; then
        msg "Ensuring packages within Strata environments... / 正在确保 Strata 环境内的软件包..."
        for name in "${!target_strata_pkgs[@]}"; do
            local pkgs_to_install="${target_strata_pkgs[$name]}"
            local strata_type
            strata_type=$(grep '^pm=' "$STRATA_DIR/$name/.corix_strata" | cut -d= -f2)
            
            local install_cmd=""
            case "$strata_type" in
                apt) install_cmd="apt-get install -y" ;;
                pacman) install_cmd="pacman -S --noconfirm" ;;
                dnf) install_cmd="dnf install -y" ;;
                portage) install_cmd="emerge --noreplace" ;;
                dcpm|decentralized) install_cmd="dcpm install" ;;
            esac

            if [ -n "$install_cmd" ]; then
                info "Installing into '$name' (type: $strata_type): $pkgs_to_install / 正在向 '$name' (类型: $strata_type) 中安装: $pkgs_to_install"
                # The strata execute function handles locks appropriately
                # strata 执行函数会妥善处理锁
                corix_strata_execute "$name" "$install_cmd $pkgs_to_install"
            else
                warn "Unsupported strata type '$strata_type' for package installation inside strata '$name'. Please install manually. / 不支持在 strata '$name' 内部为 '$strata_type' 类型的环境自动安装包，请手动安装。"
            fi
        done
    fi
    
    _commit_transaction
    msg "System rebuild complete. State is now in sync with the world file. / 系统重建完成。当前状态已与 world 文件同步。"
}

# Autoremoves orphaned packages and Strata environments not required by the world file.
# v2.1 with granular confirmation
#
# 自动移除 world 文件不再需要的孤儿软件包和 Strata 环境。
# v2.1 版本，带有粒度化确认功能
corix_autoremove() {
    local CORIUM_DEP_RESOLVE_ALL=1
    check_permissions "autoremove"
    msg "Searching for orphaned packages and Strata to remove... / 正在搜索要移除的孤儿软件包和 Strata 环境..."
    
    # --- State Calculation (reusing the complete logic from rebuild-from-world) ---
    # --- 状态计算 (复用来自 rebuild-from-world 的完整逻辑) ---
    [ -f "$WORLD_FILE" ] || error "World file not found: $WORLD_FILE / world 文件未找到: $WORLD_FILE"

    # --- Step 1: Parse world file to get target state ---
    local -a target_corix_pkgs=()
    local -a target_strata=()
    while IFS= read -r line || [[ -n "$line" ]]; do
        [[ "$line" =~ ^\s*(#|$) ]] && continue
        case "$line" in
            strata:*:*)
                local name type
                name=$(echo "$line" | cut -d':' -f2); type=$(echo "$line" | cut -d':' -f3)
                target_strata+=("${name}:${type}")
                ;;
            strata-pkg:*:*)
                # autoremove ignores packages inside strata.
                # autoremove 会忽略 strata 内部的包。
                ;;
            *)
                target_corix_pkgs+=("$line")
                ;;
        esac
    done < "$WORLD_FILE"

    local target_full_dep_list
    target_full_dep_list=$(dep_resolve_topological "${target_corix_pkgs[@]}")
    for pkg in "${target_corix_pkgs[@]}"; do
        if ! [[ " ${target_full_dep_list[*]} " =~ " ${pkg} " ]]; then
            target_full_dep_list+=" $pkg"
        fi
    done
    local -a target_pkgs_sorted
    mapfile -t target_pkgs_sorted < <(echo "$target_full_dep_list" | tr ' ' '\n' | sort -u)

    # --- Step 2: Get current system state ---
    local -a installed_pkgs_sorted=()
    [ -d "$INSTALLED_DB" ] && [ -n "$(ls -A "$INSTALLED_DB")" ] && \
        mapfile -t installed_pkgs_sorted < <(_installed_package_ids | sort -u)

    local -a current_strata_sorted=()
    [ -d "$STRATA_DIR" ] && \
        mapfile -t current_strata_sorted < <(find "$STRATA_DIR" -mindepth 1 -maxdepth 1 -type d -printf '%f\n' | while read -r name; do
            local type="unknown"
            local conf_file="$STRATA_DIR/$name/.corix_strata"; [ -f "$conf_file" ] && type=$(grep '^pm=' "$conf_file" | cut -d= -f2)
            echo "${name}:${type}"
        done | sort -u)

    # --- Step 3: Calculate orphans ---
    local -a to_remove_pkgs to_remove_strata
    mapfile -t to_remove_pkgs < <(comm -23 <(printf '%s\n' "${installed_pkgs_sorted[@]}") <(printf '%s\n' "${target_pkgs_sorted[@]}"))
    mapfile -t to_remove_strata < <(comm -23 <(printf '%s\n' "${current_strata_sorted[@]}") <(printf '%s\n' "${target_strata[@]}" | sort -u))

    if [ ${#to_remove_pkgs[@]} -eq 0 ] && [ ${#to_remove_strata[@]} -eq 0 ]; then
        msg "No orphaned items found. Your system is clean. / 未找到孤儿项目。您的系统是干净的。"
        return 0
    fi
    
    # --- [MODIFIED] Step 4: Granular Confirmation ---
    # --- [已修改] 步骤 4: 粒度化确认 ---
    local proceed_with_pkgs=0
    local proceed_with_strata=0
    
    if [ ${#to_remove_pkgs[@]} -gt 0 ]; then
        echo
        echo -e "\033[1;33mThe following packages are no longer required and can be removed:\033[0m"
        echo -e "\033[1;33m以下软件包已不再需要，可以被移除：\033[0m"
        printf "  %s\n" "${to_remove_pkgs[@]}"
        echo
        read -rp "Proceed with removing these packages? [y/N] / 确认移除这些软件包吗？[y/N] " choice
        if [[ "$choice" =~ ^[yY] ]]; then
            proceed_with_pkgs=1
        fi
    fi

    if [ ${#to_remove_strata[@]} -gt 0 ]; then
        echo
        echo -e "\033[1;33mThe following Strata environments are no longer required and can be destroyed:\033[0m"
        echo -e "\033[1;33m以下 Strata 环境已不再需要，可以被销毁：\033[0m"
        printf "  %s\n" "${to_remove_strata[@]}"
        echo
        read -rp "Proceed with destroying these Strata? [y/N] / 确认销毁这些 Strata 吗？[y/N] " choice
        if [[ "$choice" =~ ^[yY] ]]; then
            proceed_with_strata=1
        fi
    fi

    if [ "$proceed_with_pkgs" -eq 0 ] && [ "$proceed_with_strata" -eq 0 ]; then
        msg "Autoremove cancelled. No changes were made. / 自动移除已取消。未做任何更改。"
        return 0
    fi

    # --- Execution Phase ---
    acquire_lock "system"
    _begin_transaction "$INSTALLED_DB"
    trap 'release_lock "system"' RETURN
    if [ "$proceed_with_strata" -eq 1 ]; then
        msg "Destroying orphaned Strata environments... / 正在销毁孤儿 Strata 环境..."
        for s in "${to_remove_strata[@]}"; do
            local name=${s%:*}
            # Use the internal function directly for less output noise
            # 直接使用内部函数以减少输出噪音
            corix_strata_destroy "$name"
        done
    fi
    if [ "$proceed_with_pkgs" -eq 1 ]; then
        msg "Removing orphaned Corium packages... / 正在移除孤儿 Corium 软件包..."
        release_lock
        corix_remove "${to_remove_pkgs[@]}"
        acquire_lock "system"
        trap 'release_lock "system"' RETURN
    fi
    _commit_transaction
    msg "Autoremove complete. / 自动移除完成。"
}

# =======================================================
# --- SECTION 20: CACHE MANAGEMENT AND CLEANING       ---
# --- 第20节: 缓存管理与清理                         ---
# =======================================================

# Cleans up cached source files and binary packages to free up disk space.
# 清理缓存的源码文件和二进制包以释放磁盘空间。
#
# This function provides a user-facing command 'corix clean' with various
# options to control what gets deleted. It prioritizes safety by using a
# dry-run mode by default and requiring explicit confirmation.
# 此函数提供了面向用户的 'corix clean' 命令，带有多种选项来控制删除内容。
# 它默认使用“演习模式”(dry-run)并要求显式确认，以此来优先保证安全。
corix_clean() {
    check_permissions "clean"

    # --- Default settings ---
    local dry_run=1
    local force_confirm=0
    local target_sources=0
    local target_binaries=0
    local target_tmp=0 # --- [功能增强] 新增目标：临时文件 ---
    local older_than_days=0
    local keep_last_n=0

    # --- Argument parsing for user control ---
    if [ $# -eq 0 ]; then
        info "Running in default mode: --dry-run --binaries --sources --tmp / 以默认模式运行: --dry-run --binaries --sources --tmp"
        target_sources=1
        target_binaries=1
        target_tmp=1
    fi

    while [ $# -gt 0 ]; do
        case "$1" in
            --sources)
                target_sources=1; shift ;;
            --binaries)
                target_binaries=1; shift ;;
            --tmp) # --- [功能增强] 新增选项 ---
                target_tmp=1; shift ;;
            --all)
                target_sources=1; target_binaries=1; target_tmp=1; shift ;;
            --dry-run)
                dry_run=1; shift ;;
            --force)
                dry_run=0; force_confirm=1; shift ;;
            --older-than)
                [ -z "${2:-}" ] && error "--older-than requires a number of days (e.g., 30)."
                older_than_days="$2"; shift 2 ;;
            --keep-last)
                [ -z "${2:-}" ] && error "--keep-last requires a number (e.g., 3)."
                keep_last_n="$2"; shift 2 ;;
            -y) # Alias for --force
                dry_run=0; force_confirm=1; shift ;;
            *)
                error "Unknown option for clean: $1" ;;
        esac
    done

    if [ "$target_sources" -eq 0 ] && [ "$target_binaries" -eq 0 ] && [ "$target_tmp" -eq 0 ]; then
        error "No target specified. Use --sources, --binaries, --tmp, or --all."
    fi

    msg "Starting cache and temporary file cleaning process... / 开始缓存与临时文件清理流程..."

    local items_to_delete=()
    local total_size=0

    # --- Binary Cache Cleaning ---
    if [ "$target_binaries" -eq 1 ]; then
        info "Analyzing binary package cache... / 正在分析二进制包缓存..."
        mapfile -t bin_files < <(_clean_binary_cache "$dry_run" "$older_than_days" "$keep_last_n")
        items_to_delete+=("${bin_files[@]}")
    fi

    # --- Source Cache Cleaning ---
    if [ "$target_sources" -eq 1 ]; then
        info "Analyzing source code cache... / 正在分析源码缓存..."
        mapfile -t src_files < <(_clean_source_cache "$dry_run" "$older_than_days" "${items_to_delete[@]}")
        items_to_delete+=("${src_files[@]}")
    fi

    # --- [功能增强] Temporary Files Cleaning ---
    if [ "$target_tmp" -eq 1 ]; then
        info "Analyzing temporary build directories... / 正在分析临时构建目录..."
        if [ -d "$BUILD_TMP_DIR_BASE" ]; then
            # 安全地查找并列出所有corix创建的临时目录
            mapfile -t tmp_dirs < <(find "$BUILD_TMP_DIR_BASE" -mindepth 1 -maxdepth 1 -type d -name '*-build.XXXXXX' -o -name '*-install.XXXXXX' -o -name 'bt_download.XXXXXX')
            items_to_delete+=("${tmp_dirs[@]}")
        fi
    fi

    # --- Execution Phase ---
    if [ ${#items_to_delete[@]} -eq 0 ]; then
        msg "System is clean. No items to delete. / 系统是干净的。没有项目需要删除。"
        return 0
    fi

    info "The following files/directories have been marked for deletion: / 以下文件/目录已被标记为待删除:"
    for item in "${items_to_delete[@]}"; do
        local item_size
        item_size=$(du -sh "$item" 2>/dev/null | awk '{print $1}')
        total_size=$((total_size + $(du -sb "$item" 2>/dev/null | awk '{print $1}' || echo 0)))
        detail "  - $(basename "$item") ($item_size)"
    done

    local human_readable_size
    human_readable_size=$(echo "$total_size" | awk '{
        suff="B";
        if($1 > 1024){$1/=1024; suff="K"}
        if($1 > 1024){$1/=1024; suff="M"}
        if($1 > 1024){$1/=1024; suff="G"}
        printf "%.1f%s", $1, suff;
    }')

    echo
    msg "Total space to be freed / 总计可释放空间: $human_readable_size"

    if [ "$dry_run" -eq 1 ]; then
        msg "Dry run complete. No items were deleted. / 演习运行完毕。未删除任何项目。"
        info "To delete these items, run the command again with the --force or -y flag. / 要删除这些项目，请使用 --force 或 -y 标志重新运行此命令。"
        return 0
    fi

    if [ "$force_confirm" -eq 0 ]; then
        read -rp "Proceed with deletion? [y/N] / 确认删除吗？[y/N] " choice
        [[ ! "$choice" =~ ^[yY]([eE][sS])?$ ]] && {
            msg "Deletion cancelled by user. / 用户已取消删除操作。"
            return 1
        }
    fi

    acquire_lock "system"
    trap 'release_lock "system"' RETURN
    info "Deleting items... / 正在删除项目..."
    for item in "${items_to_delete[@]}"; do
        # 对文件和目录都有效的删除命令
        rm -rf "$item"
        local sig_file="${item}.sig"
        [ -f "$sig_file" ] && rm -f "$sig_file"
    done
    release_lock

    msg "Cleaning complete. Freed $human_readable_size of space. / 清理完成。释放了 $human_readable_size 的空间。"
}

# Internal function to determine and list orphan binary packages for deletion.
# An orphan is a package that is NOT installed AND NOT the latest available version.
# This preserves the latest version for quick installation and older versions if they are
# currently in use, which is critical for the 'rollback' feature.
#
# 内部函数，用于确定并列出待删除的孤儿二进制包。
# 孤儿包的定义是：未被安装 且 不是最新可用版本 的包。
# 这种策略保留了最新版本以备快速安装，也保留了当前正在使用的旧版本，这对 'rollback' 功能至关重要。
_clean_binary_cache() {
    local dry_run="$1"
    local older_than_days="$2"
    local keep_last_n="$3"

    # --- Stage 1: Gather system state information for quick lookups ---
    declare -A installed_pkgs
    declare -A latest_versions
    declare -A all_pkg_versions

    # Get a list of all installed packages (format: category/name-version-slot)
    if [ -d "$INSTALLED_DB" ]; then
        while read -r pkg_dir; do
            local pkg_name pkg_ver pkg_slot
            pkg_name=$(cat "$pkg_dir/name" 2>/dev/null)
            pkg_ver=$(cat "$pkg_dir/version" 2>/dev/null)
            pkg_slot=$(cat "$pkg_dir/slot" 2>/dev/null)
            [ -n "$pkg_name" ] && [ -n "$pkg_ver" ] && installed_pkgs["${pkg_name//\//_}-${pkg_ver}-${pkg_slot}"]=1
        done < <(find "$INSTALLED_DB" -mindepth 2 -maxdepth 2 -type d)
    fi

    # Get a list of the latest available version for all packages in repos
    while read -r build_file; do
        local meta pkg_cat pkg_name pkg_ver
        meta=$(_parse_build_file "$build_file" 2>/dev/null || continue)
        pkg_cat=$(dirname "$build_file" | xargs basename)
        pkg_name_base=$(echo "$meta" | grep "^pkgname=" | cut -d= -f2)
        pkg_name="${pkg_cat}/${pkg_name_base}"
        pkg_ver=$(echo "$meta" | grep "^pkgver=" | cut -d= -f2)
        latest_versions["$pkg_name"]="$pkg_ver"
    done < <(find "$REPOS_DIR" -name "*.build" -type f)

    # --- Stage 2: Iterate through the cache and apply deletion rules ---
    local now
    now=$(date +%s)
    
    find "$BINARY_CACHE" -type f -name "*.corix.tar.*" | while read -r pkg_file; do
        local filename pkg_base_name pkg_ver pkg_slot pkg_id_for_lookup
        filename=$(basename "$pkg_file")
        # Regex to parse "category_name-version-slot-arch.corix.tar.zst"
        # 正则表达式，用于解析 "类别_名称-版本-槽位-架构.corix.tar.zst"
        if [[ "$filename" =~ ^(.*)-([0-9].*)-([0-9]+)-.*\.corix\.tar\..*$ ]]; then
            pkg_base_name="${BASH_REMATCH[1]}"
            pkg_ver="${BASH_REMATCH[2]}"
            pkg_slot="${BASH_REMATCH[3]}"
        else
            continue # Skip files with non-standard names / 跳过非标准命名的文件
        fi
        
        # Reconstruct package name (category/name) from category_name
        local pkg_cat pkg_name
        pkg_cat=$(echo "$pkg_base_name" | cut -d_ -f1)
        pkg_name=$(echo "$pkg_base_name" | cut -d_ -f2-)
        local full_pkg_name="${pkg_cat}/${pkg_name}"
        
        # --- Rule 1: Never delete currently installed packages ---
        pkg_id_for_lookup="${pkg_base_name}-${pkg_ver}-${pkg_slot}"
        if [ "${installed_pkgs[$pkg_id_for_lookup]+_}" ]; then
            continue
        fi
        
        # --- Rule 2: Never delete the latest available version ---
        local latest_ver="${latest_versions[$full_pkg_name]:-}"
        if [ -n "$latest_ver" ] && [ "$pkg_ver" = "$latest_ver" ]; then
            continue
        fi

        # --- Rule 3 (Optional): Check age if --older-than is used ---
        if [ "$older_than_days" -gt 0 ]; then
            local file_age_seconds
            file_age_seconds=$((now - $(stat -c %Y "$pkg_file")))
            if [ "$file_age_seconds" -lt $((older_than_days * 86400)) ]; then
                continue # File is not old enough / 文件还不够旧
            fi
        fi
        
        # If we reach here, the package is an orphan. Mark for deletion.
        # 如果代码执行到这里，说明这个包是孤儿包。标记以待删除。
        echo "$pkg_file"
    done
}

# Internal function to determine and list orphan source code archives.
# An orphan source is one that is not required by any installed package
# or any package currently available in the repositories.
#
# 内部函数，用于确定并列出孤儿源码存档。
# 孤儿源码的定义是：没有任何已安装的软件包需要它，也没有任何当前仓库中
# 的软件包需要它。
_clean_source_cache() {
    local dry_run="$1"
    local older_than_days="$2"

    # --- 步骤 1: 构建一个“必需源码”的哈希集合，用于快速查找 ---
    # --- Step 1: Build a hash set of "required sources" for fast lookups ---
    declare -A required_sources
    info "正在构建必需源码文件的索引... / Building index of required source files..."

    # a) 添加所有当前仓库中定义的源码
    # a) Add all sources defined in current repositories
    while read -r build_file; do
        local meta; meta=$(_parse_build_file "$build_file" 2>/dev/null || continue)
        local source_list; source_list=$(echo "$meta" | grep "^source=" | cut -d= -f2-)
        while IFS= read -r src_url; do
            local src_filename
            [[ "$src_url" == *"::"* ]] && src_filename="${src_url%%::*}" || src_filename=$(basename "$src_url")
            required_sources["$src_filename"]=1
        done <<< "$source_list"
    done < <(find "$REPOS_DIR" -name "*.build" -type f)

    # b) 添加所有已安装软件包的源码
    # b) Add all sources for currently installed packages
    while read -r pkg_dir; do
        local build_file="${pkg_dir}/build_file"
        if [ -f "$build_file" ]; then
            local meta; meta=$(_parse_build_file "$build_file" 2>/dev/null || continue)
            local source_list; source_list=$(echo "$meta" | grep "^source=" | cut -d= -f2-)
            while IFS= read -r src_url; do
                local src_filename
                [[ "$src_url" == *"::"* ]] && src_filename="${src_url%%::*}" || src_filename=$(basename "$src_url")
                required_sources["$src_filename"]=1
            done <<< "$source_list"
        fi
    done < <(find "$INSTALLED_DB" -mindepth 2 -maxdepth 2 -type d)

    # --- 步骤 2: 遍历源码缓存，找出孤儿文件 ---
    # --- Step 2: Iterate through the source cache and find orphans ---
    local now; now=$(date +%s)
    find "$SOURCE_CACHE" -type f | while read -r src_file; do
        local filename; filename=$(basename "$src_file")

        # 如果这个文件不在我们的“必需”列表中，它就是一个孤儿
        # If this file is not in our "required" list, it's an orphan
        if [ -z "${required_sources[$filename]+_}" ]; then
            # (可选) 年龄检查
            if [ "$older_than_days" -gt 0 ]; then
                local file_age_seconds
                file_age_seconds=$((now - $(stat -c %Y "$src_file")))
                if [ "$file_age_seconds" -lt $((older_than_days * 86400)) ]; then
                    continue # 文件还不够旧
                fi
            fi
            # 标记为待删除
            echo "$src_file"
        fi
    done
}



# =======================================================
# --- SECTION 10: TRUST AND SIGNATURE MANAGEMENT      ---
# --- 第10节: 信任与签名管理                         ---
# =======================================================
# This section implements a Public Key Infrastructure (PKI) based on GPG.
# It provides a "defense-in-depth" layer on top of the blockchain consensus,
# allowing administrators to define explicit trust anchors.
#
# 本节基于GPG实现了一个公钥基础设施(PKI)。它在区块链共识之上提供了一个
# “深度防御”层，允许管理员定义明确的信任锚。

# New Paths
# 新增路径
TRUST_ZONES_DIR="${ETC_CORIUM_DIR}/trust_zones"

# Get the current active trust zone's keyring path.
# 获取当前活动信任区的密钥环路径。
_get_current_keyring_path() {
    local active_zone
    active_zone=$(cat "${TRUST_ZONES_DIR}/active_zone" 2>/dev/null || echo "default")
    echo "${TRUST_ZONES_DIR}/${active_zone}/keyring.gpg"
}

# 修改后的 _verify_gpg_signature
# REVISED _verify_gpg_signature
#
# 返回值: 成功时，输出成功验证的 TrustZone 的名称 (例如 "default" 或 "awesome-community")，并且返回码为 0。
#         失败时，无输出，并且返回码为 1。
#
# RETURNS: On success, outputs the name of the TrustZone that successfully verified the signature
#          (e.g., "default" or "awesome-community"), and the return code is 0.
#          On failure, there is no output, and the return code is 1.
_verify_gpg_signature() {
    local file_to_verify="$1"
    local signature_file="$2"
    
    # 扫描所有信任区目录，找到所有存在的密钥环文件
    # Scan all trust zone directories to find all existing keyring files
    local all_keyrings
    mapfile -t all_keyrings < <(find "$TRUST_ZONES_DIR" -type f -name "keyring.gpg")

    if [ ${#all_keyrings[@]} -eq 0 ]; then
         warn "系统中未找到任何信任区密钥环。 (No trust zone keyrings found in the system.)"
         return 1
    fi

    for keyring_path in "${all_keyrings[@]}"; do
        if gpg --batch --no-default-keyring --keyring "$keyring_path" --verify "$signature_file" "$file_to_verify" >/dev/null 2>&1; then
            # 验证成功！输出是哪个 TrustZone 成功的。
            # Verification successful! Output which TrustZone succeeded.
            basename "$(dirname "$keyring_path")"
            return 0
        fi
    done

    # 如果循环结束都没有成功，则返回失败
    # If the loop finishes without success, return failure
    return 1
}

# The user-facing command dispatcher for 'corix key'.
# 面向用户的 'corix key' 命令分发器。
corix_key() {
    check_permissions "key"
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        --list)
            corix_key_list
            ;;
        --import)
            [ $# -lt 1 ] && error "用法: corix key --import <key_file.asc> (Usage: corix key --import <key_file.asc>)"
            corix_key_import "$1"
            ;;
        --delete)
            [ $# -lt 1 ] && error "用法: corix key --delete <KEY_ID> (Usage: corix key --delete <KEY_ID>)"
            corix_key_delete "$1"
            ;;
        --list-zones)
            corix_key_list_zones
            ;;
        --create-zone)
            [ $# -lt 1 ] && error "用法: corix key --create-zone <zone_name> (Usage: corix key --create-zone <zone_name>)"
            corix_key_create_zone "$1"
            ;;
        --switch-zone)
            [ $# -lt 1 ] && error "用法: corix key --switch-zone <zone_name> (Usage: corix key --switch-zone <zone_name>)"
            corix_key_switch_zone "$1"
            ;;
        *)
            echo "corix key: 管理信任密钥与信任区 (Manage trust keys and zones)"
            echo "  --list             列出当前信任区中的所有GPG公钥 (List all GPG public keys in the current zone)"
            echo "  --import <file>    向当前信任区导入一个新的GPG公钥 (Import a new GPG public key to the current zone)"
            echo "  --delete <KEY_ID>  从当前信任区删除一个GPG公key (Delete a GPG key from the current zone)"
            echo "  --list-zones       列出所有可用的信任区 (List all available trust zones)"
            echo "  --create-zone <name> 创建一个新的信任区 (Create a new trust zone)"
            echo "  --switch-zone <name> 切换到指定的信任区 (Switch to a specific trust zone)"
            ;;
    esac
}

# Lists all keys in the current trust zone's keyring.
# 列出当前信任区密钥环中的所有密钥。
corix_key_list() {
    local keyring_path
    keyring_path=$(_get_current_keyring_path)
    [ ! -f "$keyring_path" ] && { msg "当前信任区没有密钥。 (No keys in the current trust zone.)"; return 0; }
    
    msg "当前信任区中的密钥 (Keys in current trust zone): $(cat "${TRUST_ZONES_DIR}/active_zone" 2>/dev/null || echo "default")"
    gpg --batch --no-default-keyring --keyring "$keyring_path" --list-keys
}

# Imports a new GPG key into the current trust zone.
# 向当前信任区导入一个新的GPG密钥。
corix_key_import() {
    local key_file="$1"
    [ ! -f "$key_file" ] && error "密钥文件未找到: $key_file (Key file not found: $key_file)"
    
    local keyring_path zone_dir
    zone_dir=$(dirname "$(_get_current_keyring_path)")
    keyring_path=$(_get_current_keyring_path)
    
    mkdir -p "$zone_dir"
    
    msg "正在向当前信任区导入密钥... (Importing key to the current trust zone...)"
    if gpg --batch --no-default-keyring --keyring "$keyring_path" --import "$key_file"; then
        info "密钥导入成功。 (Key imported successfully.)"
    else
        error "密钥导入失败。请检查文件格式或密钥是否已存在。 (Failed to import key. Check the file format or if the key already exists.)"
    fi
}

# Deletes a key from the current trust zone.
# 从当前信任区删除一个密钥。
corix_key_delete() {
    local key_id="$1"
    local keyring_path
    keyring_path=$(_get_current_keyring_path)
    [ ! -f "$keyring_path" ] && error "密钥环未找到，无法删除。 (Keyring not found, cannot delete.)"
    
    read -rp "您确定要从当前信任区永久删除密钥 '$key_id' 吗? [y/N] (Are you sure you want to permanently delete key '$key_id' from the current trust zone? [y/N]) " choice
    [[ ! "$choice" =~ ^[yY] ]] && { msg "删除已取消。 (Deletion cancelled.)"; return 0; }

    if gpg --batch --no-default-keyring --keyring "$keyring_path" --delete-key "$key_id"; then
        msg "密钥已成功删除。 (Key deleted successfully.)"
    else
        error "删除密钥失败。请检查KEY_ID是否正确。 (Failed to delete key. Please check if the KEY_ID is correct.)"
    fi
}

# Lists all available trust zones.
# 列出所有可用的信任区。
corix_key_list_zones() {
    msg "可用的信任区: (Available trust zones:)"
    local active_zone
    active_zone=$(cat "${TRUST_ZONES_DIR}/active_zone" 2>/dev/null || echo "default")
    
    find "$TRUST_ZONES_DIR" -mindepth 1 -maxdepth 1 -type d | while read -r zone_dir; do
        local zone_name
        zone_name=$(basename "$zone_dir")
        if [ "$zone_name" = "$active_zone" ]; then
            echo "  * $zone_name (active / 当前)"
        else
            echo "    $zone_name"
        fi
    done
}

# Creates a new, empty trust zone.
# 创建一个新的、空的信任区。
corix_key_create_zone() {
    local zone_name="$1"
    local zone_path="${TRUST_ZONES_DIR}/${zone_name}"

    [ -d "$zone_path" ] && error "信任区 '$zone_name' 已存在。 (Trust zone '$zone_name' already exists.)"
    
    mkdir -p "$zone_path"
    msg "信任区 '$zone_name' 已创建。 (Trust zone '$zone_name' created.)"
    info "您现在可以切换到它并导入密钥: corix key --switch-zone $zone_name (You can now switch to it and import keys: corix key --switch-zone $zone_name)"
}

# Switches the active trust zone.
# 切换活动的信任区。
corix_key_switch_zone() {
    local zone_name="$1"
    local zone_path="${TRUST_ZONES_DIR}/${zone_name}"
    
    [ ! -d "$zone_path" ] && error "信任区 '$zone_name' 未找到。请先创建它。 (Trust zone '$zone_name' not found. Please create it first.)"
    
    echo "$zone_name" > "${TRUST_ZONES_DIR}/active_zone"
    msg "已切换到信任区: $zone_name (Switched to trust zone: $zone_name)"
}

# =======================================================
# --- SECTION 27: SNAPSHOT MANAGEMENT (NEW)           ---
# --- 第27节: 快照管理 (新增)                         ---
# =======================================================

# The user-facing command dispatcher for 'corix snapshot'.
# 'corix snapshot' 的用户侧命令分发器。
corix_snapshot() {
    check_permissions "snapshot"
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        create)
            [ $# -lt 1 ] && error "Usage: corix snapshot create <snapshot_name> / 用法: corix snapshot create <快照名称>"
            corix_snapshot_create "$1"
            ;;
        list)
            corix_snapshot_list
            ;;
        delete)
             [ $# -lt 1 ] && error "Usage: corix snapshot delete <snapshot_name> / 用法: corix snapshot delete <快照名称>"
            corix_snapshot_delete "$1"
            ;;
        rollback)
            [ $# -lt 1 ] && error "Usage: corix snapshot rollback <snapshot_name> / 用法: corix snapshot rollback <快照名称>"
            corix_snapshot_rollback "$1"
            ;;
        *)
            echo "corix snapshot: Manage local, instantaneous system state snapshots."
            echo "corix snapshot: 管理本地的、瞬时的系统状态快照。"
            echo
            echo "  create <name>     Create a new snapshot of the current state."
            echo "                    (创建当前系统状态的一个新快照)"
            echo "  list              List all available snapshots."
            echo "                    (列出所有可用的快照)"
            echo "  delete <name>     Delete a specific snapshot."
            echo "                    (删除一个指定的快照)"
            echo "  rollback <name>   Revert the system state to a specific snapshot."
            echo "                    (将系统状态回滚到一个指定的快照)"
            ;;
    esac
}

# Creates a new snapshot. Uses ZFS/Btrfs if available for efficiency.
# 创建一个新快照。如果可用，则优先使用 ZFS/Btrfs 以提高效率。
_internal_snapshot_zfs_dataset() {
    command -v zfs >/dev/null 2>&1 || return 1
    zfs list -H -o name,mountpoint,mounted | awk -F '\t' -v path="$VAR_LIB_CORIUM_DIR" '$2==path && $3=="yes" {print $1; found=1; exit} END {if(!found) exit 1}'
}

corix_snapshot_create() {
    local name="$1"
    [[ "$name" =~ ^[a-zA-Z0-9][a-zA-Z0-9._-]*$ ]] || return 1
    # 验证名称以防止路径遍历
    # Validate name to prevent path traversal
    case "$name" in
      */* | .. | .)
        error "无效的名称。它不能包含 '/' 或 '.' 字符。/ Invalid name. It cannot contain '/' or '.' characters."
        return 1
        ;;
    esac
    local snapshot_base_path="${SNAPSHOTS_DIR}/${name}"
    local snapshot_type="rsync" # Default type / 默认类型

    mkdir -p "$SNAPSHOTS_DIR"
    [ -e "$snapshot_base_path" ] && error "Snapshot with name '$name' already exists. / 名为 '$name' 的快照已存在。"

    acquire_lock "system"
    trap 'release_lock "system"' RETURN
    
    msg "Creating snapshot '$name'... / 正在创建快照 '$name'..."

    # --- 智能检测文件系统类型以实现高效快照 ---
    # --- Intelligent filesystem detection for efficient snapshots ---
    local detected_zfs_dataset=""
    detected_zfs_dataset=$(_internal_snapshot_zfs_dataset 2>/dev/null) || detected_zfs_dataset=""
    if [ -n "$detected_zfs_dataset" ]; then
        # --- ZFS a a ---
        info "ZFS filesystem detected. Creating efficient ZFS snapshot. / 检测到 ZFS 文件系统。正在创建高效的 ZFS 快照。"
        local dataset
        dataset=$(_internal_snapshot_zfs_dataset)
        if zfs snapshot "${dataset}@corix_${name}"; then
            snapshot_type="zfs"
            # We create a marker file to make it listable / 我们创建一个标记文件以便列表功能可以发现它
            mkdir -p "$snapshot_base_path"
        else
            error "ZFS snapshot creation failed. / ZFS 快照创建失败。"
        fi
    elif command -v btrfs >/dev/null 2>&1 && btrfs subvolume show "$VAR_LIB_CORIUM_DIR" >/dev/null 2>&1; then
        # --- Btrfs a a ---
        info "Btrfs subvolume detected. Creating efficient Btrfs snapshot. / 检测到 Btrfs 子卷。正在创建高效的 Btrfs 快照。"
        mkdir -p "$snapshot_base_path" || return 1
        if btrfs subvolume snapshot -r "${VAR_LIB_CORIUM_DIR}" "$snapshot_base_path/var"; then
            snapshot_type="btrfs"
        else
            error "Btrfs snapshot creation failed. / Btrfs 快照创建失败。"
        fi
    else
        # --- Fallback to rsync with hard-links ---
        # --- 回退到使用硬链接的 rsync ---
        info "Using rsync with hard-links for space-efficient snapshot. / 正在使用 rsync 和硬链接以创建节省空间的快照。"
        local latest_snapshot
        latest_snapshot=$(find "$SNAPSHOTS_DIR" -mindepth 1 -maxdepth 1 -type d -printf '%T@ %p\n' | sort -nr | head -n1 | cut -d' ' -f2-)
        
        local rsync_opts=("-a")
        if [ -n "$latest_snapshot" ]; then
            detail "Linking against latest snapshot for efficiency: $(basename "$latest_snapshot") / 为提高效率，正链接到最新的快照: $(basename "$latest_snapshot")"
            rsync_opts+=("--link-dest=${latest_snapshot}")
        fi
        
        # We snapshot both the configuration and the state databases
        # 我们同时快照配置目录和状态数据库目录
        mkdir -p "${snapshot_base_path}/etc" "${snapshot_base_path}/var"
        rsync "${rsync_opts[@]}" "$ETC_CORIUM_DIR/" "${snapshot_base_path}/etc/"
        rsync "${rsync_opts[@]}" --exclude="snapshots" "$VAR_LIB_CORIUM_DIR/" "${snapshot_base_path}/var/" || return 1
        _internal_copy_sqlite_state "$VAR_LIB_CORIUM_DIR" "${snapshot_base_path}/var" || return 1
    fi

    if [ "$snapshot_type" != rsync ]; then
        mkdir -p "$snapshot_base_path/etc" || return 1
        cp -a "$ETC_CORIUM_DIR/." "$snapshot_base_path/etc/" || return 1
    fi

    # Write metadata for easier management
    # 写入元数据以便于管理
    cat > "${snapshot_base_path}/snapshot.meta" <<EOF
name=${name}
type=${snapshot_type}
date=$(date -u --rfc-3339=seconds)
corix_version=${CORIUM_VERSION}
EOF

    msg "Snapshot '$name' created successfully (type: $snapshot_type). / 快照 '$name' 创建成功 (类型: $snapshot_type)。"
}

# Lists all available snapshots.
# 列出所有可用的快照。
corix_snapshot_list() {
    msg "Available Snapshots: / 可用快照列表:"
    [ ! -d "$SNAPSHOTS_DIR" ] || [ -z "$(ls -A "$SNAPSHOTS_DIR")" ] && { info "No snapshots found. / 未找到任何快照。"; return 0; }

    find "$SNAPSHOTS_DIR" -mindepth 1 -maxdepth 1 -type d | while read -r snap_dir; do
        if [ -f "${snap_dir}/snapshot.meta" ]; then
            local name type date
            name=$(grep '^name=' "${snap_dir}/snapshot.meta" | cut -d= -f2)
            type=$(grep '^type=' "${snap_dir}/snapshot.meta" | cut -d= -f2)
            date=$(grep '^date=' "${snap_dir}/snapshot.meta" | cut -d= -f2)
            echo -e "  - \033[1;32m${name}\033[0m (type: ${type}, created: ${date})"
        fi
    done
}

# Deletes a specific snapshot.
# 删除一个指定的快照。
corix_snapshot_delete() {
    local name="$1"
    [[ "$name" =~ ^[a-zA-Z0-9][a-zA-Z0-9._-]*$ ]] || return 1
    local snapshot_base_path="${SNAPSHOTS_DIR}/${name}"
    
    [ ! -d "$snapshot_base_path" ] || [ ! -f "${snapshot_base_path}/snapshot.meta" ] && error "Snapshot '$name' not found. / 未找到快照 '$name'。"

    local type
    type=$(grep '^type=' "${snapshot_base_path}/snapshot.meta" | cut -d= -f2)

    warn "This will permanently delete the snapshot '$name'. This action cannot be undone."
    warn "此操作将永久删除快照 '$name'。该操作无法撤销。"
    read -rp "Are you sure? [y/N] / 您确定吗？[y/N] " choice
    [[ ! "$choice" =~ ^[yY] ]] && { msg "Deletion cancelled. / 删除操作已取消。"; return 0; }

    acquire_lock "system"
    trap 'release_lock "system"' RETURN
    
    msg "Deleting snapshot '$name'... / 正在删除快照 '$name'..."

    case "$type" in
        zfs)
            local dataset
            dataset=$(_internal_snapshot_zfs_dataset)
            zfs destroy "${dataset}@corix_${name}" || error "Failed to destroy ZFS snapshot. / 销毁 ZFS 快照失败。"
            rm -rf "$snapshot_base_path" # Remove the marker directory / 删除标记目录
            ;;
        btrfs)
            local subvolume_path="$snapshot_base_path"
            [ ! -d "$snapshot_base_path/var" ] || subvolume_path="$snapshot_base_path/var"
            btrfs subvolume delete "$subvolume_path" || error "Failed to delete Btrfs snapshot. / 删除 Btrfs 快照失败。"
            [ "$subvolume_path" = "$snapshot_base_path" ] || rm -rf -- "$snapshot_base_path"
            ;;
        rsync)
            rm -rf "${snapshot_base_path:?Error: Variable is unset or empty}"
            ;;
        *)
            error "Unknown snapshot type '$type'. Manual deletion required. / 未知的快照类型 '$type'。需要手动删除。"
            ;;
    esac
    
    msg "Snapshot '$name' deleted successfully. / 快照 '$name' 已成功删除。"
}

# Rolls the system state back to a previous snapshot.
# 将系统状态回滚到之前的快照。
corix_snapshot_rollback() (
    set -e
    local name="$1"
    [[ "$name" =~ ^[a-zA-Z0-9][a-zA-Z0-9._-]*$ ]] || return 1
    local snapshot_base_path="${SNAPSHOTS_DIR}/${name}"

    [ ! -d "$snapshot_base_path" ] || [ ! -f "${snapshot_base_path}/snapshot.meta" ] && error "Snapshot '$name' not found. / 未找到快照 '$name'。"

    local type snapshot_version source_snapshot="$snapshot_base_path"
    type=$(sed -n 's/^type=//p' "$snapshot_base_path/snapshot.meta") || return 1
    snapshot_version=$(sed -n 's/^corix_version=//p' "$snapshot_base_path/snapshot.meta") || return 1
    [ "$snapshot_version" = "$CORIUM_VERSION" ] || return 1
    case "$type" in rsync|btrfs|zfs) ;; *) return 1 ;; esac
    warn "!!! DANGER ZONE !!!"
    warn "This will revert all Corium configurations, databases, and installed package records to the state of snapshot '$name'."
    warn "Your current state will be moved to a .bak directory, but this is a destructive operation."
    warn "!!! 危险区域 !!!"
    warn "此操作将把所有 Corium 配置、数据库和已安装包的记录，恢复到快照 '$name' 的状态。"
    warn "您当前的状态将被移动到一个 .bak 目录，但这仍然是一个破坏性操作。"
    read -rp "Are you absolutely sure you want to proceed? [y/N] / 您完全确定要继续吗？[y/N] " choice
    [[ ! "$choice" =~ ^[yY] ]] && { msg "Rollback cancelled. / 回滚操作已取消。"; return 0; }

    acquire_lock "system"
    trap 'release_lock "system"' RETURN
    msg "Starting rollback to snapshot '$name'... / 开始回滚到快照 '$name'..."

    local stage restored=false old_etc="" old_var=""
    stage=$(mktemp -d -p "$BUILD_TMP_DIR_BASE" "snapshot-restore.XXXXXX") || return 1
    trap 'status=$?; if ! $restored; then _rollback_filesystem_transaction; _internal_db_rollback_all_active; if [ -n "$old_etc" ] && [ -d "$old_etc" ]; then rm -rf -- "$ETC_CORIUM_DIR"; mv -- "$old_etc" "$ETC_CORIUM_DIR"; fi; if [ -n "$old_var" ] && [ -d "$old_var" ]; then rm -rf -- "$VAR_LIB_CORIUM_DIR"; mv -- "$old_var" "$VAR_LIB_CORIUM_DIR"; fi; fi; rm -rf -- "$stage"; release_lock "system"; exit "$status"' EXIT
    [ -d "$snapshot_base_path/etc" ] || return 1
    cp -a "$snapshot_base_path/etc" "$stage/etc" || return 1
    if [ "$type" = rsync ]; then
        [ -d "$snapshot_base_path/var" ] || return 1
        cp -a "$snapshot_base_path/var" "$stage/var" || return 1
        _internal_copy_sqlite_state "$snapshot_base_path/var" "$stage/var" || return 1
    fi
    # --- Step 1: Backup current state just in case ---
    # --- 步骤 1: 备份当前状态以防万一 ---
    info "Backing up current state to .bak directories... / 正在将当前状态备份到 .bak 目录..."
    local ts
    ts=$(date +%s%N)
    old_etc="${ETC_CORIUM_DIR}.bak.${ts}"
    mv -- "$ETC_CORIUM_DIR" "$old_etc" || return 1
    if [ "$type" != zfs ]; then
        old_var="${VAR_LIB_CORIUM_DIR}.bak.${ts}"
        mv -- "$VAR_LIB_CORIUM_DIR" "$old_var" || return 1
        source_snapshot="$old_var/snapshots/$name"
    fi

    # --- Step 2: Restore from snapshot ---
    # --- 步骤 2: 从快照恢复 ---
    info "Restoring state from snapshot... / 正在从快照恢复状态..."


    case "$type" in
        zfs)
            local dataset
            dataset=$(_internal_snapshot_zfs_dataset)
            zfs rollback -r "${dataset}@corix_${name}" || error "ZFS rollback failed. / ZFS 回滚失败。"
            # ZFS rollback is atomic and replaces the content, so we just need to recreate the dir structure
            # ZFS 回滚是原子的，会替换内容，我们只需重建目录结构
            mkdir -p "$ETC_CORIUM_DIR" "$VAR_LIB_CORIUM_DIR"
            cp -a "$stage/etc/." "$ETC_CORIUM_DIR/" || return 1
            ;;
        btrfs)
            # For Btrfs, we restore by creating a new read-write snapshot at the original location
            # 对于 Btrfs，我们通过在原位置创建一个新的可读写快照来进行恢复
            local subvolume_path="$source_snapshot"
            [ ! -d "$source_snapshot/var" ] || subvolume_path="$source_snapshot/var"
            btrfs subvolume snapshot "$subvolume_path" "$VAR_LIB_CORIUM_DIR" || error "Btrfs restore failed. / Btrfs 恢复失败。"
            # We must restore the config separately as it's not part of the Btrfs subvolume
            # 我们必须单独恢复配置目录，因为它不属于 Btrfs 子卷
            mkdir -p "$ETC_CORIUM_DIR"
            rsync -a "$stage/etc/" "$ETC_CORIUM_DIR/" || return 1
            ;;
        rsync)
            mkdir -p "$ETC_CORIUM_DIR" "$VAR_LIB_CORIUM_DIR"
            rsync -a "$stage/etc/" "$ETC_CORIUM_DIR/" || return 1
            rsync -a "$stage/var/" "$VAR_LIB_CORIUM_DIR/" || return 1
            ;;
        *)
            error "Unknown snapshot type '$type'. Cannot rollback. / 未知的快照类型 '$type'。无法回滚。"
            ;;
    esac

    # --- Step 3: Reconstruct system to match the restored state ---
    # --- 步骤 3: 重建系统以匹配恢复后的状态 ---
    msg "State files have been restored. Now running 'rebuild' to synchronize system reality."
    msg "状态文件已恢复。现在运行 'rebuild' 来同步系统的实际状态。"
    
    release_lock
    # Use --force to avoid interactive prompts during a rollback
    # 在回滚过程中使用 --force 来避免交互式提示
    corix_rebuild_from_world --force --prune || return 1
    restored=true
    
    msg "Rollback to snapshot '$name' complete. / 已成功回滚到快照 '$name'。"
    info "Your previous state has been saved with a .bak.${ts} suffix. / 您之前的状态已被保存，并带有 .bak.${ts} 后缀。"
)

# =======================================================
# --- SECTION 28: BACKUP AND RESTORE (NEW)            ---
# --- 第28节: 备份与恢复 (新增)                       ---
# =======================================================

# The user-facing command dispatcher for 'corix backup'.
# 'corix backup' 的用户侧命令分发器。
corix_backup() {
    check_permissions "backup"
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        create)
            [ $# -lt 1 ] && error "Usage: corix backup create <output_file.tar.gz> [--encrypt] [--no-private-keys] / 用法: corix backup create <输出文件.tar.gz> [--encrypt] [--no-private-keys]"
            corix_backup_create "$@"
            ;;
        restore)
            [ $# -lt 1 ] && error "Usage: corix backup restore <input_file> / 用法: corix backup restore <输入文件>"
            corix_backup_restore "$1"
            ;;
        *)
            echo "corix backup: Create or restore a portable archive of the system state."
            echo "corix backup: 创建或恢复一个可移植的系统状态压缩包。"
            echo
            echo "  create <file> [--encrypt] [--no-private-keys]"
            echo "      Create a backup archive. (创建备份压缩包)"
            echo "      --encrypt          : Symmetrically encrypt the backup with GPG. (使用GPG对称加密备份)"
            echo "      --no-private-keys  : Exclude sensitive private keys from the backup. (从备份中排除敏感的私钥)"
            echo "  restore <file>"
            echo "      Restore system state from a backup archive. (从备份压缩包恢复系统状态)"
            ;;
    esac
}

# Creates a portable backup archive.
# 创建一个可移植的备份压缩包。
_internal_copy_sqlite_state() {
    "${PYTHON_CMD}" - "$1" "$2" <<'PY_SQLITE_STATE_COPY'
import pathlib,sqlite3,sys,tempfile,os
root=pathlib.Path(sys.argv[1]); target=pathlib.Path(sys.argv[2])
for source in root.rglob('*.db'):
    if source.is_symlink(): raise ValueError('Symlink state database')
    if 'snapshots' in source.relative_to(root).parts: continue
    with source.open('rb') as f:
        if f.read(16)!=b'SQLite format 3\x00': raise ValueError('Corrupt state database')
    output=target/source.relative_to(root); output.parent.mkdir(parents=True,exist_ok=True)
    fd,temporary=tempfile.mkstemp(prefix='.snapshot.',dir=output.parent);os.close(fd)
    try:
        with sqlite3.connect(source.resolve().as_uri()+'?mode=ro',uri=True,timeout=10) as src, sqlite3.connect(temporary) as dst:
            if src.execute('PRAGMA integrity_check').fetchall()!=[('ok',)]: raise ValueError('Corrupt state database')
            src.backup(dst)
        os.replace(temporary,output)
        pathlib.Path(str(output)+'-wal').unlink(missing_ok=True); pathlib.Path(str(output)+'-shm').unlink(missing_ok=True)
    finally:
        if os.path.exists(temporary): os.unlink(temporary)
PY_SQLITE_STATE_COPY
}

corix_backup_create() {
    local output_file="$1"
    shift
    local encrypt=0
    local no_private_keys=0

    while [ $# -gt 0 ]; do
        case "$1" in
            --encrypt) encrypt=1; shift ;;
            --no-private-keys) no_private_keys=1; shift ;;
            *) error "backup create: Unknown option '$1' / 未知选项 '$1'" ;;
        esac
    done

    acquire_lock "system"
    trap 'release_lock "system"' RETURN
    
    msg "Creating backup archive... / 正在创建备份压缩包..."
    
    # 计算需要备份的总大小 (以 KB 为单位)
    #，Calculate the total size (in KB) that needs to be backed up
    local size_etc_kb=$(du -sk "$ETC_CORIUM_DIR" | awk '{print $1}')
    local size_var_kb=$(du -sk "$VAR_LIB_CORIUM_DIR" | awk '{print $1}')
    # 转换为 MB 并增加 10% 的余量
    # Convert to MB and increase margin by 10%
    local total_needed_mb=$(( (size_etc_kb + size_var_kb) * 11 / 10 / 1024 ))
    # 检查输出文件所在的目录
    # Check the directory where the output file is located
    _check_disk_space "$(dirname "$output_file")" "$total_needed_mb"
    
    detail "Output file / 输出文件: $output_file"
    
    check_dep gpg

    local temp_backup_dir
    temp_backup_dir=$(mktemp -d -p "$BUILD_TMP_DIR_BASE" "backup-prep.XXXXXX")
    CORIUM_TEMP_ITEMS+=("$temp_backup_dir")

    info "Collecting state files into a temporary directory... / 正在将状态文件收集到临时目录..."
    cp -a "$ETC_CORIUM_DIR" "${temp_backup_dir}/etc_corix"
    cp -a "$VAR_LIB_CORIUM_DIR" "${temp_backup_dir}/var_lib_corix"
    _internal_copy_sqlite_state "$VAR_LIB_CORIUM_DIR" "${temp_backup_dir}/var_lib_corix" || return 1

    if [ "$no_private_keys" -eq 1 ]; then
        info "Excluding private keys as requested... / 根据请求排除私钥..."
        rm -f "${temp_backup_dir}/etc_corix/identity.key"
        rm -f "${temp_backup_dir}/etc_corix/tls.key"
        # Also remove GPG keyrings as they can be sensitive
        # 同时移除 GPG 密钥环，因为它们也可能包含敏感信息
        rm -rf "${temp_backup_dir}/etc_corix/trust_zones"/*/*.gpg*
        detail "Private keys and GPG keyrings removed from backup. / 私钥和 GPG 密钥环已从备份中移除。"
    fi
    
    info "Creating tarball... / 正在创建 tar 压缩包..."
    if [ "$encrypt" -eq 1 ]; then
        info "Encrypting backup with GPG. Please enter a password when prompted."
        info "正在使用 GPG 加密备份。请在提示时输入密码。"
        tar -C "$temp_backup_dir" -czf - . | gpg --symmetric --cipher-algo AES256 -o "${output_file}.gpg"
        detail "Encrypted backup created / 已创建加密备份: ${output_file}.gpg"
    else
        local staged_backup
        staged_backup=$(mktemp "${output_file}.XXXXXX") || return 1
        CORIUM_TEMP_ITEMS+=("$staged_backup")
        tar -C "$temp_backup_dir" -czf "$staged_backup" . || return 1
        mv -f -- "$staged_backup" "$output_file" || return 1
        detail "Backup created / 已创建备份: $output_file"
    fi

    msg "Backup creation complete. / 备份创建完成。"
}

# Restores system state from a backup archive.
# 从备份压缩包恢复系统状态。
corix_backup_restore() (
    set -e
    local input_file="$1" choice
    [ -f "$input_file" ] || return 1
    warn "恢复将覆盖当前 Corium 状态。/ Restore will overwrite the current Corium state."
    read -rp "确认恢复？[y/N] / Confirm restore? [y/N] " choice || return 1
    [[ "$choice" =~ ^[yY]$ ]] || return 0
    acquire_lock "system" || return 1
    local temp_restore_dir archive="$input_file" old_etc="" old_var="" restored=false
    mkdir -p "$BUILD_TMP_DIR_BASE" || return 1
    temp_restore_dir=$(mktemp -d -p "$BUILD_TMP_DIR_BASE" "restore-extract.XXXXXX") || return 1
    trap 'status=$?; if ! $restored; then if [ -n "$old_var" ] && [ -d "$old_var" ]; then rm -rf -- "$VAR_LIB_CORIUM_DIR"; mv -- "$old_var" "$VAR_LIB_CORIUM_DIR"; fi; if [ -n "$old_etc" ] && [ -d "$old_etc" ]; then rm -rf -- "$ETC_CORIUM_DIR"; mv -- "$old_etc" "$ETC_CORIUM_DIR"; fi; fi; rm -rf -- "$temp_restore_dir"; release_lock "system"; exit "$status"' EXIT
    if [[ "$input_file" == *.gpg ]]; then
        check_dep gpg
        archive="$temp_restore_dir/decrypted.tar.gz"
        gpg -d -- "$input_file" > "$archive" || return 1
    fi
    _validate_archive "$archive" || return 1
    mkdir "$temp_restore_dir/extracted" || return 1
    tar -C "$temp_restore_dir/extracted" -xzf "$archive" || return 1
    "${PYTHON_CMD}" - "$temp_restore_dir/extracted" <<'PY_VALIDATE_RESTORE'
import pathlib,sqlite3,json,sys
root=pathlib.Path(sys.argv[1]); etc=root/'etc_corix'; var=root/'var_lib_corix'
if not etc.is_dir() or not var.is_dir() or etc.is_symlink() or var.is_symlink(): raise ValueError('Incomplete backup structure')
for path in root.rglob('*'):
    if path.is_symlink():
        try: path.resolve().relative_to(root.resolve())
        except ValueError: raise ValueError('Backup symlink escapes restored state')
for relative in ('blockchain/chain.db','forum/forum.db'):
    path=var/relative
    if not path.is_file(): raise ValueError('Missing state database')
    with sqlite3.connect(path.resolve().as_uri()+'?mode=ro',uri=True) as db:
        if db.execute('PRAGMA integrity_check').fetchall()!=[('ok',)]: raise ValueError('Corrupted restore database')
if not (etc/'genesis.json').is_file(): raise ValueError('Missing recovery anchor')
json.load((etc/'genesis.json').open())
PY_VALIDATE_RESTORE
    # Stage complete replacements beside their final directories for atomic rename.
    local new_etc new_var
    new_etc=$(mktemp -d "${ETC_CORIUM_DIR}.restore.XXXXXX") || return 1
    new_var=$(mktemp -d "${VAR_LIB_CORIUM_DIR}.restore.XXXXXX") || return 1
    cp -a "$temp_restore_dir/extracted/etc_corix/." "$new_etc/" || return 1
    cp -a "$temp_restore_dir/extracted/var_lib_corix/." "$new_var/" || return 1
    old_etc=$(mktemp -d "${ETC_CORIUM_DIR}.previous.XXXXXX") || return 1
    old_var=$(mktemp -d "${VAR_LIB_CORIUM_DIR}.previous.XXXXXX") || return 1
    rmdir "$old_etc" "$old_var" || return 1
    if [ -d "$ETC_CORIUM_DIR" ]; then mv -- "$ETC_CORIUM_DIR" "$old_etc" || return 1; fi
    if [ -d "$VAR_LIB_CORIUM_DIR" ]; then mv -- "$VAR_LIB_CORIUM_DIR" "$old_var" || return 1; fi
    mv -- "$new_etc" "$ETC_CORIUM_DIR" || return 1
    mv -- "$new_var" "$VAR_LIB_CORIUM_DIR" || return 1
    restored=true
    rm -rf -- "$old_etc" "$old_var"
    msg "恢复完成。/ Restore complete."
)


# 文件: corix.sh (新增函数)
# File: corix.sh (NEW FUNCTION)

# =======================================================================================
# --- [V95 Phoenix Protocol] 内联状态证明生成器源码                             ---
# --- [V95 Phoenix Protocol] Inlined State Prover Source Code                   ---
# =======================================================================================
# 此函数作为一个容器，存储了 corix-state-prover 工具的完整 Python 源代码。
# This function acts as a container for the full Python source code of the
# corix-state-prover tool.
_corix_get_state_prover_source() {
# 使用 cat <<'EOF' 的形式可以防止 Shell 对 HEREDOC 内部的美元符号($)和反引号()进行变量替换。
# Using cat <<'EOF' prevents the shell from expanding variables like $ or  inside the HEREDOC.
cat <<'EOF_STATE_PROVER'
#!/usr/bin/env python3
# -*- coding: utf-8 -*-

# ==============================================================================
#  corix-state-prover - Corium 状态默克尔证明生成器 v1.0
#  Corium State Merkle Proof Generator v1.0
#
#  这是一个独立的、高性能的工具，用于为 Corium 的灾难恢复协议生成状态证明。
#  This is a standalone, high-performance tool for generating state proofs for
#  Corium's disaster recovery protocol.
# ==============================================================================

import sqlite3
import hashlib
import json
import sys
import argparse
import os
import pathlib

def bilingual_print(message_en, message_zh, level="INFO", file=sys.stderr):
    """
    打印双语消息到指定的输出流。
    Prints a bilingual message to the specified output stream.
    """
    print(f"PROVER_LOG|{level}| {message_en} / {message_zh}", file=file)

def hash_func(data):
    """
    对输入数据进行 SHA-256 哈希计算。
    Calculates the SHA-256 hash of the input data.
    """
    if isinstance(data, str):
        data = data.encode('utf-8')
    return hashlib.sha256(data).hexdigest()
    
def build_merkle_tree(leaves):
    """从一个叶子节点列表构建一个完整的默克尔树。/ Builds a full Merkle tree from a list of leaves."""
    if not leaves:
        return [[hash_func('')]]
    
    # 为保证确定性，叶子节点必须排序
    # Leaves must be sorted for a deterministic tree
    tree = [sorted(leaves)]
    
    current_level = tree[0]
    while len(current_level) > 1:
        next_level = []
        
        for i in range(0, len(current_level), 2):
            left = current_level[i]
            if i + 1 < len(current_level):
                right = current_level[i+1]
            else:
                # 如果是奇数个节点，最后一个节点与自身配对计算父哈希
                # If odd number of nodes, the last one is paired with itself for the parent hash
                right = left
            parent = hash_func(left + right)
            next_level.append(parent)
        
        tree.append(next_level)
        current_level = next_level
        
    return tree

def get_merkle_proof(tree, target_leaf):
    """
    为目标叶子节点生成密码学上正确的默克尔证明（兄弟哈希列表）。
    Generates a cryptographically correct Merkle proof (list of sibling hashes) for a target leaf.
    """
    if not tree or target_leaf not in tree[0]:
        bilingual_print(f"Target leaf {target_leaf[:10]}... not in the tree's base.", f"目标叶子节点 {target_leaf[:10]}... 不在树的底层。", "DEBUG")
        return None
    
    proof = []
    current_index = tree[0].index(target_leaf)
    
    # 从底层开始，逐层向上，直到根的下一层
    # Iterate from the bottom level up to the one below the root
    for i in range(len(tree) - 1):
        level_nodes = tree[i]
        num_nodes_in_level = len(level_nodes)
        
        # 检查当前节点是否是该层的最后一个，并且该层节点总数为奇数
        # Check if the current node is the last one on an odd-numbered level
        is_last_and_odd = (current_index == num_nodes_in_level - 1) and (num_nodes_in_level % 2 == 1)
        
        if is_last_and_odd:
            # 如果是，它没有兄弟节点，这一层无需提供证明。
            # If so, it has no sibling, and no proof is needed for this level.
            # 验证者在重构时也会独立发现这一点。
            # The verifier will independently discover this during reconstruction.
            proof.append({"hash": level_nodes[current_index], "position": "right"})
        else:
            is_right_node = current_index % 2 != 0
            if is_right_node:
                # 兄弟在左边
                # The sibling is on the left
                sibling_index = current_index - 1
                proof.append({"hash": level_nodes[sibling_index], "position": "left"})
            else:
                # 兄弟在右边
                # The sibling is on the right
                sibling_index = current_index + 1
                proof.append({"hash": level_nodes[sibling_index], "position": "right"})

        # 计算在上一层中的索引
        # Calculate the index in the parent level
        current_index //= 2
        
    return proof
    
def main():
    """主执行函数。/ Main execution function."""
    parser = argparse.ArgumentParser(
        description="Corium 状态默克尔证明生成器 (Corium State Merkle Proof Generator).",
        formatter_class=argparse.RawTextHelpFormatter
    )
    parser.add_argument("--db-path", required=True, help="[必须] 指向区块链或应用数据库的路径。\n[Required] Path to the blockchain or application database.")
    parser.add_argument("--height", required=True, type=int, help="[必须] 状态快照所在的区块高度。\n[Required] The block height of the state snapshot.")
    parser.add_argument("--asset-type", required=True, choices=['contribution_score', 'nns_record', 'group_membership'], help="[必须] 需要证明的资产/状态的类型。\n[Required] The type of asset/state to prove.")
    parser.add_argument("--owner-id", required=True, help="[必须] 资产/状态的所有者的ID。\n[Required] The ID of the owner of the asset/state.")
    # (未来可以增加 --domain-name 等参数来定位更具体的资产)
    # (Future arguments like --domain-name can be added to locate more specific assets)
    
    args = parser.parse_args()

    try:
        conn = sqlite3.connect(pathlib.Path(args.db_path).resolve().as_uri()+"?mode=ro", uri=True)
        cursor = conn.cursor()
    except sqlite3.Error as e:
        bilingual_print(f"Error connecting to database: {e}", f"连接数据库时出错: {e}", "FATAL", file=sys.stdout)
        sys.exit(1)

    leaves = []
    target_leaf_data_unhashed = None
    
    bilingual_print("Extracting and serializing state leaves from database...", "正在从数据库提取并序列化状态叶子节点...")

    # 根据资产类型，从数据库中提取所有相关状态，并序列化为确定性的叶子节点
    # Based on asset type, extract all relevant state and serialize into deterministic leaves
    if args.asset_type == 'contribution_score':
        cursor.execute("SELECT user_id, score FROM contribution_scores ORDER BY user_id")
        for user_id, score in cursor.fetchall():
            leaf_data = f"score|{user_id}|{score}" # 使用带前缀的格式以避免跨类型冲突 / Use a prefixed format to avoid cross-type collisions
            leaves.append(hash_func(leaf_data))
            if user_id == args.owner_id:
                target_leaf_data_unhashed = leaf_data
                target_leaf_data_structured = {"user_id": user_id, "score": score}
    
    elif args.asset_type == 'nns_record':
        cursor.execute("SELECT domain_name, owner_id, target_hash FROM nns_records ORDER BY domain_name")
        for domain, owner, target in cursor.fetchall():
             leaf_data = f"nns|{domain}|{owner}|{target}"
             leaves.append(hash_func(leaf_data))
             if owner == args.owner_id: # (这是一个简化的查找，实际可能需要 --domain-name)
                 target_leaf_data_unhashed = leaf_data
                 target_leaf_data_structured = {"domain_name": domain, "owner_id": owner, "target_hash": target}

    elif args.asset_type == 'group_membership':
        cursor.execute("SELECT acl_id,grantee_id,permissions FROM acl_state ORDER BY acl_id,grantee_id")
        for group,member,raw in cursor.fetchall():
            permissions=json.loads(raw)
            if not isinstance(permissions,list) or not all(isinstance(p,str) for p in permissions): raise ValueError('Malformed membership permissions')
            if not any(p in permissions for p in ('member','owner','admin')): continue
            canonical=json.dumps(sorted(set(permissions)),ensure_ascii=False,separators=(',',':'))
            leaf_data=f'group|{group}|{member}|{canonical}'
            leaves.append(hash_func(leaf_data))
            if member==args.owner_id:
                target_leaf_data_unhashed=leaf_data
                target_leaf_data_structured={'group_id':group,'member_id':member,'permissions':sorted(set(permissions))}
    
    conn.close()

    if not leaves:
        bilingual_print("No state leaves found for the given asset type.", "未找到指定资产类型的状态叶子节点。", "ERROR", file=sys.stdout)
        sys.exit(1)
        
    if not target_leaf_data_unhashed:
        bilingual_print("The specified owner ID was not found in the state snapshot for this asset type.", "在此资产类型的状态快照中未找到指定的所有者ID。", "ERROR", file=sys.stdout)
        sys.exit(1)
    
    target_leaf_hash = hash_func(target_leaf_data_unhashed)
        
    bilingual_print("Building Merkle tree from state leaves...", "正在从状态叶子节点构建默克尔树...")
    tree = build_merkle_tree(leaves)
    state_root_hash = tree[-1][0]
    
    bilingual_print("Generating Merkle proof for the target leaf...", "正在为目标叶子节点生成默克尔证明...")
    proof = get_merkle_proof(tree, target_leaf_hash)

    if proof is None:
        bilingual_print("Failed to generate Merkle proof. Target leaf might not be in the tree.", "生成默克尔证明失败。目标叶子节点可能不在树中。", "FATAL", file=sys.stdout)
        sys.exit(1)

    # 输出最终的、标准化的 JSON 证明
    # Output the final, standardized JSON proof
    final_proof = {
        "source_chain": os.environ.get('CORIUM_NETWORK_ID', 'unknown'),
        "block_height": args.height,
        "state_root_hash": state_root_hash,
        "asset_type": args.asset_type,
        "asset_data": target_leaf_data_structured,
        "merkle_proof": {
            "target_leaf_hash": target_leaf_hash,
            "siblings": proof
        }
    }
    
    # 打印最终的 JSON 到标准输出，这是与 corix.sh 交互的唯一方式
    # Print the final JSON to stdout, which is the only way to interact with corix.sh
    print(json.dumps(final_proof, indent=2))

if __name__ == "__main__":
    main()

EOF_STATE_PROVER
}

# =======================================================================================
# --- [V95 Phoenix Protocol] 状态证明生成器安装命令                          ---
# --- [V95 Phoenix Protocol] State Prover Installer Command                     ---
# =======================================================================================
# 此函数将内联的 corix-state-prover Python 脚本安装到系统中，使其成为一个可执行命令。
# This function installs the inlined corix-state-prover Python script into the
# system, making it an executable command.
corix_setup_prover() {
    # 优先选择的安装路径
    # Preferred installation paths
    local -a INSTALL_DIRS=(
        "/usr/local/bin"
        "/usr/bin"
        "$HOME/.local/bin"
    )
    
    local dest_dir=""
    # 寻找第一个存在且可写的目录
    # Find the first directory that exists and is writable
    for dir in "${INSTALL_DIRS[@]}"; do
        if [ -d "$dir" ] && [ -w "$dir" ]; then
            dest_dir="$dir"
            break
        fi
    done

    if [ -z "$dest_dir" ]; then
        error "未能找到可写的安装目录。 / Could not find a writable installation directory."
        info "请尝试使用 'sudo' 运行此命令，或者确保 '$HOME/.local/bin' 存在并已添加到您的 PATH。 / Please try running this command with 'sudo', or ensure '$HOME/.local/bin' exists and is in your PATH."
        return 1
    fi
    
    local dest_file="${dest_dir}/corix-state-prover"

    # --- 幂等性检查：如果文件已存在且内容相同，则无需操作 ---
    # --- Idempotency Check: If the file exists and content is identical, do nothing ---
    if [ -f "$dest_file" ]; then
        local new_hash; new_hash=$(_corix_get_state_prover_source | calculate_hash)
        local old_hash; old_hash=$(calculate_hash "$dest_file")
        if [ "$new_hash" = "$old_hash" ]; then
            msg "状态证明生成器已安装且为最新版本。 / State proof generator is already installed and up-to-date."
            info "路径 / Path: ${dest_file}"
            return 0
        fi
    fi

    info "正在将状态证明生成器安装到: ${dest_file} / Installing state proof generator to: ${dest_file}"
    # 调用“数据容器”函数，并通过管道将源码写入目标文件
    # Call the "data container" function and pipe the source code to the destination file
    if ! _corix_get_state_prover_source > "$dest_file"; then
        error "写入文件失败！请检查权限。 / Failed to write file! Please check permissions."
        return 1
    fi
    
    # 赋予执行权限
    # Grant execute permissions
    chmod +x "$dest_file"
    
    msg "✅ 状态证明生成器已成功安装。 / State proof generator installed successfully."
    info "您现在可以在命令行中直接使用 'corix-state-prover' 命令。/ You can now use the 'corix-state-prover' command directly from your terminal."
}
# =======================================================
# --- SECTION 28.5: SYSTEM STOPPAGE (NEW)             ---
# --- 第28.5节: 系统停止 (新增)                       ---
# =======================================================

# =======================================================
# --- [V74 Stop-Fix] _stop_daemons (多层防御版)       ---
# --- [V74 Stop-Fix] _stop_daemons (Multi-Layered Defense) ---
# =======================================================
# =======================================================================================
# --- [V74.1 Stop-Fix] _stop_daemons (多层防御与PID文件管理整合版)                  ---
# --- [V74.1 Stop-Fix] _stop_daemons (Multi-Layered Defense & PID File Mgmt Integrated) ---
# =======================================================================================
# =======================================================================================
# --- [V104.2 FINAL] _stop_daemons (多层防御与后备清扫整合版)                       ---
# --- [V104.2 FINAL] _stop_daemons (Multi-Layered Defense with Integrated Sweep)    ---
# =======================================================================================
# This function provides a robust, multi-layered approach to stopping all known
# Corium background services. It prioritizes using PID files for accuracy and falls
# back to process sweeping for resilience.
#
# 此函数提供了一个健壮的、多层防御的方法来停止所有已知的 Corium 后台服务。
# 它优先使用 PID 文件以保证准确性，并回退到进程清扫以确保韧性。
#
# @param $1 - (可选) "force"，如果提供，则跳过优雅等待，直接强制终止。
#             (Optional) "force", if provided, skips the graceful wait and terminates forcefully.
_stop_daemons() {
    local force_mode="${1:-}"
    local main_pid_file="$DAEMON_PID_FILE"
    local relayer_pid_file="$RELAYER_PID_FILE"
    local services_were_running=0

    # --- 第一层防御：通过 PID 文件精确停止 (Layer 1: Precise Stop via PID Files) ---
    info "正在通过 PID 文件检查并停止核心服务... / Checking and stopping core services via PID files..."

    for pid_file in "$main_pid_file" "$relayer_pid_file"; do
        if [ ! -f "$pid_file" ]; then continue; fi
        
        local pid
        pid=$(cat "$pid_file" 2>/dev/null)
        if [ -n "$pid" ] && kill -0 "$pid" 2>/dev/null; then
            services_were_running=1
            info "  -> 正在向进程 (PID: ${pid}) 发送 SIGTERM 信号... / Sending SIGTERM to process (PID: ${pid})..."
            kill "$pid" 2>/dev/null # 尝试优雅地发送 SIGTERM / Attempt graceful SIGTERM
        else
            rm -f "$pid_file" # 清理无效的 PID 文件 / Clean up stale PID file
        fi
    done

    if [ "$services_were_running" -eq 1 ] && [ "$force_mode" != "force" ]; then
        info "  -> 正在等待服务优雅地退出 (最多5秒)... / Waiting up to 5s for services to exit gracefully..."
        local countdown=5
        while [ "$countdown" -gt 0 ]; do
            # 检查所有已知 PID 文件对应的进程是否都已退出
            # Check if processes for all known PID files have exited
            if ! ( [ -f "$main_pid_file" ] && kill -0 "$(cat "$main_pid_file" 2>/dev/null)" 2>/dev/null ) && \
               ! ( [ -f "$relayer_pid_file" ] && kill -0 "$(cat "$relayer_pid_file" 2>/dev/null)" 2>/dev/null ); then
                break # 所有进程都已退出 / All processes have exited
            fi
            sleep 1; countdown=$((countdown - 1))
        done
    fi

    # --- 第二层防御：后备清扫 (Layer 2: Fallback Sweep) ---
    info "正在执行后备清扫，以查找并终止任何残留的 Corium 进程... / Performing fallback sweep for any remaining Corium processes..."
    
    local pids_to_kill
    # 使用 pgrep 查找所有可能的守护进程，-f 标志匹配整个命令行
    # Use pgrep with the -f flag to match against the full command line
    mapfile -t pids_to_kill < <(pgrep -f "Corium Python Unified Daemon|Corium Built-in IBC Relayer|_consensus_daemon_loop" | grep -v "^$$\$")

    if [ ${#pids_to_kill[@]} -gt 0 ]; then
        warn "  -> 发现 ${#pids_to_kill[@]} 个残留进程。正在强制终止... / Found ${#pids_to_kill[@]} lingering processes. Force terminating..."
        # 使用 SIGKILL (-9) 确保进程被终止
        # Use SIGKILL (-9) to ensure termination
        kill -9 "${pids_to_kill[@]}" 2>/dev/null || true
    else
        info "  -> 未发现残留进程。 / No lingering processes found."
    fi

    # --- 最后一步：清理所有 PID 文件 ---
    # --- Final Step: Clean up all PID files ---
    rm -f "$main_pid_file" "$relayer_pid_file" 2>/dev/null
    msg "停止流程完成。 / Shutdown process complete."
}



# The user-facing command to stop Corium services.
# 面向用户的、用于停止 Corium 服务的命令。

# =======================================================================================
# --- [V104.1 修复] corix_stop (健壮版)                                               ---
# =======================================================================================
corix_stop() {
    local force=0
    if [ "${1:-}" = "-f" ] || [ "${1:-}" = "--force" ]; then
        force=1
    fi
    
    # --- [V103.2 核心修改] 创建信号文件，通知监控循环不要重启 ---
    # --- [V103.2 CORE FIX] Create the signal file to tell the monitor loop not to restart ---
    info "正在发送停止信号... / Sending stop signal..."
    touch "$DAEMON_STOP_FLAG_FILE"

    # --- [V103.1 核心修改] 移除了对系统锁的请求 ---
    # --- [V103.1 CORE FIX] Removed the request for the system lock ---
    # stop 命令的职责是停止服务，不应与安装等文件系统操作竞争同一个锁。
    # The 'stop' command's responsibility is to stop services and should not compete for the same lock
    # as filesystem operations like 'install'.

    if [ "$force" -eq 1 ]; then
        warn "强制停止已启动。将立即终止所有 Corium 后台服务。/ Force-stop initiated. This will immediately terminate all Corium background services."
        # 直接调用 _stop_daemons 的强制模式
        # Directly call _stop_daemons in force mode
        _stop_daemons "force"
    else
        msg "正在启动 Corium 服务的优雅关停流程... / Initiating graceful shutdown of Corium services..."
        # 调用 _stop_daemons 的默认（优雅）模式
        # Call _stop_daemons in its default (graceful) mode
        _stop_daemons
    fi
}


# =======================================================================================
# --- FILE: corix.sh (NEW INTERNAL FUNCTION) for GIMPS                              ---
# --- 文件: corix.sh (新的内部函数) 用于GIMPS                                         ---
# =======================================================================================
# This is the built-in, deterministic task generator specifically for GIMPS-like engines.
# It is called by the main task dispatcher when a compute engine is identified as 'built-in'.
#
# 这是专为类GIMPS引擎设计的、内置的、确定性的任务生成器。
# 当一个计算引擎被识别为“内置”时，主任务分发器会调用此函数。
#
# @param $1 - engine_id
# @param $2 - problem_set_id
# @param $3 - problem_set_metadata (JSON string)
# @return "problem_id|task_data" to stdout, or empty on failure/completion.
#         向标准输出返回 "problem_id|task_data"，如果失败或已完成则返回空。
_internal_generate_gimps_task() {
    local engine_id="$1"
    local set_id="$2"
    local metadata="$3"

    local task_info
    task_info=$(_corium_gimps_consensus next-task "$BLOCKCHAIN_DB" "$engine_id" "$set_id" "$metadata" 2>/dev/null)
    if [ $? -eq 0 ] && [ -n "$task_info" ]; then
        echo "$task_info"
        return 0
    else
        detail "[Compute] GIMPS 问题集 '${set_id:0:12}...' 中暂无可用新任务或所有任务已完成。 / No available new tasks or all tasks complete in GIMPS problem set '${set_id:0:12}'."
        return 1
    fi
}

# =======================================================================================
# --- [批次三 新增] 核心任务生成器 (V62.5 - 最终、完整、资源友好版)                     ---
# --- [BATCH THREE NEW] Core Task Generator (V62.5 - Final, Complete, Resource-Friendly) ---
# =======================================================================================
# This function deterministically generates the current computation task. It prioritizes
# on-chain governed engines, but falls back to a built-in, protocol-defined "Engine Zero"
# to ensure the system can always bootstrap itself without external dependencies.
#
# 此函数确定性地生成当前的计算任务。它优先使用链上治理的引擎，但会回退到一个
# 内置的、协议定义的“零号引擎”，以确保系统总能在没有外部依赖的情况下自举。
#
# @output (stdout) A single line containing the task description in the format:
#                   "engine_id|problem_id|task_data|compute_program_hash|verifier_script_hash"
# @返回 (标准输出)  一个单行的任务描述，格式如下:
#                   "引擎ID|问题ID|任务数据|计算程序哈希|验证脚本哈希"
# =======================================================================================
# --- FILE: corix.sh (FINAL ARCHITECTURE + GIMPS) in SECTION 32.5                     ---
# --- 文件: corix.sh (最终架构 + GIMPS) 位于 第32.5节                               ---
# =======================================================================================
_get_current_compute_task() {
    local requested_engine="${1:-}"
    local tasks_found=0
    local current_chain_height
    current_chain_height=$(db_query_static "$BLOCKCHAIN_DB" "SELECT COALESCE(MAX(height), 0) FROM blocks;")

    # --- 步骤 1: 查找所有当前链上激活的计算引擎 Mod ---
    while IFS='|' read -r engine_id pkg_id compute_program_hash verifier_script_hash description; do
        
        if [ -n "$requested_engine" ] && [ "$engine_id" != "$requested_engine" ]; then continue; fi
        local active_problem_set_info
        active_problem_set_info=$(db_query_safe "$BLOCKCHAIN_DB" \
            "SELECT set_id, metadata FROM problem_sets WHERE engine_id = %s AND activation_height IS NOT NULL AND activation_height <= %d ORDER BY activation_height DESC LIMIT 1;" \
            "$engine_id" "$current_chain_height")

        if [[ -z "$active_problem_set_info" ]]; then
            detail "  -> 引擎 '${engine_id:0:12}...' 没有激活的问题集，跳过。 / Engine '${engine_id:0:12}...' has no active problem set, skipping."
            continue
        fi
        
        local set_id metadata
        IFS='|' read -r set_id metadata <<< "$active_problem_set_info"
        
        local task_generation_output=""
        # ==================================================================
        # --- [V88 混合模型] 检查是否是内置支持的引擎               ---
        # --- [V88 Hybrid Model] Check if this is a built-in supported engine ---
        # ==================================================================
        if [[ "$pkg_id" == "corium/built-in-gimps" ]]; then
            detail "[Compute] 检测到内置 GIMPS 引擎，正在使用内部任务生成器... / Detected built-in GIMPS engine, using internal task generator..."
            task_generation_output=$(_internal_generate_gimps_task "$engine_id" "$set_id" "$metadata")
        else
            # --- 对于所有其他引擎，走通用的沙箱化接口 ---
            # --- For all other engines, use the generic sandboxed interface ---
            detail "[Compute] 正在向 Mod '${pkg_id}' 请求下一个任务... / Requesting next task from Mod '${pkg_id}'..."
            local executable_path
            executable_path=$(_get_mod_executable_path "$pkg_id")

            if [[ -z "$executable_path" || ! -x "$executable_path" ]]; then
                warn "  -> 引擎 Mod '${pkg_id}' 的可执行文件未找到或不可执行，跳过。 / Executable for engine Mod '${pkg_id}' not found or not executable, skipping."
                continue
            fi
            
            task_generation_output=$(_execute_mod_in_sandbox "$pkg_id" "contribution_compute" "$executable_path" "get-next-task")
        fi

        # --- 后续处理逻辑统一 ---
        # --- Subsequent processing logic is unified ---
        if [ $? -ne 0 ] || [ -z "$task_generation_output" ]; then
            detail "  -> 引擎 '${pkg_id}' 未返回任何任务（可能已完成）。 / Engine '${pkg_id}' returned no task (may be complete)."
            continue
        fi
        
        local problem_id task_data
        IFS='|' read -r problem_id task_data <<< "$task_generation_output"

        if [ -z "$problem_id" ] || [ -z "$task_data" ]; then
            warn "  -> 引擎 '${pkg_id}' 返回了格式无效的任务，跳过。 / Engine '${pkg_id}' returned a malformed task, skipping."
            continue
        fi
        
        echo "${engine_id}|${problem_id}|${task_data}|${compute_program_hash}|${verifier_script_hash}|${description}"
        tasks_found=1
    done < <(db_query_safe "$BLOCKCHAIN_DB" "SELECT engine_id, pkg_id, compute_program_hash, verifier_script_hash, description FROM compute_engines WHERE is_active = 1;")

    # --- 回退到内置的“零号引擎” (难度已调整为2) ---
    if [ "$tasks_found" -eq 0 ] && { [ -z "$requested_engine" ] || [ "$requested_engine" = corium/internal-engine-zero-v1 ]; }; then
        _apply_theme "info" "[Compute] 未在链上找到激活的社区计算任务，正在使用协议内置任务... / [Compute] No active community compute task found on-chain, using protocol-integrated task..." >&2

        local engine_id="corium/internal-engine-zero-v1"
        local HASH_CHALLENGE_DIFFICULTY=3
        local last_block_hash=$(blockchain_get_latest_hash)
        [ -z "$last_block_hash" ] && return 1 
        local problem_id="$last_block_hash"
        local task_data="${last_block_hash}|${HASH_CHALLENGE_DIFFICULTY}"
        local compute_program_hash="BUILT_IN"
        local verifier_script_hash="BUILT_IN"
        local description="协议内置的哈希算力挑战 (Protocol-integrated hash power challenge)"
        
        echo "${engine_id}|${problem_id}|${task_data}|${compute_program_hash}|${verifier_script_hash}|${description}"
    fi
}


# --- NEW HELP FUNCTION for 'work' command ---
# --- 'work' 命令的新增帮助函数 ---
usage_work() {
    echo "corix work: 通过“有用功证明”为网络做出贡献并赚取积分。"
    echo "corix work: Contribute to the network and earn points via 'Proof of Useful Work'."
    echo
    echo "用法 / Usage: corix work <subcommand>"
    echo
    echo "子命令 / Subcommands:"
    echo "  report    生成并提交一份在线时长证明报告，以获得贡献分。"
    echo "            Generate and submit an uptime proof report to gain contribution points."
    echo "  status    查看您当前的贡献分。"
    echo "            View your current contribution points."
}

# --- NEW COMMAND IMPLEMENTATION for 'work' ---
# --- 'work' 命令的新增实现 ---
corix_work() {
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        report)
            acquire_lock "network"
            trap 'release_lock "network"' RETURN

            msg "步骤 1/3: 生成本地在线时长证明... / Step 1/3: Generating local uptime proof..."
            local uptime_proof
            uptime_proof=$(_pouw_generate_uptime_proof)
            if [ $? -ne 0 ]; then
                # _pouw_generate_uptime_proof 内部会打印错误信息
                # _pouw_generate_uptime_proof will print its own error message
                return 1
            fi
            
            msg "步骤 2/3: 寻求同行交叉验证... / Step 2/3: Seeking cross-validation from peers..."
            local peer_signatures_json
            peer_signatures_json=$(_pouw_find_and_request_validation "$uptime_proof")
            
            if [ $? -ne 0 ]; then
                error "无法完成工作报告，未能获得足够的签名。 / Could not complete work report, failed to get enough signatures."
                return 1
            fi
            
            msg "步骤 3/3: 构建并提交 PoUW 报告交易... / Step 3/3: Constructing and submitting PoUW report transaction..."
            local tx_data
            tx_data=$(jq -n \
                --argjson proof "$uptime_proof" \
                --argjson sigs "$peer_signatures_json" \
                '{proof_payload: $proof, peer_signatures: $sigs}')
            
            local tx_hash
            tx_hash=$(blockchain_create_transaction "pouw_submit_report" "$tx_data")

            if [ -n "$tx_hash" ]; then
                msg "✅ 工作报告已成功提交！交易哈希 / Work report submitted successfully! Tx Hash: ${tx_hash}"
                info "   您的贡献将在报告被打包进区块并确认后计入。/ Your contribution will be credited after the report is included in a block."
            else
                error "提交报告失败。/ Failed to submit the report."
            fi
            ;;
        status)
            _update_chain_state_cache >/dev/null 2>&1
            local my_id my_points
            my_id=$(get_our_node_id)
            my_points=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT points FROM contribution_ledger WHERE node_id = %s;" "$my_id")
            
            msg "您的 PoUW 状态 / Your PoUW Status"
            echo "  ID: ${my_id}"
            echo "  贡献分 / Contribution Points: ${my_points:-0}"
            ;;
        *)
            usage_work
            ;;
    esac
}

# --- NEW HELP FUNCTION for 'consensus' command ---
# --- 'consensus' 命令的新增帮助函数 ---
usage_consensus() {
    echo "corix consensus: 与共识相关的操作 / Consensus-related operations."
    echo
    echo "用法 / Usage: corix consensus <subcommand> [arguments...]"
    echo
    echo "子命令 / Subcommands:"
    echo "  report-double-sign --header1 <path> --header2 <path>"
    echo "      报告一个验证者的双签行为。文件应包含区块头的JSON内容。"
    echo "      Report a validator's double-signing offense. Files should contain JSON content of block headers."
}

# --- NEW COMMAND IMPLEMENTATION for 'consensus' ---
# --- 'consensus' 命令的新增实现 ---
corix_consensus() {
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        report-double-sign)
            acquire_lock "network"
            trap 'release_lock "network"' RETURN
            
            local header1_file="" header2_file=""
            while [ $# -gt 0 ]; do
                case "$1" in
                    --header1) header1_file="$2"; shift 2 ;;
                    --header2) header2_file="$2"; shift 2 ;;
                    *) error "未知选项 / Unknown option: '$1'";;
                esac
            done

            [ ! -f "$header1_file" ] || [ ! -f "$header2_file" ] && { error "必须提供两个有效的区块头文件。/ Two valid block header files must be provided."; exit 1; }

            local header1_json header2_json
            header1_json=$(cat "$header1_file")
            header2_json=$(cat "$header2_file")

            # 客户端初步验证 / Client-side preliminary validation
            local validator1=$(echo "$header1_json" | jq -r .validator)
            local validator2=$(echo "$header2_json" | jq -r .validator)
            local height1=$(echo "$header1_json" | jq -r .height)
            local height2=$(echo "$header2_json" | jq -r .height)

            if [ "$validator1" != "$validator2" ] || [ "$height1" != "$height2" ]; then
                error "提供的区块头不构成双签证据：验证者或高度不匹配。/ Provided headers do not constitute double-signing evidence: validator or height mismatch."
                exit 1
            fi
            
            local tx_data
            tx_data=$(jq -n --argjson h1 "$header1_json" --argjson h2 "$header2_json" '{header1: $h1, header2: $h2}')
            
            info "正在提交双签举报交易... / Submitting double-signing report transaction..."
            blockchain_create_transaction "slashing_report_double_sign" "$tx_data"
            ;;
        *)
            usage_consensus
            ;;
    esac
}


# =======================================================
# --- NEW: IPC Gateway Client for Agent Supervisor    ---
# --- 新增: 用于 Agent Supervisor 的 IPC 网关客户端   ---
# =======================================================
# This function sends a JSON-RPC request to the running Python daemon's
# Unix socket to interact with the Agent Supervisor.
#
# 此函数向正在运行的 Python 守护进程的 Unix 套接字发送一个 JSON-RPC 请求，
# 以便与 Agent Supervisor 进行交互。
#
# @param $1 - method (The API method to call, e.g., "get_service_status")
#             (要调用的 API 方法, 例如 "get_service_status")
# @param $2 - params (A JSON array string, e.g., "[\"start\", \"my-mod:0\"]")
#             (一个 JSON 数组字符串, 例如 "[\"start\", \"my-mod:0\"]")
# @return On success, outputs the 'data' field of the JSON response to stdout.
#         On failure, prints an error to stderr and returns 1.
#         成功时，向 stdout 输出 JSON 响应的 'data' 字段。
#         失败时，向 stderr 打印错误并返回 1。
_service_ipc_call() {
    local method="$1"
    local params="${2:-[]}" # Default to an empty JSON array / 默认为一个空的 JSON 数组
    
    # 检查核心依赖 socat
    # Check for the core dependency socat
    check_dep socat
    
    local ipc_socket="${CORIUM_ROOT%/}/run/corix.${CORIUM_NETWORK_ID_OVERRIDE:-default}.sock"
    
    if [ ! -S "$ipc_socket" ]; then
        error "无法连接到 Corium 守护进程。它是否正在运行？/ Cannot connect to the Corium daemon. Is it running?"
        return 1
    fi
    
    # 构造 JSON-RPC 请求
    # Construct the JSON-RPC request
    # 我们将 mod_name 设为 'corix-cli' 以表明请求来源
    # We set mod_name to 'corix-cli' to identify the request source
    local request_json
    request_json=$(jq -n \
        --argjson id "$RANDOM" \
        --arg method "$method" \
        --argjson params "$params" \
        '{jsonrpc: "2.0", id: $id, method: $method, params: $params, mod_name: "corix-cli"}')

    # 使用 socat 发送请求并捕获响应
    # Use socat to send the request and capture the response
    local response_json
    response_json=$(echo "$request_json" | socat -T 10 - UNIX-CONNECT:"$ipc_socket" 2>/dev/null)
    local exit_code=$?
    
    if [ "$exit_code" -ne 0 ] || [ -z "$response_json" ]; then
        error "与守护进程的 IPC 通信失败。/ IPC communication with the daemon failed."
        return 1
    fi

    # 解析响应
    # Parse the response
    if echo "$response_json" | jq -e '.error' >/dev/null; then
        local error_msg
        error_msg=$(echo "$response_json" | jq -r '.error.message // "Unknown error"')
        error "Supervisor API 调用失败 / Supervisor API call failed: ${error_msg}"
        return 1
    else
        # 成功时，提取并输出 'result' 字段的内容
        # On success, extract and output the content of the 'result' field
        echo "$response_json" | jq -c '.result'
        return 0
    fi
}
    
# --- REPLACEMENT of the original usage_service function ---
# --- 替换原始的 usage_service 函数 ---
usage_service() {
    echo "corix service: 管理持久化 Corium Agents (后台服务) 的生命周期。"
    echo "corix service: Manage the lifecycle of persistent Corium Agents (background services)."
    echo
    echo "用法 / Usage: corix service <subcommand> [agent_id]"
    echo
    echo "此命令与后台的 Agent Supervisor 守护进程交互，以控制由 Mod 提供的长期运行服务。"
    echo "This command interacts with the background Agent Supervisor daemon to control long-running services provided by Mods."
    echo
    echo "子命令 / Subcommands:"
    echo "  list, ls, status    列出所有被管理的 Agent 及其当前状态。"
    echo "                      (List all managed Agents and their current status.)"
    echo "  start <agent_id>      手动启动一个已注册并启用的 Agent。"
    echo "                      (Manually start a registered and enabled Agent.)"
    echo "  stop <agent_id>       手动停止一个正在运行的 Agent。"
    echo "                      (Manually stop a running Agent.)"
    echo "  restart <agent_id>    重启一个正在运行的 Agent。"
    echo "                      (Restart a running Agent.)"
    echo "  logs <agent_id>       查看一个 Agent 的日志文件 (使用 'tail -f' 实时跟踪)。"
    echo "                      (View the log file for an Agent (uses 'tail -f' to follow).)"
}

# --- REPLACEMENT of the original corix_service function ---
# --- 替换原始的 corix_service 函数 ---
corix_service() {
    local sub_cmd="${1:-}"
    shift || true

    case "$sub_cmd" in
        list|ls|status)
            msg "Corium Agents 状态 / Corium Agents Status:"
            local status_json
            status_json=$(_service_ipc_call "get_service_status" "[]")
            
            if [ $? -eq 0 ] && [ -n "$status_json" ] && [ "$status_json" != "null" ]; then
                # 使用 jq 格式化输出一个漂亮的、带颜色的表格
                # Use jq to format a nice, colorful table
                echo "$status_json" | jq -r '
                    # ANSI Color Codes
                    def color(c): "\u001b[" + c + "m";
                    def reset: color("0");
                    def green: color("1;32");
                    def red: color("1;31");
                    def yellow: color("0;33");

                    (
                        ["AGENT ID", "STATUS", "PID", "RESTARTS", "UNBOXED", "LOG FILE"]
                    ),
                    (
                        to_entries[] | 
                        [
                            .key, 
                            (if .value.status == "running" then green + .value.status + reset else red + .value.status + reset end), 
                            (.value.pid // "N/A"), 
                            .value.restarts, 
                            (if .value.is_unboxed == true then yellow + "true" + reset else "false" end), 
                            .value.log_file
                        ]
                    )
                    | @tsv
                ' | column -t -s $'\t' | sed 's/^/  /'
            else
                info "没有正在运行或被管理的 Agent。 / No agents are running or managed."
            fi
            ;;

        start|stop|restart)
            [ $# -ne 1 ] && { error "用法: corix service $sub_cmd <mod_id> / Usage: corix service $sub_cmd <mod_id>"; return 1; }
            local mod_id="$1"
            info "正在向 Supervisor 发送 '${sub_cmd}' 请求... / Sending '${sub_cmd}' request to Supervisor..."
            local params_json
            params_json=$(jq -n --arg cmd "$sub_cmd" --arg id "$mod_id" '[$cmd, $id]')
            
            local result
            result=$(_service_ipc_call "control_service" "$params_json")
            if [ $? -eq 0 ]; then
                msg "✅ 操作成功 / Operation successful: $(echo "$result" | jq -r .)"
            fi
            ;;

        logs)
            [ $# -ne 1 ] && { error "用法: corix service logs <mod_id> / Usage: corix service logs <mod_id>"; return 1; }
            local mod_id="$1"
            local log_dir="${VAR_LIB_CORIUM_DIR}/logs/agents"
            local log_file="${log_dir}/${mod_id//\//_}.log"
            
            if [ -f "$log_file" ]; then
                info "正在实时显示日志 (按 Ctrl+C 退出)... / Tailing log (Press Ctrl+C to exit)..."
                tail -n 100 -f "$log_file"
            else
                error "未找到 Agent '${mod_id}' 的日志文件。/ Log file for Agent '${mod_id}' not found."
            fi
            ;;

        *)
            usage_service
            ;;
    esac
}


# =======================================================
# --- SECTION 34: USAGE AND HELP FUNCTION             ---
# --- 第34节: 用法与帮助函数                           ---
# =======================================================

# =======================================================================================
# --- [V101 HELP] Python 兼容性与环境一致性指南                                     ---
# --- [V101 HELP] Python Compatibility & Environment Consistency Guide              ---
# =======================================================================================
usage_python_compat_guide() {
cat <<'EOF'

================================================================================
  Corium Python 兼容性指南
  Corium Python Compatibility Guide
================================================================================

Corium 的部分核心功能由 Python 驱动。在拥有多个 Python 版本的系统上，
确保 Corium 及其所有组件都使用同一个、正确的 Python 解释器至关重要。
本指南将帮助您解决“依赖已安装但脚本找不到”的典型问题。

Parts of Corium's core functionality are driven by Python. On systems with multiple
Python versions, it is critical to ensure that Corium and all its components
use the same, correct Python interpreter. This guide helps you solve the classic
"dependency is installed but the script can't find it" problem.

--------------------------------------------------------------------------------
问题根源：环境不一致 (The Root Cause: Environment Inconsistency)
--------------------------------------------------------------------------------

当您直接在命令行运行 `pip install ...` 时，您使用的是当前 Shell 的环境。
然而，当 `corix` 脚本（尤其是在 `sudo` 下）被系统执行时，它可能会在一个
更受限的环境中运行，导致它找到一个不同的 Python 解释器。

When you run `pip install ...` directly, you're using your current shell's environment.
However, when the `corix` script is executed by the system (especially under `sudo`),
it might run in a more restricted environment, causing it to find a different
Python interpreter.

**解决方案的核心思想是：在系统层面，明确地将通用的 `python3` 命令指向
您希望使用的那个具体版本（例如 python3.11）。**

**The core solution is to explicitly point the generic `python3` command to the
specific version you intend to use at a system-wide level.**

---
### 方案 A: 使用 `update-alternatives` (Debian/Ubuntu 最佳实践)
### Method A: Using `update-alternatives` (Debian/Ubuntu Best Practice)

1.  **注册可用的 Python 版本 (Register available Python versions):**
    为每个 Python 版本赋予一个优先级（数字越大越高）。
    Assign a priority to each Python version (higher number is higher priority).

    ```bash
    # (将 python3.11 设为更高优先级 / Set python3.11 to a higher priority)
    sudo update-alternatives --install /usr/bin/python3 python3 /usr/bin/python3.11 110
    sudo update-alternatives --install /usr/bin/python3 python3 /usr/bin/python3.9 90
    ```

2.  **选择默认版本 (Select the default version):**
    运行以下命令，它会弹出一个菜单让您选择。
    Run the following command, which will bring up a menu for you to choose.

    ```bash
    sudo update-alternatives --config python3
    ```
    *   在菜单中，选择您希望设为默认的那个 Python 版本对应的数字即可。
        In the menu, simply select the number corresponding to the Python version you wish to set as default.

---
### 方案 B: 手动管理符号链接 (适用于所有 Linux 系统)
### Method B: Manually Managing Symlinks (For All Linux Systems)

如果您的系统没有 `update-alternatives`，或者该命令没有弹出交互式菜单，
您可以手动完成同样的工作。

If your system lacks `update-alternatives`, or if the command doesn't show an
interactive menu, you can perform the same task manually.

1.  **检查当前链接 (Check the current link):**
    `ls -l /usr/bin/python3`

2.  **如果链接不正确，则强制修改它 (If the link is incorrect, forcibly change it):**
    首先备份并移除旧链接，然后创建一个新的。
    First, back up and remove the old link, then create the new one.

    ```bash
    # (假设您希望默认使用 python3.11 / Assuming you want to default to python3.11)
    sudo mv /usr/bin/python3 /usr/bin/python3.bak
    sudo ln -s /usr/bin/python3.11 /usr/bin/python3
    ```

---
### 确认您的修改 (Verifying Your Changes)

无论使用哪种方法，完成后都请运行以下命令来确认：
Regardless of the method used, run the following command to confirm when you're done:

`python3 --version`

它的输出应该是您刚刚设定的那个版本。完成此操作后，Corium 的所有部分
都将能够找到并使用正确的 Python 环境和库。
Its output should be the version you just set. After this, all parts of Corium will
be able to find and use the correct Python environment and its libraries.

================================================================================
EOF
}

# =======================================================================================
# --- [AGENT DEV] Agent Mod 开发规范 (Agent Mod Development Guide)                 ---
# =======================================================================================
usage_agent_development() {
cat <<'EOF'

================================================================================
  Corium Agent 开发指南 (Corium Agent Development Guide)
================================================================================

Corium Agents 是由 Mod 驱动的、拥有独立身份的链上实体。它们可以在 Corium
网络上自主地或被动地执行任务。本指南将指导您如何开发一个 Agent Mod。

Corium Agents are on-chain entities with independent identities, driven by Mods.
They can perform tasks autonomously or passively on the Corium network. This
guide will walk you through developing an Agent Mod.

--------------------------------------------------------------------------------
第一部分：Agent 的两种执行模式 (The Two Execution Modes)
--------------------------------------------------------------------------------

Corium 为 Agent 提供了两种执行模式，以平衡安全性和能力。您必须在您的
.build 文件中明确选择一种。

Corium provides two execution modes for Agents to balance security and capability.
You MUST explicitly choose one in your .build file.

1.  **沙箱化 Agent (Sandboxed Agent) - [默认/推荐]**
    **Sandboxed Agent - [DEFAULT & RECOMMENDED]**
    - **原理:** Agent 运行在一个由 bubblewrap 构建的、严格隔离的沙箱中。
      **Principle:** The Agent runs in a tightly isolated sandbox built by bubblewrap.
    - **权限:** 文件系统访问受限，网络被禁用。它无法直接访问自己的私钥。
      **Permissions:** Filesystem access is restricted, and networking is disabled. It
      CANNOT directly access its own private key.
    - **如何行动:** 它必须通过安全的 IPC 网关调用 api.request_signature()
      来请求 Corium 核心**代为签名**，从而使用自己的身份。
      **How it Acts:** It MUST use the secure IPC gateway to call
      api.request_signature() to request the Corium core to sign on its
      behalf, thus using its identity.
    - **声明:** 在 .build 文件中不设置 unboxed_execution 或设为 false。
      **Declaration:** Do not set unboxed_execution or set it to false in the
      .build file.

2.  **非沙箱化 Agent (Unboxed Agent) - [危险/特权]**
    **Unboxed Agent - [DANGEROUS & PRIVILEGED]**
    - **原理:** Agent 直接在主机系统上运行，拥有与 corix.sh 相同的权限。
      **Principle:** The Agent runs directly on the host system with the same
      permissions as corix.sh.
    - **权限:** **无限制。** 它可以访问整个文件系统（包括自己的私钥和用户的
      私钥）、建立网络连接、执行任何命令。
      **Permissions:** **UNLIMITED.** It can access the entire filesystem (including
      its own and the user's private keys), establish network connections, and
      execute any command.
    - **安全机制:** 用户在首次启用 Unboxed Agent 时，必须通过一个高风险的
      手动确认流程，以示知情同意。
      **Safety Mechanism:** The user must go through a high-risk manual
      confirmation process when enabling an Unboxed Agent for the first time
      to show informed consent.
    - **声明:** 在 .build 文件中设置 unboxed_execution="true"。
      **Declaration:** Set unboxed_execution="true" in the .build file.
    - **用例:** 仅用于绝对受信任的、需要高级权限的系统级核心组件，例如
      未来的官方 IBC 中继者 (Relayer)。
      **Use Case:** ONLY for absolutely trusted, system-level core components that
      require advanced permissions, such as a future official IBC Relayer.

--------------------------------------------------------------------------------
第二部分：Agent 的 .build 文件规范 (.build File Specification)
--------------------------------------------------------------------------------

除了常规的 pkgname, pkgver 等字段，一个 Agent Mod 的 .build 文件
还需要定义以下元数据：

In addition to the regular pkgname, pkgver, etc., an Agent Mod's .build
file needs to define the following metadata:

  - corix_mod_type="agent" (或 onchain_agent_logic):
    (必须) 将其标记为一个 Agent 逻辑包。
    (Required) Marks the package as an Agent logic package.

  - executable="main.py":
    (必须) 指定作为 Agent 入口点的可执行文件名。
    (Required) Specifies the executable filename that serves as the Agent's entry point.

  - corix_event_hooks=("on_forum_post" "on_set_nickname"):
    (可选) 一个 Bash 数组，声明此 Agent 对哪些链上事件感兴趣。当这些事件
    发生时，Agent 将被自动激活。
    (Optional) A Bash array declaring which on-chain events this Agent is
    interested in. The Agent will be automatically activated when these events occur.

  - persistent_service="true":
    (可选) 将此 Agent 声明为一个需要长期运行的后台服务 (例如，一个 IBC 中继者)。
    corix service 命令将可以管理它的启停。
    (Optional) Declares this Agent as a long-running background service (e.g., an
    IBC Relayer). The corix service command will be able to manage it.

  - unboxed_execution="true":
    (可选, 危险) 请求以“非沙箱化”模式运行。
    (Optional, DANGEROUS) Requests to run in "unboxed" mode.

--------------------------------------------------------------------------------
第三部分：Agent 脚本的开发接口 (API for Agent Scripts)
--------------------------------------------------------------------------------

您的 Agent 脚本（例如 main.py）可以通过以下方式与 Corium 核心交互：

Your Agent script (e.g., main.py) can interact with the Corium core in the
following ways:

1.  **环境变量 (Environment Variables):**
    - CORIUM_AGENT_ID: (始终可用) 您 Agent 的链上唯一身份哈希。
                         (Always available) Your Agent's unique on-chain identity hash.
    - CORIUM_EVENT_NAME: (事件触发时) 触发了哪个事件 (e.g., on_forum_post)。
                           (On event trigger) Which event was triggered.
    - CORIUM_TRIGGER_TX_HASH: (事件触发时) 触发事件的交易哈希。
                                (On event trigger) The transaction hash that triggered the event.

2.  **标准输入 (Standard Input):**
    - 对于事件触发的 Agent，触发交易的**原始 JSON 载荷**将通过 stdin 传入。
      For event-triggered Agents, the **raw JSON payload** of the triggering
      transaction will be passed via stdin.

3.  **IPC API (仅限沙箱化 Agent / Sandboxed Agents Only):**
    - 沙箱化 Agent 会被注入一个名为 api 的全局对象（在 Python 中），它提供
      了与守护进程通信的安全方法，其中最重要的是：
      Sandboxed Agents are injected with a global api object (in Python) that
      provides safe methods to communicate with the daemon, the most important being:
      - api.request_signature(data_to_sign):
        请求 Corium 核心使用 Agent 自己的私钥对数据进行签名。这是沙箱化
        Agent 使用其链上身份的**唯一**方式。
        Requests the Corium core to sign data using the Agent's own private key.
        This is the **ONLY** way for a Sandboxed Agent to use its on-chain identity.

================================================================================
EOF
}

# =======================================================================================
# --- [DESIGN] Corium 设计哲学与实现说明 (Corium Design Philosophy & Notes)         ---
# =======================================================================================
usage_design_philosophy() {
cat <<'EOF'

================================================================================
  Corium 设计哲学与实现说明
  Corium Design Philosophy & Implementation Notes
================================================================================

Corium 的代码库，尤其是其核心的 Shell 脚本，包含了一些看似反常规、但实则
经过深思熟虑的设计决策。理解这些决策背后的哲学，有助于您更好地理解、使用
和贡献 Corium 项目。

The Corium codebase, especially its core Shell script, contains some design
decisions that may seem counter-intuitive but are in fact deliberate and
well-considered. Understanding the philosophy behind these decisions will help
you better understand, use, and contribute to the Corium project.

--------------------------------------------------------------------------------
主题一：状态转换与事件记录的分离 (Separation of State & Event)
Topic 1: Separation of State Transition and Event Recording
--------------------------------------------------------------------------------

**观察 (Observation):**
在核心的状态转换引擎 (_update_chain_state_cache) 中，处理治理提案和投票
交易 (propose_*, vote_*) 的 case 分支是空的。

In the core state transition engine (_update_chain_state_cache), the case
branches that handle governance proposal and voting transactions (propose_*,
vote_*) are empty.

**解释 (Explanation):**
**这是故意且正确的设计。 (This is an intentional and correct design.)**

这些交易的性质是**记录一个意图**，而非立即改变系统的最终状态。

The nature of these transactions is to **record an intent**, not to immediately
change the final state of the system.

*   **propose_* 交易:** 相当于“候选人登记”。它的作用就是将提案内容记录
    到区块链上。这个动作本身不产生任何状态变更。
    A propose_* transaction is like a "candidate registration." Its purpose is
    simply to record the proposal's content onto the blockchain. This action
    itself does not produce any state change.

*   **vote_* 交易:** 相当于“选民投票”。它的作用是将一张选票投进一个密封的
    票箱。这个动作同样不改变选举结果。
    A vote_* transaction is like a "voter casting a ballot." Its purpose is to
    place a vote into a sealed ballot box. This action also does not change the
    election's outcome.

真正的状态变更发生在**区块级的事件**中，当一个确定的时间点（例如，投票窗口
关闭的那个区块高度）到来时：
The real state change happens during **block-level events**, when a deterministic
point in time arrives (e.g., the block height at which the voting window closes):

1.  **计票 (_protocol_tally_votes_...)**: 此函数会被触发，它会**回溯**
    查找过去一段时间内所有相关的提案和投票记录，计算结果。如果通过，它会
    **调度**一个未来的状态变更。
    **Tallying (_protocol_tally_votes_...)**: This function is triggered. It
    **looks back** at all relevant proposal and vote records from a past period,
    calculates the result, and if it passes, **schedules** a future state change.

2.  **执行 (_protocol_execute_scheduled_changes)**: 在一个更未来的、
    确定的区块高度，此函数被触发，**最终执行**已调度的状态变更（例如，
    正式激活一个新的验证器）。
    **Enactment (_protocol_execute_scheduled_changes)**: At an even later,
    deterministic block height, this function is triggered to **finally execute**
    the scheduled state change (e.g., officially activating a new validator).

这种设计将“即时记录”和“延时结算”分离，确保了治理过程的**确定性、可预测性
和健壮性**，不受交易在区块内顺序的影响。
This design separates "immediate recording" from "deferred settlement," ensuring
the governance process is **deterministic, predictable, and robust**, unaffected
by the order of transactions within a block.

--------------------------------------------------------------------------------
主题二：向后兼容的重构 (Backward-Compatible Refactoring)
Topic 2: Backward-Compatible Refactoring
--------------------------------------------------------------------------------

**观察 (Observation):**
核心的 .build 文件解析器 (_parse_build_file) 被重写以支持 Bash 数组
语法 (e.g., depends=(...))。

The core .build file parser (_parse_build_file) was rewritten to support
Bash array syntax (e.g., depends=(...)).

**解释 (Explanation):**
**这次修改被设计为对所有旧的调用点完全向后兼容。**
**This modification was designed to be fully backward-compatible with all old call sites.**

旧的实现和新的实现，虽然内部逻辑不同，但它们的**输出约定**对于上层调用者
来说是等效的。

The old and new implementations, despite different internal logic, have an
**output convention** that is equivalent for njihove upper-level callers.

*   **旧的依赖解析**: depends=("a" "b") -> 输出一个多行块。
    **Old dependency parsing**: depends=("a" "b") -> a multi-line block was output.
*   **新的依赖解析**: depends=("a" "b") -> 输出一个单行的 depends=a b。
    **New dependency parsing**: depends=("a" "b") -> a single line depends=a b is output.

在 Shell 脚本中，当一个包含空格的、未加引号的变量被用于 for 循环时
(e.g., for dep in $depends_list)，它会被自动按空格分割。因此，无论是
读取旧的多行块还是新的单行空格分隔字符串，上层处理依赖的 for 循环
的**行为是完全一致的**。

In a Shell script, when an unquoted variable containing spaces is used in a for
loop (e.g., for dep in $depends_list), it is automatically split by whitespace.
Therefore, whether reading the old multi-line block or the new single-line,
space-separated string, the behavior of the upper-level for loop that
processes dependencies is **completely consistent**.

这次重构的目的是在**不破坏任何现有功能**的前提下，为 Mod 系统引入更强大、
更标准的元数据表达能力，例如 Agent 的事件钩子声明。
The purpose of this refactoring was to introduce more powerful and standard
metadata expression capabilities for the Mod system, such as Agent event hook
declarations, **without breaking any existing functionality**.

================================================================================
EOF
}

# ==============================================================================
# --- [新增] csi (Corium Search & Install) - 交互式搜索并安装软件包的函数 ---
# --- [NEW] csi (Corium Search & Install) - Function to interactively search and install packages ---
corix_search_interactive() {
    # 检查核心依赖 'fzf' 是否已安装
    # Check if the core dependency 'fzf' is installed
    if ! command -v fzf &> /dev/null; then
        error "命令 'csi' 需要 'fzf' (一个命令行模糊查找器) 才能工作。"
        error "The 'csi' command requires 'fzf' (a command-line fuzzy finder) to work."
        info "请先安装它，例如 (Please install it first, e.g.):"
        info "  sudo apt install fzf / sudo dnf install fzf / sudo pacman -S fzf"
        return 1
    fi

    # 运行 corix search，并将所有参数 ($@) 传递给它，然后将结果通过管道传给 fzf
    # Run corix search, passing all arguments ($@) to it, then pipe the results to fzf
    local selection
    # fzf 的预览功能会递归调用 corix info，这正是我们想要的
    # fzf's preview feature recursively calls corix info, which is exactly what we want
    selection=$(corix_search "$@" | fzf \
        --multi \
        --height '50%' \
        --header '按 TAB 键多选, 按 Enter 键确认, 按 Esc 键退出 / Press TAB to multi-select, Enter to confirm, Esc to quit' \
        --preview 'corix info {1}' \
        --preview-window 'right:50%:wrap')
    
    # 如果用户按了 Esc 键，fzf 的输出为空，则优雅地退出
    # If the user pressed Esc, fzf's output will be empty, so exit gracefully
    if [ -z "$selection" ]; then
        info "未选择任何软件包。操作已取消。 / No packages selected. Operation cancelled."
        return 0
    fi
    
    # 从 fzf 的输出中提取第一列（即完整的软件包名称）
    # Extract the first column (the full package name) from fzf's output
    local packages_to_install
    packages_to_install=$(echo "$selection" | awk '{print $1}')
    
    if [ -n "$packages_to_install" ]; then
        echo
        info "将要安装以下软件包: / The following packages will be installed:"
        # 使用颜色高亮将要安装的包列表
        # Highlight the list of packages to be installed using color
        echo "$packages_to_install" | sed 's/^/ \o033[1;32m/g'
        echo -e "\o033[0m" # 重置颜色 / Reset color
        # 直接调用 corix_install。corix_install 内部会处理权限检查和加锁。
        # Directly call corix_install. It will handle permission checks and locking internally.
        corix_install $packages_to_install
    fi
}


