_internal_verify_exodus_quorum() {
    [ $# -eq 2 ] && [[ "$1" =~ ^[a-f0-9]{64}$ ]] || return 1
    "${PYTHON_CMD}" - "$FORUM_DB" "$1" "$2" "$CORIUM_NETWORK_ID" <<'PY_EXODUS_QUORUM'
import sqlite3,json,sys,hashlib,time,pathlib
from cryptography.hazmat.primitives.serialization import load_pem_public_key
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives import hashes
path,proposal,snapshot,network=sys.argv[1:]
state=json.load(open(snapshot)); validators={v['public_key_hash']:v for v in state['state']['chain_tables']['validators']}
with sqlite3.connect(pathlib.Path(path).resolve().as_uri()+'?mode=ro',uri=True) as db:
    row=db.execute('SELECT author_id,target_block_height,target_block_hash,timestamp,full_proposal_object,expires_at FROM exodus_proposals WHERE proposal_hash=?',(proposal,)).fetchone()
    if row is None: raise ValueError('Missing proposal')
    author,height,block_hash,timestamp,raw,expires=row; data=json.loads(raw)
    if expires!=timestamp+604800 or not int(time.time())-604800<timestamp<=int(time.time())+300: raise ValueError('Invalid proposal expiry')
    if data['author_id']!=author or data['target_block_height']!=height or data['target_block_hash']!=block_hash or data['timestamp']!=timestamp: raise ValueError('Proposal record conflict')
    anchor=state['recovery_anchor']
    if anchor['height']!=height or anchor['block_hash']!=block_hash: raise ValueError('Recovery anchor conflict')
    canonical=f'CORIUM-EXODUS-SSPO-V1\n{network}\n{author}\n{height}\n{block_hash}\n{timestamp}'
    if hashlib.sha256(canonical.encode()).hexdigest()!=proposal or author not in validators: raise ValueError('Invalid proposal author or hash')
    def verify(identity,signature,payload):
        pem=validators[identity]['public_key'].rstrip('\n')
        if hashlib.sha256(pem.encode()).hexdigest()!=identity: raise ValueError('Invalid validator binding')
        key=load_pem_public_key(pem.encode())
        if not isinstance(key,ec.EllipticCurvePublicKey) or not isinstance(key.curve,ec.SECP256K1): raise ValueError('Invalid validator key')
        key.verify(bytes.fromhex(signature),payload.encode(),ec.ECDSA(hashes.SHA256()))
    verify(author,data['signature'],canonical)
    rows=db.execute('SELECT proposal_hash,notary_id,signature,full_notarization_object FROM exodus_notarizations WHERE proposal_hash=? ORDER BY notary_id',(proposal,)).fetchall()
seen=set(); weight=0
for ph,identity,signature,raw in rows:
    data=json.loads(raw)
    if ph!=proposal or data['proposal_hash']!=proposal or data['notary_id']!=identity or data['signature']!=signature or identity in seen or identity not in validators: raise ValueError('Invalid notarization binding')
    verify(identity,signature,f'CORIUM-EXODUS-SNSO-V1\n{network}\n{proposal}\n{identity}')
    seen.add(identity);weight+=validators[identity]['stake']
total=sum(v['stake'] for v in validators.values())
if total<=0: raise ValueError('No voting stake')
print(json.dumps({'count':len(seen),'weight':weight,'total':total,'quorum':3*weight>2*total},separators=(',',':')))
PY_EXODUS_QUORUM
}

corix_exodus() {
    acquire_lock "network"; trap 'release_lock "network"' RETURN
    local sub_cmd="${1:-}"; shift || true
    case "$sub_cmd" in
        propose-snapshot)
            [ $# -ne 1 ] && { usage_exodus; exit 1; }
            local height="$1"; local my_id=$(get_our_node_id); local timestamp=$(date +%s)
            
            # get target block hash
            local target_hash=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT hash FROM blocks WHERE height = %s;" "$height")
            [ -z "$target_hash" ] && { error "无法在本地找到高度为 $height 的区块。/ Block at height $height not found locally."; exit 1; }
            
            local network_id="${CORIUM_NETWORK_ID:-mainnet}"
            local canonical_str="CORIUM-EXODUS-SSPO-V1
${network_id}
${my_id}
${height}
${target_hash}
${timestamp}"
            
            # Use temporary file to sign the exact canonical string without trailing newlines issues
            local tmp_sig_file=$(mktemp)
            CORIUM_TEMP_ITEMS+=("$tmp_sig_file")
            printf "%s" "$canonical_str" > "$tmp_sig_file"
            local signature; signature=$(sign_data "$canonical_str" "$USER_IDENTITY_FILE") || return 1
            
            local sspo_object=$(jq -n --arg aid "$my_id" --argjson h "$height" --arg th "$target_hash" --argjson ts "$timestamp" --arg sig "$signature" \
                '{author_id: $aid, target_block_height: $h, target_block_hash: $th, timestamp: $ts, signature: $sig}')
            local sspo_hash; sspo_hash=$(printf '%s' "$canonical_str" | calculate_hash)
            db_execute_safe "$FORUM_DB" "INSERT OR IGNORE INTO exodus_proposals VALUES (%s,%s,%d,%s,%d,%s,%d);" "$sspo_hash" "$my_id" "$height" "$target_hash" "$timestamp" "$sspo_object" "$((timestamp+604800))" || return 1
            _apply_theme "info" "正在广播快照提案 (${sspo_hash:0:16}...)... / Broadcasting snapshot proposal (${sspo_hash:0:16}...)..."
            local peers; peers=$(dht_find_closest_nodes "$my_id" 10) || peers=""
            while IFS= read -r node_addr_string; do
                _parse_full_address "$node_addr_string" || continue; local node_id="$ADDR_NODE_ID"; [ -n "$node_id" ] || continue
                dht_send_message "$node_id" "ANNOUNCE_SSPO" "$sspo_object" >/dev/null 2>&1 &
            done <<< "$peers"; wait
            _apply_theme "success" "提案已广播。哈希 / Proposal broadcasted. Hash: ${sspo_hash}"
            ;;
        notarize)
            [ $# -ne 1 ] && { usage_exodus; exit 1; }; local proposal_hash="$1"
            [[ "$proposal_hash" =~ ^[a-f0-9]{64}$ ]] || return 1
            local my_id; my_id=$(get_our_node_id)
            local canonical_str="CORIUM-EXODUS-SNSO-V1
${CORIUM_NETWORK_ID:-mainnet}
${proposal_hash}
${my_id}"
            local signature; signature=$(sign_data "$canonical_str" "$USER_IDENTITY_FILE") || return 1
            local snso_object=$(jq -n --arg ph "$proposal_hash" --arg nid "$my_id" --arg sig "$signature" \
                '{proposal_hash: $ph, notary_id: $nid, signature: $sig}')
            [ "$(db_query_safe "$FORUM_DB" "SELECT COUNT(*) FROM exodus_proposals WHERE proposal_hash=%s AND expires_at>CAST(strftime('%' || 's','now') AS INTEGER);" "$proposal_hash")" -eq 1 ] || return 1
            db_execute_safe "$FORUM_DB" "INSERT OR IGNORE INTO exodus_notarizations VALUES (%s,%s,%s,%s);" "$proposal_hash" "$my_id" "$signature" "$snso_object" || return 1
            _apply_theme "info" "正在广播您对提案 ${proposal_hash:0:16}... 的公证签名... / Broadcasting your notarization for proposal ${proposal_hash:0:16}..."
            local peers; peers=$(dht_find_closest_nodes "$my_id" 10) || peers=""
            while IFS= read -r node_addr_string; do
                _parse_full_address "$node_addr_string" || continue; local node_id="$ADDR_NODE_ID"; [ -n "$node_id" ] || continue
                dht_send_message "$node_id" "ANNOUNCE_SNSO" "$snso_object" >/dev/null 2>&1 &
            done <<< "$peers"; wait
            _apply_theme "success" "公证签名已广播。 / Notarization signature broadcasted."
            ;;
        tally)
            # --- [V100 新增] 参数解析 ---
            local proposal_hash=""
            local dry_run=0
            while [ $# -gt 0 ]; do
                case "$1" in
                    --dry-run) dry_run=1; shift ;;
                    *)
                        if [ -z "$proposal_hash" ]; then
                            proposal_hash="$1"; shift
                        else
                            error "tally: Unknown argument '$1' / 未知参数 '$1'"; exit 1
                        fi
                        ;;
                esac
            done
            [ -z "$proposal_hash" ] && { usage_exodus; exit 1; }
            # --- [参数解析结束] ---
            
            local proposal_height=""
            local proposal_target_hash=""
            IFS="|" read -r proposal_height proposal_target_hash < <(db_query_safe "$FORUM_DB" "SELECT target_block_height, target_block_hash FROM exodus_proposals WHERE proposal_hash = %s AND expires_at > CAST(strftime('%' || 's','now') AS INTEGER);" "$proposal_hash")

            if [ -z "$proposal_height" ] || [ -z "$proposal_target_hash" ]; then
                error "无法从本地提案记录中获取目标区块高度。/ Could not retrieve target block height from local proposals."
                exit 1
            fi

            local local_block_hash=$(db_query_safe "$BLOCKCHAIN_DB" "SELECT hash FROM blocks WHERE height = %s;" "$proposal_height")
            if [ "$local_block_hash" != "$proposal_target_hash" ]; then
                error "本地链在该高度的区块哈希与提案不匹配。/ Local block hash at height $proposal_height does not match proposal target hash."
                exit 1
            fi
            
            _apply_theme "info" "正在从 P2P 网络同步并统计提案 ${proposal_hash:0:16}... 的公证签名... / Syncing and tallying notarizations for proposal ${proposal_hash:0:16}..."
            local my_id=$(get_our_node_id); local peers=$(dht_find_closest_nodes "$my_id" 5)
            local response row
            while IFS= read -r node_addr_string; do
                _parse_full_address "$node_addr_string" || continue; local node_id="$ADDR_NODE_ID"; [ -n "$node_id" ] || continue
                response=$(dht_send_message "$node_id" "GET_NOTARIZATIONS" "$proposal_hash") || return 1
                jq -e 'type=="array" and all(.[];type=="object")' <<< "$response" >/dev/null || return 1
                while IFS= read -r row; do
                    [ -n "$row" ] || continue
                    dht_send_message "$my_id" "ANNOUNCE_SNSO" "$(printf '%s' "$row" | base64 -d)" >/dev/null || return 1
                done < <(jq -r '.[]|@base64' <<< "$response")
            done <<< "$peers"
            
            local -a notary_ids=(); mapfile -t notary_ids < <(db_query_safe "$FORUM_DB" "SELECT DISTINCT notary_id FROM exodus_notarizations WHERE proposal_hash = %s;" "$proposal_hash")
            _apply_theme "primary" "已收集 ${#notary_ids[@]} 个签名。正在计算总权重... / Collected ${#notary_ids[@]} signatures. Calculating total weight..."
            
            local temp_genesis_file=$(mktemp)
            CORIUM_TEMP_ITEMS+=("$temp_genesis_file")
            
            _apply_theme "info" "正在重放到恢复参考点 (高度 ${proposal_height}) 以获取权重... / Replaying to recovery reference point (height ${proposal_height}) to get voting power..."
            _internal_export_chain_state "$proposal_height" "$temp_genesis_file" "" >/dev/null 2>&1 || { error "状态重放失败 / State replay failed"; exit 1; }
            
            local quorum_result total_network_stake total_notary_stake
            quorum_result=$(_internal_verify_exodus_quorum "$proposal_hash" "$temp_genesis_file") || return 1
            total_network_stake=$(jq -er '.total' <<< "$quorum_result") || return 1
            total_notary_stake=$(jq -er '.weight' <<< "$quorum_result") || return 1
            _apply_theme "info" "公证权重 / Notarization Weight: ${total_notary_stake} / ${total_network_stake}"
            if [ "$(jq -r '.quorum' <<< "$quorum_result")" = true ]; then
                _apply_theme "success" "✅ 共识已达成！ / Consensus has been reached!"
                
                # --- [V100 核心逻辑] ---
                if [ "$dry_run" -eq 1 ]; then
                    _apply_theme "primary" "--- EXODUS PROTOCOL DRY-RUN MODE ---"
                    _apply_theme "primary" "---      出埃及记协议演习模式      ---"

                    info "正在分析生成的创世文件并生成摘要... / Analyzing generated genesis file and creating summary..."
                    local file_hash file_size num_scores num_nns num_groups num_packages
                    file_hash=$(calculate_hash "$temp_genesis_file")
                    file_size=$(du -h "$temp_genesis_file" | awk '{print $1}')
                    num_scores=$(jq '.state.contribution_scores | length' "$temp_genesis_file")
                    num_nns=$(jq '.state.nns_records | length' "$temp_genesis_file")
                    num_groups=$(jq '.state.groups | length' "$temp_genesis_file")
                    num_packages=$(jq '.state.packages | length' "$temp_genesis_file")

                    echo "-------------------------------------"
                    _apply_theme "accent" "演习结果摘要 / Dry-Run Result Summary"
                    echo "-------------------------------------"
                    _apply_theme "info" "目标区块高度 / Target Block Height: ${proposal_height}"
                    _apply_theme "info" "创世文件哈希 / Genesis File Hash:   ${file_hash}"
                    _apply_theme "info" "创世文件大小 / Genesis File Size:   ${file_size}"
                    _apply_theme "primary" "将迁移的资产 / Assets to be Migrated:"
                    _apply_theme "info" "  - ${num_scores} 个贡献分记录 / Contribution score records"
                    _apply_theme "info" "  - ${num_nns} 个 NNS 域名 / NNS domain names"
                    _apply_theme "info" "  - ${num_groups} 个群组 / Groups"
                    _apply_theme "info" "  - ${num_packages} 个原生软件包记录 / Native package records"
                    echo "-------------------------------------"
                    _apply_theme "success" "演习成功。没有文件被写入磁盘。/ Dry-run successful. No files were written to disk."

                else
                    warn "要执行真正的状态导出，请运行: / To perform the actual state export, run:"
                    warn "  corix blockchain export-state <height> <genesis.json> --new-validators <pubkey1,...>"
                fi
                # --- [V100 逻辑结束] ---

            else 
                _apply_theme "warn" "⚠️ 共识尚未达成。/ Consensus has not yet been reached."; 
            fi
            ;;
        *) usage_exodus; return 1 ;;
    esac
}


