    echo "  --binaries        清理二进制包缓存。"
    echo "  --tmp             清理临时构建目录。"
    echo "  --all             清理以上所有 (默认动作，如果未指定目标)。"
    echo "  --force, -y       实际执行删除操作 (默认是 --dry-run)。"
    echo "  --dry-run         只显示将要被删除的内容，不实际操作 (默认)。"
    echo "  --older-than <days> 只清理比指定天数更旧的文件。"
}

usage_manage() {
